    def _create_schema_21_ltfs_qualification(self, db: sqlite3.Connection) -> None:
        existing = db.execute(
            "SELECT 1 FROM sqlite_master "
            "WHERE name='ltfs_qualification_reconciliations'"
        ).fetchone()
        if existing is not None:
            raise CatalogError("Schema 21 reconciliation table already exists")
        for statement in (
            _QUALIFICATION_RECONCILIATION_TABLE_DDL,
            _QUALIFICATION_RECONCILIATION_INDEX_DDL,
            _QUALIFICATION_RECONCILIATION_UPDATE_TRIGGER_DDL,
            _QUALIFICATION_RECONCILIATION_DELETE_TRIGGER_DDL,
        ):
            db.execute(statement)
        self._validate_schema_21_ltfs_qualification_layout(db)

    @staticmethod
    def _validate_schema_21_ltfs_qualification_layout(
        db: sqlite3.Connection,
    ) -> None:
        columns = tuple(
            (row["name"], row["type"], row["notnull"], row["pk"])
            for row in db.execute(
                "PRAGMA table_info(ltfs_qualification_reconciliations)"
            )
        )
        expected_columns = tuple(
            (
                name,
                "INTEGER"
                if name
                in {
                    "catalog_stage_ordinal",
                    "broker_stage_ordinal",
                    "terminal_exit_code",
                }
                else (
                    "BLOB"
                    if name
                    in {
                        "inspection_snapshot",
                        "inspection_proof",
                        "post_media_evidence",
                    }
                    else "TEXT"
                ),
                1,
                {"run_id": 1, "catalog_stage_ordinal": 2}.get(name, 0),
            )
            for name in _QUALIFICATION_RECONCILIATION_COLUMNS
        )
        object_rows = db.execute(
            "SELECT type,name,sql FROM sqlite_master "
            "WHERE tbl_name='ltfs_qualification_reconciliations'"
        ).fetchall()
        objects = {(row["type"], row["name"]): row["sql"] for row in object_rows}
        expected_objects = {
            ("table", "ltfs_qualification_reconciliations"),
            (
                "index",
                "ix_ltfs_qualification_reconciliations_broker_stage",
            ),
            (
                "index",
                "sqlite_autoindex_ltfs_qualification_reconciliations_1",
            ),
            (
                "trigger",
                "ltfs_qualification_reconciliations_immutable_update",
            ),
            (
                "trigger",
                "ltfs_qualification_reconciliations_immutable_delete",
            ),
        }
        indexes = {
            (row["name"], row["unique"], row["origin"], row["partial"])
            for row in db.execute(
                "PRAGMA index_list(ltfs_qualification_reconciliations)"
            )
        }
        broker_index = "ix_ltfs_qualification_reconciliations_broker_stage"
        index_columns = tuple(
            row["name"] for row in db.execute(f'PRAGMA index_info("{broker_index}")')
        )
        foreign_keys = tuple(
            tuple(row)
            for row in db.execute(
                "PRAGMA foreign_key_list(ltfs_qualification_reconciliations)"
            )
        )
        expected_foreign_keys = (
            (
                0,
                0,
                "ltfs_qualification_stages",
                "run_id",
                "run_id",
                "NO ACTION",
                "NO ACTION",
                "NONE",
            ),
            (
                0,
                1,
                "ltfs_qualification_stages",
                "catalog_stage_ordinal",
                "ordinal",
                "NO ACTION",
                "NO ACTION",
                "NONE",
            ),
        )
        if (
            columns != expected_columns
            or set(objects) != expected_objects
            or indexes
            != {
                (broker_index, 1, "c", 0),
                (
                    "sqlite_autoindex_ltfs_qualification_reconciliations_1",
                    1,
                    "pk",
                    0,
                ),
            }
            or index_columns != ("run_id", "broker_stage_ordinal")
            or foreign_keys != expected_foreign_keys
            or Catalog._normalize_schema_sql(
                objects.get(("table", "ltfs_qualification_reconciliations"))
            )
            != Catalog._normalize_schema_sql(_QUALIFICATION_RECONCILIATION_TABLE_DDL)
            or Catalog._normalize_schema_sql(objects.get(("index", broker_index)))
            != Catalog._normalize_schema_sql(_QUALIFICATION_RECONCILIATION_INDEX_DDL)
            or Catalog._normalize_schema_sql(
                objects.get(
                    (
                        "trigger",
                        "ltfs_qualification_reconciliations_immutable_update",
                    )
                )
            )
            != Catalog._normalize_schema_sql(
                _QUALIFICATION_RECONCILIATION_UPDATE_TRIGGER_DDL
            )
            or Catalog._normalize_schema_sql(
                objects.get(
                    (
                        "trigger",
                        "ltfs_qualification_reconciliations_immutable_delete",
                    )
                )
            )
            != Catalog._normalize_schema_sql(
                _QUALIFICATION_RECONCILIATION_DELETE_TRIGGER_DDL
            )
        ):
            raise CatalogError("Schema 21 LTFS qualification layout is invalid")

    @staticmethod
    def _normalize_schema_sql(value: object) -> str | None:
        if type(value) is not str:
            return None
        normalized = " ".join(value.strip().rstrip(";").upper().split())
        return re.sub(r"\s*([(),=<>])\s*", r"\1", normalized)

    def _create_schema_15_frozen_recovery(self, db: sqlite3.Connection) -> None:
        policy_columns = {
            row["name"]
            for row in db.execute("PRAGMA table_info(imported_job_policies)")
        }
        if "cassette_plan_sha256" not in policy_columns:
            db.execute(
                "ALTER TABLE imported_job_policies ADD COLUMN "
                "cassette_plan_sha256 TEXT CHECK("
                "cassette_plan_sha256 IS NULL OR length(cassette_plan_sha256)=64)"
            )
        if "completed_evidence_sha256" not in policy_columns:
            db.execute(
                "ALTER TABLE imported_job_policies ADD COLUMN "
                "completed_evidence_sha256 TEXT CHECK("
                "completed_evidence_sha256 IS NULL OR "
                "length(completed_evidence_sha256)=64)"
            )
        receipt_columns = {
            row["name"] for row in db.execute("PRAGMA table_info(migration_receipts)")
        }
        if "cassette_plan_sha256" not in receipt_columns:
            db.execute(
                "ALTER TABLE migration_receipts ADD COLUMN "
                "cassette_plan_sha256 TEXT CHECK("
                "cassette_plan_sha256 IS NULL OR length(cassette_plan_sha256)=64)"
            )
        if "completed_evidence_sha256" not in receipt_columns:
            db.execute(
                "ALTER TABLE migration_receipts ADD COLUMN "
                "completed_evidence_sha256 TEXT CHECK("
                "completed_evidence_sha256 IS NULL OR "
                "length(completed_evidence_sha256)=64)"
            )
        self._create_imported_cassette_commit_receipts(db)
        self._install_imported_job_freeze_triggers(db)

    def _create_imported_cassette_commit_receipts(self, db: sqlite3.Connection) -> None:
        db.execute(
            """
            CREATE TABLE IF NOT EXISTS imported_cassette_commit_receipts (
                job_id TEXT NOT NULL REFERENCES imported_job_policies(job_id),
                sequence INTEGER NOT NULL CHECK(sequence = 4),
                operation_id TEXT NOT NULL UNIQUE REFERENCES daemon_operations(id),
                owner_generation INTEGER NOT NULL CHECK(owner_generation > 0),
                migration_receipt_id TEXT NOT NULL REFERENCES migration_receipts(id),
                cutover_authorization_id TEXT NOT NULL
                    REFERENCES cutover_authorizations(id),
                cutover_authorization_sha256 TEXT NOT NULL
                    CHECK(length(cutover_authorization_sha256) = 64),
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256) = 64),
                manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256) = 64),
                tape_id TEXT NOT NULL REFERENCES tapes(id),
                block_ids_json TEXT NOT NULL,
                command_ids_json TEXT NOT NULL,
                command_evidence_sha256 TEXT NOT NULL
                    CHECK(length(command_evidence_sha256) = 64),
                commit_binding_sha256 TEXT NOT NULL
                    CHECK(length(commit_binding_sha256) = 64),
                observed_media_identity_sha256 TEXT NOT NULL
                    CHECK(length(observed_media_identity_sha256) = 64),
                mount_path_sha256 TEXT NOT NULL CHECK(length(mount_path_sha256) = 64),
                tape_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(tape_device_identity_sha256) = 64),
                scsi_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(scsi_device_identity_sha256) = 64),
                expected_media_scope_sha256 TEXT NOT NULL
                    CHECK(length(expected_media_scope_sha256) = 64),
                terminal_sha256 TEXT CHECK(
                    terminal_sha256 IS NULL OR length(terminal_sha256) = 64
                ),
                committed_at TEXT NOT NULL,
                PRIMARY KEY(job_id, sequence)
            )
            """
        )
        columns = {
            row["name"]
            for row in db.execute(
                "PRAGMA table_info(imported_cassette_commit_receipts)"
            )
        }
        additions = (
            ("owner_generation", "INTEGER CHECK(owner_generation > 0)"),
            ("manifest_sha256", "TEXT CHECK(length(manifest_sha256) = 64)"),
            ("tape_id", "TEXT REFERENCES tapes(id)"),
            ("block_ids_json", "TEXT"),
            ("command_ids_json", "TEXT"),
            (
                "command_evidence_sha256",
                "TEXT CHECK(length(command_evidence_sha256) = 64)",
            ),
            (
                "commit_binding_sha256",
                "TEXT CHECK(length(commit_binding_sha256) = 64)",
            ),
            (
                "cutover_authorization_sha256",
                "TEXT CHECK(length(cutover_authorization_sha256) = 64)",
            ),
            (
                "terminal_sha256",
                "TEXT CHECK(terminal_sha256 IS NULL OR length(terminal_sha256) = 64)",
            ),
        )
        for name, definition in additions:
            if name not in columns:
                db.execute(
                    f"ALTER TABLE imported_cassette_commit_receipts "
                    f"ADD COLUMN {name} {definition}"
                )
        db.execute(_RECOVERY_LINEAGE_TABLE_DDL)
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS imported_postcommit_command_receipts (
                command_id TEXT PRIMARY KEY REFERENCES hardware_command_executions(id),
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                job_id TEXT NOT NULL,
                sequence INTEGER NOT NULL CHECK(sequence = 4),
                issued_generation INTEGER NOT NULL,
                recovery_lineage_id TEXT
                    REFERENCES imported_recovery_lineage_receipts(id),
                command_order INTEGER NOT NULL CHECK(command_order > 0),
                command_evidence_sha256 TEXT NOT NULL
                    CHECK(length(command_evidence_sha256) = 64),
                recorded_at TEXT NOT NULL,
                UNIQUE(operation_id, command_order)
            );
            CREATE TABLE IF NOT EXISTS imported_recovery_resolution_receipts (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                recovery_lineage_id TEXT
                    REFERENCES imported_recovery_lineage_receipts(id),
                commit_binding_sha256 TEXT NOT NULL
                    CHECK(length(commit_binding_sha256) = 64),
                resolved_generation INTEGER NOT NULL,
                command_receipt_id TEXT NOT NULL
                    REFERENCES command_quiescence_receipts(id),
                physical_receipt_id TEXT NOT NULL
                    REFERENCES physical_reconciliation_receipts(id),
                resolved_at TEXT NOT NULL,
                resolution_evidence_sha256 TEXT NOT NULL
                    CHECK(length(resolution_evidence_sha256) = 64)
            );
            """,
        )
        lineage_columns = {
            row["name"]
            for row in db.execute(
                "PRAGMA table_info(imported_recovery_lineage_receipts)"
            )
        }
        if "command_observations_json" not in lineage_columns:
            db.execute(
                "ALTER TABLE imported_recovery_lineage_receipts "
                "ADD COLUMN command_observations_json TEXT"
            )
        legacy_lineages = db.execute(
            "SELECT * FROM imported_recovery_lineage_receipts "
            "ORDER BY recovery_generation, id"
        ).fetchall()
        verified_lineages = []
        for lineage in legacy_lineages:
            try:
                source_observations, _ = self._reconstruct_legacy_lineage_observations(
                    db, lineage
                )
                encoded = lineage["command_observations_json"]
                if encoded is not None:
                    stored = tuple(tuple(value) for value in json.loads(encoded))
                    if stored != source_observations:
                        raise ValueError(
                            "stored observations differ from schema-14 command rows"
                        )
                verified_lineages.append((lineage, source_observations))
            except (KeyError, TypeError, ValueError, ValidationError) as exc:
                raise CatalogError(
                    "legacy recovery lineage cannot be reconstructed exactly"
                ) from exc
        try:
            verified_receipt_ids = self._verify_schema14_postcommit_receipts(db)
            self._upgrade_schema14_imported_authority_evidence(db)
            self._upgrade_schema14_postcommit_receipts(db, verified_receipt_ids)
        except (
            KeyError,
            LookupError,
            sqlite3.DatabaseError,
            TypeError,
            ValueError,
        ) as exc:
            raise CatalogError(
                "legacy recovery lineage cannot be reconstructed exactly"
            ) from exc
        for lineage, _ in verified_lineages:
            try:
                command_ids = tuple(json.loads(lineage["command_ids_json"]))
                commands = tuple(
                    self._command_with_release_tx(db, command_id)
                    for command_id in command_ids
                )
                if any(command is None for command in commands):
                    raise ValueError("lineage command disappeared during upgrade")
                observations = tuple(
                    _postcommit_command_evidence_tuple(command) for command in commands
                )
                if any(
                    not hardware_command_release_evidence_valid(observation)
                    for observation in observations
                ):
                    raise ValueError("upgraded release evidence is invalid")
                command_evidence = imported_postcommit_command_sha256(observations)
                commit = db.execute(
                    "SELECT commit_binding_sha256 FROM "
                    "imported_cassette_commit_receipts WHERE operation_id=?",
                    (lineage["operation_id"],),
                ).fetchone()
                if commit is None:
                    raise ValueError("upgraded commit binding is missing")
                lineage_sha256 = imported_recovery_lineage_sha256(
                    (
                        lineage["id"],
                        lineage["job_id"],
                        lineage["sequence"],
                        lineage["operation_id"],
                        lineage["original_owner_generation"],
                        lineage["recovery_generation"],
                        lineage["daemon_owner_id"],
                        lineage["prior_lineage_id"],
                        commit["commit_binding_sha256"],
                        lineage["restart_state"],
                        tuple(json.loads(lineage["command_ids_json"])),
                        command_evidence,
                        lineage["recorded_at"],
                    )
                )
                db.execute(
                    "UPDATE imported_recovery_lineage_receipts SET "
                    "commit_binding_sha256=?, command_observations_json=?, "
                    "command_evidence_sha256=?, lineage_sha256=? WHERE id=?",
                    (
                        commit["commit_binding_sha256"],
                        json.dumps(observations, separators=(",", ":")),
                        command_evidence,
                        lineage_sha256,
                        lineage["id"],
                    ),
                )
            except (KeyError, TypeError, ValueError, ValidationError) as exc:
                raise CatalogError(
                    "legacy recovery lineage cannot be reconstructed exactly"
                ) from exc
        remaining = db.execute(
            "SELECT COUNT(*) FROM imported_recovery_lineage_receipts "
            "WHERE command_observations_json IS NULL"
        ).fetchone()[0]
        if remaining:
            raise CatalogError(
                "legacy recovery lineage cannot be reconstructed exactly"
            )
        self._canonicalize_recovery_lineage_table(db)

    def _verify_schema14_postcommit_receipts(
        self, db: sqlite3.Connection
    ) -> tuple[str, ...]:
        receipts = db.execute(
            "SELECT * FROM imported_postcommit_command_receipts "
            "ORDER BY operation_id, command_order, command_id"
        ).fetchall()
        if len({row["command_id"] for row in receipts}) != len(receipts) or len(
            {(row["operation_id"], row["command_order"]) for row in receipts}
        ) != len(receipts):
            raise ValueError("schema-14 postcommit receipt cardinality is invalid")
        for operation_id in {row["operation_id"] for row in receipts}:
            operation_receipts = tuple(
                row for row in receipts if row["operation_id"] == operation_id
            )
            commit = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if commit is None:
                raise ValueError("schema-14 postcommit receipt has no commit")
            try:
                frozen_ids = set(json.loads(commit["command_ids_json"]))
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    "schema-14 frozen command identity is invalid"
                ) from exc
            operation_commands = self._commands_with_release_for_operation_tx(
                db, operation_id
            )
            postcommit_commands = tuple(
                row for row in operation_commands if row["id"] not in frozen_ids
            )
            if (
                len({row["id"] for row in operation_commands})
                != len(operation_commands)
                or tuple(row["command_id"] for row in operation_receipts)
                != tuple(row["id"] for row in postcommit_commands)
                or tuple(row["command_order"] for row in operation_receipts)
                != tuple(range(1, len(operation_receipts) + 1))
            ):
                raise ValueError("schema-14 postcommit receipt ordering is invalid")
        verified = []
        for receipt in receipts:
            command = self._command_with_release_tx(db, receipt["command_id"])
            commit = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
                (receipt["operation_id"],),
            ).fetchone()
            if command is None or commit is None:
                raise ValueError("schema-14 postcommit receipt is orphaned")
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?",
                (receipt["operation_id"],),
            ).fetchone()
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (receipt["operation_id"],),
            ).fetchone()
            media = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (receipt["operation_id"],),
            ).fetchone()
            authorization = db.execute(
                "SELECT * FROM cutover_authorizations WHERE id=?",
                (commit["cutover_authorization_id"],),
            ).fetchone()
            cassette = db.execute(
                "SELECT physical_label,tape_serial FROM automatic_cassettes "
                "WHERE job_id=? AND sequence=?",
                (commit["job_id"], commit["sequence"]),
            ).fetchone()
            if (
                operation is None
                or target is None
                or media is None
                or authorization is None
                or cassette is None
            ):
                raise ValueError("schema-14 postcommit authority is incomplete")
            try:
                frozen_ids = set(json.loads(commit["command_ids_json"]))
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    "schema-14 frozen command identity is invalid"
                ) from exc
            legacy_observation = _schema14_postcommit_command_evidence_tuple(command)
            observation = _postcommit_command_evidence_tuple(command)
            legacy_scope = _schema14_expected_media_scope_sha256(
                (
                    operation["kind"],
                    commit["job_id"],
                    str(commit["sequence"]),
                    cassette["physical_label"],
                )
            )
            canonical_scope = expected_media_scope_sha256(
                (
                    operation["kind"],
                    commit["job_id"],
                    str(commit["sequence"]),
                    cassette["physical_label"],
                    "",
                    "",
                )
            )
            receipt_recorded = self._parse_utc_timestamp(receipt["recorded_at"])
            command_quiesced = self._parse_utc_timestamp(command["quiesced_at"])
            if (
                command["id"] in frozen_ids
                or command["operation_id"] != receipt["operation_id"]
                or command["issued_generation"] != receipt["issued_generation"]
                or command["command_kind"] not in _IMPORTED_POSTCOMMIT_COMMAND_KINDS
                or commit["job_id"] != receipt["job_id"]
                or commit["sequence"] != receipt["sequence"]
                or operation["job_id"] != receipt["job_id"]
                or operation["cassette_sequence"] != receipt["sequence"]
                or authorization["job_id"] != receipt["job_id"]
                or authorization["cassette_sequence"] != receipt["sequence"]
                or authorization["consumed_by_operation_id"] != receipt["operation_id"]
                or authorization["expected_label"] != cassette["physical_label"]
                or authorization["drive_serial_sha256"]
                != target["tape_device_identity_sha256"]
                or target["expected_media_scope_sha256"]
                not in {legacy_scope, canonical_scope}
                or any(
                    commit[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
                or any(
                    command[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
                or command["observed_media_identity_sha256"]
                != media["observed_media_identity_sha256"]
                or command["state"] != "quiesced"
                or receipt_recorded is None
                or command_quiesced is None
                or receipt_recorded <= command_quiesced
                or not _schema14_command_observation_valid(legacy_observation)
                or not hardware_command_release_evidence_valid(observation)
                or not imported_postcommit_terminal_timeline_valid(
                    outcome=command["exit_outcome"],
                    created_at=command["created_at"],
                    released_at=command["released_at"],
                    exit_observed_at=command["exit_observed_at"],
                    quiesced_at=command["quiesced_at"],
                    process_identity=tuple(
                        command[field]
                        for field in (
                            "boot_id",
                            "pid",
                            "process_start_ticks",
                            "process_group_id",
                        )
                    ),
                    committed_at=commit["committed_at"],
                )
                or receipt["command_evidence_sha256"]
                not in {
                    imported_postcommit_command_sha256(legacy_observation),
                    imported_postcommit_command_sha256(observation),
                }
            ):
                raise ValueError("schema-14 postcommit receipt is invalid")
            verified.append(receipt["command_id"])
        return tuple(verified)

    def _upgrade_schema14_postcommit_receipts(
        self,
        db: sqlite3.Connection,
        command_ids: tuple[str, ...],
    ) -> None:
        for command_id in command_ids:
            command = self._command_with_release_tx(db, command_id)
            if command is None:
                raise ValueError("schema-14 postcommit command disappeared")
            observation = _postcommit_command_evidence_tuple(command)
            if not hardware_command_release_evidence_valid(observation):
                raise ValueError("upgraded postcommit release evidence is invalid")
            db.execute(
                "UPDATE imported_postcommit_command_receipts "
                "SET command_evidence_sha256=? WHERE command_id=?",
                (imported_postcommit_command_sha256(observation), command_id),
            )

    def _upgrade_schema14_imported_authority_evidence(
        self, db: sqlite3.Connection
    ) -> None:
        commits = db.execute(
            "SELECT * FROM imported_cassette_commit_receipts ORDER BY job_id, sequence"
        ).fetchall()
        for commit in commits:
            try:
                command_ids = tuple(json.loads(commit["command_ids_json"]))
                block_ids = tuple(json.loads(commit["block_ids_json"]))
            except (TypeError, ValueError) as exc:
                raise ValueError("schema-14 commit identity is malformed") from exc
            commands = self._commands_with_release_by_ids_tx(db, command_ids)
            if (
                not command_ids
                or len(set(command_ids)) != len(command_ids)
                or tuple(row["id"] for row in commands) != command_ids
                or len({row["id"] for row in commands}) != len(commands)
                or any(
                    row["operation_id"] != commit["operation_id"]
                    or not hardware_command_release_evidence_valid(
                        _postcommit_command_evidence_tuple(row)
                    )
                    for row in commands
                )
            ):
                raise ValueError("schema-14 commit command ledger is invalid")
            legacy_evidence = _schema14_commit_command_sha256(commands)
            current_evidence = imported_postcommit_command_sha256(
                tuple(_postcommit_command_evidence_tuple(row) for row in commands)
            )
            if commit["command_evidence_sha256"] not in {
                legacy_evidence,
                current_evidence,
            }:
                raise ValueError("schema-14 commit command digest is invalid")
            stored_binding = imported_cassette_commit_binding_sha256(
                (
                    commit["operation_id"],
                    commit["owner_generation"],
                    commit["job_id"],
                    commit["sequence"],
                    commit["tape_id"],
                    block_ids,
                    commit["manifest_sha256"],
                    commit["evidence_sha256"],
                    commit["observed_media_identity_sha256"],
                    *(
                        ()
                        if "terminal_sha256" not in frozenset(commit.keys())
                        or commit["terminal_sha256"] is None
                        else (commit["terminal_sha256"],)
                    ),
                    tuple(
                        commit[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    ),
                    command_ids,
                    commit["command_evidence_sha256"],
                    commit["cutover_authorization_sha256"],
                    commit["committed_at"],
                )
            )
            if stored_binding != commit["commit_binding_sha256"]:
                raise ValueError("schema-14 commit binding is invalid")
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?",
                (commit["operation_id"],),
            ).fetchone()
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (commit["operation_id"],),
            ).fetchone()
            authorization = db.execute(
                "SELECT * FROM cutover_authorizations WHERE id=?",
                (commit["cutover_authorization_id"],),
            ).fetchone()
            cassette = db.execute(
                "SELECT physical_label,tape_serial FROM automatic_cassettes "
                "WHERE job_id=? AND sequence=?",
                (commit["job_id"], commit["sequence"]),
            ).fetchone()
            if (
                operation is None
                or target is None
                or authorization is None
                or cassette is None
                or commit["sequence"] != 4
                or any(
                    row[field] != target[field]
                    for row in commands
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
                or any(
                    commit[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
                or self._cutover_authorization_evidence(
                    authorization, operation, target
                )
                != commit["cutover_authorization_sha256"]
            ):
                raise ValueError("schema-14 commit target is invalid")
            legacy_scope = _schema14_expected_media_scope_sha256(
                (
                    operation["kind"],
                    commit["job_id"],
                    str(commit["sequence"]),
                    cassette["physical_label"],
                )
            )
            canonical_scope = expected_media_scope_sha256(
                (
                    operation["kind"],
                    commit["job_id"],
                    str(commit["sequence"]),
                    cassette["physical_label"],
                    "",
                    "",
                )
            )
            if target["expected_media_scope_sha256"] not in {
                legacy_scope,
                canonical_scope,
            }:
                raise ValueError("schema-14 media scope is invalid")
            db.execute(
                "UPDATE operation_hardware_targets "
                "SET expected_media_scope_sha256=? WHERE operation_id=?",
                (canonical_scope, commit["operation_id"]),
            )
            db.execute(
                "UPDATE hardware_command_executions "
                "SET expected_media_scope_sha256=? WHERE operation_id=?",
                (canonical_scope, commit["operation_id"]),
            )
            db.execute(
                "UPDATE physical_reconciliation_receipts "
                "SET expected_media_scope_sha256=? WHERE operation_id=?",
                (canonical_scope, commit["operation_id"]),
            )
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (commit["operation_id"],),
            ).fetchone()
            commands = self._commands_with_release_by_ids_tx(db, command_ids)
            command_evidence = imported_postcommit_command_sha256(
                tuple(_postcommit_command_evidence_tuple(row) for row in commands)
            )
            authorization_evidence = self._cutover_authorization_evidence(
                authorization, operation, target
            )
            binding = imported_cassette_commit_binding_sha256(
                (
                    commit["operation_id"],
                    commit["owner_generation"],
                    commit["job_id"],
                    commit["sequence"],
                    commit["tape_id"],
                    block_ids,
                    commit["manifest_sha256"],
                    commit["evidence_sha256"],
                    commit["observed_media_identity_sha256"],
                    *(
                        ()
                        if "terminal_sha256" not in frozenset(commit.keys())
                        or commit["terminal_sha256"] is None
                        else (commit["terminal_sha256"],)
                    ),
                    tuple(
                        target[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    ),
                    command_ids,
                    command_evidence,
                    authorization_evidence,
                    commit["committed_at"],
                )
            )
            db.execute(
                "UPDATE imported_cassette_commit_receipts SET "
                "expected_media_scope_sha256=?, command_evidence_sha256=?, "
                "cutover_authorization_sha256=?, commit_binding_sha256=? "
                "WHERE job_id=? AND sequence=?",
                (
                    canonical_scope,
                    command_evidence,
                    authorization_evidence,
                    binding,
                    commit["job_id"],
                    commit["sequence"],
                ),
            )
            self._upgrade_schema14_recovery_resolution_evidence(
                db, commit["operation_id"], binding
            )

    @staticmethod
    def _upgrade_schema14_recovery_resolution_evidence(
        db: sqlite3.Connection,
        operation_id: str,
        commit_binding_sha256: str,
    ) -> None:
        receipts = db.execute(
            "SELECT * FROM imported_recovery_resolution_receipts WHERE operation_id=?",
            (operation_id,),
        ).fetchall()
        if not receipts:
            return
        if len(receipts) != 1:
            raise ValueError("schema-14 recovery resolution is duplicated")
        receipt = receipts[0]
        resolution = db.execute(
            "SELECT * FROM recovery_resolutions WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        command_receipt = db.execute(
            "SELECT * FROM command_quiescence_receipts WHERE id=?",
            (receipt["command_receipt_id"],),
        ).fetchone()
        items = db.execute(
            "SELECT command_id, exit_outcome FROM "
            "command_quiescence_receipt_items WHERE receipt_id=? ORDER BY command_id",
            (receipt["command_receipt_id"],),
        ).fetchall()
        physical = db.execute(
            "SELECT * FROM physical_reconciliation_receipts WHERE id=?",
            (receipt["physical_receipt_id"],),
        ).fetchone()
        if resolution is None or command_receipt is None or physical is None:
            raise ValueError("schema-14 recovery resolution is incomplete")
        evidence = imported_recovery_resolution_sha256(
            (
                operation_id,
                receipt["recovery_lineage_id"],
                commit_binding_sha256,
                receipt["resolved_generation"],
                resolution["reason_code"],
                tuple(command_receipt),
                tuple((row["command_id"], row["exit_outcome"]) for row in items),
                tuple(physical),
                resolution["resolved_at"],
            )
        )
        db.execute(
            "UPDATE imported_recovery_resolution_receipts SET "
            "commit_binding_sha256=?, resolution_evidence_sha256=? "
            "WHERE operation_id=?",
            (commit_binding_sha256, evidence, operation_id),
        )

    def _reconstruct_legacy_lineage_observations(
        self, db: sqlite3.Connection, lineage: sqlite3.Row
    ) -> tuple[
        tuple[tuple[object, ...], ...],
        tuple[tuple[object, ...], ...],
    ]:
        command_ids_raw = json.loads(lineage["command_ids_json"])
        if (
            not isinstance(command_ids_raw, list)
            or not all(isinstance(value, str) for value in command_ids_raw)
            or len(set(command_ids_raw)) != len(command_ids_raw)
        ):
            raise ValueError("invalid command identity list")
        command_ids = tuple(command_ids_raw)
        for value, name in (
            (lineage["id"], "lineage id"),
            (lineage["job_id"], "lineage job id"),
            (lineage["operation_id"], "lineage operation id"),
            (lineage["daemon_owner_id"], "lineage daemon owner id"),
        ):
            self._validate_safe_identifier(value, name)
        if lineage["prior_lineage_id"] is not None:
            self._validate_safe_identifier(
                lineage["prior_lineage_id"], "prior lineage id"
            )
        for value, name in (
            (lineage["commit_binding_sha256"], "lineage commit binding"),
            (lineage["command_evidence_sha256"], "lineage command evidence"),
            (lineage["lineage_sha256"], "lineage digest"),
        ):
            self._validate_sha256(value, name)
        original_generation = lineage["original_owner_generation"]
        recovery_generation = lineage["recovery_generation"]
        if (
            lineage["sequence"] != 4
            or type(original_generation) is not int
            or type(recovery_generation) is not int
            or original_generation <= 0
            or recovery_generation <= original_generation
            or lineage["restart_state"] not in {"running", "recovery_required"}
            or self._parse_utc_timestamp(lineage["recorded_at"]) is None
        ):
            raise ValueError("invalid lineage identity")
        commit = db.execute(
            "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
            (lineage["operation_id"],),
        ).fetchone()
        if (
            commit is None
            or commit["job_id"] != lineage["job_id"]
            or commit["sequence"] != lineage["sequence"]
            or commit["owner_generation"] != original_generation
            or commit["commit_binding_sha256"] != lineage["commit_binding_sha256"]
        ):
            raise ValueError("lineage commit binding is not exact")
        lineage_digest = imported_recovery_lineage_sha256(
            (
                lineage["id"],
                lineage["job_id"],
                lineage["sequence"],
                lineage["operation_id"],
                original_generation,
                recovery_generation,
                lineage["daemon_owner_id"],
                lineage["prior_lineage_id"],
                lineage["commit_binding_sha256"],
                lineage["restart_state"],
                command_ids,
                lineage["command_evidence_sha256"],
                lineage["recorded_at"],
            )
        )
        if lineage_digest != lineage["lineage_sha256"]:
            raise ValueError("lineage digest is not exact")
        legacy_observations = []
        observations = []
        for command_id in command_ids:
            self._validate_safe_identifier(command_id, "lineage command id")
            command = self._command_with_release_tx(db, command_id)
            if command is None or command["operation_id"] != lineage["operation_id"]:
                raise ValueError("lineage command is missing or rebound")
            legacy_observation = _schema14_postcommit_command_evidence_tuple(command)
            observation = _postcommit_command_evidence_tuple(command)
            issued_generation = legacy_observation[2]
            if (
                type(issued_generation) is not int
                or not original_generation <= issued_generation <= recovery_generation
                or legacy_observation[3] not in _HARDWARE_COMMAND_KINDS
            ):
                raise ValueError("lineage command identity is invalid")
            self._validate_safe_identifier(
                legacy_observation[1], "command operation id"
            )
            for value, name in zip(
                legacy_observation[4:10],
                (
                    "command argument digest",
                    "command mount digest",
                    "command tape device digest",
                    "command SCSI device digest",
                    "command media scope digest",
                    "command observed media digest",
                ),
                strict=True,
            ):
                self._validate_sha256(value, name)
            process_identity = legacy_observation[12:16]
            if any(value is not None for value in process_identity) and (
                not isinstance(process_identity[0], str)
                or not process_identity[0]
                or any(
                    type(value) is not int or value <= 0
                    for value in process_identity[1:]
                )
            ):
                raise ValueError("lineage process identity is invalid")
            if not _schema14_command_observation_valid(legacy_observation):
                raise ValueError("lineage command lifecycle is invalid")
            if legacy_observation[
                10
            ] == "quiesced" and not imported_postcommit_terminal_timeline_valid(
                outcome=legacy_observation[11],
                created_at=legacy_observation[16],
                released_at=legacy_observation[17],
                exit_observed_at=legacy_observation[18],
                quiesced_at=legacy_observation[19],
                process_identity=process_identity,
                committed_at=commit["committed_at"],
            ):
                raise ValueError("lineage terminal lifecycle is invalid")
            if not hardware_command_release_evidence_valid(observation):
                raise ValueError("lineage command release evidence is invalid")
            legacy_observations.append(legacy_observation)
            observations.append(observation)
        legacy_result = tuple(legacy_observations)
        result = tuple(observations)
        legacy_matches = (
            imported_postcommit_command_sha256(legacy_result)
            == lineage["command_evidence_sha256"]
        )
        current_matches = (
            imported_postcommit_command_sha256(result)
            == lineage["command_evidence_sha256"]
        )
        if not legacy_matches and not current_matches:
            raise ValueError("lineage command digest is not exact")
        return (legacy_result if legacy_matches else result), result

    def _canonicalize_recovery_lineage_table(self, db: sqlite3.Connection) -> None:
        columns = tuple(
            db.execute("PRAGMA table_info(imported_recovery_lineage_receipts)")
        )
        observation = next(
            row for row in columns if row["name"] == "command_observations_json"
        )
        canonical_names = (
            "id",
            "job_id",
            "sequence",
            "operation_id",
            "original_owner_generation",
            "recovery_generation",
            "daemon_owner_id",
            "prior_lineage_id",
            "commit_binding_sha256",
            "restart_state",
            "command_ids_json",
            "command_observations_json",
            "command_evidence_sha256",
            "recorded_at",
            "lineage_sha256",
        )
        if (
            observation["notnull"] == 1
            and tuple(row["name"] for row in columns) == canonical_names
        ):
            return
        schema_objects = tuple(
            row["sql"]
            for row in db.execute(
                "SELECT sql FROM sqlite_master WHERE tbl_name=? "
                "AND type IN ('index','trigger') AND sql IS NOT NULL",
                ("imported_recovery_lineage_receipts",),
            )
        )
        db.execute("PRAGMA defer_foreign_keys=ON")
        names = ", ".join(canonical_names)
        db.execute(
            f"CREATE TEMP TABLE imported_recovery_lineage_receipts_stage AS "
            f"SELECT {names} FROM imported_recovery_lineage_receipts"
        )
        db.execute("DROP TABLE imported_recovery_lineage_receipts")
        db.execute(_RECOVERY_LINEAGE_TABLE_DDL)
        db.execute(
            f"INSERT INTO imported_recovery_lineage_receipts ({names}) "
            f"SELECT {names} FROM imported_recovery_lineage_receipts_stage"
        )
        db.execute("DROP TABLE imported_recovery_lineage_receipts_stage")
        for statement in schema_objects:
            db.execute(statement)

    def _install_imported_job_freeze_triggers(self, db: sqlite3.Connection) -> None:
        """Make imported allocation identity immutable at the catalog boundary."""

        self._execute_sql_batch(
            db,
            """
            CREATE TRIGGER IF NOT EXISTS freeze_imported_job_identity_update
            BEFORE UPDATE OF id, media_key, library_id, total_cassettes, force_format
            ON automatic_jobs
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.id
            ) AND (
                NEW.id IS NOT OLD.id
                OR NEW.media_key IS NOT OLD.media_key
                OR NEW.library_id IS NOT OLD.library_id
                OR NEW.total_cassettes IS NOT OLD.total_cassettes
                OR NEW.force_format IS NOT OLD.force_format
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_job_delete
            BEFORE DELETE ON automatic_jobs
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_insert
            BEFORE INSERT ON automatic_cassettes
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=NEW.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_identity_update
            BEFORE UPDATE OF job_id, sequence, physical_label, tape_serial,
                planned_files, planned_bytes, operation, reuse_registered
            ON automatic_cassettes
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id
            ) AND (
                NEW.job_id IS NOT OLD.job_id
                OR NEW.sequence IS NOT OLD.sequence
                OR NEW.physical_label IS NOT OLD.physical_label
                OR NEW.tape_serial IS NOT OLD.tape_serial
                OR NEW.planned_files IS NOT OLD.planned_files
                OR NEW.planned_bytes IS NOT OLD.planned_bytes
                OR NEW.operation IS NOT OLD.operation
                OR NEW.reuse_registered IS NOT OLD.reuse_registered
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_delete
            BEFORE DELETE ON automatic_cassettes
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_job_library_insert
            BEFORE INSERT ON automatic_job_libraries
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=NEW.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_job_library_update
            BEFORE UPDATE ON automatic_job_libraries
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id OR policy.job_id=NEW.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_job_library_delete
            BEFORE DELETE ON automatic_job_libraries
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_item_insert
            BEFORE INSERT ON automatic_cassette_items
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=NEW.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_item_update
            BEFORE UPDATE ON automatic_cassette_items
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id OR policy.job_id=NEW.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS freeze_imported_cassette_item_delete
            BEFORE DELETE ON automatic_cassette_items
            WHEN EXISTS (
                SELECT 1 FROM imported_job_policies policy
                WHERE policy.job_id=OLD.job_id
            )
            BEGIN
                SELECT RAISE(ABORT, 'imported frozen job plan is immutable');
            END;
            """,
        )

    def _migrate_v1_to_v2(self, db: sqlite3.Connection) -> None:
        columns = {row["name"] for row in db.execute("PRAGMA table_info(tapes)")}
        if "cassette_number" not in columns:
            db.execute("ALTER TABLE tapes ADD COLUMN cassette_number TEXT")
        db.execute(
            "UPDATE tapes SET cassette_number=id "
            "WHERE cassette_number IS NULL OR trim(cassette_number)=''"
        )
        db.execute(
            "UPDATE metadata SET value=? WHERE key='schema_version'",
            ("2",),
        )
        self._event(
            db,
            "catalog.migrate",
            {"from_version": 1, "to_version": 2, "cassette_number_default": "tape_id"},
        )

