    def _migrate_v13_to_v14(self, db: sqlite3.Connection) -> None:
        db.execute("PRAGMA defer_foreign_keys=ON")
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE automatic_jobs_v14 (
                id TEXT PRIMARY KEY COLLATE NOCASE,
                display_name TEXT NOT NULL,
                media_key TEXT NOT NULL DEFAULT 'LTO-6',
                library_id TEXT NOT NULL REFERENCES libraries(id),
                device_name TEXT NOT NULL,
                mount_path TEXT NOT NULL,
                status TEXT NOT NULL CHECK(status IN (
                    'planned','pending','waiting_media','identifying_media',
                    'formatting_media','mounting','writing','writing_manifest',
                    'finalizing_index','unmounting','committing','unloading',
                    'paused','completed','failed'
                )),
                current_sequence INTEGER NOT NULL DEFAULT 0,
                total_cassettes INTEGER NOT NULL,
                destructive_confirmed_at TEXT NOT NULL,
                force_format INTEGER NOT NULL DEFAULT 0 CHECK(force_format IN (0, 1)),
                created_at TEXT NOT NULL,
                started_at TEXT,
                completed_at TEXT,
                last_error TEXT
            );
            CREATE TABLE automatic_cassettes_v14 (
                job_id TEXT NOT NULL REFERENCES automatic_jobs_v14(id) ON DELETE CASCADE,
                sequence INTEGER NOT NULL,
                physical_label TEXT NOT NULL COLLATE NOCASE,
                tape_serial TEXT NOT NULL,
                status TEXT NOT NULL CHECK(status IN (
                    'pending','waiting_media','identifying_media','formatting_media',
                    'mounting','writing','writing_manifest','finalizing_index',
                    'unmounting','committing','unloading','paused','completed','failed'
                )),
                tape_id TEXT,
                block_id TEXT,
                planned_files INTEGER NOT NULL,
                planned_bytes INTEGER NOT NULL,
                copied_files INTEGER NOT NULL DEFAULT 0,
                copied_bytes INTEGER NOT NULL DEFAULT 0,
                started_at TEXT,
                completed_at TEXT,
                error TEXT,
                operation TEXT NOT NULL DEFAULT 'format'
                    CHECK(operation IN ('format', 'append')),
                reuse_registered INTEGER NOT NULL DEFAULT 0
                    CHECK(reuse_registered IN (0, 1)),
                PRIMARY KEY(job_id, sequence),
                UNIQUE(job_id, physical_label),
                UNIQUE(job_id, tape_serial)
            );
            CREATE TABLE automatic_job_libraries_v14 (
                job_id TEXT NOT NULL REFERENCES automatic_jobs_v14(id) ON DELETE CASCADE,
                library_id TEXT NOT NULL REFERENCES libraries(id),
                sequence INTEGER NOT NULL,
                PRIMARY KEY(job_id, library_id),
                UNIQUE(job_id, sequence)
            );
            CREATE TABLE automatic_cassette_items_v14 (
                job_id TEXT NOT NULL,
                sequence INTEGER NOT NULL,
                item_sequence INTEGER NOT NULL,
                library_id TEXT NOT NULL REFERENCES libraries(id),
                relative_path TEXT NOT NULL COLLATE NOCASE,
                size INTEGER NOT NULL,
                mtime_ns INTEGER NOT NULL,
                PRIMARY KEY(job_id, sequence, item_sequence),
                UNIQUE(job_id, library_id, relative_path),
                FOREIGN KEY(job_id, sequence)
                    REFERENCES automatic_cassettes_v14(job_id, sequence) ON DELETE CASCADE
            );
            """,
        )
        db.execute(
            """
            INSERT INTO automatic_jobs_v14
            SELECT id, display_name, media_key, library_id, device_name, mount_path,
                   CASE status WHEN 'formatting' THEN 'formatting_media' ELSE status END,
                   current_sequence, total_cassettes, destructive_confirmed_at,
                   force_format, created_at, started_at, completed_at, last_error
            FROM automatic_jobs
            """
        )
        db.execute(
            """
            INSERT INTO automatic_cassettes_v14
            SELECT job_id, sequence, physical_label, tape_serial,
                   CASE status WHEN 'formatting' THEN 'formatting_media' ELSE status END,
                   tape_id, block_id, planned_files, planned_bytes, copied_files,
                   copied_bytes, started_at, completed_at, error, operation,
                   reuse_registered
            FROM automatic_cassettes
            """
        )
        db.execute(
            """
            INSERT INTO automatic_job_libraries_v14
            SELECT job_id, library_id, sequence FROM automatic_job_libraries
            """
        )
        db.execute(
            """
            INSERT INTO automatic_cassette_items_v14
            SELECT job_id, sequence, item_sequence, library_id, relative_path,
                   size, mtime_ns FROM automatic_cassette_items
            """
        )
        self._execute_sql_batch(
            db,
            """
            DROP TABLE automatic_cassette_items;
            DROP TABLE automatic_job_libraries;
            DROP TABLE automatic_cassettes;
            DROP TABLE automatic_jobs;
            ALTER TABLE automatic_jobs_v14 RENAME TO automatic_jobs;
            ALTER TABLE automatic_cassettes_v14 RENAME TO automatic_cassettes;
            ALTER TABLE automatic_job_libraries_v14 RENAME TO automatic_job_libraries;
            ALTER TABLE automatic_cassette_items_v14 RENAME TO automatic_cassette_items;
            CREATE INDEX ix_automatic_cassette_items_queue
                ON automatic_cassette_items(job_id, sequence, item_sequence);
            """,
        )
        self._create_schema_14_tables(db)
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        if violations:
            raise CatalogError("Schema 14 migration failed foreign-key validation")
        db.execute("UPDATE metadata SET value='14' WHERE key='schema_version'")

    def _migrate_v14_to_v15(self, db: sqlite3.Connection) -> None:
        self._create_schema_15_frozen_recovery(db)
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 15 migration failed catalog validation")
        from .daemon.frozen_job import FrozenJobError, FrozenJobPlan

        active_jobs = db.execute(
            "SELECT job_id FROM imported_job_policies "
            "WHERE authority_state='active_linux' ORDER BY job_id"
        ).fetchall()
        for row in active_jobs:
            try:
                FrozenJobPlan._load(db, row["job_id"])
            except (
                FrozenJobError,
                LookupError,
                sqlite3.DatabaseError,
                TypeError,
                ValueError,
            ) as exc:
                raise CatalogError(
                    "upgraded frozen authority failed semantic validation"
                ) from exc
        db.execute("UPDATE metadata SET value='15' WHERE key='schema_version'")

    def _migrate_v15_to_v16(self, db: sqlite3.Connection) -> None:
        self._maintain_schema_16_ltfs_receipts(db)
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 16 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='16' WHERE key='schema_version'")

    def _migrate_v16_to_v17(self, db: sqlite3.Connection) -> None:
        self._maintain_schema_17_format_media_rebinding(db)
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 17 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='17' WHERE key='schema_version'")

    def _migrate_v17_to_v18(self, db: sqlite3.Connection) -> None:
        common_columns = (
            "operation_id",
            "owner_generation",
            "confirmation_confirmed_at",
        )
        trailing_columns = (
            "format_command_id",
            "expected_label",
            "observed_label",
            "expected_serial",
            "observed_serial",
            "post_volume_uuid",
            "post_index_generation",
            "pre_media_identity_sha256",
            "post_media_identity_sha256",
            "recorded_at",
        )
        identify_layout = (
            *common_columns,
            "pre_identify_command_id",
            trailing_columns[0],
            "post_identify_command_id",
            *trailing_columns[1:],
        )
        probe_layout = (
            *common_columns,
            "pre_probe_media_command_id",
            trailing_columns[0],
            "post_probe_media_command_id",
            *trailing_columns[1:],
        )
        columns = tuple(
            row["name"]
            for row in db.execute("PRAGMA table_info(format_media_rebindings)")
        )
        if columns not in (identify_layout, probe_layout):
            raise CatalogError("Schema 17 format media rebinding layout is invalid")
        row_count = db.execute(
            "SELECT COUNT(*) FROM format_media_rebindings"
        ).fetchone()[0]
        if columns == identify_layout:
            db.execute(
                "ALTER TABLE format_media_rebindings RENAME COLUMN "
                "pre_identify_command_id TO pre_probe_media_command_id"
            )
            db.execute(
                "ALTER TABLE format_media_rebindings RENAME COLUMN "
                "post_identify_command_id TO post_probe_media_command_id"
            )
        self._maintain_schema_18_format_media_rebinding(db)
        migrated_columns = tuple(
            row["name"]
            for row in db.execute("PRAGMA table_info(format_media_rebindings)")
        )
        migrated_count = db.execute(
            "SELECT COUNT(*) FROM format_media_rebindings"
        ).fetchone()[0]
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if (
            migrated_columns != probe_layout
            or migrated_count != row_count
            or violations
            or integrity != ["ok"]
        ):
            raise CatalogError("Schema 18 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='18' WHERE key='schema_version'")

    def _migrate_v18_to_v19(self, db: sqlite3.Connection) -> None:
        self._maintain_schema_19_ltfs_qualification(db)
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 19 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='19' WHERE key='schema_version'")

    def _migrate_v19_to_v20(self, db: sqlite3.Connection) -> None:
        columns = tuple(
            row["name"]
            for row in db.execute("PRAGMA table_info(ltfs_qualification_stages)")
        )
        expected = (
            "run_id",
            "ordinal",
            "operation",
            "request_sha256",
            "dispatched",
            "terminal_receipt_sha256",
            "child_exit_code",
            "before_volume_uuid",
            "before_generation",
            "after_volume_uuid",
            "after_generation",
            "content_manifest_sha256",
            "verdict",
            "recorded_at",
        )
        if columns != expected:
            raise CatalogError("Schema 20 migration found an invalid source layout")
        row_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_stages"
        ).fetchone()[0]
        db.execute("DROP TRIGGER ltfs_qualification_stages_immutable_update")
        db.execute("DROP TRIGGER ltfs_qualification_stages_immutable_delete")
        db.execute(
            "ALTER TABLE ltfs_qualification_stages "
            "RENAME TO ltfs_qualification_stages_v19"
        )
        self._maintain_schema_20_ltfs_qualification(db)
        joined = ",".join(expected)
        db.execute(
            f"INSERT INTO ltfs_qualification_stages({joined}) "
            f"SELECT {joined} FROM ltfs_qualification_stages_v19"
        )
        db.execute("DROP TABLE ltfs_qualification_stages_v19")
        migrated_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_stages"
        ).fetchone()[0]
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if migrated_count != row_count or violations or integrity != ["ok"]:
            raise CatalogError("Schema 20 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='20' WHERE key='schema_version'")

    def _migrate_v20_to_v21(self, db: sqlite3.Connection) -> None:
        run_columns = tuple(
            row["name"]
            for row in db.execute("PRAGMA table_info(ltfs_qualification_runs)")
        )
        expected_runs = (
            "run_id",
            "plan_sha256",
            "plan_json",
            "job_id",
            "cassette_sequence",
            "physical_label",
            "tape_serial",
            "drive_serial",
            "drive_wwid",
            "linux_tree_sha256",
            "ltfs_tree_sha256",
            "ltfs_rpm_sha256",
            "status",
            "fence_reason",
            "created_at",
            "fenced_at",
        )
        source_columns = tuple(
            row["name"]
            for row in db.execute("PRAGMA table_info(ltfs_qualification_stages)")
        )
        expected_source = (
            "run_id",
            "ordinal",
            "operation",
            "request_sha256",
            "dispatched",
            "terminal_receipt_sha256",
            "child_exit_code",
            "before_volume_uuid",
            "before_generation",
            "after_volume_uuid",
            "after_generation",
            "content_manifest_sha256",
            "verdict",
            "recorded_at",
        )
        existing_object = db.execute(
            "SELECT type FROM sqlite_master "
            "WHERE name='ltfs_qualification_reconciliations'"
        ).fetchone()
        if run_columns != expected_runs or source_columns != expected_source:
            raise CatalogError("Schema 21 migration found an invalid schema 20 layout")
        if existing_object is not None:
            if existing_object["type"] != "table":
                raise CatalogError(
                    "Schema 21 migration found an invalid schema 20 layout"
                )
            self._validate_schema_21_ltfs_qualification_layout(db)
        stage_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_stages"
        ).fetchone()[0]
        run_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_runs"
        ).fetchone()[0]
        if existing_object is None:
            self._create_schema_21_ltfs_qualification(db)
        migrated_stage_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_stages"
        ).fetchone()[0]
        migrated_run_count = db.execute(
            "SELECT COUNT(*) FROM ltfs_qualification_runs"
        ).fetchone()[0]
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if (
            migrated_stage_count != stage_count
            or migrated_run_count != run_count
            or violations
            or integrity != ["ok"]
        ):
            raise CatalogError("Schema 21 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='21' WHERE key='schema_version'")

    def _migrate_v21_to_v22(self, db: sqlite3.Connection) -> None:
        """Repair the persisted pre-cutover format cassette regression.

        A short-lived v21 importer persisted registered-reuse state on the
        untouched format queue.  Only a fully attested frozen pre-cutover job
        can be repaired: any unrelated or already-invalid imported job is left
        exactly as found.
        """

        from .daemon.frozen_job import FrozenJobError, FrozenJobPlan
        from .migration.validator import (
            canonical_assignment_sha256,
            canonical_cassette_plan_sha256,
            canonical_completed_evidence_sha256,
        )

        candidates = db.execute(
            """
            SELECT policy.job_id, policy.assignment_sha256,
                   policy.cassette_plan_sha256,
                   policy.completed_evidence_sha256
            FROM imported_job_policies policy
            JOIN automatic_jobs job ON job.id=policy.job_id
            WHERE policy.policy_kind='frozen-allocation'
              AND policy.authority_state='pre_cutover'
              AND policy.windows_authority='resumable'
              AND policy.rollback_allowed=1
              AND policy.activated_by_operation IS NULL
              AND policy.activated_at IS NULL
              AND job.status IN ('paused', 'waiting_media')
              AND job.current_sequence=4
              AND job.total_cassettes>=4
              AND (
                  SELECT COUNT(*) FROM automatic_cassettes cassette
                  WHERE cassette.job_id=policy.job_id
              )=job.total_cassettes
              AND NOT EXISTS (
                  SELECT 1 FROM automatic_cassettes cassette
                  WHERE cassette.job_id=policy.job_id
                    AND (
                        (cassette.sequence<=3 AND cassette.status!='completed')
                        OR (cassette.sequence=4
                            AND cassette.status NOT IN ('pending', 'waiting_media'))
                        OR (cassette.sequence>4 AND cassette.status!='pending')
                        OR (cassette.sequence>=4 AND cassette.operation!='format')
                        OR (cassette.sequence>=4 AND (
                            cassette.tape_id IS NOT NULL
                            OR cassette.block_id IS NOT NULL
                            OR cassette.copied_files!=0
                            OR cassette.copied_bytes!=0
                            OR cassette.completed_at IS NOT NULL
                            OR cassette.error IS NOT NULL
                        ))
                    )
              )
              AND EXISTS (
                  SELECT 1 FROM automatic_cassettes cassette
                  WHERE cassette.job_id=policy.job_id
                    AND cassette.operation='format'
                    AND cassette.status IN ('pending', 'waiting_media')
                    AND (cassette.reuse_registered!=0
                         OR cassette.started_at IS NOT NULL)
              )
            ORDER BY policy.job_id
            """
        ).fetchall()
        if candidates:
            db.execute(
                "DROP TRIGGER IF EXISTS freeze_imported_cassette_identity_update"
            )
        try:
            for index, candidate in enumerate(candidates):
                job_id = candidate["job_id"]
                receipts = db.execute(
                    """
                    SELECT assignment_sha256, cassette_plan_sha256,
                           completed_evidence_sha256
                    FROM migration_receipts WHERE job_id=? ORDER BY id
                    """,
                    (job_id,),
                ).fetchall()
                if len(receipts) != 1:
                    continue
                receipt = receipts[0]
                try:
                    assignment_sha256 = canonical_assignment_sha256(db, job_id)
                    completed_evidence_sha256 = canonical_completed_evidence_sha256(
                        db,
                        job_id,
                        (1, 2, 3),
                        allow_missing_assignments=True,
                    )
                    pre_repair_cassette_plan_sha256 = canonical_cassette_plan_sha256(
                        db,
                        job_id,
                        assignment_sha256=assignment_sha256,
                    )
                except (LookupError, sqlite3.DatabaseError, TypeError, ValueError):
                    continue
                if (
                    assignment_sha256 != candidate["assignment_sha256"]
                    or assignment_sha256 != receipt["assignment_sha256"]
                    or (
                        completed_evidence_sha256
                        != candidate["completed_evidence_sha256"]
                    )
                    or (
                        completed_evidence_sha256
                        != receipt["completed_evidence_sha256"]
                    )
                    or pre_repair_cassette_plan_sha256
                    != candidate["cassette_plan_sha256"]
                    or candidate["cassette_plan_sha256"]
                    != receipt["cassette_plan_sha256"]
                ):
                    continue

                savepoint = f"schema_22_frozen_candidate_{index}"
                db.execute(f"SAVEPOINT {savepoint}")
                try:
                    db.execute(
                        """
                        UPDATE automatic_cassettes
                        SET reuse_registered=0, started_at=NULL
                        WHERE job_id=? AND operation='format'
                          AND status IN ('pending', 'waiting_media')
                          AND (reuse_registered!=0 OR started_at IS NOT NULL)
                        """,
                        (job_id,),
                    )
                    cassette_plan_sha256 = canonical_cassette_plan_sha256(
                        db,
                        job_id,
                        assignment_sha256=assignment_sha256,
                    )
                    db.execute(
                        "UPDATE imported_job_policies SET cassette_plan_sha256=? "
                        "WHERE job_id=?",
                        (cassette_plan_sha256, job_id),
                    )
                    db.execute(
                        "UPDATE migration_receipts SET cassette_plan_sha256=? "
                        "WHERE job_id=?",
                        (cassette_plan_sha256, job_id),
                    )
                    FrozenJobPlan._load(db, job_id)
                except (
                    FrozenJobError,
                    LookupError,
                    sqlite3.DatabaseError,
                    TypeError,
                    ValueError,
                ):
                    db.execute(f"ROLLBACK TO {savepoint}")
                    db.execute(f"RELEASE {savepoint}")
                    continue
                db.execute(f"RELEASE {savepoint}")
        finally:
            if candidates:
                self._install_imported_job_freeze_triggers(db)

        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 22 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='22' WHERE key='schema_version'")

    def _migrate_v22_to_v23(self, db: sqlite3.Connection) -> None:
        """Add immutable, shared job-plan drafts without changing legacy jobs."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS cartridges (
                physical_label TEXT PRIMARY KEY COLLATE NOCASE,
                first_seen_at TEXT NOT NULL,
                CHECK(length(physical_label)=6),
                CHECK(physical_label NOT GLOB '*[^A-Z0-9]*')
            );

            CREATE TABLE IF NOT EXISTS job_plan_drafts (
                id TEXT PRIMARY KEY COLLATE NOCASE,
                state TEXT NOT NULL CHECK(state IN (
                    'building','ready','failed','expired','consumed'
                )),
                kind TEXT NOT NULL CHECK(kind IN ('create','extend')),
                creator TEXT NOT NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                media_key TEXT NOT NULL,
                requested_library_ids_json TEXT NOT NULL,
                canonical_json TEXT NOT NULL,
                digest_sha256 TEXT NOT NULL CHECK(length(digest_sha256)=64),
                canonical_json_version INTEGER NOT NULL DEFAULT 1
                    CHECK(canonical_json_version=1),
                plan_schema_version INTEGER NOT NULL DEFAULT 1
                    CHECK(plan_schema_version=1),
                planner_version TEXT NOT NULL DEFAULT 'automatic-ltfs-v1',
                application_settings_revision INTEGER NOT NULL DEFAULT 0
                    CHECK(application_settings_revision>=0),
                application_settings_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(application_settings_fingerprint_sha256)=64),
                base_job_id TEXT,
                base_job_revision INTEGER,
                base_job_fingerprint_sha256 TEXT,
                failure_code TEXT,
                failure_message TEXT,
                consumed_at TEXT,
                consumed_job_id TEXT REFERENCES automatic_jobs(id),
                consumption_key TEXT,
                consumption_request_sha256 TEXT,
                CHECK(base_job_revision IS NULL OR base_job_revision>=0),
                CHECK(base_job_fingerprint_sha256 IS NULL
                      OR length(base_job_fingerprint_sha256)=64),
                CHECK(consumption_request_sha256 IS NULL
                      OR length(consumption_request_sha256)=64),
                CHECK(state!='consumed' OR (
                    consumed_at IS NOT NULL AND consumed_job_id IS NOT NULL
                    AND consumption_key IS NOT NULL
                    AND consumption_request_sha256 IS NOT NULL
                ))
            );

            CREATE TABLE IF NOT EXISTS job_plan_libraries (
                plan_id TEXT NOT NULL REFERENCES job_plan_drafts(id) ON DELETE CASCADE,
                sequence INTEGER NOT NULL CHECK(sequence>0),
                library_id TEXT NOT NULL,
                source_root TEXT NOT NULL,
                scan_revision INTEGER NOT NULL CHECK(scan_revision>=0),
                scan_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(scan_fingerprint_sha256)=64),
                PRIMARY KEY(plan_id, sequence),
                UNIQUE(plan_id, library_id)
            );

            CREATE TABLE IF NOT EXISTS job_plan_cassettes (
                plan_id TEXT NOT NULL REFERENCES job_plan_drafts(id) ON DELETE CASCADE,
                sequence INTEGER NOT NULL CHECK(sequence>0),
                objects INTEGER NOT NULL CHECK(objects>=0),
                payload_bytes INTEGER NOT NULL CHECK(payload_bytes>=0),
                allocation_bytes INTEGER NOT NULL CHECK(allocation_bytes>=payload_bytes),
                capacity_utilization REAL NOT NULL
                    CHECK(capacity_utilization>=0 AND capacity_utilization<=1),
                operation TEXT NOT NULL CHECK(operation IN ('format','append','reserve')),
                PRIMARY KEY(plan_id, sequence)
            );

            CREATE TABLE IF NOT EXISTS job_plan_items (
                plan_id TEXT NOT NULL,
                cassette_sequence INTEGER NOT NULL,
                item_sequence INTEGER NOT NULL CHECK(item_sequence>0),
                library_id TEXT NOT NULL,
                relative_path TEXT NOT NULL,
                size INTEGER NOT NULL CHECK(size>=0),
                mtime_ns INTEGER NOT NULL CHECK(mtime_ns>=0),
                PRIMARY KEY(plan_id, cassette_sequence, item_sequence),
                UNIQUE(plan_id, library_id, relative_path),
                FOREIGN KEY(plan_id, cassette_sequence)
                    REFERENCES job_plan_cassettes(plan_id, sequence) ON DELETE CASCADE
            );

            CREATE INDEX IF NOT EXISTS ix_job_plan_drafts_state_expiry
                ON job_plan_drafts(state, expires_at);
            CREATE UNIQUE INDEX IF NOT EXISTS ix_automatic_cassettes_one_active_physical_label
                ON automatic_cassettes(upper(substr(physical_label, 1, 6)))
                WHERE status NOT IN ('completed','failed');

            CREATE TRIGGER IF NOT EXISTS job_plan_libraries_immutable_update
            BEFORE UPDATE ON job_plan_libraries
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_cassettes_immutable_update
            BEFORE UPDATE ON job_plan_cassettes
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_items_immutable_update
            BEFORE UPDATE ON job_plan_items
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS job_plan_libraries_immutable_insert
            BEFORE INSERT ON job_plan_libraries
            WHEN (SELECT state FROM job_plan_drafts WHERE id=NEW.plan_id)!='building'
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_cassettes_immutable_insert
            BEFORE INSERT ON job_plan_cassettes
            WHEN (SELECT state FROM job_plan_drafts WHERE id=NEW.plan_id)!='building'
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_items_immutable_insert
            BEFORE INSERT ON job_plan_items
            WHEN (SELECT state FROM job_plan_drafts WHERE id=NEW.plan_id)!='building'
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS job_plan_libraries_immutable_delete
            BEFORE DELETE ON job_plan_libraries
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_cassettes_immutable_delete
            BEFORE DELETE ON job_plan_cassettes
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_items_immutable_delete
            BEFORE DELETE ON job_plan_items
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS job_plan_draft_frozen_fields_immutable
            BEFORE UPDATE ON job_plan_drafts
            WHEN OLD.state IN ('ready','failed','expired','consumed') AND (
                NEW.kind!=OLD.kind OR NEW.creator!=OLD.creator
                OR NEW.created_at!=OLD.created_at OR NEW.expires_at!=OLD.expires_at
                OR NEW.media_key!=OLD.media_key
                OR NEW.requested_library_ids_json!=OLD.requested_library_ids_json
                OR NEW.canonical_json!=OLD.canonical_json
                OR NEW.digest_sha256!=OLD.digest_sha256
                OR NEW.canonical_json_version!=OLD.canonical_json_version
                OR NEW.plan_schema_version!=OLD.plan_schema_version
                OR NEW.planner_version!=OLD.planner_version
                OR NEW.application_settings_revision!=OLD.application_settings_revision
                OR NEW.application_settings_fingerprint_sha256
                   !=OLD.application_settings_fingerprint_sha256
                OR NEW.base_job_id IS NOT OLD.base_job_id
                OR NEW.base_job_revision IS NOT OLD.base_job_revision
                OR NEW.base_job_fingerprint_sha256 IS NOT OLD.base_job_fingerprint_sha256
                OR NEW.failure_code IS NOT OLD.failure_code
                OR NEW.failure_message IS NOT OLD.failure_message
                OR (
                    NOT (OLD.state='ready' AND NEW.state='consumed')
                    AND (
                        NEW.consumed_at IS NOT OLD.consumed_at
                        OR NEW.consumed_job_id IS NOT OLD.consumed_job_id
                        OR NEW.consumption_key IS NOT OLD.consumption_key
                        OR NEW.consumption_request_sha256
                           IS NOT OLD.consumption_request_sha256
                    )
                )
            )
            BEGIN
                SELECT RAISE(ABORT, 'job plan draft is immutable');
            END;

            CREATE TRIGGER IF NOT EXISTS job_plan_draft_controlled_delete
            BEFORE DELETE ON job_plan_drafts
            WHEN OLD.state!='expired' OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(
                    ABORT, 'job plan draft deletion requires expired cleanup'
                );
            END;

            CREATE TRIGGER IF NOT EXISTS job_plan_draft_state_transition
            BEFORE UPDATE OF state ON job_plan_drafts
            WHEN NOT (
                NEW.state=OLD.state
                OR (OLD.state='building'
                    AND NEW.state IN ('ready','failed','expired'))
                OR (OLD.state='ready'
                    AND NEW.state IN ('consumed','expired'))
            )
            BEGIN
                SELECT RAISE(ABORT, 'invalid job plan state transition');
            END;

            CREATE TRIGGER IF NOT EXISTS automatic_cassettes_register_cartridge_insert
            AFTER INSERT ON automatic_cassettes
            WHEN length(NEW.physical_label)>=6
                 AND upper(substr(NEW.physical_label, 1, 6))
                     NOT GLOB '*[^A-Z0-9]*'
            BEGIN
                INSERT OR IGNORE INTO cartridges(physical_label, first_seen_at)
                VALUES(
                    upper(substr(NEW.physical_label, 1, 6)),
                    COALESCE(
                        (SELECT created_at FROM automatic_jobs WHERE id=NEW.job_id),
                        CURRENT_TIMESTAMP
                    )
                );
            END;
            """,
        )
        db.execute(
            """
            INSERT OR IGNORE INTO cartridges(physical_label, first_seen_at)
            SELECT upper(substr(cassette.physical_label, 1, 6)), min(job.created_at)
            FROM automatic_cassettes cassette
            JOIN automatic_jobs job ON job.id=cassette.job_id
            WHERE length(cassette.physical_label)>=6
              AND upper(substr(cassette.physical_label, 1, 6))
                  NOT GLOB '*[^A-Z0-9]*'
            GROUP BY upper(substr(cassette.physical_label, 1, 6))
            """
        )
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if violations or integrity != ["ok"]:
            raise CatalogError("Schema 23 migration failed catalog validation")
        db.execute("UPDATE metadata SET value='23' WHERE key='schema_version'")

    def _migrate_v23_to_v24(self, db: sqlite3.Connection) -> None:
        """Repair terminal plan evidence triggers installed by schema 23."""

        self._execute_sql_batch(
            db,
            """
            DROP TRIGGER IF EXISTS job_plan_libraries_immutable_delete;
            DROP TRIGGER IF EXISTS job_plan_cassettes_immutable_delete;
            DROP TRIGGER IF EXISTS job_plan_items_immutable_delete;
            DROP TRIGGER IF EXISTS job_plan_draft_frozen_fields_immutable;
            DROP TRIGGER IF EXISTS job_plan_draft_controlled_delete;

            CREATE TRIGGER job_plan_libraries_immutable_delete
            BEFORE DELETE ON job_plan_libraries
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER job_plan_cassettes_immutable_delete
            BEFORE DELETE ON job_plan_cassettes
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            CREATE TRIGGER job_plan_items_immutable_delete
            BEFORE DELETE ON job_plan_items
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;

            CREATE TRIGGER job_plan_draft_frozen_fields_immutable
            BEFORE UPDATE ON job_plan_drafts
            WHEN OLD.state IN ('ready','failed','expired','consumed') AND (
                NEW.kind!=OLD.kind OR NEW.creator!=OLD.creator
                OR NEW.created_at!=OLD.created_at OR NEW.expires_at!=OLD.expires_at
                OR NEW.media_key!=OLD.media_key
                OR NEW.requested_library_ids_json!=OLD.requested_library_ids_json
                OR NEW.canonical_json!=OLD.canonical_json
                OR NEW.digest_sha256!=OLD.digest_sha256
                OR NEW.canonical_json_version!=OLD.canonical_json_version
                OR NEW.plan_schema_version!=OLD.plan_schema_version
                OR NEW.planner_version!=OLD.planner_version
                OR NEW.application_settings_revision!=OLD.application_settings_revision
                OR NEW.application_settings_fingerprint_sha256
                   !=OLD.application_settings_fingerprint_sha256
                OR NEW.base_job_id IS NOT OLD.base_job_id
                OR NEW.base_job_revision IS NOT OLD.base_job_revision
                OR NEW.base_job_fingerprint_sha256 IS NOT OLD.base_job_fingerprint_sha256
                OR NEW.failure_code IS NOT OLD.failure_code
                OR NEW.failure_message IS NOT OLD.failure_message
                OR (
                    NOT (OLD.state='ready' AND NEW.state='consumed')
                    AND (
                        NEW.consumed_at IS NOT OLD.consumed_at
                        OR NEW.consumed_job_id IS NOT OLD.consumed_job_id
                        OR NEW.consumption_key IS NOT OLD.consumption_key
                        OR NEW.consumption_request_sha256
                           IS NOT OLD.consumption_request_sha256
                    )
                )
            )
            BEGIN
                SELECT RAISE(ABORT, 'job plan draft is immutable');
            END;

            CREATE TRIGGER job_plan_draft_controlled_delete
            BEFORE DELETE ON job_plan_drafts
            WHEN OLD.state!='expired' OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(
                    ABORT, 'job plan draft deletion requires expired cleanup'
                );
            END;
            """,
        )
        db.execute("UPDATE metadata SET value='24' WHERE key='schema_version'")

    def _migrate_v24_to_v25(self, db: sqlite3.Connection) -> None:
        """Add named-library lifecycle and scan evidence without replacing history."""

        columns = {
            str(row["name"]) for row in db.execute("PRAGMA table_info(libraries)")
        }
        additions = {
            "enabled": "INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1))",
            "source_canonical_root": "TEXT",
            "source_identity_sha256": (
                "TEXT CHECK(source_identity_sha256 IS NULL "
                "OR length(source_identity_sha256)=64)"
            ),
            "scan_state": (
                "TEXT NOT NULL DEFAULT 'never' "
                "CHECK(scan_state IN ('never','running','ready','failed'))"
            ),
            "scan_revision": ("INTEGER NOT NULL DEFAULT 0 CHECK(scan_revision>=0)"),
            "scan_fingerprint_sha256": (
                "TEXT CHECK(scan_fingerprint_sha256 IS NULL "
                "OR length(scan_fingerprint_sha256)=64)"
            ),
        }
        for name, declaration in additions.items():
            if name not in columns:
                db.execute(f"ALTER TABLE libraries ADD COLUMN {name} {declaration}")
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS management_idempotency (
                actor TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                action TEXT NOT NULL,
                target_id TEXT NOT NULL COLLATE NOCASE,
                request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                response_json TEXT NOT NULL,
                created_at TEXT NOT NULL,
                PRIMARY KEY(actor, idempotency_key)
            );
            """,
        )
        db.execute("UPDATE libraries SET enabled=0 WHERE status='retired'")
        scanned = db.execute(
            "SELECT id,source_root,last_scan_files,last_scan_bytes,last_scanned_at "
            "FROM libraries WHERE last_scanned_at IS NOT NULL "
            "AND scan_revision=0 AND scan_fingerprint_sha256 IS NULL"
        ).fetchall()
        for row in scanned:
            payload = json.dumps(
                {
                    "byte_count": int(row["last_scan_bytes"] or 0),
                    "file_count": int(row["last_scan_files"] or 0),
                    "library_id": str(row["id"]),
                    "migrated_last_successful_scan_at": row["last_scanned_at"],
                    "source_root": str(row["source_root"]),
                },
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            db.execute(
                "UPDATE libraries SET scan_state='ready',scan_revision=1,"
                "scan_fingerprint_sha256=? WHERE id=?",
                (hashlib.sha256(payload.encode("utf-8")).hexdigest(), row["id"]),
            )
        db.execute("UPDATE metadata SET value='25' WHERE key='schema_version'")

    def _migrate_v25_to_v26(self, db: sqlite3.Connection) -> None:
        """Add managed shares while preserving every legacy local source root."""

        library_columns = {
            str(row["name"]) for row in db.execute("PRAGMA table_info(libraries)")
        }
        if "source_kind" not in library_columns:
            db.execute(
                "ALTER TABLE libraries ADD COLUMN source_kind TEXT NOT NULL "
                "DEFAULT 'local' CHECK(source_kind IN ('local','network'))"
            )
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS managed_shares (
                share_id TEXT PRIMARY KEY COLLATE NOCASE,
                display_name TEXT NOT NULL,
                protocol TEXT NOT NULL CHECK(protocol IN ('nfs','smb')),
                config_json TEXT NOT NULL,
                revision INTEGER NOT NULL CHECK(revision > 0),
                credential_generation INTEGER NOT NULL
                    CHECK(credential_generation >= 0),
                credential_configured INTEGER NOT NULL
                    CHECK(credential_configured IN (0,1)),
                desired_state TEXT NOT NULL
                    CHECK(desired_state IN ('connected','disconnected')),
                observed_state TEXT NOT NULL CHECK(observed_state IN (
                    'disconnected','connecting','connected','disconnecting','error'
                )),
                lifecycle TEXT NOT NULL
                    CHECK(lifecycle IN ('active','disabled','retired')),
                auto_connect INTEGER NOT NULL CHECK(auto_connect IN (0,1)),
                mount_identity_sha256 TEXT CHECK(
                    mount_identity_sha256 IS NULL
                    OR length(mount_identity_sha256)=64
                ),
                safe_error_code TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                last_checked_at TEXT
            );

            CREATE TABLE IF NOT EXISTS share_operations (
                operation_id TEXT PRIMARY KEY COLLATE NOCASE,
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                keyed_request_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(keyed_request_fingerprint_sha256)=64),
                expected_share_revision INTEGER NOT NULL
                    CHECK(expected_share_revision > 0),
                state TEXT NOT NULL
                    CHECK(state IN ('running','succeeded','failed')),
                safe_error_code TEXT,
                receipt_sha256 TEXT CHECK(
                    receipt_sha256 IS NULL OR length(receipt_sha256)=64
                ),
                started_at TEXT NOT NULL,
                finished_at TEXT,
                UNIQUE(actor,idempotency_key),
                CHECK(
                    (state='running' AND finished_at IS NULL)
                    OR (state!='running' AND finished_at IS NOT NULL)
                )
            );
            CREATE UNIQUE INDEX IF NOT EXISTS ux_share_one_live_operation
                ON share_operations(share_id COLLATE NOCASE)
                WHERE state='running';

            CREATE TABLE IF NOT EXISTS library_share_bindings (
                library_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES libraries(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                relative_subpath TEXT NOT NULL,
                bound_share_revision INTEGER NOT NULL
                    CHECK(bound_share_revision > 0),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS ix_library_share_bindings_share
                ON library_share_bindings(share_id COLLATE NOCASE);
            """,
        )
        db.execute("UPDATE metadata SET value='26' WHERE key='schema_version'")

    def _migrate_v26_to_v27(self, db: sqlite3.Connection) -> None:
        """Persist native job policy state without altering schema-26 shares."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS job_management_state (
                job_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES automatic_jobs(id),
                revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),
                retired_at TEXT,
                pause_requested_at TEXT,
                pause_acknowledged_at TEXT,
                current_checkpoint TEXT NOT NULL DEFAULT 'saved',
                creation_plan_id TEXT REFERENCES job_plan_drafts(id),
                updated_at TEXT NOT NULL,
                CHECK(pause_acknowledged_at IS NULL
                      OR pause_requested_at IS NOT NULL)
            );

            CREATE TABLE IF NOT EXISTS job_execution_state (
                singleton INTEGER PRIMARY KEY CHECK(singleton=1),
                current_job_id TEXT REFERENCES automatic_jobs(id),
                updated_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS job_management_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES automatic_jobs(id),
                occurred_at TEXT NOT NULL,
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                checkpoint TEXT NOT NULL,
                payload_json TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS ix_job_management_history_job
                ON job_management_history(job_id,id);

            CREATE TABLE IF NOT EXISTS job_extension_commits (
                plan_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES job_plan_drafts(id),
                job_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES automatic_jobs(id),
                base_revision INTEGER NOT NULL CHECK(base_revision>=0),
                committed_revision INTEGER NOT NULL CHECK(committed_revision>base_revision),
                first_new_sequence INTEGER,
                committed_at TEXT NOT NULL,
                CHECK(first_new_sequence IS NULL OR first_new_sequence>0)
            );

            CREATE TABLE IF NOT EXISTS job_manifest_history (
                job_id TEXT NOT NULL COLLATE NOCASE REFERENCES automatic_jobs(id),
                revision INTEGER NOT NULL CHECK(revision>=0),
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                item_sequence INTEGER NOT NULL CHECK(item_sequence>0),
                library_id TEXT NOT NULL REFERENCES libraries(id),
                relative_path TEXT NOT NULL COLLATE NOCASE,
                size INTEGER NOT NULL CHECK(size>=0),
                mtime_ns INTEGER NOT NULL CHECK(mtime_ns>=0),
                PRIMARY KEY(job_id,revision,cassette_sequence,item_sequence)
            );
            CREATE INDEX IF NOT EXISTS ix_job_manifest_history_job
                ON job_manifest_history(job_id,cassette_sequence,item_sequence);
            """,
        )
        now = utc_now()
        db.execute(
            """
            INSERT OR IGNORE INTO job_management_state(
                job_id,revision,current_checkpoint,creation_plan_id,updated_at
            )
            SELECT job.id,0,
                CASE job.status
                    WHEN 'planned' THEN 'saved'
                    WHEN 'formatting' THEN 'formatting_media'
                    ELSE job.status
                END,
                (SELECT draft.id FROM job_plan_drafts draft
                 WHERE draft.consumed_job_id=job.id LIMIT 1),
                ?
            FROM automatic_jobs job
            """,
            (now,),
        )
        current = db.execute(
            """
            SELECT job.id
            FROM automatic_jobs job
            LEFT JOIN imported_job_policies policy ON policy.job_id=job.id
            LEFT JOIN daemon_operations operation ON operation.job_id=job.id
                AND operation.state IN ('running','recovery_required')
            WHERE job.status NOT IN ('completed','failed')
            ORDER BY (operation.id IS NOT NULL) DESC,
                     (policy.job_id IS NOT NULL) DESC,
                     job.started_at DESC,job.created_at DESC,job.id DESC
            LIMIT 1
            """
        ).fetchone()
        db.execute(
            "INSERT OR IGNORE INTO job_execution_state(singleton,current_job_id,updated_at) "
            "VALUES(1,?,?)",
            (None if current is None else current["id"], now),
        )
        db.execute("UPDATE metadata SET value='27' WHERE key='schema_version'")

    def _migrate_v27_to_v28(self, db: sqlite3.Connection) -> None:
        """Add authoritative application policy without rewriting frozen work."""

        operation_columns = {
            str(row["name"])
            for row in db.execute("PRAGMA table_info(daemon_operations)")
        }
        if "copy_buffer_bytes" not in operation_columns:
            db.execute(
                "ALTER TABLE daemon_operations ADD COLUMN copy_buffer_bytes INTEGER "
                "CHECK(copy_buffer_bytes IS NULL OR "
                "copy_buffer_bytes BETWEEN 1048576 AND 67108864)"
            )
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS application_settings (
                singleton INTEGER PRIMARY KEY CHECK(singleton=1),
                revision INTEGER NOT NULL CHECK(revision>=1),
                capacity_reserve_bytes INTEGER NOT NULL
                    CHECK(capacity_reserve_bytes>=0),
                minimum_source_file_age_seconds INTEGER NOT NULL
                    CHECK(minimum_source_file_age_seconds BETWEEN 0 AND 2678400),
                copy_buffer_bytes INTEGER NOT NULL
                    CHECK(copy_buffer_bytes BETWEEN 1048576 AND 67108864),
                content_verification_policy TEXT NOT NULL
                    CHECK(content_verification_policy IN ('none','manifest','full')),
                default_media_profile TEXT NOT NULL,
                tape_root_directory TEXT NOT NULL,
                legacy_tape_capacity_bytes INTEGER NOT NULL
                    CHECK(legacy_tape_capacity_bytes>0),
                legacy_source_sha256 TEXT CHECK(
                    legacy_source_sha256 IS NULL OR length(legacy_source_sha256)=64
                ),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS job_plan_policy_snapshots (
                plan_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES job_plan_drafts(id) ON DELETE CASCADE,
                settings_revision INTEGER NOT NULL CHECK(settings_revision>=1),
                policy_json TEXT NOT NULL,
                policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
                created_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS job_policy_snapshots (
                job_id TEXT PRIMARY KEY COLLATE NOCASE,
                plan_id TEXT COLLATE NOCASE REFERENCES job_plan_drafts(id),
                settings_revision INTEGER NOT NULL CHECK(settings_revision>=1),
                policy_json TEXT NOT NULL,
                policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
                created_at TEXT NOT NULL
            );

            CREATE TRIGGER IF NOT EXISTS job_plan_policy_snapshot_immutable_update
            BEFORE UPDATE ON job_plan_policy_snapshots
            BEGIN
                SELECT RAISE(ABORT, 'job plan policy snapshot is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_plan_policy_snapshot_controlled_delete
            BEFORE DELETE ON job_plan_policy_snapshots
            WHEN (SELECT state FROM job_plan_drafts WHERE id=OLD.plan_id)!='expired'
                 OR lto_expired_plan_cleanup_active()!=1
            BEGIN
                SELECT RAISE(ABORT, 'job plan policy snapshot is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_policy_snapshot_immutable_update
            BEFORE UPDATE ON job_policy_snapshots
            BEGIN
                SELECT RAISE(ABORT, 'job policy snapshot is immutable');
            END;
            CREATE TRIGGER IF NOT EXISTS job_policy_snapshot_immutable_delete
            BEFORE DELETE ON job_policy_snapshots
            BEGIN
                SELECT RAISE(ABORT, 'job policy snapshot is immutable');
            END;
            """,
        )
        db.execute("UPDATE metadata SET value='28' WHERE key='schema_version'")

    def _migrate_v28_to_v29(self, db: sqlite3.Connection) -> None:
        """Add optimistic library metadata revisions without changing scan evidence."""

        library_columns = {
            str(row["name"]) for row in db.execute("PRAGMA table_info(libraries)")
        }
        if "metadata_revision" not in library_columns:
            db.execute(
                "ALTER TABLE libraries ADD COLUMN metadata_revision INTEGER "
                "NOT NULL DEFAULT 0 CHECK(metadata_revision>=0)"
            )
        db.execute("UPDATE metadata SET value='29' WHERE key='schema_version'")

    def _migrate_v29_to_v30(self, db: sqlite3.Connection) -> None:
        """Add durable managed-share orchestration without rewriting history."""

        share_columns = {
            str(row["name"]) for row in db.execute("PRAGMA table_info(managed_shares)")
        }
        for name, definition in (
            ("config_revision", "INTEGER NOT NULL DEFAULT 1 CHECK(config_revision>0)"),
            (
                "mounted_config_revision",
                "INTEGER CHECK(mounted_config_revision IS NULL OR mounted_config_revision>0)",
            ),
            (
                "mounted_credential_generation",
                (
                    "INTEGER CHECK(mounted_credential_generation IS NULL "
                    "OR mounted_credential_generation>=0)"
                ),
            ),
            ("removed_at", "TEXT"),
        ):
            if name not in share_columns:
                db.execute(f"ALTER TABLE managed_shares ADD COLUMN {name} {definition}")

        self._execute_sql_batch(
            db,
            """
            DROP INDEX IF EXISTS ux_share_one_live_operation;
            CREATE TABLE share_operations_v30 (
                operation_id TEXT PRIMARY KEY COLLATE NOCASE,
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                keyed_request_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(keyed_request_fingerprint_sha256)=64),
                expected_share_revision INTEGER NOT NULL
                    CHECK(expected_share_revision>0),
                frozen_config_json TEXT NOT NULL,
                frozen_config_revision INTEGER NOT NULL
                    CHECK(frozen_config_revision>0),
                frozen_credential_generation INTEGER NOT NULL
                    CHECK(frozen_credential_generation>=0),
                frozen_observed_state TEXT NOT NULL CHECK(frozen_observed_state IN (
                    'disconnected','connecting','connected','disconnecting','error'
                )),
                state TEXT NOT NULL
                    CHECK(state IN (
                        'queued','running','recovering','succeeded','failed'
                    )),
                owner_id TEXT,
                safe_error_code TEXT,
                receipt_sha256 TEXT CHECK(
                    receipt_sha256 IS NULL OR length(receipt_sha256)=64
                ),
                queued_at TEXT NOT NULL,
                started_at TEXT NOT NULL,
                claimed_at TEXT,
                recovery_deadline TEXT,
                finished_at TEXT,
                recovered_at TEXT,
                UNIQUE(actor,idempotency_key),
                CHECK(
                    (state='queued' AND owner_id IS NULL
                        AND claimed_at IS NULL AND finished_at IS NULL)
                    OR (state IN ('running','recovering') AND owner_id IS NOT NULL
                        AND claimed_at IS NOT NULL AND finished_at IS NULL)
                    OR (state IN ('succeeded','failed') AND finished_at IS NOT NULL)
                )
            );
            INSERT INTO share_operations_v30(
                operation_id,share_id,actor,action,idempotency_key,
                keyed_request_fingerprint_sha256,expected_share_revision,
                frozen_config_json,frozen_config_revision,
                frozen_credential_generation,frozen_observed_state,state,
                owner_id,safe_error_code,receipt_sha256,queued_at,started_at,
                claimed_at,recovery_deadline,finished_at,recovered_at
            )
            SELECT operation.operation_id,operation.share_id,operation.actor,
                operation.action,operation.idempotency_key,
                operation.keyed_request_fingerprint_sha256,
                operation.expected_share_revision,share.config_json,1,
                share.credential_generation,share.observed_state,operation.state,
                CASE WHEN operation.state='running'
                    THEN 'schema29-owner-unknown' END,
                operation.safe_error_code,operation.receipt_sha256,
                operation.started_at,operation.started_at,
                CASE WHEN operation.state='running'
                    THEN operation.started_at END,
                NULL,operation.finished_at,NULL
            FROM share_operations AS operation
            JOIN managed_shares AS share ON share.share_id=operation.share_id;
            DROP TABLE share_operations;
            ALTER TABLE share_operations_v30 RENAME TO share_operations;
            CREATE UNIQUE INDEX ux_share_one_live_operation
                ON share_operations(share_id COLLATE NOCASE)
                WHERE state IN ('queued','running','recovering');
            CREATE INDEX ix_share_operations_latest
                ON share_operations(share_id COLLATE NOCASE,queued_at DESC,operation_id);
            """,
        )
        db.execute("UPDATE metadata SET value='30' WHERE key='schema_version'")

    def _migrate_v30_to_v31(self, db: sqlite3.Connection) -> None:
        """Add separate immutable managed-source evidence and short-lived leases."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS library_share_scan_evidence (
                library_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES libraries(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                scan_revision INTEGER NOT NULL CHECK(scan_revision>0),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                verified_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS library_share_binding_evidence (
                library_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES libraries(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                bound_at TEXT NOT NULL
            );
            CREATE TRIGGER IF NOT EXISTS
                trg_library_share_binding_evidence_no_update
                BEFORE UPDATE ON library_share_binding_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_library_share_binding_evidence'); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_library_share_binding_evidence_no_delete
                BEFORE DELETE ON library_share_binding_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_library_share_binding_evidence'); END;

            CREATE TABLE IF NOT EXISTS operation_share_evidence (
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                library_id TEXT NOT NULL COLLATE NOCASE REFERENCES libraries(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                admitted_at TEXT NOT NULL,
                PRIMARY KEY(operation_id,library_id)
            );
            CREATE TRIGGER IF NOT EXISTS trg_operation_share_evidence_no_update
                BEFORE UPDATE ON operation_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_operation_share_evidence'); END;
            CREATE TRIGGER IF NOT EXISTS trg_operation_share_evidence_no_delete
                BEFORE DELETE ON operation_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_operation_share_evidence'); END;
            CREATE INDEX IF NOT EXISTS ix_operation_share_evidence_share
                ON operation_share_evidence(share_id COLLATE NOCASE,operation_id);

            CREATE TABLE IF NOT EXISTS job_plan_share_evidence (
                plan_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES job_plan_drafts(id),
                library_id TEXT NOT NULL COLLATE NOCASE REFERENCES libraries(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                admitted_at TEXT NOT NULL,
                PRIMARY KEY(plan_id,library_id)
            );
            CREATE TRIGGER IF NOT EXISTS trg_job_plan_share_evidence_no_update
                BEFORE UPDATE ON job_plan_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_job_plan_share_evidence'); END;
            CREATE TRIGGER IF NOT EXISTS trg_job_plan_share_evidence_no_delete
                BEFORE DELETE ON job_plan_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_job_plan_share_evidence'); END;

            CREATE TABLE IF NOT EXISTS automatic_job_share_evidence (
                job_id TEXT NOT NULL COLLATE NOCASE REFERENCES automatic_jobs(id),
                library_id TEXT NOT NULL COLLATE NOCASE REFERENCES libraries(id),
                creation_plan_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES job_plan_drafts(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                admitted_at TEXT NOT NULL,
                PRIMARY KEY(job_id,library_id)
            );
            CREATE TRIGGER IF NOT EXISTS trg_automatic_job_share_evidence_no_update
                BEFORE UPDATE ON automatic_job_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_automatic_job_share_evidence'); END;
            CREATE TRIGGER IF NOT EXISTS trg_automatic_job_share_evidence_no_delete
                BEFORE DELETE ON automatic_job_share_evidence
                BEGIN SELECT RAISE(ABORT,'immutable_automatic_job_share_evidence'); END;

            CREATE TABLE IF NOT EXISTS managed_source_leases (
                lease_id TEXT PRIMARY KEY,
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                consumer_kind TEXT NOT NULL CHECK(consumer_kind IN (
                    'scan','plan','save','worker'
                )),
                consumer_id TEXT NOT NULL,
                owner_id TEXT NOT NULL,
                daemon_generation INTEGER NOT NULL CHECK(daemon_generation>=0),
                created_at TEXT NOT NULL,
                UNIQUE(share_id,consumer_kind,consumer_id)
            );
            CREATE INDEX IF NOT EXISTS ix_managed_source_leases_share
                ON managed_source_leases(share_id COLLATE NOCASE,created_at);
            """,
        )
        db.execute("UPDATE metadata SET value='31' WHERE key='schema_version'")

    def _migrate_v31_to_v32(self, db: sqlite3.Connection) -> None:
        """Separate stable library selection from refreshable current evidence."""

        self._execute_sql_batch(
            db,
            """
            DROP TRIGGER IF EXISTS trg_library_share_binding_evidence_no_update;
            DROP TRIGGER IF EXISTS trg_library_share_binding_evidence_no_delete;
            DROP TRIGGER IF EXISTS trg_job_plan_share_evidence_no_delete;
            DROP TRIGGER IF EXISTS trg_automatic_job_share_evidence_no_delete;

            CREATE TRIGGER IF NOT EXISTS trg_job_plan_share_evidence_no_delete
                BEFORE DELETE ON job_plan_share_evidence
                WHEN lto_expired_plan_cleanup_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'immutable_job_plan_share_evidence'
                ); END;
            CREATE TRIGGER IF NOT EXISTS trg_automatic_job_share_evidence_no_delete
                BEFORE DELETE ON automatic_job_share_evidence
                WHEN lto_job_delete_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_job_share_evidence'
                ); END;

            CREATE TABLE IF NOT EXISTS automatic_cassette_share_evidence (
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                library_id TEXT NOT NULL COLLATE NOCASE REFERENCES libraries(id),
                creation_plan_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES job_plan_drafts(id),
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                evidence_json TEXT NOT NULL,
                evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64),
                admitted_at TEXT NOT NULL,
                PRIMARY KEY(job_id,cassette_sequence,library_id,creation_plan_id),
                FOREIGN KEY(job_id,cassette_sequence)
                    REFERENCES automatic_cassettes(job_id,sequence)
            );
            CREATE TRIGGER IF NOT EXISTS trg_automatic_cassette_share_evidence_no_update
                BEFORE UPDATE ON automatic_cassette_share_evidence
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_cassette_share_evidence'
                ); END;
            CREATE TRIGGER IF NOT EXISTS trg_automatic_cassette_share_evidence_no_delete
                BEFORE DELETE ON automatic_cassette_share_evidence
                WHEN lto_job_delete_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_cassette_share_evidence'
                ); END;

            CREATE TABLE IF NOT EXISTS automatic_cassette_share_evidence_sets (
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                creation_plan_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES job_plan_drafts(id),
                admitted_at TEXT NOT NULL,
                PRIMARY KEY(job_id,cassette_sequence,creation_plan_id),
                FOREIGN KEY(job_id,cassette_sequence)
                    REFERENCES automatic_cassettes(job_id,sequence)
            );
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_cassette_share_evidence_sets_no_update
                BEFORE UPDATE ON automatic_cassette_share_evidence_sets
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_cassette_share_evidence_set'
                ); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_cassette_share_evidence_sets_no_delete
                BEFORE DELETE ON automatic_cassette_share_evidence_sets
                WHEN lto_job_delete_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_cassette_share_evidence_set'
                ); END;

            CREATE TABLE IF NOT EXISTS managed_source_job_fences (
                job_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES automatic_jobs(id),
                reason TEXT NOT NULL CHECK(
                    reason='legacy_managed_source_evidence_missing'
                ),
                fenced_at TEXT NOT NULL
            );
            CREATE TRIGGER IF NOT EXISTS trg_managed_source_job_fences_no_update
                BEFORE UPDATE ON managed_source_job_fences
                BEGIN SELECT RAISE(
                    ABORT,'immutable_managed_source_job_fence'
                ); END;
            CREATE TRIGGER IF NOT EXISTS trg_managed_source_job_fences_no_delete
                BEFORE DELETE ON managed_source_job_fences
                WHEN lto_job_delete_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'immutable_managed_source_job_fence'
                ); END;

            CREATE TABLE IF NOT EXISTS deleted_automatic_job_tombstones (
                job_id TEXT PRIMARY KEY COLLATE NOCASE
                    REFERENCES automatic_jobs(id),
                deleted_at TEXT NOT NULL
            );
            CREATE TRIGGER IF NOT EXISTS trg_deleted_automatic_job_tombstones_no_update
                BEFORE UPDATE ON deleted_automatic_job_tombstones
                BEGIN SELECT RAISE(
                    ABORT,'immutable_deleted_automatic_job_tombstone'
                ); END;
            CREATE TRIGGER IF NOT EXISTS trg_deleted_automatic_job_tombstones_no_delete
                BEFORE DELETE ON deleted_automatic_job_tombstones
                BEGIN SELECT RAISE(
                    ABORT,'immutable_deleted_automatic_job_tombstone'
                ); END;

            INSERT OR IGNORE INTO managed_source_job_fences(job_id,reason,fenced_at)
            SELECT job.id,'legacy_managed_source_evidence_missing',
                strftime('%Y-%m-%dT%H:%M:%fZ','now')
            FROM automatic_jobs AS job
            WHERE EXISTS(
                SELECT 1
                FROM automatic_job_libraries AS link
                JOIN libraries AS library
                    ON library.id=link.library_id COLLATE NOCASE
                WHERE link.job_id=job.id COLLATE NOCASE
                  AND library.source_kind='network'
            ) AND (
                EXISTS(
                    SELECT 1
                    FROM automatic_job_libraries AS link
                    JOIN libraries AS library
                        ON library.id=link.library_id COLLATE NOCASE
                    LEFT JOIN automatic_job_share_evidence AS evidence
                        ON evidence.job_id=link.job_id COLLATE NOCASE
                       AND evidence.library_id=link.library_id COLLATE NOCASE
                    WHERE link.job_id=job.id COLLATE NOCASE
                      AND library.source_kind='network'
                      AND evidence.library_id IS NULL
                ) OR EXISTS(
                    SELECT 1
                    FROM automatic_job_share_evidence AS evidence
                    LEFT JOIN automatic_job_libraries AS link
                        ON link.job_id=evidence.job_id COLLATE NOCASE
                       AND link.library_id=evidence.library_id COLLATE NOCASE
                    LEFT JOIN libraries AS library
                        ON library.id=link.library_id COLLATE NOCASE
                       AND library.source_kind='network'
                    WHERE evidence.job_id=job.id COLLATE NOCASE
                      AND library.id IS NULL
                )
            );

            INSERT OR IGNORE INTO automatic_cassette_share_evidence(
                job_id,cassette_sequence,library_id,creation_plan_id,share_id,
                evidence_json,evidence_sha256,admitted_at
            )
            SELECT cassette.job_id,cassette.sequence,evidence.library_id,
                evidence.creation_plan_id,evidence.share_id,evidence.evidence_json,
                evidence.evidence_sha256,evidence.admitted_at
            FROM automatic_cassettes AS cassette
            JOIN automatic_job_share_evidence AS evidence
                ON evidence.job_id=cassette.job_id
            WHERE EXISTS(
                SELECT 1 FROM automatic_cassette_items AS item
                WHERE item.job_id=cassette.job_id
                  AND item.sequence=cassette.sequence
                  AND item.library_id=evidence.library_id COLLATE NOCASE
            );

            INSERT OR IGNORE INTO automatic_cassette_share_evidence_sets(
                job_id,cassette_sequence,creation_plan_id,admitted_at
            )
            SELECT cassette.job_id,cassette.sequence,evidence.creation_plan_id,
                MIN(evidence.admitted_at)
            FROM automatic_cassettes AS cassette
            JOIN automatic_job_share_evidence AS evidence
                ON evidence.job_id=cassette.job_id
            GROUP BY cassette.job_id,cassette.sequence,evidence.creation_plan_id;
            """,
        )
        db.execute("UPDATE metadata SET value='32' WHERE key='schema_version'")

    def _migrate_v32_to_v33(self, db: sqlite3.Connection) -> None:
        """Add the immutable automatic-recovery attempt event ledger."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS recovery_attempt_events (
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                attempt_number INTEGER NOT NULL CHECK(attempt_number>0),
                event_sequence INTEGER NOT NULL CHECK(event_sequence IN (1,2)),
                job_id TEXT,
                cassette_sequence INTEGER CHECK(cassette_sequence>0),
                cassette_label TEXT,
                trigger TEXT NOT NULL CHECK(length(trigger) BETWEEN 1 AND 128),
                evidence_sha256 TEXT NOT NULL CHECK(
                    length(evidence_sha256)=64
                    AND evidence_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                decision TEXT NOT NULL CHECK(decision IN (
                    'wait_for_media','retry_identification','reconcile_commands',
                    'reconcile_commit','retry_unload','retry_current_cassette',
                    'prepare_restore_retry','reconcile_restore_commit',
                    'finalize_restore_control',
                    'enter_critical_quarantine'
                )),
                state TEXT NOT NULL CHECK(state IN (
                    'started','succeeded','waiting_media','retry_scheduled',
                    'critical_quarantine','failed_safe'
                )),
                daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),
                recorded_at TEXT NOT NULL,
                next_eligible_at TEXT,
                PRIMARY KEY(operation_id,attempt_number,event_sequence),
                CHECK(
                    (event_sequence=1 AND state='started'
                        AND next_eligible_at IS NULL)
                    OR (event_sequence=2 AND state!='started')
                ),
                CHECK(
                    (state='retry_scheduled' AND next_eligible_at IS NOT NULL)
                    OR (state!='retry_scheduled' AND next_eligible_at IS NULL)
                ),
                CHECK(
                    (job_id IS NULL AND cassette_sequence IS NULL
                        AND cassette_label IS NULL)
                    OR (job_id IS NOT NULL AND cassette_sequence IS NULL
                        AND cassette_label IS NULL)
                    OR (job_id IS NOT NULL AND cassette_sequence IS NOT NULL
                        AND cassette_label IS NOT NULL)
                )
            );
            CREATE INDEX IF NOT EXISTS ix_recovery_attempt_events_recorded
                ON recovery_attempt_events(operation_id,attempt_number,event_sequence);
            CREATE TRIGGER IF NOT EXISTS
                trg_recovery_attempt_events_outcome_requires_start
                BEFORE INSERT ON recovery_attempt_events
                WHEN NEW.event_sequence=2 AND NOT EXISTS(
                    SELECT 1 FROM recovery_attempt_events AS started
                    WHERE started.operation_id=NEW.operation_id
                      AND started.attempt_number=NEW.attempt_number
                      AND started.event_sequence=1
                      AND started.job_id IS NEW.job_id
                      AND started.cassette_sequence IS NEW.cassette_sequence
                      AND started.cassette_label IS NEW.cassette_label
                      AND started.trigger=NEW.trigger
                )
                BEGIN SELECT RAISE(
                    ABORT,'recovery_attempt_start_identity_required'
                ); END;
            CREATE TRIGGER IF NOT EXISTS trg_recovery_attempt_events_no_update
                BEFORE UPDATE ON recovery_attempt_events
                BEGIN SELECT RAISE(ABORT,'immutable_recovery_attempt_event'); END;
            CREATE TRIGGER IF NOT EXISTS trg_recovery_attempt_events_no_delete
                BEFORE DELETE ON recovery_attempt_events
                BEGIN SELECT RAISE(ABORT,'immutable_recovery_attempt_event'); END;
            """,
        )
        db.execute("UPDATE metadata SET value='33' WHERE key='schema_version'")

    def _migrate_v33_to_v34(self, db: sqlite3.Connection) -> None:
        """Bind each APPEND block to its exact native operation checkpoint."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS automatic_operation_blocks (
                block_id TEXT PRIMARY KEY REFERENCES blocks(id),
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                created_at TEXT NOT NULL,
                FOREIGN KEY(job_id,cassette_sequence)
                    REFERENCES automatic_cassettes(job_id,sequence)
            );
            CREATE INDEX IF NOT EXISTS ix_automatic_operation_blocks_operation
                ON automatic_operation_blocks(operation_id,block_id);
            CREATE TRIGGER IF NOT EXISTS trg_automatic_operation_blocks_no_update
                BEFORE UPDATE ON automatic_operation_blocks
                BEGIN SELECT RAISE(ABORT,'immutable_automatic_operation_block'); END;
            CREATE TABLE IF NOT EXISTS native_recovery_dispatches (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                owner_generation INTEGER NOT NULL CHECK(owner_generation>0),
                state TEXT NOT NULL CHECK(state IN ('admitted','started','finished')),
                admitted_at TEXT NOT NULL,
                started_at TEXT,
                finished_at TEXT,
                CHECK(
                    (state='admitted' AND started_at IS NULL AND finished_at IS NULL)
                    OR (state='started' AND started_at IS NOT NULL
                        AND finished_at IS NULL)
                    OR (state='finished' AND started_at IS NOT NULL
                        AND finished_at IS NOT NULL)
                )
            );
            """,
        )
        self._maintain_schema_34_operation_block_lifecycle(db)
        db.execute("UPDATE metadata SET value='34' WHERE key='schema_version'")

    def _migrate_v34_to_v35(self, db: sqlite3.Connection) -> None:
        """Add daemon-fenced incremental policy and immutable layout history."""
        if db.execute("PRAGMA foreign_key_check").fetchall():
            raise CatalogError("schema35 source foreign key check failed")
        self._rebuild_schema_35_cassette_segments(db)
        self._rebuild_schema_35_job_policy_snapshots(db)
        # Backfilling the new physical path is part of this one atomic
        # migration.  Temporarily remove only the update guard and restore it
        # before the transaction can commit; ordinary callers never observe a
        # mutable ready plan.
        db.execute("DROP TRIGGER IF EXISTS job_plan_items_immutable_update")
        db.execute("DROP TRIGGER IF EXISTS freeze_imported_cassette_item_update")
        for table in (
            "job_plan_items",
            "automatic_cassette_items",
            "job_manifest_history",
        ):
            columns = {
                str(row["name"])
                for row in db.execute(f"PRAGMA table_info({table})")
            }
            if "tape_relative_path" not in columns:
                db.execute(
                    f"ALTER TABLE {table} ADD COLUMN tape_relative_path TEXT "
                    "NOT NULL DEFAULT ''"
                )
            rows = db.execute(
                f"SELECT rowid,relative_path,tape_relative_path FROM {table}"
            ).fetchall()
            for row in rows:
                frozen_path = str(row["tape_relative_path"])
                if not frozen_path:
                    frozen_path = ltfs_tape_relative_path(str(row["relative_path"]))
                    db.execute(
                        f"UPDATE {table} SET tape_relative_path=? WHERE rowid=?",
                        (frozen_path, row["rowid"]),
                    )
                self._validate_portable_relative_path(
                    frozen_path, "frozen tape relative path"
                )
        self._execute_sql_batch(
            db,
            """
            CREATE TRIGGER job_plan_items_immutable_update
            BEFORE UPDATE ON job_plan_items
            BEGIN
                SELECT RAISE(ABORT, 'job plan manifest is immutable');
            END;
            """,
        )
        self._install_imported_job_freeze_triggers(db)
        self._maintain_schema_35_incremental_jobs(db)
        now = self._precise_utc_now()
        db.execute(
            "INSERT OR IGNORE INTO job_incremental_policies("
            "job_id,cadence,next_eligible_at,last_attempt_at,last_success_at,"
            "last_outcome,revision,updated_at) "
            "SELECT job.id,'off',NULL,NULL,NULL,NULL,1,? FROM automatic_jobs job "
            "WHERE NOT EXISTS(SELECT 1 FROM imported_job_policies imported "
            "WHERE imported.job_id=job.id COLLATE NOCASE)", (now,),
        )
        rows = db.execute(
            "SELECT job.id,state.creation_plan_id FROM automatic_jobs job "
            "JOIN job_management_state state ON state.job_id=job.id "
            "WHERE NOT EXISTS(SELECT 1 FROM imported_job_policies imported "
            "WHERE imported.job_id=job.id COLLATE NOCASE) "
            "AND NOT EXISTS(SELECT 1 FROM job_layout_epochs epoch "
            "WHERE epoch.job_id=job.id COLLATE NOCASE) ORDER BY job.id"
        ).fetchall()
        for row in rows:
            plan_id = row["creation_plan_id"]
            plan = None if plan_id is None else db.execute(
                "SELECT digest_sha256 FROM job_plan_drafts WHERE id=?", (plan_id,)
            ).fetchone()
            digest = "0" * 64 if plan is None or plan["digest_sha256"] is None else str(plan["digest_sha256"])
            self._insert_layout_epoch_tx(
                db, str(row["id"]), kind="initial",
                plan_id=None if plan_id is None else str(plan_id),
                plan_digest_sha256=digest, created_at=now,
            )
        violations = db.execute("PRAGMA foreign_key_check").fetchall()
        if violations:
            raise CatalogError("schema35 foreign key check failed")
        db.execute("UPDATE metadata SET value='35' WHERE key='schema_version'")

    def _migrate_v35_to_v36(self, db: sqlite3.Connection) -> None:
        """Persist exact native format authority without inferring legacy consent."""

        self._maintain_schema_36_unattended_sequences(db)
        if db.execute("PRAGMA foreign_key_check").fetchall():
            raise CatalogError("schema36 foreign key check failed")
        db.execute("UPDATE metadata SET value='36' WHERE key='schema_version'")

    def _migrate_v36_to_v37(self, db: sqlite3.Connection) -> None:
        """Permit immutable authority history across layout epochs."""

        self._execute_sql_batch(
            db,
            """
            DROP TRIGGER IF EXISTS trg_automatic_format_authorizations_no_update;
            DROP TRIGGER IF EXISTS trg_automatic_format_authorizations_no_delete;
            DROP TRIGGER IF EXISTS trg_operation_format_authorizations_no_update;
            DROP TRIGGER IF EXISTS trg_operation_format_authorizations_no_delete;
            CREATE TABLE automatic_format_authorizations_v37 (
                authorization_id TEXT PRIMARY KEY,
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence > 0),
                layout_epoch INTEGER NOT NULL CHECK(layout_epoch > 0),
                layout_fingerprint_sha256 TEXT NOT NULL CHECK(length(layout_fingerprint_sha256)=64),
                expected_label TEXT NOT NULL CHECK(length(expected_label)=6),
                expected_operation TEXT NOT NULL CHECK(expected_operation='format'),
                reuse_registered INTEGER NOT NULL CHECK(reuse_registered IN (0,1)),
                authorized_by TEXT NOT NULL,
                authorized_at TEXT NOT NULL,
                request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                UNIQUE(job_id,cassette_sequence,expected_label,layout_epoch),
                FOREIGN KEY(job_id,cassette_sequence)
                  REFERENCES automatic_cassettes(job_id,sequence),
                FOREIGN KEY(job_id,layout_epoch)
                  REFERENCES job_layout_epochs(job_id,epoch_number)
            );
            INSERT INTO automatic_format_authorizations_v37
                SELECT * FROM automatic_format_authorizations;
            CREATE TABLE operation_format_authorizations_v37 (
                operation_id TEXT PRIMARY KEY REFERENCES format_confirmations(operation_id),
                authorization_id TEXT NOT NULL REFERENCES automatic_format_authorizations_v37(authorization_id),
                linked_at TEXT NOT NULL
            );
            INSERT INTO operation_format_authorizations_v37
                SELECT * FROM operation_format_authorizations;
            DROP TABLE operation_format_authorizations;
            DROP TABLE automatic_format_authorizations;
            ALTER TABLE automatic_format_authorizations_v37
                RENAME TO automatic_format_authorizations;
            ALTER TABLE operation_format_authorizations_v37
                RENAME TO operation_format_authorizations;
            """,
        )
        self._maintain_schema_36_unattended_sequences(db)
        if db.execute("PRAGMA foreign_key_check").fetchall():
            raise CatalogError("schema37 foreign key check failed")
        db.execute("UPDATE metadata SET value='37' WHERE key='schema_version'")

