    def _migrate_v40_to_v41(self, db: sqlite3.Connection) -> None:
        """Store dedicated source change-time and future-plan scan policy."""

        version_columns = {
            row["name"] for row in db.execute("PRAGMA table_info(file_versions)")
        }
        if "source_change_ns" not in version_columns:
            db.execute(
                "ALTER TABLE file_versions ADD COLUMN source_change_ns INTEGER "
                "CHECK(source_change_ns>0)"
            )
        setting_columns = {
            row["name"] for row in db.execute("PRAGMA table_info(application_settings)")
        }
        if "source_change_detection_policy" not in setting_columns:
            db.execute(
                "ALTER TABLE application_settings ADD COLUMN "
                "source_change_detection_policy TEXT NOT NULL DEFAULT 'size_mtime_change' "
                "CHECK(source_change_detection_policy IN ('size_mtime','size_mtime_change'))"
            )
        if db.execute("PRAGMA foreign_key_check").fetchall():
            raise CatalogError("schema41 foreign key check failed")
        db.execute("UPDATE metadata SET value='41' WHERE key='schema_version'")

    @staticmethod
    def _maintain_schema_40_command_exit_codes(db: sqlite3.Connection) -> None:
        columns = {
            str(row["name"])
            for row in db.execute("PRAGMA table_info(hardware_command_executions)")
        }
        if "terminal_exit_code" not in columns:
            db.execute(
                "ALTER TABLE hardware_command_executions "
                "ADD COLUMN terminal_exit_code INTEGER"
            )
        db.execute(
            """
            CREATE TABLE IF NOT EXISTS qualification_readback_release_receipts (
                operation_id TEXT PRIMARY KEY NOT NULL
                    REFERENCES daemon_operations(id),
                owner_generation INTEGER NOT NULL,
                unload_command_id TEXT NOT NULL
                    REFERENCES hardware_command_executions(id),
                probe_command_id TEXT NOT NULL
                    REFERENCES hardware_command_executions(id),
                release_receipt_sha256 TEXT NOT NULL
                    CHECK(length(release_receipt_sha256)=64),
                recorded_at TEXT NOT NULL
            )
            """
        )
        db.execute(
            """
            CREATE TRIGGER IF NOT EXISTS qualification_readback_release_immutable
            BEFORE UPDATE ON qualification_readback_release_receipts
            BEGIN
                SELECT RAISE(ABORT, 'qualification readback release is immutable');
            END
            """
        )
        db.execute(
            """
            CREATE TRIGGER IF NOT EXISTS qualification_readback_release_no_delete
            BEFORE DELETE ON qualification_readback_release_receipts
            BEGIN
                SELECT RAISE(ABORT, 'qualification readback release is immutable');
            END
            """
        )

    def _maintain_schema_39_restore_destinations(
        self, db: sqlite3.Connection
    ) -> None:
        """Persist a closed restore-destination snapshot for every restore plan."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS restore_plan_destinations (
                plan_id TEXT PRIMARY KEY
                    REFERENCES restore_plans(id) ON DELETE RESTRICT,
                destination_state TEXT NOT NULL
                    CHECK(destination_state IN ('exact','legacy_invalid')),
                kind TEXT CHECK(kind IS NULL OR kind='local'),
                root TEXT,
                anchor TEXT,
                invalidation_reason TEXT CHECK(
                    invalidation_reason IS NULL OR
                    invalidation_reason='legacy_destination_snapshot_missing'
                ),
                CHECK(
                    (
                        destination_state='exact' AND kind='local'
                        AND root IS NOT NULL AND anchor IS NOT NULL
                        AND invalidation_reason IS NULL
                        AND length(root) BETWEEN 1 AND 4096
                        AND length(anchor) BETWEEN 1 AND 4096
                        AND instr(root,char(0))=0
                        AND instr(anchor,char(0))=0
                        AND substr(root,1,1)='/'
                        AND substr(anchor,1,1)='/'
                        AND root NOT GLOB '*//*'
                        AND anchor NOT GLOB '*//*'
                        AND root NOT GLOB '*/./*'
                        AND anchor NOT GLOB '*/./*'
                        AND root NOT GLOB '*/.'
                        AND anchor NOT GLOB '*/.'
                        AND root NOT GLOB '*/../*'
                        AND anchor NOT GLOB '*/../*'
                        AND root NOT GLOB '*/..'
                        AND anchor NOT GLOB '*/..'
                        AND (root='/' OR root NOT GLOB '*/')
                        AND (anchor='/' OR anchor NOT GLOB '*/')
                        AND (
                            anchor='/' OR root=anchor OR (
                                substr(root,1,length(anchor))=anchor
                                AND substr(root,length(anchor)+1,1)='/'
                            )
                        )
                    ) OR (
                        destination_state='legacy_invalid' AND kind IS NULL
                        AND root IS NULL AND anchor IS NULL
                        AND invalidation_reason='legacy_destination_snapshot_missing'
                    )
                )
            );
            CREATE TRIGGER IF NOT EXISTS restore_plan_destinations_immutable_update
            BEFORE UPDATE ON restore_plan_destinations
            BEGIN SELECT RAISE(ABORT,'restore plan destination is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plan_destinations_immutable_delete
            BEFORE DELETE ON restore_plan_destinations
            BEGIN SELECT RAISE(ABORT,'restore plan destination is immutable'); END;
            """,
        )
        from .migration.validator import (
            _schema_39_restore_destination_table_matches,
            _trigger_matches_contract,
        )

        table = db.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' "
            "AND name='restore_plan_destinations'"
        ).fetchone()
        triggers = {
            str(row[0]).casefold(): str(row[1] or "")
            for row in db.execute(
                "SELECT name,sql FROM sqlite_master WHERE type='trigger' "
                "AND tbl_name='restore_plan_destinations'"
            )
        }
        if (
            table is None
            or not _schema_39_restore_destination_table_matches(str(table[0]))
            or not _trigger_matches_contract(
                triggers.get("restore_plan_destinations_immutable_update", ""),
                name="restore_plan_destinations_immutable_update",
                table="restore_plan_destinations",
                timing="before",
                event="update",
                marker="restore plan destination is immutable",
            )
            or not _trigger_matches_contract(
                triggers.get("restore_plan_destinations_immutable_delete", ""),
                name="restore_plan_destinations_immutable_delete",
                table="restore_plan_destinations",
                timing="before",
                event="delete",
                marker="restore plan destination is immutable",
            )
        ):
            raise CatalogError("schema39 restore destination schema is invalid")
        db.execute(
            "INSERT OR IGNORE INTO restore_plan_destinations("
            "plan_id,destination_state,kind,root,anchor,invalidation_reason) "
            "SELECT id,'legacy_invalid',NULL,NULL,NULL,"
            "'legacy_destination_snapshot_missing' FROM restore_plans"
        )
        receipts = db.execute(
            "SELECT actor,idempotency_key,response_json FROM management_idempotency "
            "WHERE action='restore.plan.create' "
            "AND target_id='restore-plans' COLLATE NOCASE"
        ).fetchall()
        for receipt in receipts:
            try:
                plan_id = json.loads(receipt["response_json"])["id"]
            except (KeyError, TypeError, ValueError):
                continue
            plan = db.execute(
                "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
            ).fetchone()
            if plan is None:
                continue
            destination = db.execute(
                "SELECT * FROM restore_plan_destinations WHERE plan_id=?", (plan_id,)
            ).fetchone()
            cassettes = db.execute(
                "SELECT * FROM restore_plan_cassettes WHERE plan_id=? ORDER BY sequence",
                (plan_id,),
            ).fetchall()
            items = db.execute(
                "SELECT * FROM restore_plan_items WHERE plan_id=? ORDER BY sequence",
                (plan_id,),
            ).fetchall()
            db.execute(
                "UPDATE management_idempotency SET response_json=? "
                "WHERE actor=? AND idempotency_key=?",
                (
                    json.dumps(
                        self._restore_plan_mapping(
                            plan, cassettes, items, destination=destination
                        ),
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                    receipt["actor"],
                    receipt["idempotency_key"],
                ),
            )

    def _maintain_schema_39_restore_recovery_actions(
        self, db: sqlite3.Connection
    ) -> None:
        """Expand the immutable recovery ledger for typed restore dispositions."""

        schema = db.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' "
            "AND name='recovery_attempt_events'"
        ).fetchone()
        if schema is None or "finalize_restore_control" in str(schema["sql"]):
            return
        self._execute_sql_batch(
            db,
            """
            ALTER TABLE recovery_attempt_events
                RENAME TO recovery_attempt_events_restore_legacy;
            CREATE TABLE recovery_attempt_events (
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                attempt_number INTEGER NOT NULL CHECK(attempt_number>0),
                event_sequence INTEGER NOT NULL CHECK(event_sequence IN (1,2)),
                job_id TEXT,
                cassette_sequence INTEGER CHECK(cassette_sequence>0),
                cassette_label TEXT,
                trigger TEXT NOT NULL CHECK(length(trigger) BETWEEN 1 AND 128),
                evidence_sha256 TEXT NOT NULL CHECK(
                    length(evidence_sha256)=64
                    AND evidence_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                decision TEXT NOT NULL CHECK(decision IN (
                    'wait_for_media','retry_identification','reconcile_commands',
                    'reconcile_commit','retry_unload','retry_current_cassette',
                    'prepare_restore_retry','reconcile_restore_commit',
                    'finalize_restore_control','enter_critical_quarantine'
                )),
                state TEXT NOT NULL CHECK(state IN (
                    'started','succeeded','waiting_media','retry_scheduled',
                    'critical_quarantine','failed_safe'
                )),
                daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),
                recorded_at TEXT NOT NULL,
                next_eligible_at TEXT,
                PRIMARY KEY(operation_id,attempt_number,event_sequence),
                CHECK(
                    (event_sequence=1 AND state='started' AND next_eligible_at IS NULL)
                    OR (event_sequence=2 AND state!='started')
                ),
                CHECK(
                    (state='retry_scheduled' AND next_eligible_at IS NOT NULL)
                    OR (state!='retry_scheduled' AND next_eligible_at IS NULL)
                ),
                CHECK(
                    (job_id IS NULL AND cassette_sequence IS NULL AND cassette_label IS NULL)
                    OR (job_id IS NOT NULL AND cassette_sequence IS NULL AND cassette_label IS NULL)
                    OR (job_id IS NOT NULL AND cassette_sequence IS NOT NULL
                        AND cassette_label IS NOT NULL)
                )
            );
            INSERT INTO recovery_attempt_events
                SELECT * FROM recovery_attempt_events_restore_legacy;
            DROP TABLE recovery_attempt_events_restore_legacy;
            CREATE INDEX ix_recovery_attempt_events_recorded
                ON recovery_attempt_events(operation_id,attempt_number,event_sequence);
            CREATE TRIGGER trg_recovery_attempt_events_outcome_requires_start
                BEFORE INSERT ON recovery_attempt_events
                WHEN NEW.event_sequence=2 AND NOT EXISTS(
                    SELECT 1 FROM recovery_attempt_events AS started
                    WHERE started.operation_id=NEW.operation_id
                      AND started.attempt_number=NEW.attempt_number
                      AND started.event_sequence=1
                      AND started.job_id IS NEW.job_id
                      AND started.cassette_sequence IS NEW.cassette_sequence
                      AND started.cassette_label IS NEW.cassette_label
                      AND started.trigger=NEW.trigger
                )
                BEGIN SELECT RAISE(
                    ABORT,'recovery_attempt_start_identity_required'
                ); END;
            CREATE TRIGGER trg_recovery_attempt_events_no_update
                BEFORE UPDATE ON recovery_attempt_events
                BEGIN SELECT RAISE(ABORT,'immutable_recovery_attempt_event'); END;
            CREATE TRIGGER trg_recovery_attempt_events_no_delete
                BEFORE DELETE ON recovery_attempt_events
                BEGIN SELECT RAISE(ABORT,'immutable_recovery_attempt_event'); END;
            """,
        )

    def _maintain_schema_39_restore_runs(self, db: sqlite3.Connection) -> None:
        """Maintain schema-39 restore execution without mutating frozen plan data."""

        cassette_columns = {
            str(row["name"])
            for row in db.execute("PRAGMA table_info(restore_plan_cassettes)")
        }
        added_identity = {
            column
            for column in ("volume_serial", "volume_uuid")
            if column not in cassette_columns
        }
        required_schema_objects = {
            "restore_runs",
            "restore_run_cassettes",
            "restore_run_items",
            "restore_item_conflicts",
            "restore_replacement_authorizations",
            "restore_release_receipts",
            "restore_retry_preparations",
            "ux_restore_one_active_run_per_plan",
            "ux_restore_item_one_open_conflict",
            "restore_runs_immutable_identity",
            "restore_runs_no_delete",
            "restore_run_cassettes_immutable_identity",
            "restore_run_cassettes_no_delete",
            "restore_run_items_immutable_identity",
            "restore_run_items_no_delete",
            "restore_item_conflicts_immutable_binding",
            "restore_item_conflicts_no_delete",
            "restore_replacement_authorizations_immutable_binding",
            "restore_replacement_authorizations_no_delete",
            "restore_release_receipts_no_update",
            "restore_release_receipts_no_delete",
            "restore_retry_preparations_no_update",
            "restore_retry_preparations_no_delete",
        }
        existing_schema_objects = {
            str(row["name"])
            for row in db.execute(
                "SELECT name FROM sqlite_master WHERE name IN ("
                + ",".join("?" for _ in required_schema_objects)
                + ")",
                tuple(sorted(required_schema_objects)),
            )
        }
        if not added_identity and existing_schema_objects == required_schema_objects:
            return
        if added_identity:
            db.execute("DROP TRIGGER IF EXISTS restore_plan_cassettes_immutable_update")
            if "volume_serial" in added_identity:
                db.execute(
                    "ALTER TABLE restore_plan_cassettes ADD COLUMN volume_serial TEXT "
                    "CHECK(volume_serial IS NULL OR length(volume_serial) BETWEEN 1 AND 255)"
                )
            if "volume_uuid" in added_identity:
                db.execute(
                    "ALTER TABLE restore_plan_cassettes ADD COLUMN volume_uuid TEXT "
                    "CHECK(volume_uuid IS NULL OR length(volume_uuid)=36)"
                )
            db.execute(
                "UPDATE restore_plan_cassettes SET volume_serial=("
                "SELECT tape.volume_serial FROM tapes AS tape "
                "WHERE tape.id=restore_plan_cassettes.tape_id) "
                "WHERE volume_serial IS NULL"
            )
            db.execute(
                "UPDATE restore_plan_cassettes SET volume_uuid=("
                "SELECT MIN(receipt.volume_uuid) "
                "FROM ltfs_terminal_receipts AS receipt "
                "JOIN automatic_cassettes AS cassette "
                "ON cassette.job_id=receipt.job_id AND cassette.sequence=receipt.sequence "
                "WHERE cassette.tape_id=restore_plan_cassettes.tape_id "
                "AND cassette.status='completed' "
                "GROUP BY cassette.tape_id "
                "HAVING COUNT(DISTINCT lower(receipt.volume_uuid))=1) "
                "WHERE volume_uuid IS NULL"
            )
            db.execute(
                "CREATE TRIGGER restore_plan_cassettes_immutable_update "
                "BEFORE UPDATE ON restore_plan_cassettes "
                "BEGIN SELECT RAISE(ABORT,'restore plan cassette is immutable'); END"
            )

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS restore_runs (
                id TEXT PRIMARY KEY,
                plan_id TEXT NOT NULL REFERENCES restore_plans(id) ON DELETE RESTRICT,
                actor TEXT NOT NULL,
                state TEXT NOT NULL CHECK(state IN (
                    'planned','waiting_media','restoring','paused','completed',
                    'cancelled','failed','recovery_required'
                )),
                current_cassette_sequence INTEGER
                    CHECK(current_cassette_sequence BETWEEN 1 AND 200),
                request_sha256 TEXT NOT NULL CHECK(
                    length(request_sha256)=64
                    AND request_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                plan_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(plan_fingerprint_sha256)=64
                        AND plan_fingerprint_sha256 NOT GLOB '*[^0-9a-f]*'),
                total_files INTEGER NOT NULL CHECK(total_files BETWEEN 1 AND 200),
                total_bytes INTEGER NOT NULL CHECK(total_bytes>=0),
                restored_files INTEGER NOT NULL DEFAULT 0 CHECK(restored_files>=0),
                skipped_files INTEGER NOT NULL DEFAULT 0 CHECK(skipped_files>=0),
                failed_files INTEGER NOT NULL DEFAULT 0 CHECK(failed_files>=0),
                copied_bytes INTEGER NOT NULL DEFAULT 0 CHECK(copied_bytes>=0),
                created_at TEXT NOT NULL,
                started_at TEXT,
                completed_at TEXT,
                last_error_code TEXT CHECK(
                    last_error_code IS NULL OR length(last_error_code) BETWEEN 1 AND 64
                ),
                UNIQUE(id,plan_id),
                CHECK(restored_files+skipped_files+failed_files<=total_files),
                CHECK(copied_bytes<=total_bytes),
                CHECK(
                    (state IN ('completed','cancelled','failed') AND completed_at IS NOT NULL)
                    OR (state NOT IN ('completed','cancelled','failed') AND completed_at IS NULL)
                )
            );
            CREATE UNIQUE INDEX IF NOT EXISTS ux_restore_one_active_run_per_plan
                ON restore_runs(plan_id)
                WHERE state IN (
                    'planned','waiting_media','restoring','paused','recovery_required'
                );
            CREATE TABLE IF NOT EXISTS restore_run_cassettes (
                run_id TEXT NOT NULL,
                plan_id TEXT NOT NULL,
                sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 200),
                plan_cassette_sequence INTEGER NOT NULL
                    CHECK(plan_cassette_sequence BETWEEN 1 AND 200),
                tape_id TEXT NOT NULL,
                cassette_number TEXT NOT NULL,
                physical_label TEXT NOT NULL CHECK(length(physical_label) BETWEEN 1 AND 32),
                volume_label TEXT NOT NULL CHECK(length(volume_label)<=255),
                volume_serial TEXT NOT NULL CHECK(length(volume_serial) BETWEEN 1 AND 255),
                volume_uuid TEXT CHECK(volume_uuid IS NULL OR length(volume_uuid)=36),
                state TEXT NOT NULL CHECK(state IN (
                    'pending','waiting_media','restoring','completed','failed',
                    'recovery_required'
                )),
                item_count INTEGER NOT NULL CHECK(item_count BETWEEN 1 AND 200),
                total_bytes INTEGER NOT NULL CHECK(total_bytes>=0),
                restored_files INTEGER NOT NULL DEFAULT 0 CHECK(restored_files>=0),
                skipped_files INTEGER NOT NULL DEFAULT 0 CHECK(skipped_files>=0),
                failed_files INTEGER NOT NULL DEFAULT 0 CHECK(failed_files>=0),
                copied_bytes INTEGER NOT NULL DEFAULT 0 CHECK(copied_bytes>=0),
                operation_id TEXT REFERENCES daemon_operations(id),
                started_at TEXT,
                completed_at TEXT,
                last_error_code TEXT CHECK(
                    last_error_code IS NULL OR length(last_error_code) BETWEEN 1 AND 64
                ),
                PRIMARY KEY(run_id,sequence),
                UNIQUE(run_id,plan_cassette_sequence),
                FOREIGN KEY(run_id,plan_id)
                    REFERENCES restore_runs(id,plan_id) ON DELETE RESTRICT,
                FOREIGN KEY(plan_id,plan_cassette_sequence)
                    REFERENCES restore_plan_cassettes(plan_id,sequence) ON DELETE RESTRICT,
                CHECK(restored_files+skipped_files+failed_files<=item_count),
                CHECK(copied_bytes<=total_bytes),
                CHECK((state='completed')=(completed_at IS NOT NULL))
            );
            CREATE TABLE IF NOT EXISTS restore_run_items (
                run_id TEXT NOT NULL,
                plan_id TEXT NOT NULL,
                sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 200),
                plan_item_sequence INTEGER NOT NULL CHECK(plan_item_sequence BETWEEN 1 AND 200),
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence BETWEEN 1 AND 200),
                file_version_id INTEGER NOT NULL,
                library_id TEXT NOT NULL,
                relative_path TEXT NOT NULL,
                tape_relative_path TEXT NOT NULL,
                tape_id TEXT NOT NULL,
                cassette_number TEXT NOT NULL,
                physical_label TEXT NOT NULL CHECK(length(physical_label) BETWEEN 1 AND 32),
                volume_label TEXT NOT NULL CHECK(length(volume_label)<=255),
                block_id TEXT NOT NULL,
                size INTEGER NOT NULL CHECK(size>=0),
                sha256 TEXT NOT NULL CHECK(
                    length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                copied_at TEXT NOT NULL,
                is_current INTEGER NOT NULL CHECK(is_current IN (0,1)),
                destination_relative_path TEXT NOT NULL,
                canonical_destination TEXT NOT NULL CHECK(substr(canonical_destination,1,1)='/'),
                state TEXT NOT NULL CHECK(state IN (
                    'pending','restoring','restored','skipped_verified','failed',
                    'recovery_required'
                )),
                bytes_copied INTEGER NOT NULL DEFAULT 0 CHECK(bytes_copied>=0),
                observed_sha256 TEXT CHECK(
                    observed_sha256 IS NULL OR (
                        length(observed_sha256)=64
                        AND observed_sha256 NOT GLOB '*[^0-9a-f]*'
                    )
                ),
                error_code TEXT CHECK(error_code IS NULL OR length(error_code) BETWEEN 1 AND 64),
                started_at TEXT,
                completed_at TEXT,
                PRIMARY KEY(run_id,sequence),
                UNIQUE(run_id,plan_item_sequence),
                FOREIGN KEY(run_id,plan_id)
                    REFERENCES restore_runs(id,plan_id) ON DELETE RESTRICT,
                FOREIGN KEY(run_id,cassette_sequence)
                    REFERENCES restore_run_cassettes(run_id,sequence) ON DELETE RESTRICT,
                FOREIGN KEY(plan_id,plan_item_sequence)
                    REFERENCES restore_plan_items(plan_id,sequence) ON DELETE RESTRICT,
                CHECK(bytes_copied<=size),
                CHECK(
                    (state IN ('restored','skipped_verified','failed') AND completed_at IS NOT NULL)
                    OR (state NOT IN ('restored','skipped_verified','failed') AND completed_at IS NULL)
                )
            );
            CREATE TABLE IF NOT EXISTS restore_item_conflicts (
                id TEXT PRIMARY KEY,
                run_id TEXT NOT NULL,
                item_sequence INTEGER NOT NULL CHECK(item_sequence BETWEEN 1 AND 200),
                conflict_sequence INTEGER NOT NULL CHECK(conflict_sequence>0),
                file_version_id INTEGER NOT NULL,
                canonical_destination TEXT NOT NULL CHECK(substr(canonical_destination,1,1)='/'),
                observed_size INTEGER NOT NULL CHECK(observed_size>=0),
                observed_sha256 TEXT NOT NULL CHECK(
                    length(observed_sha256)=64
                    AND observed_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                state TEXT NOT NULL CHECK(state IN ('recorded','authorized','consumed')),
                authorization_id TEXT,
                recorded_at TEXT NOT NULL,
                authorized_at TEXT,
                consumed_at TEXT,
                UNIQUE(id,run_id,item_sequence),
                UNIQUE(run_id,item_sequence,conflict_sequence),
                FOREIGN KEY(run_id,item_sequence)
                    REFERENCES restore_run_items(run_id,sequence) ON DELETE RESTRICT,
                CHECK(
                    (state='recorded' AND authorization_id IS NULL AND authorized_at IS NULL AND consumed_at IS NULL)
                    OR (state='authorized' AND authorization_id IS NOT NULL AND authorized_at IS NOT NULL AND consumed_at IS NULL)
                    OR (state='consumed' AND authorization_id IS NOT NULL AND authorized_at IS NOT NULL AND consumed_at IS NOT NULL)
                )
            );
            CREATE UNIQUE INDEX IF NOT EXISTS ux_restore_item_one_open_conflict
                ON restore_item_conflicts(run_id,item_sequence)
                WHERE state IN ('recorded','authorized');
            CREATE TABLE IF NOT EXISTS restore_replacement_authorizations (
                id TEXT PRIMARY KEY,
                conflict_id TEXT NOT NULL UNIQUE,
                run_id TEXT NOT NULL,
                item_sequence INTEGER NOT NULL CHECK(item_sequence BETWEEN 1 AND 200),
                file_version_id INTEGER NOT NULL,
                canonical_destination TEXT NOT NULL CHECK(substr(canonical_destination,1,1)='/'),
                observed_size INTEGER NOT NULL CHECK(observed_size>=0),
                observed_sha256 TEXT NOT NULL CHECK(
                    length(observed_sha256)=64
                    AND observed_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                administrator TEXT NOT NULL,
                reauthentication_proof_sha256 TEXT NOT NULL UNIQUE
                    CHECK(length(reauthentication_proof_sha256)=64
                        AND reauthentication_proof_sha256
                            NOT GLOB '*[^0-9a-f]*'),
                request_sha256 TEXT NOT NULL CHECK(
                    length(request_sha256)=64
                    AND request_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                state TEXT NOT NULL CHECK(state IN ('authorized','consumed')),
                authorized_at TEXT NOT NULL,
                consumed_at TEXT,
                consumed_by_operation_id TEXT REFERENCES daemon_operations(id),
                FOREIGN KEY(conflict_id,run_id,item_sequence)
                    REFERENCES restore_item_conflicts(id,run_id,item_sequence)
                        ON DELETE RESTRICT,
                CHECK(
                    (state='authorized' AND consumed_at IS NULL AND consumed_by_operation_id IS NULL)
                    OR (state='consumed' AND consumed_at IS NOT NULL AND consumed_by_operation_id IS NOT NULL)
                )
            );
            CREATE TABLE IF NOT EXISTS restore_release_receipts (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                owner_generation INTEGER NOT NULL CHECK(owner_generation>0),
                run_id TEXT NOT NULL,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence BETWEEN 1 AND 200),
                plan_fingerprint_sha256 TEXT NOT NULL CHECK(
                    length(plan_fingerprint_sha256)=64
                    AND plan_fingerprint_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                boundary TEXT NOT NULL CHECK(boundary IN ('pre_mount','post_eject')),
                item_checkpoint_sha256 TEXT NOT NULL CHECK(
                    length(item_checkpoint_sha256)=64
                    AND item_checkpoint_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                mount_receipt_sha256 TEXT CHECK(
                    mount_receipt_sha256 IS NULL OR length(mount_receipt_sha256)=64
                ),
                unmount_receipt_sha256 TEXT CHECK(
                    unmount_receipt_sha256 IS NULL OR length(unmount_receipt_sha256)=64
                ),
                unload_command_id TEXT REFERENCES hardware_command_executions(id),
                mount_path_sha256 TEXT NOT NULL CHECK(length(mount_path_sha256)=64),
                tape_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(tape_device_identity_sha256)=64),
                scsi_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(scsi_device_identity_sha256)=64),
                expected_media_scope_sha256 TEXT NOT NULL
                    CHECK(length(expected_media_scope_sha256)=64),
                recorded_at TEXT NOT NULL,
                FOREIGN KEY(run_id,cassette_sequence)
                    REFERENCES restore_run_cassettes(run_id,sequence),
                CHECK(
                    (boundary='pre_mount' AND mount_receipt_sha256 IS NULL
                        AND unmount_receipt_sha256 IS NULL AND unload_command_id IS NULL)
                    OR (boundary='post_eject' AND mount_receipt_sha256 IS NOT NULL
                        AND unmount_receipt_sha256 IS NOT NULL AND unload_command_id IS NOT NULL)
                )
            );
            CREATE TABLE IF NOT EXISTS restore_retry_preparations (
                source_operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                resolved_by_generation INTEGER NOT NULL CHECK(resolved_by_generation>0),
                run_id TEXT NOT NULL,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence BETWEEN 1 AND 200),
                plan_fingerprint_sha256 TEXT NOT NULL CHECK(
                    length(plan_fingerprint_sha256)=64
                    AND plan_fingerprint_sha256 NOT GLOB '*[^0-9a-f]*'
                ),
                prepared_at TEXT NOT NULL,
                FOREIGN KEY(run_id,cassette_sequence)
                    REFERENCES restore_run_cassettes(run_id,sequence)
            );
            CREATE TRIGGER IF NOT EXISTS restore_runs_immutable_identity
            BEFORE UPDATE ON restore_runs WHEN
                NEW.id!=OLD.id OR NEW.plan_id!=OLD.plan_id OR NEW.actor!=OLD.actor
                OR NEW.request_sha256!=OLD.request_sha256
                OR NEW.plan_fingerprint_sha256!=OLD.plan_fingerprint_sha256
                OR NEW.total_files!=OLD.total_files OR NEW.total_bytes!=OLD.total_bytes
                OR NEW.created_at!=OLD.created_at
            BEGIN SELECT RAISE(ABORT,'restore run identity is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_runs_no_delete
            BEFORE DELETE ON restore_runs
            BEGIN SELECT RAISE(ABORT,'restore run evidence is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_run_cassettes_immutable_identity
            BEFORE UPDATE ON restore_run_cassettes WHEN
                NEW.run_id!=OLD.run_id OR NEW.plan_id!=OLD.plan_id
                OR NEW.sequence!=OLD.sequence
                OR NEW.plan_cassette_sequence!=OLD.plan_cassette_sequence
                OR NEW.tape_id!=OLD.tape_id OR NEW.cassette_number!=OLD.cassette_number
                OR NEW.physical_label!=OLD.physical_label
                OR NEW.volume_label!=OLD.volume_label
                OR NEW.volume_serial!=OLD.volume_serial
                OR NEW.volume_uuid IS NOT OLD.volume_uuid
                OR NEW.item_count!=OLD.item_count OR NEW.total_bytes!=OLD.total_bytes
            BEGIN SELECT RAISE(ABORT,'restore run cassette identity is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_run_cassettes_no_delete
            BEFORE DELETE ON restore_run_cassettes
            BEGIN SELECT RAISE(ABORT,'restore run cassette evidence is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_run_items_immutable_identity
            BEFORE UPDATE ON restore_run_items WHEN
                NEW.run_id!=OLD.run_id OR NEW.plan_id!=OLD.plan_id
                OR NEW.sequence!=OLD.sequence OR NEW.plan_item_sequence!=OLD.plan_item_sequence
                OR NEW.cassette_sequence!=OLD.cassette_sequence
                OR NEW.file_version_id!=OLD.file_version_id OR NEW.library_id!=OLD.library_id
                OR NEW.relative_path!=OLD.relative_path
                OR NEW.tape_relative_path!=OLD.tape_relative_path
                OR NEW.tape_id!=OLD.tape_id OR NEW.cassette_number!=OLD.cassette_number
                OR NEW.physical_label!=OLD.physical_label OR NEW.volume_label!=OLD.volume_label
                OR NEW.block_id!=OLD.block_id OR NEW.size!=OLD.size OR NEW.sha256!=OLD.sha256
                OR NEW.copied_at!=OLD.copied_at OR NEW.is_current!=OLD.is_current
                OR NEW.destination_relative_path!=OLD.destination_relative_path
                OR NEW.canonical_destination!=OLD.canonical_destination
            BEGIN SELECT RAISE(ABORT,'restore run item identity is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_run_items_no_delete
            BEFORE DELETE ON restore_run_items
            BEGIN SELECT RAISE(ABORT,'restore run item evidence is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_item_conflicts_immutable_binding
            BEFORE UPDATE ON restore_item_conflicts WHEN
                NEW.id!=OLD.id OR NEW.run_id!=OLD.run_id
                OR NEW.item_sequence!=OLD.item_sequence
                OR NEW.conflict_sequence!=OLD.conflict_sequence
                OR NEW.file_version_id!=OLD.file_version_id
                OR NEW.canonical_destination!=OLD.canonical_destination
                OR NEW.observed_size!=OLD.observed_size
                OR NEW.observed_sha256!=OLD.observed_sha256
                OR NEW.recorded_at!=OLD.recorded_at
            BEGIN SELECT RAISE(ABORT,'restore conflict binding is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_item_conflicts_no_delete
            BEFORE DELETE ON restore_item_conflicts
            BEGIN SELECT RAISE(ABORT,'restore conflict evidence is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_replacement_authorizations_immutable_binding
            BEFORE UPDATE ON restore_replacement_authorizations WHEN
                NEW.id!=OLD.id OR NEW.conflict_id!=OLD.conflict_id
                OR NEW.run_id!=OLD.run_id OR NEW.item_sequence!=OLD.item_sequence
                OR NEW.file_version_id!=OLD.file_version_id
                OR NEW.canonical_destination!=OLD.canonical_destination
                OR NEW.observed_size!=OLD.observed_size
                OR NEW.observed_sha256!=OLD.observed_sha256
                OR NEW.administrator!=OLD.administrator
                OR NEW.reauthentication_proof_sha256!=OLD.reauthentication_proof_sha256
                OR NEW.request_sha256!=OLD.request_sha256
                OR NEW.authorized_at!=OLD.authorized_at
            BEGIN SELECT RAISE(ABORT,'restore replacement authorization binding is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_replacement_authorizations_no_delete
            BEFORE DELETE ON restore_replacement_authorizations
            BEGIN SELECT RAISE(ABORT,'restore replacement authorization is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_release_receipts_no_update
            BEFORE UPDATE ON restore_release_receipts
            BEGIN SELECT RAISE(ABORT,'restore release receipt is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_release_receipts_no_delete
            BEFORE DELETE ON restore_release_receipts
            BEGIN SELECT RAISE(ABORT,'restore release receipt is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_retry_preparations_no_update
            BEFORE UPDATE ON restore_retry_preparations
            BEGIN SELECT RAISE(ABORT,'restore retry preparation is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_retry_preparations_no_delete
            BEFORE DELETE ON restore_retry_preparations
            BEGIN SELECT RAISE(ABORT,'restore retry preparation is immutable'); END;
            """,
        )

        if added_identity:
            receipts = db.execute(
                "SELECT actor,idempotency_key,response_json "
                "FROM management_idempotency WHERE action='restore.plan.create' "
                "AND target_id='restore-plans' COLLATE NOCASE"
            ).fetchall()
            for receipt in receipts:
                try:
                    plan_id = json.loads(receipt["response_json"])["id"]
                except (KeyError, TypeError, ValueError):
                    continue
                plan = db.execute(
                    "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
                ).fetchone()
                if plan is None:
                    continue
                cassettes = db.execute(
                    "SELECT * FROM restore_plan_cassettes WHERE plan_id=? "
                    "ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                items = db.execute(
                    "SELECT * FROM restore_plan_items WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                db.execute(
                    "UPDATE management_idempotency SET response_json=? "
                    "WHERE actor=? AND idempotency_key=?",
                    (
                        json.dumps(
                            self._restore_plan_mapping(plan, cassettes, items),
                            ensure_ascii=False,
                            separators=(",", ":"),
                            sort_keys=True,
                        ),
                        receipt["actor"],
                        receipt["idempotency_key"],
                    ),
                )

    def _maintain_schema_38_sequence_continuations(
        self, db: sqlite3.Connection
    ) -> None:
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS operation_sequence_continuations (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence > 0),
                layout_epoch INTEGER NOT NULL CHECK(layout_epoch > 0),
                layout_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(layout_fingerprint_sha256) = 64),
                continuation_idempotency_key TEXT NOT NULL UNIQUE,
                linked_at TEXT NOT NULL,
                FOREIGN KEY(job_id, cassette_sequence)
                    REFERENCES automatic_cassettes(job_id, sequence),
                FOREIGN KEY(job_id, layout_epoch)
                    REFERENCES job_layout_epochs(job_id, epoch_number)
            );
            CREATE TRIGGER IF NOT EXISTS
                trg_operation_sequence_continuations_no_update
                BEFORE UPDATE ON operation_sequence_continuations
                BEGIN SELECT RAISE(ABORT,'immutable_operation_sequence_continuation'); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_operation_sequence_continuations_no_delete
                BEFORE DELETE ON operation_sequence_continuations
                BEGIN SELECT RAISE(ABORT,'immutable_operation_sequence_continuation'); END;
            """,
        )

    def _maintain_schema_36_unattended_sequences(
        self, db: sqlite3.Connection
    ) -> None:
        """Install authority tables and disabled state for native existing jobs."""

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS automatic_format_authorizations (
                authorization_id TEXT PRIMARY KEY,
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence > 0),
                layout_epoch INTEGER NOT NULL CHECK(layout_epoch > 0),
                layout_fingerprint_sha256 TEXT NOT NULL CHECK(length(layout_fingerprint_sha256)=64),
                expected_label TEXT NOT NULL CHECK(length(expected_label)=6),
                expected_operation TEXT NOT NULL CHECK(expected_operation='format'),
                reuse_registered INTEGER NOT NULL CHECK(reuse_registered IN (0,1)),
                authorized_by TEXT NOT NULL,
                authorized_at TEXT NOT NULL,
                request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                UNIQUE(job_id,cassette_sequence,expected_label),
                FOREIGN KEY(job_id,cassette_sequence)
                  REFERENCES automatic_cassettes(job_id,sequence),
                FOREIGN KEY(job_id,layout_epoch)
                  REFERENCES job_layout_epochs(job_id,epoch_number)
            );
            CREATE TABLE IF NOT EXISTS automatic_sequence_state (
                job_id TEXT PRIMARY KEY COLLATE NOCASE REFERENCES automatic_jobs(id),
                state TEXT NOT NULL CHECK(state IN ('disabled','enabled','pause_pending','completed')),
                layout_epoch INTEGER NOT NULL CHECK(layout_epoch > 0),
                layout_fingerprint_sha256 TEXT NOT NULL CHECK(length(layout_fingerprint_sha256)=64),
                revision INTEGER NOT NULL CHECK(revision > 0),
                enabled_by TEXT,
                enabled_at TEXT,
                updated_at TEXT NOT NULL,
                FOREIGN KEY(job_id,layout_epoch)
                  REFERENCES job_layout_epochs(job_id,epoch_number)
            );
            CREATE TABLE IF NOT EXISTS operation_format_authorizations (
                operation_id TEXT PRIMARY KEY REFERENCES format_confirmations(operation_id),
                authorization_id TEXT NOT NULL REFERENCES automatic_format_authorizations(authorization_id),
                linked_at TEXT NOT NULL
            );
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_format_authorizations_no_update
                BEFORE UPDATE ON automatic_format_authorizations
                BEGIN SELECT RAISE(ABORT,'immutable_automatic_format_authorization'); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_format_authorizations_no_delete
                BEFORE DELETE ON automatic_format_authorizations
                BEGIN SELECT RAISE(ABORT,'immutable_automatic_format_authorization'); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_operation_format_authorizations_no_update
                BEFORE UPDATE ON operation_format_authorizations
                BEGIN SELECT RAISE(ABORT,'immutable_operation_format_authorization'); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_operation_format_authorizations_no_delete
                BEFORE DELETE ON operation_format_authorizations
                BEGIN SELECT RAISE(ABORT,'immutable_operation_format_authorization'); END;
            """,
        )
        now = self._precise_utc_now()
        db.execute(
            "INSERT OR IGNORE INTO automatic_sequence_state("
            "job_id,state,layout_epoch,layout_fingerprint_sha256,revision,"
            "enabled_by,enabled_at,updated_at) "
            "SELECT job.id,'disabled',epoch.epoch_number,"
            "epoch.layout_fingerprint_sha256,1,NULL,NULL,? "
            "FROM automatic_jobs AS job "
            "JOIN job_layout_epochs AS epoch ON epoch.job_id=job.id "
            "WHERE epoch.epoch_number=(SELECT MAX(current.epoch_number) "
            "FROM job_layout_epochs AS current WHERE current.job_id=job.id) "
            "AND NOT EXISTS(SELECT 1 FROM imported_job_policies AS imported "
            "WHERE imported.job_id=job.id COLLATE NOCASE)",
            (now,),
        )

    def _rebuild_schema_35_job_policy_snapshots(
        self, db: sqlite3.Connection
    ) -> None:
        """Detach immutable job policy history from the consumed plan lifetime."""

        expected_columns = (
            "job_id",
            "plan_id",
            "settings_revision",
            "policy_json",
            "policy_sha256",
            "created_at",
        )
        actual_columns = tuple(
            str(row["name"])
            for row in db.execute("PRAGMA table_info(job_policy_snapshots)")
        )
        if actual_columns != expected_columns:
            raise CatalogError("schema35 invalid job policy snapshot layout")
        replacement = "job_policy_snapshots_v35"
        db.execute(
            f"""
            CREATE TABLE {replacement} (
                job_id TEXT PRIMARY KEY COLLATE NOCASE,
                plan_id TEXT COLLATE NOCASE,
                settings_revision INTEGER NOT NULL CHECK(settings_revision>=1),
                policy_json TEXT NOT NULL,
                policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
                created_at TEXT NOT NULL
            )
            """
        )
        columns = ",".join(expected_columns)
        db.execute(
            f"INSERT INTO {replacement}({columns}) "
            f"SELECT {columns} FROM job_policy_snapshots"
        )
        db.execute("DROP TABLE job_policy_snapshots")
        db.execute(
            f"ALTER TABLE {replacement} RENAME TO job_policy_snapshots"
        )
        self._execute_sql_batch(
            db,
            """
            CREATE TRIGGER job_policy_snapshot_immutable_update
            BEFORE UPDATE ON job_policy_snapshots
            BEGIN
                SELECT RAISE(ABORT, 'job policy snapshot is immutable');
            END;
            CREATE TRIGGER job_policy_snapshot_immutable_delete
            BEFORE DELETE ON job_policy_snapshots
            BEGIN
                SELECT RAISE(ABORT, 'job policy snapshot is immutable');
            END;
            """,
        )

    def _rebuild_schema_35_cassette_segments(self, db: sqlite3.Connection) -> None:
        """Permit immutable APPEND segments to share one physical cassette.

        Before schema 35 an APPEND reused and rewrote the completed FORMAT row.
        A layout epoch cannot do that: each write segment needs a new queue row,
        while the completed row and manifest remain byte-for-byte unchanged.
        """

        parent = "automatic_cassettes"
        replacement = "automatic_cassettes_v35"
        parent_sql_row = db.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name=?", (parent,)
        ).fetchone()
        if parent_sql_row is None:
            raise CatalogError("schema35_missing_automatic_cassettes")
        parent_sql = str(parent_sql_row["sql"])
        if "UNIQUE(job_id, physical_label)" not in parent_sql:
            return
        parent_objects = [
            str(row["sql"])
            for row in db.execute(
                "SELECT sql FROM sqlite_master WHERE tbl_name=? "
                "AND type IN ('index','trigger') AND sql IS NOT NULL",
                (parent,),
            )
        ]
        replacement_sql = re.sub(
            r'^CREATE TABLE\s+(?:"automatic_cassettes"|automatic_cassettes)',
            f'CREATE TABLE "{replacement}"',
            parent_sql,
            count=1,
        )
        replacement_sql = re.sub(
            r",\s*UNIQUE\(job_id, physical_label\)\s*,\s*"
            r"UNIQUE\(job_id, tape_serial\)\s*",
            "",
            replacement_sql,
            count=1,
        )
        db.execute(replacement_sql)
        parent_columns = [
            str(row["name"]) for row in db.execute(f"PRAGMA table_info({parent})")
        ]
        quoted_parent_columns = ",".join(f'"{name}"' for name in parent_columns)
        db.execute(
            f'INSERT INTO "{replacement}"({quoted_parent_columns}) '
            f'SELECT {quoted_parent_columns} FROM "{parent}"'
        )

        table_names = {
            str(row["name"])
            for row in db.execute(
                "SELECT name FROM sqlite_master WHERE type='table' "
                "AND name NOT LIKE 'sqlite_%'"
            )
        }
        descendants: set[str] = set()
        changed = True
        while changed:
            changed = False
            referenced = {parent, *descendants}
            for table in sorted(table_names - {parent, replacement} - descendants):
                foreign_targets = {
                    str(row["table"])
                    for row in db.execute(f'PRAGMA foreign_key_list("{table}")')
                }
                if foreign_targets & referenced:
                    descendants.add(table)
                    changed = True

        dependencies = {
            table: {
                str(row["table"])
                for row in db.execute(f'PRAGMA foreign_key_list("{table}")')
                if str(row["table"]) in descendants and str(row["table"]) != table
            }
            for table in descendants
        }
        recreate_order: list[str] = []
        remaining = set(descendants)
        while remaining:
            ready = sorted(
                table for table in remaining if not (dependencies[table] & remaining)
            )
            if not ready:
                raise CatalogError("schema35_cassette_fk_cycle")
            recreate_order.extend(ready)
            remaining.difference_update(ready)

        saved_tables: dict[str, tuple[str, tuple[str, ...], str, str]] = {}
        for index, table in enumerate(recreate_order, 1):
            table_sql = str(
                db.execute(
                    "SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                    (table,),
                ).fetchone()["sql"]
            )
            objects = tuple(
                str(row["sql"])
                for row in db.execute(
                    "SELECT sql FROM sqlite_master WHERE tbl_name=? "
                    "AND type IN ('index','trigger') AND sql IS NOT NULL "
                    "ORDER BY type,name",
                    (table,),
                )
            )
            columns = tuple(
                str(row["name"])
                for row in db.execute(f'PRAGMA table_info("{table}")')
            )
            quoted_columns = ",".join(f'"{name}"' for name in columns)
            stage = f"schema35_stage_{index}"
            db.execute(
                f'CREATE TEMP TABLE "{stage}" AS '
                f'SELECT {quoted_columns} FROM "{table}"'
            )
            saved_tables[table] = (table_sql, objects, quoted_columns, stage)

        db.execute("PRAGMA defer_foreign_keys=ON")
        for table in reversed(recreate_order):
            db.execute(f'DROP TABLE "{table}"')
        db.execute(f'DROP TABLE "{parent}"')
        db.execute(f'ALTER TABLE "{replacement}" RENAME TO "{parent}"')
        for object_sql in parent_objects:
            db.execute(object_sql)
        for table in recreate_order:
            table_sql, objects, quoted_columns, stage = saved_tables[table]
            db.execute(table_sql)
            db.execute(
                f'INSERT INTO "{table}"({quoted_columns}) '
                f'SELECT {quoted_columns} FROM "{stage}"'
            )
            db.execute(f'DROP TABLE "{stage}"')
            for object_sql in objects:
                db.execute(object_sql)

    def _maintain_schema_35_incremental_jobs(self, db: sqlite3.Connection) -> None:
        self._execute_sql_batch(db, """
            CREATE TABLE IF NOT EXISTS job_incremental_policies (
                job_id TEXT PRIMARY KEY COLLATE NOCASE REFERENCES automatic_jobs(id),
                cadence TEXT NOT NULL CHECK(cadence IN ('off','every_6_hours','every_12_hours','daily','weekly')),
                next_eligible_at TEXT,last_attempt_at TEXT,last_success_at TEXT,
                last_outcome TEXT CHECK(last_outcome IS NULL OR last_outcome IN (
                    'no_changes','extension_queued','waiting_labels','deferred_busy',
                    'plan_stale','source_unavailable','failed_safe')),
                revision INTEGER NOT NULL CHECK(revision>0),updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS job_incremental_scan_leases (
                job_id TEXT PRIMARY KEY COLLATE NOCASE REFERENCES automatic_jobs(id),
                run_id TEXT NOT NULL UNIQUE,daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),
                claimed_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS job_layout_epochs (
                job_id TEXT NOT NULL COLLATE NOCASE,
                epoch_number INTEGER NOT NULL CHECK(epoch_number>0),
                kind TEXT NOT NULL CHECK(kind IN ('initial','extension')),
                plan_id TEXT COLLATE NOCASE,
                plan_digest_sha256 TEXT NOT NULL CHECK(length(plan_digest_sha256)=64 AND plan_digest_sha256 NOT GLOB '*[^0-9a-f]*'),
                prior_epoch_sha256 TEXT CHECK(prior_epoch_sha256 IS NULL OR (
                    length(prior_epoch_sha256)=64 AND prior_epoch_sha256 NOT GLOB '*[^0-9a-f]*')),
                layout_fingerprint_sha256 TEXT NOT NULL CHECK(length(layout_fingerprint_sha256)=64 AND layout_fingerprint_sha256 NOT GLOB '*[^0-9a-f]*'),
                canonical_json TEXT NOT NULL,created_at TEXT NOT NULL,
                PRIMARY KEY(job_id,epoch_number),UNIQUE(plan_id),
                CHECK((epoch_number=1 AND kind='initial' AND prior_epoch_sha256 IS NULL)
                    OR (epoch_number>1 AND kind='extension' AND prior_epoch_sha256 IS NOT NULL))
            );
            CREATE TABLE IF NOT EXISTS job_layout_targets (
                job_id TEXT NOT NULL COLLATE NOCASE,epoch_number INTEGER NOT NULL,
                target_sequence INTEGER NOT NULL CHECK(target_sequence>0),
                plan_sequence INTEGER NOT NULL CHECK(plan_sequence>0),physical_label TEXT NOT NULL,
                operation TEXT NOT NULL CHECK(operation IN ('format','append','reserve')),
                segment_id TEXT NOT NULL CHECK(length(segment_id)=64 AND segment_id NOT GLOB '*[^0-9a-f]*'),canonical_json TEXT NOT NULL,
                PRIMARY KEY(job_id,epoch_number,plan_sequence),
                FOREIGN KEY(job_id,epoch_number) REFERENCES job_layout_epochs(job_id,epoch_number)
            );
            CREATE TABLE IF NOT EXISTS job_layout_target_blocks (
                job_id TEXT NOT NULL COLLATE NOCASE,
                epoch_number INTEGER NOT NULL CHECK(epoch_number>0),
                plan_sequence INTEGER NOT NULL CHECK(plan_sequence>0),
                target_sequence INTEGER NOT NULL CHECK(target_sequence>0),
                segment_id TEXT NOT NULL,
                operation_id TEXT NOT NULL,
                block_id TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL,
                PRIMARY KEY(job_id,epoch_number,plan_sequence,block_id),
                FOREIGN KEY(job_id,epoch_number,plan_sequence)
                    REFERENCES job_layout_targets(job_id,epoch_number,plan_sequence)
            );
            CREATE TABLE IF NOT EXISTS job_incremental_pending_extensions (
                job_id TEXT PRIMARY KEY COLLATE NOCASE REFERENCES automatic_jobs(id),
                base_epoch_number INTEGER NOT NULL CHECK(base_epoch_number>0),
                base_layout_fingerprint TEXT NOT NULL CHECK(length(base_layout_fingerprint)=64 AND base_layout_fingerprint NOT GLOB '*[^0-9a-f]*'),
                plan_id TEXT NOT NULL UNIQUE COLLATE NOCASE,
                plan_digest_sha256 TEXT NOT NULL CHECK(length(plan_digest_sha256)=64 AND plan_digest_sha256 NOT GLOB '*[^0-9a-f]*'),
                discovered_files INTEGER NOT NULL CHECK(discovered_files>=0),
                discovered_bytes INTEGER NOT NULL CHECK(discovered_bytes>=0),
                required_additional_labels INTEGER NOT NULL CHECK(required_additional_labels>=0),
                created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS job_incremental_scan_events (
                run_id TEXT NOT NULL,event_sequence INTEGER NOT NULL CHECK(event_sequence>0),
                job_id TEXT NOT NULL COLLATE NOCASE,
                trigger TEXT NOT NULL CHECK(trigger IN ('scheduled','manual','labels_added','startup_catchup')),
                base_layout_epoch INTEGER NOT NULL CHECK(base_layout_epoch>0),
                base_layout_fingerprint TEXT NOT NULL CHECK(length(base_layout_fingerprint)=64 AND base_layout_fingerprint NOT GLOB '*[^0-9a-f]*'),
                idempotency_key_sha256 TEXT NOT NULL CHECK(length(idempotency_key_sha256)=64 AND idempotency_key_sha256 NOT GLOB '*[^0-9a-f]*'),
                state TEXT NOT NULL CHECK(state IN ('claimed','scanning','no_changes','extension_ready','extension_queued','waiting_labels','deferred_busy','plan_stale','source_unavailable','failed_safe')),
                daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),recorded_at TEXT NOT NULL,
                plan_id TEXT COLLATE NOCASE,
                plan_digest_sha256 TEXT CHECK(plan_digest_sha256 IS NULL OR (length(plan_digest_sha256)=64 AND plan_digest_sha256 NOT GLOB '*[^0-9a-f]*')),
                discovered_files INTEGER NOT NULL DEFAULT 0 CHECK(discovered_files>=0),
                discovered_bytes INTEGER NOT NULL DEFAULT 0 CHECK(discovered_bytes>=0),
                required_additional_labels INTEGER NOT NULL DEFAULT 0 CHECK(required_additional_labels>=0),
                error_code TEXT CHECK(error_code IS NULL OR (length(error_code) BETWEEN 1 AND 64 AND error_code NOT GLOB '*[^a-z0-9_]*')),
                PRIMARY KEY(run_id,event_sequence),CHECK((event_sequence=1 AND state='claimed') OR (event_sequence>1 AND state!='claimed'))
            );
            CREATE INDEX IF NOT EXISTS ix_incremental_policy_due ON job_incremental_policies(cadence,next_eligible_at,job_id);
            CREATE INDEX IF NOT EXISTS ix_incremental_events_job ON job_incremental_scan_events(job_id,recorded_at,run_id,event_sequence);
            CREATE TRIGGER IF NOT EXISTS trg_layout_epochs_no_update BEFORE UPDATE ON job_layout_epochs BEGIN SELECT RAISE(ABORT,'immutable_layout_epoch'); END;
            CREATE TRIGGER IF NOT EXISTS trg_layout_epochs_no_delete BEFORE DELETE ON job_layout_epochs BEGIN SELECT RAISE(ABORT,'immutable_layout_epoch'); END;
            CREATE TRIGGER IF NOT EXISTS trg_layout_targets_no_update BEFORE UPDATE ON job_layout_targets BEGIN SELECT RAISE(ABORT,'immutable_layout_target'); END;
            CREATE TRIGGER IF NOT EXISTS trg_layout_targets_no_delete BEFORE DELETE ON job_layout_targets BEGIN SELECT RAISE(ABORT,'immutable_layout_target'); END;
            CREATE TRIGGER IF NOT EXISTS trg_layout_target_blocks_no_update BEFORE UPDATE ON job_layout_target_blocks BEGIN SELECT RAISE(ABORT,'immutable_layout_target_block'); END;
            CREATE TRIGGER IF NOT EXISTS trg_layout_target_blocks_no_delete BEFORE DELETE ON job_layout_target_blocks BEGIN SELECT RAISE(ABORT,'immutable_layout_target_block'); END;
            CREATE TRIGGER IF NOT EXISTS trg_incremental_events_no_update BEFORE UPDATE ON job_incremental_scan_events BEGIN SELECT RAISE(ABORT,'immutable_incremental_scan_event'); END;
            CREATE TRIGGER IF NOT EXISTS trg_incremental_events_no_delete BEFORE DELETE ON job_incremental_scan_events BEGIN SELECT RAISE(ABORT,'immutable_incremental_scan_event'); END;
            CREATE TRIGGER IF NOT EXISTS trg_incremental_events_claim_fence
            BEFORE INSERT ON job_incremental_scan_events
            WHEN NEW.event_sequence=1 AND NOT EXISTS(
                SELECT 1 FROM daemon_ownership owner WHERE owner.singleton=1
                AND owner.generation=NEW.daemon_generation)
            BEGIN SELECT RAISE(ABORT,'incremental_event_fence_invalid'); END;
            CREATE TRIGGER IF NOT EXISTS trg_incremental_events_append_guard BEFORE INSERT ON job_incremental_scan_events
            WHEN NEW.event_sequence>1 AND (
                NOT EXISTS(SELECT 1 FROM job_incremental_scan_events prior WHERE prior.run_id=NEW.run_id
                    AND prior.event_sequence=NEW.event_sequence-1 AND prior.job_id=NEW.job_id COLLATE NOCASE
                    AND prior.trigger=NEW.trigger AND prior.base_layout_epoch=NEW.base_layout_epoch
                    AND prior.base_layout_fingerprint=NEW.base_layout_fingerprint
                    AND prior.idempotency_key_sha256=NEW.idempotency_key_sha256
                    AND prior.daemon_generation=NEW.daemon_generation AND prior.recorded_at<=NEW.recorded_at)
                OR EXISTS(SELECT 1 FROM job_incremental_scan_events terminal WHERE terminal.run_id=NEW.run_id
                    AND terminal.state IN ('no_changes','extension_queued','waiting_labels','deferred_busy','plan_stale','source_unavailable','failed_safe'))
                OR NOT EXISTS(SELECT 1 FROM daemon_ownership owner WHERE owner.singleton=1 AND owner.generation=NEW.daemon_generation))
            BEGIN SELECT RAISE(ABORT,'incremental_event_fence_invalid'); END;
        """)

    def _maintain_schema_34_operation_block_lifecycle(
        self, db: sqlite3.Connection
    ) -> None:
        """Install the immutable archive used before deleting ownership parents."""

        tombstone_table = db.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' "
            "AND name='automatic_operation_block_tombstones'"
        ).fetchone()
        if tombstone_table is not None and "registered_tape_recovery_reset" not in str(
            tombstone_table["sql"]
        ):
            self._execute_sql_batch(
                db,
                """
                DROP TRIGGER IF EXISTS trg_automatic_operation_blocks_no_delete;
                DROP TRIGGER IF EXISTS
                    trg_automatic_operation_block_tombstones_insert_controlled;
                DROP TRIGGER IF EXISTS
                    trg_automatic_operation_block_tombstones_no_update;
                DROP TRIGGER IF EXISTS
                    trg_automatic_operation_block_tombstones_no_delete;
                ALTER TABLE automatic_operation_block_tombstones
                    RENAME TO automatic_operation_block_tombstones_legacy_v34;
                CREATE TABLE automatic_operation_block_tombstones (
                    block_id TEXT PRIMARY KEY,
                    operation_id TEXT NOT NULL,
                    job_id TEXT NOT NULL COLLATE NOCASE,
                    cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                    daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),
                    created_at TEXT NOT NULL,
                    disposition TEXT NOT NULL CHECK(disposition IN (
                        'job_deleted','registered_tape_reformatted',
                        'registered_tape_reset','registered_tape_recovery_reset'
                    )),
                    archived_at TEXT NOT NULL
                );
                INSERT INTO automatic_operation_block_tombstones(
                    block_id,operation_id,job_id,cassette_sequence,
                    daemon_generation,created_at,disposition,archived_at
                )
                SELECT block_id,operation_id,job_id,cassette_sequence,
                    daemon_generation,created_at,disposition,archived_at
                FROM automatic_operation_block_tombstones_legacy_v34;
                DROP TABLE automatic_operation_block_tombstones_legacy_v34;
                """,
            )

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS automatic_operation_block_tombstones (
                block_id TEXT PRIMARY KEY,
                operation_id TEXT NOT NULL,
                job_id TEXT NOT NULL COLLATE NOCASE,
                cassette_sequence INTEGER NOT NULL CHECK(cassette_sequence>0),
                daemon_generation INTEGER NOT NULL CHECK(daemon_generation>0),
                created_at TEXT NOT NULL,
                disposition TEXT NOT NULL CHECK(disposition IN (
                    'job_deleted','registered_tape_reformatted',
                    'registered_tape_reset','registered_tape_recovery_reset'
                )),
                archived_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS
                ix_automatic_operation_block_tombstones_operation
                ON automatic_operation_block_tombstones(operation_id,block_id);
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_operation_block_tombstones_insert_controlled
                BEFORE INSERT ON automatic_operation_block_tombstones
                WHEN lto_operation_block_archive_active()!=1
                BEGIN SELECT RAISE(
                    ABORT,'controlled_automatic_operation_block_archive_required'
                ); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_operation_block_tombstones_no_update
                BEFORE UPDATE ON automatic_operation_block_tombstones
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_operation_block_tombstone'
                ); END;
            CREATE TRIGGER IF NOT EXISTS
                trg_automatic_operation_block_tombstones_no_delete
                BEFORE DELETE ON automatic_operation_block_tombstones
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_operation_block_tombstone'
                ); END;
            DROP TRIGGER IF EXISTS trg_automatic_operation_blocks_no_delete;
            CREATE TRIGGER trg_automatic_operation_blocks_no_delete
                BEFORE DELETE ON automatic_operation_blocks
                WHEN lto_operation_block_archive_active()!=1 OR NOT EXISTS(
                    SELECT 1
                    FROM automatic_operation_block_tombstones AS archived
                    WHERE archived.block_id=OLD.block_id
                      AND archived.operation_id=OLD.operation_id
                      AND archived.job_id=OLD.job_id COLLATE NOCASE
                      AND archived.cassette_sequence=OLD.cassette_sequence
                      AND archived.created_at=OLD.created_at
                )
                BEGIN SELECT RAISE(
                    ABORT,'immutable_automatic_operation_block'
                ); END;
            """,
        )

    def _maintain_schema_34_restore_plans(self, db: sqlite3.Connection) -> None:
        """Maintain metadata-only restore plans without consuming schema 35."""

        plan_table_exists = db.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='restore_plans'"
        ).fetchone()
        if plan_table_exists is not None:
            plan_columns = {
                str(row["name"])
                for row in db.execute("PRAGMA table_info(restore_plans)")
            }
            if "identity_state" not in plan_columns:
                db.execute(
                    "ALTER TABLE restore_plans ADD COLUMN identity_state TEXT "
                    "NOT NULL DEFAULT 'exact' CHECK(identity_state IN "
                    "('exact','legacy_invalid'))"
                )
            if "invalidation_reason" not in plan_columns:
                db.execute(
                    "ALTER TABLE restore_plans ADD COLUMN invalidation_reason TEXT "
                    "CHECK(invalidation_reason IS NULL OR "
                    "invalidation_reason='legacy_physical_identity_ambiguous')"
                )

        item_foreign_keys = tuple(
            db.execute("PRAGMA foreign_key_list(restore_plan_items)")
        )
        if any(str(row["table"]) == "file_versions" for row in item_foreign_keys):
            legacy_items = db.execute(
                "SELECT plan_id,sequence,file_version_id,tape_id,"
                "cassette_number,physical_label FROM restore_plan_items"
            ).fetchall()
            repaired_item_labels: dict[tuple[str, int], str | None] = {}
            ambiguous_plan_ids: set[str] = set()
            for item in legacy_items:
                legacy_label = item["physical_label"]
                cassette_number = item["cassette_number"]
                valid_legacy_label = (
                    isinstance(legacy_label, str)
                    and 1 <= len(legacy_label) <= 32
                )
                if valid_legacy_label and legacy_label != cassette_number:
                    repaired_label = legacy_label
                else:
                    candidates = {
                        str(row["physical_label"])
                        for row in db.execute(
                            "SELECT cassette.physical_label "
                            "FROM file_versions AS version "
                            "JOIN automatic_cassettes AS cassette ON instr("
                            "',' || cassette.block_id || ',',"
                            "',' || version.block_id || ','"
                            ") > 0 WHERE version.id=?",
                            (item["file_version_id"],),
                        )
                        if isinstance(row["physical_label"], str)
                        and 1 <= len(row["physical_label"]) <= 32
                    }
                    repaired_label = (
                        next(iter(candidates)) if len(candidates) == 1 else None
                    )
                    if (
                        valid_legacy_label
                        and legacy_label == cassette_number
                        and len(candidates) != 1
                    ):
                        ambiguous_plan_ids.add(str(item["plan_id"]))
                repaired_item_labels[
                    (str(item["plan_id"]), int(item["sequence"]))
                ] = repaired_label

            self._execute_sql_batch(
                db,
                """
                DROP TRIGGER IF EXISTS restore_plans_immutable_update;
                DROP TRIGGER IF EXISTS restore_plan_cassettes_immutable_update;
                DROP TRIGGER IF EXISTS restore_plan_items_immutable_update;
                DROP TRIGGER IF EXISTS restore_plan_items_immutable_delete;
                ALTER TABLE restore_plan_items
                    RENAME TO restore_plan_items_legacy_v34;
                CREATE TABLE restore_plan_items (
                    plan_id TEXT NOT NULL
                        REFERENCES restore_plans(id) ON DELETE RESTRICT,
                    sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 200),
                    file_version_id INTEGER NOT NULL,
                    library_id TEXT NOT NULL,
                    relative_path TEXT NOT NULL,
                    tape_relative_path TEXT NOT NULL,
                    tape_id TEXT NOT NULL,
                    cassette_number TEXT NOT NULL,
                    physical_label TEXT,
                    volume_label TEXT,
                    block_id TEXT,
                    size INTEGER NOT NULL CHECK(size>=0),
                    sha256 TEXT NOT NULL CHECK(length(sha256)=64),
                    copied_at TEXT NOT NULL,
                    is_current INTEGER CHECK(is_current IN (0,1)),
                    PRIMARY KEY(plan_id,sequence),
                    UNIQUE(plan_id,file_version_id)
                );
                INSERT INTO restore_plan_items(
                    plan_id,sequence,file_version_id,library_id,relative_path,
                    tape_relative_path,tape_id,cassette_number,physical_label,
                    size,sha256,copied_at
                )
                SELECT plan_id,sequence,file_version_id,library_id,relative_path,
                    tape_relative_path,tape_id,cassette_number,physical_label,
                    size,sha256,copied_at
                FROM restore_plan_items_legacy_v34;
                DROP TABLE restore_plan_items_legacy_v34;
                """,
            )
            db.executemany(
                "UPDATE restore_plans SET identity_state='legacy_invalid',"
                "invalidation_reason='legacy_physical_identity_ambiguous' "
                "WHERE id=?",
                ((plan_id,) for plan_id in sorted(ambiguous_plan_ids)),
            )
            db.executemany(
                "UPDATE restore_plan_items SET physical_label=? "
                "WHERE plan_id=? AND sequence=?",
                (
                    (label, plan_id, sequence)
                    for (plan_id, sequence), label in repaired_item_labels.items()
                ),
            )
            cassette_rows = db.execute(
                "SELECT plan_id,sequence,tape_id FROM restore_plan_cassettes"
            ).fetchall()
            for cassette in cassette_rows:
                labels = {
                    row["physical_label"]
                    for row in db.execute(
                        "SELECT physical_label FROM restore_plan_items "
                        "WHERE plan_id=? AND tape_id=? AND physical_label IS NOT NULL",
                        (cassette["plan_id"], cassette["tape_id"]),
                    )
                }
                physical_label = next(iter(labels)) if len(labels) == 1 else None
                db.execute(
                    "UPDATE restore_plan_cassettes SET physical_label=? "
                    "WHERE plan_id=? AND sequence=?",
                    (
                        physical_label,
                        cassette["plan_id"],
                        cassette["sequence"],
                    ),
                )

            receipts = db.execute(
                "SELECT actor,idempotency_key,response_json "
                "FROM management_idempotency "
                "WHERE action='restore.plan.create' "
                "AND target_id='restore-plans' COLLATE NOCASE"
            ).fetchall()
            for receipt in receipts:
                try:
                    recorded = json.loads(receipt["response_json"])
                    plan_id = recorded["id"]
                except (KeyError, TypeError, ValueError):
                    continue
                plan = db.execute(
                    "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
                ).fetchone()
                if plan is None:
                    continue
                cassettes = db.execute(
                    "SELECT * FROM restore_plan_cassettes "
                    "WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                items = db.execute(
                    "SELECT * FROM restore_plan_items "
                    "WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                response_json = json.dumps(
                    self._restore_plan_mapping(plan, cassettes, items),
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                db.execute(
                    "UPDATE management_idempotency SET response_json=? "
                    "WHERE actor=? AND idempotency_key=?",
                    (
                        response_json,
                        receipt["actor"],
                        receipt["idempotency_key"],
                    ),
                )

        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS restore_plans (
                id TEXT PRIMARY KEY,
                state TEXT NOT NULL CHECK(state='planned'),
                destination_root TEXT NOT NULL,
                created_by TEXT NOT NULL,
                created_at TEXT NOT NULL,
                request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                total_files INTEGER NOT NULL CHECK(total_files BETWEEN 1 AND 200),
                total_bytes INTEGER NOT NULL CHECK(total_bytes>=0),
                identity_state TEXT NOT NULL DEFAULT 'exact'
                    CHECK(identity_state IN ('exact','legacy_invalid')),
                invalidation_reason TEXT CHECK(
                    invalidation_reason IS NULL OR
                    invalidation_reason='legacy_physical_identity_ambiguous'
                )
            );
            CREATE TABLE IF NOT EXISTS restore_plan_cassettes (
                plan_id TEXT NOT NULL REFERENCES restore_plans(id) ON DELETE RESTRICT,
                sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 200),
                tape_id TEXT NOT NULL,
                cassette_number TEXT NOT NULL,
                physical_label TEXT,
                item_count INTEGER NOT NULL CHECK(item_count BETWEEN 1 AND 200),
                total_bytes INTEGER NOT NULL CHECK(total_bytes>=0),
                PRIMARY KEY(plan_id,sequence),
                UNIQUE(plan_id,tape_id)
            );
            CREATE TABLE IF NOT EXISTS restore_plan_items (
                plan_id TEXT NOT NULL REFERENCES restore_plans(id) ON DELETE RESTRICT,
                sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 200),
                file_version_id INTEGER NOT NULL,
                library_id TEXT NOT NULL,
                relative_path TEXT NOT NULL,
                tape_relative_path TEXT NOT NULL,
                tape_id TEXT NOT NULL,
                cassette_number TEXT NOT NULL,
                physical_label TEXT,
                volume_label TEXT,
                block_id TEXT,
                size INTEGER NOT NULL CHECK(size>=0),
                sha256 TEXT NOT NULL CHECK(length(sha256)=64),
                copied_at TEXT NOT NULL,
                is_current INTEGER CHECK(is_current IN (0,1)),
                PRIMARY KEY(plan_id,sequence),
                UNIQUE(plan_id,file_version_id)
            );
            CREATE TRIGGER IF NOT EXISTS restore_plans_immutable_update
            BEFORE UPDATE ON restore_plans
            BEGIN SELECT RAISE(ABORT,'restore plan is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plans_immutable_delete
            BEFORE DELETE ON restore_plans
            BEGIN SELECT RAISE(ABORT,'restore plan is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plan_cassettes_immutable_update
            BEFORE UPDATE ON restore_plan_cassettes
            BEGIN SELECT RAISE(ABORT,'restore plan cassette is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plan_cassettes_immutable_delete
            BEFORE DELETE ON restore_plan_cassettes
            BEGIN SELECT RAISE(ABORT,'restore plan cassette is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plan_items_immutable_update
            BEFORE UPDATE ON restore_plan_items
            BEGIN SELECT RAISE(ABORT,'restore plan item is immutable'); END;
            CREATE TRIGGER IF NOT EXISTS restore_plan_items_immutable_delete
            BEFORE DELETE ON restore_plan_items
            BEGIN SELECT RAISE(ABORT,'restore plan item is immutable'); END;
            """,
        )

        item_columns = {
            str(row["name"])
            for row in db.execute("PRAGMA table_info(restore_plan_items)")
        }
        added_snapshot_columns = {
            column
            for column in ("volume_label", "block_id", "is_current")
            if column not in item_columns
        }
        snapshot_backfill_required = bool(added_snapshot_columns)
        if not snapshot_backfill_required:
            snapshot_backfill_required = (
                db.execute(
                    "SELECT 1 FROM restore_plan_items AS item "
                    "JOIN file_versions AS version ON version.id=item.file_version_id "
                    "WHERE item.volume_label IS NULL OR item.block_id IS NULL "
                    "LIMIT 1"
                ).fetchone()
                is not None
            )
        if snapshot_backfill_required:
            db.execute("DROP TRIGGER IF EXISTS restore_plan_items_immutable_update")
            if "volume_label" in added_snapshot_columns:
                db.execute("ALTER TABLE restore_plan_items ADD COLUMN volume_label TEXT")
            if "block_id" in added_snapshot_columns:
                db.execute("ALTER TABLE restore_plan_items ADD COLUMN block_id TEXT")
            if "is_current" in added_snapshot_columns:
                db.execute(
                    "ALTER TABLE restore_plan_items ADD COLUMN is_current INTEGER "
                    "CHECK(is_current IN (0,1))"
                )
            db.execute(
                "UPDATE restore_plan_items SET "
                "volume_label=(SELECT tape.volume_label FROM file_versions AS version "
                "JOIN tapes AS tape ON tape.id=version.tape_id "
                "WHERE version.id=restore_plan_items.file_version_id),"
                "block_id=(SELECT version.block_id FROM file_versions AS version "
                "WHERE version.id=restore_plan_items.file_version_id)"
            )
            db.execute(
                "CREATE TRIGGER restore_plan_items_immutable_update "
                "BEFORE UPDATE ON restore_plan_items "
                "BEGIN SELECT RAISE(ABORT,'restore plan item is immutable'); END"
            )
            receipts = db.execute(
                "SELECT actor,idempotency_key,response_json "
                "FROM management_idempotency WHERE action='restore.plan.create' "
                "AND target_id='restore-plans' COLLATE NOCASE"
            ).fetchall()
            for receipt in receipts:
                try:
                    plan_id = json.loads(receipt["response_json"])["id"]
                except (KeyError, TypeError, ValueError):
                    continue
                plan = db.execute(
                    "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
                ).fetchone()
                if plan is None:
                    continue
                cassettes = db.execute(
                    "SELECT * FROM restore_plan_cassettes WHERE plan_id=? "
                    "ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                items = db.execute(
                    "SELECT * FROM restore_plan_items WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                ).fetchall()
                db.execute(
                    "UPDATE management_idempotency SET response_json=? "
                    "WHERE actor=? AND idempotency_key=?",
                    (
                        json.dumps(
                            self._restore_plan_mapping(plan, cassettes, items),
                            ensure_ascii=False,
                            separators=(",", ":"),
                            sort_keys=True,
                        ),
                        receipt["actor"],
                        receipt["idempotency_key"],
                    ),
                )

    def _maintain_schema_33_recovery_attempt_ledger(
        self, db: sqlite3.Connection
    ) -> None:
        """Restore the schema-33 outcome ordering guard if it is absent."""

        db.execute(
            """
            CREATE TRIGGER IF NOT EXISTS
                trg_recovery_attempt_events_outcome_requires_start
                BEFORE INSERT ON recovery_attempt_events
                WHEN NEW.event_sequence=2 AND NOT EXISTS(
                    SELECT 1 FROM recovery_attempt_events AS started
                    WHERE started.operation_id=NEW.operation_id
                      AND started.attempt_number=NEW.attempt_number
                      AND started.event_sequence=1
                      AND started.job_id IS NEW.job_id
                      AND started.cassette_sequence IS NEW.cassette_sequence
                      AND started.cassette_label IS NEW.cassette_label
                      AND started.trigger=NEW.trigger
                )
                BEGIN SELECT RAISE(
                    ABORT,'recovery_attempt_start_identity_required'
                ); END
            """
        )

    def _maintain_schema_30_share_recovery(self, db: sqlite3.Connection) -> None:
        columns = {
            str(row["name"])
            for row in db.execute("PRAGMA table_info(share_operations)")
        }
        table = db.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='share_operations'"
        ).fetchone()
        if (
            "recovery_deadline" in columns
            and table is not None
            and "recovering" in str(table["sql"])
        ):
            return
        self._execute_sql_batch(
            db,
            """
            DROP INDEX IF EXISTS ux_share_one_live_operation;
            DROP INDEX IF EXISTS ix_share_operations_latest;
            CREATE TABLE share_operations_recovery_v30 (
                operation_id TEXT PRIMARY KEY COLLATE NOCASE,
                share_id TEXT NOT NULL COLLATE NOCASE
                    REFERENCES managed_shares(share_id),
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                keyed_request_fingerprint_sha256 TEXT NOT NULL
                    CHECK(length(keyed_request_fingerprint_sha256)=64),
                expected_share_revision INTEGER NOT NULL CHECK(expected_share_revision>0),
                frozen_config_json TEXT NOT NULL,
                frozen_config_revision INTEGER NOT NULL CHECK(frozen_config_revision>0),
                frozen_credential_generation INTEGER NOT NULL
                    CHECK(frozen_credential_generation>=0),
                frozen_observed_state TEXT NOT NULL CHECK(frozen_observed_state IN (
                    'disconnected','connecting','connected','disconnecting','error'
                )),
                state TEXT NOT NULL CHECK(state IN (
                    'queued','running','recovering','succeeded','failed'
                )),
                owner_id TEXT,
                safe_error_code TEXT,
                receipt_sha256 TEXT CHECK(
                    receipt_sha256 IS NULL OR length(receipt_sha256)=64
                ),
                queued_at TEXT NOT NULL,
                started_at TEXT NOT NULL,
                claimed_at TEXT,
                recovery_deadline TEXT,
                finished_at TEXT,
                recovered_at TEXT,
                UNIQUE(actor,idempotency_key),
                CHECK(
                    (state='queued' AND owner_id IS NULL
                        AND claimed_at IS NULL AND finished_at IS NULL)
                    OR (state IN ('running','recovering') AND owner_id IS NOT NULL
                        AND claimed_at IS NOT NULL AND finished_at IS NULL)
                    OR (state IN ('succeeded','failed') AND finished_at IS NOT NULL)
                )
            );
            INSERT INTO share_operations_recovery_v30(
                operation_id,share_id,actor,action,idempotency_key,
                keyed_request_fingerprint_sha256,expected_share_revision,
                frozen_config_json,frozen_config_revision,
                frozen_credential_generation,frozen_observed_state,state,
                owner_id,safe_error_code,receipt_sha256,queued_at,started_at,
                claimed_at,recovery_deadline,finished_at,recovered_at
            )
            SELECT operation_id,share_id,actor,action,idempotency_key,
                keyed_request_fingerprint_sha256,expected_share_revision,
                frozen_config_json,frozen_config_revision,
                frozen_credential_generation,frozen_observed_state,state,
                owner_id,safe_error_code,receipt_sha256,queued_at,started_at,
                claimed_at,NULL,finished_at,recovered_at
            FROM share_operations;
            DROP TABLE share_operations;
            ALTER TABLE share_operations_recovery_v30 RENAME TO share_operations;
            CREATE UNIQUE INDEX ux_share_one_live_operation
                ON share_operations(share_id COLLATE NOCASE)
                WHERE state IN ('queued','running','recovering');
            CREATE INDEX ix_share_operations_latest
                ON share_operations(share_id COLLATE NOCASE,queued_at DESC,operation_id);
            """,
        )

    def _create_schema_14_tables(self, db: sqlite3.Connection) -> None:
        self._execute_sql_batch(
            db,
            """
            CREATE TABLE IF NOT EXISTS daemon_operations (
                id TEXT PRIMARY KEY,
                kind TEXT NOT NULL,
                state TEXT NOT NULL CHECK(state IN (
                    'running','succeeded','failed','cancelled','recovery_required'
                )),
                phase TEXT CHECK(phase IS NULL OR phase IN (
                    'identifying_media','formatting_media','mounting','writing',
                    'writing_manifest','finalizing_index','unmounting','committing','unloading'
                )),
                idempotency_key TEXT NOT NULL UNIQUE,
                principal TEXT NOT NULL,
                owner_generation INTEGER NOT NULL,
                job_id TEXT,
                cassette_sequence INTEGER,
                started_at TEXT NOT NULL,
                finished_at TEXT,
                error_class TEXT CHECK(error_class IN (
                    'retryable','operator_required','terminal_safety_failure'
                )),
                error_code TEXT,
                error_message TEXT
            );
            CREATE UNIQUE INDEX IF NOT EXISTS ux_daemon_one_blocking
                ON daemon_operations((1))
                WHERE state IN ('running','recovery_required');

            CREATE TABLE IF NOT EXISTS operation_hardware_targets (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                mount_path_sha256 TEXT NOT NULL CHECK(length(mount_path_sha256) = 64),
                tape_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(tape_device_identity_sha256) = 64),
                scsi_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(scsi_device_identity_sha256) = 64),
                expected_media_scope_sha256 TEXT NOT NULL
                    CHECK(length(expected_media_scope_sha256) = 64),
                bound_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS cutover_authorizations (
                id TEXT PRIMARY KEY,
                credential_sha256 TEXT NOT NULL UNIQUE,
                job_id TEXT NOT NULL,
                cassette_sequence INTEGER NOT NULL,
                bundle_sha256 TEXT NOT NULL,
                catalog_binding_sha256 TEXT NOT NULL,
                assignment_sha256 TEXT NOT NULL,
                expected_label TEXT NOT NULL,
                host_id TEXT NOT NULL,
                drive_serial_sha256 TEXT NOT NULL,
                peer_kind TEXT NOT NULL CHECK(peer_kind = 'local_admin'),
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                consumed_at TEXT,
                consumed_by_operation_id TEXT REFERENCES daemon_operations(id)
            );

            CREATE TABLE IF NOT EXISTS format_confirmations (
                operation_id TEXT PRIMARY KEY
                    REFERENCES daemon_operations(id) ON DELETE CASCADE,
                job_id TEXT NOT NULL,
                cassette_sequence INTEGER NOT NULL,
                expected_label TEXT NOT NULL,
                confirmed_by TEXT NOT NULL,
                confirmed_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS hardware_command_executions (
                id TEXT PRIMARY KEY,
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                issued_generation INTEGER NOT NULL,
                command_kind TEXT NOT NULL,
                argv_sha256 TEXT NOT NULL,
                mount_path_sha256 TEXT NOT NULL CHECK(length(mount_path_sha256) = 64),
                tape_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(tape_device_identity_sha256) = 64),
                scsi_device_identity_sha256 TEXT NOT NULL
                    CHECK(length(scsi_device_identity_sha256) = 64),
                expected_media_scope_sha256 TEXT NOT NULL
                    CHECK(length(expected_media_scope_sha256) = 64),
                observed_media_identity_sha256 TEXT CHECK(
                    observed_media_identity_sha256 IS NULL
                    OR length(observed_media_identity_sha256) = 64
                ),
                state TEXT NOT NULL CHECK(state IN (
                    'launch_reserved','launch_blocked','released','exit_observed','quiesced'
                )),
                boot_id TEXT,
                pid INTEGER,
                process_start_ticks INTEGER,
                process_group_id INTEGER,
                exit_outcome TEXT CHECK(exit_outcome IN (
                    'completed','terminated','launch_aborted'
                )),
                created_at TEXT NOT NULL,
                released_at TEXT,
                exit_observed_at TEXT,
                quiesced_at TEXT,
                CHECK (
                    (boot_id IS NULL AND pid IS NULL AND process_start_ticks IS NULL
                     AND process_group_id IS NULL)
                    OR
                    (boot_id IS NOT NULL AND pid IS NOT NULL
                     AND process_start_ticks IS NOT NULL AND process_group_id IS NOT NULL)
                )
            );
            CREATE INDEX IF NOT EXISTS ix_hardware_command_nonquiescent
                ON hardware_command_executions(operation_id, state)
                WHERE state != 'quiesced';

            CREATE TABLE IF NOT EXISTS operation_media_identity_bindings (
                operation_id TEXT PRIMARY KEY
                    REFERENCES operation_hardware_targets(operation_id),
                observed_media_identity_sha256 TEXT NOT NULL
                    CHECK(length(observed_media_identity_sha256) = 64),
                bound_by_command_id TEXT NOT NULL REFERENCES hardware_command_executions(id),
                bound_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS command_quiescence_receipts (
                id TEXT PRIMARY KEY,
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                reconciled_by_generation INTEGER NOT NULL,
                recorded_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS command_quiescence_receipt_items (
                receipt_id TEXT NOT NULL
                    REFERENCES command_quiescence_receipts(id) ON DELETE CASCADE,
                command_id TEXT NOT NULL REFERENCES hardware_command_executions(id),
                exit_outcome TEXT NOT NULL CHECK(exit_outcome IN (
                    'completed','terminated','launch_aborted'
                )),
                PRIMARY KEY(receipt_id, command_id)
            );
            CREATE TABLE IF NOT EXISTS physical_reconciliation_receipts (
                id TEXT PRIMARY KEY,
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                reconciled_by_generation INTEGER NOT NULL,
                command_receipt_id TEXT NOT NULL REFERENCES command_quiescence_receipts(id),
                mount_path_sha256 TEXT CHECK(
                    mount_path_sha256 IS NULL OR length(mount_path_sha256) = 64
                ),
                tape_device_identity_sha256 TEXT CHECK(
                    tape_device_identity_sha256 IS NULL
                    OR length(tape_device_identity_sha256) = 64
                ),
                scsi_device_identity_sha256 TEXT CHECK(
                    scsi_device_identity_sha256 IS NULL
                    OR length(scsi_device_identity_sha256) = 64
                ),
                expected_media_scope_sha256 TEXT CHECK(
                    expected_media_scope_sha256 IS NULL
                    OR length(expected_media_scope_sha256) = 64
                ),
                observed_media_identity_sha256 TEXT CHECK(
                    observed_media_identity_sha256 IS NULL
                    OR length(observed_media_identity_sha256) = 64
                ),
                mounted INTEGER NOT NULL CHECK(mounted = 0),
                media_loaded INTEGER NOT NULL CHECK(media_loaded = 0),
                drive_busy INTEGER NOT NULL CHECK(drive_busy = 0),
                related_process_count INTEGER NOT NULL CHECK(related_process_count = 0),
                recorded_at TEXT NOT NULL,
                CHECK (
                    (mount_path_sha256 IS NULL AND tape_device_identity_sha256 IS NULL
                     AND scsi_device_identity_sha256 IS NULL
                     AND expected_media_scope_sha256 IS NULL
                     AND observed_media_identity_sha256 IS NULL)
                    OR
                    (mount_path_sha256 IS NOT NULL
                     AND tape_device_identity_sha256 IS NOT NULL
                     AND scsi_device_identity_sha256 IS NOT NULL
                     AND expected_media_scope_sha256 IS NOT NULL)
                )
            );

            CREATE TABLE IF NOT EXISTS phase_samples (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                operation_id TEXT NOT NULL REFERENCES daemon_operations(id),
                owner_generation INTEGER NOT NULL,
                phase TEXT NOT NULL CHECK(phase IN (
                    'identifying_media','formatting_media','mounting','writing',
                    'writing_manifest','finalizing_index','unmounting','committing','unloading'
                )),
                started_at TEXT NOT NULL,
                duration_seconds REAL NOT NULL CHECK(duration_seconds >= 0),
                recorded_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS audit_entries (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recorded_at TEXT NOT NULL,
                principal TEXT NOT NULL,
                action TEXT NOT NULL,
                result TEXT NOT NULL,
                request_id TEXT NOT NULL,
                remote_address TEXT,
                payload_json TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS migration_receipts (
                id TEXT PRIMARY KEY,
                job_id TEXT NOT NULL REFERENCES automatic_jobs(id),
                bundle_sha256 TEXT NOT NULL CHECK(length(bundle_sha256) = 64),
                assignment_sha256 TEXT NOT NULL CHECK(length(assignment_sha256) = 64),
                recorded_at TEXT NOT NULL,
                UNIQUE(job_id, bundle_sha256)
            );
            CREATE TABLE IF NOT EXISTS imported_job_policies (
                job_id TEXT PRIMARY KEY REFERENCES automatic_jobs(id),
                policy_kind TEXT NOT NULL DEFAULT 'frozen-allocation'
                    CHECK(policy_kind = 'frozen-allocation'),
                assignment_sha256 TEXT NOT NULL CHECK(length(assignment_sha256) = 64),
                bundle_sha256 TEXT NOT NULL CHECK(length(bundle_sha256) = 64),
                authority_state TEXT NOT NULL CHECK(authority_state IN (
                    'pre_cutover','active_linux'
                )),
                windows_authority TEXT NOT NULL CHECK(windows_authority IN (
                    'resumable','historical_read_only'
                )),
                rollback_allowed INTEGER NOT NULL CHECK(rollback_allowed IN (0, 1)),
                frozen_at TEXT NOT NULL,
                activated_by_operation TEXT REFERENCES daemon_operations(id),
                activated_at TEXT
            );
            CREATE TABLE IF NOT EXISTS daemon_ownership (
                singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
                owner_id TEXT NOT NULL,
                generation INTEGER NOT NULL CHECK(generation > 0),
                claimed_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS daemon_event_sequence (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                reserved_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS recovery_resolutions (
                operation_id TEXT PRIMARY KEY REFERENCES daemon_operations(id),
                resolved_by_generation INTEGER NOT NULL,
                reason_code TEXT NOT NULL,
                command_receipt_id TEXT NOT NULL REFERENCES command_quiescence_receipts(id),
                physical_receipt_id TEXT NOT NULL
                    REFERENCES physical_reconciliation_receipts(id),
                resolved_at TEXT NOT NULL
            );
            """,
        )

    @staticmethod
    def _split_relative_path(relative_path: str) -> tuple[str, str]:
        normalized = relative_path.replace("\\", "/").strip("/")
        path = PurePosixPath(normalized)
        parent = "" if str(path.parent) == "." else path.parent.as_posix()
        return parent, path.name

    def add_library(self, library_id: str, name: str, source_root: str) -> None:
        validate_id(library_id, "ID libreria")
        if not name.strip():
            raise ValidationError("Il nome della libreria è obbligatorio")
        source = Path(source_root)
        if not source.is_absolute():
            raise ValidationError("Il percorso sorgente deve essere assoluto o UNC")
        if not source.is_dir():
            raise ValidationError(f"Sorgente non accessibile o non directory: {source}")
        try:
            with self.transaction() as db:
                db.execute(
                    """
                    INSERT INTO libraries(id, name, source_root, status, created_at)
                    VALUES(?, ?, ?, 'active', ?)
                    """,
                    (library_id, name.strip(), str(source), utc_now()),
                )
                self._event(
                    db,
                    "library.add",
                    {"library_id": library_id, "source_root": str(source)},
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(f"Libreria già presente: {library_id}") from exc

    @staticmethod
    def _validate_library_name(name: object) -> str:
        if not isinstance(name, str):
            raise ValidationError("invalid library display name")
        normalized = name.strip()
        if (
            not normalized
            or len(normalized) > 120
            or any(ord(character) < 32 for character in normalized)
        ):
            raise ValidationError("invalid library display name")
        return normalized

    @staticmethod
    def _validate_library_source_identity(
        source_root: object,
        source_canonical_root: object,
        source_identity_sha256: object,
    ) -> tuple[str, str, str]:
        if (
            not isinstance(source_root, str)
            or not source_root
            or not Path(source_root).is_absolute()
            or not isinstance(source_canonical_root, str)
            or not source_canonical_root
            or not Path(source_canonical_root).is_absolute()
        ):
            raise ValidationError("invalid library source root")
        Catalog._validate_sha256(source_identity_sha256, "library source identity")
        return source_root, source_canonical_root, str(source_identity_sha256)

    def add_named_library(
        self,
        library_id: str,
        display_name: str,
        source_root: str,
        source_canonical_root: str,
        source_identity_sha256: str,
    ) -> None:
        """Create one active library without exposing a physical-delete path."""

        validate_id(library_id, "library ID")
        normalized_name = self._validate_library_name(display_name)
        source_root, source_canonical_root, source_identity_sha256 = (
            self._validate_library_source_identity(
                source_root,
                source_canonical_root,
                source_identity_sha256,
            )
        )
        try:
            with self.transaction() as db:
                db.execute(
                    "INSERT INTO libraries("
                    "id,name,source_root,status,created_at,enabled,"
                    "source_canonical_root,source_identity_sha256,scan_state,"
                    "scan_revision) VALUES(?,?,?,'active',?,1,?,?,'never',0)",
                    (
                        library_id,
                        normalized_name,
                        source_root,
                        utc_now(),
                        source_canonical_root,
                        source_identity_sha256,
                    ),
                )
                self._event(
                    db,
                    "library.create",
                    {"library_id": library_id},
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(f"library_already_exists:{library_id}") from exc

    def add_named_network_library(
        self,
        library_id: str,
        display_name: str,
        derived_source_root: str,
        source_identity_sha256: str,
        share_id: str,
        relative_subpath: str,
        *,
        expected_share_revision: int,
        binding_evidence: Mapping[str, Any],
    ) -> None:
        validate_id(library_id, "library ID")
        normalized_name = self._validate_library_name(display_name)
        normalized_share_id = normalize_share_id(share_id)
        normalized_subpath = normalize_managed_source_subpath(relative_subpath)
        derived_source_root, canonical_root, source_identity_sha256 = (
            self._validate_library_source_identity(
                derived_source_root, derived_source_root, source_identity_sha256
            )
        )
        canonical_evidence = canonical_managed_source_evidence(binding_evidence)
        if (
            canonical_evidence["share_id"].casefold() != normalized_share_id.casefold()
            or canonical_evidence["relative_subpath"] != normalized_subpath
            or canonical_evidence["resource_revision"] != expected_share_revision
            or canonical_evidence["source_identity_sha256"] != source_identity_sha256
        ):
            raise ValidationError("managed source binding evidence mismatch")
        evidence_json = json.dumps(
            canonical_evidence,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        evidence_sha256 = hashlib.sha256(
            b"lto-managed-source-evidence-v1\0" + evidence_json.encode("utf-8")
        ).hexdigest()
        try:
            with self.transaction() as db:
                share = db.execute(
                    "SELECT * FROM managed_shares WHERE share_id=? AND removed_at IS NULL",
                    (normalized_share_id,),
                ).fetchone()
                if share is None:
                    raise CatalogError("share_not_found")
                if int(share["revision"]) != expected_share_revision:
                    raise CatalogError("share_revision_conflict")
                if (
                    share["lifecycle"] != "active"
                    or share["desired_state"] != "connected"
                    or share["observed_state"] != "connected"
                    or share["mount_identity_sha256"] is None
                    or int(share["mounted_config_revision"] or 0)
                    != int(share["config_revision"])
                    or share["mounted_credential_generation"] is None
                    or int(share["mounted_credential_generation"])
                    != int(share["credential_generation"])
                ):
                    raise CatalogError("share_identity_changed")
                now = utc_now()
                db.execute(
                    "INSERT INTO libraries("
                    "id,name,source_root,status,created_at,enabled,"
                    "source_canonical_root,source_identity_sha256,scan_state,"
                    "scan_revision,source_kind) "
                    "VALUES(?,?,?,'active',?,1,?,?,'never',0,'network')",
                    (
                        library_id,
                        normalized_name,
                        derived_source_root,
                        now,
                        canonical_root,
                        source_identity_sha256,
                    ),
                )
                db.execute(
                    "INSERT INTO library_share_bindings("
                    "library_id,share_id,relative_subpath,bound_share_revision,"
                    "created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    (
                        library_id,
                        share["share_id"],
                        normalized_subpath,
                        share["revision"],
                        now,
                        now,
                    ),
                )
                db.execute(
                    "INSERT INTO library_share_binding_evidence("
                    "library_id,share_id,evidence_json,evidence_sha256,bound_at) "
                    "VALUES(?,?,?,?,?)",
                    (
                        library_id,
                        share["share_id"],
                        evidence_json,
                        evidence_sha256,
                        now,
                    ),
                )
                self._event(db, "library.create", {"library_id": library_id})
        except sqlite3.IntegrityError as exc:
            raise CatalogError(f"library_already_exists:{library_id}") from exc

    def get_named_library(self, library_id: str) -> sqlite3.Row:
        validate_id(library_id, "library ID")
        has_bindings = self.connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='library_share_bindings'"
        ).fetchone()
        if has_bindings is None:
            row = self.connection.execute(
                "SELECT library.*,NULL AS bound_share_id,"
                "NULL AS bound_relative_subpath FROM libraries AS library "
                "WHERE library.id=?",
                (library_id,),
            ).fetchone()
        else:
            row = self.connection.execute(
                "SELECT library.*,binding.share_id AS bound_share_id,"
                "binding.relative_subpath AS bound_relative_subpath "
                "FROM libraries AS library "
                "LEFT JOIN library_share_bindings AS binding "
                "ON binding.library_id=library.id WHERE library.id=?",
                (library_id,),
            ).fetchone()
        if row is None:
            raise CatalogError(f"library_not_found:{library_id}")
        return row

    def list_named_libraries(self) -> list[sqlite3.Row]:
        has_bindings = self.connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='library_share_bindings'"
        ).fetchone()
        if has_bindings is None:
            return list(
                self.connection.execute(
                    "SELECT library.*,NULL AS bound_share_id,"
                    "NULL AS bound_relative_subpath FROM libraries AS library "
                    "ORDER BY library.id COLLATE NOCASE"
                )
            )
        return list(
            self.connection.execute(
                "SELECT library.*,binding.share_id AS bound_share_id,"
                "binding.relative_subpath AS bound_relative_subpath "
                "FROM libraries AS library LEFT JOIN library_share_bindings AS binding "
                "ON binding.library_id=library.id ORDER BY library.id COLLATE NOCASE"
            )
        )

    def get_library_share_binding(self, library_id: str) -> dict[str, Any]:
        validate_id(library_id, "library ID")
        row = self.connection.execute(
            "SELECT * FROM library_share_bindings WHERE library_id=? COLLATE NOCASE",
            (library_id,),
        ).fetchone()
        if row is None:
            raise CatalogError("library_share_binding_not_found")
        return self._library_share_binding_mapping(row)

    def get_library_share_binding_evidence(self, library_id: str) -> dict[str, Any]:
        validate_id(library_id, "library ID")
        row = self.connection.execute(
            "SELECT evidence_json FROM library_share_binding_evidence "
            "WHERE library_id=? COLLATE NOCASE",
            (library_id,),
        ).fetchone()
        if row is None:
            raise CatalogError("library_share_binding_evidence_not_found")
        value = json.loads(str(row["evidence_json"]))
        return canonical_managed_source_evidence(value)

    @staticmethod
    def _library_has_ready_plan_tx(db: sqlite3.Connection, library_id: str) -> bool:
        return (
            db.execute(
                "SELECT 1 FROM job_plan_libraries library "
                "JOIN job_plan_drafts draft ON draft.id=library.plan_id "
                "WHERE library.library_id=? COLLATE NOCASE "
                "AND draft.state='ready' LIMIT 1",
                (library_id,),
            ).fetchone()
            is not None
        )

    @staticmethod
    def _library_has_immutable_job_tx(db: sqlite3.Connection, library_id: str) -> bool:
        return (
            db.execute(
                "SELECT 1 FROM automatic_jobs job "
                "JOIN automatic_job_libraries library ON library.job_id=job.id "
                "LEFT JOIN imported_job_policies policy ON policy.job_id=job.id "
                "WHERE library.library_id=? COLLATE NOCASE "
                "AND (job.status NOT IN ('completed','failed') "
                "OR policy.job_id IS NOT NULL) LIMIT 1",
                (library_id,),
            ).fetchone()
            is not None
        )

    def update_named_library(
        self,
        library_id: str,
        *,
        display_name: str | None = None,
        source_root: str | None = None,
        source_canonical_root: str | None = None,
        source_identity_sha256: str | None = None,
        requested_state: str | None = None,
        expected_revision: int | None = None,
    ) -> sqlite3.Row:
        """Atomically rename, move, disable, enable, or restore by stable ID."""

        validate_id(library_id, "library ID")
        normalized_name = (
            None if display_name is None else self._validate_library_name(display_name)
        )
        source_values: tuple[str, str, str] | None = None
        if source_root is not None:
            source_values = self._validate_library_source_identity(
                source_root,
                source_canonical_root,
                source_identity_sha256,
            )
        elif source_canonical_root is not None or source_identity_sha256 is not None:
            raise ValidationError("incomplete library source identity")
        if requested_state not in {None, "active", "disabled"}:
            raise ValidationError("invalid library state")

        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM libraries WHERE id=?", (library_id,)
            ).fetchone()
            if row is None:
                raise CatalogError(f"library_not_found:{library_id}")
            revision_column = (
                "metadata_revision"
                if "metadata_revision" in tuple(row.keys())
                else "scan_revision"
            )
            if (
                expected_revision is not None
                and int(row[revision_column]) != expected_revision
            ):
                raise CatalogError(f"library_revision_conflict:{library_id}")
            if normalized_name == str(row["name"]):
                normalized_name = None
            if source_values == (
                str(row["source_root"]),
                str(row["source_canonical_root"]),
                str(row["source_identity_sha256"]),
            ):
                source_values = None
            if source_values is not None:
                if row["status"] == "retired":
                    raise CatalogError(f"library_state_conflict:{library_id}")
                if row["scan_state"] == "running":
                    raise CatalogError(f"library_state_conflict:{library_id}")
                if self._library_has_ready_plan_tx(
                    db, row["id"]
                ) or self._library_has_immutable_job_tx(db, row["id"]):
                    raise CatalogError(f"library_in_use:{library_id}")

            status = str(row["status"])
            enabled = int(row["enabled"])
            retired_at = row["retired_at"]
            if requested_state == "active":
                if status == "retired":
                    status = "active"
                    retired_at = None
                enabled = 1
            elif requested_state == "disabled":
                if status == "retired":
                    status = "active"
                    retired_at = None
                enabled = 0
            if requested_state is not None and (
                status == str(row["status"])
                and enabled == int(row["enabled"])
                and retired_at == row["retired_at"]
            ):
                requested_state = None

            assignments: list[str] = []
            values: list[object] = []
            if normalized_name is not None:
                assignments.append("name=?")
                values.append(normalized_name)
            if source_values is not None:
                assignments.extend(
                    (
                        "source_root=?",
                        "source_canonical_root=?",
                        "source_identity_sha256=?",
                        "scan_state='never'",
                        "last_scan_files=NULL",
                        "last_scan_bytes=NULL",
                        "last_scanned_at=NULL",
                        "scan_fingerprint_sha256=NULL",
                    )
                )
                values.extend(source_values)
            if requested_state is not None:
                assignments.extend(("status=?", "enabled=?", "retired_at=?"))
                values.extend((status, enabled, retired_at))
            if not assignments:
                return row
            if revision_column == "metadata_revision":
                assignments.append("metadata_revision=metadata_revision+1")
            values.append(row["id"])
            db.execute(
                f"UPDATE libraries SET {','.join(assignments)} WHERE id=?",
                tuple(values),
            )
            self._event(
                db,
                "library.update",
                {
                    "library_id": row["id"],
                    "name_changed": normalized_name is not None,
                    "root_changed": source_values is not None,
                    "state_changed": requested_state is not None,
                },
            )
        return self.get_named_library(library_id)

    def retire_named_library(
        self, library_id: str, *, expected_revision: int | None = None
    ) -> sqlite3.Row:
        """Logically retire a library while preserving all history."""

        validate_id(library_id, "library ID")
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM libraries WHERE id=?", (library_id,)
            ).fetchone()
            if row is None:
                raise CatalogError(f"library_not_found:{library_id}")
            revision_column = (
                "metadata_revision"
                if "metadata_revision" in tuple(row.keys())
                else "scan_revision"
            )
            if (
                expected_revision is not None
                and int(row[revision_column]) != expected_revision
            ):
                raise CatalogError(f"library_revision_conflict:{library_id}")
            if row["status"] != "retired" and row["scan_state"] == "running":
                raise CatalogError(f"library_state_conflict:{library_id}")
            if row["status"] != "retired" and (
                self._library_has_ready_plan_tx(db, row["id"])
                or self._library_has_immutable_job_tx(db, row["id"])
            ):
                raise CatalogError(f"library_in_use:{library_id}")
            if row["status"] != "retired":
                revision_assignment = (
                    ",metadata_revision=metadata_revision+1"
                    if revision_column == "metadata_revision"
                    else ""
                )
                db.execute(
                    "UPDATE libraries SET status='retired',enabled=0,retired_at=?"
                    f"{revision_assignment} WHERE id=?",
                    (utc_now(), row["id"]),
                )
                self._event(db, "library.retire", {"library_id": row["id"]})
        return self.get_named_library(library_id)

    def start_named_library_scan(
        self,
        library_id: str,
        *,
        managed_source_lease_id: str | None = None,
        managed_source_evidence: Mapping[str, Any] | None = None,
    ) -> sqlite3.Row:
        validate_id(library_id, "library ID")
        canonical_evidence = (
            None
            if managed_source_evidence is None
            else canonical_managed_source_evidence(managed_source_evidence)
        )
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM libraries WHERE id=?", (library_id,)
            ).fetchone()
            if row is None:
                raise CatalogError(f"library_not_found:{library_id}")
            if row["status"] != "active" or not bool(row["enabled"]):
                raise CatalogError(f"library_scan_disabled:{library_id}")
            if row["scan_state"] == "running":
                raise CatalogError(f"library_scan_running:{library_id}")
            if managed_source_lease_id is not None:
                lease = db.execute(
                    "SELECT lease.share_id,binding.relative_subpath "
                    "FROM managed_source_leases AS lease "
                    "JOIN library_share_bindings AS binding "
                    "ON binding.share_id=lease.share_id COLLATE NOCASE "
                    "WHERE lease.lease_id=? AND lease.consumer_kind='scan' "
                    "AND binding.library_id=? COLLATE NOCASE",
                    (managed_source_lease_id, row["id"]),
                ).fetchone()
                if (
                    lease is None
                    or canonical_evidence is None
                    or str(lease["share_id"]).casefold()
                    != str(canonical_evidence["share_id"]).casefold()
                    or str(lease["relative_subpath"])
                    != str(canonical_evidence["relative_subpath"])
                    or not self._managed_source_evidence_matches_share_tx(
                        db, canonical_evidence
                    )
                ):
                    raise CatalogError("managed_source_lease_lost")
                evidence_json = json.dumps(
                    canonical_evidence,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                evidence_sha256 = hashlib.sha256(
                    b"lto-managed-source-evidence-v1\0" + evidence_json.encode("utf-8")
                ).hexdigest()
                db.execute(
                    "INSERT INTO library_share_binding_evidence("
                    "library_id,share_id,evidence_json,evidence_sha256,bound_at) "
                    "VALUES(?,?,?,?,?) ON CONFLICT(library_id) DO UPDATE SET "
                    "share_id=excluded.share_id,evidence_json=excluded.evidence_json,"
                    "evidence_sha256=excluded.evidence_sha256,bound_at=excluded.bound_at",
                    (
                        row["id"],
                        canonical_evidence["share_id"],
                        evidence_json,
                        evidence_sha256,
                        utc_now(),
                    ),
                )
            elif canonical_evidence is not None:
                raise CatalogError("managed_source_lease_lost")
            db.execute(
                "UPDATE libraries SET scan_state='running' WHERE id=?", (row["id"],)
            )
            self._event(db, "library.scan.start", {"library_id": row["id"]})
        return self.get_named_library(library_id)

    def recover_interrupted_named_library_scans(self) -> list[sqlite3.Row]:
        """Mark daemon-owned scans interrupted by restart as failed."""

        with self.transaction() as db:
            library_ids = [
                str(row["id"])
                for row in db.execute(
                    "SELECT id FROM libraries WHERE scan_state='running'"
                )
            ]
            if library_ids:
                db.execute(
                    "UPDATE libraries SET scan_state='failed' "
                    "WHERE scan_state='running'"
                )
                for library_id in library_ids:
                    self._event(
                        db,
                        "library.scan.failed",
                        {"library_id": library_id, "interrupted": True},
                    )
        return [self.get_named_library(library_id) for library_id in library_ids]

    def complete_named_library_scan(
        self,
        library_id: str,
        *,
        total_files: int,
        total_bytes: int,
        scan_fingerprint_sha256: str,
        source_canonical_root: str,
        source_identity_sha256: str,
        managed_source_evidence: Mapping[str, Any] | None = None,
        managed_source_lease_id: str | None = None,
        release_managed_source_lease: bool = True,
    ) -> sqlite3.Row:
        if (
            type(total_files) is not int
            or total_files < 0
            or type(total_bytes) is not int
            or total_bytes < 0
        ):
            raise ValidationError("invalid library scan totals")
        self._validate_sha256(scan_fingerprint_sha256, "library scan fingerprint")
        self._validate_sha256(source_identity_sha256, "library source identity")
        if not Path(source_canonical_root).is_absolute():
            raise ValidationError("invalid canonical library root")
        evidence_json: str | None = None
        evidence_sha256: str | None = None
        if managed_source_evidence is not None:
            canonical_evidence = canonical_managed_source_evidence(
                managed_source_evidence
            )
            evidence_json = json.dumps(
                canonical_evidence,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            evidence_sha256 = hashlib.sha256(
                b"lto-managed-source-evidence-v1\0" + evidence_json.encode("utf-8")
            ).hexdigest()
        with self.transaction() as db:
            current = db.execute(
                "SELECT * FROM libraries WHERE id=?", (library_id,)
            ).fetchone()
            if current is None:
                raise CatalogError(f"library_not_found:{library_id}")
            if managed_source_evidence is not None:
                binding = db.execute(
                    "SELECT binding.share_id,binding_evidence.evidence_json "
                    "FROM library_share_bindings AS binding "
                    "JOIN library_share_binding_evidence AS binding_evidence "
                    "ON binding_evidence.library_id=binding.library_id "
                    "WHERE binding.library_id=? COLLATE NOCASE",
                    (library_id,),
                ).fetchone()
                lease = db.execute(
                    "SELECT share_id,consumer_kind FROM managed_source_leases "
                    "WHERE lease_id=?",
                    (managed_source_lease_id,),
                ).fetchone()
                if (
                    binding is None
                    or lease is None
                    or str(binding["share_id"]).casefold()
                    != str(lease["share_id"]).casefold()
                    or json.loads(str(binding["evidence_json"])) != canonical_evidence
                    or not self._managed_source_evidence_matches_share_tx(
                        db, canonical_evidence
                    )
                ):
                    raise CatalogError("managed_source_evidence_changed")
                if (
                    lease["consumer_kind"] == "scan"
                    and current["scan_state"] != "running"
                ):
                    raise CatalogError("library_scan_not_running")
            cursor = db.execute(
                "UPDATE libraries SET scan_state='ready',scan_revision=scan_revision+1,"
                "scan_fingerprint_sha256=?,last_scan_files=?,last_scan_bytes=?,"
                "last_scanned_at=?,source_canonical_root=?,source_identity_sha256=? "
                "WHERE id=?",
                (
                    scan_fingerprint_sha256,
                    total_files,
                    total_bytes,
                    utc_now(),
                    source_canonical_root,
                    source_identity_sha256,
                    library_id,
                ),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"library_not_found:{library_id}")
            if evidence_json is not None:
                scan_revision = int(current["scan_revision"]) + 1
                db.execute(
                    "INSERT INTO library_share_scan_evidence("
                    "library_id,share_id,scan_revision,evidence_json,"
                    "evidence_sha256,verified_at) "
                    "SELECT ?,share_id,?,?,?,? FROM library_share_bindings "
                    "WHERE library_id=? COLLATE NOCASE "
                    "ON CONFLICT(library_id) DO UPDATE SET "
                    "share_id=excluded.share_id,scan_revision=excluded.scan_revision,"
                    "evidence_json=excluded.evidence_json,"
                    "evidence_sha256=excluded.evidence_sha256,"
                    "verified_at=excluded.verified_at",
                    (
                        library_id,
                        scan_revision,
                        evidence_json,
                        evidence_sha256,
                        utc_now(),
                        library_id,
                    ),
                )
                if release_managed_source_lease:
                    db.execute(
                        "DELETE FROM managed_source_leases WHERE lease_id=?",
                        (managed_source_lease_id,),
                    )
            self._event(
                db,
                "library.scan.complete",
                {
                    "library_id": library_id,
                    "total_files": total_files,
                    "total_bytes": total_bytes,
                },
            )
        return self.get_named_library(library_id)

    def fail_named_library_scan(
        self,
        library_id: str,
        *,
        invalidate_ready_plans: bool = False,
        previous_scan: tuple[object, object, object] | None = None,
    ) -> sqlite3.Row:
        validate_id(library_id, "library ID")
        with self.transaction() as db:
            row = db.execute(
                "SELECT id FROM libraries WHERE id=?", (library_id,)
            ).fetchone()
            if row is None:
                raise CatalogError(f"library_not_found:{library_id}")
            if previous_scan is None:
                db.execute(
                    "UPDATE libraries SET scan_state='failed' WHERE id=?",
                    (row["id"],),
                )
            else:
                db.execute(
                    "UPDATE libraries SET scan_state='failed',last_scan_files=?,"
                    "last_scan_bytes=?,last_scanned_at=? WHERE id=?",
                    (*previous_scan, row["id"]),
                )
            invalidated = 0
            if invalidate_ready_plans:
                invalidated = db.execute(
                    "UPDATE job_plan_drafts SET state='expired',updated_at=? "
                    "WHERE state='ready' AND id IN ("
                    "SELECT plan_id FROM job_plan_libraries "
                    "WHERE library_id=? COLLATE NOCASE)",
                    (utc_now(), row["id"]),
                ).rowcount
            self._event(
                db,
                "library.scan.failed",
                {
                    "library_id": row["id"],
                    "invalidated_plans": int(invalidated),
                },
            )
        return self.get_named_library(library_id)

    @staticmethod
    def _application_settings_mapping(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "revision": int(row["revision"]),
            "capacity_reserve_bytes": int(row["capacity_reserve_bytes"]),
            "minimum_source_file_age_seconds": int(
                row["minimum_source_file_age_seconds"]
            ),
            "copy_buffer_bytes": int(row["copy_buffer_bytes"]),
            "source_change_detection_policy": (
                str(row["source_change_detection_policy"])
                if "source_change_detection_policy" in row.keys()
                else "size_mtime"
            ),
            "content_verification_policy": str(row["content_verification_policy"]),
            "default_media_profile": str(row["default_media_profile"]),
            "tape_root_directory": str(row["tape_root_directory"]),
            "legacy_tape_capacity_bytes": int(row["legacy_tape_capacity_bytes"]),
            "legacy_source_sha256": row["legacy_source_sha256"],
        }

    def get_application_settings(self) -> dict[str, Any]:
        row = self.connection.execute(
            "SELECT * FROM application_settings WHERE singleton=1"
        ).fetchone()
        if row is None:
            raise CatalogError("application_settings_uninitialized")
        return self._application_settings_mapping(row)

    def application_settings_initialized(self) -> bool:
        return (
            self.connection.execute(
                "SELECT 1 FROM application_settings WHERE singleton=1"
            ).fetchone()
            is not None
        )

    @staticmethod
    def _compatibility_policy(
        settings_row: sqlite3.Row,
        selected_media_profile: object,
        *,
        job: bool,
    ) -> dict[str, Any]:
        selected = require_ltfs_profile(selected_media_profile)
        revision = int(settings_row["revision"])
        policy = {
            "capacity_reserve_bytes": int(settings_row["capacity_reserve_bytes"]),
            "default_media_profile": str(settings_row["default_media_profile"]),
            "minimum_source_file_age_seconds": int(
                settings_row["minimum_source_file_age_seconds"]
            ),
            "selected_media_profile": selected.key,
            "settings_revision": revision,
            "tape_root_directory": str(settings_row["tape_root_directory"]),
        }
        if job:
            policy.update(
                {
                    "content_verification_policy": str(
                        settings_row["content_verification_policy"]
                    ),
                    "job_settings_revision": revision,
                }
            )
        return policy

    @staticmethod
    def _insert_policy_snapshot_tx(
        db: sqlite3.Connection,
        *,
        table: str,
        identity: str,
        settings_revision: int,
        policy: Mapping[str, Any],
        created_at: str,
        plan_id: str | None = None,
    ) -> None:
        encoded = json.dumps(
            dict(policy),
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
        if table == "job_plan_policy_snapshots":
            db.execute(
                "INSERT OR IGNORE INTO job_plan_policy_snapshots("
                "plan_id,settings_revision,policy_json,policy_sha256,created_at) "
                "VALUES(?,?,?,?,?)",
                (identity, settings_revision, encoded, digest, created_at),
            )
        elif table == "job_policy_snapshots":
            db.execute(
                "INSERT OR IGNORE INTO job_policy_snapshots("
                "job_id,plan_id,settings_revision,policy_json,policy_sha256,created_at) "
                "VALUES(?,?,?,?,?,?)",
                (
                    identity,
                    plan_id,
                    settings_revision,
                    encoded,
                    digest,
                    created_at,
                ),
            )
        else:  # pragma: no cover - private callers use closed table names.
            raise AssertionError(f"unsupported policy snapshot table: {table}")

    def _backfill_compatibility_policy_snapshots_tx(
        self, db: sqlite3.Connection, settings_row: sqlite3.Row
    ) -> None:
        revision = int(settings_row["revision"])
        created_at = str(settings_row["created_at"])
        plans = db.execute(
            "SELECT id,media_key FROM job_plan_drafts "
            "WHERE state IN ('ready','consumed') AND NOT EXISTS("
            "SELECT 1 FROM job_plan_policy_snapshots snapshot "
            "WHERE snapshot.plan_id=job_plan_drafts.id) ORDER BY id"
        ).fetchall()
        for plan in plans:
            self._insert_policy_snapshot_tx(
                db,
                table="job_plan_policy_snapshots",
                identity=str(plan["id"]),
                settings_revision=revision,
                policy=self._compatibility_policy(
                    settings_row, plan["media_key"], job=False
                ),
                created_at=created_at,
            )
        jobs = db.execute(
            "SELECT job.id,job.media_key,state.creation_plan_id "
            "FROM automatic_jobs job "
            "JOIN job_management_state state ON state.job_id=job.id "
            "LEFT JOIN imported_job_policies imported ON imported.job_id=job.id "
            "WHERE imported.job_id IS NULL AND NOT EXISTS("
            "SELECT 1 FROM job_policy_snapshots snapshot "
            "WHERE snapshot.job_id=job.id) ORDER BY job.id"
        ).fetchall()
        for job in jobs:
            plan_id = job["creation_plan_id"]
            self._insert_policy_snapshot_tx(
                db,
                table="job_policy_snapshots",
                identity=str(job["id"]),
                plan_id=None if plan_id is None else str(plan_id),
                settings_revision=revision,
                policy=self._compatibility_policy(
                    settings_row, job["media_key"], job=True
                ),
                created_at=created_at,
            )

    def backfill_compatibility_policy_snapshots(self) -> None:
        with self.transaction() as db:
            settings_row = db.execute(
                "SELECT * FROM application_settings WHERE singleton=1"
            ).fetchone()
            if settings_row is None:
                raise CatalogError("application_settings_uninitialized")
            self._backfill_compatibility_policy_snapshots_tx(db, settings_row)

    def import_application_settings_once(
        self,
        settings: Settings,
        *,
        legacy_source_sha256: str | None,
    ) -> dict[str, Any]:
        settings.validate()
        if legacy_source_sha256 is not None:
            self._validate_sha256(legacy_source_sha256, "legacy settings digest")
        profile = require_ltfs_profile(settings.default_media_key)
        with self.transaction() as db:
            existing = db.execute(
                "SELECT * FROM application_settings WHERE singleton=1"
            ).fetchone()
            if existing is not None:
                self._backfill_compatibility_policy_snapshots_tx(db, existing)
                return self._application_settings_mapping(existing)
            now = self._precise_utc_now()
            db.execute(
                "INSERT INTO application_settings("
                "singleton,revision,capacity_reserve_bytes,"
                "minimum_source_file_age_seconds,copy_buffer_bytes,"
                "content_verification_policy,default_media_profile,"
                "tape_root_directory,legacy_tape_capacity_bytes,"
                "legacy_source_sha256,created_at,updated_at) "
                "VALUES(1,1,?,?,?,?,?,?,?,?,?,?)",
                (
                    settings.reserve_bytes,
                    settings.min_age_seconds,
                    settings.buffer_bytes,
                    "full" if settings.verify_unchanged_content else "none",
                    profile.key,
                    settings.tape_root_directory,
                    settings.tape_capacity_bytes,
                    legacy_source_sha256,
                    now,
                    now,
                ),
            )
            row = db.execute(
                "SELECT * FROM application_settings WHERE singleton=1"
            ).fetchone()
            assert row is not None
            self._backfill_compatibility_policy_snapshots_tx(db, row)
            return self._application_settings_mapping(row)

    @staticmethod
    def _validated_application_settings_candidate(
        candidate: Mapping[str, Any], legacy_tape_capacity_bytes: int
    ) -> dict[str, Any]:
        required = {
            "capacity_reserve_bytes",
            "minimum_source_file_age_seconds",
            "copy_buffer_bytes",
            "content_verification_policy",
            "source_change_detection_policy",
            "default_media_profile",
            "tape_root_directory",
        }
        if set(candidate) != required:
            raise ValidationError("application settings candidate must be complete")
        policy = candidate["content_verification_policy"]
        if policy not in {"none", "manifest", "full"}:
            raise ValidationError("invalid content verification policy")
        source_policy = candidate["source_change_detection_policy"]
        if source_policy not in {"size_mtime", "size_mtime_change"}:
            raise ValidationError("invalid source change detection policy")
        profile = require_ltfs_profile(candidate["default_media_profile"])
        try:
            settings = Settings(
                reserve_bytes=candidate["capacity_reserve_bytes"],
                tape_capacity_bytes=legacy_tape_capacity_bytes,
                buffer_bytes=candidate["copy_buffer_bytes"],
                min_age_seconds=candidate["minimum_source_file_age_seconds"],
                tape_root_directory=candidate["tape_root_directory"],
                verify_unchanged_content=policy == "full",
                default_media_key=profile.key,
            )
            settings.validate()
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValidationError("invalid application settings candidate") from exc
        return {
            "capacity_reserve_bytes": settings.reserve_bytes,
            "minimum_source_file_age_seconds": settings.min_age_seconds,
            "copy_buffer_bytes": settings.buffer_bytes,
            "content_verification_policy": policy,
            "source_change_detection_policy": source_policy,
            "default_media_profile": profile.key,
            "tape_root_directory": settings.tape_root_directory,
        }

    def update_application_settings(
        self,
        candidate: Mapping[str, Any],
        *,
        expected_revision: int | None = None,
        actor: str,
        idempotency_key: str,
        request_sha256: str,
    ) -> dict[str, Any]:
        if type(expected_revision) is not int or expected_revision < 1:
            raise ValidationError("invalid expected application settings revision")
        with self.transaction() as db:
            replay = self.management_idempotency_replay(
                actor=actor,
                idempotency_key=idempotency_key,
                action="application.settings.update",
                target_id="application-settings",
                request_sha256=request_sha256,
            )
            if replay is not None:
                return replay
            current = db.execute(
                "SELECT * FROM application_settings WHERE singleton=1"
            ).fetchone()
            if current is None:
                raise CatalogError("application_settings_uninitialized")
            if int(current["revision"]) != expected_revision:
                raise CatalogError("settings_revision_conflict")
            effective_candidate = dict(candidate)
            if effective_candidate.get("source_change_detection_policy") is None:
                effective_candidate["source_change_detection_policy"] = str(
                    current["source_change_detection_policy"]
                )
            normalized = self._validated_application_settings_candidate(
                effective_candidate, int(current["legacy_tape_capacity_bytes"])
            )
            revision = expected_revision + 1
            db.execute(
                "UPDATE application_settings SET revision=?,"
                "capacity_reserve_bytes=?,minimum_source_file_age_seconds=?,"
                "copy_buffer_bytes=?,content_verification_policy=?,"
                "source_change_detection_policy=?,"
                "default_media_profile=?,tape_root_directory=?,updated_at=? "
                "WHERE singleton=1 AND revision=?",
                (
                    revision,
                    normalized["capacity_reserve_bytes"],
                    normalized["minimum_source_file_age_seconds"],
                    normalized["copy_buffer_bytes"],
                    normalized["content_verification_policy"],
                    normalized["source_change_detection_policy"],
                    normalized["default_media_profile"],
                    normalized["tape_root_directory"],
                    self._precise_utc_now(),
                    expected_revision,
                ),
            )
            row = db.execute(
                "SELECT * FROM application_settings WHERE singleton=1"
            ).fetchone()
            assert row is not None
            response = self._application_settings_mapping(row)
            response.pop("legacy_source_sha256", None)
            response = self.record_management_idempotency(
                actor=actor,
                idempotency_key=idempotency_key,
                action="application.settings.update",
                target_id="application-settings",
                request_sha256=request_sha256,
                response=response,
            )
            self._record_audit_tx(
                db,
                actor,
                "application.settings.update",
                "accepted",
                f"request-{uuid.uuid4().hex}",
                None,
                json.dumps(
                    {"revision": revision},
                    ensure_ascii=True,
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            )
            return response

    def management_idempotency_replay(
        self,
        *,
        actor: str,
        idempotency_key: str,
        action: str,
        target_id: str,
        request_sha256: str,
    ) -> dict[str, Any] | None:
        for value, name in (
            (actor, "management actor"),
            (action, "management action"),
            (target_id, "management target"),
        ):
            self._validate_safe_identifier(value, name)
        if (
            not isinstance(idempotency_key, str)
            or not idempotency_key.strip()
            or len(idempotency_key) > 128
            or any(
                ord(character) < 32 or ord(character) == 127
                for character in idempotency_key
            )
        ):
            raise ValidationError("invalid idempotency key")
        self._validate_sha256(request_sha256, "management request digest")
        row = self.connection.execute(
            "SELECT * FROM management_idempotency WHERE actor=? AND idempotency_key=?",
            (actor, idempotency_key),
        ).fetchone()
        if row is None:
            return None
        if (
            row["action"] != action
            or str(row["target_id"]).casefold() != target_id.casefold()
            or row["request_sha256"] != request_sha256
        ):
            raise CatalogError("idempotency_conflict")
        try:
            response = json.loads(row["response_json"])
        except (TypeError, ValueError) as exc:
            raise CatalogError("invalid management idempotency record") from exc
        if not isinstance(response, dict):
            raise CatalogError("invalid management idempotency record")
        return response

    def record_management_idempotency(
        self,
        *,
        actor: str,
        idempotency_key: str,
        action: str,
        target_id: str,
        request_sha256: str,
        response: Mapping[str, Any],
    ) -> dict[str, Any]:
        existing = self.management_idempotency_replay(
            actor=actor,
            idempotency_key=idempotency_key,
            action=action,
            target_id=target_id,
            request_sha256=request_sha256,
        )
        if existing is not None:
            return existing
        encoded = json.dumps(
            dict(response),
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        try:
            with self.transaction() as db:
                db.execute(
                    "INSERT INTO management_idempotency("
                    "actor,idempotency_key,action,target_id,request_sha256,"
                    "response_json,created_at) VALUES(?,?,?,?,?,?,?)",
                    (
                        actor,
                        idempotency_key,
                        action,
                        target_id,
                        request_sha256,
                        encoded,
                        utc_now(),
                    ),
                )
        except sqlite3.IntegrityError:
            replay = self.management_idempotency_replay(
                actor=actor,
                idempotency_key=idempotency_key,
                action=action,
                target_id=target_id,
                request_sha256=request_sha256,
            )
            if replay is None:  # pragma: no cover - unique collision always has a row.
                raise
            return replay
        return dict(response)

    @staticmethod
    def _validate_share_display_name(display_name: object) -> str:
        if not isinstance(display_name, str):
            raise ValidationError("invalid managed share display name")
        normalized = unicodedata.normalize("NFKC", display_name).strip()
        if (
            not normalized
            or len(normalized) > 120
            or any(
                ord(character) < 32 or ord(character) == 127 for character in normalized
            )
        ):
            raise ValidationError("invalid managed share display name")
        return normalized

    @staticmethod
    def _canonical_share_config(protocol: object, config_json: object) -> str:
        if protocol not in {"nfs", "smb"} or not isinstance(config_json, str):
            raise ValidationError("invalid managed share config")
        try:
            payload = json.loads(config_json)
            model = (
                NfsShareConfig.model_validate(payload)
                if protocol == "nfs"
                else SmbShareConfig.model_validate(payload)
            )
        except (TypeError, ValueError):
            # Do not chain validation details: pydantic includes rejected input,
            # which may be a write-only password submitted to the wrong seam.
            raise ValidationError("invalid managed share config") from None
        if model.kind != protocol:
            raise ValidationError("managed share protocol does not match config")
        return json.dumps(
            model.model_dump(mode="json"),
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )

    @staticmethod
    def _managed_share_mapping(row: sqlite3.Row | Mapping[str, Any]) -> dict[str, Any]:
        result = dict(row)
        result["credential_configured"] = bool(result["credential_configured"])
        result["auto_connect"] = bool(result["auto_connect"])
        return result

    @staticmethod
    def _share_operation_mapping(
        row: sqlite3.Row | Mapping[str, Any],
    ) -> dict[str, Any]:
        return dict(row)

    @staticmethod
    def _library_share_binding_mapping(
        row: sqlite3.Row | Mapping[str, Any],
    ) -> dict[str, Any]:
        return dict(row)

    @staticmethod
    def _insert_management_receipt_tx(
        db: sqlite3.Connection,
        *,
        actor: str,
        idempotency_key: str,
        action: str,
        target_id: str,
        request_fingerprint_sha256: str,
        response: Mapping[str, Any],
    ) -> None:
        db.execute(
            "INSERT INTO management_idempotency("
            "actor,idempotency_key,action,target_id,request_sha256,"
            "response_json,created_at) VALUES(?,?,?,?,?,?,?)",
            (
                actor,
                idempotency_key,
                action,
                target_id,
                request_fingerprint_sha256,
                json.dumps(
                    dict(response),
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ),
                utc_now(),
            ),
        )

    @staticmethod
    def _record_share_audit_tx(
        db: sqlite3.Connection,
        *,
        actor: str,
        action: str,
        idempotency_key: str,
        payload: Mapping[str, Any],
    ) -> None:
        encoded = json.dumps(
            Catalog._redact_audit_value(dict(payload)),
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        Catalog._record_audit_tx(
            db,
            actor,
            action,
            "accepted",
            idempotency_key,
            None,
            encoded,
        )

    def _share_mutation_replay_tx(
        self,
        *,
        actor: str,
        idempotency_key: str,
        action: str,
        share_id: str,
        request_fingerprint_sha256: str,
    ) -> dict[str, Any] | None:
        # Called only after BEGIN IMMEDIATE, so the replay decision and any
        # following mutation share the same serialization boundary.
        return self.management_idempotency_replay(
            actor=actor,
            idempotency_key=idempotency_key,
            action=action,
            target_id=share_id,
            request_sha256=request_fingerprint_sha256,
        )

    def create_managed_share(
        self,
        share_id: str,
        display_name: str,
        protocol: Literal["nfs", "smb"],
        config_json: str,
        *,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
        credential_generation: int = 0,
        credential_configured: bool = False,
        desired_state: Literal["connected", "disconnected"] = "disconnected",
        observed_state: Literal[
            "disconnected", "connecting", "connected", "disconnecting", "error"
        ] = "disconnected",
        lifecycle: Literal["active", "disabled"] = "active",
        auto_connect: bool = False,
    ) -> dict[str, Any]:
        normalized_id = normalize_share_id(share_id)
        normalized_name = self._validate_share_display_name(display_name)
        canonical_config = self._canonical_share_config(protocol, config_json)
        self._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )
        if (
            type(credential_generation) is not int
            or credential_generation < 0
            or type(credential_configured) is not bool
            or type(auto_connect) is not bool
            or desired_state not in {"connected", "disconnected"}
            or observed_state
            not in {"disconnected", "connecting", "connected", "disconnecting", "error"}
            or lifecycle not in {"active", "disabled"}
            or (protocol == "nfs" and (credential_generation or credential_configured))
        ):
            raise ValidationError("invalid managed share state")

        with self.transaction() as db:
            replay = self._share_mutation_replay_tx(
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.create",
                share_id=normalized_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
            )
            if replay is not None:
                return self._managed_share_mapping(replay)
            if (
                db.execute(
                    "SELECT 1 FROM managed_shares WHERE share_id=?", (normalized_id,)
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_already_exists")
            now = utc_now()
            db.execute(
                "INSERT INTO managed_shares("
                "share_id,display_name,protocol,config_json,revision,"
                "credential_generation,credential_configured,desired_state,"
                "observed_state,lifecycle,auto_connect,created_at,updated_at) "
                "VALUES(?,?,?,?,1,?,?,?,?,?,?,?,?)",
                (
                    normalized_id,
                    normalized_name,
                    protocol,
                    canonical_config,
                    credential_generation,
                    int(credential_configured),
                    desired_state,
                    observed_state,
                    lifecycle,
                    int(auto_connect),
                    now,
                    now,
                ),
            )
            row = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_id,)
            ).fetchone()
            assert row is not None
            result = self._managed_share_mapping(row)
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.create",
                target_id=normalized_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
                response=result,
            )
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.create",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": normalized_id,
                    "protocol": protocol,
                    "revision": 1,
                    "lifecycle": lifecycle,
                },
            )
            return result

    def get_managed_share(
        self, share_id: str, *, include_removed: bool = False
    ) -> dict[str, Any]:
        normalized_id = normalize_share_id(share_id)
        row = self.connection.execute(
            "SELECT * FROM managed_shares WHERE share_id=?"
            + ("" if include_removed else " AND removed_at IS NULL"),
            (normalized_id,),
        ).fetchone()
        if row is None:
            raise CatalogError("share_not_found")
        return self._managed_share_mapping(row)

    def list_managed_shares(
        self, *, include_removed: bool = False
    ) -> list[dict[str, Any]]:
        return [
            self._managed_share_mapping(row)
            for row in self.connection.execute(
                "SELECT * FROM managed_shares"
                + ("" if include_removed else " WHERE removed_at IS NULL")
                + " ORDER BY share_id COLLATE NOCASE"
            )
        ]

    def update_managed_share(
        self,
        share_id: str,
        *,
        expected_revision: int,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
        display_name: str | None = None,
        protocol: Literal["nfs", "smb"] | None = None,
        config_json: str | None = None,
        credential_generation: int | None = None,
        credential_configured: bool | None = None,
        desired_state: Literal["connected", "disconnected"] | None = None,
        observed_state: Literal[
            "disconnected", "connecting", "connected", "disconnecting", "error"
        ]
        | None = None,
        lifecycle: Literal["active", "disabled"] | None = None,
        auto_connect: bool | None = None,
        mount_identity_sha256: object = _UNSET,
        safe_error_code: object = _UNSET,
        last_checked_at: object = _UNSET,
        queue_lifecycle_operation: bool = False,
        lifecycle_operation_id: str | None = None,
    ) -> dict[str, Any]:
        normalized_id = normalize_share_id(share_id)
        self._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )
        if type(expected_revision) is not int or expected_revision < 1:
            raise ValidationError("invalid expected share revision")
        normalized_name = (
            None
            if display_name is None
            else self._validate_share_display_name(display_name)
        )
        if protocol not in {None, "nfs", "smb"}:
            raise ValidationError("invalid managed share protocol")
        if credential_generation is not None and (
            type(credential_generation) is not int or credential_generation < 0
        ):
            raise ValidationError("invalid credential generation")
        if (
            credential_configured is not None
            and type(credential_configured) is not bool
        ):
            raise ValidationError("invalid credential state")
        if desired_state not in {None, "connected", "disconnected"}:
            raise ValidationError("invalid desired share state")
        if observed_state not in {
            None,
            "disconnected",
            "connecting",
            "connected",
            "disconnecting",
            "error",
        }:
            raise ValidationError("invalid observed share state")
        if lifecycle not in {None, "active", "disabled"}:
            raise ValidationError("invalid share lifecycle")
        if auto_connect is not None and type(auto_connect) is not bool:
            raise ValidationError("invalid auto-connect state")
        if mount_identity_sha256 is not _UNSET and mount_identity_sha256 is not None:
            self._validate_sha256(mount_identity_sha256, "share mount identity")
        if safe_error_code is not _UNSET:
            safe_error_code = validate_share_safe_error_code(safe_error_code)
        if (
            last_checked_at is not _UNSET
            and last_checked_at is not None
            and self._parse_utc_timestamp(last_checked_at) is None
        ):
            raise ValidationError("invalid share health timestamp")
        if type(queue_lifecycle_operation) is not bool or (
            queue_lifecycle_operation != (lifecycle_operation_id is not None)
        ):
            raise ValidationError("invalid lifecycle operation request")
        if lifecycle_operation_id is not None:
            self._validate_safe_identifier(
                lifecycle_operation_id, "share operation ID"
            )
        if all(
            value is None
            for value in (
                normalized_name,
                protocol,
                config_json,
                credential_generation,
                credential_configured,
                desired_state,
                observed_state,
                lifecycle,
                auto_connect,
            )
        ) and all(
            value is _UNSET
            for value in (mount_identity_sha256, safe_error_code, last_checked_at)
        ):
            raise ValidationError("managed share update is empty")

        with self.transaction() as db:
            replay = self._share_mutation_replay_tx(
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.update",
                share_id=normalized_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
            )
            if replay is not None:
                return self._managed_share_mapping(replay)
            row = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_id,)
            ).fetchone()
            if row is None:
                raise CatalogError("share_not_found")
            if int(row["revision"]) != expected_revision:
                raise CatalogError("share_revision_conflict")
            if row["lifecycle"] == "retired":
                raise CatalogError("share_retired")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            next_lifecycle = str(lifecycle or row["lifecycle"])
            next_desired_state = str(desired_state or row["desired_state"])
            lifecycle_operation_action: str | None = None
            lifecycle_operation_key: str | None = None
            lifecycle_operation_fingerprint: str | None = None
            frozen_observed_state = str(row["observed_state"])
            if queue_lifecycle_operation:
                if (
                    next_lifecycle == "active"
                    and next_desired_state == "connected"
                    and frozen_observed_state in {"disconnected", "error"}
                ):
                    lifecycle_operation_action = "connect"
                    observed_state = "connecting"
                elif (
                    next_lifecycle == "disabled"
                    and next_desired_state == "disconnected"
                    and frozen_observed_state == "connected"
                ):
                    lifecycle_operation_action = "disconnect"
                    observed_state = "disconnecting"
                if lifecycle_operation_action is not None:
                    lifecycle_operation_key = (
                        f"{idempotency_key}-{lifecycle_operation_action}"
                    )
                    lifecycle_operation_fingerprint = hashlib.sha256(
                        json.dumps(
                            {
                                "action": lifecycle_operation_action,
                                "expected_revision": expected_revision + 1,
                                "share_id": normalized_id,
                            },
                            ensure_ascii=False,
                            separators=(",", ":"),
                            sort_keys=True,
                        ).encode("utf-8")
                    ).hexdigest()
                    self._validate_share_operation_identity(
                        lifecycle_operation_id,
                        lifecycle_operation_action,
                        actor,
                        lifecycle_operation_key,
                        lifecycle_operation_fingerprint,
                    )
                    if (
                        lifecycle_operation_action == "disconnect"
                        and self._share_has_active_consumer_tx(
                            db, str(row["share_id"])
                        )
                    ):
                        raise CatalogError("share_in_use")
            next_protocol = str(protocol or row["protocol"])
            next_config = str(row["config_json"])
            if config_json is not None:
                next_config = self._canonical_share_config(next_protocol, config_json)
            elif protocol is not None and protocol != row["protocol"]:
                raise ValidationError("protocol change requires matching config")
            endpoint_changed = (
                next_protocol != row["protocol"] or next_config != row["config_json"]
            )
            if endpoint_changed and row["observed_state"] == "connected":
                raise CatalogError("share_connected")
            next_generation = (
                int(row["credential_generation"])
                if credential_generation is None
                else credential_generation
            )
            if next_generation < int(row["credential_generation"]):
                raise ValidationError("credential generation cannot decrease")
            next_configured = (
                bool(row["credential_configured"])
                if credential_configured is None
                else credential_configured
            )
            if next_protocol == "nfs" and (next_generation or next_configured):
                raise ValidationError("NFS shares cannot retain credentials")
            consumer_sensitive = (
                endpoint_changed
                or next_generation != int(row["credential_generation"])
                or next_configured != bool(row["credential_configured"])
                or desired_state is not None
                or observed_state is not None
                or lifecycle is not None
                or mount_identity_sha256 is not _UNSET
            )
            if (
                consumer_sensitive
                and db.execute(
                    "SELECT 1 FROM managed_source_leases "
                    "WHERE share_id=? COLLATE NOCASE LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_in_use")

            assignments = [
                "display_name=?",
                "protocol=?",
                "config_json=?",
                "config_revision=config_revision+?",
                "credential_generation=?",
                "credential_configured=?",
                "desired_state=?",
                "observed_state=?",
                "lifecycle=?",
                "auto_connect=?",
                "revision=revision+1",
                "updated_at=?",
            ]
            values: list[object] = [
                normalized_name or row["display_name"],
                next_protocol,
                next_config,
                int(endpoint_changed),
                next_generation,
                int(next_configured),
                desired_state or row["desired_state"],
                observed_state or row["observed_state"],
                lifecycle or row["lifecycle"],
                int(
                    bool(row["auto_connect"]) if auto_connect is None else auto_connect
                ),
                utc_now(),
            ]
            if lifecycle_operation_action is not None:
                safe_error_code = None
            for column, value in (
                ("mount_identity_sha256", mount_identity_sha256),
                ("safe_error_code", safe_error_code),
                ("last_checked_at", last_checked_at),
            ):
                if value is not _UNSET:
                    assignments.append(f"{column}=?")
                    values.append(value)
            values.append(row["share_id"])
            db.execute(
                f"UPDATE managed_shares SET {','.join(assignments)} WHERE share_id=?",
                tuple(values),
            )
            self._invalidate_managed_share_dependents_tx(db, str(row["share_id"]))
            changed = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (row["share_id"],)
            ).fetchone()
            assert changed is not None
            result = self._managed_share_mapping(changed)
            if lifecycle_operation_action is not None:
                assert lifecycle_operation_id is not None
                assert lifecycle_operation_key is not None
                assert lifecycle_operation_fingerprint is not None
                if (
                    db.execute(
                        "SELECT 1 FROM share_operations "
                        "WHERE operation_id=? OR (actor=? AND idempotency_key=?)",
                        (
                            lifecycle_operation_id,
                            actor,
                            lifecycle_operation_key,
                        ),
                    ).fetchone()
                    is not None
                ):
                    raise CatalogError("idempotency_conflict")
                operation_queued_at = utc_now()
                db.execute(
                    "INSERT INTO share_operations("
                    "operation_id,share_id,actor,action,idempotency_key,"
                    "keyed_request_fingerprint_sha256,expected_share_revision,"
                    "frozen_config_json,frozen_config_revision,"
                    "frozen_credential_generation,frozen_observed_state,state,"
                    "queued_at,started_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'queued',?,?)",
                    (
                        lifecycle_operation_id,
                        changed["share_id"],
                        actor,
                        lifecycle_operation_action,
                        lifecycle_operation_key,
                        lifecycle_operation_fingerprint,
                        result["revision"],
                        changed["config_json"],
                        changed["config_revision"],
                        changed["credential_generation"],
                        frozen_observed_state,
                        operation_queued_at,
                        operation_queued_at,
                    ),
                )
                self._record_share_audit_tx(
                    db,
                    actor=actor,
                    action="share.operation.queue",
                    idempotency_key=lifecycle_operation_key,
                    payload={
                        "share_id": changed["share_id"],
                        "operation_id": lifecycle_operation_id,
                        "operation_action": lifecycle_operation_action,
                        "share_revision": result["revision"],
                    },
                )
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.update",
                target_id=str(row["share_id"]),
                request_fingerprint_sha256=request_fingerprint_sha256,
                response=result,
            )
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.update",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": row["share_id"],
                    "protocol": next_protocol,
                    "previous_revision": expected_revision,
                    "revision": result["revision"],
                    "state_transition": {
                        "from": row["lifecycle"],
                        "to": result["lifecycle"],
                    },
                },
            )
            return result

    def retire_managed_share(
        self,
        share_id: str,
        *,
        expected_revision: int,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
    ) -> dict[str, Any]:
        normalized_id = normalize_share_id(share_id)
        self._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )
        if type(expected_revision) is not int or expected_revision < 1:
            raise ValidationError("invalid expected share revision")
        with self.transaction() as db:
            replay = self._share_mutation_replay_tx(
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.retire",
                share_id=normalized_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
            )
            if replay is not None:
                return self._managed_share_mapping(replay)
            row = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_id,)
            ).fetchone()
            if row is None:
                raise CatalogError("share_not_found")
            if int(row["revision"]) != expected_revision:
                raise CatalogError("share_revision_conflict")
            if row["lifecycle"] == "retired":
                raise CatalogError("share_state_conflict")
            if (
                db.execute(
                    "SELECT 1 FROM library_share_bindings "
                    "WHERE share_id=? COLLATE NOCASE LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_in_use")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations "
                    "WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            if row["desired_state"] != "disconnected" or row["observed_state"] not in {
                "disconnected",
                "error",
            }:
                raise CatalogError("share_connected")
            now = utc_now()
            db.execute(
                "UPDATE managed_shares SET lifecycle='retired',auto_connect=0,"
                "revision=revision+1,updated_at=? WHERE share_id=?",
                (now, row["share_id"]),
            )
            retired = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (row["share_id"],)
            ).fetchone()
            assert retired is not None
            result = self._managed_share_mapping(retired)
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.retire",
                target_id=str(row["share_id"]),
                request_fingerprint_sha256=request_fingerprint_sha256,
                response=result,
            )
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.retire",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": row["share_id"],
                    "protocol": row["protocol"],
                    "previous_revision": expected_revision,
                    "revision": result["revision"],
                    "state_transition": {
                        "from": row["lifecycle"],
                        "to": "retired",
                    },
                },
            )
            return result

    def finalize_managed_share_removal(
        self,
        share_id: str,
        *,
        expected_revision: int,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
    ) -> dict[str, Any]:
        """Hide a fully cleaned retired share without deleting its history."""

        normalized_id = normalize_share_id(share_id)
        self._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )
        if type(expected_revision) is not int or expected_revision < 1:
            raise ValidationError("invalid expected share revision")
        with self.transaction() as db:
            replay = self._share_mutation_replay_tx(
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.remove",
                share_id=normalized_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
            )
            if replay is not None:
                return self._managed_share_mapping(replay)
            row = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_id,)
            ).fetchone()
            if row is None or row["removed_at"] is not None:
                raise CatalogError("share_not_found")
            if int(row["revision"]) != expected_revision:
                raise CatalogError("share_revision_conflict")
            if row["lifecycle"] != "retired":
                raise CatalogError("share_state_conflict")
            if (
                db.execute(
                    "SELECT 1 FROM library_share_bindings WHERE share_id=? COLLATE NOCASE "
                    "LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_in_use")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (row["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            if (
                row["desired_state"] != "disconnected"
                or row["observed_state"] not in {"disconnected", "error"}
                or bool(row["credential_configured"])
                or row["mount_identity_sha256"] is not None
                or row["mounted_config_revision"] is not None
                or row["mounted_credential_generation"] is not None
            ):
                raise CatalogError("share_state_conflict")
            now = utc_now()
            db.execute(
                "UPDATE managed_shares SET removed_at=?,revision=revision+1,"
                "updated_at=? WHERE share_id=?",
                (now, now, row["share_id"]),
            )
            removed = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (row["share_id"],)
            ).fetchone()
            assert removed is not None
            result = self._managed_share_mapping(removed)
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.remove",
                target_id=str(row["share_id"]),
                request_fingerprint_sha256=request_fingerprint_sha256,
                response=result,
            )
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.remove",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": row["share_id"],
                    "protocol": row["protocol"],
                    "previous_revision": expected_revision,
                    "revision": result["revision"],
                },
            )
            return result

    @staticmethod
    def _normalize_share_relative_subpath(value: object) -> str:
        if value == "":
            return ""
        return normalize_managed_source_subpath(value)

    def bind_library_to_share(
        self,
        library_id: str,
        share_id: str,
        relative_subpath: str,
        *,
        expected_share_revision: int,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
    ) -> dict[str, Any]:
        validate_id(library_id, "library ID")
        normalized_share_id = normalize_share_id(share_id)
        normalized_subpath = self._normalize_share_relative_subpath(relative_subpath)
        self._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )
        if type(expected_share_revision) is not int or expected_share_revision < 1:
            raise ValidationError("invalid expected share revision")
        target_id = self._library_share_receipt_target(library_id, normalized_share_id)
        with self.transaction() as db:
            replay = self.management_idempotency_replay(
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.bind_library",
                target_id=target_id,
                request_sha256=request_fingerprint_sha256,
            )
            if replay is not None:
                return self._library_share_binding_mapping(replay)
            library = db.execute(
                "SELECT * FROM libraries WHERE id=? COLLATE NOCASE", (library_id,)
            ).fetchone()
            if library is None:
                raise CatalogError("library_not_found")
            if library["status"] == "retired":
                raise CatalogError("library_state_conflict")
            share = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_share_id,)
            ).fetchone()
            if share is None:
                raise CatalogError("share_not_found")
            if int(share["revision"]) != expected_share_revision:
                raise CatalogError("share_revision_conflict")
            if share["lifecycle"] != "active":
                raise CatalogError("share_inactive")
            if (
                db.execute(
                    "SELECT 1 FROM library_share_bindings "
                    "WHERE library_id=? COLLATE NOCASE",
                    (library["id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("library_share_binding_exists")
            now = utc_now()
            db.execute(
                "INSERT INTO library_share_bindings("
                "library_id,share_id,relative_subpath,bound_share_revision,"
                "created_at,updated_at) VALUES(?,?,?,?,?,?)",
                (
                    library["id"],
                    share["share_id"],
                    normalized_subpath,
                    share["revision"],
                    now,
                    now,
                ),
            )
            db.execute(
                "UPDATE libraries SET source_kind='network' WHERE id=?",
                (library["id"],),
            )
            binding = db.execute(
                "SELECT * FROM library_share_bindings WHERE library_id=?",
                (library["id"],),
            ).fetchone()
            assert binding is not None
            result = self._library_share_binding_mapping(binding)
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action="share.bind_library",
                target_id=target_id,
                request_fingerprint_sha256=request_fingerprint_sha256,
                response=result,
            )
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.bind_library",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": share["share_id"],
                    "library_id": library["id"],
                    "share_revision": share["revision"],
                },
            )
            return result

    @staticmethod
    def _library_share_receipt_target(library_id: str, share_id: str) -> str:
        normalized_pair = json.dumps(
            {
                "library_id": library_id.casefold(),
                "share_id": share_id.casefold(),
            },
            ensure_ascii=True,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
        digest = hashlib.sha256(
            b"lto-library-share-binding-target-v1\0" + normalized_pair
        ).hexdigest()
        return f"library-share-{digest}"

    @staticmethod
    def _validate_share_operation_identity(
        operation_id: object,
        action: object,
        actor: object,
        idempotency_key: object,
        request_fingerprint_sha256: object,
    ) -> None:
        for value, name in (
            (operation_id, "share operation ID"),
            (action, "share operation action"),
            (actor, "share operation actor"),
        ):
            Catalog._validate_safe_identifier(value, name)
        if (
            not isinstance(idempotency_key, str)
            or not idempotency_key.strip()
            or len(idempotency_key) > 128
            or any(
                ord(character) < 32 or ord(character) == 127
                for character in idempotency_key
            )
        ):
            raise ValidationError("invalid idempotency key")
        Catalog._validate_sha256(
            request_fingerprint_sha256, "keyed share request fingerprint"
        )

    def begin_share_operation(
        self,
        operation_id: str,
        share_id: str,
        action: str,
        *,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
        expected_share_revision: int,
    ) -> dict[str, Any]:
        normalized_share_id = normalize_share_id(share_id)
        self._validate_share_operation_identity(
            operation_id,
            action,
            actor,
            idempotency_key,
            request_fingerprint_sha256,
        )
        if type(expected_share_revision) is not int or expected_share_revision < 1:
            raise ValidationError("invalid expected share revision")
        with self.transaction() as db:
            replay = db.execute(
                "SELECT * FROM share_operations WHERE actor=? AND idempotency_key=?",
                (actor, idempotency_key),
            ).fetchone()
            if replay is not None:
                if (
                    str(replay["share_id"]).casefold() != normalized_share_id.casefold()
                    or replay["action"] != action
                    or replay["keyed_request_fingerprint_sha256"]
                    != request_fingerprint_sha256
                    or replay["expected_share_revision"] != expected_share_revision
                ):
                    raise CatalogError("idempotency_conflict")
                return self._share_operation_mapping(replay)
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_operation_exists")
            share = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (normalized_share_id,)
            ).fetchone()
            if share is None:
                raise CatalogError("share_not_found")
            if int(share["revision"]) != expected_share_revision:
                raise CatalogError("share_revision_conflict")
            if share["lifecycle"] == "retired":
                raise CatalogError("share_retired")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (share["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            now = utc_now()
            db.execute(
                "INSERT INTO share_operations("
                "operation_id,share_id,actor,action,idempotency_key,"
                "keyed_request_fingerprint_sha256,expected_share_revision,"
                "frozen_config_json,frozen_config_revision,"
                "frozen_credential_generation,frozen_observed_state,"
                "state,owner_id,queued_at,started_at,claimed_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,'running',"
                "'legacy-direct-admission',?,?,?)",
                (
                    operation_id,
                    share["share_id"],
                    actor,
                    action,
                    idempotency_key,
                    request_fingerprint_sha256,
                    expected_share_revision,
                    share["config_json"],
                    share["config_revision"],
                    share["credential_generation"],
                    share["observed_state"],
                    now,
                    now,
                    now,
                ),
            )
            created = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?", (operation_id,)
            ).fetchone()
            assert created is not None
            result = self._share_operation_mapping(created)
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.operation.begin",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": share["share_id"],
                    "operation_id": operation_id,
                    "operation_action": action,
                    "share_revision": expected_share_revision,
                },
            )
            return result

    def get_share_operation(self, operation_id: str) -> dict[str, Any]:
        self._validate_safe_identifier(operation_id, "share operation ID")
        row = self.connection.execute(
            "SELECT * FROM share_operations WHERE operation_id=?", (operation_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("share_operation_not_found")
        return self._share_operation_mapping(row)

    def replay_share_operation(
        self,
        *,
        share_id: str,
        action: str,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
        expected_share_revision: int,
    ) -> dict[str, Any] | None:
        """Resolve exact replay without consulting current mutable share state."""

        normalized_share_id = normalize_share_id(share_id)
        self._validate_share_operation_identity(
            "share-replay-probe",
            action,
            actor,
            idempotency_key,
            request_fingerprint_sha256,
        )
        row = self.connection.execute(
            "SELECT * FROM share_operations WHERE actor=? AND idempotency_key=?",
            (actor, idempotency_key),
        ).fetchone()
        if row is None:
            return None
        if (
            str(row["share_id"]).casefold() != normalized_share_id.casefold()
            or row["action"] != action
            or row["keyed_request_fingerprint_sha256"] != request_fingerprint_sha256
            or int(row["expected_share_revision"]) != expected_share_revision
        ):
            raise CatalogError("idempotency_conflict")
        return self._share_operation_mapping(row)

    def queue_share_operation(
        self,
        operation_id: str,
        share_id: str,
        action: str,
        *,
        actor: str,
        idempotency_key: str,
        request_fingerprint_sha256: str,
        expected_share_revision: int,
        desired_state: Literal["connected", "disconnected"] | None = None,
        observed_state: Literal[
            "disconnected", "connecting", "connected", "disconnecting", "error"
        ]
        | None = None,
        require_no_consumers: bool = False,
    ) -> dict[str, Any]:
        """Durably admit one queued share operation and optional observed transition."""

        normalized_share_id = normalize_share_id(share_id)
        self._validate_share_operation_identity(
            operation_id,
            action,
            actor,
            idempotency_key,
            request_fingerprint_sha256,
        )
        if type(expected_share_revision) is not int or expected_share_revision < 1:
            raise ValidationError("invalid expected share revision")
        if desired_state not in {None, "connected", "disconnected"}:
            raise ValidationError("invalid desired share state")
        if observed_state not in {
            None,
            "disconnected",
            "connecting",
            "connected",
            "disconnecting",
            "error",
        }:
            raise ValidationError("invalid observed share state")
        if type(require_no_consumers) is not bool:
            raise ValidationError("invalid share consumer guard")
        with self.transaction() as db:
            replay = db.execute(
                "SELECT * FROM share_operations WHERE actor=? AND idempotency_key=?",
                (actor, idempotency_key),
            ).fetchone()
            if replay is not None:
                if (
                    str(replay["share_id"]).casefold() != normalized_share_id.casefold()
                    or replay["action"] != action
                    or replay["keyed_request_fingerprint_sha256"]
                    != request_fingerprint_sha256
                    or int(replay["expected_share_revision"]) != expected_share_revision
                ):
                    raise CatalogError("idempotency_conflict")
                return self._share_operation_mapping(replay)
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_operation_exists")
            share = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?",
                (normalized_share_id,),
            ).fetchone()
            if share is None or share["removed_at"] is not None:
                raise CatalogError("share_not_found")
            if int(share["revision"]) != expected_share_revision:
                raise CatalogError("share_revision_conflict")
            if share["lifecycle"] == "retired":
                raise CatalogError("share_retired")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (share["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            if require_no_consumers and self._share_has_active_consumer_tx(
                db, str(share["share_id"])
            ):
                raise CatalogError("share_in_use")
            now = utc_now()
            db.execute(
                "INSERT INTO share_operations("
                "operation_id,share_id,actor,action,idempotency_key,"
                "keyed_request_fingerprint_sha256,expected_share_revision,"
                "frozen_config_json,frozen_config_revision,"
                "frozen_credential_generation,frozen_observed_state,state,"
                "queued_at,started_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'queued',?,?)",
                (
                    operation_id,
                    share["share_id"],
                    actor,
                    action,
                    idempotency_key,
                    request_fingerprint_sha256,
                    expected_share_revision,
                    share["config_json"],
                    share["config_revision"],
                    share["credential_generation"],
                    share["observed_state"],
                    now,
                    now,
                ),
            )
            assignments = ["safe_error_code=NULL", "updated_at=?"]
            values: list[object] = [now]
            if desired_state is not None:
                assignments.append("desired_state=?")
                values.append(desired_state)
            if observed_state is not None:
                assignments.append("observed_state=?")
                values.append(observed_state)
            values.append(share["share_id"])
            db.execute(
                f"UPDATE managed_shares SET {','.join(assignments)} WHERE share_id=?",
                tuple(values),
            )
            created = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            assert created is not None
            result = self._share_operation_mapping(created)
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.operation.queue",
                idempotency_key=idempotency_key,
                payload={
                    "share_id": share["share_id"],
                    "operation_id": operation_id,
                    "operation_action": action,
                    "share_revision": expected_share_revision,
                },
            )
            return result

    def claim_share_operation(
        self, operation_id: str, *, owner_id: str
    ) -> dict[str, Any]:
        self._validate_safe_identifier(operation_id, "share operation ID")
        self._validate_safe_identifier(owner_id, "share operation owner")
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if row is None:
                raise CatalogError("share_operation_not_found")
            if row["state"] == "running" and row["owner_id"] == owner_id:
                return self._share_operation_mapping(row)
            if row["state"] != "queued":
                raise CatalogError("share_operation_conflict")
            now = utc_now()
            db.execute(
                "UPDATE share_operations SET state='running',owner_id=?,"
                "claimed_at=?,started_at=? WHERE operation_id=? AND state='queued'",
                (owner_id, now, now, row["operation_id"]),
            )
            claimed = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (row["operation_id"],),
            ).fetchone()
            assert claimed is not None
            return self._share_operation_mapping(claimed)

    def mark_share_operation_recovering(
        self,
        operation_id: str,
        *,
        owner_id: str,
        recovery_deadline: str,
    ) -> dict[str, Any]:
        self._validate_safe_identifier(operation_id, "share operation ID")
        self._validate_safe_identifier(owner_id, "share operation owner")
        if self._parse_utc_timestamp(recovery_deadline) is None:
            raise ValidationError("invalid share recovery deadline")
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if row is None:
                raise CatalogError("share_operation_not_found")
            if row["state"] == "recovering" and row["owner_id"] == owner_id:
                return self._share_operation_mapping(row)
            if row["state"] != "running" or row["owner_id"] != owner_id:
                raise CatalogError("share_operation_conflict")
            now = utc_now()
            db.execute(
                "UPDATE share_operations SET state='recovering',"
                "safe_error_code='share_recovery_required',recovery_deadline=? "
                "WHERE operation_id=?",
                (recovery_deadline, row["operation_id"]),
            )
            db.execute(
                "UPDATE managed_shares SET observed_state='error',"
                "safe_error_code='share_recovery_required',updated_at=? "
                "WHERE share_id=?",
                (now, row["share_id"]),
            )
            recovering = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (row["operation_id"],),
            ).fetchone()
            assert recovering is not None
            return self._share_operation_mapping(recovering)

    def get_current_share_operation(self, share_id: str) -> dict[str, Any] | None:
        normalized_share_id = normalize_share_id(share_id)
        row = self.connection.execute(
            "SELECT * FROM share_operations WHERE share_id=? COLLATE NOCASE "
            "AND state IN ('queued','running','recovering') ORDER BY rowid DESC LIMIT 1",
            (normalized_share_id,),
        ).fetchone()
        return None if row is None else self._share_operation_mapping(row)

    def get_latest_share_operation(self, share_id: str) -> dict[str, Any] | None:
        normalized_share_id = normalize_share_id(share_id)
        row = self.connection.execute(
            "SELECT * FROM share_operations WHERE share_id=? COLLATE NOCASE "
            "ORDER BY rowid DESC LIMIT 1",
            (normalized_share_id,),
        ).fetchone()
        return None if row is None else self._share_operation_mapping(row)

    def share_has_active_library_consumer(self, share_id: str) -> bool:
        normalized_id = normalize_share_id(share_id)
        return self._share_has_active_consumer_tx(self.connection, normalized_id)

    @staticmethod
    def _invalidate_managed_share_dependents_tx(
        db: sqlite3.Connection, share_id: str
    ) -> None:
        library_ids = [
            str(row["library_id"])
            for row in db.execute(
                "SELECT library_id FROM library_share_bindings "
                "WHERE share_id=? COLLATE NOCASE",
                (share_id,),
            )
        ]
        now = utc_now()
        for library_id in library_ids:
            db.execute(
                "DELETE FROM library_share_scan_evidence WHERE library_id=?",
                (library_id,),
            )
            db.execute(
                "UPDATE libraries SET scan_state='never' WHERE id=? "
                "AND scan_state='ready'",
                (library_id,),
            )
            db.execute(
                "UPDATE job_plan_drafts SET state='expired',updated_at=? "
                "WHERE state='ready' AND EXISTS("
                "SELECT 1 FROM job_plan_libraries AS plan_library "
                "WHERE plan_library.plan_id=job_plan_drafts.id "
                "AND plan_library.library_id=? COLLATE NOCASE)",
                (now, library_id),
            )

    @staticmethod
    def _managed_source_evidence_matches_share_tx(
        db: sqlite3.Connection, evidence: Mapping[str, Any]
    ) -> bool:
        share = db.execute(
            "SELECT * FROM managed_shares WHERE share_id=? COLLATE NOCASE",
            (evidence["share_id"],),
        ).fetchone()
        return bool(
            share is not None
            and share["removed_at"] is None
            and share["lifecycle"] == "active"
            and share["desired_state"] == "connected"
            and share["observed_state"] == "connected"
            and int(share["revision"]) == int(evidence["resource_revision"])
            and int(share["config_revision"]) == int(evidence["config_revision"])
            and int(share["mounted_config_revision"] or 0)
            == int(evidence["config_revision"])
            and int(share["credential_generation"])
            == int(evidence["credential_generation"])
            and share["mounted_credential_generation"] is not None
            and int(share["mounted_credential_generation"])
            == int(evidence["credential_generation"])
            and share["mount_identity_sha256"] == evidence["mount_identity_sha256"]
        )

    def acquire_managed_source_lease(
        self,
        share_id: str,
        *,
        consumer_kind: Literal["scan", "plan", "save", "worker"],
        consumer_id: str,
        owner_id: str,
        daemon_generation: int,
    ) -> str:
        normalized_id = normalize_share_id(share_id)
        if consumer_kind not in {"scan", "plan", "save", "worker"}:
            raise ValidationError("invalid managed source lease consumer")
        self._validate_safe_identifier(consumer_id, "managed source consumer")
        self._validate_safe_identifier(owner_id, "managed source lease owner")
        if type(daemon_generation) is not int or daemon_generation < 0:
            raise ValidationError("invalid managed source lease generation")
        lease_id = f"source-lease-{uuid.uuid4().hex}"
        with self.transaction() as db:
            share = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=? COLLATE NOCASE",
                (normalized_id,),
            ).fetchone()
            if (
                share is None
                or share["removed_at"] is not None
                or share["lifecycle"] != "active"
                or share["desired_state"] != "connected"
                or share["observed_state"] != "connected"
            ):
                raise CatalogError("share_identity_changed")
            if (
                db.execute(
                    "SELECT 1 FROM share_operations WHERE share_id=? COLLATE NOCASE "
                    "AND state IN ('queued','running','recovering') LIMIT 1",
                    (share["share_id"],),
                ).fetchone()
                is not None
            ):
                raise CatalogError("share_busy")
            db.execute(
                "INSERT INTO managed_source_leases("
                "lease_id,share_id,consumer_kind,consumer_id,owner_id,"
                "daemon_generation,created_at) VALUES(?,?,?,?,?,?,?)",
                (
                    lease_id,
                    share["share_id"],
                    consumer_kind,
                    consumer_id,
                    owner_id,
                    daemon_generation,
                    utc_now(),
                ),
            )
        return lease_id

    def release_managed_source_lease(
        self,
        lease_id: str,
        *,
        owner_id: str,
        daemon_generation: int,
    ) -> None:
        self._validate_safe_identifier(lease_id, "managed source lease")
        self._validate_safe_identifier(owner_id, "managed source lease owner")
        if type(daemon_generation) is not int or daemon_generation < 0:
            raise ValidationError("invalid managed source lease generation")
        with self.transaction() as db:
            cursor = db.execute(
                "DELETE FROM managed_source_leases WHERE lease_id=? "
                "AND owner_id=? AND daemon_generation=?",
                (lease_id, owner_id, daemon_generation),
            )
            if cursor.rowcount != 1:
                raise CatalogError("managed_source_lease_lost")

    def recover_stale_managed_source_leases(
        self, *, owner_id: str, daemon_generation: int
    ) -> int:
        self._validate_safe_identifier(owner_id, "managed source lease owner")
        if type(daemon_generation) is not int or daemon_generation < 0:
            raise ValidationError("invalid managed source lease generation")
        with self.transaction() as db:
            cursor = db.execute(
                "DELETE FROM managed_source_leases "
                "WHERE owner_id<>? OR daemon_generation<>?",
                (owner_id, daemon_generation),
            )
        return int(cursor.rowcount)

    def record_operation_share_evidence(
        self,
        operation_id: str,
        evidence_by_library: Mapping[str, Mapping[str, Any]],
        lease_by_library: Mapping[str, str],
    ) -> None:
        self._validate_safe_identifier(operation_id, "managed source operation")
        normalized_evidence = {
            library_id.casefold(): canonical_managed_source_evidence(evidence)
            for library_id, evidence in evidence_by_library.items()
        }
        if set(normalized_evidence) != set(lease_by_library):
            raise ValidationError("incomplete operation managed source evidence")
        with self.transaction() as db:
            operation = db.execute(
                "SELECT 1 FROM daemon_operations WHERE id=? AND state IN ("
                "'running','recovery_required')",
                (operation_id,),
            ).fetchone()
            if operation is None:
                raise CatalogError("operation_not_admitted")
            for library_id, evidence in normalized_evidence.items():
                lease = db.execute(
                    "SELECT * FROM managed_source_leases WHERE lease_id=? "
                    "AND consumer_kind='worker'",
                    (lease_by_library[library_id],),
                ).fetchone()
                if (
                    lease is None
                    or str(lease["share_id"]).casefold()
                    != str(evidence["share_id"]).casefold()
                    or not self._managed_source_evidence_matches_share_tx(db, evidence)
                ):
                    raise CatalogError("managed_source_lease_lost")
                encoded = json.dumps(
                    evidence,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                db.execute(
                    "INSERT INTO operation_share_evidence("
                    "operation_id,library_id,share_id,evidence_json,evidence_sha256,"
                    "admitted_at) VALUES(?,?,?,?,?,?)",
                    (
                        operation_id,
                        library_id,
                        evidence["share_id"],
                        encoded,
                        hashlib.sha256(
                            b"lto-managed-source-evidence-v1\0"
                            + encoded.encode("utf-8")
                        ).hexdigest(),
                        utc_now(),
                    ),
                )

    @staticmethod
    def _share_has_active_consumer_tx(db: sqlite3.Connection, share_id: str) -> bool:
        return (
            db.execute(
                "SELECT 1 FROM managed_source_leases "
                "WHERE share_id=? COLLATE NOCASE LIMIT 1",
                (share_id,),
            ).fetchone()
            is not None
            or db.execute(
                "SELECT 1 FROM library_share_bindings AS binding "
                "JOIN libraries AS library ON library.id=binding.library_id "
                "WHERE binding.share_id=? COLLATE NOCASE AND ("
                "library.scan_state='running' OR "
                "EXISTS(SELECT 1 FROM job_plan_drafts AS building_plan "
                "JOIN json_each(building_plan.requested_library_ids_json) AS item "
                "WHERE building_plan.state='building' "
                "AND item.value=library.id COLLATE NOCASE) OR "
                "EXISTS(SELECT 1 FROM automatic_job_libraries AS job_library "
                "JOIN daemon_operations AS operation "
                "ON operation.job_id=job_library.job_id "
                "WHERE job_library.library_id=library.id COLLATE NOCASE "
                "AND operation.kind IN ('archive.native','archive.resume') "
                "AND operation.state IN ('running','recovery_required'))"
                ") LIMIT 1",
                (share_id,),
            ).fetchone()
            is not None
        )

    def recover_interrupted_share_operations(
        self, *, owner_id: str
    ) -> tuple[dict[str, Any], ...]:
        self._validate_safe_identifier(owner_id, "share recovery owner")
        with self.transaction() as db:
            rows = db.execute(
                "SELECT * FROM share_operations "
                "WHERE state IN ('queued','running','recovering') "
                "ORDER BY rowid"
            ).fetchall()
            recovered: list[dict[str, Any]] = []
            for row in rows:
                now = utc_now()
                db.execute(
                    "UPDATE share_operations SET state='recovering',owner_id=?,"
                    "safe_error_code='share_recovery_required',receipt_sha256=NULL,"
                    "claimed_at=COALESCE(claimed_at,?),recovered_at=? "
                    "WHERE operation_id=?",
                    (owner_id, now, now, row["operation_id"]),
                )
                db.execute(
                    "UPDATE managed_shares SET observed_state='error',"
                    "safe_error_code='share_recovery_required',updated_at=? "
                    "WHERE share_id=?",
                    (now, row["share_id"]),
                )
                finished = db.execute(
                    "SELECT * FROM share_operations WHERE operation_id=?",
                    (row["operation_id"],),
                ).fetchone()
                assert finished is not None
                recovered.append(self._share_operation_mapping(finished))
                self._record_share_audit_tx(
                    db,
                    actor=owner_id,
                    action="share.operation.recover",
                    idempotency_key=str(row["idempotency_key"]),
                    payload={
                        "share_id": row["share_id"],
                        "operation_id": row["operation_id"],
                        "operation_action": row["action"],
                        "safe_error_code": "share_recovery_required",
                    },
                )
            return tuple(recovered)

    def record_managed_share_observation(
        self,
        share_id: str,
        *,
        actor: str,
        observed_state: Literal["disconnected", "connected", "error"],
        safe_error_code: str | None,
        mount_identity_sha256: str | None,
        mounted_config_revision: int | None,
        mounted_credential_generation: int | None,
        checked_at: str,
    ) -> dict[str, Any]:
        """Persist startup/kernel evidence without mutating resource revision."""

        normalized_id = normalize_share_id(share_id)
        self._validate_safe_identifier(actor, "share reconciliation actor")
        safe_error_code = validate_share_safe_error_code(safe_error_code)
        if observed_state not in {"disconnected", "connected", "error"}:
            raise ValidationError("invalid reconciled share state")
        if mount_identity_sha256 is not None:
            self._validate_sha256(mount_identity_sha256, "share mount identity")
        if self._parse_utc_timestamp(checked_at) is None:
            raise ValidationError("invalid share health timestamp")
        has_any_evidence = any(
            value is not None
            for value in (
                mount_identity_sha256,
                mounted_config_revision,
                mounted_credential_generation,
            )
        )
        has_complete_evidence = (
            mount_identity_sha256 is not None
            and type(mounted_config_revision) is int
            and mounted_config_revision >= 1
            and type(mounted_credential_generation) is int
            and mounted_credential_generation >= 0
        )
        if observed_state == "connected":
            if not has_complete_evidence:
                raise ValidationError("connected share evidence is incomplete")
        elif observed_state == "disconnected" and has_any_evidence:
            raise ValidationError("unmounted share cannot retain mount evidence")
        elif (
            observed_state == "error" and has_any_evidence and not has_complete_evidence
        ):
            raise ValidationError("failed share evidence is incomplete")
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=? AND removed_at IS NULL",
                (normalized_id,),
            ).fetchone()
            if row is None:
                raise CatalogError("share_not_found")
            db.execute(
                "UPDATE managed_shares SET observed_state=?,safe_error_code=?,"
                "mount_identity_sha256=?,mounted_config_revision=?,"
                "mounted_credential_generation=?,last_checked_at=?,updated_at=? "
                "WHERE share_id=?",
                (
                    observed_state,
                    safe_error_code,
                    mount_identity_sha256,
                    mounted_config_revision,
                    mounted_credential_generation,
                    checked_at,
                    utc_now(),
                    row["share_id"],
                ),
            )
            if (
                observed_state != row["observed_state"]
                or mount_identity_sha256 != row["mount_identity_sha256"]
                or mounted_config_revision != row["mounted_config_revision"]
                or mounted_credential_generation != row["mounted_credential_generation"]
            ):
                self._invalidate_managed_share_dependents_tx(db, str(row["share_id"]))
            observed = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?", (row["share_id"],)
            ).fetchone()
            assert observed is not None
            result = self._managed_share_mapping(observed)
            self._record_share_audit_tx(
                db,
                actor=actor,
                action="share.reconcile.observe",
                idempotency_key=f"reconcile-{uuid.uuid4().hex}",
                payload={
                    "share_id": row["share_id"],
                    "observed_state": observed_state,
                    "safe_error_code": safe_error_code,
                    "share_revision": row["revision"],
                },
            )
            return result

    def finish_share_operation(
        self,
        operation_id: str,
        *,
        state: Literal["succeeded", "failed"],
        receipt_sha256: str | None,
        safe_error_code: str | None = None,
        desired_state: Literal["connected", "disconnected"] | None = None,
        observed_state: Literal[
            "disconnected", "connecting", "connected", "disconnecting", "error"
        ]
        | None = None,
        mount_identity_sha256: object = _UNSET,
        mounted_config_revision: object = _UNSET,
        mounted_credential_generation: object = _UNSET,
        credential_generation: int | None = None,
        credential_configured: bool | None = None,
        last_checked_at: object = _UNSET,
        increment_resource_revision: bool = False,
    ) -> dict[str, Any]:
        self._validate_safe_identifier(operation_id, "share operation ID")
        if state not in {"succeeded", "failed"}:
            raise ValidationError("invalid terminal share operation state")
        if receipt_sha256 is not None:
            self._validate_sha256(receipt_sha256, "share operation receipt")
        if state == "succeeded" and safe_error_code is not None:
            raise ValidationError("successful share operation cannot have an error")
        if state == "succeeded" and receipt_sha256 is None:
            raise ValidationError("successful share operation requires a receipt")
        if state == "failed":
            safe_error_code = validate_share_safe_error_code(safe_error_code)
            if safe_error_code is None:
                raise ValidationError("failed share operation requires a safe error")
        if desired_state not in {None, "connected", "disconnected"}:
            raise ValidationError("invalid desired share state")
        if observed_state not in {
            None,
            "disconnected",
            "connecting",
            "connected",
            "disconnecting",
            "error",
        }:
            raise ValidationError("invalid observed share state")
        if mount_identity_sha256 is not _UNSET and mount_identity_sha256 is not None:
            self._validate_sha256(mount_identity_sha256, "share mount identity")
        if mounted_config_revision is not _UNSET and (
            mounted_config_revision is not None
            and (
                type(mounted_config_revision) is not int or mounted_config_revision < 1
            )
        ):
            raise ValidationError("invalid mounted config revision")
        if mounted_credential_generation is not _UNSET and (
            mounted_credential_generation is not None
            and (
                type(mounted_credential_generation) is not int
                or mounted_credential_generation < 0
            )
        ):
            raise ValidationError("invalid mounted credential generation")
        if credential_generation is not None and (
            type(credential_generation) is not int or credential_generation < 0
        ):
            raise ValidationError("invalid credential generation")
        if (
            credential_configured is not None
            and type(credential_configured) is not bool
        ):
            raise ValidationError("invalid credential state")
        if (
            last_checked_at is not _UNSET
            and last_checked_at is not None
            and self._parse_utc_timestamp(last_checked_at) is None
        ):
            raise ValidationError("invalid share health timestamp")
        if type(increment_resource_revision) is not bool:
            raise ValidationError("invalid resource revision transition")
        with self.transaction() as db:
            row = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?", (operation_id,)
            ).fetchone()
            if row is None:
                raise CatalogError("share_operation_not_found")
            if row["state"] not in {"running", "recovering"}:
                if (
                    row["state"] == state
                    and row["safe_error_code"] == safe_error_code
                    and row["receipt_sha256"] == receipt_sha256
                ):
                    return self._share_operation_mapping(row)
                raise CatalogError("share_operation_conflict")
            share = db.execute(
                "SELECT * FROM managed_shares WHERE share_id=?",
                (row["share_id"],),
            ).fetchone()
            if share is None:
                raise CatalogError("share_not_found")
            candidate_identity = (
                share["mount_identity_sha256"]
                if mount_identity_sha256 is _UNSET
                else mount_identity_sha256
            )
            candidate_config_revision = (
                share["mounted_config_revision"]
                if mounted_config_revision is _UNSET
                else mounted_config_revision
            )
            candidate_credential_generation = (
                share["mounted_credential_generation"]
                if mounted_credential_generation is _UNSET
                else mounted_credential_generation
            )
            candidate_observed = observed_state or str(share["observed_state"])
            if candidate_observed == "connected" and (
                candidate_identity is None
                or candidate_config_revision is None
                or candidate_credential_generation is None
            ):
                raise ValidationError(
                    "connected share requires complete mount evidence"
                )
            if candidate_observed == "disconnected" and any(
                value is not None
                for value in (
                    candidate_identity,
                    candidate_config_revision,
                    candidate_credential_generation,
                )
            ):
                raise ValidationError("disconnected share cannot retain mount evidence")
            next_credential_generation = (
                int(share["credential_generation"])
                if credential_generation is None
                else credential_generation
            )
            next_credential_configured = (
                bool(share["credential_configured"])
                if credential_configured is None
                else credential_configured
            )
            if next_credential_generation < int(share["credential_generation"]):
                raise ValidationError("credential generation cannot decrease")
            if share["protocol"] == "nfs" and (
                next_credential_generation or next_credential_configured
            ):
                raise ValidationError("NFS shares cannot retain credentials")
            now = utc_now()
            db.execute(
                "UPDATE share_operations SET state=?,safe_error_code=?,"
                "receipt_sha256=?,finished_at=? WHERE operation_id=?",
                (state, safe_error_code, receipt_sha256, now, row["operation_id"]),
            )
            assignments = [
                "safe_error_code=?",
                "credential_generation=?",
                "credential_configured=?",
                "revision=revision+?",
                "updated_at=?",
            ]
            values: list[object] = [
                safe_error_code,
                next_credential_generation,
                int(next_credential_configured),
                int(increment_resource_revision),
                now,
            ]
            for column, value in (
                ("desired_state", desired_state),
                ("observed_state", observed_state),
                ("mount_identity_sha256", mount_identity_sha256),
                ("mounted_config_revision", mounted_config_revision),
                ("mounted_credential_generation", mounted_credential_generation),
                ("last_checked_at", last_checked_at),
            ):
                if value is not None and value is not _UNSET:
                    assignments.append(f"{column}=?")
                    values.append(value)
                elif value is None and column in {
                    "mount_identity_sha256",
                    "mounted_config_revision",
                    "mounted_credential_generation",
                    "last_checked_at",
                }:
                    assignments.append(f"{column}=NULL")
            values.append(row["share_id"])
            db.execute(
                f"UPDATE managed_shares SET {','.join(assignments)} WHERE share_id=?",
                tuple(values),
            )
            if (
                increment_resource_revision
                or next_credential_generation != int(share["credential_generation"])
                or next_credential_configured != bool(share["credential_configured"])
                or candidate_observed != share["observed_state"]
                or candidate_identity != share["mount_identity_sha256"]
                or candidate_config_revision != share["mounted_config_revision"]
                or candidate_credential_generation
                != share["mounted_credential_generation"]
            ):
                self._invalidate_managed_share_dependents_tx(db, str(row["share_id"]))
            finished = db.execute(
                "SELECT * FROM share_operations WHERE operation_id=?",
                (row["operation_id"],),
            ).fetchone()
            assert finished is not None
            result = self._share_operation_mapping(finished)
            self._record_share_audit_tx(
                db,
                actor=str(row["actor"]),
                action="share.operation.finish",
                idempotency_key=str(row["idempotency_key"]),
                payload={
                    "share_id": row["share_id"],
                    "operation_id": row["operation_id"],
                    "operation_action": row["action"],
                    "share_revision": row["expected_share_revision"],
                    "state": state,
                    "safe_error_code": safe_error_code,
                },
            )
            return result

    def get_library(
        self, library_id: str, include_retired: bool = False
    ) -> sqlite3.Row:
        query = "SELECT * FROM libraries WHERE id=?"
        params: tuple[Any, ...] = (library_id,)
        if not include_retired:
            query += " AND status='active'"
        row = self.connection.execute(query, params).fetchone()
        if row is None:
            raise CatalogError(f"Libreria non trovata o ritirata: {library_id}")
        return row

    def list_libraries(self, include_retired: bool = False) -> list[sqlite3.Row]:
        query = "SELECT * FROM libraries"
        if not include_retired:
            query += " WHERE status='active'"
        query += " ORDER BY id COLLATE NOCASE"
        return list(self.connection.execute(query))

    def update_library_scan(
        self, library_id: str, total_files: int, total_bytes: int
    ) -> None:
        if total_files < 0 or total_bytes < 0:
            raise ValidationError("Dimensione o numero file della libreria non validi")
        scanned_at = utc_now()
        with self.transaction() as db:
            cursor = db.execute(
                """
                UPDATE libraries
                SET last_scan_files=?, last_scan_bytes=?, last_scanned_at=?
                WHERE id=?
                """,
                (total_files, total_bytes, scanned_at, library_id),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"Libreria non trovata: {library_id}")
            self._event(
                db,
                "library.scan",
                {
                    "library_id": library_id,
                    "total_files": total_files,
                    "total_bytes": total_bytes,
                },
            )

    def register_tape(
        self,
        tape_id: str,
        volume_serial: str,
        volume_label: str,
        filesystem: str,
        mount_hint: str,
        cassette_number: str | None = None,
    ) -> None:
        validate_id(tape_id, "ID nastro")
        cassette_number = (cassette_number or tape_id).strip()
        validate_id(cassette_number, "Numero cassetta")
        now = utc_now()
        with self.transaction() as db:
            if filesystem.casefold() == "ltfs" and volume_label.strip():
                existing_label = db.execute(
                    "SELECT id FROM tapes WHERE filesystem=? COLLATE NOCASE "
                    "AND volume_label=? COLLATE NOCASE AND id<>? COLLATE NOCASE",
                    ("LTFS", volume_label, tape_id),
                ).fetchone()
                if existing_label:
                    raise CatalogError(
                        f"L'etichetta LTFS {volume_label} è già registrata come "
                        f"{existing_label['id']}"
                    )
            existing = db.execute(
                "SELECT * FROM tapes WHERE id=?", (tape_id,)
            ).fetchone()
            if (
                existing
                and existing["cassette_number"].casefold() != cassette_number.casefold()
            ):
                raise CatalogError(
                    f"Il nastro {tape_id} è già associato al numero cassetta "
                    f"{existing['cassette_number']}"
                )
            if (
                existing
                and filesystem.casefold() != "ltfs"
                and existing["volume_serial"].casefold() != volume_serial.casefold()
            ):
                raise CatalogError(
                    f"Il nastro {tape_id} è associato al seriale {existing['volume_serial']}, non {volume_serial}"
                )
            if (
                existing
                and filesystem.casefold() == "ltfs"
                and str(existing["volume_label"]).casefold() != volume_label.casefold()
            ):
                raise CatalogError(
                    f"Il nastro {tape_id} è associato all'etichetta LTFS "
                    f"{existing['volume_label']}, non {volume_label}"
                )
            try:
                db.execute(
                    """
                INSERT INTO tapes(
                    id, cassette_number, volume_serial, volume_label, filesystem,
                    mount_hint, status, created_at, last_seen_at
                )
                VALUES(?, ?, ?, ?, ?, ?, 'active', ?, ?)
                ON CONFLICT(id) DO UPDATE SET
                    volume_serial=excluded.volume_serial,
                    volume_label=excluded.volume_label,
                    filesystem=excluded.filesystem,
                    mount_hint=excluded.mount_hint,
                    last_seen_at=excluded.last_seen_at
                    """,
                    (
                        tape_id,
                        cassette_number,
                        volume_serial,
                        volume_label,
                        filesystem,
                        mount_hint,
                        now,
                        now,
                    ),
                )
            except sqlite3.IntegrityError as exc:
                raise CatalogError(
                    f"Numero cassetta già registrato: {cassette_number}"
                ) from exc
            self._event(
                db,
                "tape.register",
                {
                    "tape_id": tape_id,
                    "cassette_number": cassette_number,
                    "serial": volume_serial,
                },
            )

    def get_tape(self, tape_id: str) -> sqlite3.Row:
        row = self.connection.execute(
            "SELECT * FROM tapes WHERE id=? AND status='active'", (tape_id,)
        ).fetchone()
        if row is None:
            raise CatalogError(f"Nastro non trovato o ritirato: {tape_id}")
        return row

    def list_tapes(self) -> list[sqlite3.Row]:
        return list(
            self.connection.execute("SELECT * FROM tapes ORDER BY id COLLATE NOCASE")
        )

    def touch_tape(self, tape_id: str, mount_hint: str) -> None:
        with self.transaction() as db:
            db.execute(
                "UPDATE tapes SET mount_hint=?, last_seen_at=? WHERE id=?",
                (mount_hint, utc_now(), tape_id),
            )

    def latest_versions(self, library_id: str) -> dict[str, sqlite3.Row]:
        rows = self.connection.execute(
            """
            SELECT fv.*
            FROM file_versions fv
            JOIN (
                SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                FROM file_versions candidate
                JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                WHERE candidate.library_id=?
                  AND candidate.visible=1
                  AND candidate_block.visible=1
                  AND candidate_block.status='completed'
                GROUP BY candidate.relative_path
            ) latest ON latest.max_id=fv.id
            ORDER BY fv.relative_path COLLATE NOCASE
            """,
            (library_id,),
        )
        return {row["relative_path"]: row for row in rows}

    def create_block(
        self,
        block_id: str,
        library_id: str,
        tape_id: str,
        tape_relative_root: str,
        planned_files: int,
        planned_bytes: int,
        *,
        automatic_operation_id: str | None = None,
        automatic_job_id: str | None = None,
        automatic_cassette_sequence: int | None = None,
    ) -> None:
        automatic_coordinates = (
            automatic_operation_id,
            automatic_job_id,
            automatic_cassette_sequence,
        )
        if any(value is not None for value in automatic_coordinates) and any(
            value is None for value in automatic_coordinates
        ):
            raise ValidationError("automatic block coordinates are incomplete")
        with self.transaction() as db:
            bind_automatic_append = False
            automatic_layout_operation: str | None = None
            if automatic_operation_id is not None:
                operation = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?",
                    (automatic_operation_id,),
                ).fetchone()
                cassette = db.execute(
                    "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                    (automatic_job_id, automatic_cassette_sequence),
                ).fetchone()
                if (
                    operation is None
                    or operation["state"] != "running"
                    or operation["kind"] != "archive.native"
                    or operation["job_id"] != automatic_job_id
                    or operation["cassette_sequence"] != automatic_cassette_sequence
                    or cassette is None
                    or cassette["status"] not in {"pending", "writing"}
                    or tape_id
                    != (cassette["tape_id"] or cassette["physical_label"])
                ):
                    raise ValidationError("automatic block checkpoint is not exact")
                automatic_layout_operation = str(cassette["operation"])
                bind_automatic_append = automatic_layout_operation == "append"
            db.execute(
                """
                INSERT INTO blocks(
                    id, library_id, tape_id, tape_relative_root, status, visible,
                    planned_files, planned_bytes, started_at
                ) VALUES(?, ?, ?, ?, 'copying', 0, ?, ?, ?)
                """,
                (
                    block_id,
                    library_id,
                    tape_id,
                    tape_relative_root,
                    planned_files,
                    planned_bytes,
                    utc_now(),
                ),
            )
            binding_created_at = utc_now()
            if bind_automatic_append:
                db.execute(
                    "INSERT INTO automatic_operation_blocks("
                    "block_id,operation_id,job_id,cassette_sequence,created_at) "
                    "VALUES(?,?,?,?,?)",
                    (
                        block_id,
                        automatic_operation_id,
                        automatic_job_id,
                        automatic_cassette_sequence,
                        binding_created_at,
                    ),
                )
            if automatic_layout_operation is not None:
                target = db.execute(
                    "SELECT * FROM job_layout_targets WHERE job_id=? "
                    "AND target_sequence=? AND operation=? "
                    "ORDER BY epoch_number DESC,plan_sequence DESC LIMIT 1",
                    (
                        automatic_job_id,
                        automatic_cassette_sequence,
                        automatic_layout_operation,
                    ),
                ).fetchone()
                if target is not None:
                    db.execute(
                        "INSERT INTO job_layout_target_blocks("
                        "job_id,epoch_number,plan_sequence,target_sequence,segment_id,"
                        "operation_id,block_id,created_at) VALUES(?,?,?,?,?,?,?,?)",
                        (
                            target["job_id"], target["epoch_number"],
                            target["plan_sequence"], target["target_sequence"],
                            target["segment_id"], automatic_operation_id, block_id,
                            binding_created_at,
                        ),
                    )
            self._event(
                db,
                "block.start",
                {
                    "block_id": block_id,
                    "library_id": library_id,
                    "tape_id": tape_id,
                    "planned_files": planned_files,
                    "planned_bytes": planned_bytes,
                    "automatic_operation_id": automatic_operation_id,
                    "automatic_job_id": automatic_job_id,
                    "automatic_cassette_sequence": automatic_cassette_sequence,
                },
            )

    def record_file_version(
        self,
        library_id: str,
        block_id: str,
        tape_id: str,
        relative_path: str,
        tape_relative_path: str,
        size: int,
        mtime_ns: int,
        sha256: str,
        metadata: dict[str, Any] | None = None,
    ) -> int:
        return self._record_file_version(
            library_id,
            block_id,
            tape_id,
            relative_path,
            tape_relative_path,
            size,
            mtime_ns,
            sha256,
            metadata,
            visible=1,
        )

    def stage_file_version(
        self,
        library_id: str,
        block_id: str,
        tape_id: str,
        relative_path: str,
        tape_relative_path: str,
        size: int,
        mtime_ns: int,
        sha256: str,
    ) -> int:
        validate_source_relative_path(relative_path, "relative_path")
        self._validate_portable_relative_path(tape_relative_path, "tape_relative_path")
        self._validate_sha256(sha256, "sha256")
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value < 0
            for value in (size, mtime_ns)
        ):
            raise ValidationError("invalid staged file size or mtime")
        with self.transaction() as db:
            block = db.execute(
                "SELECT library_id, tape_id, tape_relative_root, status FROM blocks WHERE id=?",
                (block_id,),
            ).fetchone()
            if block is None or block["status"] != "copying":
                raise CatalogError(f"Blocco non in stato copying: {block_id}")
            if (
                block["library_id"].casefold() != library_id.casefold()
                or block["tape_id"].casefold() != tape_id.casefold()
            ):
                raise CatalogError("La versione staged non appartiene al blocco")
            expected_tape_path = (
                PurePosixPath(block["tape_relative_root"])
                / "files"
                / PurePosixPath(ltfs_tape_relative_path(relative_path))
            ).as_posix()
            if tape_relative_path != expected_tape_path:
                raise ValidationError("tape_relative_path non corrisponde al blocco")
            return self._insert_file_version(
                db,
                library_id,
                block_id,
                tape_id,
                relative_path,
                tape_relative_path,
                size,
                mtime_ns,
                sha256,
                {},
                visible=0,
            )

    def _record_file_version(
        self,
        library_id: str,
        block_id: str,
        tape_id: str,
        relative_path: str,
        tape_relative_path: str,
        size: int,
        mtime_ns: int,
        sha256: str,
        metadata: dict[str, Any] | None,
        *,
        visible: int,
    ) -> int:
        parent_path, file_name = self._split_relative_path(relative_path)
        details = metadata or {}
        alternate_streams = details.get("alternate_streams", [])
        with self.transaction() as db:
            return self._insert_file_version(
                db,
                library_id,
                block_id,
                tape_id,
                relative_path,
                tape_relative_path,
                size,
                mtime_ns,
                sha256,
                details,
                visible=visible,
                parent_path=parent_path,
                file_name=file_name,
                alternate_streams=alternate_streams,
            )

    def _insert_file_version(
        self,
        db: sqlite3.Connection,
        library_id: str,
        block_id: str,
        tape_id: str,
        relative_path: str,
        tape_relative_path: str,
        size: int,
        mtime_ns: int,
        sha256: str,
        details: dict[str, Any],
        *,
        visible: int,
        parent_path: str | None = None,
        file_name: str | None = None,
        alternate_streams: object | None = None,
    ) -> int:
        if parent_path is None or file_name is None:
            parent_path, file_name = self._split_relative_path(relative_path)
        if alternate_streams is None:
            alternate_streams = details.get("alternate_streams", [])
        source_change_ns = details.get("source_change_ns")
        if type(source_change_ns) is not int or source_change_ns <= 0:
            source_change_ns = None
        if source_change_ns is not None:
            if self._file_version_change_column is None:
                self._file_version_change_column = any(
                    row["name"] == "source_change_ns"
                    for row in db.execute("PRAGMA table_info(file_versions)")
                )
            if not self._file_version_change_column:
                source_change_ns = None
        column_suffix = ", source_change_ns" if source_change_ns is not None else ""
        value_suffix = ", ?" if source_change_ns is not None else ""
        change_values = (source_change_ns,) if source_change_ns is not None else ()

        cursor = db.execute(
            f"""
                INSERT INTO file_versions(
                    library_id, block_id, tape_id, relative_path, tape_relative_path,
                    size, mtime_ns, sha256, copied_at, parent_path, file_name,
                    created_ns, accessed_ns, source_mode, windows_attributes,
                    owner_name, owner_sid, security_descriptor, alternate_streams_json,
                    metadata_state, metadata_error, visible{column_suffix}
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?{value_suffix})
                """,
            (
                library_id,
                block_id,
                tape_id,
                relative_path,
                tape_relative_path,
                size,
                mtime_ns,
                sha256,
                utc_now(),
                parent_path,
                file_name,
                details.get("created_ns"),
                details.get("accessed_ns"),
                details.get("source_mode"),
                details.get("windows_attributes"),
                details.get("owner_name"),
                details.get("owner_sid"),
                details.get("security_descriptor"),
                json.dumps(alternate_streams, ensure_ascii=False, sort_keys=True),
                details.get("metadata_state", "legacy"),
                details.get("metadata_error"),
                visible,
                *change_values,
            ),
        )
        db.execute(
            """
            UPDATE blocks
            SET copied_files=copied_files+1, copied_bytes=copied_bytes+?
            WHERE id=?
            """,
            (size, block_id),
        )
        return int(cursor.lastrowid)

    def update_file_metadata(
        self, file_version_id: int, metadata: dict[str, Any]
    ) -> None:
        self.update_file_metadata_batch([(file_version_id, metadata)])

    def update_file_metadata_batch(
        self, updates: list[tuple[int, dict[str, Any]]]
    ) -> None:
        if not updates:
            return
        with self.transaction() as db:
            for file_version_id, metadata in updates:
                cursor = db.execute(
                    """
                    UPDATE file_versions SET
                        created_ns=?, accessed_ns=?, source_mode=?, windows_attributes=?,
                        owner_name=?, owner_sid=?, security_descriptor=?, alternate_streams_json=?,
                        metadata_state=?, metadata_error=?
                    WHERE id=?
                    """,
                    (
                        metadata.get("created_ns"),
                        metadata.get("accessed_ns"),
                        metadata.get("source_mode"),
                        metadata.get("windows_attributes"),
                        metadata.get("owner_name"),
                        metadata.get("owner_sid"),
                        metadata.get("security_descriptor"),
                        json.dumps(
                            metadata.get("alternate_streams", []),
                            ensure_ascii=False,
                            sort_keys=True,
                        ),
                        metadata.get("metadata_state", "partial"),
                        metadata.get("metadata_error"),
                        file_version_id,
                    ),
                )
                if cursor.rowcount != 1:
                    raise CatalogError(f"Versione file non trovata: {file_version_id}")

    def browse_backup_children(
        self, library_id: str, parent_path: str = ""
    ) -> list[dict[str, Any]]:
        """Return immediate current children from the local catalog only."""
        self.get_library(library_id, include_retired=True)
        normalized_parent = parent_path.replace("\\", "/").strip("/")
        if normalized_parent in (".", "..") or any(
            part in ("", ".", "..")
            for part in normalized_parent.split("/")
            if normalized_parent
        ):
            raise ValidationError(f"Cartella catalogo non valida: {parent_path}")
        current_cte = """
            WITH latest AS (
                SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                FROM file_versions candidate
                JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                WHERE candidate.library_id=?
                  AND candidate.visible=1
                  AND candidate_block.visible=1
                  AND candidate_block.status='completed'
                GROUP BY candidate.relative_path
            ), current_files AS (
                SELECT fv.*
                FROM file_versions fv
                JOIN latest ON latest.max_id=fv.id
            )
        """
        prefix = normalized_parent + "/" if normalized_parent else ""
        escaped_prefix = (
            prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        )
        parent_rows = self.connection.execute(
            current_cte + "SELECT DISTINCT parent_path FROM current_files "
            "WHERE parent_path LIKE ? ESCAPE '\\'",
            (library_id, escaped_prefix + "%"),
        )
        directory_names: set[str] = set()
        for row in parent_rows:
            directory_path = row["parent_path"]
            if not directory_path.startswith(prefix):
                continue
            remainder = directory_path[len(prefix) :]
            if remainder:
                directory_names.add(remainder.split("/", 1)[0])

        result: list[dict[str, Any]] = [
            {
                "kind": "directory",
                "name": name,
                "library_id": library_id,
                "relative_path": f"{prefix}{name}",
            }
            for name in sorted(directory_names, key=str.casefold)
        ]
        file_rows = self.connection.execute(
            current_cte
            + """
                SELECT
                    fv.*, l.name AS library_name, b.status AS block_status,
                    t.cassette_number, t.volume_label, t.volume_serial,
                    1 AS is_current
                FROM current_files fv
                JOIN libraries l ON l.id=fv.library_id
                JOIN blocks b ON b.id=fv.block_id
                JOIN tapes t ON t.id=fv.tape_id
                WHERE fv.parent_path=?
                ORDER BY fv.file_name COLLATE NOCASE
            """,
            (library_id, normalized_parent),
        )
        for row in file_rows:
            item = dict(row)
            item["kind"] = "file"
            item["name"] = item["file_name"]
            try:
                item["alternate_streams"] = json.loads(
                    item["alternate_streams_json"] or "[]"
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                item["alternate_streams"] = []
            result.append(item)
        return result

    @staticmethod
    def _catalog_browse_cursor(
        kind_rank: object,
        name: object,
        relative_path: object,
        version_id: object,
    ) -> str:
        if (
            isinstance(kind_rank, bool)
            or not isinstance(kind_rank, int)
            or kind_rank not in {0, 1}
            or not isinstance(name, str)
            or not name
            or len(name) > 255
            or not isinstance(relative_path, str)
            or not relative_path
            or len(relative_path) > 4096
            or isinstance(version_id, bool)
            or not isinstance(version_id, int)
            or version_id < 0
        ):
            raise ValidationError("invalid catalog browse cursor")
        encoded = json.dumps(
            {
                "kind_rank": kind_rank,
                "name": name,
                "relative_path": relative_path,
                "version_id": version_id,
            },
            ensure_ascii=True,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("ascii")
        return base64.urlsafe_b64encode(encoded).decode("ascii").rstrip("=")

    @staticmethod
    def _parse_catalog_browse_cursor(
        cursor: object,
    ) -> tuple[int, str, str, int] | None:
        if cursor is None:
            return None
        if not isinstance(cursor, str) or not cursor or len(cursor) > 512:
            raise ValidationError("invalid catalog browse cursor")
        try:
            padding = "=" * (-len(cursor) % 4)
            decoded = base64.b64decode(
                cursor + padding, altchars=b"-_", validate=True
            ).decode("ascii")
            value = json.loads(decoded)
        except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
            raise ValidationError("invalid catalog browse cursor") from None
        if not isinstance(value, dict) or set(value) != {
            "kind_rank",
            "name",
            "relative_path",
            "version_id",
        }:
            raise ValidationError("invalid catalog browse cursor")
        kind_rank = value["kind_rank"]
        name = value["name"]
        relative_path = value["relative_path"]
        version_id = value["version_id"]
        if (
            isinstance(kind_rank, bool)
            or not isinstance(kind_rank, int)
            or kind_rank not in {0, 1}
            or not isinstance(name, str)
            or not name
            or len(name) > 255
            or not isinstance(relative_path, str)
            or not relative_path
            or len(relative_path) > 4096
            or isinstance(version_id, bool)
            or not isinstance(version_id, int)
            or version_id < 0
        ):
            raise ValidationError("invalid catalog browse cursor")
        return kind_rank, name, relative_path, version_id

    def browse_backup_children_page(
        self,
        library_id: str,
        parent_path: str = "",
        *,
        limit: int = 50,
        cursor: str | None = None,
    ) -> dict[str, Any]:
        """Return a bounded, SQL-keyset page of immediate current children."""

        if (
            not isinstance(limit, int)
            or isinstance(limit, bool)
            or not 1 <= limit <= 200
        ):
            raise ValidationError("invalid catalog browse limit")
        self.get_library(library_id, include_retired=True)
        normalized_parent = parent_path.replace("\\", "/").strip("/")
        if normalized_parent in (".", "..") or any(
            part in ("", ".", "..")
            for part in normalized_parent.split("/")
            if normalized_parent
        ):
            raise ValidationError(f"Cartella catalogo non valida: {parent_path}")
        parsed_cursor = self._parse_catalog_browse_cursor(cursor)
        prefix = normalized_parent + "/" if normalized_parent else ""
        escaped_prefix = (
            prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        )
        current_cte = """
            WITH latest AS (
                SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                FROM file_versions candidate
                JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                WHERE candidate.library_id=?
                  AND candidate.visible=1
                  AND candidate_block.visible=1
                  AND candidate_block.status='completed'
                GROUP BY candidate.relative_path
            ), current_files AS (
                SELECT fv.*
                FROM file_versions fv
                JOIN latest ON latest.max_id=fv.id
            ), directory_names AS (
                SELECT DISTINCT
                    CASE
                        WHEN instr(substr(parent_path, ?), '/') > 0
                        THEN substr(
                            substr(parent_path, ?),
                            1,
                            instr(substr(parent_path, ?), '/') - 1
                        )
                        ELSE substr(parent_path, ?)
                    END AS name
                FROM current_files
                WHERE parent_path LIKE ? ESCAPE '\\'
                  AND parent_path<>?
            ), children AS (
                SELECT
                    0 AS kind_rank,
                    'directory' AS kind,
                    name,
                    ? || name AS relative_path,
                    0 AS version_id
                FROM directory_names
                UNION ALL
                SELECT
                    1 AS kind_rank,
                    'file' AS kind,
                    file_name AS name,
                    relative_path,
                    id AS version_id
                FROM current_files
                WHERE parent_path=?
            )
        """
        cursor_clause = ""
        cursor_params: list[Any] = []
        if parsed_cursor is not None:
            kind_rank, name, relative_path, version_id = parsed_cursor
            cursor_clause = """
                WHERE kind_rank>?
                   OR (
                        kind_rank=?
                    AND (
                        name COLLATE NOCASE>? COLLATE NOCASE
                        OR (
                            name COLLATE NOCASE=? COLLATE NOCASE
                            AND (
                                name COLLATE BINARY>? COLLATE BINARY
                                OR (
                                    name COLLATE BINARY=? COLLATE BINARY
                                    AND (
                                        relative_path COLLATE NOCASE>? COLLATE NOCASE
                                        OR (
                                            relative_path COLLATE NOCASE=? COLLATE NOCASE
                                            AND (
                                                relative_path COLLATE BINARY>? COLLATE BINARY
                                                OR (
                                                    relative_path COLLATE BINARY=? COLLATE BINARY
                                                    AND version_id>?
                                                )
                                            )
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            """
            cursor_params.extend(
                (
                    kind_rank,
                    kind_rank,
                    name,
                    name,
                    name,
                    name,
                    relative_path,
                    relative_path,
                    relative_path,
                    relative_path,
                    version_id,
                )
            )
        rows = list(
            self.connection.execute(
                current_cte
                + "SELECT kind_rank, kind, name, relative_path, version_id FROM children "
                + cursor_clause
                + """
                    ORDER BY
                        kind_rank,
                        name COLLATE NOCASE,
                        name COLLATE BINARY,
                        relative_path COLLATE NOCASE,
                        relative_path COLLATE BINARY,
                        version_id
                    LIMIT ?
                """,
                (
                    library_id,
                    len(prefix) + 1,
                    len(prefix) + 1,
                    len(prefix) + 1,
                    len(prefix) + 1,
                    escaped_prefix + "%",
                    normalized_parent,
                    prefix,
                    normalized_parent,
                    *cursor_params,
                    limit + 1,
                ),
            )
        )
        has_more = len(rows) > limit
        page_rows = rows[:limit]
        items = [
            {
                "kind": row["kind"],
                "name": row["name"],
                "library_id": library_id,
                "relative_path": row["relative_path"],
                **({"id": row["version_id"]} if row["kind"] == "file" else {}),
            }
            for row in page_rows
        ]
        return {
            "items": items,
            "next_cursor": (
                self._catalog_browse_cursor(
                    page_rows[-1]["kind_rank"],
                    page_rows[-1]["name"],
                    page_rows[-1]["relative_path"],
                    page_rows[-1]["version_id"],
                )
                if has_more
                else None
            ),
        }

    def complete_block(self, block_id: str) -> None:
        self.complete_blocks([block_id])

    def complete_blocks(self, block_ids: list[str]) -> None:
        if not block_ids:
            return
        with self.transaction() as db:
            completed_at = utc_now()
            for block_id in block_ids:
                cursor = db.execute(
                    """
                    UPDATE blocks SET status='completed', visible=1, completed_at=?, error=NULL
                    WHERE id=? AND status='copying'
                    """,
                    (completed_at, block_id),
                )
                if cursor.rowcount != 1:
                    raise CatalogError(f"Blocco non in stato copying: {block_id}")
                db.execute(
                    "UPDATE file_versions SET visible=1 WHERE block_id=? AND visible=0",
                    (block_id,),
                )
                self._event(db, "block.complete", {"block_id": block_id})

    def fail_block(self, block_id: str, error: str) -> None:
        self.fail_blocks([block_id], error)

    def fail_blocks(self, block_ids: list[str], error: str) -> None:
        if not block_ids:
            return
        with self.transaction() as db:
            failed_at = utc_now()
            for block_id in block_ids:
                cursor = db.execute(
                    """
                    UPDATE blocks SET status='failed', completed_at=?, error=?
                    WHERE id=? AND status='copying'
                    """,
                    (failed_at, error[:4000], block_id),
                )
                if cursor.rowcount:
                    db.execute(
                        "UPDATE file_versions SET visible=0 WHERE block_id=?",
                        (block_id,),
                    )
                    self._event(
                        db, "block.fail", {"block_id": block_id, "error": error[:1000]}
                    )

    def list_blocks(
        self, library_id: str | None = None, include_forgotten: bool = False
    ) -> list[sqlite3.Row]:
        clauses: list[str] = []
        params: list[Any] = []
        if library_id:
            clauses.append("library_id=?")
            params.append(library_id)
        if not include_forgotten:
            clauses.append("visible=1")
        query = "SELECT * FROM blocks"
        if clauses:
            query += " WHERE " + " AND ".join(clauses)
        query += " ORDER BY started_at DESC"
        return list(self.connection.execute(query, params))

    def forget_block(self, block_id: str) -> None:
        with self.transaction() as db:
            cursor = db.execute(
                "UPDATE blocks SET visible=0 WHERE id=? AND visible=1", (block_id,)
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"Blocco visibile non trovato: {block_id}")
            db.execute(
                "UPDATE file_versions SET visible=0 WHERE block_id=?", (block_id,)
            )
            self._event(
                db, "block.forget", {"block_id": block_id, "tape_data_deleted": False}
            )

    def restore_plan(self, library_id: str) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                """
                WITH latest AS (
                    SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                    FROM file_versions candidate
                    JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                    WHERE candidate.library_id=?
                      AND candidate.visible=1
                      AND candidate_block.status='completed'
                    GROUP BY candidate.relative_path
                )
                SELECT fv.tape_id, COUNT(*) AS file_count, SUM(fv.size) AS total_bytes
                FROM file_versions fv
                JOIN latest ON latest.max_id=fv.id
                GROUP BY fv.tape_id
                ORDER BY MIN(fv.id)
                """,
                (library_id,),
            )
        )

    def library_tape_distribution(self, library_id: str) -> list[sqlite3.Row]:
        """Return the physical location of each current catalogued file."""
        return list(
            self.connection.execute(
                """
                WITH latest AS (
                    SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                    FROM file_versions candidate
                    JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                    WHERE candidate.library_id=?
                      AND candidate.visible=1
                      AND candidate_block.status='completed'
                    GROUP BY candidate.relative_path
                )
                SELECT fv.tape_id, t.cassette_number,
                       COUNT(*) AS file_count, SUM(fv.size) AS total_bytes
                FROM file_versions fv
                JOIN latest ON latest.max_id=fv.id
                JOIN tapes t ON t.id=fv.tape_id
                GROUP BY fv.tape_id, t.cassette_number
                ORDER BY t.cassette_number COLLATE NOCASE, fv.tape_id COLLATE NOCASE
                """,
                (library_id,),
            )
        )

    def restore_files_for_tape(
        self, library_id: str, tape_id: str
    ) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                """
                WITH latest AS (
                    SELECT candidate.relative_path, MAX(candidate.id) AS max_id
                    FROM file_versions candidate
                    JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                    WHERE candidate.library_id=?
                      AND candidate.visible=1
                      AND candidate_block.status='completed'
                    GROUP BY candidate.relative_path
                )
                SELECT fv.*
                FROM file_versions fv
                JOIN latest ON latest.max_id=fv.id
                WHERE fv.tape_id=?
                ORDER BY fv.relative_path COLLATE NOCASE
                """,
                (library_id, tape_id),
            )
        )

    @staticmethod
    def _restore_plan_mapping(
        plan: Mapping[str, Any],
        cassettes: Sequence[Mapping[str, Any]],
        items: Sequence[Mapping[str, Any]],
        *,
        destination: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        cassette_columns = set(cassettes[0].keys()) if cassettes else set()
        item_columns = set(items[0].keys()) if items else set()
        if destination is None or destination["destination_state"] != "exact":
            destination_mapping = None
            destination_state = "legacy_invalid"
            destination_invalidation_reason = "legacy_destination_snapshot_missing"
        else:
            destination_mapping = {
                "kind": destination["kind"],
                "root": destination["root"],
                "anchor": destination["anchor"],
            }
            destination_state = "exact"
            destination_invalidation_reason = None
        return {
            "id": plan["id"],
            "state": plan["state"],
            "identity_state": plan["identity_state"],
            "invalidation_reason": plan["invalidation_reason"],
            "destination_root": plan["destination_root"],
            "destination": destination_mapping,
            "destination_state": destination_state,
            "destination_invalidation_reason": destination_invalidation_reason,
            "created_by": plan["created_by"],
            "created_at": plan["created_at"],
            "total_files": int(plan["total_files"]),
            "total_bytes": int(plan["total_bytes"]),
            "cassettes": [
                {
                    "sequence": int(row["sequence"]),
                    "tape_id": row["tape_id"],
                    "cassette_number": row["cassette_number"],
                    "physical_label": row["physical_label"],
                    "volume_serial": (
                        row["volume_serial"]
                        if "volume_serial" in cassette_columns
                        else None
                    ),
                    "volume_uuid": (
                        row["volume_uuid"] if "volume_uuid" in cassette_columns else None
                    ),
                    "item_count": int(row["item_count"]),
                    "total_bytes": int(row["total_bytes"]),
                }
                for row in cassettes
            ],
            "items": [
                {
                    "sequence": int(row["sequence"]),
                    "file_version_id": int(row["file_version_id"]),
                    "library_id": row["library_id"],
                    "relative_path": row["relative_path"],
                    "tape_relative_path": row["tape_relative_path"],
                    "tape_id": row["tape_id"],
                    "cassette_number": row["cassette_number"],
                    "physical_label": row["physical_label"],
                    "volume_label": (
                        row["volume_label"] if "volume_label" in item_columns else None
                    ),
                    "block_id": (
                        row["block_id"] if "block_id" in item_columns else None
                    ),
                    "size": int(row["size"]),
                    "sha256": row["sha256"],
                    "copied_at": row["copied_at"],
                    "is_current": (
                        None
                        if "is_current" not in item_columns
                        or row["is_current"] is None
                        else bool(row["is_current"])
                    ),
                }
                for row in items
            ],
        }

    def get_restore_plan(self, plan_id: str) -> dict[str, Any]:
        self._validate_safe_identifier(plan_id, "restore plan id")
        plan = self.connection.execute(
            "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
        ).fetchone()
        if plan is None:
            raise CatalogError("restore_plan_not_found")
        cassettes = self.connection.execute(
            "SELECT * FROM restore_plan_cassettes WHERE plan_id=? ORDER BY sequence",
            (plan_id,),
        ).fetchall()
        items = self.connection.execute(
            "SELECT * FROM restore_plan_items WHERE plan_id=? ORDER BY sequence",
            (plan_id,),
        ).fetchall()
        destination = None
        destination_table = self.connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='restore_plan_destinations'"
        ).fetchone()
        if destination_table is not None:
            destination = self.connection.execute(
                "SELECT * FROM restore_plan_destinations WHERE plan_id=?",
                (plan_id,),
            ).fetchone()
        return self._restore_plan_mapping(
            plan, cassettes, items, destination=destination
        )

    @staticmethod
    def _trustworthy_restore_volume_uuid_tx(
        db: sqlite3.Connection, tape_id: str
    ) -> str | None:
        rows = db.execute(
            "SELECT DISTINCT lower(receipt.volume_uuid) AS volume_uuid "
            "FROM ltfs_terminal_receipts AS receipt "
            "JOIN automatic_cassettes AS cassette "
            "ON cassette.job_id=receipt.job_id AND cassette.sequence=receipt.sequence "
            "WHERE cassette.tape_id=? AND cassette.status='completed' "
            "ORDER BY volume_uuid",
            (tape_id,),
        ).fetchall()
        return str(rows[0]["volume_uuid"]) if len(rows) == 1 else None

    @staticmethod
    def _validate_restore_destination_snapshot(
        destination_kind: str,
        destination_root: str,
        destination_anchor: str,
    ) -> None:
        if destination_kind != "local":
            raise ValidationError("invalid restore destination snapshot")
        for value in (destination_root, destination_anchor):
            if (
                not isinstance(value, str)
                or not 1 <= len(value) <= 4096
                or "\x00" in value
            ):
                raise ValidationError("invalid restore destination snapshot")
            path = PurePosixPath(value)
            if (
                not path.is_absolute()
                or value.startswith("//")
                or any(part in {".", ".."} for part in path.parts)
                or path.as_posix() != value
            ):
                raise ValidationError("invalid restore destination snapshot")
        root = PurePosixPath(destination_root)
        anchor = PurePosixPath(destination_anchor)
        if root.parts[: len(anchor.parts)] != anchor.parts:
            raise ValidationError("invalid restore destination snapshot")

    def create_restore_plan(
        self,
        file_version_ids: Sequence[int],
        destination_root: str,
        *,
        actor: str,
        idempotency_key: str,
        request_sha256: str,
        destination_kind: str = "local",
        destination_anchor: str | None = None,
    ) -> dict[str, Any]:
        version_ids = tuple(file_version_ids)
        if (
            not version_ids
            or len(version_ids) > 200
            or len(set(version_ids)) != len(version_ids)
            or any(
                type(version_id) is not int or version_id < 1
                or version_id > 2**63 - 1
                for version_id in version_ids
            )
            or not isinstance(destination_root, str)
            or not destination_root.startswith("/")
            or "\x00" in destination_root
            or len(destination_root) > 4096
        ):
            raise ValidationError("invalid restore plan selection")
        self._validate_safe_identifier(actor, "restore plan actor")
        self._validate_sha256(request_sha256, "restore plan request digest")
        if destination_anchor is None:
            destination_anchor = destination_root
        self._validate_restore_destination_snapshot(
            destination_kind, destination_root, destination_anchor
        )
        action = "restore.plan.create"
        target_id = "restore-plans"
        with self.transaction() as db:
            replay = self.management_idempotency_replay(
                actor=actor,
                idempotency_key=idempotency_key,
                action=action,
                target_id=target_id,
                request_sha256=request_sha256,
            )
            if replay is not None:
                return replay
            selected = []
            for version_id in version_ids:
                try:
                    selected.append(dict(self.get_file_version(version_id)))
                except CatalogError as exc:
                    raise CatalogError("catalog_file_version_not_found") from exc
            plan_id = f"RESTORE-{uuid.uuid4().hex}"
            created_at = self._precise_utc_now()
            item_rows = [
                {
                    "sequence": sequence,
                    "file_version_id": int(item["id"]),
                    "library_id": item["library_id"],
                    "relative_path": item["relative_path"],
                    "tape_relative_path": item["tape_relative_path"],
                    "tape_id": item["tape_id"],
                    "cassette_number": item["cassette_number"],
                    "physical_label": item["physical_label"],
                    "volume_label": item["volume_label"],
                    "_volume_serial": item["volume_serial"],
                    "block_id": item["block_id"],
                    "size": int(item["size"]),
                    "sha256": item["sha256"],
                    "copied_at": item["copied_at"],
                    "is_current": bool(item["is_current"]),
                }
                for sequence, item in enumerate(selected, 1)
            ]
            for item in item_rows:
                physical_label = item["physical_label"]
                if (
                    type(item["file_version_id"]) is not int
                    or not 1 <= item["file_version_id"] <= 2**63 - 1
                    or not isinstance(item["library_id"], str)
                    or len(item["library_id"]) > 64
                    or not _SAFE_IDENTIFIER.fullmatch(item["library_id"])
                    or not isinstance(item["tape_id"], str)
                    or len(item["tape_id"]) > 64
                    or not _SAFE_IDENTIFIER.fullmatch(item["tape_id"])
                    or not isinstance(item["cassette_number"], str)
                    or not 1 <= len(item["cassette_number"]) <= 255
                    or (
                        physical_label is not None
                        and (
                            not isinstance(physical_label, str)
                            or not 1 <= len(physical_label) <= 32
                        )
                    )
                    or not isinstance(item["relative_path"], str)
                    or not 1 <= len(item["relative_path"]) <= 4096
                    or "\x00" in item["relative_path"]
                    or not isinstance(item["tape_relative_path"], str)
                    or not 1 <= len(item["tape_relative_path"]) <= 4096
                    or "\x00" in item["tape_relative_path"]
                    or not isinstance(item["volume_label"], str)
                    or len(item["volume_label"]) > 255
                    or not isinstance(item["_volume_serial"], str)
                    or not 1 <= len(item["_volume_serial"]) <= 255
                    or not isinstance(item["block_id"], str)
                    or len(item["block_id"]) > 64
                    or not _SAFE_IDENTIFIER.fullmatch(item["block_id"])
                    or type(item["is_current"]) is not bool
                    or type(item["size"]) is not int
                    or not 0 <= item["size"] <= 2**63 - 1
                    or not isinstance(item["sha256"], str)
                    or not _SHA256.fullmatch(item["sha256"])
                    or not isinstance(item["copied_at"], str)
                    or not 1 <= len(item["copied_at"]) <= 64
                ):
                    raise ValidationError("invalid restore plan identity")
            grouped: dict[str, dict[str, Any]] = {}
            total_bytes = 0
            for item in item_rows:
                tape_id = str(item["tape_id"])
                cassette = grouped.setdefault(
                    tape_id,
                    {
                        "sequence": len(grouped) + 1,
                        "tape_id": tape_id,
                        "cassette_number": item["cassette_number"],
                        "physical_label": item["physical_label"],
                        "volume_serial": item["_volume_serial"],
                        "volume_uuid": self._trustworthy_restore_volume_uuid_tx(
                            db, tape_id
                        ),
                        "item_count": 0,
                        "total_bytes": 0,
                    },
                )
                cassette["item_count"] += 1
                size = int(item["size"])
                if (
                    cassette["total_bytes"] > 2**63 - 1 - size
                    or total_bytes > 2**63 - 1 - size
                ):
                    raise ValidationError("invalid restore plan size")
                cassette["total_bytes"] += size
                total_bytes += size
            cassette_rows = list(grouped.values())
            cassette_columns = {
                str(row["name"])
                for row in db.execute("PRAGMA table_info(restore_plan_cassettes)")
            }
            has_restore_identity_columns = {
                "volume_serial",
                "volume_uuid",
            }.issubset(cassette_columns)
            db.execute(
                "INSERT INTO restore_plans(id,state,destination_root,created_by,"
                "created_at,request_sha256,total_files,total_bytes) "
                "VALUES(?,'planned',?,?,?,?,?,?)",
                (
                    plan_id,
                    destination_root,
                    actor,
                    created_at,
                    request_sha256,
                    len(item_rows),
                    total_bytes,
                ),
            )
            destination_table_exists = db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='restore_plan_destinations'"
            ).fetchone() is not None
            if destination_table_exists:
                db.execute(
                    "INSERT INTO restore_plan_destinations("
                    "plan_id,destination_state,kind,root,anchor,invalidation_reason) "
                    "VALUES(?,'exact',?,?,?,NULL)",
                    (plan_id, destination_kind, destination_root, destination_anchor),
                )
            if has_restore_identity_columns:
                db.executemany(
                    "INSERT INTO restore_plan_cassettes(plan_id,sequence,tape_id,"
                    "cassette_number,physical_label,item_count,total_bytes,"
                    "volume_serial,volume_uuid) VALUES(?,?,?,?,?,?,?,?,?)",
                    [
                        (
                            plan_id,
                            row["sequence"],
                            row["tape_id"],
                            row["cassette_number"],
                            row["physical_label"],
                            row["item_count"],
                            row["total_bytes"],
                            row["volume_serial"],
                            row["volume_uuid"],
                        )
                        for row in cassette_rows
                    ],
                )
            else:
                db.executemany(
                    "INSERT INTO restore_plan_cassettes(plan_id,sequence,tape_id,"
                    "cassette_number,physical_label,item_count,total_bytes) "
                    "VALUES(?,?,?,?,?,?,?)",
                    [
                        (
                            plan_id,
                            row["sequence"],
                            row["tape_id"],
                            row["cassette_number"],
                            row["physical_label"],
                            row["item_count"],
                            row["total_bytes"],
                        )
                        for row in cassette_rows
                    ],
                )
            db.executemany(
                "INSERT INTO restore_plan_items(plan_id,sequence,file_version_id,"
                "library_id,relative_path,tape_relative_path,tape_id,cassette_number,"
                "physical_label,volume_label,block_id,size,sha256,copied_at,is_current) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                [
                    (
                        plan_id,
                        row["sequence"],
                        row["file_version_id"],
                        row["library_id"],
                        row["relative_path"],
                        row["tape_relative_path"],
                        row["tape_id"],
                        row["cassette_number"],
                        row["physical_label"],
                        row["volume_label"],
                        row["block_id"],
                        row["size"],
                        row["sha256"],
                        row["copied_at"],
                        int(row["is_current"]),
                    )
                    for row in item_rows
                ],
            )
            plan = {
                "id": plan_id,
                "state": "planned",
                "identity_state": "exact",
                "invalidation_reason": None,
                "destination_root": destination_root,
                "destination": (
                    {
                        "kind": destination_kind,
                        "root": destination_root,
                        "anchor": destination_anchor,
                    }
                    if destination_table_exists
                    else None
                ),
                "destination_state": (
                    "exact" if destination_table_exists else "legacy_invalid"
                ),
                "destination_invalidation_reason": (
                    None
                    if destination_table_exists
                    else "legacy_destination_snapshot_missing"
                ),
                "created_by": actor,
                "created_at": created_at,
                "total_files": len(item_rows),
                "total_bytes": total_bytes,
                "cassettes": [
                    {
                        **row,
                        "volume_serial": (
                            row["volume_serial"]
                            if has_restore_identity_columns
                            else None
                        ),
                        "volume_uuid": (
                            row["volume_uuid"]
                            if has_restore_identity_columns
                            else None
                        ),
                    }
                    for row in cassette_rows
                ],
                "items": [
                    {key: value for key, value in row.items() if not key.startswith("_")}
                    for row in item_rows
                ],
            }
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action=action,
                target_id=target_id,
                request_fingerprint_sha256=request_sha256,
                response=plan,
            )
            self._record_audit_tx(
                db,
                actor,
                action,
                "accepted",
                idempotency_key,
                None,
                json.dumps(
                    {"plan_id": plan_id, "file_count": len(item_rows)},
                    ensure_ascii=True,
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            )
            return plan

    @staticmethod
    def _restore_conflict_mapping(row: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "id": row["id"],
            "run_id": row["run_id"],
            "item_sequence": int(row["item_sequence"]),
            "conflict_sequence": int(row["conflict_sequence"]),
            "file_version_id": int(row["file_version_id"]),
            "canonical_destination": row["canonical_destination"],
            "observed_size": int(row["observed_size"]),
            "observed_sha256": row["observed_sha256"],
            "state": row["state"],
            "authorization_id": row["authorization_id"],
            "recorded_at": row["recorded_at"],
            "authorized_at": row["authorized_at"],
            "consumed_at": row["consumed_at"],
        }

    @staticmethod
    def _restore_replacement_authorization_mapping(
        row: Mapping[str, Any],
    ) -> dict[str, Any]:
        return {
            "id": row["id"],
            "conflict_id": row["conflict_id"],
            "run_id": row["run_id"],
            "item_sequence": int(row["item_sequence"]),
            "file_version_id": int(row["file_version_id"]),
            "canonical_destination": row["canonical_destination"],
            "observed_size": int(row["observed_size"]),
            "observed_sha256": row["observed_sha256"],
            "administrator": row["administrator"],
            "state": row["state"],
            "authorized_at": row["authorized_at"],
            "consumed_at": row["consumed_at"],
            "consumed_by_operation_id": row["consumed_by_operation_id"],
        }

    def _restore_run_mapping_tx(
        self, db: sqlite3.Connection, run: Mapping[str, Any]
    ) -> dict[str, Any]:
        cassettes = db.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? ORDER BY sequence",
            (run["id"],),
        ).fetchall()
        items = db.execute(
            "SELECT * FROM restore_run_items WHERE run_id=? ORDER BY sequence",
            (run["id"],),
        ).fetchall()
        conflicts = {
            int(row["item_sequence"]): self._restore_conflict_mapping(row)
            for row in db.execute(
                "SELECT * FROM restore_item_conflicts WHERE run_id=? "
                "ORDER BY item_sequence,conflict_sequence",
                (run["id"],),
            )
        }
        return {
            "id": run["id"],
            "plan_id": run["plan_id"],
            "actor": run["actor"],
            "state": run["state"],
            "current_cassette_sequence": (
                None
                if run["current_cassette_sequence"] is None
                else int(run["current_cassette_sequence"])
            ),
            "plan_fingerprint_sha256": run["plan_fingerprint_sha256"],
            "total_files": int(run["total_files"]),
            "total_bytes": int(run["total_bytes"]),
            "restored_files": int(run["restored_files"]),
            "skipped_files": int(run["skipped_files"]),
            "failed_files": int(run["failed_files"]),
            "copied_bytes": int(run["copied_bytes"]),
            "created_at": run["created_at"],
            "started_at": run["started_at"],
            "completed_at": run["completed_at"],
            "last_error_code": run["last_error_code"],
            "cassettes": [
                {
                    "sequence": int(row["sequence"]),
                    "plan_cassette_sequence": int(row["plan_cassette_sequence"]),
                    "tape_id": row["tape_id"],
                    "cassette_number": row["cassette_number"],
                    "physical_label": row["physical_label"],
                    "volume_label": row["volume_label"],
                    "volume_serial": row["volume_serial"],
                    "volume_uuid": row["volume_uuid"],
                    "state": row["state"],
                    "item_count": int(row["item_count"]),
                    "total_bytes": int(row["total_bytes"]),
                    "restored_files": int(row["restored_files"]),
                    "skipped_files": int(row["skipped_files"]),
                    "failed_files": int(row["failed_files"]),
                    "copied_bytes": int(row["copied_bytes"]),
                    "operation_id": row["operation_id"],
                    "started_at": row["started_at"],
                    "completed_at": row["completed_at"],
                    "last_error_code": row["last_error_code"],
                }
                for row in cassettes
            ],
            "items": [
                {
                    "sequence": int(row["sequence"]),
                    "cassette_sequence": int(row["cassette_sequence"]),
                    "destination_relative_path": row["destination_relative_path"],
                    "canonical_destination": row["canonical_destination"],
                    "state": row["state"],
                    "bytes_copied": int(row["bytes_copied"]),
                    "observed_sha256": row["observed_sha256"],
                    "error_code": row["error_code"],
                    "started_at": row["started_at"],
                    "completed_at": row["completed_at"],
                    "conflict": conflicts.get(int(row["sequence"])),
                    "plan_item": {
                        "sequence": int(row["plan_item_sequence"]),
                        "file_version_id": int(row["file_version_id"]),
                        "library_id": row["library_id"],
                        "relative_path": row["relative_path"],
                        "tape_relative_path": row["tape_relative_path"],
                        "tape_id": row["tape_id"],
                        "cassette_number": row["cassette_number"],
                        "physical_label": row["physical_label"],
                        "volume_label": row["volume_label"],
                        "block_id": row["block_id"],
                        "size": int(row["size"]),
                        "sha256": row["sha256"],
                        "copied_at": row["copied_at"],
                        "is_current": bool(row["is_current"]),
                    },
                }
                for row in items
            ],
        }

    def restore_run(self, run_id: str) -> dict[str, Any]:
        self._validate_safe_identifier(run_id, "restore run id")
        run = self.connection.execute(
            "SELECT * FROM restore_runs WHERE id=?", (run_id,)
        ).fetchone()
        if run is None:
            raise CatalogError("restore_run_not_found")
        return self._restore_run_mapping_tx(self.connection, run)

    def restore_run_cancel_requested(self, run_id: str) -> bool:
        """Return the durable cooperative-cancellation marker for one run."""

        self._validate_safe_identifier(run_id, "restore run id")
        return self.connection.execute(
            "SELECT 1 FROM audit_entries WHERE action='restore.run.cancel' "
            "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? "
            "LIMIT 1",
            (run_id,),
        ).fetchone() is not None

    def restore_run_pause_requested(self, run_id: str) -> bool:
        """Return whether the latest durable pause control remains unresumed."""

        self._validate_safe_identifier(run_id, "restore run id")
        latest = self.connection.execute(
            "SELECT action FROM audit_entries WHERE result='accepted' "
            "AND action IN ('restore.run.pause','restore.run.resume') "
            "AND json_extract(payload_json,'$.run_id')=? ORDER BY id DESC LIMIT 1",
            (run_id,),
        ).fetchone()
        return latest is not None and latest["action"] == "restore.run.pause"

    @staticmethod
    def _restore_receipt_sha256(value: object) -> str:
        """Hash every dataclass field, including proof bytes hidden from repr."""

        def canonical(item: object) -> object:
            fields = getattr(type(item), "__dataclass_fields__", None)
            if fields is not None:
                return {
                    "type": type(item).__name__,
                    "fields": {
                        name: canonical(getattr(item, name)) for name in fields
                    },
                }
            if isinstance(item, bytes):
                return {"bytes": item.hex()}
            if isinstance(item, Path):
                return {"path": str(item)}
            if isinstance(item, tuple):
                return [canonical(member) for member in item]
            if isinstance(item, (str, int, float, bool)) or item is None:
                return item
            raise ValidationError("restore receipt contains unsupported evidence")

        return hashlib.sha256(
            json.dumps(
                canonical(value), ensure_ascii=True, separators=(",", ":"), sort_keys=True
            ).encode("ascii")
        ).hexdigest()

    @staticmethod
    def _restore_item_checkpoint_sha256_tx(
        db: sqlite3.Connection, run_id: str, cassette_sequence: int
    ) -> str:
        rows = db.execute(
            "SELECT sequence,file_version_id,state,bytes_copied,observed_sha256,"
            "error_code FROM restore_run_items WHERE run_id=? AND cassette_sequence=? "
            "ORDER BY sequence",
            (run_id, cassette_sequence),
        ).fetchall()
        if not rows:
            raise CatalogError("restore cassette items are unavailable")
        return hashlib.sha256(
            json.dumps(
                [tuple(row) for row in rows],
                ensure_ascii=True,
                separators=(",", ":"),
            ).encode("ascii")
        ).hexdigest()

    @staticmethod
    def _pending_restore_control_tx(
        db: sqlite3.Connection, run_id: str
    ) -> str | None:
        cancelled = db.execute(
            "SELECT 1 FROM audit_entries WHERE action='restore.run.cancel' "
            "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? LIMIT 1",
            (run_id,),
        ).fetchone()
        latest = db.execute(
            "SELECT action FROM audit_entries WHERE result='accepted' "
            "AND action IN ('restore.run.pause','restore.run.resume') "
            "AND json_extract(payload_json,'$.run_id')=? ORDER BY id DESC LIMIT 1",
            (run_id,),
        ).fetchone()
        if cancelled is not None:
            return "cancelled"
        if latest is not None and latest["action"] == "restore.run.pause":
            return "paused"
        return None

    def _restore_release_boundary_tx(
        self,
        db: sqlite3.Connection,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
    ) -> str:
        receipt = db.execute(
            "SELECT * FROM restore_release_receipts WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
        ).fetchone()
        target = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        if (
            receipt is None
            or operation is None
            or target is None
            or operation["kind"] != "restore.cassette"
            or operation["job_id"] != run_id
            or operation["cassette_sequence"] != cassette_sequence
            or receipt["run_id"] != run_id
            or receipt["cassette_sequence"] != cassette_sequence
            or receipt["owner_generation"] != operation["owner_generation"]
            or receipt["plan_fingerprint_sha256"] != plan_fingerprint_sha256
            or receipt["item_checkpoint_sha256"]
            != self._restore_item_checkpoint_sha256_tx(db, run_id, cassette_sequence)
            or any(
                receipt[name] != target[name]
                for name in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
        ):
            return "missing"
        if receipt["boundary"] == "pre_mount":
            forbidden = db.execute(
                "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
                "AND command_kind IN ('mount','unmount','load','unload','format') LIMIT 1",
                (operation_id,),
            ).fetchone()
            unfinished = db.execute(
                "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
                "AND state!='quiesced' LIMIT 1",
                (operation_id,),
            ).fetchone()
            return "pre_mount" if forbidden is None and unfinished is None else "missing"
        unload = db.execute(
            "SELECT * FROM hardware_command_executions WHERE id=?",
            (receipt["unload_command_id"],),
        ).fetchone()
        if (
            receipt["boundary"] != "post_eject"
            or unload is None
            or unload["operation_id"] != operation_id
            or unload["issued_generation"] != operation["owner_generation"]
            or unload["command_kind"] != "unload"
            or unload["state"] != "quiesced"
            or unload["exit_outcome"] != "completed"
            or unload["terminal_exit_code"] != 0
            or any(
                unload[name] != target[name]
                for name in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
        ):
            return "missing"
        probe = self._restore_exact_no_media_probe_tx(
            db, operation, target, unload
        )
        probe_quiesced = (
            None
            if probe is None
            else self._parse_utc_timestamp(probe["quiesced_at"])
        )
        receipt_recorded = self._parse_utc_timestamp(receipt["recorded_at"])
        if (
            probe is None
            or probe_quiesced is None
            or receipt_recorded is None
            or receipt_recorded < probe_quiesced
        ):
            return "missing"
        return "post_eject"

    @classmethod
    def _restore_exact_no_media_probe_tx(
        cls,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        target: sqlite3.Row,
        unload: sqlite3.Row,
    ) -> sqlite3.Row | None:
        commands = cls._commands_with_release_for_operation_tx(
            db, str(operation["id"])
        )
        unload_index = next(
            (
                index
                for index, command in enumerate(commands)
                if command["id"] == unload["id"]
            ),
            None,
        )
        if unload_index is None or unload_index + 2 != len(commands):
            return None
        probe = commands[unload_index + 1]
        unload_quiesced = cls._parse_utc_timestamp(unload["quiesced_at"])
        probe_created = cls._parse_utc_timestamp(probe["created_at"])
        probe_quiesced = cls._parse_utc_timestamp(probe["quiesced_at"])
        if (
            probe["issued_generation"] != operation["owner_generation"]
            or probe["command_kind"] != "probe_media"
            or probe["state"] != "quiesced"
            or probe["exit_outcome"] != "completed"
            or probe["terminal_exit_code"] != 3
            or any(
                probe[name] != target[name]
                for name in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
            or unload_quiesced is None
            or probe_created is None
            or probe_quiesced is None
            or unload_quiesced > probe_created
            or probe_created > probe_quiesced
        ):
            return None
        return probe

    def restore_release_boundary(
        self,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
    ) -> str:
        """Validate the exact restore-specific durable release chain."""

        return self._restore_release_boundary_tx(
            self.connection,
            operation_id,
            run_id,
            cassette_sequence,
            plan_fingerprint_sha256,
        )

    def _restore_pre_mount_recovery_candidate_tx(
        self,
        db: sqlite3.Connection,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
    ) -> bool:
        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
        ).fetchone()
        run = db.execute(
            "SELECT * FROM restore_runs WHERE id=?", (run_id,)
        ).fetchone()
        cassette = db.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
            (run_id, cassette_sequence),
        ).fetchone()
        target = db.execute(
            "SELECT 1 FROM operation_hardware_targets WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        receipt = db.execute(
            "SELECT 1 FROM restore_release_receipts WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        forbidden = db.execute(
            "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
            "AND command_kind IN ('mount','unmount','load','unload','format') LIMIT 1",
            (operation_id,),
        ).fetchone()
        unfinished = db.execute(
            "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
            "AND state!='quiesced' LIMIT 1",
            (operation_id,),
        ).fetchone()
        restoring_item = db.execute(
            "SELECT 1 FROM restore_run_items WHERE run_id=? AND cassette_sequence=? "
            "AND state='restoring' LIMIT 1",
            (run_id, cassette_sequence),
        ).fetchone()
        incomplete_item = db.execute(
            "SELECT 1 FROM restore_run_items WHERE run_id=? AND cassette_sequence=? "
            "AND state NOT IN ('restored','skipped_verified') LIMIT 1",
            (run_id, cassette_sequence),
        ).fetchone()
        return bool(
            operation is not None
            and operation["kind"] == "restore.cassette"
            and operation["state"] == "recovery_required"
            and operation["job_id"] == run_id
            and operation["cassette_sequence"] == cassette_sequence
            and run is not None
            and run["plan_fingerprint_sha256"] == plan_fingerprint_sha256
            and run["current_cassette_sequence"] == cassette_sequence
            and run["state"] == "recovery_required"
            and cassette is not None
            and cassette["operation_id"] == operation_id
            and cassette["state"] == "recovery_required"
            and target is not None
            and receipt is None
            and forbidden is None
            and unfinished is None
            and restoring_item is None
            and incomplete_item is not None
        )

    def restore_pre_mount_recovery_candidate(
        self,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
    ) -> bool:
        """Prove a legacy failed restore never crossed the mount boundary."""

        return self._restore_pre_mount_recovery_candidate_tx(
            self.connection,
            operation_id,
            run_id,
            cassette_sequence,
            plan_fingerprint_sha256,
        )

    def request_restore_run_pause(
        self, run_id: str, *, actor: str, idempotency_key: str | None = None
    ) -> dict[str, Any]:
        """Persist an idempotent pause request and pause idle waiting work."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(actor, "restore pause actor")
        action = "restore.run.pause"
        request_sha256 = hashlib.sha256(
            json.dumps({"run_id": run_id}, separators=(",", ":"), sort_keys=True).encode()
        ).hexdigest()
        with self.transaction() as db:
            if idempotency_key is not None:
                replay = self.management_idempotency_replay(
                    actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_sha256=request_sha256,
                )
                if replay is not None:
                    return replay
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            if run is None:
                raise CatalogError("restore_run_not_found")
            if run["state"] == "paused":
                response = self._restore_run_mapping_tx(db, run)
                if idempotency_key is not None:
                    self._insert_management_receipt_tx(
                        db, actor=actor, idempotency_key=idempotency_key, action=action,
                        target_id=run_id, request_fingerprint_sha256=request_sha256,
                        response=response,
                    )
                return response
            if run["state"] not in {"waiting_media", "restoring"}:
                raise CatalogError("restore pause state conflict")
            latest = db.execute(
                "SELECT action FROM audit_entries WHERE result='accepted' "
                "AND action IN ('restore.run.pause','restore.run.resume') "
                "AND json_extract(payload_json,'$.run_id')=? "
                "ORDER BY id DESC LIMIT 1",
                (run_id,),
            ).fetchone()
            if latest is None or latest["action"] != "restore.run.pause":
                self._record_audit_tx(
                    db, actor, "restore.run.pause", "accepted",
                    f"restore-pause-{uuid.uuid4().hex}", None,
                    json.dumps({"run_id": run_id}, separators=(",", ":"), sort_keys=True),
                )
            active = db.execute(
                "SELECT 1 FROM daemon_operations WHERE kind='restore.cassette' "
                "AND job_id=? AND state='running' LIMIT 1",
                (run_id,),
            ).fetchone()
            if active is None:
                if run["state"] != "waiting_media":
                    raise CatalogError("restore pause operation is absent")
                db.execute(
                    "UPDATE restore_runs SET state='paused',last_error_code=NULL "
                    "WHERE id=? AND state='waiting_media'",
                    (run_id,),
                )
            current = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert current is not None
            response = self._restore_run_mapping_tx(db, current)
            if idempotency_key is not None:
                self._insert_management_receipt_tx(
                    db, actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_fingerprint_sha256=request_sha256,
                    response=response,
                )
            return response

    def resume_restore_run(
        self, run_id: str, *, actor: str, idempotency_key: str | None = None
    ) -> dict[str, Any]:
        """Resume only an exact paused checkpoint, never recovery evidence."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(actor, "restore resume actor")
        action = "restore.run.resume"
        request_sha256 = hashlib.sha256(
            json.dumps({"run_id": run_id}, separators=(",", ":"), sort_keys=True).encode()
        ).hexdigest()
        with self.transaction() as db:
            if idempotency_key is not None:
                replay = self.management_idempotency_replay(
                    actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_sha256=request_sha256,
                )
                if replay is not None:
                    return replay
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            if run is None:
                raise CatalogError("restore_run_not_found")
            if run["state"] != "paused":
                raise CatalogError("restore resume state conflict")
            if db.execute(
                "SELECT 1 FROM restore_item_conflicts WHERE run_id=? "
                "AND state IN ('recorded','authorized') LIMIT 1",
                (run_id,),
            ).fetchone() is not None:
                raise CatalogError("restore replacement authorization is required")
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE action='restore.run.cancel' "
                "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? LIMIT 1",
                (run_id,),
            ).fetchone() is not None:
                raise CatalogError("restore cancellation is terminal")
            if db.execute(
                "SELECT 1 FROM daemon_operations WHERE kind='restore.cassette' "
                "AND job_id=? AND state IN ('running','recovery_required') LIMIT 1",
                (run_id,),
            ).fetchone() is not None:
                raise CatalogError("restore resume operation is active")
            cassette = db.execute(
                "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
                (run_id, run["current_cassette_sequence"]),
            ).fetchone()
            if cassette is None or cassette["state"] != "waiting_media":
                raise CatalogError("restore resume checkpoint is not exact")
            latest_operation = db.execute(
                "SELECT id FROM daemon_operations WHERE kind='restore.cassette' "
                "AND job_id=? AND cassette_sequence=? "
                "ORDER BY rowid DESC LIMIT 1",
                (run_id, run["current_cassette_sequence"]),
            ).fetchone()
            if latest_operation is not None and not self._restore_pause_continuation_ready_tx(
                db,
                str(latest_operation["id"]),
                run_id,
                int(run["current_cassette_sequence"]),
                str(run["plan_fingerprint_sha256"]),
                require_resumed=False,
            ):
                raise CatalogError("restore resume checkpoint is not exact")
            self._record_audit_tx(
                db, actor, "restore.run.resume", "accepted",
                f"restore-resume-{uuid.uuid4().hex}", None,
                json.dumps({"run_id": run_id}, separators=(",", ":"), sort_keys=True),
            )
            db.execute(
                "UPDATE restore_runs SET state='waiting_media',last_error_code=NULL "
                "WHERE id=? AND state='paused'",
                (run_id,),
            )
            current = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert current is not None
            response = self._restore_run_mapping_tx(db, current)
            if idempotency_key is not None:
                self._insert_management_receipt_tx(
                    db, actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_fingerprint_sha256=request_sha256,
                    response=response,
                )
            return response

    def checkpoint_restore_run_control(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
    ) -> str | None:
        """Compatibility seam requiring an already durable exact release receipt."""

        self._validate_safe_identifier(run_id, "restore run id")
        if type(cassette_sequence) is not int or not 1 <= cassette_sequence <= 200:
            raise ValidationError("invalid restore cassette sequence")
        with self.transaction() as db:
            operation, run, _cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            boundary = self._restore_release_boundary_tx(
                db,
                operation_fence.operation_id,
                run_id,
                cassette_sequence,
                str(run["plan_fingerprint_sha256"]),
            )
            if boundary == "missing":
                raise CatalogError("restore control has no exact release receipt")
            return self._checkpoint_restore_control_or_complete_tx(
                db,
                operation,
                run,
                operation_fence,
                run_id,
                cassette_sequence,
                require_control=True,
            )

    def _insert_restore_release_receipt_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        run: sqlite3.Row,
        cassette_sequence: int,
        boundary: str,
        *,
        mount_receipt_sha256: str | None = None,
        unmount_receipt_sha256: str | None = None,
        unload_command_id: str | None = None,
    ) -> None:
        target = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        if target is None:
            raise CatalogError("restore release target is unavailable")
        values = (
            operation["id"],
            operation["owner_generation"],
            run["id"],
            cassette_sequence,
            run["plan_fingerprint_sha256"],
            boundary,
            self._restore_item_checkpoint_sha256_tx(
                db, str(run["id"]), cassette_sequence
            ),
            mount_receipt_sha256,
            unmount_receipt_sha256,
            unload_command_id,
            target["mount_path_sha256"],
            target["tape_device_identity_sha256"],
            target["scsi_device_identity_sha256"],
            target["expected_media_scope_sha256"],
            self._precise_utc_now(),
        )
        existing = db.execute(
            "SELECT * FROM restore_release_receipts WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        if existing is not None:
            if tuple(existing)[:-1] != values[:-1]:
                raise CatalogError("restore release receipt conflicts")
            return
        db.execute(
            "INSERT INTO restore_release_receipts(operation_id,owner_generation,"
            "run_id,cassette_sequence,plan_fingerprint_sha256,boundary,"
            "item_checkpoint_sha256,mount_receipt_sha256,unmount_receipt_sha256,"
            "unload_command_id,mount_path_sha256,tape_device_identity_sha256,"
            "scsi_device_identity_sha256,expected_media_scope_sha256,recorded_at) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            values,
        )

    def checkpoint_restore_control_before_mount(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
    ) -> str:
        """Terminalize pending control only at a proven no-mount boundary."""

        with self.transaction() as db:
            operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            if (
                operation["state"] != "running"
                or run["state"] != "waiting_media"
                or cassette["state"] != "waiting_media"
                or self._pending_restore_control_tx(db, run_id) is None
                or db.execute(
                    "SELECT 1 FROM restore_run_items WHERE run_id=? "
                    "AND cassette_sequence=? AND state='restoring' LIMIT 1",
                    (run_id, cassette_sequence),
                ).fetchone()
                is not None
                or db.execute(
                    "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
                    "AND (state!='quiesced' OR command_kind IN "
                    "('mount','unmount','load','unload','format')) LIMIT 1",
                    (operation_fence.operation_id,),
                ).fetchone()
                is not None
            ):
                raise CatalogError("restore pre-mount control boundary is not exact")
            self._insert_restore_release_receipt_tx(
                db, operation, run, cassette_sequence, "pre_mount"
            )
            control = self._checkpoint_restore_control_or_complete_tx(
                db,
                operation,
                run,
                operation_fence,
                run_id,
                cassette_sequence,
                require_control=True,
            )
            assert control in {"paused", "cancelled"}
            return control

    def record_restore_pre_mount_recovery_receipt(
        self,
        daemon_fence: DaemonFence,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
    ) -> None:
        """Repair the missing receipt only from an exact no-mount ledger."""

        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            if not self._restore_pre_mount_recovery_candidate_tx(
                db,
                operation_id,
                run_id,
                cassette_sequence,
                plan_fingerprint_sha256,
            ):
                raise CatalogError("restore pre-mount recovery boundary is not exact")
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert operation is not None and run is not None
            self._insert_restore_release_receipt_tx(
                db, operation, run, cassette_sequence, "pre_mount"
            )

    def record_restore_pre_mount_failure_receipt(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
    ) -> None:
        """Persist proof that a failed attempt never mounted or copied data."""

        with self.transaction() as db:
            operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            forbidden = db.execute(
                "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
                "AND command_kind IN ('mount','unmount','load','unload','format') LIMIT 1",
                (operation_fence.operation_id,),
            ).fetchone()
            unfinished = db.execute(
                "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
                "AND state!='quiesced' LIMIT 1",
                (operation_fence.operation_id,),
            ).fetchone()
            changed_item = db.execute(
                "SELECT 1 FROM restore_run_items WHERE run_id=? AND cassette_sequence=? "
                "AND state!='pending' LIMIT 1",
                (run_id, cassette_sequence),
            ).fetchone()
            if (
                operation["state"] != "running"
                or run["state"] != "waiting_media"
                or cassette["state"] != "waiting_media"
                or forbidden is not None
                or unfinished is not None
                or changed_item is not None
            ):
                raise CatalogError("restore pre-mount failure boundary is not exact")
            self._insert_restore_release_receipt_tx(
                db, operation, run, cassette_sequence, "pre_mount"
            )

    def record_restore_post_eject_receipt(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
        mounted: object,
        unmount: object,
        *,
        no_media_proven: bool,
    ) -> None:
        """Persist the exact read-only mount/unmount/eject chain."""

        from .tape.command_supervisor import LtfsFinalizationReceipt
        from .tape.models import MountedTape, UnmountResult

        if (
            type(no_media_proven) is not bool
            or no_media_proven is not True
            or type(mounted) is not MountedTape
            or type(unmount) is not UnmountResult
        ):
            raise ValidationError("restore release receipt is invalid")
        finalization = unmount.finalization_receipt
        if type(finalization) is not LtfsFinalizationReceipt:
            raise ValidationError("restore release receipt is invalid")
        session = mounted.session_receipt
        standalone = finalization.standalone_receipt
        with self.transaction() as db:
            operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (operation_fence.operation_id,),
            ).fetchone()
            path_digest = hashlib.sha256(
                b"lto-target-v1\0mount-path\0"
                + json.dumps(
                    str(Path(mounted.path).resolve(strict=False)),
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()
            if (
                operation["state"] != "running"
                or target is None
                or path_digest != target["mount_path_sha256"]
                or mounted.read_only is not True
                or session.operation_id != operation_fence.operation_id
                or session.owner_generation != operation_fence.owner_generation
                or session.read_only is not True
                or session.mounted is not True
                or session.observed_volume_label != cassette["volume_label"]
                or (
                    cassette["volume_uuid"] is not None
                    and session.observed_volume_uuid != cassette["volume_uuid"]
                )
                or finalization.session_receipt != session
                or finalization.unmounted is not True
                or finalization.child_quiesced is not True
                or standalone.operation_id != session.receipt_operation_uuid
                or standalone.volume_uuid != session.observed_volume_uuid
                or standalone.device_close_result_valid is not True
                or standalone.device_close_result != 0
                or standalone.cleanup_failed is not False
                or standalone.result != 0
            ):
                raise ValidationError("restore release receipt is invalid")
            unload = db.execute(
                "SELECT * FROM hardware_command_executions WHERE operation_id=? "
                "AND issued_generation=? AND command_kind='unload' "
                "AND state='quiesced' AND exit_outcome='completed' "
                "ORDER BY created_at DESC,id DESC LIMIT 1",
                (operation_fence.operation_id, operation_fence.owner_generation),
            ).fetchone()
            if (
                unload is None
                or unload["terminal_exit_code"] != 0
                or any(
                    unload[name] != target[name]
                    for name in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
            ):
                raise CatalogError("restore eject command receipt is unavailable")
            if self._restore_exact_no_media_probe_tx(
                db, operation, target, unload
            ) is None:
                raise CatalogError("restore no-media proof is unavailable")
            self._insert_restore_release_receipt_tx(
                db,
                operation,
                run,
                cassette_sequence,
                "post_eject",
                mount_receipt_sha256=self._restore_receipt_sha256(session),
                unmount_receipt_sha256=self._restore_receipt_sha256(unmount),
                unload_command_id=str(unload["id"]),
            )

    def _checkpoint_restore_control_or_complete_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        run: sqlite3.Row,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
        *,
        require_control: bool,
    ) -> str | None:
        if operation["state"] != "running":
            raise CatalogError("restore checkpoint operation is not running")
        if db.execute(
            "SELECT 1 FROM restore_run_items WHERE run_id=? "
            "AND cassette_sequence=? AND state='restoring' LIMIT 1",
            (run_id, cassette_sequence),
        ).fetchone() is not None:
            raise CatalogError("restore checkpoint is not at a file boundary")
        control = self._pending_restore_control_tx(db, run_id)
        if control is None and require_control:
            return None
        now = self._precise_utc_now()
        if control is not None:
            error_code = "restore_cancelled" if control == "cancelled" else "restore_paused"
            if control == "cancelled":
                cursor = db.execute(
                    "UPDATE restore_runs SET state='cancelled',completed_at=?,"
                    "last_error_code=? WHERE id=? AND state IN "
                    "('waiting_media','restoring','recovery_required')",
                    (now, error_code, run_id),
                )
            else:
                db.execute(
                    "UPDATE restore_run_cassettes SET state='waiting_media',"
                    "operation_id=NULL,completed_at=NULL,last_error_code=NULL "
                    "WHERE run_id=? AND sequence=? AND state IN "
                    "('waiting_media','restoring','recovery_required')",
                    (run_id, cassette_sequence),
                )
                cursor = db.execute(
                    "UPDATE restore_runs SET state='paused',completed_at=NULL,"
                    "last_error_code=NULL WHERE id=? AND state IN "
                    "('waiting_media','restoring','recovery_required')",
                    (run_id,),
                )
            if cursor.rowcount != 1:
                raise CatalogError("restore control state changed")
            db.execute(
                "UPDATE daemon_operations SET state='cancelled',finished_at=?,"
                "error_class='operator_required',error_code=?,error_message=NULL "
                "WHERE id=? AND state='running'",
                (now, error_code, operation_fence.operation_id),
            )
            self._record_audit_tx(
                db, "restore-coordinator", f"restore.run.{control}_checkpoint",
                "accepted", f"restore-control-{uuid.uuid4().hex}", None,
                json.dumps(
                    {"run_id": run_id, "cassette_sequence": cassette_sequence,
                     "operation_id": operation_fence.operation_id},
                    separators=(",", ":"), sort_keys=True,
                ),
            )
            return control
        cassette = db.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
            (run_id, cassette_sequence),
        ).fetchone()
        if cassette is None or cassette["state"] != "restoring":
            raise CatalogError("restore completion checkpoint is not exact")
        if db.execute(
            "SELECT 1 FROM restore_run_items WHERE run_id=? AND cassette_sequence=? "
            "AND state NOT IN ('restored','skipped_verified') LIMIT 1",
            (run_id, cassette_sequence),
        ).fetchone() is not None:
            raise CatalogError("restore cassette items are incomplete")
        db.execute(
            "UPDATE restore_run_cassettes SET state='completed',completed_at=?,"
            "last_error_code=NULL WHERE run_id=? AND sequence=? AND state='restoring'",
            (now, run_id, cassette_sequence),
        )
        following = db.execute(
            "SELECT sequence FROM restore_run_cassettes WHERE run_id=? AND sequence>? "
            "AND state='pending' ORDER BY sequence LIMIT 1",
            (run_id, cassette_sequence),
        ).fetchone()
        if following is None:
            cursor = db.execute(
                "UPDATE restore_runs SET state='completed',current_cassette_sequence=NULL,"
                "completed_at=?,last_error_code=NULL WHERE id=? AND state='restoring'",
                (now, run_id),
            )
            result = "completed"
        else:
            db.execute(
                "UPDATE restore_run_cassettes SET state='waiting_media' WHERE run_id=? "
                "AND sequence=? AND state='pending'",
                (run_id, following["sequence"]),
            )
            cursor = db.execute(
                "UPDATE restore_runs SET state='waiting_media',current_cassette_sequence=?,"
                "last_error_code=NULL WHERE id=? AND state='restoring'",
                (following["sequence"], run_id),
            )
            result = "waiting_media"
        if cursor.rowcount != 1:
            raise CatalogError("restore completion state changed")
        return result

    def checkpoint_restore_control_or_complete(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
    ) -> str:
        """Re-sample control and atomically choose it over cassette completion."""

        with self.transaction() as db:
            operation, run, _cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            if self._restore_release_boundary_tx(
                db, operation_fence.operation_id, run_id, cassette_sequence,
                str(run["plan_fingerprint_sha256"]),
            ) != "post_eject":
                raise CatalogError("restore completion has no exact post-eject receipt")
            result = self._checkpoint_restore_control_or_complete_tx(
                db, operation, run, operation_fence, run_id, cassette_sequence,
                require_control=False,
            )
            assert result is not None
            return result

    def request_restore_run_cancel(
        self, run_id: str, *, actor: str, idempotency_key: str | None = None
    ) -> dict[str, Any]:
        """Persist one idempotent file-boundary cancellation request."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(actor, "restore cancellation actor")
        action = "restore.run.cancel"
        request_sha256 = hashlib.sha256(
            json.dumps({"run_id": run_id}, separators=(",", ":"), sort_keys=True).encode()
        ).hexdigest()
        with self.transaction() as db:
            if idempotency_key is not None:
                replay = self.management_idempotency_replay(
                    actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_sha256=request_sha256,
                )
                if replay is not None:
                    return replay
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            if run is None:
                raise CatalogError("restore_run_not_found")
            existing = db.execute(
                "SELECT 1 FROM audit_entries WHERE action='restore.run.cancel' "
                "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? "
                "LIMIT 1",
                (run_id,),
            ).fetchone()
            if existing is None and run["state"] not in {
                "completed", "cancelled", "failed"
            }:
                self._record_audit_tx(
                    db,
                    actor,
                    "restore.run.cancel",
                    "accepted",
                    f"restore-cancel-{uuid.uuid4().hex}",
                    None,
                    json.dumps(
                        {"run_id": run_id},
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
            active = db.execute(
                "SELECT 1 FROM daemon_operations WHERE kind='restore.cassette' "
                "AND job_id=? AND state IN ('running','recovery_required') LIMIT 1",
                (run_id,),
            ).fetchone()
            prior = db.execute(
                "SELECT id,cassette_sequence FROM daemon_operations "
                "WHERE kind='restore.cassette' AND job_id=? "
                "ORDER BY rowid DESC LIMIT 1",
                (run_id,),
            ).fetchone()
            released = prior is None
            if prior is not None and prior["cassette_sequence"] is not None:
                released = self._restore_release_boundary_tx(
                    db,
                    str(prior["id"]),
                    run_id,
                    int(prior["cassette_sequence"]),
                    str(run["plan_fingerprint_sha256"]),
                ) in {"pre_mount", "post_eject"}
            if (
                run["state"] not in {"completed", "cancelled", "failed"}
                and active is None
                and released
            ):
                db.execute(
                    "UPDATE restore_runs SET state='cancelled',completed_at=?,"
                    "last_error_code='restore_cancelled' WHERE id=?",
                    (self._precise_utc_now(), run_id),
                )
            current = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert current is not None
            response = self._restore_run_mapping_tx(db, current)
            if idempotency_key is not None:
                self._insert_management_receipt_tx(
                    db, actor=actor, idempotency_key=idempotency_key, action=action,
                    target_id=run_id, request_fingerprint_sha256=request_sha256,
                    response=response,
                )
            return response

    def finalize_restore_run_cancel(self, run_id: str) -> dict[str, Any]:
        """Legacy callback seam: observe only; it has no release authority."""

        self._validate_safe_identifier(run_id, "restore run id")
        with self.transaction() as db:
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            if run is None:
                raise CatalogError("restore_run_not_found")
            return self._restore_run_mapping_tx(db, run)

    def _restore_pause_continuation_ready_tx(
        self,
        db: sqlite3.Connection,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
        *,
        require_resumed: bool,
    ) -> bool:
        """Validate one exact, safely released pause checkpoint continuation."""

        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
        ).fetchone()
        cassette = db.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
            (run_id, cassette_sequence),
        ).fetchone()
        checkpoint = db.execute(
            "SELECT id FROM audit_entries WHERE action='restore.run.paused_checkpoint' "
            "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? "
            "AND json_extract(payload_json,'$.cassette_sequence')=? "
            "AND json_extract(payload_json,'$.operation_id')=? "
            "ORDER BY id DESC LIMIT 1",
            (run_id, cassette_sequence, operation_id),
        ).fetchone()
        control = db.execute(
            "SELECT id,action FROM audit_entries WHERE result='accepted' "
            "AND action IN ('restore.run.pause','restore.run.resume') "
            "AND json_extract(payload_json,'$.run_id')=? ORDER BY id DESC LIMIT 1",
            (run_id,),
        ).fetchone()
        pause = db.execute(
            "SELECT id FROM audit_entries WHERE action='restore.run.pause' "
            "AND result='accepted' AND json_extract(payload_json,'$.run_id')=? "
            "ORDER BY id DESC LIMIT 1",
            (run_id,),
        ).fetchone()
        expected_control = "restore.run.resume" if require_resumed else "restore.run.pause"
        return bool(
            operation is not None
            and operation["kind"] == "restore.cassette"
            and operation["job_id"] == run_id
            and operation["cassette_sequence"] == cassette_sequence
            and operation["state"] == "cancelled"
            and operation["error_class"] == "operator_required"
            and operation["error_code"] == "restore_paused"
            and operation["finished_at"] is not None
            and cassette is not None
            and cassette["state"] == "waiting_media"
            and cassette["operation_id"] is None
            and checkpoint is not None
            and pause is not None
            and control is not None
            and control["action"] == expected_control
            and (
                not require_resumed
                or (
                    int(checkpoint["id"]) < int(control["id"])
                    and int(pause["id"]) < int(control["id"])
                )
            )
            and self._restore_release_boundary_tx(
                db,
                operation_id,
                run_id,
                cassette_sequence,
                plan_fingerprint_sha256,
            )
            in {"pre_mount", "post_eject"}
        )

    def _next_restore_sequence_candidate_tx(
        self, db: sqlite3.Connection
    ) -> dict[str, Any] | None:
        rows = db.execute(
            "SELECT run.id AS run_id,cassette.sequence AS cassette_sequence,"
            "run.plan_fingerprint_sha256 AS plan_fingerprint_sha256,"
            "(SELECT prior.id FROM daemon_operations prior "
            "WHERE prior.kind='restore.cassette' AND prior.job_id=run.id "
            "AND prior.cassette_sequence=cassette.sequence "
            "ORDER BY prior.rowid DESC LIMIT 1) "
            "AS latest_operation_id,"
            "1+(SELECT COUNT(*) FROM daemon_operations prior "
            "WHERE prior.kind='restore.cassette' AND prior.job_id=run.id "
            "AND prior.cassette_sequence=cassette.sequence) AS attempt_number "
            "FROM restore_runs run JOIN restore_run_cassettes cassette "
            "ON cassette.run_id=run.id "
            "WHERE run.state='waiting_media' "
            "AND run.current_cassette_sequence=cassette.sequence "
            "AND cassette.state='waiting_media' "
            "AND NOT EXISTS(SELECT 1 FROM daemon_operations active "
            "WHERE active.state IN ('running','recovery_required')) "
            "AND NOT EXISTS(SELECT 1 FROM audit_entries audit "
            "WHERE audit.action='restore.run.cancel' AND audit.result='accepted' "
            "AND json_extract(audit.payload_json,'$.run_id')=run.id) "
            "AND NOT EXISTS(SELECT 1 FROM audit_entries pause "
            "WHERE pause.action='restore.run.pause' AND pause.result='accepted' "
            "AND json_extract(pause.payload_json,'$.run_id')=run.id "
            "AND pause.id>COALESCE((SELECT MAX(resume.id) FROM audit_entries resume "
            "WHERE resume.action='restore.run.resume' AND resume.result='accepted' "
            "AND json_extract(resume.payload_json,'$.run_id')=run.id),0)) "
            "ORDER BY run.created_at,run.id"
        ).fetchall()
        for row in rows:
            candidate = dict(row)
            latest_operation_id = candidate.pop("latest_operation_id")
            candidate["source_operation_id"] = latest_operation_id
            if latest_operation_id is None:
                candidate["continuation_kind"] = "initial"
                return candidate
            prepared = db.execute(
                "SELECT 1 FROM restore_retry_preparations WHERE run_id=? "
                "AND cassette_sequence=? AND plan_fingerprint_sha256=? "
                "AND source_operation_id=? LIMIT 1",
                (
                    candidate["run_id"],
                    candidate["cassette_sequence"],
                    candidate["plan_fingerprint_sha256"],
                    latest_operation_id,
                ),
            ).fetchone() is not None
            paused = self._restore_pause_continuation_ready_tx(
                db,
                str(latest_operation_id),
                str(candidate["run_id"]),
                int(candidate["cassette_sequence"]),
                str(candidate["plan_fingerprint_sha256"]),
                require_resumed=True,
            )
            if prepared == paused:
                continue
            candidate["continuation_kind"] = (
                "recovery_retry" if prepared else "paused_resume"
            )
            return candidate
        return None

    def next_restore_sequence_candidate(self) -> dict[str, Any] | None:
        """Return one exact waiting cassette and its monotonic attempt number."""

        with self.transaction() as db:
            return self._next_restore_sequence_candidate_tx(db)

    def admit_restore_sequence_operation(
        self,
        candidate: OperationRecord,
        daemon_fence: DaemonFence,
        *,
        admission_open: bool,
        hardware_target: HardwareTargetBinding,
        expected_candidate: Mapping[str, Any],
    ) -> OperationAdmission:
        """Revalidate and admit one restore candidate in the same transaction."""

        if (
            candidate.kind != "restore.cassette"
            or candidate.job_id is None
            or candidate.cassette_sequence is None
        ):
            raise ValidationError("restore sequence operation is invalid")
        with self.transaction() as db:
            replay = self._find_operation_by_key_tx(db, candidate.idempotency_key)
            if replay is not None:
                persisted_target = db.execute(
                    "SELECT mount_path_sha256,tape_device_identity_sha256,"
                    "scsi_device_identity_sha256,expected_media_scope_sha256 "
                    "FROM operation_hardware_targets WHERE operation_id=?",
                    (replay["id"],),
                ).fetchone()
                if (
                    replay["kind"] != candidate.kind
                    or replay["job_id"] != candidate.job_id
                    or replay["cassette_sequence"] != candidate.cassette_sequence
                    or persisted_target is None
                    or tuple(persisted_target) != self._target_values(hardware_target)
                ):
                    raise CatalogError("restore sequence admission replay conflicts")
                return self.admit_operation(
                    candidate,
                    daemon_fence,
                    admission_open=admission_open,
                    hardware_target=hardware_target,
                )
            current = self._next_restore_sequence_candidate_tx(db)
            required = (
                "run_id",
                "cassette_sequence",
                "plan_fingerprint_sha256",
                "attempt_number",
                "source_operation_id",
                "continuation_kind",
            )
            try:
                matches = current is not None and all(
                    current[name] == expected_candidate[name] for name in required
                )
                attempt_number = int(expected_candidate["attempt_number"])
            except (KeyError, TypeError, ValueError):
                matches = False
                attempt_number = 0
            expected_key = hashlib.sha256(
                f"restore.cassette\0{candidate.job_id}\0"
                f"{candidate.cassette_sequence}\0{attempt_number}".encode()
            ).hexdigest()
            if (
                not matches
                or candidate.job_id != expected_candidate.get("run_id")
                or candidate.cassette_sequence
                != expected_candidate.get("cassette_sequence")
                or candidate.idempotency_key != expected_key
            ):
                raise MutationAdmissionClosed("restore sequence candidate changed")
            return self.admit_operation(
                candidate,
                daemon_fence,
                admission_open=admission_open,
                hardware_target=hardware_target,
            )

    def prepare_restore_retry_after_resolution(
        self,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
        daemon_fence: DaemonFence,
    ) -> dict[str, Any]:
        """Expose a retry only after exact physical recovery was resolved."""

        self._validate_safe_identifier(operation_id, "restore operation id")
        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_sha256(
            plan_fingerprint_sha256, "restore plan fingerprint"
        )
        if type(cassette_sequence) is not int or not 1 <= cassette_sequence <= 200:
            raise ValidationError("invalid restore cassette sequence")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            cassette = db.execute(
                "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
                (run_id, cassette_sequence),
            ).fetchone()
            resolution = db.execute(
                "SELECT * FROM recovery_resolutions WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if (
                operation is None
                or run is None
                or cassette is None
                or resolution is None
                or operation["kind"] != "restore.cassette"
                or operation["job_id"] != run_id
                or operation["cassette_sequence"] != cassette_sequence
                or operation["state"] != "cancelled"
                or resolution["resolved_by_generation"] != daemon_fence.generation
                or run["plan_fingerprint_sha256"] != plan_fingerprint_sha256
                or run["current_cassette_sequence"] != cassette_sequence
                or cassette["operation_id"] != operation_id
            ):
                raise CatalogError("restore recovery resolution is not exact")
            recorded = db.execute(
                "SELECT 1 FROM restore_item_conflicts conflict "
                "JOIN restore_run_items item ON item.run_id=conflict.run_id "
                "AND item.sequence=conflict.item_sequence "
                "WHERE conflict.run_id=? AND item.cassette_sequence=? "
                "AND conflict.state='recorded' LIMIT 1",
                (run_id, cassette_sequence),
            ).fetchone()
            if recorded is not None:
                raise CatalogError("restore destination conflict requires authorization")
            authorized = db.execute(
                "SELECT 1 FROM restore_item_conflicts conflict "
                "JOIN restore_run_items item ON item.run_id=conflict.run_id "
                "AND item.sequence=conflict.item_sequence "
                "WHERE conflict.run_id=? AND item.cassette_sequence=? "
                "AND conflict.state='authorized' LIMIT 1",
                (run_id, cassette_sequence),
            ).fetchone()
            if authorized is None:
                if run["state"] not in {"restoring", "recovery_required"} or cassette[
                    "state"
                ] not in {"restoring", "recovery_required"}:
                    raise CatalogError("restore retry checkpoint is not incomplete")
                db.execute(
                    "UPDATE restore_runs SET state='waiting_media',"
                    "last_error_code=NULL WHERE id=?",
                    (run_id,),
                )
                db.execute(
                    "UPDATE restore_run_cassettes SET state='waiting_media',"
                    "operation_id=NULL,last_error_code=NULL "
                    "WHERE run_id=? AND sequence=?",
                    (run_id, cassette_sequence),
                )
            else:
                if run["state"] != "recovery_required" or cassette[
                    "state"
                ] != "recovery_required":
                    raise CatalogError("restore replacement checkpoint is not exact")
                db.execute(
                    "UPDATE restore_run_cassettes SET operation_id=NULL "
                    "WHERE run_id=? AND sequence=?",
                    (run_id, cassette_sequence),
                )
            current = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert current is not None
            return self._restore_run_mapping_tx(db, current)

    def resolve_restore_recovery_boundary(
        self,
        operation_id: str,
        run_id: str,
        cassette_sequence: int,
        plan_fingerprint_sha256: str,
        daemon_fence: DaemonFence,
        resolution: SafeRecoveryResolution,
        *,
        action: Literal["retry", "commit", "control"],
    ) -> dict[str, Any]:
        """Resolve recovery and its exact restore disposition in one transaction."""

        self._validate_safe_identifier(operation_id, "restore operation id")
        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_sha256(plan_fingerprint_sha256, "restore plan fingerprint")
        if (
            type(cassette_sequence) is not int
            or not 1 <= cassette_sequence <= 200
            or action not in {"retry", "commit", "control"}
        ):
            raise ValidationError("invalid restore recovery disposition")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            cassette = db.execute(
                "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
                (run_id, cassette_sequence),
            ).fetchone()
            if (
                operation is None
                or run is None
                or cassette is None
                or operation["kind"] != "restore.cassette"
                or operation["job_id"] != run_id
                or operation["cassette_sequence"] != cassette_sequence
                or operation["state"] != "recovery_required"
                or run["plan_fingerprint_sha256"] != plan_fingerprint_sha256
                or run["current_cassette_sequence"] != cassette_sequence
                or cassette["operation_id"] != operation_id
            ):
                raise CatalogError("restore recovery boundary is not exact")
            boundary = self._restore_release_boundary_tx(
                db,
                operation_id,
                run_id,
                cassette_sequence,
                plan_fingerprint_sha256,
            )
            if boundary == "missing":
                raise CatalogError("restore release receipt chain is missing")
            incomplete = db.execute(
                "SELECT sequence FROM restore_run_items WHERE run_id=? "
                "AND cassette_sequence=? AND state NOT IN ('restored','skipped_verified') "
                "ORDER BY sequence LIMIT 1",
                (run_id, cassette_sequence),
            ).fetchone()
            pending_control = self._pending_restore_control_tx(db, run_id)
            effective_action = (
                "control" if pending_control is not None else action
            )
            if effective_action == "control" and pending_control is None:
                raise CatalogError("restore recovery control is not pending")
            if effective_action == "commit" and (
                boundary != "post_eject" or incomplete is not None
            ):
                raise CatalogError("restore recovery commit is not exact")
            if effective_action == "retry" and (
                boundary not in {"pre_mount", "post_eject"} or incomplete is None
            ):
                raise CatalogError("restore recovery retry is not exact")
            if effective_action == "retry" and db.execute(
                "SELECT 1 FROM restore_item_conflicts conflict "
                "JOIN restore_run_items item ON item.run_id=conflict.run_id "
                "AND item.sequence=conflict.item_sequence "
                "WHERE conflict.run_id=? AND item.cassette_sequence=? "
                "AND conflict.state='recorded' LIMIT 1",
                (run_id, cassette_sequence),
            ).fetchone() is not None:
                raise CatalogError("restore destination conflict requires authorization")
            self.resolve_recovery(
                operation_id, daemon_fence, resolution, _db=db
            )
            now = self._precise_utc_now()
            if effective_action == "retry":
                db.execute(
                    "INSERT INTO restore_retry_preparations(source_operation_id,"
                    "resolved_by_generation,run_id,cassette_sequence,"
                    "plan_fingerprint_sha256,prepared_at) VALUES(?,?,?,?,?,?)",
                    (
                        operation_id,
                        daemon_fence.generation,
                        run_id,
                        cassette_sequence,
                        plan_fingerprint_sha256,
                        now,
                    ),
                )
                cassette_cursor = db.execute(
                    "UPDATE restore_run_cassettes SET state='waiting_media',"
                    "operation_id=NULL,last_error_code=NULL WHERE run_id=? "
                    "AND sequence=? AND state IN ('restoring','recovery_required')",
                    (run_id, cassette_sequence),
                )
                run_cursor = db.execute(
                    "UPDATE restore_runs SET state='waiting_media',last_error_code=NULL "
                    "WHERE id=? AND state IN ('restoring','recovery_required')",
                    (run_id,),
                )
                if cassette_cursor.rowcount != 1 or run_cursor.rowcount != 1:
                    raise CatalogError("restore retry readiness changed")
            elif effective_action == "control":
                assert pending_control is not None
                error_code = (
                    "restore_cancelled"
                    if pending_control == "cancelled"
                    else "restore_paused"
                )
                if pending_control == "paused":
                    db.execute(
                        "UPDATE restore_run_cassettes SET state='waiting_media',"
                        "operation_id=NULL,last_error_code=NULL WHERE run_id=? "
                        "AND sequence=? AND state IN ('restoring','recovery_required')",
                        (run_id, cassette_sequence),
                    )
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='paused',completed_at=NULL,"
                        "last_error_code=NULL WHERE id=? AND state IN "
                        "('restoring','recovery_required')",
                        (run_id,),
                    )
                else:
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='cancelled',completed_at=?,"
                        "last_error_code=? WHERE id=? AND state IN "
                        "('restoring','recovery_required')",
                        (now, error_code, run_id),
                    )
                if run_cursor.rowcount != 1:
                    raise CatalogError("restore recovery control state changed")
            else:
                cassette_cursor = db.execute(
                    "UPDATE restore_run_cassettes SET state='completed',completed_at=?,"
                    "last_error_code=NULL WHERE run_id=? AND sequence=? AND state IN "
                    "('restoring','recovery_required')",
                    (now, run_id, cassette_sequence),
                )
                following = db.execute(
                    "SELECT sequence FROM restore_run_cassettes WHERE run_id=? "
                    "AND sequence>? AND state='pending' ORDER BY sequence LIMIT 1",
                    (run_id, cassette_sequence),
                ).fetchone()
                if following is None:
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='completed',"
                        "current_cassette_sequence=NULL,completed_at=?,last_error_code=NULL "
                        "WHERE id=? AND state IN ('restoring','recovery_required')",
                        (now, run_id),
                    )
                else:
                    db.execute(
                        "UPDATE restore_run_cassettes SET state='waiting_media' "
                        "WHERE run_id=? AND sequence=? AND state='pending'",
                        (run_id, following["sequence"]),
                    )
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='waiting_media',"
                        "current_cassette_sequence=?,last_error_code=NULL WHERE id=? "
                        "AND state IN ('restoring','recovery_required')",
                        (following["sequence"], run_id),
                    )
                if cassette_cursor.rowcount != 1 or run_cursor.rowcount != 1:
                    raise CatalogError("restore recovery commit state changed")
            current = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert current is not None
            return self._restore_run_mapping_tx(db, current)

    def create_restore_run(
        self,
        plan_id: str,
        *,
        actor: str,
        idempotency_key: str,
        request_sha256: str,
    ) -> dict[str, Any]:
        """Create or replay one immutable-plan restore run."""

        self._validate_safe_identifier(plan_id, "restore plan id")
        self._validate_safe_identifier(actor, "restore run actor")
        self._validate_sha256(request_sha256, "restore run request digest")
        action = "restore.run.create"
        with self.transaction() as db:
            replay = self.management_idempotency_replay(
                actor=actor,
                idempotency_key=idempotency_key,
                action=action,
                target_id=plan_id,
                request_sha256=request_sha256,
            )
            if replay is not None:
                replay_id = replay.get("id")
                if not isinstance(replay_id, str):
                    raise CatalogError("invalid management idempotency record")
                row = db.execute(
                    "SELECT * FROM restore_runs WHERE id=?", (replay_id,)
                ).fetchone()
                if row is None or row["plan_id"] != plan_id:
                    raise CatalogError("invalid management idempotency record")
                return self._restore_run_mapping_tx(db, row)
            plan = db.execute(
                "SELECT * FROM restore_plans WHERE id=?", (plan_id,)
            ).fetchone()
            if plan is None:
                raise CatalogError("restore_plan_not_found")
            if (
                plan["state"] != "planned"
                or plan["identity_state"] != "exact"
                or plan["invalidation_reason"] is not None
            ):
                raise CatalogError("restore plan identity is not executable")
            destination = db.execute(
                "SELECT * FROM restore_plan_destinations WHERE plan_id=?",
                (plan_id,),
            ).fetchone()
            if (
                destination is None
                or destination["destination_state"] != "exact"
                or destination["invalidation_reason"] is not None
            ):
                raise CatalogError("restore plan destination is not executable")
            try:
                self._validate_restore_destination_snapshot(
                    str(destination["kind"]),
                    str(destination["root"]),
                    str(destination["anchor"]),
                )
            except ValidationError as exc:
                raise CatalogError("restore plan destination is invalid") from exc
            active = db.execute(
                "SELECT id FROM restore_runs WHERE plan_id=? AND state IN "
                "('planned','waiting_media','restoring','paused','recovery_required')",
                (plan_id,),
            ).fetchone()
            if active is not None:
                raise CatalogError("restore_run_active")
            plan_cassettes = db.execute(
                "SELECT * FROM restore_plan_cassettes WHERE plan_id=? ORDER BY sequence",
                (plan_id,),
            ).fetchall()
            plan_items = db.execute(
                "SELECT * FROM restore_plan_items WHERE plan_id=? ORDER BY sequence",
                (plan_id,),
            ).fetchall()
            if (
                not plan_cassettes
                or not plan_items
                or [int(row["sequence"]) for row in plan_cassettes]
                != list(range(1, len(plan_cassettes) + 1))
                or [int(row["sequence"]) for row in plan_items]
                != list(range(1, len(plan_items) + 1))
                or any(
                    not isinstance(row["physical_label"], str)
                    or not row["physical_label"]
                    or not isinstance(row["volume_serial"], str)
                    or not row["volume_serial"]
                    for row in plan_cassettes
                )
            ):
                raise CatalogError("restore plan identity is incomplete")
            plan_mapping = self._restore_plan_mapping(
                plan, plan_cassettes, plan_items, destination=destination
            )
            plan_fingerprint = hashlib.sha256(
                json.dumps(
                    plan_mapping,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()
            cassette_by_tape = {
                str(row["tape_id"]): int(row["sequence"])
                for row in plan_cassettes
            }
            destination_root = PurePosixPath(str(destination["root"]))
            item_values: list[tuple[Any, ...]] = []
            for row in plan_items:
                relative = PurePosixPath(str(row["relative_path"]))
                library_id = str(row["library_id"])
                if (
                    relative.is_absolute()
                    or any(part in {".", ".."} for part in relative.parts)
                    or str(relative) != row["relative_path"]
                    or _SAFE_IDENTIFIER.fullmatch(library_id) is None
                    or str(row["tape_id"]) not in cassette_by_tape
                    or row["physical_label"] is None
                    or row["volume_label"] is None
                    or row["block_id"] is None
                    or row["is_current"] is None
                ):
                    raise CatalogError("restore plan item identity is incomplete")
                destination_relative = str(PurePosixPath(library_id) / relative)
                canonical_destination = str(destination_root / destination_relative)
                if (
                    not canonical_destination.startswith("/")
                    or len(canonical_destination) > 4096
                ):
                    raise CatalogError("restore plan destination is invalid")
                item_values.append(
                    (
                        int(row["sequence"]),
                        int(row["sequence"]),
                        cassette_by_tape[str(row["tape_id"])],
                        int(row["file_version_id"]),
                        library_id,
                        row["relative_path"],
                        row["tape_relative_path"],
                        row["tape_id"],
                        row["cassette_number"],
                        row["physical_label"],
                        row["volume_label"],
                        row["block_id"],
                        int(row["size"]),
                        row["sha256"],
                        row["copied_at"],
                        int(row["is_current"]),
                        destination_relative,
                        canonical_destination,
                    )
                )
            run_id = f"RESTORE-RUN-{uuid.uuid4().hex}"
            created_at = self._precise_utc_now()
            db.execute(
                "INSERT INTO restore_runs(id,plan_id,actor,state,"
                "current_cassette_sequence,request_sha256,plan_fingerprint_sha256,"
                "total_files,total_bytes,created_at) "
                "VALUES(?,?,?,'waiting_media',1,?,?,?,?,?)",
                (
                    run_id,
                    plan_id,
                    actor,
                    request_sha256,
                    plan_fingerprint,
                    int(plan["total_files"]),
                    int(plan["total_bytes"]),
                    created_at,
                ),
            )
            db.executemany(
                "INSERT INTO restore_run_cassettes(run_id,plan_id,sequence,"
                "plan_cassette_sequence,tape_id,cassette_number,physical_label,"
                "volume_label,volume_serial,volume_uuid,state,item_count,total_bytes) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?, ?,?)",
                [
                    (
                        run_id,
                        plan_id,
                        int(row["sequence"]),
                        int(row["sequence"]),
                        row["tape_id"],
                        row["cassette_number"],
                        row["physical_label"],
                        next(
                            item["volume_label"]
                            for item in plan_items
                            if item["tape_id"] == row["tape_id"]
                        ),
                        row["volume_serial"],
                        row["volume_uuid"],
                        "waiting_media" if int(row["sequence"]) == 1 else "pending",
                        int(row["item_count"]),
                        int(row["total_bytes"]),
                    )
                    for row in plan_cassettes
                ],
            )
            db.executemany(
                "INSERT INTO restore_run_items(run_id,plan_id,sequence,"
                "plan_item_sequence,cassette_sequence,file_version_id,library_id,"
                "relative_path,tape_relative_path,tape_id,cassette_number,"
                "physical_label,volume_label,block_id,size,sha256,copied_at,is_current,"
                "destination_relative_path,canonical_destination,state) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending')",
                [(run_id, plan_id, *values) for values in item_values],
            )
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            assert run is not None
            response = self._restore_run_mapping_tx(db, run)
            self._insert_management_receipt_tx(
                db,
                actor=actor,
                idempotency_key=idempotency_key,
                action=action,
                target_id=plan_id,
                request_fingerprint_sha256=request_sha256,
                response=response,
            )
            self._record_audit_tx(
                db,
                actor,
                action,
                "accepted",
                idempotency_key,
                None,
                json.dumps(
                    {"plan_id": plan_id, "run_id": run_id},
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            )
            return response

    def next_restore_cassette(self, run_id: str) -> sqlite3.Row | None:
        self._validate_safe_identifier(run_id, "restore run id")
        return self.connection.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? "
            "AND state!='completed' ORDER BY sequence LIMIT 1",
            (run_id,),
        ).fetchone()

    def _assert_restore_operation_tx(
        self,
        db: sqlite3.Connection,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
    ) -> tuple[sqlite3.Row, sqlite3.Row, sqlite3.Row]:
        if type(operation_fence) is not OperationFence:
            raise ValidationError("invalid restore operation fence")
        operation = self._assert_operation_fence_tx(db, operation_fence)
        run = db.execute(
            "SELECT * FROM restore_runs WHERE id=?", (run_id,)
        ).fetchone()
        cassette = db.execute(
            "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
            (run_id, cassette_sequence),
        ).fetchone()
        if (
            run is None
            or cassette is None
            or operation["kind"] != "restore.cassette"
            or operation["job_id"] != run_id
            or operation["cassette_sequence"] != cassette_sequence
            or run["current_cassette_sequence"] != cassette_sequence
            or cassette["operation_id"] not in {None, operation_fence.operation_id}
        ):
            raise StaleOperationFence("restore operation is not current")
        if cassette["operation_id"] is None:
            db.execute(
                "UPDATE restore_run_cassettes SET operation_id=?,"
                "started_at=COALESCE(started_at,?) WHERE run_id=? AND sequence=?",
                (
                    operation_fence.operation_id,
                    self._precise_utc_now(),
                    run_id,
                    cassette_sequence,
                ),
            )
            cassette = db.execute(
                "SELECT * FROM restore_run_cassettes WHERE run_id=? AND sequence=?",
                (run_id, cassette_sequence),
            ).fetchone()
            assert cassette is not None
        return operation, run, cassette

    @staticmethod
    def _restore_has_open_conflicts_tx(
        db: sqlite3.Connection,
        run_id: str,
    ) -> bool:
        return (
            db.execute(
                "SELECT 1 FROM restore_item_conflicts WHERE run_id=? "
                "AND state IN ('recorded','authorized') LIMIT 1",
                (run_id,),
            ).fetchone()
            is not None
        )

    @staticmethod
    def _validate_restore_error_code(error_code: str | None) -> None:
        if error_code is not None and (
            not isinstance(error_code, str)
            or not 1 <= len(error_code) <= 64
            or _SAFE_IDENTIFIER.fullmatch(error_code) is None
        ):
            raise ValidationError("invalid restore error code")

    def record_restore_item_conflict(
        self,
        operation_fence: OperationFence,
        run_id: str,
        item_sequence: int,
        *,
        canonical_destination: str,
        observed_size: int,
        observed_sha256: str,
    ) -> dict[str, Any]:
        """Persist one independently observed differing-destination conflict."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_sha256(observed_sha256, "restore conflict digest")
        if (
            type(item_sequence) is not int
            or not 1 <= item_sequence <= 200
            or not isinstance(canonical_destination, str)
            or not canonical_destination.startswith("/")
            or "\x00" in canonical_destination
            or len(canonical_destination) > 4096
            or type(observed_size) is not int
            or not 0 <= observed_size <= 2**63 - 1
        ):
            raise ValidationError("invalid restore conflict evidence")
        with self.transaction() as db:
            item = db.execute(
                "SELECT * FROM restore_run_items WHERE run_id=? AND sequence=?",
                (run_id, item_sequence),
            ).fetchone()
            if item is None:
                raise CatalogError("restore_item_not_found")
            _operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, int(item["cassette_sequence"])
            )
            if (
                run["state"] == "recovery_required"
                or cassette["state"] == "recovery_required"
                or self._restore_has_open_conflicts_tx(db, run_id)
            ):
                raise CatalogError("restore recovery exit is required")
            existing = db.execute(
                "SELECT * FROM restore_item_conflicts WHERE run_id=? "
                "AND item_sequence=? AND state IN ('recorded','authorized')",
                (run_id, item_sequence),
            ).fetchone()
            evidence = (
                int(item["file_version_id"]),
                canonical_destination,
                observed_size,
                observed_sha256,
            )
            if existing is not None:
                if tuple(
                    existing[key]
                    for key in (
                        "file_version_id",
                        "canonical_destination",
                        "observed_size",
                        "observed_sha256",
                    )
                ) != evidence:
                    raise CatalogError("restore conflict evidence changed")
                return self._restore_conflict_mapping(existing)
            if (
                item["state"] not in {"pending", "restoring"}
                or item["canonical_destination"] != canonical_destination
            ):
                raise CatalogError("restore conflict is not exact")
            conflict_sequence = int(
                db.execute(
                    "SELECT COALESCE(MAX(conflict_sequence),0)+1 "
                    "FROM restore_item_conflicts WHERE run_id=? AND item_sequence=?",
                    (run_id, item_sequence),
                ).fetchone()[0]
            )
            conflict_id = f"RESTORE-CONFLICT-{uuid.uuid4().hex}"
            now = self._precise_utc_now()
            db.execute(
                "INSERT INTO restore_item_conflicts(id,run_id,item_sequence,"
                "conflict_sequence,file_version_id,canonical_destination,"
                "observed_size,observed_sha256,state,recorded_at) "
                "VALUES(?,?,?,?,?,?,?,?,'recorded',?)",
                (
                    conflict_id,
                    run_id,
                    item_sequence,
                    conflict_sequence,
                    *evidence,
                    now,
                ),
            )
            db.execute(
                "UPDATE restore_run_items SET state='recovery_required',"
                "bytes_copied=0,observed_sha256=?,error_code='destination_conflict',"
                "started_at=COALESCE(started_at,?),completed_at=NULL "
                "WHERE run_id=? AND sequence=? AND state IN ('pending','restoring')",
                (observed_sha256, now, run_id, item_sequence),
            )
            db.execute(
                "UPDATE restore_run_cassettes SET state='recovery_required',"
                "last_error_code='destination_conflict' "
                "WHERE run_id=? AND sequence=?",
                (run_id, item["cassette_sequence"]),
            )
            db.execute(
                "UPDATE restore_runs SET state='recovery_required',"
                "started_at=COALESCE(started_at,?),"
                "last_error_code='destination_conflict' WHERE id=?",
                (now, run_id),
            )
            row = db.execute(
                "SELECT * FROM restore_item_conflicts WHERE id=?", (conflict_id,)
            ).fetchone()
            assert row is not None
            return self._restore_conflict_mapping(row)

    def authorize_restore_item_replacement(
        self,
        run_id: str,
        item_sequence: int,
        *,
        administrator: str,
        fresh_reauthentication: str,
        idempotency_key: str,
    ) -> dict[str, Any]:
        """Authorize one durable conflict after server-side exact binding checks."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(administrator, "restore administrator")
        self._validate_sha256(
            fresh_reauthentication, "fresh reauthentication proof digest"
        )
        if type(item_sequence) is not int or not 1 <= item_sequence <= 200:
            raise ValidationError("invalid restore item sequence")
        action = "restore.replacement.authorize"
        with self.transaction() as db:
            conflict = db.execute(
                "SELECT * FROM restore_item_conflicts WHERE run_id=? "
                "AND item_sequence=? ORDER BY conflict_sequence DESC LIMIT 1",
                (run_id, item_sequence),
            ).fetchone()
            item = db.execute(
                "SELECT * FROM restore_run_items WHERE run_id=? AND sequence=?",
                (run_id, item_sequence),
            ).fetchone()
            run = db.execute(
                "SELECT * FROM restore_runs WHERE id=?", (run_id,)
            ).fetchone()
            if conflict is None or item is None or run is None:
                raise CatalogError("restore conflict not found")
            request_sha256 = hashlib.sha256(
                json.dumps(
                    {
                        "administrator": administrator,
                        "canonical_destination": conflict["canonical_destination"],
                        "conflict_id": conflict["id"],
                        "file_version_id": int(conflict["file_version_id"]),
                        "fresh_reauthentication_sha256": fresh_reauthentication,
                        "item_sequence": item_sequence,
                        "observed_sha256": conflict["observed_sha256"],
                        "observed_size": int(conflict["observed_size"]),
                        "run_id": run_id,
                    },
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()
            replay = self.management_idempotency_replay(
                actor=administrator,
                idempotency_key=idempotency_key,
                action=action,
                target_id=run_id,
                request_sha256=request_sha256,
            )
            if replay is not None:
                authorization_id = replay.get("id")
                row = db.execute(
                    "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                    (authorization_id,),
                ).fetchone()
                if row is None:
                    raise CatalogError("invalid management idempotency record")
                return self._restore_replacement_authorization_mapping(row)
            if db.execute(
                "SELECT 1 FROM restore_replacement_authorizations "
                "WHERE reauthentication_proof_sha256=?",
                (fresh_reauthentication,),
            ).fetchone() is not None:
                raise CatalogError("fresh reauthentication proof was already used")
            if (
                run["state"] != "recovery_required"
                or item["state"] != "recovery_required"
                or conflict["state"] != "recorded"
                or conflict["authorization_id"] is not None
                or int(conflict["file_version_id"]) != int(item["file_version_id"])
                or conflict["canonical_destination"] != item["canonical_destination"]
            ):
                raise CatalogError("restore conflict evidence is stale or mismatched")
            authorization_id = f"RESTORE-AUTH-{uuid.uuid4().hex}"
            now = self._precise_utc_now()
            db.execute(
                "INSERT INTO restore_replacement_authorizations(id,conflict_id,"
                "run_id,item_sequence,file_version_id,canonical_destination,"
                "observed_size,observed_sha256,administrator,"
                "reauthentication_proof_sha256,request_sha256,state,authorized_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,'authorized',?)",
                (
                    authorization_id,
                    conflict["id"],
                    run_id,
                    item_sequence,
                    conflict["file_version_id"],
                    conflict["canonical_destination"],
                    conflict["observed_size"],
                    conflict["observed_sha256"],
                    administrator,
                    fresh_reauthentication,
                    request_sha256,
                    now,
                ),
            )
            db.execute(
                "UPDATE restore_item_conflicts SET state='authorized',"
                "authorization_id=?,authorized_at=? WHERE id=? AND state='recorded'",
                (authorization_id, now, conflict["id"]),
            )
            row = db.execute(
                "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                (authorization_id,),
            ).fetchone()
            assert row is not None
            response = self._restore_replacement_authorization_mapping(row)
            self._insert_management_receipt_tx(
                db,
                actor=administrator,
                idempotency_key=idempotency_key,
                action=action,
                target_id=run_id,
                request_fingerprint_sha256=request_sha256,
                response=response,
            )
            self._record_audit_tx(
                db,
                administrator,
                action,
                "accepted",
                idempotency_key,
                None,
                json.dumps(
                    {
                        "authorization_id": authorization_id,
                        "conflict_id": conflict["id"],
                        "item_sequence": item_sequence,
                        "run_id": run_id,
                    },
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            )
        return response

    def restore_replacement_authorization_replay(
        self, run_id: str, item_sequence: int, *, administrator: str,
        fresh_reauthentication: str, idempotency_key: str,
    ) -> dict[str, Any] | None:
        """Return an exact prior authorization before proof expiry is evaluated."""
        with self.transaction() as db:
            conflict = db.execute(
                "SELECT * FROM restore_item_conflicts WHERE run_id=? AND item_sequence=? "
                "ORDER BY conflict_sequence DESC LIMIT 1", (run_id, item_sequence)
            ).fetchone()
            if conflict is None:
                return None
            request_sha256 = hashlib.sha256(json.dumps({
                "administrator": administrator, "canonical_destination": conflict["canonical_destination"],
                "conflict_id": conflict["id"], "file_version_id": int(conflict["file_version_id"]),
                "fresh_reauthentication_sha256": fresh_reauthentication, "item_sequence": item_sequence,
                "observed_sha256": conflict["observed_sha256"], "observed_size": int(conflict["observed_size"]),
                "run_id": run_id,
            }, separators=(",", ":"), sort_keys=True).encode()).hexdigest()
            return self.management_idempotency_replay(
                actor=administrator, idempotency_key=idempotency_key,
                action="restore.replacement.authorize", target_id=run_id,
                request_sha256=request_sha256,
            )

    def consume_restore_item_replacement_authorization(
        self,
        operation_fence: OperationFence,
        run_id: str,
        item_sequence: int,
        authorization_id: str,
    ) -> dict[str, Any]:
        """Atomically consume the exact authorization before replacement."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(
            authorization_id, "restore replacement authorization id"
        )
        if type(item_sequence) is not int or not 1 <= item_sequence <= 200:
            raise ValidationError("invalid restore item sequence")
        with self.transaction() as db:
            item = db.execute(
                "SELECT * FROM restore_run_items WHERE run_id=? AND sequence=?",
                (run_id, item_sequence),
            ).fetchone()
            if item is None:
                raise CatalogError("restore_item_not_found")
            self._assert_restore_operation_tx(
                db, operation_fence, run_id, int(item["cassette_sequence"])
            )
            authorization = db.execute(
                "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                (authorization_id,),
            ).fetchone()
            if authorization is None:
                raise CatalogError("restore replacement authorization not found")
            if authorization["state"] == "consumed":
                raise CatalogError("restore replacement authorization was consumed")
            conflict = db.execute(
                "SELECT * FROM restore_item_conflicts WHERE id=?",
                (authorization["conflict_id"],),
            ).fetchone()
            binding_names = (
                "run_id",
                "item_sequence",
                "file_version_id",
                "canonical_destination",
                "observed_size",
                "observed_sha256",
            )
            if (
                conflict is None
                or authorization["run_id"] != run_id
                or int(authorization["item_sequence"]) != item_sequence
                or item["state"] != "recovery_required"
                or conflict["state"] != "authorized"
                or conflict["authorization_id"] != authorization_id
                or any(
                    authorization[name] != conflict[name] for name in binding_names
                )
                or int(authorization["file_version_id"])
                != int(item["file_version_id"])
                or authorization["canonical_destination"]
                != item["canonical_destination"]
            ):
                raise CatalogError("restore replacement authorization is stale")
            now = self._precise_utc_now()
            db.execute(
                "UPDATE restore_replacement_authorizations SET state='consumed',"
                "consumed_at=?,consumed_by_operation_id=? WHERE id=? "
                "AND state='authorized'",
                (now, operation_fence.operation_id, authorization_id),
            )
            db.execute(
                "UPDATE restore_item_conflicts SET state='consumed',consumed_at=? "
                "WHERE id=? AND state='authorized'",
                (now, conflict["id"]),
            )
            row = db.execute(
                "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                (authorization_id,),
            ).fetchone()
            assert row is not None
            return self._restore_replacement_authorization_mapping(row)

    def consume_restore_item_replacement_and_begin(
        self,
        operation_fence: OperationFence,
        run_id: str,
        item_sequence: int,
        authorization_id: str,
    ) -> dict[str, Any]:
        """Consume one exact authority and begin only its item atomically."""

        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_safe_identifier(
            authorization_id, "restore replacement authorization id"
        )
        if type(item_sequence) is not int or not 1 <= item_sequence <= 200:
            raise ValidationError("invalid restore item sequence")
        with self.transaction() as db:
            item = db.execute(
                "SELECT * FROM restore_run_items WHERE run_id=? AND sequence=?",
                (run_id, item_sequence),
            ).fetchone()
            if item is None:
                raise CatalogError("restore_item_not_found")
            _operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, int(item["cassette_sequence"])
            )
            authorization = db.execute(
                "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                (authorization_id,),
            ).fetchone()
            conflict = (
                None
                if authorization is None
                else db.execute(
                    "SELECT * FROM restore_item_conflicts WHERE id=?",
                    (authorization["conflict_id"],),
                ).fetchone()
            )
            binding_names = (
                "run_id", "item_sequence", "file_version_id",
                "canonical_destination", "observed_size", "observed_sha256",
            )
            if (
                authorization is None
                or conflict is None
                or authorization["state"] != "authorized"
                or authorization["run_id"] != run_id
                or int(authorization["item_sequence"]) != item_sequence
                or item["state"] != "recovery_required"
                or conflict["state"] != "authorized"
                or conflict["authorization_id"] != authorization_id
                or any(
                    authorization[name] != conflict[name] for name in binding_names
                )
                or int(authorization["file_version_id"])
                != int(item["file_version_id"])
                or authorization["canonical_destination"]
                != item["canonical_destination"]
                or run["state"] not in {"waiting_media", "recovery_required"}
                or cassette["state"] not in {"waiting_media", "recovery_required"}
            ):
                raise CatalogError("restore replacement authorization is stale")
            now = self._precise_utc_now()
            auth_cursor = db.execute(
                "UPDATE restore_replacement_authorizations SET state='consumed',"
                "consumed_at=?,consumed_by_operation_id=? WHERE id=? "
                "AND state='authorized'",
                (now, operation_fence.operation_id, authorization_id),
            )
            conflict_cursor = db.execute(
                "UPDATE restore_item_conflicts SET state='consumed',consumed_at=? "
                "WHERE id=? AND state='authorized'",
                (now, conflict["id"]),
            )
            item_cursor = db.execute(
                "UPDATE restore_run_items SET state='restoring',bytes_copied=0,"
                "observed_sha256=NULL,error_code=NULL,"
                "started_at=COALESCE(started_at,?),completed_at=NULL "
                "WHERE run_id=? AND sequence=? AND state='recovery_required'",
                (now, run_id, item_sequence),
            )
            if (
                auth_cursor.rowcount != 1
                or conflict_cursor.rowcount != 1
                or item_cursor.rowcount != 1
            ):
                raise CatalogError("restore replacement state changed")
            db.execute(
                "UPDATE restore_run_cassettes SET state='restoring',"
                "started_at=COALESCE(started_at,?),last_error_code=NULL "
                "WHERE run_id=? AND sequence=? AND state IN "
                "('waiting_media','recovery_required')",
                (now, run_id, item["cassette_sequence"]),
            )
            db.execute(
                "UPDATE restore_runs SET state='restoring',"
                "started_at=COALESCE(started_at,?),last_error_code=NULL "
                "WHERE id=? AND state IN ('waiting_media','recovery_required')",
                (now, run_id),
            )
            row = db.execute(
                "SELECT * FROM restore_replacement_authorizations WHERE id=?",
                (authorization_id,),
            ).fetchone()
            assert row is not None
            return self._restore_replacement_authorization_mapping(row)

    def authorized_restore_item_replacement(
        self, run_id: str, item_sequence: int
    ) -> dict[str, Any] | None:
        """Return only the exact current server-side replacement authority."""

        self._validate_safe_identifier(run_id, "restore run id")
        if type(item_sequence) is not int or not 1 <= item_sequence <= 200:
            raise ValidationError("invalid restore item sequence")
        row = self.connection.execute(
            "SELECT authorization.* FROM restore_replacement_authorizations authorization "
            "JOIN restore_item_conflicts conflict ON conflict.id=authorization.conflict_id "
            "JOIN restore_run_items item ON item.run_id=authorization.run_id "
            "AND item.sequence=authorization.item_sequence "
            "WHERE authorization.run_id=? AND authorization.item_sequence=? "
            "AND authorization.state='authorized' AND conflict.state='authorized' "
            "AND conflict.authorization_id=authorization.id "
            "AND item.state='recovery_required' "
            "AND authorization.file_version_id=item.file_version_id "
            "AND authorization.canonical_destination=item.canonical_destination "
            "ORDER BY conflict.conflict_sequence DESC LIMIT 1",
            (run_id, item_sequence),
        ).fetchone()
        return (
            None
            if row is None
            else self._restore_replacement_authorization_mapping(row)
        )

    def transition_restore_item(
        self,
        operation_fence: OperationFence,
        run_id: str,
        item_sequence: int,
        *,
        expected_state: str,
        new_state: str,
        bytes_copied: int,
        observed_sha256: str | None,
        error_code: str | None = None,
    ) -> None:
        """Apply one fenced, compare-and-swap item transition."""

        states = {
            "pending",
            "restoring",
            "restored",
            "skipped_verified",
            "failed",
            "recovery_required",
        }
        allowed = {
            "pending": {"restoring", "restored", "skipped_verified", "failed", "recovery_required"},
            "restoring": {"restored", "skipped_verified", "failed", "recovery_required"},
            "recovery_required": {"restoring"},
        }
        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_restore_error_code(error_code)
        if observed_sha256 is not None:
            self._validate_sha256(observed_sha256, "restore observed digest")
        if (
            type(item_sequence) is not int
            or not 1 <= item_sequence <= 200
            or expected_state not in states
            or new_state not in allowed.get(expected_state, set())
            or type(bytes_copied) is not int
            or not 0 <= bytes_copied <= 2**63 - 1
        ):
            raise ValidationError("invalid restore item transition")
        with self.transaction() as db:
            item = db.execute(
                "SELECT * FROM restore_run_items WHERE run_id=? AND sequence=?",
                (run_id, item_sequence),
            ).fetchone()
            if item is None:
                raise CatalogError("restore_item_not_found")
            _operation, run, cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, int(item["cassette_sequence"])
            )
            if (
                run["state"] == "recovery_required"
                or cassette["state"] == "recovery_required"
                or self._restore_has_open_conflicts_tx(db, run_id)
            ):
                raise CatalogError("restore recovery exit is required")
            if bytes_copied > int(item["size"]):
                raise ValidationError("invalid restore item byte count")
            if new_state in {"restored", "skipped_verified"} and (
                bytes_copied != int(item["size"])
                or observed_sha256 != item["sha256"]
                or error_code is not None
            ):
                raise ValidationError("restore item verification is incomplete")
            if new_state == "recovery_required" and error_code is None:
                raise ValidationError("restore recovery reason is required")
            if expected_state == "recovery_required":
                conflict = db.execute(
                    "SELECT * FROM restore_item_conflicts WHERE run_id=? "
                    "AND item_sequence=? ORDER BY conflict_sequence DESC LIMIT 1",
                    (run_id, item_sequence),
                ).fetchone()
                if conflict is not None and conflict["state"] != "consumed":
                    raise CatalogError("restore replacement authorization is required")
            now = self._precise_utc_now()
            completed_at = (
                now if new_state in {"restored", "skipped_verified", "failed"} else None
            )
            cursor = db.execute(
                "UPDATE restore_run_items SET state=?,bytes_copied=?,"
                "observed_sha256=?,error_code=?,started_at=COALESCE(started_at,?),"
                "completed_at=? WHERE run_id=? AND sequence=? AND state=?",
                (
                    new_state,
                    bytes_copied,
                    observed_sha256,
                    error_code,
                    now,
                    completed_at,
                    run_id,
                    item_sequence,
                    expected_state,
                ),
            )
            if cursor.rowcount != 1:
                raise CatalogError("restore item state changed")
            counts = db.execute(
                "SELECT SUM(state='restored'),SUM(state='skipped_verified'),"
                "SUM(state='failed'),SUM(bytes_copied) FROM restore_run_items "
                "WHERE run_id=?",
                (run_id,),
            ).fetchone()
            cassette_counts = db.execute(
                "SELECT SUM(state='restored'),SUM(state='skipped_verified'),"
                "SUM(state='failed'),SUM(bytes_copied) FROM restore_run_items "
                "WHERE run_id=? AND cassette_sequence=?",
                (run_id, item["cassette_sequence"]),
            ).fetchone()
            run_state = "recovery_required" if new_state == "recovery_required" else "restoring"
            cassette_state = run_state
            db.execute(
                "UPDATE restore_runs SET state=?,restored_files=?,skipped_files=?,"
                "failed_files=?,copied_bytes=?,started_at=COALESCE(started_at,?),"
                "last_error_code=? WHERE id=?",
                (
                    run_state,
                    *[int(value or 0) for value in counts],
                    now,
                    error_code,
                    run_id,
                ),
            )
            db.execute(
                "UPDATE restore_run_cassettes SET state=?,restored_files=?,"
                "skipped_files=?,failed_files=?,copied_bytes=?,"
                "started_at=COALESCE(started_at,?),last_error_code=? "
                "WHERE run_id=? AND sequence=?",
                (
                    cassette_state,
                    *[int(value or 0) for value in cassette_counts],
                    now,
                    error_code,
                    run_id,
                    item["cassette_sequence"],
                ),
            )

    def transition_restore_cassette(
        self,
        operation_fence: OperationFence,
        run_id: str,
        cassette_sequence: int,
        *,
        expected_state: str,
        new_state: str,
        error_code: str | None = None,
    ) -> None:
        """Apply one fenced cassette transition and advance deterministic order."""

        allowed = {
            "waiting_media": {"restoring", "failed", "recovery_required"},
            "restoring": {"completed", "failed", "recovery_required"},
            "recovery_required": {"waiting_media", "restoring", "failed"},
        }
        self._validate_safe_identifier(run_id, "restore run id")
        self._validate_restore_error_code(error_code)
        if (
            type(cassette_sequence) is not int
            or not 1 <= cassette_sequence <= 200
            or new_state not in allowed.get(expected_state, set())
        ):
            raise ValidationError("invalid restore cassette transition")
        with self.transaction() as db:
            _operation, run, _cassette = self._assert_restore_operation_tx(
                db, operation_fence, run_id, cassette_sequence
            )
            if run["state"] != expected_state:
                raise CatalogError("restore run state changed")
            if (
                new_state in {"waiting_media", "restoring"}
                and self._restore_has_open_conflicts_tx(db, run_id)
            ):
                raise CatalogError("restore replacement authorization is required")
            if new_state == "completed" and db.execute(
                "SELECT 1 FROM restore_run_items WHERE run_id=? "
                "AND cassette_sequence=? AND state NOT IN ('restored','skipped_verified')",
                (run_id, cassette_sequence),
            ).fetchone() is not None:
                raise CatalogError("restore cassette items are incomplete")
            now = self._precise_utc_now()
            cursor = db.execute(
                "UPDATE restore_run_cassettes SET state=?,last_error_code=?,"
                "completed_at=? WHERE run_id=? AND sequence=? AND state=?",
                (
                    new_state,
                    error_code,
                    now if new_state == "completed" else None,
                    run_id,
                    cassette_sequence,
                    expected_state,
                ),
            )
            if cursor.rowcount != 1:
                raise CatalogError("restore cassette state changed")
            if new_state == "completed":
                following = db.execute(
                    "SELECT sequence FROM restore_run_cassettes WHERE run_id=? "
                    "AND sequence>? AND state='pending' ORDER BY sequence LIMIT 1",
                    (run_id, cassette_sequence),
                ).fetchone()
                if following is None:
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='completed',"
                        "current_cassette_sequence=NULL,completed_at=?,"
                        "last_error_code=NULL WHERE id=? AND state=?",
                        (now, run_id, expected_state),
                    )
                else:
                    db.execute(
                        "UPDATE restore_run_cassettes SET state='waiting_media' "
                        "WHERE run_id=? AND sequence=? AND state='pending'",
                        (run_id, following["sequence"]),
                    )
                    run_cursor = db.execute(
                        "UPDATE restore_runs SET state='waiting_media',"
                        "current_cassette_sequence=?,last_error_code=NULL "
                        "WHERE id=? AND state=?",
                        (following["sequence"], run_id, expected_state),
                    )
            elif new_state in {"failed", "recovery_required"}:
                run_cursor = db.execute(
                    "UPDATE restore_runs SET state=?,last_error_code=?,"
                    "completed_at=? WHERE id=? AND state=?",
                    (
                        new_state,
                        error_code,
                        now if new_state == "failed" else None,
                        run_id,
                        expected_state,
                    ),
                )
            else:
                run_cursor = db.execute(
                    "UPDATE restore_runs SET state=?,"
                    "started_at=COALESCE(started_at,?),last_error_code=NULL "
                    "WHERE id=? AND state=?",
                    (new_state, now, run_id, expected_state),
                )
            if run_cursor.rowcount != 1:
                raise CatalogError("restore run state changed")

    def block_file_versions(self, block_id: str) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT * FROM file_versions WHERE block_id=? ORDER BY id", (block_id,)
            )
        )

    def search_files(
        self,
        query: str,
        library_id: str | None = None,
        include_history: bool = False,
        limit: int = 500,
    ) -> list[sqlite3.Row]:
        if not 1 <= limit <= 5000:
            raise ValidationError(
                "Il limite della ricerca deve essere compreso tra 1 e 5000"
            )
        params: list[Any] = [query.strip()]
        clauses = ["instr(lower(fv.relative_path), lower(?)) > 0"]
        if library_id:
            clauses.append("fv.library_id=?")
            params.append(library_id)

        if include_history:
            current_expression = """
                CASE WHEN fv.id = (
                    SELECT MAX(current.id)
                    FROM file_versions current
                    JOIN blocks current_block ON current_block.id=current.block_id
                    WHERE current.library_id=fv.library_id
                      AND current.relative_path=fv.relative_path
                      AND current.visible=1
                      AND current_block.visible=1
                      AND current_block.status='completed'
                ) THEN 1 ELSE 0 END
            """
            join_latest = ""
        else:
            current_expression = "1"
            join_latest = """
                JOIN (
                    SELECT candidate.library_id, candidate.relative_path,
                           MAX(candidate.id) AS max_id
                    FROM file_versions candidate
                    JOIN blocks candidate_block ON candidate_block.id=candidate.block_id
                    WHERE candidate.visible=1
                      AND candidate_block.visible=1
                      AND candidate_block.status='completed'
                    GROUP BY candidate.library_id, candidate.relative_path
                ) latest ON latest.max_id=fv.id
            """

        clauses.extend(("fv.visible=1", "b.visible=1", "b.status='completed'"))

        sql = f"""
            SELECT
                fv.id,
                fv.library_id,
                l.name AS library_name,
                fv.relative_path,
                fv.parent_path,
                fv.file_name,
                fv.tape_relative_path,
                fv.size,
                fv.mtime_ns,
                fv.created_ns,
                fv.accessed_ns,
                fv.source_mode,
                fv.windows_attributes,
                fv.owner_name,
                fv.owner_sid,
                fv.security_descriptor,
                fv.alternate_streams_json,
                fv.metadata_state,
                fv.metadata_error,
                fv.sha256,
                fv.copied_at,
                fv.visible,
                fv.block_id,
                b.status AS block_status,
                fv.tape_id,
                t.cassette_number,
                t.volume_label,
                t.volume_serial,
                ({current_expression}) AS is_current
            FROM file_versions fv
            {join_latest}
            JOIN libraries l ON l.id=fv.library_id
            JOIN blocks b ON b.id=fv.block_id
            JOIN tapes t ON t.id=fv.tape_id
            WHERE {" AND ".join(clauses)}
            ORDER BY is_current DESC, fv.copied_at DESC, fv.id DESC
            LIMIT ?
        """
        params.append(limit)
        return list(self.connection.execute(sql, params))

    @staticmethod
    def _catalog_query_timestamp(value: object, name: str) -> str | None:
        if value is None:
            return None
        if isinstance(value, datetime):
            if value.tzinfo is None or value.utcoffset() != timedelta(0):
                raise ValidationError(f"invalid {name}")
            return value.isoformat()
        parsed = Catalog._parse_utc_timestamp(value)
        if parsed is None:
            raise ValidationError(f"invalid {name}")
        return parsed.isoformat()

    @staticmethod
    def _catalog_search_cursor(copied_at: object, version_id: object) -> str:
        if (
            not isinstance(copied_at, str)
            or Catalog._parse_utc_timestamp(copied_at) is None
        ):
            raise ValidationError("invalid catalog cursor")
        if (
            isinstance(version_id, bool)
            or not isinstance(version_id, int)
            or version_id < 1
        ):
            raise ValidationError("invalid catalog cursor")
        encoded = json.dumps(
            {"copied_at": copied_at, "id": version_id},
            ensure_ascii=True,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("ascii")
        return base64.urlsafe_b64encode(encoded).decode("ascii").rstrip("=")

    @staticmethod
    def _parse_catalog_search_cursor(cursor: object) -> tuple[str, int] | None:
        if cursor is None:
            return None
        if not isinstance(cursor, str) or not cursor or len(cursor) > 512:
            raise ValidationError("invalid catalog cursor")
        try:
            padding = "=" * (-len(cursor) % 4)
            decoded = base64.b64decode(
                cursor + padding, altchars=b"-_", validate=True
            ).decode("ascii")
            value = json.loads(decoded)
        except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
            raise ValidationError("invalid catalog cursor") from None
        if not isinstance(value, dict) or set(value) != {"copied_at", "id"}:
            raise ValidationError("invalid catalog cursor")
        copied_at = value["copied_at"]
        version_id = value["id"]
        if (
            not isinstance(copied_at, str)
            or Catalog._parse_utc_timestamp(copied_at) is None
        ):
            raise ValidationError("invalid catalog cursor")
        if (
            isinstance(version_id, bool)
            or not isinstance(version_id, int)
            or version_id < 1
        ):
            raise ValidationError("invalid catalog cursor")
        return copied_at, version_id

    @staticmethod
    def _catalog_file_version_item(row: sqlite3.Row) -> dict[str, Any]:
        item = dict(row)
        item["is_current"] = bool(item["is_current"])
        try:
            item["alternate_streams"] = json.loads(
                item["alternate_streams_json"] or "[]"
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            item["alternate_streams"] = []
        return item

    def _catalog_file_versions_sql(self, clauses: Sequence[str]) -> str:
        return f"""
            SELECT
                fv.*,
                l.name AS library_name,
                b.status AS block_status,
                b.visible AS block_visible,
                t.cassette_number,
                t.volume_label,
                t.volume_serial,
                cassette.physical_label AS physical_label,
                cassette.job_id AS job_id,
                job.display_name AS job_display_name,
                CASE WHEN fv.id = (
                    SELECT MAX(current.id)
                    FROM file_versions current
                    JOIN blocks current_block ON current_block.id=current.block_id
                    WHERE current.library_id=fv.library_id
                      AND current.relative_path=fv.relative_path
                      AND current.visible=1
                      AND current_block.visible=1
                      AND current_block.status='completed'
                ) THEN 1 ELSE 0 END AS is_current
            FROM file_versions fv
            JOIN libraries l ON l.id=fv.library_id
            JOIN blocks b ON b.id=fv.block_id
            JOIN tapes t ON t.id=fv.tape_id
            LEFT JOIN automatic_cassettes cassette
                ON instr(',' || cassette.block_id || ',', ',' || fv.block_id || ',') > 0
            LEFT JOIN automatic_jobs job ON job.id=cassette.job_id
            WHERE fv.visible=1
              AND b.visible=1
              AND b.status='completed'
              AND {" AND ".join(clauses)}
        """

    def search_file_versions(
        self,
        *,
        query: str = "",
        library_id: str | None = None,
        job_id: str | None = None,
        cassette: str | None = None,
        sha256: str | None = None,
        min_size: int | None = None,
        max_size: int | None = None,
        copied_after: str | datetime | None = None,
        copied_before: str | datetime | None = None,
        include_history: bool = False,
        limit: int = 50,
        cursor: str | None = None,
    ) -> dict[str, Any]:
        """Search visible completed catalog entries without touching tape hardware."""
        if not isinstance(query, str) or len(query) > 256:
            raise ValidationError("invalid catalog query")
        if (
            not isinstance(limit, int)
            or isinstance(limit, bool)
            or not 1 <= limit <= 200
        ):
            raise ValidationError(
                "Il limite della ricerca deve essere compreso tra 1 e 200"
            )
        for name, value in (
            ("library_id", library_id),
            ("job_id", job_id),
            ("cassette", cassette),
        ):
            if value is not None and (
                not isinstance(value, str) or not value or len(value) > 128
            ):
                raise ValidationError(f"invalid {name}")
        if sha256 is not None:
            if not isinstance(sha256, str) or not re.fullmatch(
                r"[0-9A-Fa-f]{64}", sha256
            ):
                raise ValidationError("invalid sha256")
            sha256 = sha256.lower()
        for name, value in (("min_size", min_size), ("max_size", max_size)):
            if value is not None and (
                isinstance(value, bool)
                or not isinstance(value, int)
                or not 0 <= value <= 2**63 - 1
            ):
                raise ValidationError(f"invalid {name}")
        if min_size is not None and max_size is not None and min_size > max_size:
            raise ValidationError("invalid size range")
        after = self._catalog_query_timestamp(copied_after, "copied_after")
        before = self._catalog_query_timestamp(copied_before, "copied_before")
        if after is not None and before is not None and after > before:
            raise ValidationError("invalid copied_at range")
        parsed_cursor = self._parse_catalog_search_cursor(cursor)

        clauses = ["instr(lower(fv.relative_path), lower(?)) > 0"]
        params: list[Any] = [query.strip()]
        if not include_history:
            clauses.append(
                "fv.id = (SELECT MAX(current.id) FROM file_versions current "
                "JOIN blocks current_block ON current_block.id=current.block_id "
                "WHERE current.library_id=fv.library_id "
                "AND current.relative_path=fv.relative_path "
                "AND current.visible=1 AND current_block.visible=1 "
                "AND current_block.status='completed')"
            )
        if library_id is not None:
            clauses.append("fv.library_id=?")
            params.append(library_id)
        if job_id is not None:
            clauses.append("cassette.job_id=?")
            params.append(job_id)
        if cassette is not None:
            clauses.append(
                "(instr(lower(t.cassette_number), lower(?)) > 0 "
                "OR instr(lower(cassette.physical_label), lower(?)) > 0 "
                "OR instr(lower(t.volume_label), lower(?)) > 0 "
                "OR instr(lower(t.volume_serial), lower(?)) > 0)"
            )
            params.extend((cassette, cassette, cassette, cassette))
        if sha256 is not None:
            clauses.append("fv.sha256=?")
            params.append(sha256)
        if min_size is not None:
            clauses.append("fv.size>=?")
            params.append(min_size)
        if max_size is not None:
            clauses.append("fv.size<=?")
            params.append(max_size)
        if after is not None:
            clauses.append("fv.copied_at>=?")
            params.append(after)
        if before is not None:
            clauses.append("fv.copied_at<=?")
            params.append(before)
        if parsed_cursor is not None:
            cursor_copied_at, cursor_id = parsed_cursor
            clauses.append("(fv.copied_at<? OR (fv.copied_at=? AND fv.id<?))")
            params.extend((cursor_copied_at, cursor_copied_at, cursor_id))

        rows = list(
            self.connection.execute(
                self._catalog_file_versions_sql(clauses)
                + " ORDER BY fv.copied_at DESC, fv.id DESC LIMIT ?",
                (*params, limit + 1),
            )
        )
        has_more = len(rows) > limit
        items = [self._catalog_file_version_item(row) for row in rows[:limit]]
        return {
            "items": items,
            "next_cursor": (
                self._catalog_search_cursor(items[-1]["copied_at"], items[-1]["id"])
                if has_more
                else None
            ),
        }

    def get_file_version(self, version_id: int) -> dict[str, Any]:
        if (
            isinstance(version_id, bool)
            or not isinstance(version_id, int)
            or version_id < 1
        ):
            raise ValidationError("invalid version_id")
        row = self.connection.execute(
            self._catalog_file_versions_sql(("fv.id=?",)), (version_id,)
        ).fetchone()
        if row is None:
            raise CatalogError(f"Versione file non trovata: {version_id}")
        return self._catalog_file_version_item(row)

    def create_ltfs_qualification_run(self, plan: QualificationPlan) -> None:
        if type(plan) is not QualificationPlan:
            raise ValidationError("invalid LTFS qualification plan")
        plan_bytes = plan.canonical_bytes()
        plan_json = plan_bytes.decode("utf-8")
        try:
            with self.transaction() as db:
                cassette = db.execute(
                    "SELECT physical_label,tape_serial FROM automatic_cassettes "
                    "WHERE job_id=? AND sequence=?",
                    (plan.job_id, plan.cassette_sequence),
                ).fetchone()
                if cassette is None:
                    raise ValidationError(
                        "LTFS qualification catalog identity is missing"
                    )
                if (
                    cassette["physical_label"] != plan.physical_label
                    or cassette["tape_serial"] != plan.tape_serial
                ):
                    raise ValidationError(
                        "LTFS qualification catalog identity mismatch"
                    )
                db.execute(
                    """
                    INSERT INTO ltfs_qualification_runs(
                        run_id,plan_sha256,plan_json,job_id,cassette_sequence,
                        physical_label,tape_serial,drive_serial,drive_wwid,
                        linux_tree_sha256,ltfs_tree_sha256,ltfs_rpm_sha256,
                        status,created_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'planned',?)
                    """,
                    (
                        plan.run_id,
                        plan.plan_sha256,
                        plan_json,
                        plan.job_id,
                        plan.cassette_sequence,
                        plan.physical_label,
                        plan.tape_serial,
                        plan.drive_serial,
                        plan.drive_wwid,
                        plan.linux_tree_sha256,
                        plan.ltfs_tree_sha256,
                        plan.ltfs_rpm_sha256,
                        utc_now(),
                    ),
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError("LTFS qualification run already exists") from exc

    def record_ltfs_qualification_stage(
        self,
        *,
        run_id: str,
        ordinal: int,
        operation: QualificationOperation,
        request_sha256: str,
        dispatched: bool,
        terminal_receipt_sha256: str | None,
        child_exit_code: int | None,
        before_volume_uuid: str | None,
        before_generation: int | None,
        after_volume_uuid: str | None,
        after_generation: int | None,
        content_manifest_sha256: str | None,
        verdict: str,
    ) -> None:
        self._validate_qualification_run_id(run_id)
        if type(ordinal) is not int or ordinal < 1:
            raise ValidationError("invalid LTFS qualification stage ordinal")
        if type(operation) is not QualificationOperation:
            raise ValidationError("invalid LTFS qualification operation")
        self._validate_sha256(request_sha256, "qualification request digest")
        if type(dispatched) is not bool:
            raise ValidationError("invalid LTFS qualification dispatch state")
        if terminal_receipt_sha256 is not None:
            self._validate_sha256(
                terminal_receipt_sha256, "qualification terminal receipt digest"
            )
        if child_exit_code is not None and type(child_exit_code) is not int:
            raise ValidationError("invalid LTFS qualification child exit code")
        self._validate_qualification_media_state(
            before_volume_uuid, before_generation, "before"
        )
        self._validate_qualification_media_state(
            after_volume_uuid, after_generation, "after"
        )
        if content_manifest_sha256 is not None:
            self._validate_sha256(
                content_manifest_sha256, "qualification content manifest digest"
            )
        if (
            type(verdict) is not str
            or not verdict
            or len(verdict.encode("utf-8")) > 128
            or any(
                ord(character) < 32 or ord(character) == 127 for character in verdict
            )
        ):
            raise ValidationError("invalid LTFS qualification verdict")
        if not dispatched and any(
            value is not None
            for value in (
                terminal_receipt_sha256,
                child_exit_code,
                after_volume_uuid,
                after_generation,
            )
        ):
            raise ValidationError(
                "undispatched qualification stage has terminal evidence"
            )
        if (terminal_receipt_sha256 is None) != (child_exit_code is None):
            raise ValidationError("qualification terminal evidence is incomplete")
        accepted_exit_codes = qualification_success_exit_codes(operation)
        if verdict == "pass" and (
            not dispatched
            or terminal_receipt_sha256 is None
            or child_exit_code not in accepted_exit_codes
        ):
            raise ValidationError("passing qualification stage lacks terminal proof")
        try:
            with self.transaction() as db:
                run = db.execute(
                    "SELECT * FROM ltfs_qualification_runs WHERE run_id=?", (run_id,)
                ).fetchone()
                if run is None:
                    raise CatalogError("LTFS qualification run not found")
                if run["status"] in {"fenced", "completed"}:
                    raise CatalogError("LTFS qualification run is terminal")
                plan = QualificationPlan.from_bytes(run["plan_json"].encode("utf-8"))
                if (
                    plan.canonical_bytes().decode("utf-8") != run["plan_json"]
                    or plan.plan_sha256 != run["plan_sha256"]
                    or operation not in plan.operations
                ):
                    raise ValidationError("LTFS qualification plan evidence is invalid")
                next_ordinal = db.execute(
                    "SELECT COALESCE(MAX(ordinal),0)+1 FROM ltfs_qualification_stages "
                    "WHERE run_id=?",
                    (run_id,),
                ).fetchone()[0]
                if ordinal != next_ordinal:
                    raise ValidationError("LTFS qualification stage order is invalid")
                db.execute(
                    """
                    INSERT INTO ltfs_qualification_stages(
                        run_id,ordinal,operation,request_sha256,dispatched,
                        terminal_receipt_sha256,child_exit_code,
                        before_volume_uuid,before_generation,
                        after_volume_uuid,after_generation,
                        content_manifest_sha256,verdict,recorded_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        run_id,
                        ordinal,
                        operation.value,
                        request_sha256,
                        int(dispatched),
                        terminal_receipt_sha256,
                        child_exit_code,
                        before_volume_uuid,
                        before_generation,
                        after_volume_uuid,
                        after_generation,
                        content_manifest_sha256,
                        verdict,
                        utc_now(),
                    ),
                )
                if dispatched:
                    db.execute(
                        "UPDATE ltfs_qualification_runs SET status='running' "
                        "WHERE run_id=? AND status='planned'",
                        (run_id,),
                    )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(
                "LTFS qualification stage conflicts with durable evidence"
            ) from exc

    def reconcile_ltfs_qualification_stage(
        self,
        *,
        plan: QualificationPlan,
        inspection_request: BrokerQualificationInspectionRequest,
        inspection: BrokerQualificationInspection,
        physical_label: str,
        tape_serial: str,
        drive_serial: str,
        drive_wwid: str,
        tape_device_identity_sha256: str,
        scsi_device_identity_sha256: str,
        expected_media_scope_sha256: str,
        observed_media_identity_sha256: str,
        volume_uuid: str | None,
        generation: int | None,
    ) -> None:
        """Import one already-terminal broker stage without redispatching it."""

        if type(plan) is not QualificationPlan:
            raise ValidationError("invalid LTFS qualification plan")
        if type(inspection_request) is not BrokerQualificationInspectionRequest:
            raise ValidationError("invalid LTFS qualification inspection request")
        if type(inspection) is not BrokerQualificationInspection:
            raise ValidationError("invalid LTFS qualification inspection")
        for value, purpose in (
            (physical_label, "physical label"),
            (tape_serial, "tape serial"),
            (drive_serial, "drive serial"),
            (drive_wwid, "drive WWID"),
        ):
            self._validate_qualification_text(value, purpose)
        for value, purpose in (
            (tape_device_identity_sha256, "tape device identity digest"),
            (scsi_device_identity_sha256, "SCSI device identity digest"),
            (expected_media_scope_sha256, "expected media scope digest"),
            (observed_media_identity_sha256, "observed media identity digest"),
        ):
            self._validate_sha256(value, f"qualification {purpose}")
        self._validate_qualification_media_state(volume_uuid, generation, "post")
        if generation is not None and generation >= 1 << 64:
            raise ValidationError("invalid LTFS qualification post generation")

        if inspection.state != "terminal" or inspection.dispatch is None:
            raise ValidationError("LTFS qualification inspection is not terminal")
        snapshot = inspection.stage_snapshot
        dispatch = inspection.dispatch
        if snapshot is None:
            raise ValidationError("LTFS qualification inspection snapshot is missing")
        snapshot_payload = qualification_inspection_snapshot_payload(snapshot)
        proof_payload = qualification_inspection_proof_payload(
            inspection_request, inspection
        )
        canonical_inspection_proof = (
            _QUALIFICATION_INSPECTION_PROOF_DOMAIN
            + len(proof_payload).to_bytes(4, "big")
            + proof_payload
            + inspection.proof
        )
        snapshot_sha256 = hashlib.sha256(snapshot_payload).hexdigest()
        proof_sha256 = hashlib.sha256(canonical_inspection_proof).hexdigest()
        post_media_payload = json.dumps(
            {
                "drive_serial": drive_serial,
                "drive_wwid": drive_wwid,
                "expected_media_scope_sha256": expected_media_scope_sha256,
                "generation": generation,
                "observed_media_identity_sha256": observed_media_identity_sha256,
                "physical_label": physical_label,
                "scsi_device_identity_sha256": scsi_device_identity_sha256,
                "tape_device_identity_sha256": tape_device_identity_sha256,
                "tape_serial": tape_serial,
                "volume_uuid": volume_uuid,
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
        post_media_sha256 = hashlib.sha256(post_media_payload).hexdigest()

        try:
            with self.transaction() as db:
                run = db.execute(
                    "SELECT * FROM ltfs_qualification_runs WHERE run_id=?",
                    (plan.run_id,),
                ).fetchone()
                if run is None:
                    raise CatalogError("LTFS qualification run not found")
                if (
                    plan.canonical_bytes().decode("utf-8") != run["plan_json"]
                    or plan.plan_sha256 != run["plan_sha256"]
                    or plan.run_id != inspection_request.run_id
                    or plan.run_id != snapshot["run_id"]
                    or plan.run_id != dispatch.run_id
                    or inspection_request.stage_ordinal != snapshot["stage_ordinal"]
                    or inspection_request.stage_ordinal != dispatch.stage_ordinal
                    or snapshot["plan_sha256"] != plan.plan_sha256
                ):
                    raise ValidationError(
                        "LTFS qualification plan identity does not match"
                    )
                replay = db.execute(
                    "SELECT * FROM ltfs_qualification_reconciliations "
                    "WHERE run_id=? AND broker_stage_ordinal=?",
                    (plan.run_id, inspection_request.stage_ordinal),
                ).fetchone()
                if replay is not None:
                    self._validate_ltfs_qualification_reconciliation_replay(
                        db,
                        replay,
                        request_sha256=dispatch.request_sha256,
                        inspection_snapshot=snapshot_payload,
                        inspection_snapshot_sha256=snapshot_sha256,
                        inspection_proof=canonical_inspection_proof,
                        inspection_proof_sha256=proof_sha256,
                        terminal_receipt_sha256=dispatch.terminal_receipt_sha256,
                        terminal_exit_code=dispatch.child_exit_code,
                        evidence_sha256=dispatch.evidence_sha256,
                        post_media_evidence=post_media_payload,
                        post_media_evidence_sha256=post_media_sha256,
                    )
                    return
                if run["status"] != "fenced":
                    raise CatalogError("LTFS qualification run is not fenced")
                if (
                    type(run["fence_reason"]) is not str
                    or not run["fence_reason"]
                    or len(run["fence_reason"].encode("utf-8")) > 128
                    or self._parse_utc_timestamp(run["fenced_at"]) is None
                ):
                    raise CatalogError("LTFS qualification fence evidence is invalid")
                dispatch_row, completed_operations = (
                    self._require_single_unpaired_ltfs_qualification_dispatch_tx(
                        db, plan
                    )
                )
                try:
                    operation = QualificationOperation(dispatch_row["operation"])
                except ValueError:
                    raise CatalogError(
                        "LTFS qualification dispatch operation is invalid"
                    ) from None
                expected_broker_ordinal = (
                    _QUALIFICATION_EXECUTION_ORDER.index(operation) + 1
                )
                if (
                    operation not in plan.operations
                    or inspection_request.stage_ordinal != expected_broker_ordinal
                    or snapshot["stage_ordinal"] != expected_broker_ordinal
                    or dispatch.stage_ordinal != expected_broker_ordinal
                    or snapshot["operation"] != operation.value
                    or dispatch.operation is not operation
                    or dispatch_row["request_sha256"] != dispatch.request_sha256
                    or snapshot["request_sha256"] != dispatch.request_sha256
                    or dispatch.dispatch_state != "terminal"
                    or dispatch.child_exit_code
                    not in qualification_success_exit_codes(operation)
                    or dispatch.terminal_receipt_sha256 is None
                ):
                    raise ValidationError(
                        "LTFS qualification terminal evidence does not match dispatch"
                    )
                if (
                    snapshot["expected_physical_label"] != run["physical_label"]
                    or snapshot["expected_tape_serial"] != run["tape_serial"]
                    or snapshot["expected_drive_serial"] != run["drive_serial"]
                    or snapshot["expected_drive_wwid"] != run["drive_wwid"]
                    or snapshot["expected_volume_uuid"]
                    != dispatch_row["before_volume_uuid"]
                    or snapshot["expected_generation"]
                    != dispatch_row["before_generation"]
                    or physical_label != run["physical_label"]
                    or tape_serial != run["tape_serial"]
                    or drive_serial != run["drive_serial"]
                    or drive_wwid != run["drive_wwid"]
                    or tape_device_identity_sha256
                    != snapshot["tape_device_identity_sha256"]
                    or scsi_device_identity_sha256
                    != snapshot["scsi_device_identity_sha256"]
                    or (
                        operation is not QualificationOperation.FORMAT
                        and expected_media_scope_sha256
                        != snapshot["expected_media_scope_sha256"]
                    )
                ):
                    raise ValidationError(
                        "LTFS qualification physical evidence does not match"
                    )
                self._validate_ltfs_qualification_reconciliation_media(
                    operation,
                    dispatch_row["before_volume_uuid"],
                    dispatch_row["before_generation"],
                    volume_uuid,
                    generation,
                    snapshot_observed_media_identity_sha256=snapshot[
                        "observed_media_identity_sha256"
                    ],
                    observed_media_identity_sha256=observed_media_identity_sha256,
                )
                terminal_ordinal = dispatch_row["ordinal"] + 1
                content_manifest_sha256 = (
                    dispatch.evidence_sha256
                    if operation in _QUALIFICATION_CONTENT_OPERATIONS
                    else None
                )
                reconciled_at = utc_now()
                self._insert_ltfs_qualification_terminal_tx(
                    db,
                    run_id=plan.run_id,
                    ordinal=terminal_ordinal,
                    operation=operation,
                    request_sha256=dispatch.request_sha256,
                    terminal_receipt_sha256=dispatch.terminal_receipt_sha256,
                    child_exit_code=dispatch.child_exit_code,
                    before_volume_uuid=dispatch_row["before_volume_uuid"],
                    before_generation=dispatch_row["before_generation"],
                    after_volume_uuid=volume_uuid,
                    after_generation=generation,
                    content_manifest_sha256=content_manifest_sha256,
                    recorded_at=reconciled_at,
                )
                self._insert_ltfs_qualification_reconciliation_tx(
                    db,
                    run_id=plan.run_id,
                    catalog_stage_ordinal=terminal_ordinal,
                    broker_stage_ordinal=expected_broker_ordinal,
                    request_sha256=dispatch.request_sha256,
                    inspection_snapshot=snapshot_payload,
                    inspection_snapshot_sha256=snapshot_sha256,
                    inspection_proof=canonical_inspection_proof,
                    inspection_proof_sha256=proof_sha256,
                    terminal_receipt_sha256=dispatch.terminal_receipt_sha256,
                    terminal_exit_code=dispatch.child_exit_code,
                    evidence_sha256=dispatch.evidence_sha256,
                    previous_fence_reason=run["fence_reason"],
                    previous_fenced_at=run["fenced_at"],
                    post_media_evidence=post_media_payload,
                    post_media_evidence_sha256=post_media_sha256,
                    reconciled_at=reconciled_at,
                )
                completed_operations.add(operation)
                status = (
                    "completed"
                    if completed_operations == set(plan.operations)
                    else "running"
                )
                cursor = db.execute(
                    "UPDATE ltfs_qualification_runs "
                    "SET status=?,fence_reason=NULL,fenced_at=NULL "
                    "WHERE run_id=? AND status='fenced'",
                    (status, plan.run_id),
                )
                if cursor.rowcount != 1:
                    raise CatalogError(
                        "LTFS qualification run reconciliation lost its fence"
                    )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(
                "LTFS qualification reconciliation conflicts with durable evidence"
            ) from exc

    @staticmethod
    def _insert_ltfs_qualification_terminal_tx(
        db: sqlite3.Connection,
        *,
        run_id: str,
        ordinal: int,
        operation: QualificationOperation,
        request_sha256: str,
        terminal_receipt_sha256: str,
        child_exit_code: int,
        before_volume_uuid: str | None,
        before_generation: int | None,
        after_volume_uuid: str | None,
        after_generation: int | None,
        content_manifest_sha256: str | None,
        recorded_at: str,
    ) -> None:
        db.execute(
            """
            INSERT INTO ltfs_qualification_stages(
                run_id,ordinal,operation,request_sha256,dispatched,
                terminal_receipt_sha256,child_exit_code,
                before_volume_uuid,before_generation,
                after_volume_uuid,after_generation,
                content_manifest_sha256,verdict,recorded_at
            ) VALUES(?,?,?,?,1,?,?,?,?,?,?,?,'pass',?)
            """,
            (
                run_id,
                ordinal,
                operation.value,
                request_sha256,
                terminal_receipt_sha256,
                child_exit_code,
                before_volume_uuid,
                before_generation,
                after_volume_uuid,
                after_generation,
                content_manifest_sha256,
                recorded_at,
            ),
        )

    @staticmethod
    def _insert_ltfs_qualification_reconciliation_tx(
        db: sqlite3.Connection, **values: object
    ) -> None:
        columns = ",".join(values)
        placeholders = ",".join("?" for _ in values)
        db.execute(
            f"INSERT INTO ltfs_qualification_reconciliations({columns}) "
            f"VALUES({placeholders})",
            tuple(values.values()),
        )

    @staticmethod
    def _validate_ltfs_qualification_reconciliation_replay(
        db: sqlite3.Connection,
        replay: sqlite3.Row,
        **expected: object,
    ) -> None:
        if any(replay[key] != value for key, value in expected.items()):
            raise CatalogError("LTFS qualification reconciliation replay diverges")
        terminal = db.execute(
            "SELECT * FROM ltfs_qualification_stages WHERE run_id=? AND ordinal=?",
            (replay["run_id"], replay["catalog_stage_ordinal"]),
        ).fetchone()
        if (
            terminal is None
            or terminal["request_sha256"] != replay["request_sha256"]
            or terminal["terminal_receipt_sha256"] != replay["terminal_receipt_sha256"]
            or terminal["child_exit_code"] != replay["terminal_exit_code"]
            or terminal["verdict"] != "pass"
        ):
            raise CatalogError("LTFS qualification reconciliation replay is invalid")

    @staticmethod
    def _require_single_unpaired_ltfs_qualification_dispatch_tx(
        db: sqlite3.Connection, plan: QualificationPlan
    ) -> tuple[sqlite3.Row, set[QualificationOperation]]:
        rows = db.execute(
            "SELECT * FROM ltfs_qualification_stages WHERE run_id=? ORDER BY ordinal",
            (plan.run_id,),
        ).fetchall()
        if not rows or len(rows) % 2 != 1:
            raise CatalogError("LTFS qualification run has no single unpaired dispatch")
        planned = [
            operation
            for operation in _QUALIFICATION_EXECUTION_ORDER
            if operation in plan.operations
        ]
        completed: set[QualificationOperation] = set()
        for index, (dispatch, terminal) in enumerate(
            zip(rows[:-1:2], rows[1:-1:2], strict=True)
        ):
            operation = planned[index] if index < len(planned) else None
            if (
                operation is None
                or dispatch["ordinal"] != 2 * index + 1
                or terminal["ordinal"] != dispatch["ordinal"] + 1
                or dispatch["operation"] != operation.value
                or terminal["operation"] != operation.value
                or dispatch["request_sha256"] != terminal["request_sha256"]
                or dispatch["dispatched"] != 1
                or dispatch["verdict"] != "dispatch_started"
                or dispatch["terminal_receipt_sha256"] is not None
                or dispatch["child_exit_code"] is not None
                or terminal["dispatched"] != 1
                or terminal["verdict"] != "pass"
                or terminal["terminal_receipt_sha256"] is None
                or terminal["child_exit_code"]
                not in qualification_success_exit_codes(operation)
            ):
                raise CatalogError("LTFS qualification paired evidence is invalid")
            completed.add(operation)
        dispatch = rows[-1]
        next_index = len(completed)
        if (
            next_index >= len(planned)
            or dispatch["ordinal"] != 2 * next_index + 1
            or dispatch["operation"] != planned[next_index].value
            or dispatch["dispatched"] != 1
            or dispatch["verdict"] != "dispatch_started"
            or dispatch["terminal_receipt_sha256"] is not None
            or dispatch["child_exit_code"] is not None
        ):
            raise CatalogError("LTFS qualification unpaired dispatch is invalid")
        return dispatch, completed

    @staticmethod
    def _validate_ltfs_qualification_reconciliation_media(
        operation: QualificationOperation,
        before_volume_uuid: str | None,
        before_generation: int | None,
        after_volume_uuid: str | None,
        after_generation: int | None,
        *,
        snapshot_observed_media_identity_sha256: str,
        observed_media_identity_sha256: str,
    ) -> None:
        if operation is QualificationOperation.FORMAT:
            valid = (
                after_volume_uuid is not None
                and after_generation is not None
                and after_generation > 0
                and (
                    before_volume_uuid is None
                    or after_volume_uuid != before_volume_uuid
                )
            )
        elif operation in {
            QualificationOperation.READ_ONLY,
            QualificationOperation.LOAD,
        }:
            valid = (
                (after_volume_uuid, after_generation)
                == (before_volume_uuid, before_generation)
                and observed_media_identity_sha256
                == snapshot_observed_media_identity_sha256
            )
        elif operation in {
            QualificationOperation.ADDITIVE_WRITE,
            QualificationOperation.OVERWRITE,
        }:
            valid = (
                before_volume_uuid is not None
                and after_volume_uuid == before_volume_uuid
                and type(before_generation) is int
                and type(after_generation) is int
                and after_generation > before_generation
                and observed_media_identity_sha256
                == snapshot_observed_media_identity_sha256
            )
        elif operation is QualificationOperation.REPAIR:
            valid = (
                before_volume_uuid is not None
                and after_volume_uuid == before_volume_uuid
                and type(before_generation) is int
                and type(after_generation) is int
                and after_generation >= before_generation
                and observed_media_identity_sha256
                == snapshot_observed_media_identity_sha256
            )
        else:
            valid = True
        if not valid:
            raise ValidationError(
                "LTFS qualification post-operation media evidence is invalid"
            )

    @staticmethod
    def _validate_qualification_text(value: object, purpose: str) -> None:
        if (
            type(value) is not str
            or not value
            or len(value.encode("utf-8")) > 255
            or any(ord(character) < 32 or ord(character) == 127 for character in value)
        ):
            raise ValidationError(f"invalid LTFS qualification {purpose}")

    def fence_ltfs_qualification_run(self, run_id: str, reason: str) -> None:
        self._validate_qualification_run_id(run_id)
        if (
            type(reason) is not str
            or not reason
            or len(reason.encode("utf-8")) > 128
            or any(ord(character) < 32 or ord(character) == 127 for character in reason)
        ):
            raise ValidationError("invalid LTFS qualification fence reason")
        with self.transaction() as db:
            cursor = db.execute(
                "UPDATE ltfs_qualification_runs "
                "SET status='fenced',fence_reason=?,fenced_at=? "
                "WHERE run_id=? AND status IN ('planned','running')",
                (reason, utc_now(), run_id),
            )
            if cursor.rowcount != 1:
                raise CatalogError("LTFS qualification run cannot be fenced")

    def complete_ltfs_qualification_run(self, run_id: str) -> None:
        self._validate_qualification_run_id(run_id)
        with self.transaction() as db:
            run = db.execute(
                "SELECT * FROM ltfs_qualification_runs WHERE run_id=?", (run_id,)
            ).fetchone()
            if run is None or run["status"] != "running":
                raise CatalogError("LTFS qualification run cannot be completed")
            plan = QualificationPlan.from_bytes(run["plan_json"].encode("utf-8"))
            rows = db.execute(
                "SELECT * FROM ltfs_qualification_stages WHERE run_id=? "
                "ORDER BY ordinal",
                (run_id,),
            ).fetchall()
            if len(rows) != 2 * len(plan.operations):
                raise CatalogError("LTFS qualification evidence is incomplete")
            completed_operations: set[QualificationOperation] = set()
            for dispatch, terminal in zip(rows[::2], rows[1::2], strict=True):
                try:
                    operation = QualificationOperation(dispatch["operation"])
                except ValueError:
                    raise CatalogError(
                        "LTFS qualification evidence is invalid"
                    ) from None
                accepted_exit_codes = qualification_success_exit_codes(operation)
                if (
                    operation in completed_operations
                    or operation not in plan.operations
                    or dispatch["dispatched"] != 1
                    or dispatch["verdict"] != "dispatch_started"
                    or dispatch["terminal_receipt_sha256"] is not None
                    or dispatch["child_exit_code"] is not None
                    or terminal["operation"] != dispatch["operation"]
                    or terminal["request_sha256"] != dispatch["request_sha256"]
                    or terminal["dispatched"] != 1
                    or terminal["verdict"] != "pass"
                    or terminal["terminal_receipt_sha256"] is None
                    or terminal["child_exit_code"] not in accepted_exit_codes
                ):
                    raise CatalogError("LTFS qualification evidence is invalid")
                completed_operations.add(operation)
            if completed_operations != set(plan.operations):
                raise CatalogError("LTFS qualification evidence is incomplete")
            cursor = db.execute(
                "UPDATE ltfs_qualification_runs SET status='completed' "
                "WHERE run_id=? AND status='running'",
                (run_id,),
            )
            if cursor.rowcount != 1:
                raise CatalogError("LTFS qualification run cannot be completed")

    @staticmethod
    def _validate_qualification_run_id(run_id: object) -> None:
        if type(run_id) is not str:
            raise ValidationError("invalid LTFS qualification run id")
        try:
            parsed = uuid.UUID(run_id)
        except ValueError:
            raise ValidationError("invalid LTFS qualification run id") from None
        if parsed.version != 4 or str(parsed) != run_id:
            raise ValidationError("invalid LTFS qualification run id")

    @staticmethod
    def _validate_qualification_media_state(
        volume_uuid: object, generation: object, purpose: str
    ) -> None:
        if (volume_uuid is None) != (generation is None):
            raise ValidationError(
                f"incomplete LTFS qualification {purpose} media state"
            )
        if volume_uuid is None:
            return
        if type(volume_uuid) is not str:
            raise ValidationError(f"invalid LTFS qualification {purpose} volume UUID")
        try:
            parsed = uuid.UUID(volume_uuid)
        except ValueError:
            raise ValidationError(
                f"invalid LTFS qualification {purpose} volume UUID"
            ) from None
        if str(parsed) != volume_uuid:
            raise ValidationError(f"invalid LTFS qualification {purpose} volume UUID")
        if type(generation) is not int or generation < 0:
            raise ValidationError(f"invalid LTFS qualification {purpose} generation")

    def create_job_plan_draft(
        self,
        *,
        plan_id: str,
        kind: Literal["create", "extend"],
        creator: str,
        created_at: str,
        expires_at: str,
        media_key: str,
        library_ids: tuple[str, ...] | list[str] = (),
        base_job_id: str | None = None,
        base_job_revision: int | None = None,
        base_job_fingerprint_sha256: str | None = None,
    ) -> dict[str, Any]:
        """Persist the observable building state before source planning starts."""

        validate_id(plan_id, "plan ID")
        validate_id(creator, "plan creator")
        if kind not in {"create", "extend"}:
            raise ValidationError("invalid job plan kind")
        if not isinstance(media_key, str):
            raise ValidationError("invalid job plan media key")
        try:
            media_key = require_ltfs_profile(media_key).key
        except ValidationError:
            raise ValidationError("invalid job plan media key") from None
        normalized_library_ids: list[str] = []
        seen: set[str] = set()
        for value in library_ids:
            validate_id(value, "library ID")
            folded = value.casefold()
            if folded in seen:
                raise ValidationError("duplicate job plan library")
            seen.add(folded)
            normalized_library_ids.append(value)
        if not normalized_library_ids:
            raise ValidationError("job plan requires at least one library")
        if base_job_id is not None:
            validate_id(base_job_id, "base job ID")
        if kind == "create" and any(
            value is not None
            for value in (
                base_job_id,
                base_job_revision,
                base_job_fingerprint_sha256,
            )
        ):
            raise ValidationError("create plans cannot name a base job")
        if kind == "extend" and (
            base_job_id is None
            or type(base_job_revision) is not int
            or base_job_revision < 0
            or base_job_fingerprint_sha256 is None
        ):
            raise ValidationError("extend plans require frozen base job evidence")
        if base_job_fingerprint_sha256 is not None:
            self._validate_sha256(base_job_fingerprint_sha256, "base job fingerprint")
        created = self._parse_utc_timestamp(created_at)
        expires = self._parse_utc_timestamp(expires_at)
        if (
            created is None
            or expires is None
            or expires - created != timedelta(hours=24)
        ):
            raise ValidationError("job plan expiry must be exactly 24 hours")
        request = {
            "base_job_fingerprint_sha256": base_job_fingerprint_sha256,
            "base_job_id": base_job_id,
            "base_job_revision": base_job_revision,
            "kind": kind,
            "library_ids": normalized_library_ids,
            "media_key": media_key,
        }
        canonical_json = json.dumps(
            request,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        digest_sha256 = hashlib.sha256(canonical_json.encode("utf-8")).hexdigest()
        try:
            with self.transaction() as db:
                db.execute(
                    """
                    INSERT INTO job_plan_drafts(
                        id,state,kind,creator,created_at,updated_at,expires_at,
                        media_key,requested_library_ids_json,canonical_json,
                        digest_sha256,canonical_json_version,plan_schema_version,
                        planner_version,application_settings_revision,
                        application_settings_fingerprint_sha256,base_job_id,
                        base_job_revision,base_job_fingerprint_sha256
                    ) VALUES(?, 'building', ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 1,
                             'automatic-ltfs-v1', 0, ?, ?, ?, ?)
                    """,
                    (
                        plan_id,
                        kind,
                        creator,
                        created_at,
                        created_at,
                        expires_at,
                        media_key,
                        json.dumps(
                            normalized_library_ids,
                            ensure_ascii=False,
                            separators=(",", ":"),
                        ),
                        canonical_json,
                        digest_sha256,
                        hashlib.sha256(b"lto-current-policy-seam-v1\0").hexdigest(),
                        base_job_id,
                        base_job_revision,
                        base_job_fingerprint_sha256,
                    ),
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(f"job plan already exists: {plan_id}") from exc
        return self.get_job_plan(plan_id)

    def complete_job_plan_draft(
        self, plan_id: str, frozen_plan: Mapping[str, Any]
    ) -> dict[str, Any]:
        """Atomically publish a canonical ready manifest into a building draft."""

        validate_id(plan_id, "plan ID")
        canonical_json = frozen_plan.get("canonical_json")
        digest_sha256 = frozen_plan.get("digest_sha256")
        if not isinstance(canonical_json, str):
            raise ValidationError("invalid canonical job plan")
        try:
            parsed = json.loads(canonical_json)
        except (TypeError, ValueError) as exc:
            raise ValidationError("invalid canonical job plan") from exc
        if (
            json.dumps(
                parsed,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            != canonical_json
        ):
            raise ValidationError("job plan JSON is not canonical")
        self._validate_sha256(digest_sha256, "job plan digest")
        if hashlib.sha256(canonical_json.encode("utf-8")).hexdigest() != digest_sha256:
            raise ValidationError("job plan digest does not match canonical JSON")
        if frozen_plan.get("canonical_json_version") != 1:
            raise ValidationError("unsupported canonical JSON version")
        if frozen_plan.get("plan_schema_version") != 1:
            raise ValidationError("unsupported job plan schema version")
        if frozen_plan.get("planner_version") != "automatic-ltfs-v1":
            raise ValidationError("unsupported job planner version")
        settings_revision = frozen_plan.get("application_settings_revision")
        settings_fingerprint = frozen_plan.get(
            "application_settings_fingerprint_sha256"
        )
        if type(settings_revision) is not int or settings_revision < 0:
            raise ValidationError("invalid application settings revision")
        self._validate_sha256(settings_fingerprint, "application settings fingerprint")

        libraries = list(frozen_plan.get("libraries", ()))
        cassettes = list(frozen_plan.get("cassettes", ()))
        if not libraries or not cassettes:
            raise ValidationError("ready job plan must contain libraries and cassettes")
        normalized_libraries: list[tuple[Any, ...]] = []
        library_ids: set[str] = set()
        for expected_sequence, library in enumerate(libraries, 1):
            if library.get("sequence") != expected_sequence:
                raise ValidationError("job plan library sequence is not contiguous")
            library_id = library.get("library_id")
            source_root = library.get("source_root")
            scan_revision = library.get("scan_revision")
            scan_fingerprint = library.get("scan_fingerprint_sha256")
            self._validate_safe_identifier(library_id, "job plan library ID")
            if (
                not isinstance(source_root, str)
                or not source_root
                or type(scan_revision) is not int
                or scan_revision < 0
            ):
                raise ValidationError("invalid job plan library evidence")
            self._validate_sha256(scan_fingerprint, "library scan fingerprint")
            folded = library_id.casefold()
            if folded in library_ids:
                raise ValidationError("duplicate job plan library")
            library_ids.add(folded)
            normalized_libraries.append(
                (
                    plan_id,
                    expected_sequence,
                    library_id,
                    source_root,
                    scan_revision,
                    scan_fingerprint,
                )
            )

        normalized_cassettes: list[tuple[Any, ...]] = []
        normalized_items: list[tuple[Any, ...]] = []
        seen_items: set[tuple[str, str]] = set()
        for expected_sequence, cassette in enumerate(cassettes, 1):
            if cassette.get("sequence") != expected_sequence:
                raise ValidationError("job plan cassette sequence is not contiguous")
            items = list(cassette.get("items", ()))
            objects = cassette.get("objects")
            payload_bytes = cassette.get("payload_bytes")
            allocation_bytes = cassette.get("allocation_bytes")
            utilization = cassette.get("capacity_utilization")
            operation = cassette.get("operation")
            if (
                type(objects) is not int
                or objects != len(items)
                or type(payload_bytes) is not int
                or payload_bytes < 0
                or type(allocation_bytes) is not int
                or allocation_bytes < payload_bytes
                or type(utilization) not in {int, float}
                or not 0 <= utilization <= 1
                or operation not in {"format", "append", "reserve"}
            ):
                raise ValidationError("invalid job plan cassette allocation")
            item_bytes = 0
            for expected_item_sequence, item in enumerate(items, 1):
                if item.get("item_sequence") != expected_item_sequence:
                    raise ValidationError("job plan item sequence is not contiguous")
                library_id = item.get("library_id")
                relative_path = item.get("relative_path")
                supplied_tape_relative_path = "tape_relative_path" in item
                tape_relative_path = item.get("tape_relative_path")
                if tape_relative_path is None:
                    # Plans frozen before schema 35 did not carry the physical
                    # LTFS path.  Derive it exactly once while publishing the
                    # plan; all later lifecycle paths load the persisted value.
                    tape_relative_path = ltfs_tape_relative_path(relative_path)
                size = item.get("size")
                mtime_ns = item.get("mtime_ns")
                self._validate_safe_identifier(library_id, "job plan item library")
                validate_source_relative_path(relative_path, "job plan item path")
                self._validate_portable_relative_path(
                    tape_relative_path, "job plan item tape path"
                )
                if (
                    library_id.casefold() not in library_ids
                    or type(size) is not int
                    or size < 0
                    or type(mtime_ns) is not int
                    or mtime_ns < 0
                    or tape_relative_path != ltfs_tape_relative_path(relative_path)
                ):
                    raise ValidationError("invalid job plan item evidence")
                key = (library_id.casefold(), relative_path.casefold())
                if key in seen_items:
                    raise ValidationError("duplicate job plan item")
                seen_items.add(key)
                item_bytes += size
                normalized_items.append(
                    (
                        plan_id,
                        expected_sequence,
                        expected_item_sequence,
                        library_id,
                        relative_path,
                        tape_relative_path,
                        size,
                        mtime_ns,
                        supplied_tape_relative_path,
                    )
                )
            if item_bytes != payload_bytes:
                raise ValidationError("job plan item bytes do not match allocation")
            normalized_cassettes.append(
                (
                    plan_id,
                    expected_sequence,
                    objects,
                    payload_bytes,
                    allocation_bytes,
                    float(utilization),
                    operation,
                )
            )

        relational_libraries = [
            {
                "library_id": row[2],
                "scan_fingerprint_sha256": row[5],
                "scan_revision": row[4],
                "source_root": row[3],
            }
            for row in normalized_libraries
        ]
        relational_cassettes: list[dict[str, Any]] = []
        items_by_cassette: dict[int, list[dict[str, Any]]] = {}
        for item in normalized_items:
            items_by_cassette.setdefault(int(item[1]), []).append(
                {
                    "library_id": item[3],
                    "mtime_ns": item[7],
                    "relative_path": item[4],
                    "size": item[6],
                }
            )
            if item[8]:
                items_by_cassette[int(item[1])][-1]["tape_relative_path"] = item[5]
        for row in normalized_cassettes:
            relational_cassettes.append(
                {
                    "allocation_bytes": row[4],
                    "capacity_utilization": row[5],
                    "items": items_by_cassette.get(int(row[1]), []),
                    "objects": row[2],
                    "operation": row[6],
                    "payload_bytes": row[3],
                    "sequence": row[1],
                }
            )
        if (
            parsed.get("libraries") != relational_libraries
            or parsed.get("cassettes") != relational_cassettes
            or parsed.get("library_ids")
            != [row["library_id"] for row in relational_libraries]
            or parsed.get("canonical_json_version") != 1
            or parsed.get("plan_schema_version") != 1
            or parsed.get("planner_version") != "automatic-ltfs-v1"
            or parsed.get("application_settings")
            != {
                "fingerprint_sha256": settings_fingerprint,
                "revision": settings_revision,
            }
        ):
            raise ValidationError(
                "canonical job plan does not match relational manifest"
            )

        managed_sources = list(frozen_plan.get("managed_sources", ()))
        managed_source_leases = frozen_plan.get("managed_source_leases", {})
        normalized_managed_sources: list[tuple[str, dict[str, Any], str]] = []
        normalized_managed_ids: set[str] = set()
        if not isinstance(managed_source_leases, Mapping):
            raise ValidationError("invalid managed source plan evidence")
        normalized_lease_mapping: dict[str, str] = {}
        for lease_library_id, lease_id in managed_source_leases.items():
            if (
                not isinstance(lease_library_id, str)
                or not lease_library_id
                or not isinstance(lease_id, str)
                or not lease_id
            ):
                raise ValidationError("invalid managed source plan evidence")
            folded_lease_id = lease_library_id.casefold()
            if folded_lease_id in normalized_lease_mapping:
                raise ValidationError("managed source plan cardinality mismatch")
            normalized_lease_mapping[folded_lease_id] = lease_id
        if managed_sources:
            if parsed.get("managed_sources") != managed_sources:
                raise ValidationError("invalid managed source plan evidence")
            for item in managed_sources:
                if not isinstance(item, Mapping) or set(item) != {
                    "library_id",
                    "evidence",
                }:
                    raise ValidationError("invalid managed source plan evidence")
                library_id = str(item["library_id"])
                folded_library_id = library_id.casefold()
                if folded_library_id not in library_ids:
                    raise ValidationError("invalid managed source plan library")
                if folded_library_id in normalized_managed_ids:
                    raise ValidationError("managed source plan cardinality mismatch")
                normalized_managed_ids.add(folded_library_id)
                evidence = canonical_managed_source_evidence(item["evidence"])
                lease_id = normalized_lease_mapping.get(folded_library_id)
                if not isinstance(lease_id, str):
                    raise ValidationError("missing managed source plan lease")
                normalized_managed_sources.append((library_id, evidence, lease_id))
        elif "managed_sources" in parsed:
            raise ValidationError("unexpected managed source plan evidence")

        policy_snapshot = frozen_plan.get("policy_snapshot")
        encoded_policy: str | None = None
        policy_sha256: str | None = None
        if policy_snapshot is not None:
            policy_keys = {
                "capacity_reserve_bytes",
                "default_media_profile",
                "minimum_source_file_age_seconds",
                "selected_media_profile",
                "settings_revision",
                "tape_root_directory",
            }
            if (
                not isinstance(policy_snapshot, Mapping)
                or set(policy_snapshot) not in (
                    policy_keys,
                    policy_keys | {"source_change_detection_policy"},
                )
            ):
                raise ValidationError("invalid job plan policy snapshot")
            reserve = policy_snapshot["capacity_reserve_bytes"]
            minimum_age = policy_snapshot["minimum_source_file_age_seconds"]
            selected_profile = require_ltfs_profile(
                policy_snapshot["selected_media_profile"]
            )
            default_profile = require_ltfs_profile(
                policy_snapshot["default_media_profile"]
            )
            if (
                policy_snapshot["settings_revision"] != settings_revision
                or selected_profile.key != parsed.get("media_key")
                or default_profile.key != policy_snapshot["default_media_profile"]
                or policy_snapshot.get("source_change_detection_policy", "size_mtime")
                not in {"size_mtime", "size_mtime_change"}
                or type(reserve) is not int
                or reserve < 0
                or selected_profile.ltfs_usable_bytes is None
                or reserve >= selected_profile.ltfs_usable_bytes
                or type(minimum_age) is not int
                or not 0 <= minimum_age <= 31 * 24 * 60 * 60
                or not isinstance(policy_snapshot["tape_root_directory"], str)
            ):
                raise ValidationError("invalid job plan policy snapshot")
            encoded_policy = json.dumps(
                dict(policy_snapshot),
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            policy_sha256 = hashlib.sha256(encoded_policy.encode("utf-8")).hexdigest()

        try:
            with self.transaction() as db:
                draft = db.execute(
                    "SELECT * FROM job_plan_drafts WHERE id=?", (plan_id,)
                ).fetchone()
                if draft is None:
                    raise CatalogError(f"job plan not found: {plan_id}")
                if draft["state"] != "building":
                    raise CatalogError(f"job plan is not building: {plan_id}")
                requested = json.loads(draft["requested_library_ids_json"])
                if [row[2] for row in normalized_libraries] != requested:
                    raise ValidationError("job plan libraries changed while building")
                if parsed.get("kind") != draft["kind"]:
                    raise ValidationError("job plan kind changed while building")
                expected_base_job = (
                    {
                        "fingerprint_sha256": draft["base_job_fingerprint_sha256"],
                        "id": draft["base_job_id"],
                        "revision": draft["base_job_revision"],
                    }
                    if draft["kind"] == "extend"
                    else None
                )
                if (
                    parsed.get("media_key") != draft["media_key"]
                    or "base_job" not in parsed
                    or parsed["base_job"] != expected_base_job
                ):
                    raise ValidationError(
                        "canonical job plan does not match frozen draft"
                    )
                has_source_kind = any(
                    str(row["name"]) == "source_kind"
                    for row in db.execute("PRAGMA table_info(libraries)")
                )
                persisted_network_libraries = (
                    {
                        str(row["id"]).casefold(): row
                        for row in db.execute(
                            "SELECT * FROM libraries WHERE source_kind='network' "
                            "AND id IN ("
                            + ",".join("?" for _row in normalized_libraries)
                            + ")",
                            tuple(row[2] for row in normalized_libraries),
                        )
                    }
                    if has_source_kind
                    else {}
                )
                expected_managed_ids = set(persisted_network_libraries)
                if (
                    normalized_managed_ids != expected_managed_ids
                    or set(normalized_lease_mapping) != expected_managed_ids
                ):
                    raise ValidationError("managed source plan cardinality mismatch")
                managed_by_library = {
                    library_id.casefold(): evidence
                    for library_id, evidence, _lease_id in normalized_managed_sources
                }
                frozen_by_library = {
                    str(row[2]).casefold(): row for row in normalized_libraries
                }
                for library_key, library in persisted_network_libraries.items():
                    binding = db.execute(
                        "SELECT binding.*,binding_evidence.evidence_json "
                        "FROM library_share_bindings AS binding "
                        "JOIN library_share_binding_evidence AS binding_evidence "
                        "ON binding_evidence.library_id=binding.library_id "
                        "WHERE binding.library_id=? COLLATE NOCASE",
                        (library["id"],),
                    ).fetchone()
                    evidence = managed_by_library[library_key]
                    frozen_library = frozen_by_library[library_key]
                    if (
                        binding is None
                        or str(binding["share_id"]).casefold()
                        != str(evidence["share_id"]).casefold()
                        or str(binding["relative_subpath"])
                        != str(evidence["relative_subpath"])
                        or json.loads(str(binding["evidence_json"])) != evidence
                        or str(library["source_root"]) != str(frozen_library[3])
                        or str(library["source_identity_sha256"])
                        != str(evidence["source_identity_sha256"])
                    ):
                        raise ValidationError("managed source plan identity mismatch")
                db.executemany(
                    "INSERT INTO job_plan_libraries("
                    "plan_id,sequence,library_id,source_root,scan_revision,"
                    "scan_fingerprint_sha256) VALUES(?,?,?,?,?,?)",
                    normalized_libraries,
                )
                db.executemany(
                    "INSERT INTO job_plan_cassettes("
                    "plan_id,sequence,objects,payload_bytes,allocation_bytes,"
                    "capacity_utilization,operation) VALUES(?,?,?,?,?,?,?)",
                    normalized_cassettes,
                )
                item_columns = {
                    str(row["name"])
                    for row in db.execute("PRAGMA table_info(job_plan_items)")
                }
                if "tape_relative_path" in item_columns:
                    db.executemany(
                        "INSERT INTO job_plan_items("
                        "plan_id,cassette_sequence,item_sequence,library_id,"
                        "relative_path,tape_relative_path,size,mtime_ns) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        [item[:8] for item in normalized_items],
                    )
                else:
                    db.executemany(
                        "INSERT INTO job_plan_items("
                        "plan_id,cassette_sequence,item_sequence,library_id,"
                        "relative_path,size,mtime_ns) VALUES(?,?,?,?,?,?,?)",
                        [item[:5] + item[6:8] for item in normalized_items],
                    )
                db.execute(
                    """
                    UPDATE job_plan_drafts
                    SET state='ready',updated_at=?,canonical_json=?,digest_sha256=?,
                        canonical_json_version=?,plan_schema_version=?,planner_version=?,
                        application_settings_revision=?,
                        application_settings_fingerprint_sha256=?
                    WHERE id=?
                    """,
                    (
                        utc_now(),
                        canonical_json,
                        digest_sha256,
                        frozen_plan["canonical_json_version"],
                        frozen_plan["plan_schema_version"],
                        frozen_plan["planner_version"],
                        settings_revision,
                        settings_fingerprint,
                        plan_id,
                    ),
                )
                if encoded_policy is not None and policy_sha256 is not None:
                    db.execute(
                        "INSERT INTO job_plan_policy_snapshots("
                        "plan_id,settings_revision,policy_json,policy_sha256,created_at) "
                        "VALUES(?,?,?,?,?)",
                        (
                            plan_id,
                            settings_revision,
                            encoded_policy,
                            policy_sha256,
                            utc_now(),
                        ),
                    )
                for library_id, evidence, lease_id in normalized_managed_sources:
                    lease = db.execute(
                        "SELECT * FROM managed_source_leases WHERE lease_id=? "
                        "AND consumer_kind='plan'",
                        (lease_id,),
                    ).fetchone()
                    if (
                        lease is None
                        or str(lease["share_id"]).casefold()
                        != str(evidence["share_id"]).casefold()
                        or not self._managed_source_evidence_matches_share_tx(
                            db, evidence
                        )
                    ):
                        raise CatalogError("managed_source_lease_lost")
                    evidence_json = json.dumps(
                        evidence,
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    )
                    db.execute(
                        "INSERT INTO job_plan_share_evidence("
                        "plan_id,library_id,share_id,evidence_json,evidence_sha256,"
                        "admitted_at) VALUES(?,?,?,?,?,?)",
                        (
                            plan_id,
                            library_id,
                            evidence["share_id"],
                            evidence_json,
                            hashlib.sha256(
                                b"lto-managed-source-evidence-v1\0"
                                + evidence_json.encode("utf-8")
                            ).hexdigest(),
                            utc_now(),
                        ),
                    )
                    db.execute(
                        "DELETE FROM managed_source_leases WHERE lease_id=?",
                        (lease_id,),
                    )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(f"invalid persisted job plan: {plan_id}") from exc
        return self.get_job_plan(plan_id)

    def get_job_plan_policy_snapshot(self, plan_id: str) -> dict[str, Any]:
        validate_id(plan_id, "plan ID")
        row = self.connection.execute(
            "SELECT * FROM job_plan_policy_snapshots WHERE plan_id=?", (plan_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("job_plan_policy_snapshot_not_found")
        try:
            policy = json.loads(row["policy_json"])
        except (TypeError, ValueError) as exc:
            raise CatalogError("invalid job plan policy snapshot") from exc
        if (
            not isinstance(policy, dict)
            or hashlib.sha256(str(row["policy_json"]).encode("utf-8")).hexdigest()
            != row["policy_sha256"]
        ):
            raise CatalogError("invalid job plan policy snapshot")
        return dict(policy)

    def get_job_policy_snapshot(self, job_id: str) -> dict[str, Any]:
        validate_id(job_id, "job ID")
        row = self.connection.execute(
            "SELECT * FROM job_policy_snapshots WHERE job_id=?", (job_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("job_policy_snapshot_not_found")
        try:
            policy = json.loads(row["policy_json"])
        except (TypeError, ValueError) as exc:
            raise CatalogError("invalid job policy snapshot") from exc
        if (
            not isinstance(policy, dict)
            or hashlib.sha256(str(row["policy_json"]).encode("utf-8")).hexdigest()
            != row["policy_sha256"]
        ):
            raise CatalogError("invalid job policy snapshot")
        return dict(policy)

    def fail_job_plan_draft(
        self, plan_id: str, failure_code: str, failure_message: str
    ) -> dict[str, Any]:
        validate_id(plan_id, "plan ID")
        self._validate_safe_identifier(failure_code, "job plan failure code")
        if not isinstance(failure_message, str) or not failure_message:
            raise ValidationError("invalid job plan failure message")
        with self.transaction() as db:
            cursor = db.execute(
                "UPDATE job_plan_drafts SET state='failed',updated_at=?,"
                "failure_code=?,failure_message=? WHERE id=? AND state='building'",
                (utc_now(), failure_code, failure_message[:500], plan_id),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"job plan is not building: {plan_id}")
        return self.get_job_plan(plan_id)

    def cleanup_expired_job_plans(self, now: str | None = None) -> int:
        effective_now = utc_now() if now is None else now
        if self._parse_utc_timestamp(effective_now) is None:
            raise ValidationError("invalid job plan cleanup time")
        with self.transaction() as db:
            cursor = db.execute(
                "UPDATE job_plan_drafts SET state='expired',updated_at=? "
                "WHERE state IN ('building','ready') AND expires_at<=?",
                (effective_now, effective_now),
            )
            return cursor.rowcount

    def purge_expired_job_plans(self, expired_before: str) -> int:
        if self._parse_utc_timestamp(expired_before) is None:
            raise ValidationError("invalid job plan purge time")
        self._expired_plan_cleanup_active = True
        try:
            with self.transaction() as db:
                db.execute(
                    "DELETE FROM job_plan_share_evidence WHERE plan_id IN ("
                    "SELECT id FROM job_plan_drafts "
                    "WHERE state='expired' AND updated_at<=?)",
                    (expired_before,),
                )
                cursor = db.execute(
                    "DELETE FROM job_plan_drafts "
                    "WHERE state='expired' AND updated_at<=?",
                    (expired_before,),
                )
                return cursor.rowcount
        finally:
            self._expired_plan_cleanup_active = False

    @contextmanager
    def _controlled_job_delete(self) -> Iterator[None]:
        if self._job_delete_active:
            raise CatalogError("automatic job delete already active")
        self._job_delete_active = True
        try:
            yield
        finally:
            self._job_delete_active = False

    @contextmanager
    def _controlled_operation_block_archive(self) -> Iterator[None]:
        if self._operation_block_archive_active:
            raise CatalogError("automatic operation block archive already active")
        self._operation_block_archive_active = True
        try:
            yield
        finally:
            self._operation_block_archive_active = False

    def _archive_automatic_operation_blocks(
        self,
        db: sqlite3.Connection,
        block_ids: Sequence[str],
        *,
        disposition: Literal[
            "job_deleted",
            "registered_tape_reformatted",
            "registered_tape_reset",
            "registered_tape_recovery_reset",
        ],
    ) -> int:
        unique_block_ids = tuple(
            dict.fromkeys(str(block_id) for block_id in block_ids)
        )
        if not unique_block_ids:
            return 0
        placeholders = ", ".join("?" for _ in unique_block_ids)
        rows = tuple(
            db.execute(
                "SELECT binding.block_id,binding.operation_id,binding.job_id,"
                "binding.cassette_sequence,operation.owner_generation AS "
                "daemon_generation,binding.created_at "
                "FROM automatic_operation_blocks AS binding "
                "JOIN daemon_operations AS operation "
                "ON operation.id=binding.operation_id "
                f"WHERE binding.block_id IN ({placeholders}) "
                "ORDER BY binding.block_id",
                unique_block_ids,
            )
        )
        if len(rows) != len(unique_block_ids):
            raise CatalogError("automatic operation block ownership is incomplete")
        archived_at = utc_now()
        with self._controlled_operation_block_archive():
            db.executemany(
                "INSERT INTO automatic_operation_block_tombstones("
                "block_id,operation_id,job_id,cassette_sequence,daemon_generation,"
                "created_at,disposition,archived_at) VALUES(?,?,?,?,?,?,?,?)",
                [
                    (
                        row["block_id"],
                        row["operation_id"],
                        row["job_id"],
                        row["cassette_sequence"],
                        row["daemon_generation"],
                        row["created_at"],
                        disposition,
                        archived_at,
                    )
                    for row in rows
                ],
            )
            cursor = db.execute(
                f"DELETE FROM automatic_operation_blocks "
                f"WHERE block_id IN ({placeholders})",
                unique_block_ids,
            )
        if cursor.rowcount != len(rows):
            raise CatalogError("automatic operation block archive is incomplete")
        return len(rows)

    def _invalidate_tape_catalog_for_lifecycle(
        self,
        db: sqlite3.Connection,
        tape_id: str,
        *,
        disposition: Literal[
            "job_deleted",
            "registered_tape_reformatted",
            "registered_tape_reset",
            "registered_tape_recovery_reset",
        ],
    ) -> dict[str, int]:
        file_count = int(
            db.execute(
                "SELECT COUNT(*) FROM file_versions "
                "WHERE tape_id=? COLLATE NOCASE",
                (tape_id,),
            ).fetchone()[0]
        )
        block_count = int(
            db.execute(
                "SELECT COUNT(*) FROM blocks WHERE tape_id=? COLLATE NOCASE",
                (tape_id,),
            ).fetchone()[0]
        )
        owned_block_ids = tuple(
            str(row["block_id"])
            for row in db.execute(
                "SELECT binding.block_id "
                "FROM automatic_operation_blocks AS binding "
                "JOIN blocks AS block ON block.id=binding.block_id "
                "WHERE block.tape_id=? COLLATE NOCASE "
                "ORDER BY binding.block_id",
                (tape_id,),
            )
        )
        self._archive_automatic_operation_blocks(
            db,
            owned_block_ids,
            disposition=disposition,
        )
        db.execute(
            "DELETE FROM file_versions WHERE tape_id=? COLLATE NOCASE", (tape_id,)
        )
        db.execute("DELETE FROM blocks WHERE tape_id=? COLLATE NOCASE", (tape_id,))
        tape_count = max(
            0,
            int(
                db.execute(
                    "DELETE FROM tapes WHERE id=? COLLATE NOCASE", (tape_id,)
                ).rowcount
            ),
        )
        return {"blocks": block_count, "files": file_count, "tapes": tape_count}

    @staticmethod
    def _resolve_registered_tape_label_tx(
        db: sqlite3.Connection,
        physical_label: str,
    ) -> tuple[Literal["missing", "unique", "ambiguous"], sqlite3.Row | None]:
        """Resolve one six-character physical label against legacy tape identities."""

        normalized_label = physical_label.strip().upper()
        if re.fullmatch(r"[A-Z0-9]{6}", normalized_label) is None:
            raise CatalogError("registered_tape_identity_label_invalid")
        candidates = list(
            db.execute(
                "SELECT * FROM tapes WHERE "
                "upper(substr(trim(id),1,6))=? "
                "OR upper(substr(trim(cassette_number),1,6))=? "
                "ORDER BY id COLLATE NOCASE LIMIT 2",
                (normalized_label, normalized_label),
            )
        )
        if not candidates:
            return "missing", None
        if len(candidates) == 1:
            return "unique", candidates[0]
        return "ambiguous", None

    @staticmethod
    def _registered_tape_reformat_receipt_tx(
        db: sqlite3.Connection,
        *,
        job_id: str,
        sequence: int,
        physical_label: str,
    ) -> dict[str, int] | None:
        """Return one unambiguous prior invalidation receipt for recovery replay."""

        proofs: set[tuple[str, int, int, int, int]] = set()
        for row in db.execute(
            "SELECT payload_json FROM events "
            "WHERE action='tape.reformat.catalog_invalidated' ORDER BY id",
        ):
            try:
                payload = json.loads(str(row["payload_json"]))
            except (TypeError, ValueError):
                continue
            if (
                not isinstance(payload, dict)
                or str(payload.get("job_id", "")).casefold() != job_id.casefold()
                or type(payload.get("sequence")) is not int
                or payload["sequence"] != sequence
                or str(payload.get("physical_label", "")).casefold()
                != physical_label.casefold()
                or not isinstance(payload.get("tape_id"), str)
                or not payload["tape_id"]
            ):
                continue
            counts = tuple(
                payload.get(field)
                for field in ("tapes", "blocks", "files", "jobs")
            )
            if any(type(value) is not int or value < 0 for value in counts):
                continue
            proofs.add((payload["tape_id"].casefold(), *counts))
        if not proofs:
            return None
        if len(proofs) != 1:
            raise CatalogError("registered_tape_reformat_receipt_ambiguous")
        _tape_id, tapes, blocks, files, jobs = proofs.pop()
        return {"tapes": tapes, "blocks": blocks, "files": files, "jobs": jobs}

    def get_job_plan(self, plan_id: str) -> dict[str, Any]:
        validate_id(plan_id, "plan ID")
        row = self.connection.execute(
            "SELECT * FROM job_plan_drafts WHERE id=?", (plan_id,)
        ).fetchone()
        if row is None:
            raise CatalogError(f"job plan not found: {plan_id}")
        result = dict(row)
        libraries = [
            dict(item)
            for item in self.connection.execute(
                "SELECT * FROM job_plan_libraries WHERE plan_id=? ORDER BY sequence",
                (plan_id,),
            )
        ]
        cassette_rows = self.connection.execute(
            "SELECT * FROM job_plan_cassettes WHERE plan_id=? ORDER BY sequence",
            (plan_id,),
        ).fetchall()
        cassettes: list[dict[str, Any]] = []
        for cassette_row in cassette_rows:
            cassette = dict(cassette_row)
            cassette["items"] = [
                dict(item)
                for item in self.connection.execute(
                    "SELECT * FROM job_plan_items WHERE plan_id=? "
                    "AND cassette_sequence=? ORDER BY item_sequence",
                    (plan_id, cassette["sequence"]),
                )
            ]
            cassettes.append(cassette)
        result["library_ids"] = (
            [item["library_id"] for item in libraries]
            if libraries
            else json.loads(row["requested_library_ids_json"])
        )
        result["libraries"] = libraries
        result["cassettes"] = cassettes
        result["requires_automatic_format_authorization"] = (
            self.extension_requires_automatic_format_authorization(
                str(row["base_job_id"]),
                (str(cassette["operation"]) for cassette in cassette_rows),
            )
            if row["kind"] == "extend"
            else False
        )
        if row["canonical_json"] is not None:
            canonical = json.loads(row["canonical_json"])
            for field in (
                "completed_assignments",
                "existing_reserve_labels",
                "residual_append_capacity_bytes",
            ):
                if field in canonical:
                    result[field] = canonical[field]
        return result

    @staticmethod
    def _extension_requires_automatic_format_authorization_tx(
        db: sqlite3.Connection,
        job_id: str,
        plan_operations: Iterable[str],
    ) -> bool:
        """Return whether an extension's next layout needs a format grant."""

        if any(operation in {"format", "reserve"} for operation in plan_operations):
            return True
        return db.execute(
            "SELECT 1 FROM automatic_cassettes WHERE job_id=? "
            "AND status IN ('pending','waiting_media') AND operation='format' LIMIT 1",
            (job_id,),
        ).fetchone() is not None

    def extension_requires_automatic_format_authorization(
        self, job_id: str, plan_operations: Iterable[str]
    ) -> bool:
        """Read the catalog-owned automatic-format requirement for an extension."""

        validate_id(job_id, "job ID")
        return self._extension_requires_automatic_format_authorization_tx(
            self.connection, job_id, plan_operations
        )

    def list_job_plans(self) -> list[dict[str, Any]]:
        return [
            self.get_job_plan(row["id"])
            for row in self.connection.execute(
                "SELECT id FROM job_plan_drafts ORDER BY created_at DESC,id"
            )
        ]

    def consume_job_plan(
        self,
        *,
        plan_id: str,
        digest_sha256: str,
        labels: tuple[str, ...] | list[str],
        idempotency_key: str,
        request_sha256: str,
        job_id: str,
        display_name: str,
        device_name: str,
        mount_path: str,
        consumed_at: str,
        actor: str = "system",
        managed_source_leases: Mapping[str, str] | None = None,
        allow_registered_reuse: bool = False,
        authorize_automatic_formatting: bool,
    ) -> tuple[str, bool]:
        """Linearize one exact plan consumption with its complete legacy job rows."""

        validate_id(plan_id, "plan ID")
        validate_id(job_id, "job ID")
        self._validate_sha256(digest_sha256, "job plan digest")
        self._validate_safe_identifier(idempotency_key, "idempotency key")
        self._validate_sha256(request_sha256, "job plan request digest")
        if self._parse_utc_timestamp(consumed_at) is None:
            raise ValidationError("invalid job plan consumption time")
        if type(allow_registered_reuse) is not bool:
            raise ValidationError("invalid registered cassette reuse authority")
        if type(authorize_automatic_formatting) is not bool:
            raise ValidationError("invalid automatic formatting authority")
        if (
            not isinstance(display_name, str)
            or not display_name.strip()
            or len(display_name.strip()) > 120
            or any(ord(character) < 32 for character in display_name)
        ):
            raise ValidationError("invalid job display name")
        normalized_labels = tuple(str(label).strip().upper() for label in labels)
        if (
            not normalized_labels
            or len(normalized_labels) > 64
            or len(set(normalized_labels)) != len(normalized_labels)
            or any(
                not re.fullmatch(r"[A-Z0-9]{6}", label) for label in normalized_labels
            )
        ):
            raise ValidationError("invalid physical cassette labels")

        outcome: tuple[str, bool] | None = None
        deferred_error: str | None = None
        reused_labels: set[str] = set()
        try:
            with self.transaction() as db:
                draft = db.execute(
                    "SELECT * FROM job_plan_drafts WHERE id=?", (plan_id,)
                ).fetchone()
                if draft is None:
                    deferred_error = "plan_not_found"
                elif draft["creator"] == "boundary-coordinator":
                    deferred_error = "boundary_plan_reserved"
                elif draft["digest_sha256"] != digest_sha256:
                    deferred_error = "plan_digest_mismatch"
                elif draft["state"] == "consumed":
                    if (
                        draft["consumption_key"] == idempotency_key
                        and draft["consumption_request_sha256"] == request_sha256
                        and draft["consumed_job_id"] is not None
                    ):
                        outcome = (str(draft["consumed_job_id"]), True)
                    else:
                        deferred_error = "plan_consumed"
                elif draft["state"] not in {"ready", "building"}:
                    deferred_error = f"plan_{draft['state']}"
                elif draft["expires_at"] <= consumed_at:
                    db.execute(
                        "UPDATE job_plan_drafts SET state='expired',updated_at=? "
                        "WHERE id=? AND state IN ('building','ready')",
                        (consumed_at, plan_id),
                    )
                    deferred_error = "plan_expired"
                elif draft["state"] != "ready":
                    deferred_error = "plan_building"
                elif draft["kind"] != "create":
                    deferred_error = "plan_kind_unsupported"
                else:
                    libraries = db.execute(
                        "SELECT * FROM job_plan_libraries WHERE plan_id=? ORDER BY sequence",
                        (plan_id,),
                    ).fetchall()
                    cassettes = db.execute(
                        "SELECT * FROM job_plan_cassettes WHERE plan_id=? ORDER BY sequence",
                        (plan_id,),
                    ).fetchall()
                    if (
                        not libraries
                        or not cassettes
                        or len(normalized_labels) < len(cassettes)
                    ):
                        deferred_error = "plan_labels_inexact"
                    else:
                        planned_labels = normalized_labels[: len(cassettes)]
                        reserve_labels = normalized_labels[len(cassettes) :]
                        for library in libraries:
                            current = db.execute(
                                "SELECT source_root,status FROM libraries WHERE id=?",
                                (library["library_id"],),
                            ).fetchone()
                            if (
                                current is None
                                or current["status"] != "active"
                                or current["source_root"] != library["source_root"]
                            ):
                                deferred_error = "plan_stale"
                                break
                            conflict = db.execute(
                                """
                                SELECT job.id
                                FROM automatic_jobs job
                                JOIN automatic_job_libraries link ON link.job_id=job.id
                                WHERE link.library_id=? COLLATE NOCASE
                                  AND job.status NOT IN ('completed','failed')
                                LIMIT 1
                                """,
                                (library["library_id"],),
                            ).fetchone()
                            if conflict is not None:
                                deferred_error = "plan_library_conflict"
                                break
                    if deferred_error is None:
                        for label in normalized_labels:
                            assigned = db.execute(
                                "SELECT job_id FROM automatic_cassettes "
                                "WHERE upper(substr(physical_label,1,6))=? "
                                "AND status NOT IN ('completed','failed') LIMIT 1",
                                (label,),
                            ).fetchone()
                            if assigned is not None:
                                deferred_error = "plan_label_unavailable"
                                break
                            resolution, _registered = self._resolve_registered_tape_label_tx(
                                db, label
                            )
                            if resolution == "ambiguous":
                                deferred_error = "plan_label_identity_ambiguous"
                                break
                            if resolution == "unique" and not allow_registered_reuse:
                                deferred_error = "plan_label_registered"
                                break
                            if resolution == "unique":
                                reused_labels.add(label)
                    if deferred_error is None:
                        has_format_rows = bool(reserve_labels) or any(
                            label in reused_labels
                            or str(cassettes[index]["operation"]) != "append"
                            for index, label in enumerate(planned_labels)
                        )
                        if has_format_rows and not authorize_automatic_formatting:
                            deferred_error = "automatic_format_authorization_required"
                    if deferred_error is None:
                        has_share_evidence = db.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' "
                            "AND name='job_plan_share_evidence'"
                        ).fetchone()
                        plan_share_evidence = (
                            []
                            if has_share_evidence is None
                            else db.execute(
                                "SELECT * FROM job_plan_share_evidence "
                                "WHERE plan_id=? ORDER BY library_id COLLATE NOCASE",
                                (plan_id,),
                            ).fetchall()
                        )
                        lease_mapping = dict(managed_source_leases or {})
                        managed_plan_libraries = (
                            set()
                            if has_share_evidence is None
                            else {
                                str(row["library_id"]).casefold()
                                for row in db.execute(
                                    "SELECT plan_library.library_id "
                                    "FROM job_plan_libraries AS plan_library "
                                    "JOIN libraries AS library "
                                    "ON library.id=plan_library.library_id "
                                    "WHERE plan_library.plan_id=? "
                                    "AND library.source_kind='network'",
                                    (plan_id,),
                                )
                            }
                        )
                        evidence_libraries = {
                            str(row["library_id"]).casefold()
                            for row in plan_share_evidence
                        }
                        if (
                            managed_plan_libraries != evidence_libraries
                            or evidence_libraries != set(lease_mapping)
                        ):
                            deferred_error = "managed_source_evidence_changed"
                        for row in plan_share_evidence:
                            lease = db.execute(
                                "SELECT * FROM managed_source_leases WHERE lease_id=? "
                                "AND consumer_kind='save'",
                                (lease_mapping.get(str(row["library_id"]).casefold()),),
                            ).fetchone()
                            if (
                                lease is None
                                or str(lease["share_id"]).casefold()
                                != str(row["share_id"]).casefold()
                                or not self._managed_source_evidence_matches_share_tx(
                                    db, json.loads(str(row["evidence_json"]))
                                )
                            ):
                                deferred_error = "managed_source_evidence_changed"
                                break
                    if deferred_error is None:
                        db.execute(
                            """
                            INSERT INTO automatic_jobs(
                                id,display_name,media_key,library_id,device_name,
                                mount_path,status,total_cassettes,
                                destructive_confirmed_at,force_format,created_at
                            ) VALUES(?,?,?,?,?,?,'planned',?,?,1,?)
                            """,
                            (
                                job_id,
                                display_name.strip(),
                                draft["media_key"],
                                libraries[0]["library_id"],
                                device_name,
                                mount_path,
                                len(normalized_labels),
                                consumed_at,
                                consumed_at,
                            ),
                        )
                        db.executemany(
                            "INSERT INTO automatic_job_libraries("
                            "job_id,library_id,sequence) VALUES(?,?,?)",
                            [
                                (job_id, row["library_id"], row["sequence"])
                                for row in libraries
                            ],
                        )
                        cassette_by_sequence = {
                            int(row["sequence"]): row for row in cassettes
                        }
                        db.executemany(
                            """
                            INSERT INTO automatic_cassettes(
                                job_id,sequence,physical_label,tape_serial,status,
                                planned_files,planned_bytes,operation,reuse_registered
                            ) VALUES(?,?,?,?,'pending',?,?,?,?)
                            """,
                            [
                                (
                                    job_id,
                                    sequence,
                                    label,
                                    label,
                                    int(cassette_by_sequence[sequence]["objects"]),
                                    int(
                                        cassette_by_sequence[sequence]["payload_bytes"]
                                    ),
                                    (
                                        "format"
                                        if label in reused_labels
                                        else (
                                            cassette_by_sequence[sequence]["operation"]
                                            if cassette_by_sequence[sequence]["operation"]
                                            in {"format", "append"}
                                            else "format"
                                        )
                                    ),
                                    int(label in reused_labels),
                                )
                                for sequence, label in enumerate(planned_labels, 1)
                            ],
                        )
                        db.executemany(
                            """
                            INSERT INTO automatic_cassettes(
                                job_id,sequence,physical_label,tape_serial,status,
                                planned_files,planned_bytes,operation,reuse_registered
                            ) VALUES(?,?,?,?,'pending',0,0,'format',?)
                            """,
                            [
                                (
                                    job_id,
                                    sequence,
                                    label,
                                    label,
                                    int(label in reused_labels),
                                )
                                for sequence, label in enumerate(
                                    reserve_labels, len(cassettes) + 1
                                )
                            ],
                        )
                        items = db.execute(
                            "SELECT * FROM job_plan_items WHERE plan_id=? "
                            "ORDER BY cassette_sequence,item_sequence",
                            (plan_id,),
                        ).fetchall()
                        item_columns = {
                            str(row["name"])
                            for row in db.execute(
                                "PRAGMA table_info(automatic_cassette_items)"
                            )
                        }
                        if "tape_relative_path" in item_columns:
                            db.executemany(
                                "INSERT INTO automatic_cassette_items("
                                "job_id,sequence,item_sequence,library_id,relative_path,"
                                "tape_relative_path,size,mtime_ns) "
                                "VALUES(?,?,?,?,?,?,?,?)",
                                [
                                    (
                                        job_id,
                                        row["cassette_sequence"],
                                        row["item_sequence"],
                                        row["library_id"],
                                        row["relative_path"],
                                        row["tape_relative_path"],
                                        row["size"],
                                        row["mtime_ns"],
                                    )
                                    for row in items
                                ],
                            )
                        else:
                            db.executemany(
                                "INSERT INTO automatic_cassette_items("
                                "job_id,sequence,item_sequence,library_id,relative_path,"
                                "size,mtime_ns) VALUES(?,?,?,?,?,?,?)",
                                [
                                    (
                                        job_id,
                                        row["cassette_sequence"],
                                        row["item_sequence"],
                                        row["library_id"],
                                        row["relative_path"],
                                        row["size"],
                                        row["mtime_ns"],
                                    )
                                    for row in items
                                ],
                            )
                        db.execute(
                            "UPDATE job_plan_drafts SET state='consumed',updated_at=?,"
                            "consumed_at=?,consumed_job_id=?,consumption_key=?,"
                            "consumption_request_sha256=? WHERE id=? AND state='ready'",
                            (
                                consumed_at,
                                consumed_at,
                                job_id,
                                idempotency_key,
                                request_sha256,
                                plan_id,
                            ),
                        )
                        has_management_state = (
                            db.execute(
                                "SELECT 1 FROM sqlite_master WHERE type='table' "
                                "AND name='job_management_state'"
                            ).fetchone()
                            is not None
                        )
                        if has_management_state:
                            db.execute(
                                "INSERT INTO job_management_state("
                                "job_id,revision,current_checkpoint,"
                                "creation_plan_id,updated_at) "
                                "VALUES(?,0,'saved',?,?)",
                                (job_id, plan_id, consumed_at),
                            )
                        layout_epoch = None
                        if db.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' "
                            "AND name='job_layout_epochs'"
                        ).fetchone() is not None:
                            db.execute(
                                "INSERT OR IGNORE INTO job_incremental_policies("
                                "job_id,cadence,revision,updated_at) VALUES(?,'off',1,?)",
                                (job_id, consumed_at),
                            )
                            layout_epoch = self._insert_layout_epoch_tx(
                                db,
                                job_id,
                                kind="initial",
                                plan_id=plan_id,
                                plan_digest_sha256=digest_sha256,
                                created_at=consumed_at,
                            )
                        if (
                            layout_epoch is not None
                            and db.execute(
                                "SELECT 1 FROM sqlite_master WHERE type='table' "
                                "AND name='automatic_sequence_state'"
                            ).fetchone() is not None
                        ):
                            fingerprint = str(
                                layout_epoch["layout_fingerprint_sha256"]
                            )
                            db.execute(
                                "INSERT INTO automatic_sequence_state("
                                "job_id,state,layout_epoch,layout_fingerprint_sha256,"
                                "revision,enabled_by,enabled_at,updated_at) "
                                "VALUES(?,'disabled',?,?,1,NULL,NULL,?)",
                                (
                                    job_id,
                                    layout_epoch["epoch_number"],
                                    fingerprint,
                                    consumed_at,
                                ),
                            )
                            if authorize_automatic_formatting:
                                format_cassettes = db.execute(
                                    "SELECT sequence,physical_label,reuse_registered "
                                    "FROM automatic_cassettes WHERE job_id=? "
                                    "AND operation='format' ORDER BY sequence",
                                    (job_id,),
                                ).fetchall()
                                for cassette in format_cassettes:
                                    authority_payload = {
                                        "cassette_sequence": int(cassette["sequence"]),
                                        "expected_label": str(cassette["physical_label"]),
                                        "expected_operation": "format",
                                        "job_id": job_id,
                                        "layout_epoch": int(layout_epoch["epoch_number"]),
                                        "layout_fingerprint_sha256": fingerprint,
                                        "reuse_registered": int(cassette["reuse_registered"]),
                                    }
                                    authorization_id = hashlib.sha256(
                                        json.dumps(
                                            authority_payload,
                                            ensure_ascii=False,
                                            separators=(",", ":"),
                                            sort_keys=True,
                                        ).encode("utf-8")
                                    ).hexdigest()
                                    db.execute(
                                        "INSERT INTO automatic_format_authorizations("
                                        "authorization_id,job_id,cassette_sequence,layout_epoch,"
                                        "layout_fingerprint_sha256,expected_label,expected_operation,"
                                        "reuse_registered,authorized_by,authorized_at,request_sha256) "
                                        "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                                        (
                                            authorization_id,
                                            job_id,
                                            cassette["sequence"],
                                            layout_epoch["epoch_number"],
                                            fingerprint,
                                            cassette["physical_label"],
                                            "format",
                                            cassette["reuse_registered"],
                                            actor,
                                            consumed_at,
                                            request_sha256,
                                        ),
                                    )
                        has_policy = (
                            db.execute(
                                "SELECT 1 FROM sqlite_master WHERE type='table' "
                                "AND name='job_plan_policy_snapshots'"
                            ).fetchone()
                            is not None
                        )
                        plan_policy = (
                            db.execute(
                                "SELECT * FROM job_plan_policy_snapshots "
                                "WHERE plan_id=?",
                                (plan_id,),
                            ).fetchone()
                            if has_policy
                            else None
                        )
                        if plan_policy is not None:
                            current_settings = db.execute(
                                "SELECT * FROM application_settings WHERE singleton=1"
                            ).fetchone()
                            if current_settings is None:
                                raise CatalogError("application_settings_uninitialized")
                            try:
                                job_policy = json.loads(plan_policy["policy_json"])
                            except (TypeError, ValueError) as exc:
                                raise CatalogError(
                                    "invalid job plan policy snapshot"
                                ) from exc
                            if not isinstance(job_policy, dict):
                                raise CatalogError("invalid job plan policy snapshot")
                            job_policy.update(
                                {
                                    "content_verification_policy": current_settings[
                                        "content_verification_policy"
                                    ],
                                    "job_settings_revision": int(
                                        current_settings["revision"]
                                    ),
                                }
                            )
                            encoded_job_policy = json.dumps(
                                job_policy,
                                ensure_ascii=False,
                                separators=(",", ":"),
                                sort_keys=True,
                            )
                            db.execute(
                                "INSERT INTO job_policy_snapshots("
                                "job_id,plan_id,settings_revision,policy_json,"
                                "policy_sha256,created_at) VALUES(?,?,?,?,?,?)",
                                (
                                    job_id,
                                    plan_id,
                                    int(current_settings["revision"]),
                                    encoded_job_policy,
                                    hashlib.sha256(
                                        encoded_job_policy.encode("utf-8")
                                    ).hexdigest(),
                                    consumed_at,
                                ),
                            )
                        if plan_share_evidence:
                            db.execute(
                                "INSERT INTO automatic_cassette_share_evidence_sets("
                                "job_id,cassette_sequence,creation_plan_id,admitted_at) "
                                "SELECT ?,sequence,?,? FROM automatic_cassettes "
                                "WHERE job_id=?",
                                (job_id, plan_id, consumed_at, job_id),
                            )
                        for row in plan_share_evidence:
                            db.execute(
                                "INSERT INTO automatic_job_share_evidence("
                                "job_id,library_id,creation_plan_id,share_id,"
                                "evidence_json,evidence_sha256,admitted_at) "
                                "VALUES(?,?,?,?,?,?,?)",
                                (
                                    job_id,
                                    row["library_id"],
                                    plan_id,
                                    row["share_id"],
                                    row["evidence_json"],
                                    row["evidence_sha256"],
                                    consumed_at,
                                ),
                            )
                            db.execute(
                                "INSERT INTO automatic_cassette_share_evidence("
                                "job_id,cassette_sequence,library_id,creation_plan_id,"
                                "share_id,evidence_json,evidence_sha256,admitted_at) "
                                "SELECT ?,cassette.sequence,?,?,?, ?,?,? "
                                "FROM automatic_cassettes AS cassette "
                                "WHERE cassette.job_id=? AND EXISTS("
                                "SELECT 1 FROM automatic_cassette_items AS item "
                                "WHERE item.job_id=cassette.job_id "
                                "AND item.sequence=cassette.sequence "
                                "AND item.library_id=? COLLATE NOCASE)",
                                (
                                    job_id,
                                    row["library_id"],
                                    plan_id,
                                    row["share_id"],
                                    row["evidence_json"],
                                    row["evidence_sha256"],
                                    consumed_at,
                                    job_id,
                                    row["library_id"],
                                ),
                            )
                            db.execute(
                                "DELETE FROM managed_source_leases WHERE lease_id=?",
                                (lease_mapping[str(row["library_id"]).casefold()],),
                            )
                        if has_management_state:
                            self._job_history_tx(
                                db,
                                job_id,
                                actor,
                                "job.created",
                                "saved",
                                {"plan_id": plan_id},
                                occurred_at=consumed_at,
                            )
                        self._event(
                            db,
                            "job_plan.consume",
                            {
                                "plan_id": plan_id,
                                "job_id": job_id,
                                "labels": list(normalized_labels),
                            },
                        )
                        self.record_audit(
                            actor,
                            "job.create",
                            "accepted",
                            f"request-{uuid.uuid4().hex}",
                            None,
                            {"job_id": job_id, "plan_id": plan_id},
                        )
                        outcome = (job_id, False)
        except sqlite3.IntegrityError as exc:
            raise CatalogError("plan_consumption_conflict") from exc
        if deferred_error is not None:
            raise CatalogError(deferred_error)
        assert outcome is not None
        return outcome

    def consume_extension_plan(
        self,
        *,
        plan_id: str,
        digest_sha256: str,
        labels: Sequence[str],
        idempotency_key: str,
        request_sha256: str,
        job_id: str,
        consumed_at: str,
        expected_revision: int,
        managed_source_leases: Mapping[str, str] | None = None,
        actor: str = "system",
        authorize_automatic_formatting: bool = False,
    ) -> None:
        """Atomically apply one frozen extension without repacking old assignments."""

        validate_id(plan_id, "plan ID")
        validate_id(job_id, "job ID")
        self._validate_sha256(digest_sha256, "job plan digest")
        self._validate_safe_identifier(idempotency_key, "idempotency key")
        self._validate_sha256(request_sha256, "job extension request digest")
        normalized_labels = tuple(str(label).strip().upper() for label in labels)
        if (
            len(normalized_labels) > 64
            or len(set(normalized_labels)) != len(normalized_labels)
            or any(
                not re.fullmatch(r"[A-Z0-9]{6}", label) for label in normalized_labels
            )
        ):
            raise ValidationError("invalid physical cassette labels")
        if self._parse_utc_timestamp(consumed_at) is None:
            raise ValidationError("invalid job extension consumption time")
        self._validate_safe_identifier(actor, "authorization actor")
        if type(authorize_automatic_formatting) is not bool:
            raise ValidationError("invalid automatic formatting authority")

        with self.transaction() as db:
            draft = db.execute(
                "SELECT * FROM job_plan_drafts WHERE id=?", (plan_id,)
            ).fetchone()
            if draft is None:
                raise CatalogError("plan_not_found")
            if draft["creator"] == "boundary-coordinator":
                raise CatalogError("boundary_plan_reserved")
            if draft["digest_sha256"] != digest_sha256:
                raise CatalogError("plan_digest_mismatch")
            if draft["state"] == "consumed":
                if (
                    draft["consumed_job_id"] == job_id
                    and draft["consumption_key"] == idempotency_key
                    and draft["consumption_request_sha256"] == request_sha256
                ):
                    return
                raise CatalogError("plan_consumed")
            if draft["state"] != "ready" or draft["kind"] != "extend":
                raise CatalogError(f"plan_{draft['state']}")
            if draft["expires_at"] <= consumed_at:
                db.execute(
                    "UPDATE job_plan_drafts SET state='expired',updated_at=? WHERE id=?",
                    (consumed_at, plan_id),
                )
                raise CatalogError("plan_expired")
            if draft["base_job_id"] != job_id:
                raise CatalogError("job_extension_base_mismatch")
            evidence = self.job_extension_evidence(job_id)
            pending_extension = db.execute(
                "SELECT * FROM job_incremental_pending_extensions WHERE job_id=?",
                (job_id,),
            ).fetchone()
            current_epoch = db.execute(
                "SELECT epoch_number,layout_fingerprint_sha256 "
                "FROM job_layout_epochs WHERE job_id=? "
                "ORDER BY epoch_number DESC LIMIT 1",
                (job_id,),
            ).fetchone()
            waiting_reserve_only = (
                pending_extension is not None
                and current_epoch is not None
                and str(pending_extension["plan_id"]) == plan_id
                and str(pending_extension["plan_digest_sha256"]) == digest_sha256
                and int(pending_extension["base_epoch_number"])
                == int(current_epoch["epoch_number"])
                and str(pending_extension["base_layout_fingerprint"])
                == str(current_epoch["layout_fingerprint_sha256"])
            )
            if evidence["retired"] or evidence["imported"]:
                raise CatalogError(
                    "job_imported_frozen" if evidence["imported"] else "job_retired"
                )
            if (
                expected_revision is not None
                and int(evidence["revision"]) != expected_revision
            ):
                raise CatalogError("job_revision_conflict")
            if (
                evidence["revision"] != draft["base_job_revision"]
                or evidence["fingerprint_sha256"]
                != draft["base_job_fingerprint_sha256"]
            ) and not waiting_reserve_only:
                raise CatalogError("job_extension_stale")
            plan_libraries = [
                str(row["library_id"])
                for row in db.execute(
                    "SELECT library_id FROM job_plan_libraries "
                    "WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                )
            ]
            if (
                plan_libraries != evidence["libraries"]
                or draft["media_key"] != evidence["media_key"]
            ):
                raise CatalogError("job_extension_identity_changed")
            plan_share_evidence = db.execute(
                "SELECT * FROM job_plan_share_evidence WHERE plan_id=? "
                "ORDER BY library_id COLLATE NOCASE",
                (plan_id,),
            ).fetchall()
            managed_plan_libraries = {
                str(row["library_id"]).casefold()
                for row in db.execute(
                    "SELECT plan_library.library_id "
                    "FROM job_plan_libraries AS plan_library "
                    "JOIN libraries AS library ON library.id=plan_library.library_id "
                    "WHERE plan_library.plan_id=? AND library.source_kind='network'",
                    (plan_id,),
                )
            }
            evidence_by_library = {
                str(row["library_id"]).casefold(): row for row in plan_share_evidence
            }
            lease_mapping = dict(managed_source_leases or {})
            if managed_plan_libraries != set(evidence_by_library) or set(
                evidence_by_library
            ) != set(lease_mapping):
                raise CatalogError("managed_source_evidence_changed")
            for library_key, share_evidence in evidence_by_library.items():
                lease = db.execute(
                    "SELECT * FROM managed_source_leases WHERE lease_id=? "
                    "AND consumer_kind='save'",
                    (lease_mapping[library_key],),
                ).fetchone()
                current_evidence = json.loads(str(share_evidence["evidence_json"]))
                if (
                    lease is None
                    or str(lease["share_id"]).casefold()
                    != str(share_evidence["share_id"]).casefold()
                    or not self._managed_source_evidence_matches_share_tx(
                        db, current_evidence
                    )
                ):
                    raise CatalogError("managed_source_evidence_changed")
            plan_cassettes = list(
                db.execute(
                    "SELECT * FROM job_plan_cassettes WHERE plan_id=? ORDER BY sequence",
                    (plan_id,),
                )
            )
            append_targets = [
                row
                for row in reversed(evidence["cassettes"])
                if row["status"] == "completed" and row["tape_id"] is not None
            ]
            reserve_targets = [
                row
                for row in evidence["cassettes"]
                if row["status"] == "pending"
                and row["planned_files"] == 0
                and row["planned_bytes"] == 0
            ]
            format_count = sum(row["operation"] == "format" for row in plan_cassettes)
            originally_bound_reserves = sum(
                row["operation"] == "reserve" for row in plan_cassettes
            )
            extra_reserves = max(0, len(reserve_targets) - originally_bound_reserves)
            required_labels = max(0, format_count - extra_reserves)
            if len(normalized_labels) != required_labels:
                raise CatalogError("plan_labels_inexact")
            if sum(row["operation"] == "append" for row in plan_cassettes) > 1:
                raise CatalogError("job_extension_invalid_append")
            if self._extension_requires_automatic_format_authorization_tx(
                db, job_id, (str(row["operation"]) for row in plan_cassettes)
            ) and not authorize_automatic_formatting:
                raise CatalogError("automatic_format_authorization_required")
            for label in normalized_labels:
                assigned = db.execute(
                    "SELECT cassette.job_id FROM automatic_cassettes cassette "
                    "JOIN job_management_state state ON state.job_id=cassette.job_id "
                    "JOIN automatic_jobs job ON job.id=cassette.job_id "
                    "WHERE cassette.physical_label=? COLLATE NOCASE "
                    "AND state.retired_at IS NULL "
                    "AND job.status NOT IN ('completed','failed') LIMIT 1",
                    (label,),
                ).fetchone()
                registered = db.execute(
                    "SELECT 1 FROM tapes WHERE cassette_number=? COLLATE NOCASE "
                    "OR id=? COLLATE NOCASE LIMIT 1",
                    (label, label),
                ).fetchone()
                if assigned is not None:
                    raise CatalogError("job_label_unavailable")
                if registered is not None:
                    raise CatalogError("job_label_registered")

            next_new_sequence = int(
                db.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM automatic_cassettes "
                    "WHERE job_id=?",
                    (job_id,),
                ).fetchone()[0]
            )
            first_new_sequence: int | None = None
            reserve_index = 0
            label_index = 0
            target_sequences: list[int] = []
            for planned in plan_cassettes:
                operation = str(planned["operation"])
                if operation == "append":
                    if not append_targets:
                        raise CatalogError("job_extension_append_target_changed")
                    prior_target = append_targets[0]
                    prior_cassette = db.execute(
                        "SELECT tape_serial FROM automatic_cassettes "
                        "WHERE job_id=? AND sequence=?",
                        (job_id, int(prior_target["sequence"])),
                    ).fetchone()
                    if prior_cassette is None:
                        raise CatalogError("job_extension_append_target_changed")
                    target_sequence = next_new_sequence
                    next_new_sequence += 1
                    if first_new_sequence is None:
                        first_new_sequence = target_sequence
                    db.execute(
                        "INSERT INTO automatic_cassettes("
                        "job_id,sequence,physical_label,tape_serial,status,tape_id,"
                        "planned_files,planned_bytes,operation,reuse_registered) "
                        "VALUES(?,?,?,?,'pending',?,?,?,'append',1)",
                        (
                            job_id,
                            target_sequence,
                            prior_target["physical_label"],
                            prior_cassette["tape_serial"],
                            prior_target["tape_id"],
                            int(planned["objects"]),
                            int(planned["payload_bytes"]),
                        ),
                    )
                elif operation == "reserve":
                    if reserve_index >= len(reserve_targets):
                        raise CatalogError("job_extension_reserve_target_changed")
                    target_sequence = int(reserve_targets[reserve_index]["sequence"])
                    reserve_index += 1
                    db.execute(
                        "UPDATE automatic_cassettes SET status='pending',planned_files=?,"
                        "planned_bytes=?,copied_files=0,copied_bytes=0,operation='format',"
                        "started_at=NULL,completed_at=NULL,error=NULL "
                        "WHERE job_id=? AND sequence=?",
                        (
                            int(planned["objects"]),
                            int(planned["payload_bytes"]),
                            job_id,
                            target_sequence,
                        ),
                    )
                else:
                    if reserve_index < len(reserve_targets):
                        target_sequence = int(reserve_targets[reserve_index]["sequence"])
                        reserve_index += 1
                        db.execute(
                            "UPDATE automatic_cassettes SET status='pending',planned_files=?,"
                            "planned_bytes=?,copied_files=0,copied_bytes=0,operation='format',"
                            "started_at=NULL,completed_at=NULL,error=NULL "
                            "WHERE job_id=? AND sequence=?",
                            (int(planned["objects"]), int(planned["payload_bytes"]), job_id, target_sequence),
                        )
                    else:
                        target_sequence = next_new_sequence
                        next_new_sequence += 1
                        if first_new_sequence is None:
                            first_new_sequence = target_sequence
                        label = normalized_labels[label_index]
                        label_index += 1
                        db.execute(
                            "INSERT INTO cartridges(physical_label,first_seen_at) VALUES(?,?)",
                            (label, consumed_at),
                        )
                        db.execute(
                            "INSERT INTO automatic_cassettes("
                            "job_id,sequence,physical_label,tape_serial,status,planned_files,"
                            "planned_bytes,operation,reuse_registered) "
                            "VALUES(?,?,?,?,'pending',?,?,'format',0)",
                            (job_id,target_sequence,label,label,int(planned["objects"]),int(planned["payload_bytes"])),
                        )
                target_sequences.append(target_sequence)
                items = list(
                    db.execute(
                        "SELECT * FROM job_plan_items WHERE plan_id=? "
                        "AND cassette_sequence=? ORDER BY item_sequence",
                        (plan_id, int(planned["sequence"])),
                    )
                )
                db.executemany(
                    "INSERT INTO automatic_cassette_items("
                    "job_id,sequence,item_sequence,library_id,relative_path,"
                    "tape_relative_path,size,mtime_ns) VALUES(?,?,?,?,?,?,?,?)",
                    [
                        (
                            job_id,
                            target_sequence,
                            int(item["item_sequence"]),
                            item["library_id"],
                            item["relative_path"],
                            item["tape_relative_path"],
                            int(item["size"]),
                            int(item["mtime_ns"]),
                        )
                        for item in items
                    ],
                )
                item_library_ids = {
                    str(item["library_id"]).casefold() for item in items
                }
                if evidence_by_library:
                    db.execute(
                        "INSERT INTO automatic_cassette_share_evidence_sets("
                        "job_id,cassette_sequence,creation_plan_id,admitted_at) "
                        "VALUES(?,?,?,?)",
                        (job_id, target_sequence, plan_id, consumed_at),
                    )
                for library_key in sorted(item_library_ids & set(evidence_by_library)):
                    share_evidence = evidence_by_library[library_key]
                    db.execute(
                        "INSERT INTO automatic_cassette_share_evidence("
                        "job_id,cassette_sequence,library_id,creation_plan_id,"
                        "share_id,evidence_json,evidence_sha256,admitted_at) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        (
                            job_id,
                            target_sequence,
                            share_evidence["library_id"],
                            plan_id,
                            share_evidence["share_id"],
                            share_evidence["evidence_json"],
                            share_evidence["evidence_sha256"],
                            consumed_at,
                        ),
                    )

            db.execute(
                "UPDATE automatic_jobs SET status='planned',current_sequence=?,"
                "total_cassettes=(SELECT COUNT(*) FROM automatic_cassettes WHERE job_id=?),"
                "completed_at=NULL,last_error=NULL WHERE id=?",
                (min(target_sequences), job_id, job_id),
            )
            db.execute(
                "UPDATE job_management_state SET revision=revision+1,"
                "current_checkpoint='extended',updated_at=? WHERE job_id=?",
                (consumed_at, job_id),
            )
            db.execute(
                "UPDATE job_plan_drafts SET state='consumed',updated_at=?,consumed_at=?,"
                "consumed_job_id=?,consumption_key=?,consumption_request_sha256=? "
                "WHERE id=? AND state='ready'",
                (
                    consumed_at,
                    consumed_at,
                    job_id,
                    idempotency_key,
                    request_sha256,
                    plan_id,
                ),
            )
            db.execute(
                "INSERT INTO job_extension_commits("
                "plan_id,job_id,base_revision,committed_revision,first_new_sequence,committed_at) "
                "VALUES(?,?,?,?,?,?)",
                (
                    plan_id,
                    job_id,
                    int(evidence["revision"]),
                    int(evidence["revision"]) + 1,
                    first_new_sequence,
                    consumed_at,
                ),
            )
            epoch = self._insert_layout_epoch_tx(
                db,
                job_id,
                kind="extension",
                plan_id=plan_id,
                plan_digest_sha256=digest_sha256,
                created_at=consumed_at,
                target_sequences=tuple(target_sequences),
            )
            db.execute(
                "UPDATE job_incremental_pending_extensions SET base_epoch_number=?,"
                "base_layout_fingerprint=? WHERE job_id=?",
                (epoch["epoch_number"], epoch["layout_fingerprint_sha256"], job_id),
            )
            self._rebind_automatic_sequence_layout_tx(
                db, job_id, epoch, actor=actor, changed_at=consumed_at,
                request_sha256=request_sha256,
                authorize_automatic_formatting=authorize_automatic_formatting,
            )
            db.execute(
                "DELETE FROM job_incremental_pending_extensions WHERE job_id=?",
                (job_id,),
            )
            for lease_id in lease_mapping.values():
                db.execute(
                    "DELETE FROM managed_source_leases WHERE lease_id=?", (lease_id,)
                )

    def create_automatic_job(
        self,
        job_id: str,
        library_id: str,
        device_name: str,
        mount_path: str,
        cassettes: list[tuple[str, str, int, int]],
        library_ids: list[str] | None = None,
        force_format: bool = False,
        media_key: str = "LTO-6",
        allow_registered_reuse: bool = False,
    ) -> None:
        validate_id(job_id, "ID job")
        ordered_library_ids: list[str] = []
        seen_library_ids: set[str] = set()
        for candidate in [library_id, *(library_ids or [])]:
            if candidate.casefold() in seen_library_ids:
                continue
            self.get_library(candidate)
            ordered_library_ids.append(candidate)
            seen_library_ids.add(candidate.casefold())
        if not cassettes:
            raise ValidationError("Il job automatico richiede almeno una cassetta")
        now = utc_now()
        try:
            with self.transaction() as db:
                for selected_library_id in ordered_library_ids:
                    active_job = db.execute(
                        """
                        SELECT aj.id
                        FROM automatic_jobs aj
                        JOIN automatic_job_libraries ajl ON ajl.job_id=aj.id
                        WHERE ajl.library_id=? COLLATE NOCASE
                          AND aj.status NOT IN ('completed', 'failed')
                        LIMIT 1
                        """,
                        (selected_library_id,),
                    ).fetchone()
                    if active_job:
                        raise CatalogError(
                            f"La libreria {selected_library_id} ha gia il job non concluso "
                            f"{active_job['id']}"
                        )
                for physical_label, _serial, _files, _bytes in cassettes:
                    queued = db.execute(
                        """
                        SELECT ac.job_id
                        FROM automatic_cassettes ac
                        WHERE ac.physical_label=? COLLATE NOCASE
                          AND ac.status != 'completed'
                        LIMIT 1
                        """,
                        (physical_label,),
                    ).fetchone()
                    if queued:
                        raise CatalogError(
                            f"La cassetta {physical_label} e gia assegnata al job "
                            f"{queued['job_id']}"
                        )
                    registered = db.execute(
                        "SELECT id FROM tapes WHERE cassette_number=? COLLATE NOCASE OR id=? COLLATE NOCASE",
                        (physical_label, physical_label),
                    ).fetchone()
                    if registered and not allow_registered_reuse:
                        raise CatalogError(
                            f"La cassetta {physical_label} e gia registrata come {registered['id']}; "
                            "non viene riformattata per proteggere i backup catalogati"
                        )
                db.execute(
                    """
                    INSERT INTO automatic_jobs(
                        id, display_name, media_key, library_id, device_name, mount_path, status,
                        total_cassettes, destructive_confirmed_at, force_format, created_at
                    ) VALUES(?, ?, ?, ?, ?, ?, 'planned', ?, ?, ?, ?)
                    """,
                    (
                        job_id,
                        job_id,
                        media_key,
                        library_id,
                        device_name,
                        mount_path,
                        len(cassettes),
                        now,
                        int(force_format),
                        now,
                    ),
                )
                db.executemany(
                    """
                    INSERT INTO automatic_cassettes(
                        job_id, sequence, physical_label, tape_serial, status,
                        planned_files, planned_bytes, reuse_registered
                    ) VALUES(?, ?, ?, ?, 'pending', ?, ?, ?)
                    """,
                    [
                        (
                            job_id,
                            sequence,
                            physical_label,
                            tape_serial,
                            files,
                            size,
                            int(allow_registered_reuse),
                        )
                        for sequence, (
                            physical_label,
                            tape_serial,
                            files,
                            size,
                        ) in enumerate(cassettes, 1)
                    ],
                )
                if (
                    db.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' "
                        "AND name='job_management_state'"
                    ).fetchone()
                    is not None
                ):
                    db.execute(
                        "INSERT INTO job_management_state("
                        "job_id,revision,current_checkpoint,updated_at) "
                        "VALUES(?,0,'saved',?)",
                        (job_id, now),
                    )
                    self._job_history_tx(
                        db, job_id, "system", "job.created", "saved", {}
                    )
                db.executemany(
                    """
                    INSERT INTO automatic_job_libraries(job_id, library_id, sequence)
                    VALUES(?, ?, ?)
                    """,
                    [
                        (job_id, selected_library_id, sequence)
                        for sequence, selected_library_id in enumerate(
                            ordered_library_ids, 1
                        )
                    ],
                )
                if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='job_incremental_policies'"
                ).fetchone() is not None:
                    db.execute(
                        "INSERT INTO job_incremental_policies("
                        "job_id,cadence,revision,updated_at) VALUES(?,'off',1,?)",
                        (job_id, now),
                    )
                    self._insert_layout_epoch_tx(
                        db, job_id, kind="initial", plan_id=None,
                        plan_digest_sha256="0" * 64, created_at=now,
                    )
                self._event(
                    db,
                    "automatic_job.create",
                    {
                        "job_id": job_id,
                        "library_id": library_id,
                        "library_ids": ordered_library_ids,
                        "device_name": device_name,
                        "mount_path": mount_path,
                        "force_format": force_format,
                        "media_key": media_key,
                        "allow_registered_reuse": allow_registered_reuse,
                        "labels": [row[0] for row in cassettes],
                    },
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(
                f"Job automatico o etichetta duplicata: {job_id}"
            ) from exc

    def reset_and_create_native_job(
        self,
        fence: OperationFence,
        *,
        expected_job_id: str,
        job_id: str,
        display_name: str,
        source_roots: tuple[Path, ...],
        device_name: str,
        mount_path: str,
        labels: tuple[str, ...],
        application_settings: Mapping[str, Any] | None = None,
        planned_cassettes: tuple[
            tuple[int, int, int, tuple[tuple[str, str, int, int], ...]], ...
        ]
        | None = None,
    ) -> None:
        """Supersede one active job and create a fresh label-first namespace."""

        validate_id(expected_job_id, "ID job atteso")
        validate_id(job_id, "ID job")
        normalized_name = display_name.strip()
        if (
            not normalized_name
            or len(normalized_name) > 120
            or any(ord(character) < 32 for character in normalized_name)
        ):
            raise ValidationError("Il nome del job non e valido")
        normalized_roots = tuple(Path(root) for root in source_roots)
        if (
            not normalized_roots
            or len(set(map(str, normalized_roots))) != len(normalized_roots)
            or any(not root.is_absolute() for root in normalized_roots)
        ):
            raise ValidationError("Le sorgenti native non sono valide")
        normalized_labels = tuple(label.strip().upper() for label in labels)
        if (
            not normalized_labels
            or len(normalized_labels) > 64
            or len(set(normalized_labels)) != len(normalized_labels)
            or any(
                not re.fullmatch(r"[A-Z0-9]{6}", label) for label in normalized_labels
            )
        ):
            raise ValidationError("Le etichette fisiche non sono valide")
        native_policy: dict[str, Any] | None = None
        media_key = "LTO-6"
        if application_settings is not None:
            required_settings = {
                "revision",
                "capacity_reserve_bytes",
                "minimum_source_file_age_seconds",
                "copy_buffer_bytes",
                "content_verification_policy",
                "default_media_profile",
                "tape_root_directory",
                "legacy_tape_capacity_bytes",
                "legacy_source_sha256",
            }
            if set(application_settings) not in (
                required_settings,
                required_settings | {"source_change_detection_policy"},
            ):
                raise ValidationError("invalid native application settings snapshot")
            profile = require_ltfs_profile(
                application_settings["default_media_profile"]
            )
            if profile.ltfs_usable_bytes is None:
                raise ValidationError("native media profile is not LTFS compatible")
            policy = application_settings["content_verification_policy"]
            revision = application_settings["revision"]
            source_policy = application_settings.get(
                "source_change_detection_policy", "size_mtime"
            )
            if (
                policy not in {"none", "manifest", "full"}
                or type(revision) is not int
                or source_policy not in {"size_mtime", "size_mtime_change"}
            ):
                raise ValidationError("invalid native application settings snapshot")
            settings = Settings(
                reserve_bytes=application_settings["capacity_reserve_bytes"],
                tape_capacity_bytes=profile.ltfs_usable_bytes,
                buffer_bytes=application_settings["copy_buffer_bytes"],
                min_age_seconds=application_settings["minimum_source_file_age_seconds"],
                tape_root_directory=application_settings["tape_root_directory"],
                verify_unchanged_content=policy == "full",
                default_media_key=profile.key,
            )
            settings.validate()
            media_key = profile.key
            native_policy = {
                "capacity_reserve_bytes": settings.reserve_bytes,
                "content_verification_policy": policy,
                "default_media_profile": profile.key,
                "job_settings_revision": revision,
                "minimum_source_file_age_seconds": settings.min_age_seconds,
                "selected_media_profile": profile.key,
                "settings_revision": revision,
                "tape_root_directory": settings.tape_root_directory,
            }
            if "source_change_detection_policy" in application_settings:
                native_policy["source_change_detection_policy"] = source_policy
        now = utc_now()
        library_ids = tuple(
            f"{job_id}-L{index:02d}" for index in range(1, len(normalized_roots) + 1)
        )
        normalized_plan = None
        if planned_cassettes is not None:
            if len(planned_cassettes) != len(normalized_labels):
                raise ValidationError("Il piano nativo non copre tutte le cassette")
            known_libraries = {library_id.casefold() for library_id in library_ids}
            seen_items: set[tuple[str, str]] = set()
            normalized_rows = []
            for expected_sequence, row in enumerate(planned_cassettes, 1):
                sequence, planned_files, planned_bytes, items = row
                normalized_items = []
                if sequence != expected_sequence:
                    raise ValidationError(
                        "Le sequenze del piano nativo non sono contigue"
                    )
                for library_id, relative_path, size, mtime_ns in items:
                    path = str(PurePosixPath(relative_path.replace("\\", "/"))).strip(
                        "/"
                    )
                    key = (library_id.casefold(), path.casefold())
                    if (
                        library_id.casefold() not in known_libraries
                        or not path
                        or path == "."
                        or PurePosixPath(path).is_absolute()
                        or key in seen_items
                        or int(size) < 0
                        or int(mtime_ns) < 0
                    ):
                        raise ValidationError(
                            "Il manifest del piano nativo non e valido"
                        )
                    seen_items.add(key)
                    normalized_items.append(
                        (library_id, path, int(size), int(mtime_ns))
                    )
                if int(planned_files) != len(normalized_items) or int(
                    planned_bytes
                ) != sum(item[2] for item in normalized_items):
                    raise ValidationError(
                        "Il manifest non coincide con il piano nativo"
                    )
                normalized_rows.append(
                    (
                        sequence,
                        int(planned_files),
                        int(planned_bytes),
                        tuple(normalized_items),
                    )
                )
            if not any(row[1] > 0 for row in normalized_rows):
                raise ValidationError("Il piano nativo non contiene file")
            normalized_plan = tuple(normalized_rows)
        try:
            with self.transaction() as db:
                self._assert_operation_fence_tx(db, fence)
                active = db.execute(
                    "SELECT id FROM automatic_jobs "
                    "WHERE status NOT IN ('completed','failed') ORDER BY created_at"
                ).fetchall()
                if len(active) != 1 or active[0]["id"] != expected_job_id:
                    raise CatalogError(
                        "Il job da sostituire non coincide con lo stato corrente"
                    )
                db.execute(
                    "UPDATE automatic_cassettes SET status='failed',error=? "
                    "WHERE job_id=? AND status!='completed'",
                    ("Sostituita dal reset logico del backup", expected_job_id),
                )
                db.execute(
                    "UPDATE automatic_jobs SET status='failed',completed_at=?,last_error=? "
                    "WHERE id=?",
                    (now, "Sostituito dal reset logico del backup", expected_job_id),
                )
                if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='job_incremental_policies'"
                ).fetchone():
                    db.execute(
                        "UPDATE job_incremental_policies SET cadence='off',"
                        "next_eligible_at=NULL,updated_at=? WHERE job_id=?",
                        (now, expected_job_id),
                    )
                db.execute(
                    "UPDATE libraries SET status='retired',retired_at=? "
                    "WHERE status='active'",
                    (now,),
                )
                db.executemany(
                    "INSERT INTO libraries(id,name,source_root,status,created_at) "
                    "VALUES(?,?,?,'active',?)",
                    [
                        (
                            library_id,
                            root.name or f"Sorgente {index}",
                            str(root),
                            now,
                        )
                        for index, (library_id, root) in enumerate(
                            zip(library_ids, normalized_roots, strict=True), 1
                        )
                    ],
                )
                db.execute(
                    "INSERT INTO automatic_jobs("
                    "id,display_name,media_key,library_id,device_name,mount_path,status,"
                    "current_sequence,total_cassettes,destructive_confirmed_at,"
                    "force_format,created_at) VALUES(?,?,?,?,?,?,'planned',0,?,?,1,?)",
                    (
                        job_id,
                        normalized_name,
                        media_key,
                        library_ids[0],
                        device_name,
                        mount_path,
                        len(normalized_labels),
                        now,
                        now,
                    ),
                )
                db.execute(
                    "INSERT INTO job_management_state("
                    "job_id,revision,current_checkpoint,updated_at) "
                    "VALUES(?,0,'saved',?)",
                    (job_id, now),
                )
                if native_policy is not None:
                    encoded_policy = json.dumps(
                        native_policy,
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    )
                    db.execute(
                        "INSERT INTO job_policy_snapshots("
                        "job_id,plan_id,settings_revision,policy_json,"
                        "policy_sha256,created_at) VALUES(?,NULL,?,?,?,?)",
                        (
                            job_id,
                            native_policy["settings_revision"],
                            encoded_policy,
                            hashlib.sha256(encoded_policy.encode("utf-8")).hexdigest(),
                            now,
                        ),
                    )
                db.execute(
                    "UPDATE job_management_state SET current_checkpoint='failed',"
                    "updated_at=? WHERE job_id=?",
                    (now, expected_job_id),
                )
                db.executemany(
                    "INSERT INTO automatic_cassettes("
                    "job_id,sequence,physical_label,tape_serial,status,planned_files,"
                    "planned_bytes,operation,reuse_registered) "
                    "VALUES(?,?,?,?,'pending',0,0,'format',?)",
                    [
                        (
                            job_id,
                            sequence,
                            label,
                            label,
                            int(
                                db.execute(
                                    "SELECT 1 FROM tapes WHERE "
                                    "cassette_number=? COLLATE NOCASE OR id=? COLLATE NOCASE",
                                    (label, label),
                                ).fetchone()
                                is not None
                            ),
                        )
                        for sequence, label in enumerate(normalized_labels, 1)
                    ],
                )
                db.executemany(
                    "INSERT INTO automatic_job_libraries(job_id,library_id,sequence) "
                    "VALUES(?,?,?)",
                    [
                        (job_id, library_id, sequence)
                        for sequence, library_id in enumerate(library_ids, 1)
                    ],
                )
                if normalized_plan is not None:
                    db.executemany(
                        "UPDATE automatic_cassettes SET planned_files=?,planned_bytes=? "
                        "WHERE job_id=? AND sequence=?",
                        [
                            (planned_files, planned_bytes, job_id, sequence)
                            for sequence, planned_files, planned_bytes, _items in normalized_plan
                        ],
                    )
                    first_sequence = next(
                        sequence
                        for sequence, planned_files, _planned_bytes, _items in normalized_plan
                        if planned_files > 0
                    )
                    db.execute(
                        "UPDATE automatic_jobs SET current_sequence=? WHERE id=?",
                        (first_sequence, job_id),
                    )
                    db.executemany(
                        "INSERT INTO automatic_cassette_items("
                        "job_id,sequence,item_sequence,library_id,relative_path,"
                        "tape_relative_path,size,mtime_ns) VALUES(?,?,?,?,?,?,?,?)",
                        [
                            (
                                job_id,
                                sequence,
                                item_sequence,
                                library_id,
                                relative_path,
                                ltfs_tape_relative_path(relative_path),
                                size,
                                mtime_ns,
                            )
                            for sequence, _files, _bytes, items in normalized_plan
                            for item_sequence, (
                                library_id,
                                relative_path,
                                size,
                                mtime_ns,
                            ) in enumerate(items, 1)
                        ],
                    )
                if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='job_incremental_policies'"
                ).fetchone() is not None:
                    db.execute(
                        "INSERT INTO job_incremental_policies("
                        "job_id,cadence,revision,updated_at) VALUES(?,'off',1,?)",
                        (job_id, now),
                    )
                    self._insert_layout_epoch_tx(
                        db,
                        job_id,
                        kind="initial",
                        plan_id=None,
                        plan_digest_sha256="0" * 64,
                        created_at=now,
                    )
                self._event(
                    db,
                    "automatic_job.native_reset_create",
                    {
                        "superseded_job_id": expected_job_id,
                        "job_id": job_id,
                        "library_ids": library_ids,
                        "labels": normalized_labels,
                        "media_key": media_key,
                    },
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(
                "Il reset logico del backup non e stato applicato"
            ) from exc

    def get_automatic_job(self, job_id: str) -> sqlite3.Row:
        row = self.connection.execute(
            "SELECT * FROM automatic_jobs WHERE id=? AND NOT EXISTS("
            "SELECT 1 FROM deleted_automatic_job_tombstones AS deleted "
            "WHERE deleted.job_id=automatic_jobs.id COLLATE NOCASE)",
            (job_id,),
        ).fetchone()
        if row is None:
            raise CatalogError(f"Job automatico non trovato: {job_id}")
        return row

    def current_job_id(self) -> str | None:
        row = self.connection.execute(
            "SELECT current_job_id FROM job_execution_state WHERE singleton=1"
        ).fetchone()
        if row is None or row["current_job_id"] is None:
            return None
        return str(row["current_job_id"])

    def set_current_job_id(
        self, job_id: str | None, *, actor: str = "system"
    ) -> str | None:
        now = utc_now()
        with self.transaction() as db:
            if job_id is not None:
                job = db.execute(
                    "SELECT job.id,job.status,state.retired_at "
                    "FROM automatic_jobs job JOIN job_management_state state "
                    "ON state.job_id=job.id WHERE job.id=?",
                    (job_id,),
                ).fetchone()
                if (
                    job is None
                    or job["retired_at"] is not None
                    or job["status"] in {"completed"}
                ):
                    raise CatalogError("job_not_resumable")
                job_id = str(job["id"])
            db.execute(
                "INSERT INTO job_execution_state(singleton,current_job_id,updated_at) "
                "VALUES(1,?,?) ON CONFLICT(singleton) DO UPDATE SET "
                "current_job_id=excluded.current_job_id,updated_at=excluded.updated_at",
                (job_id, now),
            )
            if job_id is not None:
                checkpoint = self._job_management_state_tx(db, job_id)[
                    "current_checkpoint"
                ]
                self._job_history_tx(
                    db,
                    job_id,
                    actor,
                    "job.selected",
                    str(checkpoint),
                    {},
                    occurred_at=now,
                )
        return job_id

    def job_management_state(self, job_id: str) -> dict[str, Any]:
        row = self.connection.execute(
            "SELECT * FROM job_management_state WHERE job_id=?", (job_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("job_not_found")
        return dict(row)

    @staticmethod
    def _layout_payload_tx(
        db: sqlite3.Connection,
        job_id: str,
        *, epoch_number: int,
        plan_id: str | None,
        plan_digest_sha256: str,
        prior_epoch_sha256: str | None,
    ) -> tuple[str, str]:
        cassettes = []
        for row in db.execute(
            "SELECT sequence,physical_label,operation,tape_id,planned_files,planned_bytes "
            "FROM automatic_cassettes WHERE job_id=? AND (planned_files>0 OR planned_bytes>0) ORDER BY sequence",
            (job_id,),
        ):
            sequence = int(row["sequence"])
            current = [dict(item) for item in db.execute(
                "SELECT item_sequence,library_id,relative_path,tape_relative_path,size,mtime_ns "
                "FROM automatic_cassette_items "
                "WHERE job_id=? AND sequence=? ORDER BY item_sequence", (job_id, sequence)
            )]
            history = [dict(item) for item in db.execute(
                "SELECT revision,item_sequence,library_id,relative_path,tape_relative_path,"
                "size,mtime_ns FROM job_manifest_history "
                "WHERE job_id=? AND cassette_sequence=? ORDER BY revision,item_sequence", (job_id, sequence)
            )]
            blocks = [] if row["tape_id"] is None else [dict(block) for block in db.execute(
                "SELECT id AS block_id FROM blocks WHERE tape_id=? "
                "AND status='completed' ORDER BY id", (row["tape_id"],)
            )]
            cassettes.append({
                "blocks": blocks,"historical_items": history,"items": current,
                "operation": str(row["operation"]),"physical_label": str(row["physical_label"]),
                "planned_bytes": int(row["planned_bytes"]),"planned_files": int(row["planned_files"]),
                "sequence": sequence,"tape_id": None if row["tape_id"] is None else str(row["tape_id"]),
            })
        prior_targets = []
        for target in db.execute(
            "SELECT epoch_number,plan_sequence,target_sequence,physical_label,operation,"
            "segment_id,canonical_json FROM job_layout_targets WHERE job_id=? "
            "ORDER BY epoch_number,plan_sequence", (job_id,)
        ):
            target_value = dict(target)
            target_value["blocks"] = [dict(binding) for binding in db.execute(
                "SELECT operation_id,block_id,created_at FROM job_layout_target_blocks "
                "WHERE job_id=? AND epoch_number=? AND plan_sequence=? ORDER BY block_id",
                (job_id, target["epoch_number"], target["plan_sequence"]),
            )]
            prior_targets.append(target_value)
        payload = {"cassettes": cassettes,"epoch_number": epoch_number,"job_id": job_id,
                   "plan_digest_sha256": plan_digest_sha256,"plan_id": plan_id,
                   "prior_epoch_sha256": prior_epoch_sha256,
                   "prior_targets": prior_targets}
        canonical = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return canonical, hashlib.sha256(canonical.encode()).hexdigest()

    def _insert_layout_epoch_tx(
        self, db: sqlite3.Connection, job_id: str, *, kind: Literal["initial", "extension"],
        plan_id: str | None, plan_digest_sha256: str, created_at: str,
        target_sequences: Sequence[int] | None = None,
        target_operations: Sequence[str] | None = None,
    ) -> sqlite3.Row:
        prior = db.execute(
            "SELECT epoch_number,layout_fingerprint_sha256 FROM job_layout_epochs "
            "WHERE job_id=? ORDER BY epoch_number DESC LIMIT 1", (job_id,)
        ).fetchone()
        number = 1 if prior is None else int(prior["epoch_number"]) + 1
        prior_sha = None if prior is None else str(prior["layout_fingerprint_sha256"])
        canonical, fingerprint = self._layout_payload_tx(
            db, job_id, epoch_number=number, plan_id=plan_id,
            plan_digest_sha256=plan_digest_sha256, prior_epoch_sha256=prior_sha,
        )
        db.execute(
            "INSERT INTO job_layout_epochs(job_id,epoch_number,kind,plan_id,plan_digest_sha256,"
            "prior_epoch_sha256,layout_fingerprint_sha256,canonical_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)",
            (job_id, number, kind, plan_id, plan_digest_sha256, prior_sha, fingerprint, canonical, created_at),
        )
        if kind == "initial":
            targets = [(int(r["sequence"]), int(r["sequence"]), str(r["physical_label"]), str(r["operation"]))
                       for r in db.execute("SELECT sequence,physical_label,operation FROM automatic_cassettes "
                                           "WHERE job_id=? AND (planned_files>0 OR planned_bytes>0) ORDER BY sequence", (job_id,))]
        else:
            plans = db.execute("SELECT sequence,operation FROM job_plan_cassettes WHERE plan_id=? ORDER BY sequence", (plan_id,)).fetchall()
            if not plans and target_operations is not None:
                plans = tuple(
                    {"sequence": index, "operation": operation}
                    for index, operation in enumerate(target_operations, 1)
                )
            sequences = tuple(target_sequences or ())
            if len(plans) != len(sequences):
                raise CatalogError("layout_target_mapping_incomplete")
            targets = []
            for planned, sequence in zip(plans, sequences):
                cassette = db.execute(
                    "SELECT physical_label,operation FROM automatic_cassettes "
                    "WHERE job_id=? AND sequence=?",
                    (job_id, sequence),
                ).fetchone()
                if cassette is None:
                    raise CatalogError("layout_target_mapping_incomplete")
                targets.append(
                    (
                        int(planned["sequence"]),
                        int(sequence),
                        str(cassette["physical_label"]),
                        str(cassette["operation"]),
                    )
                )
        for plan_sequence, target_sequence, label, operation in targets:
            value = {"epoch_number": number,"job_id": job_id,"operation": operation,
                     "physical_label": label,"plan_sequence": plan_sequence,"target_sequence": target_sequence}
            encoded = json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
            segment = hashlib.sha256((fingerprint + "\0" + encoded).encode()).hexdigest()
            db.execute("INSERT INTO job_layout_targets(job_id,epoch_number,target_sequence,plan_sequence,"
                       "physical_label,operation,segment_id,canonical_json) VALUES(?,?,?,?,?,?,?,?)",
                       (job_id, number, target_sequence, plan_sequence, label, operation, segment, encoded))
        return db.execute("SELECT * FROM job_layout_epochs WHERE job_id=? AND epoch_number=?", (job_id, number)).fetchone()

    def latest_layout_epoch(self, job_id: str) -> dict[str, Any]:
        row = self.connection.execute("SELECT * FROM job_layout_epochs WHERE job_id=? ORDER BY epoch_number DESC LIMIT 1", (job_id,)).fetchone()
        if row is None:
            raise CatalogError("layout_epoch_not_found")
        return dict(row)

    def format_sequence_authorization(
        self, job_id: str, sequence: int
    ) -> sqlite3.Row | None:
        self._validate_safe_identifier(job_id, "job ID")
        if type(sequence) is not int or sequence <= 0:
            raise ValidationError("invalid cassette sequence")
        return self.connection.execute(
            "SELECT authority.* FROM automatic_format_authorizations AS authority "
            "JOIN automatic_sequence_state AS state "
            "ON state.job_id=authority.job_id "
            "AND state.layout_epoch=authority.layout_epoch "
            "AND state.layout_fingerprint_sha256=authority.layout_fingerprint_sha256 "
            "JOIN job_layout_epochs AS epoch "
            "ON epoch.job_id=state.job_id "
            "AND epoch.epoch_number=state.layout_epoch "
            "AND epoch.layout_fingerprint_sha256=state.layout_fingerprint_sha256 "
            "JOIN job_layout_epochs AS latest_epoch "
            "ON latest_epoch.job_id=state.job_id "
            "AND latest_epoch.epoch_number=(SELECT MAX(epoch_number) "
            "FROM job_layout_epochs WHERE job_id=state.job_id) "
            "AND latest_epoch.epoch_number=state.layout_epoch "
            "AND latest_epoch.layout_fingerprint_sha256=state.layout_fingerprint_sha256 "
            "JOIN automatic_cassettes AS cassette "
            "ON cassette.job_id=authority.job_id "
            "AND cassette.sequence=authority.cassette_sequence "
            "AND cassette.physical_label=authority.expected_label "
            "AND cassette.operation=authority.expected_operation "
            "AND cassette.reuse_registered=authority.reuse_registered "
            "WHERE authority.job_id=? AND authority.cassette_sequence=?",
            (job_id, sequence),
        ).fetchone()

    def automatic_sequence_state(self, job_id: str) -> sqlite3.Row:
        self._validate_safe_identifier(job_id, "job ID")
        row = self.connection.execute(
            "SELECT * FROM automatic_sequence_state WHERE job_id=?", (job_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("automatic_sequence_state_not_found")
        return row

    def _rebind_automatic_sequence_layout_tx(
        self,
        db: sqlite3.Connection,
        job_id: str,
        epoch: sqlite3.Row,
        *,
        actor: str,
        changed_at: str,
        request_sha256: str,
        authorize_automatic_formatting: bool,
    ) -> tuple[str, ...]:
        """Disable at a new layout and optionally grant every pending format tuple."""

        pending = db.execute(
            "SELECT sequence,physical_label,reuse_registered FROM automatic_cassettes "
            "WHERE job_id=? AND status IN ('pending','waiting_media') "
            "AND operation='format' ORDER BY sequence",
            (job_id,),
        ).fetchall()
        if pending and not authorize_automatic_formatting:
            raise CatalogError("automatic_format_authorization_required")
        fingerprint = str(epoch["layout_fingerprint_sha256"])
        db.execute(
            "INSERT INTO automatic_sequence_state(job_id,state,layout_epoch,"
            "layout_fingerprint_sha256,revision,enabled_by,enabled_at,updated_at) "
            "VALUES(?,'disabled',?,?,1,NULL,NULL,?) "
            "ON CONFLICT(job_id) DO UPDATE SET state='disabled',"
            "layout_epoch=excluded.layout_epoch,"
            "layout_fingerprint_sha256=excluded.layout_fingerprint_sha256,"
            "revision=automatic_sequence_state.revision+1,enabled_by=NULL,"
            "enabled_at=NULL,updated_at=excluded.updated_at",
            (job_id, int(epoch["epoch_number"]), fingerprint, changed_at),
        )
        ids: list[str] = []
        for cassette in pending:
            payload = {
                "cassette_sequence": int(cassette["sequence"]),
                "expected_label": str(cassette["physical_label"]),
                "expected_operation": "format",
                "job_id": job_id,
                "layout_epoch": int(epoch["epoch_number"]),
                "layout_fingerprint_sha256": fingerprint,
                "reuse_registered": int(cassette["reuse_registered"]),
            }
            authority_id = hashlib.sha256(
                json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode()
            ).hexdigest()
            db.execute(
                "INSERT INTO automatic_format_authorizations(authorization_id,job_id,"
                "cassette_sequence,layout_epoch,layout_fingerprint_sha256,expected_label,"
                "expected_operation,reuse_registered,authorized_by,authorized_at,request_sha256) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (authority_id, job_id, cassette["sequence"], epoch["epoch_number"],
                 fingerprint, cassette["physical_label"], "format",
                 cassette["reuse_registered"], actor, changed_at, request_sha256),
            )
            ids.append(authority_id)
        return tuple(ids)

    def authorize_automatic_format_sequence(
        self,
        job_id: str,
        *,
        expected_revision: int,
        layout_fingerprint_sha256: str,
        actor: str,
        idempotency_key: str,
        authorized_at: str,
        request_sha256: str | None = None,
        record_idempotency: bool = True,
    ) -> tuple[str, ...]:
        self._validate_safe_identifier(job_id, "job ID")
        self._validate_safe_identifier(actor, "authorization actor")
        if type(expected_revision) is not int or expected_revision < 0:
            raise ValidationError("invalid job management revision")
        self._validate_sha256(
            layout_fingerprint_sha256, "automatic sequence layout fingerprint"
        )
        if (
            not isinstance(authorized_at, str)
            or len(authorized_at) > 64
            or self._parse_utc_timestamp(authorized_at) is None
        ):
            raise ValidationError("invalid automatic sequence authorization time")
        if record_idempotency:
            request_payload = {
                "authorize_automatic_formatting": True,
                "authorized_at": authorized_at,
                "expected_revision": expected_revision,
                "job_id": job_id,
                "layout_fingerprint_sha256": layout_fingerprint_sha256,
            }
            request_sha256 = hashlib.sha256(
                json.dumps(
                    request_payload,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()
        elif request_sha256 is None:
            raise ValidationError("missing automatic sequence request digest")
        else:
            self._validate_sha256(
                request_sha256, "automatic sequence request digest"
            )
        action = "automatic.format_sequence.authorize"
        with self.transaction() as db:
            if record_idempotency:
                replay = self.management_idempotency_replay(
                    actor=actor,
                    idempotency_key=idempotency_key,
                    action=action,
                    target_id=job_id,
                    request_sha256=request_sha256,
                )
                if replay is not None:
                    authorization_ids = replay.get("authorization_ids")
                    if (
                        not isinstance(authorization_ids, list)
                        or not all(isinstance(value, str) for value in authorization_ids)
                    ):
                        raise CatalogError("invalid automatic sequence idempotency record")
                    return tuple(authorization_ids)

            management = db.execute(
                "SELECT revision,retired_at FROM job_management_state WHERE job_id=?",
                (job_id,),
            ).fetchone()
            imported = db.execute(
                "SELECT 1 FROM imported_job_policies WHERE job_id=?", (job_id,)
            ).fetchone()
            epoch = db.execute(
                "SELECT * FROM job_layout_epochs WHERE job_id=? "
                "ORDER BY epoch_number DESC LIMIT 1",
                (job_id,),
            ).fetchone()
            if management is None or epoch is None:
                raise CatalogError("automatic_sequence_job_not_found")
            if imported is not None:
                raise CatalogError("automatic_sequence_authorization_native_only")
            if management["retired_at"] is not None:
                raise CatalogError("automatic_sequence_job_retired")
            if int(management["revision"]) != expected_revision:
                raise CatalogError("automatic_sequence_revision_conflict")
            if epoch["layout_fingerprint_sha256"] != layout_fingerprint_sha256:
                raise CatalogError("automatic_sequence_layout_conflict")

            cassettes = db.execute(
                "SELECT sequence,physical_label,reuse_registered "
                "FROM automatic_cassettes WHERE job_id=? "
                "AND status IN ('pending','waiting_media') AND operation='format' "
                "ORDER BY sequence",
                (job_id,),
            ).fetchall()
            if any(
                re.fullmatch(r"[A-Z0-9]{6}", str(row["physical_label"])) is None
                for row in cassettes
            ):
                raise ValidationError(
                    "automatic format label must be a canonical physical label"
                )
            existing = db.execute(
                "SELECT 1 FROM automatic_format_authorizations WHERE job_id=? "
                "AND layout_epoch=? AND layout_fingerprint_sha256=? LIMIT 1",
                (job_id, epoch["epoch_number"], layout_fingerprint_sha256),
            ).fetchone()
            if existing is not None:
                raise CatalogError("automatic_sequence_authorization_exists")

            authorization_ids = list(self._rebind_automatic_sequence_layout_tx(
                db, job_id, epoch, actor=actor, changed_at=authorized_at,
                request_sha256=request_sha256,
                authorize_automatic_formatting=True,
            ))
            if record_idempotency:
                self.record_management_idempotency(
                    actor=actor,
                    idempotency_key=idempotency_key,
                    action=action,
                    target_id=job_id,
                    request_sha256=request_sha256,
                    response={
                        "authorization_ids": authorization_ids,
                        "authorized_at": authorized_at,
                    },
                )
        return tuple(authorization_ids)

    def set_automatic_sequence_enabled(
        self,
        job_id: str,
        *,
        expected_revision: int,
        layout_fingerprint_sha256: str,
        actor: str,
        enabled_at: str,
    ) -> sqlite3.Row:
        self._validate_safe_identifier(job_id, "job ID")
        self._validate_safe_identifier(actor, "sequence actor")
        if type(expected_revision) is not int or expected_revision < 1:
            raise ValidationError("invalid automatic sequence revision")
        self._validate_sha256(
            layout_fingerprint_sha256, "automatic sequence layout fingerprint"
        )
        if self._parse_utc_timestamp(enabled_at) is None:
            raise ValidationError("invalid automatic sequence enable time")
        with self.transaction() as db:
            state = db.execute(
                "SELECT * FROM automatic_sequence_state WHERE job_id=?", (job_id,)
            ).fetchone()
            epoch = db.execute(
                "SELECT * FROM job_layout_epochs WHERE job_id=? "
                "ORDER BY epoch_number DESC LIMIT 1",
                (job_id,),
            ).fetchone()
            if state is None or epoch is None:
                raise CatalogError("automatic_sequence_state_not_found")
            if int(state["revision"]) != expected_revision:
                raise CatalogError("automatic_sequence_state_revision_conflict")
            if epoch["layout_fingerprint_sha256"] != layout_fingerprint_sha256:
                raise CatalogError("automatic_sequence_layout_conflict")
            db.execute(
                "UPDATE automatic_sequence_state SET state='enabled',"
                "layout_epoch=?,layout_fingerprint_sha256=?,revision=revision+1,"
                "enabled_by=?,enabled_at=?,updated_at=? WHERE job_id=?",
                (
                    epoch["epoch_number"],
                    layout_fingerprint_sha256,
                    actor,
                    enabled_at,
                    enabled_at,
                    job_id,
                ),
            )
            current_sequence = db.execute(
                "SELECT current_sequence FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            self._record_audit_tx(
                db, actor, "automatic.sequence.enabled", "accepted",
                f"sequence-enable-{uuid.uuid4().hex}", None,
                json.dumps({
                    "job_id": job_id,
                    "layout_epoch": int(epoch["epoch_number"]),
                    "layout_fingerprint_sha256": layout_fingerprint_sha256,
                    "sequence": None if current_sequence is None else current_sequence[0],
                }, separators=(",", ":"), sort_keys=True),
            )
            row = db.execute(
                "SELECT * FROM automatic_sequence_state WHERE job_id=?", (job_id,)
            ).fetchone()
        assert row is not None
        return row

    def enable_automatic_sequence_for_start(
        self, job_id: str, *, actor: str, enabled_at: str
    ) -> sqlite3.Row:
        """Enable a native start without inventing any format authority.

        Legacy rows may not have received a sequence-state projection.  Creating
        that disabled projection is safe; it never writes an authorization and
        therefore cannot make their later format rows automatic.
        """

        self._validate_safe_identifier(job_id, "job ID")
        self._validate_safe_identifier(actor, "sequence actor")
        if self._parse_utc_timestamp(enabled_at) is None:
            raise ValidationError("invalid automatic sequence enable time")
        with self.transaction() as db:
            job = db.execute(
                "SELECT id FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            imported = db.execute(
                "SELECT 1 FROM imported_job_policies WHERE job_id=?", (job_id,)
            ).fetchone()
            epoch = db.execute(
                "SELECT * FROM job_layout_epochs WHERE job_id=? "
                "ORDER BY epoch_number DESC LIMIT 1",
                (job_id,),
            ).fetchone()
            if job is None or epoch is None:
                raise CatalogError("automatic_sequence_state_not_found")
            if imported is not None:
                raise CatalogError("automatic_sequence_authorization_native_only")
            existing = db.execute(
                "SELECT state,layout_epoch,layout_fingerprint_sha256 FROM automatic_sequence_state "
                "WHERE job_id=?",
                (job_id,),
            ).fetchone()
            if existing is not None and existing["state"] == "pause_pending":
                raise CatalogError("automatic_sequence_pause_pending")
            if existing is not None and existing["state"] not in {"disabled", "enabled"}:
                raise CatalogError("automatic_sequence_state_conflict")
            if (
                existing is not None
                and existing["state"] == "enabled"
                and (
                    existing["layout_epoch"] != epoch["epoch_number"]
                    or existing["layout_fingerprint_sha256"]
                    != epoch["layout_fingerprint_sha256"]
                )
            ):
                raise CatalogError("automatic_sequence_layout_conflict")
            db.execute(
                "INSERT OR IGNORE INTO automatic_sequence_state("
                "job_id,state,layout_epoch,layout_fingerprint_sha256,revision,"
                "enabled_by,enabled_at,updated_at) VALUES(?, 'disabled', ?, ?, "
                "1, NULL, NULL, ?)",
                (
                    job_id,
                    epoch["epoch_number"],
                    epoch["layout_fingerprint_sha256"],
                    enabled_at,
                ),
            )
            if existing is not None and existing["state"] == "enabled":
                row = db.execute(
                    "SELECT * FROM automatic_sequence_state WHERE job_id=?", (job_id,)
                ).fetchone()
                assert row is not None
                return row
            db.execute(
                "UPDATE automatic_sequence_state SET state='enabled',"
                "layout_epoch=?,layout_fingerprint_sha256=?,revision=revision+1,"
                "enabled_by=?,enabled_at=?,updated_at=? WHERE job_id=?",
                (
                    epoch["epoch_number"],
                    epoch["layout_fingerprint_sha256"],
                    actor,
                    enabled_at,
                    enabled_at,
                    job_id,
                ),
            )
            current_sequence = db.execute(
                "SELECT current_sequence FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            self._record_audit_tx(
                db, actor, "automatic.sequence.enabled", "accepted",
                f"sequence-enable-{uuid.uuid4().hex}", None,
                json.dumps({
                    "job_id": job_id,
                    "layout_epoch": int(epoch["epoch_number"]),
                    "layout_fingerprint_sha256": str(epoch["layout_fingerprint_sha256"]),
                    "sequence": None if current_sequence is None else current_sequence[0],
                }, separators=(",", ":"), sort_keys=True),
            )
            row = db.execute(
                "SELECT * FROM automatic_sequence_state WHERE job_id=?", (job_id,)
            ).fetchone()
        assert row is not None
        return row

    def activate_boundary_replanning(self) -> str:
        """Persist a one-time rollout boundary; never reopen older closed jobs."""
        with self.transaction() as db:
            db.execute(
                "INSERT OR IGNORE INTO metadata(key,value) VALUES('boundary_replanning_activated_at',?)",
                (self._precise_utc_now(),),
            )
            return str(db.execute(
                "SELECT value FROM metadata WHERE key='boundary_replanning_activated_at'",
            ).fetchone()[0])

    def boundary_replan_required(self, job_id: str, cassette_sequence: int) -> bool:
        """Require a completed native boundary before admitting its unused suffix.

        Initial starts and attempted-cassette recovery keep their frozen plan.
        Only native jobs with a frozen policy can use boundary rescanning.
        """
        if self.connection.execute(
            "SELECT 1 FROM metadata WHERE key='boundary_replanning_activated_at'",
        ).fetchone() is None or self.connection.execute(
            "SELECT 1 FROM job_policy_snapshots WHERE job_id=?", (job_id,),
        ).fetchone() is None or self.connection.execute(
            "SELECT 1 FROM daemon_operations WHERE job_id=? AND cassette_sequence=?",
            (job_id, cassette_sequence),
        ).fetchone() is not None:
            return False
        boundary = self.connection.execute(
            "SELECT MAX(sequence) FROM automatic_cassettes "
            "WHERE job_id=? AND sequence<? AND status='completed'",
            (job_id, cassette_sequence),
        ).fetchone()[0]
        if boundary is None:
            return False
        if self.connection.execute(
            "SELECT 1 FROM automatic_cassettes cassette WHERE job_id=? AND sequence>? "
            "AND (operation<>'format' OR started_at IS NOT NULL OR status NOT IN ('pending','waiting_media') "
            "OR EXISTS(SELECT 1 FROM daemon_operations attempt WHERE attempt.job_id=cassette.job_id "
            "AND attempt.cassette_sequence=cassette.sequence))",
            (job_id, boundary),
        ).fetchone() is not None:
            return False
        operation = self.connection.execute(
            "SELECT state FROM daemon_operations WHERE job_id=? AND cassette_sequence=? "
            "AND kind='archive.native' ORDER BY started_at DESC,rowid DESC LIMIT 1",
            (job_id, boundary),
        ).fetchone()
        if operation is None or operation["state"] != "succeeded":
            return False
        return not any(
            json.loads(row[0]).get("completed_sequence") == boundary
            for row in self.connection.execute(
                "SELECT payload_json FROM job_management_history WHERE job_id=? "
                "AND action='job.boundary_replan.applied'", (job_id,),
            )
        )

    def pending_boundary_replan_record(self, job_id: str) -> sqlite3.Row | None:
        row = self.connection.execute(
            "SELECT action,payload_json FROM job_management_history WHERE job_id=? "
            "AND action IN ('job.boundary_replan.waiting_labels','job.boundary_replan.applied',"
            "'job.boundary_replan.discarded') ORDER BY id DESC LIMIT 1", (job_id,)
        ).fetchone()
        return row if row is not None and row["action"] == "job.boundary_replan.waiting_labels" else None

    def next_automatic_sequence_candidate(self) -> sqlite3.Row | None:
        rows = self.connection.execute(
            "SELECT state.job_id,state.layout_fingerprint_sha256,"
            "cassette.sequence AS cassette_sequence,"
            "cassette.physical_label,cassette.operation,"
            "authority.authorization_id "
            "FROM automatic_sequence_state AS state "
            "JOIN automatic_jobs AS job ON job.id=state.job_id "
            "JOIN job_layout_epochs AS epoch ON epoch.job_id=state.job_id "
            "AND epoch.epoch_number=state.layout_epoch "
            "JOIN automatic_cassettes AS cassette ON cassette.job_id=state.job_id "
            "AND cassette.sequence=job.current_sequence "
            "LEFT JOIN automatic_format_authorizations AS authority "
            "ON authority.job_id=cassette.job_id "
            "AND authority.cassette_sequence=cassette.sequence "
            "AND authority.layout_epoch=state.layout_epoch "
            "AND authority.layout_fingerprint_sha256=state.layout_fingerprint_sha256 "
            "AND authority.expected_label=cassette.physical_label "
            "AND authority.expected_operation=cassette.operation "
            "AND authority.reuse_registered=cassette.reuse_registered "
            "WHERE state.state='enabled' AND job.status='waiting_media' "
            "AND state.layout_fingerprint_sha256=epoch.layout_fingerprint_sha256 "
            "AND state.layout_epoch=(SELECT MAX(current.epoch_number) "
            "FROM job_layout_epochs AS current WHERE current.job_id=state.job_id) "
            "AND cassette.status IN ('pending','waiting_media') "
            "AND (cassette.planned_files>0 OR cassette.planned_bytes>0) "
            "AND (cassette.operation='append' OR authority.authorization_id IS NOT NULL) "
            "AND NOT EXISTS(SELECT 1 FROM imported_job_policies AS imported "
            "WHERE imported.job_id=state.job_id COLLATE NOCASE) "
            "AND NOT EXISTS(SELECT 1 FROM job_incremental_scan_leases AS scan "
            "WHERE scan.job_id=state.job_id COLLATE NOCASE) "
            "AND COALESCE((SELECT history.action FROM job_management_history AS history "
            "WHERE history.job_id=state.job_id AND history.action IN "
            "('job.boundary_replan.waiting_labels','job.boundary_replan.applied','job.boundary_replan.discarded') "
            "ORDER BY history.id DESC LIMIT 1),'')<>'job.boundary_replan.waiting_labels' "
            "AND NOT EXISTS(SELECT 1 FROM daemon_operations AS operation "
            "WHERE operation.kind='archive.native' AND operation.job_id=state.job_id "
            "AND operation.cassette_sequence=cassette.sequence) "
            "AND NOT EXISTS(SELECT 1 FROM daemon_operations AS active "
            "WHERE active.state IN ('running','recovery_required')) "
            "AND NOT EXISTS(SELECT 1 FROM hardware_command_executions AS command "
            "WHERE command.state != 'quiesced') "
            "ORDER BY job.id COLLATE NOCASE"
        ).fetchall()
        return next((row for row in rows if not self.boundary_replan_required(
            row["job_id"], int(row["cassette_sequence"]),
        )), None)

    def incremental_policy(self, job_id: str) -> dict[str, Any]:
        live = self.connection.execute(
            "SELECT 1 FROM automatic_jobs job "
            "JOIN job_management_state state ON state.job_id=job.id "
            "WHERE job.id=? AND state.retired_at IS NULL AND NOT EXISTS("
            "SELECT 1 FROM deleted_automatic_job_tombstones deleted "
            "WHERE deleted.job_id=job.id COLLATE NOCASE)",
            (job_id,),
        ).fetchone()
        if live is None:
            raise CatalogError("job_not_found")
        row = self.connection.execute("SELECT * FROM job_incremental_policies WHERE job_id=?", (job_id,)).fetchone()
        if row is None:
            raise CatalogError("job_incremental_policy_not_found")
        latest = self.connection.execute("SELECT * FROM job_incremental_scan_events WHERE job_id=? "
                                         "ORDER BY recorded_at DESC,run_id DESC,event_sequence DESC LIMIT 1", (job_id,)).fetchone()
        pending = self.connection.execute("SELECT plan_id,plan_digest_sha256,discovered_files,discovered_bytes,"
                                          "required_additional_labels FROM job_incremental_pending_extensions WHERE job_id=?", (job_id,)).fetchone()
        return {**dict(row),"latest_event": None if latest is None else dict(latest),
                "pending_extension": None if pending is None else dict(pending)}

    def update_incremental_policy(self, job_id: str, cadence: str, *, expected_revision: int, updated_at: str) -> dict[str, Any]:
        delays = {"every_6_hours": timedelta(hours=6),"every_12_hours": timedelta(hours=12),
                  "daily": timedelta(days=1),"weekly": timedelta(days=7)}
        if cadence not in {"off", *delays}:
            raise ValidationError("invalid incremental cadence")
        parsed = self._parse_utc_timestamp(updated_at)
        if parsed is None:
            raise ValidationError("invalid incremental policy time")
        next_at = None if cadence == "off" else (parsed + delays[cadence]).isoformat()
        with self.transaction() as db:
            row = db.execute("SELECT revision FROM job_incremental_policies WHERE job_id=?", (job_id,)).fetchone()
            if row is None:
                raise CatalogError("job_incremental_policy_not_found")
            if int(row["revision"]) != expected_revision:
                raise CatalogError("job_incremental_revision_conflict")
            db.execute("UPDATE job_incremental_policies SET cadence=?,next_eligible_at=?,revision=revision+1,updated_at=? WHERE job_id=?",
                       (cadence, next_at, updated_at, job_id))
        return self.incremental_policy(job_id)

    def claim_incremental_scan_run(
        self, run_id: str, job_id: str, trigger: str, *, daemon_generation: int,
        idempotency_key_sha256: str, recorded_at: str,
    ) -> tuple[dict[str, Any], bool, bool]:
        self._validate_safe_identifier(run_id, "incremental run ID")
        self._validate_sha256(idempotency_key_sha256, "incremental idempotency digest")
        self._validate_incremental_timestamp(recorded_at)
        if trigger not in {"scheduled","manual","labels_added","startup_catchup"}:
            raise ValidationError("invalid incremental trigger")
        with self.transaction() as db:
            owner = db.execute("SELECT generation FROM daemon_ownership WHERE singleton=1").fetchone()
            if owner is None or int(owner["generation"]) != daemon_generation:
                raise CatalogError("stale_incremental_daemon_fence")
            replay = db.execute("SELECT * FROM job_incremental_scan_events WHERE run_id=? ORDER BY event_sequence DESC LIMIT 1", (run_id,)).fetchone()
            if replay is not None:
                if str(replay["job_id"]).casefold() != job_id.casefold() or replay["trigger"] != trigger or replay["idempotency_key_sha256"] != idempotency_key_sha256:
                    raise CatalogError("incremental_idempotency_conflict")
                return dict(replay), True, False
            epoch = db.execute("SELECT epoch_number,layout_fingerprint_sha256 FROM job_layout_epochs WHERE job_id=? ORDER BY epoch_number DESC LIMIT 1", (job_id,)).fetchone()
            job = db.execute("SELECT job.status,state.retired_at FROM automatic_jobs job JOIN job_management_state state ON state.job_id=job.id WHERE job.id=?", (job_id,)).fetchone()
            if epoch is None or job is None:
                raise CatalogError("job_not_found")
            imported = db.execute("SELECT 1 FROM imported_job_policies WHERE job_id=?", (job_id,)).fetchone()
            if imported is not None or job["retired_at"] is not None:
                raise CatalogError("job_imported_frozen" if imported is not None else "job_retired")
            lease = db.execute("SELECT * FROM job_incremental_scan_leases WHERE job_id=?", (job_id,)).fetchone()
            if lease is not None:
                if int(lease["daemon_generation"]) != daemon_generation:
                    db.execute("DELETE FROM job_incremental_scan_leases WHERE job_id=?", (job_id,))
                else:
                    raise CatalogError("incremental_scan_busy")
            active = db.execute("SELECT 1 FROM daemon_operations WHERE state IN ('running','recovery_required') AND (job_id=? OR job_id IS NULL) LIMIT 1", (job_id,)).fetchone()
            incomplete = db.execute("SELECT 1 FROM automatic_cassettes WHERE job_id=? AND NOT(status='completed' OR (status='pending' AND planned_files=0 AND planned_bytes=0)) LIMIT 1", (job_id,)).fetchone()
            blocked = db.execute(
                "SELECT 1 FROM daemon_operations operation "
                "JOIN recovery_attempt_events event ON event.operation_id=operation.id "
                "WHERE operation.job_id=? AND operation.state='recovery_required' "
                "AND event.event_sequence=2 "
                "AND event.attempt_number=(SELECT MAX(latest.attempt_number) "
                "FROM recovery_attempt_events latest "
                "WHERE latest.operation_id=event.operation_id AND latest.event_sequence=2) "
                "AND event.state IN ('retry_scheduled','critical_quarantine') LIMIT 1",
                (job_id,),
            ).fetchone()
            fenced = db.execute("SELECT 1 FROM managed_source_job_fences WHERE job_id=?", (job_id,)).fetchone()
            admitted = str(job["status"]) == "completed" and all(x is None for x in (active,incomplete,blocked,fenced))
            db.execute("INSERT INTO job_incremental_scan_leases(job_id,run_id,daemon_generation,claimed_at) VALUES(?,?,?,?)", (job_id,run_id,daemon_generation,recorded_at))
            db.execute("INSERT INTO job_incremental_scan_events(run_id,event_sequence,job_id,trigger,base_layout_epoch,base_layout_fingerprint,idempotency_key_sha256,state,daemon_generation,recorded_at) VALUES(?,1,?,?,?,?,?,'claimed',?,?)",
                       (run_id,job_id,trigger,int(epoch["epoch_number"]),str(epoch["layout_fingerprint_sha256"]),idempotency_key_sha256,daemon_generation,recorded_at))
            result = db.execute("SELECT * FROM job_incremental_scan_events WHERE run_id=? AND event_sequence=1", (run_id,)).fetchone()
            return dict(result), False, admitted

    def append_incremental_scan_event(self, run_id: str, state: str, *, daemon_generation: int,
                                      recorded_at: str, plan_id: str | None = None,
                                      plan_digest_sha256: str | None = None, discovered_files: int = 0,
                                      discovered_bytes: int = 0, required_additional_labels: int = 0,
                                      error_code: str | None = None) -> dict[str, Any]:
        self._validate_incremental_timestamp(recorded_at)
        with self.transaction() as db:
            previous = db.execute("SELECT * FROM job_incremental_scan_events WHERE run_id=? ORDER BY event_sequence DESC LIMIT 1", (run_id,)).fetchone()
            if previous is None:
                raise CatalogError("incremental_run_not_found")
            if recorded_at < str(previous["recorded_at"]):
                raise ValidationError("incremental event time must be monotonic")
            sequence = int(previous["event_sequence"]) + 1
            db.execute("INSERT INTO job_incremental_scan_events(run_id,event_sequence,job_id,trigger,base_layout_epoch,base_layout_fingerprint,idempotency_key_sha256,state,daemon_generation,recorded_at,plan_id,plan_digest_sha256,discovered_files,discovered_bytes,required_additional_labels,error_code) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                       (run_id,sequence,previous["job_id"],previous["trigger"],previous["base_layout_epoch"],previous["base_layout_fingerprint"],previous["idempotency_key_sha256"],state,daemon_generation,recorded_at,plan_id,plan_digest_sha256,discovered_files,discovered_bytes,required_additional_labels,error_code))
            return dict(db.execute("SELECT * FROM job_incremental_scan_events WHERE run_id=? AND event_sequence=?", (run_id,sequence)).fetchone())

    def finish_incremental_scan_run(self, run_id: str, *, state: str, daemon_generation: int,
                                    recorded_at: str, next_eligible_at: str | None,
                                    invalidate_pending: bool = False, **values: Any) -> dict[str, Any]:
        self._validate_incremental_timestamp(recorded_at)
        if next_eligible_at is not None:
            self._validate_incremental_timestamp(next_eligible_at)
        with self.transaction() as db:
            lease = db.execute("SELECT job_id FROM job_incremental_scan_leases WHERE run_id=? AND daemon_generation=?", (run_id,daemon_generation)).fetchone()
            if lease is None:
                raise CatalogError("incremental_scan_lease_lost")
            previous = db.execute(
                "SELECT * FROM job_incremental_scan_events WHERE run_id=? "
                "ORDER BY event_sequence DESC LIMIT 1", (run_id,)
            ).fetchone()
            if previous is None:
                raise CatalogError("incremental_run_not_found")
            if recorded_at < str(previous["recorded_at"]):
                raise ValidationError("incremental event time must be monotonic")
            if invalidate_pending:
                if state != "plan_stale" or not values.get("plan_id") or not values.get("plan_digest_sha256"):
                    raise ValidationError("invalid pending extension invalidation")
                deleted = db.execute(
                    "DELETE FROM job_incremental_pending_extensions "
                    "WHERE job_id=? AND plan_id=? AND plan_digest_sha256=?",
                    (lease["job_id"], values["plan_id"], values["plan_digest_sha256"]),
                )
                if deleted.rowcount != 1:
                    raise CatalogError("incremental_extension_conflict")
            sequence = int(previous["event_sequence"]) + 1
            db.execute(
                "INSERT INTO job_incremental_scan_events("
                "run_id,event_sequence,job_id,trigger,base_layout_epoch,"
                "base_layout_fingerprint,idempotency_key_sha256,state,"
                "daemon_generation,recorded_at,plan_id,plan_digest_sha256,"
                "discovered_files,discovered_bytes,required_additional_labels,error_code) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    run_id, sequence, previous["job_id"], previous["trigger"],
                    previous["base_layout_epoch"], previous["base_layout_fingerprint"],
                    previous["idempotency_key_sha256"], state, daemon_generation,
                    recorded_at, values.get("plan_id"), values.get("plan_digest_sha256"),
                    values.get("discovered_files", 0), values.get("discovered_bytes", 0),
                    values.get("required_additional_labels", 0), values.get("error_code"),
                ),
            )
            success = recorded_at if state in {"no_changes","extension_queued"} else None
            db.execute("UPDATE job_incremental_policies SET next_eligible_at=?,last_attempt_at=?,last_success_at=COALESCE(?,last_success_at),last_outcome=?,updated_at=? WHERE job_id=?",
                       (next_eligible_at,recorded_at,success,state,recorded_at,lease["job_id"]))
            db.execute("DELETE FROM job_incremental_scan_leases WHERE run_id=?", (run_id,))
            event = db.execute(
                "SELECT * FROM job_incremental_scan_events "
                "WHERE run_id=? AND event_sequence=?", (run_id, sequence)
            ).fetchone()
        return dict(event)

    def due_incremental_jobs(self, now: str) -> tuple[str, ...]:
        return tuple(str(row["job_id"]) for row in self.connection.execute(
            "SELECT policy.job_id FROM job_incremental_policies policy "
            "JOIN automatic_jobs job ON job.id=policy.job_id COLLATE NOCASE "
            "JOIN job_management_state state ON state.job_id=policy.job_id COLLATE NOCASE "
            "WHERE policy.cadence!='off' AND policy.next_eligible_at IS NOT NULL "
            "AND policy.next_eligible_at<=? AND job.status='completed' "
            "AND state.retired_at IS NULL AND NOT EXISTS("
            "SELECT 1 FROM deleted_automatic_job_tombstones deleted "
            "WHERE deleted.job_id=policy.job_id COLLATE NOCASE) "
            "ORDER BY policy.next_eligible_at,policy.job_id",
            (now,),
        ))

    def retain_incremental_extension(
        self, job_id: str, *, plan_id: str, plan_digest_sha256: str,
        discovered_files: int, discovered_bytes: int,
        required_additional_labels: int, created_at: str,
    ) -> None:
        epoch = self.latest_layout_epoch(job_id)
        with self.transaction() as db:
            existing = db.execute(
                "SELECT * FROM job_incremental_pending_extensions WHERE job_id=?",
                (job_id,),
            ).fetchone()
            identity = (
                int(epoch["epoch_number"]), str(epoch["layout_fingerprint_sha256"]),
                plan_id, plan_digest_sha256, discovered_files, discovered_bytes,
                required_additional_labels, created_at,
            )
            if existing is not None:
                existing_identity = (
                    int(existing["base_epoch_number"]),
                    str(existing["base_layout_fingerprint"]), str(existing["plan_id"]),
                    str(existing["plan_digest_sha256"]), int(existing["discovered_files"]),
                    int(existing["discovered_bytes"]),
                    int(existing["required_additional_labels"]), str(existing["created_at"]),
                )
                if existing_identity == identity:
                    return
                raise CatalogError("incremental_extension_conflict")
            db.execute(
                "INSERT INTO job_incremental_pending_extensions(job_id,base_epoch_number,"
                "base_layout_fingerprint,plan_id,plan_digest_sha256,discovered_files,"
                "discovered_bytes,required_additional_labels,created_at) VALUES(?,?,?,?,?,?,?,?,?) "
                "ON CONFLICT(job_id) DO UPDATE SET base_epoch_number=excluded.base_epoch_number,"
                "base_layout_fingerprint=excluded.base_layout_fingerprint,plan_id=excluded.plan_id,"
                "plan_digest_sha256=excluded.plan_digest_sha256,discovered_files=excluded.discovered_files,"
                "discovered_bytes=excluded.discovered_bytes,required_additional_labels=excluded.required_additional_labels,"
                "created_at=excluded.created_at",
                (job_id,int(epoch["epoch_number"]),epoch["layout_fingerprint_sha256"],plan_id,
                 plan_digest_sha256,discovered_files,discovered_bytes,required_additional_labels,created_at),
            )

    @classmethod
    def _validate_incremental_timestamp(cls, value: object) -> str:
        parsed = cls._parse_utc_timestamp(value)
        if parsed is None or not isinstance(value, str) or parsed.isoformat() != value:
            raise ValidationError("incremental event time must be canonical UTC")
        return value

    def pending_incremental_extension(self, job_id: str) -> dict[str, Any] | None:
        row = self.connection.execute(
            "SELECT * FROM job_incremental_pending_extensions WHERE job_id=?", (job_id,)
        ).fetchone()
        return None if row is None else dict(row)

    def update_incremental_extension_label_deficit(
        self,
        job_id: str,
        *,
        plan_id: str,
        plan_digest_sha256: str,
        required_additional_labels: int,
    ) -> dict[str, Any]:
        """Persist a monotonic partial-label result for one frozen extension."""

        self._validate_sha256(plan_digest_sha256, "incremental plan digest")
        if (
            isinstance(required_additional_labels, bool)
            or not isinstance(required_additional_labels, int)
            or required_additional_labels < 0
        ):
            raise ValidationError("invalid incremental label deficit")
        with self.transaction() as db:
            pending = db.execute(
                "SELECT * FROM job_incremental_pending_extensions WHERE job_id=?",
                (job_id,),
            ).fetchone()
            if pending is None:
                raise CatalogError("incremental_extension_not_found")
            if (
                str(pending["plan_id"]) != plan_id
                or str(pending["plan_digest_sha256"]) != plan_digest_sha256
            ):
                raise CatalogError("incremental_extension_conflict")
            current = int(pending["required_additional_labels"])
            if required_additional_labels > current:
                raise CatalogError("incremental_label_deficit_increased")
            if required_additional_labels != current:
                db.execute(
                    "UPDATE job_incremental_pending_extensions "
                    "SET required_additional_labels=? WHERE job_id=?",
                    (required_additional_labels, job_id),
                )
            result = db.execute(
                "SELECT * FROM job_incremental_pending_extensions WHERE job_id=?",
                (job_id,),
            ).fetchone()
        return dict(result)

    def clear_incremental_extension_and_record_epoch(
        self, job_id: str, *, plan_id: str, plan_digest_sha256: str,
        target_sequences: Sequence[int], created_at: str,
        target_operations: Sequence[str] | None = None,
    ) -> dict[str, Any]:
        with self.transaction() as db:
            epoch = db.execute(
                "SELECT * FROM job_layout_epochs WHERE job_id=? AND plan_id=?",
                (job_id, plan_id),
            ).fetchone()
            if epoch is None:
                epoch = self._insert_layout_epoch_tx(
                    db, job_id, kind="extension", plan_id=plan_id,
                    plan_digest_sha256=plan_digest_sha256, created_at=created_at,
                    target_sequences=target_sequences,target_operations=target_operations,
                )
            elif str(epoch["plan_digest_sha256"]) != plan_digest_sha256:
                raise CatalogError("layout_epoch_plan_conflict")
            db.execute("DELETE FROM job_incremental_pending_extensions WHERE job_id=?", (job_id,))
        return dict(epoch)

    def incremental_reserve_capacity(self, job_id: str) -> int:
        row = self.connection.execute(
            "SELECT COUNT(*) FROM automatic_cassettes WHERE job_id=? AND status='pending' "
            "AND planned_files=0 AND planned_bytes=0", (job_id,)
        ).fetchone()
        return int(row[0])

    def job_extension_evidence(self, job_id: str) -> dict[str, Any]:
        """Return the immutable structural evidence bound into an extension draft."""

        job = self.get_automatic_job(job_id)
        state = self.job_management_state(job_id)
        libraries = [
            str(row["library_id"]) for row in self.list_automatic_job_libraries(job_id)
        ]
        cassettes = [
            {
                "copied_bytes": int(row["copied_bytes"]),
                "copied_files": int(row["copied_files"]),
                "operation": str(row["operation"]),
                "physical_label": str(row["physical_label"]),
                "planned_bytes": int(row["planned_bytes"]),
                "planned_files": int(row["planned_files"]),
                "sequence": int(row["sequence"]),
                "status": str(row["status"]),
                "tape_id": None if row["tape_id"] is None else str(row["tape_id"]),
            }
            for row in self.list_automatic_cassettes(job_id)
        ]
        payload = {
            "cassettes": cassettes,
            "job_id": str(job["id"]),
            "libraries": libraries,
            "media_key": str(job["media_key"]),
            "revision": int(state["revision"]),
        }
        canonical = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        return {
            **payload,
            "fingerprint_sha256": hashlib.sha256(canonical.encode("utf-8")).hexdigest(),
            "retired": state["retired_at"] is not None,
            "imported": self.get_import_policy(job_id) is not None,
            "status": str(job["status"]),
        }

    @staticmethod
    def _job_management_state_tx(db: sqlite3.Connection, job_id: str) -> sqlite3.Row:
        row = db.execute(
            "SELECT * FROM job_management_state WHERE job_id=?", (job_id,)
        ).fetchone()
        if row is None:
            raise CatalogError("job_not_found")
        return row

    @staticmethod
    def _job_history_tx(
        db: sqlite3.Connection,
        job_id: str,
        actor: str,
        action: str,
        checkpoint: str,
        payload: Mapping[str, Any],
        *,
        occurred_at: str | None = None,
    ) -> None:
        db.execute(
            "INSERT INTO job_management_history("
            "job_id,occurred_at,actor,action,checkpoint,payload_json) "
            "VALUES(?,?,?,?,?,?)",
            (
                job_id,
                occurred_at or utc_now(),
                actor,
                action,
                checkpoint,
                json.dumps(
                    dict(payload),
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            ),
        )

    def update_job_checkpoint(self, job_id: str, checkpoint: str) -> None:
        self._validate_safe_identifier(checkpoint, "job checkpoint")
        with self.transaction() as db:
            state = self._job_management_state_tx(db, job_id)
            if state["retired_at"] is not None:
                raise CatalogError("job_retired")
            db.execute(
                "UPDATE job_management_state SET current_checkpoint=?,updated_at=? "
                "WHERE job_id=?",
                (checkpoint, utc_now(), job_id),
            )

    def request_job_pause(self, job_id: str, actor: str) -> dict[str, Any]:
        now = utc_now()
        with self.transaction() as db:
            job = db.execute(
                "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            state = self._job_management_state_tx(db, job_id)
            if job is None or state["retired_at"] is not None:
                raise CatalogError("job_not_found")
            if job["status"] in {"planned", "paused", "completed", "failed"}:
                raise CatalogError("job_pause_state_conflict")
            if state["pause_requested_at"] is None:
                db.execute(
                    "UPDATE job_management_state SET pause_requested_at=?,"
                    "pause_acknowledged_at=NULL,updated_at=? WHERE job_id=?",
                    (now, now, job_id),
                )
                db.execute(
                    "UPDATE automatic_sequence_state SET state='pause_pending',"
                    "updated_at=? WHERE job_id=? AND state='enabled'",
                    (now, job_id),
                )
        return self.job_management_state(job_id)

    def job_pause_requested(self, job_id: str) -> bool:
        row = self.connection.execute(
            "SELECT pause_requested_at,pause_acknowledged_at "
            "FROM job_management_state WHERE job_id=?",
            (job_id,),
        ).fetchone()
        return bool(
            row is not None
            and row["pause_requested_at"] is not None
            and row["pause_acknowledged_at"] is None
        )

    def acknowledge_job_pause(
        self, job_id: str, checkpoint: str, *, fence: OperationFence | None = None
    ) -> bool:
        self._validate_safe_identifier(checkpoint, "job checkpoint")
        now = utc_now()
        with self.transaction() as db:
            state = self._job_management_state_tx(db, job_id)
            if state["pause_requested_at"] is None:
                return False
            if checkpoint == "waiting_media":
                if fence is None:
                    raise ValidationError("waiting_media checkpoint requires an operation fence")
                operation = self._assert_operation_fence_tx(db, fence)
                job = db.execute(
                    "SELECT status,current_sequence FROM automatic_jobs WHERE id=?",
                    (job_id,),
                ).fetchone()
                if (
                    operation["job_id"] != job_id
                    or operation["kind"] != "archive.native"
                    or operation["phase"] is not None
                    or job is None
                    or job["status"] != "waiting_media"
                    or job["current_sequence"] != operation["cassette_sequence"]
                ):
                    raise ValidationError("operation is not at the waiting_media checkpoint")
                if db.execute(
                    "SELECT 1 FROM hardware_command_executions "
                    "WHERE state != 'quiesced' LIMIT 1"
                ).fetchone() is not None:
                    raise CommandQuiescenceRequired(
                        "waiting_media pause requires every command to be quiescent"
                    )
            if state["pause_acknowledged_at"] is None:
                db.execute(
                    "UPDATE job_management_state SET pause_acknowledged_at=?,"
                    "current_checkpoint=?,updated_at=? WHERE job_id=?",
                    (now, checkpoint, now, job_id),
                )
                self._job_history_tx(
                    db,
                    job_id,
                    "system",
                    "job.pause_acknowledged",
                    checkpoint,
                    {},
                    occurred_at=now,
                )
                if checkpoint in {"unloaded", "waiting_media"}:
                    db.execute(
                        "UPDATE automatic_sequence_state SET state='disabled',"
                        "updated_at=? WHERE job_id=? AND state='pause_pending'",
                        (now, job_id),
                    )
                    sequence = db.execute(
                        "SELECT job.current_sequence,state.layout_epoch,"
                        "state.layout_fingerprint_sha256 FROM automatic_jobs job "
                        "JOIN automatic_sequence_state state ON state.job_id=job.id "
                        "WHERE job.id=?", (job_id,),
                    ).fetchone()
                    if sequence is not None:
                        self._record_audit_tx(
                            db, "system", "automatic.sequence.pause_checkpoint",
                            "accepted", f"sequence-pause-{uuid.uuid4().hex}", None,
                            json.dumps({
                                "job_id": job_id,
                                "layout_epoch": int(sequence["layout_epoch"]),
                                "layout_fingerprint_sha256": str(sequence["layout_fingerprint_sha256"]),
                                "sequence": int(sequence["current_sequence"]),
                                "checkpoint": checkpoint,
                            }, separators=(",", ":"), sort_keys=True),
                        )
            return True

    def clear_job_pause(self, job_id: str, actor: str) -> None:
        now = utc_now()
        with self.transaction() as db:
            self._job_management_state_tx(db, job_id)
            db.execute(
                "UPDATE job_management_state SET pause_requested_at=NULL,"
                "pause_acknowledged_at=NULL,current_checkpoint='resuming',"
                "revision=revision+1,updated_at=? WHERE job_id=?",
                (now, job_id),
            )

    def rename_managed_job(
        self,
        job_id: str,
        display_name: str,
        *,
        expected_revision: int | None = None,
    ) -> sqlite3.Row:
        state = self.job_management_state(job_id)
        if state["retired_at"] is not None:
            raise CatalogError("job_retired")
        if self.get_import_policy(job_id) is not None:
            raise CatalogError("job_imported_frozen")
        if (
            expected_revision is not None
            and int(state["revision"]) != expected_revision
        ):
            raise CatalogError("job_revision_conflict")
        self.rename_automatic_job(job_id, display_name)
        with self.transaction() as db:
            db.execute(
                "UPDATE job_management_state SET revision=revision+1,updated_at=? "
                "WHERE job_id=?",
                (utc_now(), job_id),
            )
        return self.get_automatic_job(job_id)

    def reserve_job_labels(
        self,
        job_id: str,
        labels: Sequence[str],
        *,
        expected_revision: int | None = None,
        actor: str = "system",
        authorize_automatic_formatting: bool = False,
        request_sha256: str | None = None,
    ) -> sqlite3.Row:
        normalized = tuple(str(label).strip().upper() for label in labels)
        if (
            not normalized
            or len(normalized) > 64
            or len(set(normalized)) != len(normalized)
            or any(not re.fullmatch(r"[A-Z0-9]{6}", label) for label in normalized)
        ):
            raise ValidationError("invalid physical cassette labels")
        self._validate_safe_identifier(actor, "authorization actor")
        if type(authorize_automatic_formatting) is not bool:
            raise ValidationError("invalid automatic formatting authority")
        if request_sha256 is None:
            request_sha256 = hashlib.sha256(
                json.dumps(
                    {"job_id": job_id, "labels": list(normalized)},
                    separators=(",", ":"), sort_keys=True,
                ).encode()
            ).hexdigest()
        self._validate_sha256(request_sha256, "reserve request digest")
        now = utc_now()
        with self.transaction() as db:
            job = db.execute(
                "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            state = self._job_management_state_tx(db, job_id)
            if job is None or state["retired_at"] is not None:
                raise CatalogError("job_not_found")
            if (
                expected_revision is not None
                and int(state["revision"]) != expected_revision
            ):
                raise CatalogError("job_revision_conflict")
            if self.get_import_policy(job_id) is not None:
                raise CatalogError("job_imported_frozen")
            if job["status"] not in {"planned", "paused", "waiting_media", "completed"}:
                raise CatalogError("job_reserve_state_conflict")
            if not authorize_automatic_formatting:
                raise CatalogError("automatic_format_authorization_required")
            for label in normalized:
                conflict = db.execute(
                    "SELECT cassette.job_id FROM automatic_cassettes cassette "
                    "JOIN job_management_state state ON state.job_id=cassette.job_id "
                    "JOIN automatic_jobs job ON job.id=cassette.job_id "
                    "WHERE cassette.physical_label=? COLLATE NOCASE "
                    "AND state.retired_at IS NULL "
                    "AND job.status NOT IN ('completed','failed') LIMIT 1",
                    (label,),
                ).fetchone()
                if conflict is not None:
                    raise CatalogError("job_label_unavailable")
                registered = db.execute(
                    "SELECT 1 FROM tapes WHERE cassette_number=? COLLATE NOCASE "
                    "OR id=? COLLATE NOCASE LIMIT 1",
                    (label, label),
                ).fetchone()
                if registered is not None:
                    raise CatalogError("job_label_registered")
            last_sequence = int(
                db.execute(
                    "SELECT COALESCE(MAX(sequence),0) FROM automatic_cassettes "
                    "WHERE job_id=?",
                    (job_id,),
                ).fetchone()[0]
            )
            db.executemany(
                "INSERT INTO automatic_cassettes("
                "job_id,sequence,physical_label,tape_serial,status,planned_files,"
                "planned_bytes,operation,reuse_registered) "
                "VALUES(?,?,?,?,'pending',0,0,'format',0)",
                [
                    (job_id, last_sequence + index, label, label)
                    for index, label in enumerate(normalized, 1)
                ],
            )
            new_sequences = tuple(
                last_sequence + index for index in range(1, len(normalized) + 1)
            )
            db.execute(
                "UPDATE automatic_jobs SET total_cassettes=total_cassettes+? "
                "WHERE id=?",
                (len(normalized), job_id),
            )
            db.execute(
                "UPDATE job_management_state SET revision=revision+1,updated_at=? "
                "WHERE job_id=?",
                (now, job_id),
            )
            epoch = self._insert_layout_epoch_tx(
                db, job_id, kind="extension", plan_id=None,
                plan_digest_sha256=request_sha256, created_at=now,
                target_sequences=new_sequences,
                target_operations=tuple("format" for _ in new_sequences),
            )
            db.execute(
                "UPDATE job_incremental_pending_extensions SET base_epoch_number=?,"
                "base_layout_fingerprint=? WHERE job_id=?",
                (epoch["epoch_number"], epoch["layout_fingerprint_sha256"], job_id),
            )
            self._rebind_automatic_sequence_layout_tx(
                db, job_id, epoch, actor=actor, changed_at=now,
                request_sha256=request_sha256,
                authorize_automatic_formatting=True,
            )
        return self.get_automatic_job(job_id)

    def _cleanup_exclusive_job_tapes_tx(
        self, db: sqlite3.Connection, job_id: str
    ) -> dict[str, Any]:
        """Remove only proven exclusive tape indexes; keep physical and audit identity.

        A cassette's current block pointer is insufficient for append histories.
        All layout epochs and durable operation bindings participate in ownership;
        an unrelated, conflicting, or unowned block protects the entire tape.
        """
        owners = """
            WITH owners AS (
                SELECT block_id,job_id FROM job_layout_target_blocks
                UNION SELECT block_id,job_id FROM automatic_operation_blocks
                UNION SELECT block_id,job_id FROM automatic_operation_block_tombstones
                UNION SELECT cassette.block_id,cassette.job_id
                FROM automatic_cassettes AS cassette
                JOIN blocks AS block ON block.id=cassette.block_id
                WHERE cassette.tape_id=block.tape_id COLLATE NOCASE
                  AND cassette.status IN ('completed','failed','writing','unmounting')
                  AND EXISTS(SELECT 1 FROM automatic_job_libraries AS link
                    WHERE link.job_id=cassette.job_id COLLATE NOCASE
                      AND link.library_id=block.library_id COLLATE NOCASE)
            )
        """
        candidates = db.execute(
            owners + """
            SELECT tape.* FROM tapes AS tape
            WHERE EXISTS(SELECT 1 FROM automatic_cassettes AS cassette
                WHERE cassette.job_id=? COLLATE NOCASE AND (
                    cassette.tape_id=tape.id COLLATE NOCASE
                    OR cassette.physical_label=tape.id COLLATE NOCASE
                    OR cassette.physical_label=tape.cassette_number COLLATE NOCASE
                    OR upper(cassette.physical_label)=upper(substr(trim(tape.id),1,6))
                    OR upper(cassette.physical_label)=upper(substr(trim(tape.cassette_number),1,6))))
              OR EXISTS(SELECT 1 FROM blocks AS block JOIN owners ON owners.block_id=block.id
                WHERE owners.job_id=? COLLATE NOCASE AND block.tape_id=tape.id COLLATE NOCASE)
            ORDER BY tape.id COLLATE NOCASE
            """, (job_id, job_id),
        ).fetchall()
        result: dict[str, Any] = {
            "deleted_tapes": [], "preserved_tapes": [],
            "deleted_blocks": 0, "deleted_files": 0, "tape_data_deleted": False,
        }
        for tape in candidates:
            tape_id = str(tape["id"])
            identity_aliases = tuple(dict.fromkeys((
                tape_id, str(tape["cassette_number"]),
                tape_id.strip().upper()[:6],
                str(tape["cassette_number"]).strip().upper()[:6],
            )))
            alias_parameters = ",".join("?" for _ in identity_aliases)
            reason = None
            # These identities remain immutable even after a job is retired.
            for table in (
                "imported_cassette_commit_receipts",
                "imported_runtime_cassette_commit_receipts",
                "restore_plan_cassettes",
                "restore_plan_items",
            ):
                if db.execute(
                    f"SELECT 1 FROM {table} WHERE tape_id=? COLLATE NOCASE LIMIT 1",
                    (tape_id,),
                ).fetchone() is not None:
                    reason = "retained_history_reference"
                    break
            label = str(tape["cassette_number"]).strip().upper()[:6]
            if reason is None:
                if re.fullmatch(r"[A-Z0-9]{6}", label) is None:
                    reason = "ambiguous_tape_identity"
                else:
                    resolution, resolved = self._resolve_registered_tape_label_tx(db, label)
                    if resolution != "unique" or resolved["id"] != tape_id:
                        reason = "ambiguous_tape_identity"
            if reason is None and db.execute(
                "SELECT 1 FROM automatic_cassettes WHERE job_id<>? COLLATE NOCASE "
                "AND (tape_id=? COLLATE NOCASE OR physical_label COLLATE NOCASE "
                f"IN ({alias_parameters}) "
                f"OR upper(substr(trim(physical_label),1,6)) IN ({alias_parameters}) "
                "OR block_id IN (SELECT id FROM blocks WHERE tape_id=? COLLATE NOCASE)) "
                "UNION ALL SELECT 1 FROM job_layout_targets "
                "WHERE job_id<>? COLLATE NOCASE AND (physical_label COLLATE NOCASE "
                f"IN ({alias_parameters}) "
                f"OR upper(substr(trim(physical_label),1,6)) IN ({alias_parameters})) LIMIT 1",
                (job_id, tape_id, *identity_aliases, *identity_aliases,
                 tape_id, job_id, *identity_aliases, *identity_aliases),
            ).fetchone() is not None:
                reason = "shared_tape"
            if reason is None and db.execute(
                "SELECT 1 FROM daemon_operations "
                "WHERE state IN ('running','recovery_required') "
                "UNION ALL SELECT 1 FROM hardware_command_executions "
                "WHERE state<>'quiesced' LIMIT 1",
            ).fetchone() is not None:
                reason = "operation_active"
            if reason is None:
                ownership = db.execute(
                    owners + "SELECT block.id,owners.job_id FROM blocks AS block "
                    "LEFT JOIN owners ON owners.block_id=block.id "
                    "WHERE block.tape_id=? COLLATE NOCASE", (tape_id,),
                ).fetchall()
                if not ownership or any(row["job_id"] is None for row in ownership):
                    reason = "ownership_unproven"
                elif any(str(row["job_id"]).casefold() != job_id.casefold() for row in ownership):
                    reason = "shared_tape"
            if reason is None and db.execute(
                "SELECT 1 FROM file_versions AS version LEFT JOIN blocks AS block ON block.id=version.block_id "
                "WHERE (version.tape_id=? COLLATE NOCASE OR block.tape_id=? COLLATE NOCASE) "
                "AND (block.id IS NULL OR version.tape_id<>block.tape_id COLLATE NOCASE "
                "OR version.library_id<>block.library_id COLLATE NOCASE) LIMIT 1",
                (tape_id, tape_id),
            ).fetchone() is not None:
                reason = "inconsistent_file_ownership"
            if reason is not None:
                result["preserved_tapes"].append({"tape_id": tape_id, "reason": reason})
                continue
            removed = self._invalidate_tape_catalog_for_lifecycle(
                db, tape_id, disposition="job_deleted",
            )
            result["deleted_tapes"].append(tape_id)
            result["deleted_blocks"] += removed["blocks"]
            result["deleted_files"] += removed["files"]
        return result

    def retire_managed_job(
        self, job_id: str, *, expected_revision: int | None = None, actor: str = "system"
    ) -> sqlite3.Row:
        now = utc_now()
        with self.transaction() as db:
            job = db.execute(
                "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            state = self._job_management_state_tx(db, job_id)
            if job is None:
                raise CatalogError("job_not_found")
            if (
                expected_revision is not None
                and int(state["revision"]) != expected_revision
            ):
                raise CatalogError("job_revision_conflict")
            if self.get_import_policy(job_id) is not None:
                raise CatalogError("job_imported_frozen")
            if state["retired_at"] is not None:
                return job
            if job["status"] not in {
                "planned",
                "waiting_media",
                "paused",
                "completed",
                "failed",
            }:
                raise CatalogError("job_retire_state_conflict")
            cleanup = self._cleanup_exclusive_job_tapes_tx(db, job_id)
            self._job_history_tx(
                db, job_id, actor, "job.catalog_cleanup", "retired", cleanup,
                occurred_at=now,
            )
            db.execute(
                "UPDATE automatic_cassettes SET status='failed',error=? "
                "WHERE job_id=? AND status NOT IN ('completed','failed')",
                ("Logically retired before use", job_id),
            )
            if job["status"] not in {"completed", "failed"}:
                db.execute(
                    "UPDATE automatic_jobs SET status='failed',completed_at=?,last_error=? "
                    "WHERE id=?",
                    (now, "Logically retired", job_id),
                )
            db.execute(
                "UPDATE job_management_state SET retired_at=?,revision=revision+1,"
                "pause_requested_at=NULL,pause_acknowledged_at=NULL,"
                "current_checkpoint='retired',updated_at=? WHERE job_id=?",
                (now, now, job_id),
            )
            if db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='job_incremental_policies'"
            ).fetchone():
                db.execute(
                    "UPDATE job_incremental_policies SET cadence='off',"
                    "next_eligible_at=NULL,updated_at=? WHERE job_id=?",
                    (now, job_id),
                )
            db.execute(
                "UPDATE job_execution_state SET current_job_id=NULL,updated_at=? "
                "WHERE singleton=1 AND current_job_id=? COLLATE NOCASE",
                (now, job_id),
            )
        return self.get_automatic_job(job_id)

    def rename_automatic_job(self, job_id: str, display_name: str) -> None:
        normalized = display_name.strip()
        if not normalized:
            raise ValidationError("Il nome del job e obbligatorio")
        if len(normalized) > 120:
            raise ValidationError("Il nome del job non puo superare 120 caratteri")
        if any(ord(character) < 32 for character in normalized):
            raise ValidationError("Il nome del job contiene caratteri di controllo")
        with self.transaction() as db:
            job = db.execute(
                "SELECT display_name FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            if job is None:
                raise CatalogError(f"Job automatico non trovato: {job_id}")
            db.execute(
                "UPDATE automatic_jobs SET display_name=? WHERE id=?",
                (normalized, job_id),
            )
            self._event(
                db,
                "automatic_job.rename",
                {
                    "job_id": job_id,
                    "old_name": job["display_name"],
                    "new_name": normalized,
                },
            )

    def delete_automatic_job(self, job_id: str) -> dict:
        """Delete scheduler state while preserving every catalogued tape and backup block."""

        with self._controlled_job_delete(), self.transaction() as db:
            job = db.execute(
                "SELECT * FROM automatic_jobs AS job WHERE id=? AND NOT EXISTS("
                "SELECT 1 FROM deleted_automatic_job_tombstones AS deleted "
                "WHERE deleted.job_id=job.id COLLATE NOCASE)",
                (job_id,),
            ).fetchone()
            if job is None:
                raise CatalogError(f"Job automatico non trovato: {job_id}")
            cassettes = list(
                db.execute(
                    "SELECT sequence, block_id FROM automatic_cassettes "
                    "WHERE job_id=? ORDER BY sequence",
                    (job_id,),
                )
            )
            library_count = int(
                db.execute(
                    "SELECT COUNT(*) FROM automatic_job_libraries WHERE job_id=?",
                    (job_id,),
                ).fetchone()[0]
            )
            failed_at = utc_now()
            if db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='job_incremental_policies'"
            ).fetchone():
                db.execute(
                    "UPDATE job_incremental_policies SET cadence='off',"
                    "next_eligible_at=NULL,updated_at=? WHERE job_id=?",
                    (failed_at, job_id),
                )
            failed_incomplete_blocks = 0
            for block_id in dict.fromkeys(
                row["block_id"] for row in cassettes if row["block_id"]
            ):
                cursor = db.execute(
                    "UPDATE blocks SET status='failed', completed_at=?, error=? "
                    "WHERE id=? AND status='copying'",
                    (
                        failed_at,
                        "Job eliminato dall'operatore prima del completamento",
                        block_id,
                    ),
                )
                if cursor.rowcount:
                    failed_incomplete_blocks += 1
                    db.execute(
                        "UPDATE file_versions SET visible=0 WHERE block_id=?",
                        (block_id,),
                    )
            db.execute("DELETE FROM job_management_history WHERE job_id=?", (job_id,))
            db.execute("DELETE FROM job_management_state WHERE job_id=?", (job_id,))
            db.execute(
                "DELETE FROM automatic_cassette_share_evidence_sets WHERE job_id=?",
                (job_id,),
            )
            db.execute(
                "DELETE FROM automatic_cassette_share_evidence WHERE job_id=?",
                (job_id,),
            )
            db.execute(
                "DELETE FROM automatic_job_share_evidence WHERE job_id=?", (job_id,)
            )
            db.execute(
                "DELETE FROM managed_source_job_fences WHERE job_id=?", (job_id,)
            )
            db.execute("DELETE FROM automatic_job_libraries WHERE job_id=?", (job_id,))
            owned_block_ids = tuple(
                str(row["block_id"])
                for row in db.execute(
                    "SELECT block_id FROM automatic_operation_blocks "
                    "WHERE job_id=? ORDER BY block_id",
                    (job_id,),
                )
            )
            self._archive_automatic_operation_blocks(
                db,
                owned_block_ids,
                disposition="job_deleted",
            )
            db.execute("DELETE FROM automatic_cassettes WHERE job_id=?", (job_id,))
            db.execute(
                "UPDATE job_execution_state SET current_job_id=NULL,updated_at=? "
                "WHERE current_job_id=?",
                (failed_at, job_id),
            )
            db.execute(
                "INSERT INTO deleted_automatic_job_tombstones(job_id,deleted_at) "
                "VALUES(?,?)",
                (job_id, failed_at),
            )
            result = {
                "id": job["id"],
                "display_name": job["display_name"],
                "deleted_cassettes": len(cassettes),
                "deleted_library_links": library_count,
                "failed_incomplete_blocks": failed_incomplete_blocks,
            }
            self._event(
                db,
                "automatic_job.delete",
                {
                    **result,
                    "tapes_deleted": 0,
                    "blocks_deleted": 0,
                    "tape_data_deleted": False,
                },
            )
            return result

    def append_automatic_cassettes(
        self,
        job_id: str,
        cassettes: list[tuple[str, str, int, int]],
        force_format: bool | None = None,
        *,
        allow_active: bool = False,
        allow_registered_reuse: bool = False,
    ) -> None:
        if not cassettes:
            raise ValidationError("Indicare almeno una nuova cassetta")
        now = utc_now()
        try:
            with self.transaction() as db:
                job = db.execute(
                    "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
                ).fetchone()
                if job is None:
                    raise CatalogError(f"Job automatico non trovato: {job_id}")
                allowed_statuses = (
                    {"completed", "failed", "planned", "paused", "waiting_media"}
                    if allow_active
                    else {"completed", "failed"}
                )
                if job["status"] not in allowed_statuses:
                    raise ValidationError(
                        "Le cassette si possono aggiungere solo a un job concluso o in pausa sicura"
                    )
                unfinished = db.execute(
                    "SELECT sequence FROM automatic_cassettes "
                    "WHERE job_id=? AND status<>'completed' "
                    "AND NOT(status='pending' AND planned_files=0 AND planned_bytes=0) "
                    "ORDER BY sequence LIMIT 1",
                    (job_id,),
                ).fetchone()
                if unfinished and not allow_active:
                    raise ValidationError(
                        f"La cassetta {unfinished['sequence']} non e completata; "
                        "risolvere prima la coda esistente"
                    )
                active_job = db.execute(
                    "SELECT id FROM automatic_jobs WHERE device_name=? COLLATE NOCASE "
                    "AND id<>? COLLATE NOCASE AND status NOT IN ('completed', 'failed') LIMIT 1",
                    (job["device_name"], job_id),
                ).fetchone()
                if active_job:
                    raise CatalogError(
                        f"Il drive {job['device_name']} ha gia il job non concluso {active_job['id']}"
                    )
                for physical_label, tape_serial, _files, _bytes in cassettes:
                    queued = db.execute(
                        "SELECT sequence FROM automatic_cassettes "
                        "WHERE job_id=? AND (physical_label=? COLLATE NOCASE OR tape_serial=? COLLATE NOCASE)",
                        (job_id, physical_label, tape_serial),
                    ).fetchone()
                    if queued:
                        raise CatalogError(
                            f"La cassetta {physical_label} e gia presente nella sequenza {queued['sequence']}"
                        )
                    registered = db.execute(
                        "SELECT id FROM tapes WHERE cassette_number=? COLLATE NOCASE OR id=? COLLATE NOCASE",
                        (physical_label, physical_label),
                    ).fetchone()
                    if registered and not allow_registered_reuse:
                        raise CatalogError(
                            f"La cassetta {physical_label} e gia registrata come {registered['id']}; "
                            "non viene riformattata per proteggere i backup catalogati"
                        )
                last_sequence = int(
                    db.execute(
                        "SELECT COALESCE(MAX(sequence), 0) FROM automatic_cassettes WHERE job_id=?",
                        (job_id,),
                    ).fetchone()[0]
                )
                db.executemany(
                    """
                    INSERT INTO automatic_cassettes(
                        job_id, sequence, physical_label, tape_serial, status,
                        planned_files, planned_bytes, reuse_registered
                    ) VALUES(?, ?, ?, ?, 'pending', ?, ?, ?)
                    """,
                    [
                        (
                            job_id,
                            last_sequence + offset,
                            physical_label,
                            tape_serial,
                            files,
                            size,
                            int(allow_registered_reuse),
                        )
                        for offset, (
                            physical_label,
                            tape_serial,
                            files,
                            size,
                        ) in enumerate(cassettes, 1)
                    ],
                )
                total = last_sequence + len(cassettes)
                db.execute(
                    """
                    UPDATE automatic_jobs
                    SET status='planned', total_cassettes=?, completed_at=NULL,
                        last_error=NULL, destructive_confirmed_at=?,
                        force_format=COALESCE(?, force_format)
                    WHERE id=?
                    """,
                    (
                        total,
                        now,
                        int(force_format) if force_format is not None else None,
                        job_id,
                    ),
                )
                self._event(
                    db,
                    "automatic_job.extend",
                    {
                        "job_id": job_id,
                        "first_sequence": last_sequence + 1,
                        "total_cassettes": total,
                        "labels": [row[0] for row in cassettes],
                        "force_format": force_format,
                        "active_queue_preserved": allow_active,
                        "allow_registered_reuse": allow_registered_reuse,
                    },
                )
        except sqlite3.IntegrityError as exc:
            raise CatalogError(
                f"Etichetta duplicata nel job automatico {job_id}"
            ) from exc

    def commit_registered_tape_reformat(
        self, job_id: str, sequence: int
    ) -> dict[str, int]:
        """Invalidate catalog records only after an authorized format has succeeded."""

        with self.transaction() as db:
            cassette = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (job_id, sequence),
            ).fetchone()
            if cassette is None:
                raise CatalogError(
                    f"Cassetta automatica non trovata: {job_id} sequenza {sequence}"
                )
            if not bool(cassette["reuse_registered"]):
                raise CatalogError(
                    f"La riformattazione della cassetta {cassette['physical_label']} "
                    "non e stata autorizzata"
                )
            if str(cassette["operation"] or "format") != "format":
                raise CatalogError(
                    "Una cassetta registrata si puo invalidare solo dopo la formattazione"
                )

            replay = self._registered_tape_reformat_receipt_tx(
                db,
                job_id=job_id,
                sequence=sequence,
                physical_label=str(cassette["physical_label"]),
            )
            if replay is not None:
                return replay
            resolution, tape = self._resolve_registered_tape_label_tx(
                db, str(cassette["physical_label"])
            )
            if resolution == "ambiguous":
                raise CatalogError("registered_tape_identity_ambiguous")
            if resolution == "missing":
                raise CatalogError("registered_tape_identity_missing")
            assert tape is not None
            tape_id = str(tape["id"])
            cassette_number = str(tape["cassette_number"])
            affected = list(
                db.execute(
                    """
                    SELECT DISTINCT job_id
                    FROM automatic_cassettes
                    WHERE NOT(job_id=? AND sequence=?)
                      AND (
                        tape_id=? COLLATE NOCASE
                        OR physical_label=? COLLATE NOCASE
                        OR physical_label=? COLLATE NOCASE
                      )
                    """,
                    (job_id, sequence, tape_id, cassette_number, tape_id),
                )
            )
            affected_job_ids = [str(row["job_id"]) for row in affected]
            reason = (
                f"Dati invalidati: cassetta {cassette_number} riformattata "
                f"dal job {job_id}"
            )
            db.execute(
                """
                UPDATE automatic_cassettes
                SET status='failed', tape_id=NULL, block_id=NULL,
                    copied_files=0, copied_bytes=0, error=?
                WHERE NOT(job_id=? AND sequence=?)
                  AND (
                    tape_id=? COLLATE NOCASE
                    OR physical_label=? COLLATE NOCASE
                    OR physical_label=? COLLATE NOCASE
                  )
                """,
                (reason, job_id, sequence, tape_id, cassette_number, tape_id),
            )
            if affected_job_ids:
                placeholders = ", ".join("?" for _ in affected_job_ids)
                db.execute(
                    f"UPDATE automatic_jobs SET status='failed', completed_at=NULL, "
                    f"last_error=? WHERE id IN ({placeholders})",
                    (reason, *affected_job_ids),
                )

            invalidated = self._invalidate_tape_catalog_for_lifecycle(
                db,
                tape_id,
                disposition="registered_tape_reformatted",
            )
            result = {
                **invalidated,
                "jobs": len(affected_job_ids),
            }
            self._event(
                db,
                "tape.reformat.catalog_invalidated",
                {
                    "job_id": job_id,
                    "sequence": sequence,
                    "physical_label": cassette["physical_label"],
                    "tape_id": tape_id,
                    **result,
                },
            )
            return result

    def list_automatic_jobs(self) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT * FROM automatic_jobs AS job WHERE NOT EXISTS("
                "SELECT 1 FROM deleted_automatic_job_tombstones AS deleted "
                "WHERE deleted.job_id=job.id COLLATE NOCASE) "
                "ORDER BY created_at DESC"
            )
        )

    def list_automatic_cassettes(self, job_id: str) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? ORDER BY sequence",
                (job_id,),
            )
        )

    def replace_automatic_cassette_manifest(
        self,
        job_id: str,
        sequence: int,
        items: list[tuple[str, str, int, int]],
    ) -> None:
        """Atomically freeze the exact paths assigned to one cassette."""

        normalized: list[tuple[str, str, int, int]] = []
        seen: set[tuple[str, str]] = set()
        for library_id, relative_path, size, mtime_ns in items:
            path = str(PurePosixPath(relative_path.replace("\\", "/"))).strip("/")
            if not path or path == "." or PurePosixPath(path).is_absolute():
                raise ValidationError(f"Percorso manifest non valido: {relative_path}")
            key = (library_id.casefold(), path.casefold())
            if key in seen:
                raise ValidationError(
                    f"Percorso duplicato nel manifest: {library_id}/{path}"
                )
            if int(size) < 0 or int(mtime_ns) < 0:
                raise ValidationError(
                    f"Metadati manifest non validi: {library_id}/{path}"
                )
            seen.add(key)
            normalized.append((library_id, path, int(size), int(mtime_ns)))

        with self.transaction() as db:
            cassette = db.execute(
                "SELECT planned_files, planned_bytes FROM automatic_cassettes "
                "WHERE job_id=? AND sequence=?",
                (job_id, int(sequence)),
            ).fetchone()
            if cassette is None:
                raise CatalogError(f"Cassetta {sequence} non trovata nel job {job_id}")
            if normalized and (
                len(normalized) != int(cassette["planned_files"])
                or sum(row[2] for row in normalized) != int(cassette["planned_bytes"])
            ):
                raise ValidationError(
                    f"Il manifest della cassetta {sequence} non coincide con il piano aggregato"
                )
            db.execute(
                "DELETE FROM automatic_cassette_items WHERE job_id=? AND sequence=?",
                (job_id, int(sequence)),
            )
            item_columns = {
                str(row["name"])
                for row in db.execute("PRAGMA table_info(automatic_cassette_items)")
            }
            if "tape_relative_path" in item_columns:
                db.executemany(
                    "INSERT INTO automatic_cassette_items("
                    "job_id, sequence, item_sequence, library_id, relative_path, "
                    "tape_relative_path, size, mtime_ns) "
                    "VALUES(?, ?, ?, ?, ?, ?, ?, ?)",
                    [
                        (
                            job_id,
                            int(sequence),
                            index,
                            library_id,
                            path,
                            ltfs_tape_relative_path(path),
                            size,
                            mtime_ns,
                        )
                        for index, (library_id, path, size, mtime_ns) in enumerate(
                            normalized, 1
                        )
                    ],
                )
            else:
                db.executemany(
                    "INSERT INTO automatic_cassette_items("
                    "job_id, sequence, item_sequence, library_id, relative_path, "
                    "size, mtime_ns) VALUES(?, ?, ?, ?, ?, ?, ?)",
                    [
                        (job_id, int(sequence), index, library_id, path, size, mtime_ns)
                        for index, (library_id, path, size, mtime_ns) in enumerate(
                            normalized, 1
                        )
                    ],
                )
            self._event(
                db,
                "automatic_cassette.manifest",
                {
                    "job_id": job_id,
                    "sequence": int(sequence),
                    "files": len(normalized),
                    "bytes": sum(row[2] for row in normalized),
                },
            )

    def list_automatic_cassette_manifest(
        self, job_id: str, sequence: int
    ) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT * FROM automatic_cassette_items "
                "WHERE job_id=? AND sequence=? ORDER BY item_sequence",
                (job_id, int(sequence)),
            )
        )

    def list_pending_automatic_manifest(self, job_id: str) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT item.* FROM automatic_cassette_items item "
                "JOIN automatic_cassettes cassette "
                "ON cassette.job_id=item.job_id AND cassette.sequence=item.sequence "
                "WHERE item.job_id=? AND cassette.status<>'completed' "
                "ORDER BY item.sequence, item.item_sequence",
                (job_id,),
            )
        )

    def replace_automatic_pending_plan(
        self,
        job_id: str,
        assignments: list[tuple[int, list[tuple[str, str, int, int]]]],
    ) -> None:
        """Atomically freeze every not-yet-completed cassette of a legacy job."""

        assignment_map = {int(sequence): items for sequence, items in assignments}
        with self.transaction() as db:
            rows = list(
                db.execute(
                    "SELECT sequence FROM automatic_cassettes "
                    "WHERE job_id=? AND status<>'completed' ORDER BY sequence",
                    (job_id,),
                )
            )
            known = {int(row["sequence"]) for row in rows}
            if set(assignment_map) != known:
                raise ValidationError(
                    "Il piano persistente deve coprire tutte le cassette non completate"
                )
            db.execute(
                "DELETE FROM automatic_cassette_items WHERE job_id=? "
                "AND sequence IN (SELECT sequence FROM automatic_cassettes "
                "WHERE job_id=? AND status<>'completed')",
                (job_id, job_id),
            )
            inserted = 0
            total_bytes = 0
            for row in rows:
                sequence = int(row["sequence"])
                items = assignment_map[sequence]
                db.execute(
                    "UPDATE automatic_cassettes SET planned_files=?, planned_bytes=? "
                    "WHERE job_id=? AND sequence=?",
                    (len(items), sum(int(item[2]) for item in items), job_id, sequence),
                )
                for item_sequence, (library_id, path, size, mtime_ns) in enumerate(
                    items, 1
                ):
                    normalized_path = path.replace("\\", "/").strip("/")
                    item_columns = {
                        str(column["name"])
                        for column in db.execute(
                            "PRAGMA table_info(automatic_cassette_items)"
                        )
                    }
                    if "tape_relative_path" in item_columns:
                        db.execute(
                            "INSERT INTO automatic_cassette_items("
                            "job_id,sequence,item_sequence,library_id,relative_path,"
                            "tape_relative_path,size,mtime_ns) VALUES(?,?,?,?,?,?,?,?)",
                            (
                                job_id,
                                sequence,
                                item_sequence,
                                library_id,
                                normalized_path,
                                ltfs_tape_relative_path(normalized_path),
                                int(size),
                                int(mtime_ns),
                            ),
                        )
                    else:
                        db.execute(
                            "INSERT INTO automatic_cassette_items("
                            "job_id,sequence,item_sequence,library_id,relative_path,"
                            "size,mtime_ns) VALUES(?,?,?,?,?,?,?)",
                            (
                                job_id,
                                sequence,
                                item_sequence,
                                library_id,
                                normalized_path,
                                int(size),
                                int(mtime_ns),
                            ),
                        )
                    inserted += 1
                    total_bytes += int(size)
            self._event(
                db,
                "automatic_job.manifest.freeze",
                {
                    "job_id": job_id,
                    "cassettes": len(rows),
                    "files": inserted,
                    "bytes": total_bytes,
                },
            )

    def list_automatic_job_libraries(self, job_id: str) -> list[sqlite3.Row]:
        return list(
            self.connection.execute(
                "SELECT * FROM automatic_job_libraries WHERE job_id=? ORDER BY sequence",
                (job_id,),
            )
        )

    def next_automatic_cassette(self, job_id: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT * FROM automatic_cassettes "
            "WHERE job_id=? AND status<>'completed' "
            "AND (planned_files>0 OR planned_bytes>0) "
            "ORDER BY sequence LIMIT 1",
            (job_id,),
        ).fetchone()

    def advance_automatic_job_after_eject(
        self, job_id: str, completed_sequence: int
    ) -> int | None:
        """Atomically expose the exact next data-bearing cassette after eject."""

        self._validate_safe_identifier(job_id, "automatic job ID")
        if type(completed_sequence) is not int or completed_sequence < 1:
            raise ValidationError("invalid completed cassette sequence")
        now = utc_now()
        with self.transaction() as db:
            db.execute(
                "INSERT OR IGNORE INTO automatic_sequence_state("
                "job_id,state,layout_epoch,layout_fingerprint_sha256,revision,"
                "enabled_by,enabled_at,updated_at) "
                "SELECT job.id,'disabled',epoch.epoch_number,"
                "epoch.layout_fingerprint_sha256,1,NULL,NULL,? "
                "FROM automatic_jobs AS job "
                "JOIN job_layout_epochs AS epoch ON epoch.job_id=job.id "
                "WHERE job.id=? AND epoch.epoch_number=(SELECT MAX(current.epoch_number) "
                "FROM job_layout_epochs AS current WHERE current.job_id=job.id) "
                "AND NOT EXISTS(SELECT 1 FROM imported_job_policies AS imported "
                "WHERE imported.job_id=job.id COLLATE NOCASE)",
                (now, job_id),
            )
            job = db.execute(
                "SELECT current_sequence,status FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            cassette = db.execute(
                "SELECT status FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (job_id, completed_sequence),
            ).fetchone()
            state = db.execute(
                "SELECT state,layout_epoch,layout_fingerprint_sha256 "
                "FROM automatic_sequence_state WHERE job_id=?", (job_id,)
            ).fetchone()
            if job is None or cassette is None or state is None:
                raise CatalogError("automatic_sequence_checkpoint_not_found")
            if int(job["current_sequence"]) != completed_sequence:
                raise CatalogError("automatic_sequence_current_cassette_mismatch")
            if job["status"] == "completed":
                raise CatalogError("automatic_sequence_checkpoint_already_completed")
            if job["status"] not in {"waiting_media", *_OPERATION_PHASES}:
                raise CatalogError("automatic_sequence_checkpoint_state_conflict")
            if cassette["status"] != "completed":
                raise CatalogError("automatic_sequence_completed_cassette_required")

            next_cassette = db.execute(
                "SELECT sequence,status FROM automatic_cassettes "
                "WHERE job_id=? AND sequence>? "
                "AND (planned_files>0 OR planned_bytes>0) "
                "ORDER BY sequence LIMIT 1",
                (job_id, completed_sequence),
            ).fetchone()
            if next_cassette is None:
                cursor = db.execute(
                    "UPDATE automatic_jobs SET status='completed',current_sequence=?,"
                    "completed_at=?,last_error=NULL WHERE id=? AND current_sequence=? "
                    "AND status<>'completed'",
                    (completed_sequence, now, job_id, completed_sequence),
                )
                if cursor.rowcount != 1:
                    raise CatalogError("automatic_sequence_checkpoint_already_completed")
                state_cursor = db.execute(
                    "UPDATE automatic_sequence_state SET state='completed',updated_at=? "
                    "WHERE job_id=?",
                    (now, job_id),
                )
                if state_cursor.rowcount != 1:
                    raise CatalogError("automatic_sequence_checkpoint_not_found")
                self._record_audit_tx(
                    db, "system", "automatic.sequence.terminal_stopped", "accepted",
                    f"sequence-stop-{uuid.uuid4().hex}", None,
                    json.dumps({
                        "job_id": job_id,
                        "layout_epoch": int(state["layout_epoch"]),
                        "layout_fingerprint_sha256": str(state["layout_fingerprint_sha256"]),
                        "sequence": completed_sequence,
                        "reason": "completed",
                    }, separators=(",", ":"), sort_keys=True),
                )
                return None
            if next_cassette["status"] != "pending":
                raise CatalogError("automatic_sequence_next_cassette_not_pending")

            next_sequence = int(next_cassette["sequence"])
            db.execute(
                "UPDATE automatic_cassettes SET status='waiting_media',error=NULL "
                "WHERE job_id=? AND sequence=? AND status='pending'",
                (job_id, next_sequence),
            )
            cursor = db.execute(
                "UPDATE automatic_jobs SET status='waiting_media',current_sequence=?,"
                "completed_at=NULL,last_error=NULL WHERE id=? AND current_sequence=?",
                (next_sequence, job_id, completed_sequence),
            )
            if cursor.rowcount != 1:
                raise CatalogError("automatic_sequence_current_cassette_mismatch")
            db.execute(
                "UPDATE automatic_sequence_state SET updated_at=? WHERE job_id=?",
                (now, job_id),
            )
            return next_sequence

    def completed_tape_bytes(self, tape_id: str) -> int:
        """Return committed payload bytes for an offline capacity estimate."""

        row = self.connection.execute(
            "SELECT COALESCE(SUM(copied_bytes), 0) FROM blocks "
            "WHERE tape_id=? AND status='completed'",
            (tape_id,),
        ).fetchone()
        return max(0, int(row[0]))

    def completed_tape_file_layout(self, tape_id: str) -> list[sqlite3.Row]:
        """Return every committed physical file and its block for capacity estimates."""
        return list(
            self.connection.execute(
                """
                SELECT fv.block_id, fv.size
                FROM file_versions fv
                JOIN blocks b ON b.id=fv.block_id
                WHERE fv.tape_id=? AND b.status='completed'
                ORDER BY fv.id
                """,
                (tape_id,),
            )
        )

    def activate_automatic_append(
        self,
        job_id: str,
        sequence: int,
        planned_files: int,
        planned_bytes: int,
    ) -> None:
        """Reuse a completed cassette for one non-destructive incremental cycle."""

        if planned_files <= 0 or planned_bytes <= 0:
            raise ValidationError("Il ciclo append richiede almeno un file e un byte")
        with self.transaction() as db:
            cassette = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (job_id, sequence),
            ).fetchone()
            if cassette is None:
                raise CatalogError(f"Cassetta {sequence} non trovata nel job {job_id}")
            if cassette["status"] != "completed" or not cassette["tape_id"]:
                raise ValidationError(
                    "Solo una cassetta completata e registrata puo essere riaperta in append"
                )
            tape = db.execute(
                "SELECT id FROM tapes WHERE id=? AND status='active'",
                (cassette["tape_id"],),
            ).fetchone()
            if tape is None:
                raise CatalogError(
                    f"Il nastro catalogato {cassette['tape_id']} non e disponibile per l'append"
                )
            db.execute(
                """
                UPDATE automatic_cassettes
                SET status='pending', operation='append', planned_files=?, planned_bytes=?,
                    copied_files=0, copied_bytes=0, block_id=NULL,
                    started_at=NULL, completed_at=NULL, error=NULL
                WHERE job_id=? AND sequence=?
                """,
                (planned_files, planned_bytes, job_id, sequence),
            )
            db.execute(
                """
                UPDATE automatic_jobs
                SET status='planned', current_sequence=?, completed_at=NULL, last_error=NULL
                WHERE id=?
                """,
                (sequence, job_id),
            )
            self._event(
                db,
                "automatic_job.append.activate",
                {
                    "job_id": job_id,
                    "sequence": sequence,
                    "physical_label": cassette["physical_label"],
                    "planned_files": planned_files,
                    "planned_bytes": planned_bytes,
                },
            )

    def activate_automatic_reserves(
        self,
        job_id: str,
        assignments: list[tuple[int, int]],
        *,
        current_sequence: int | None = None,
    ) -> None:
        if not assignments:
            return
        with self.transaction() as db:
            job = db.execute(
                "SELECT id FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            if job is None:
                raise CatalogError(f"Job automatico non trovato: {job_id}")
            reserves = list(
                db.execute(
                    "SELECT sequence FROM automatic_cassettes "
                    "WHERE job_id=? AND status='pending' "
                    "AND planned_files=0 AND planned_bytes=0 "
                    "ORDER BY sequence",
                    (job_id,),
                )
            )
            if len(assignments) > len(reserves):
                raise ValidationError(
                    f"Il job {job_id} non dispone di cassette di riserva sufficienti"
                )
            for reserve, (planned_files, planned_bytes) in zip(reserves, assignments):
                db.execute(
                    "UPDATE automatic_cassettes SET operation='format', "
                    "planned_files=?, planned_bytes=? "
                    "WHERE job_id=? AND sequence=?",
                    (planned_files, planned_bytes, job_id, reserve["sequence"]),
                )
            first_sequence = (
                int(current_sequence)
                if current_sequence is not None
                else int(reserves[0]["sequence"])
            )
            db.execute(
                "UPDATE automatic_jobs SET status='planned', current_sequence=?, "
                "completed_at=NULL, last_error=NULL WHERE id=?",
                (first_sequence, job_id),
            )
            self._event(
                db,
                "automatic_job.reserve.activate",
                {
                    "job_id": job_id,
                    "first_sequence": first_sequence,
                    "activated_cassettes": len(assignments),
                },
            )

    def reserve_remaining_automatic_cassettes(
        self, job_id: str, after_sequence: int
    ) -> int:
        with self.transaction() as db:
            cursor = db.execute(
                "UPDATE automatic_cassettes SET planned_files=0, planned_bytes=0 "
                "WHERE job_id=? AND sequence>? AND status='pending'",
                (job_id, after_sequence),
            )
            released = max(0, cursor.rowcount)
            if released:
                self._event(
                    db,
                    "automatic_job.reserve.release",
                    {
                        "job_id": job_id,
                        "after_sequence": after_sequence,
                        "reserved_cassettes": released,
                    },
                )
            return released

    def update_automatic_job(
        self,
        job_id: str,
        status: str,
        *,
        current_sequence: int | None = None,
        error: str | None = None,
    ) -> None:
        allowed = {
            "planned",
            "pending",
            "waiting_media",
            "formatting",
            *_OPERATION_PHASES,
            "paused",
            "completed",
            "failed",
        }
        if status not in allowed:
            raise ValidationError(f"Stato job automatico non valido: {status}")
        now = utc_now()
        with self.transaction() as db:
            schema_version = int(
                db.execute(
                    "SELECT value FROM metadata WHERE key='schema_version'"
                ).fetchone()[0]
            )
            stored_status = (
                "formatting_media"
                if schema_version >= 14 and status == "formatting"
                else status
            )
            cursor = db.execute(
                """
                UPDATE automatic_jobs SET status=?,
                    current_sequence=COALESCE(?, current_sequence),
                    started_at=CASE WHEN started_at IS NULL AND ?<>'planned' THEN ? ELSE started_at END,
                    completed_at=CASE WHEN ?='completed' THEN ? ELSE completed_at END,
                    last_error=?
                WHERE id=?
                """,
                (
                    stored_status,
                    current_sequence,
                    stored_status,
                    now,
                    stored_status,
                    now,
                    error[:4000] if error else None,
                    job_id,
                ),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"Job automatico non trovato: {job_id}")
            self._event(
                db,
                "automatic_job.state",
                {
                    "job_id": job_id,
                    "status": stored_status,
                    "sequence": current_sequence,
                    "error": error,
                },
            )

    def update_automatic_cassette(
        self,
        job_id: str,
        sequence: int,
        status: str,
        *,
        tape_id: str | None = None,
        block_id: str | None = None,
        copied_files: int | None = None,
        copied_bytes: int | None = None,
        error: str | None = None,
    ) -> None:
        allowed = {
            "pending",
            "waiting_media",
            "formatting",
            *_OPERATION_PHASES,
            "paused",
            "completed",
            "failed",
        }
        if status not in allowed:
            raise ValidationError(f"Stato cassetta automatico non valido: {status}")
        now = utc_now()
        with self.transaction() as db:
            schema_version = int(
                db.execute(
                    "SELECT value FROM metadata WHERE key='schema_version'"
                ).fetchone()[0]
            )
            stored_status = (
                "formatting_media"
                if schema_version >= 14 and status == "formatting"
                else status
            )
            cursor = db.execute(
                """
                UPDATE automatic_cassettes SET status=?,
                    tape_id=COALESCE(?, tape_id), block_id=COALESCE(?, block_id),
                    copied_files=COALESCE(?, copied_files), copied_bytes=COALESCE(?, copied_bytes),
                    started_at=CASE WHEN started_at IS NULL AND ?<>'pending' THEN ? ELSE started_at END,
                    completed_at=CASE WHEN ?='completed' THEN ? ELSE completed_at END,
                    error=?
                WHERE job_id=? AND sequence=?
                """,
                (
                    stored_status,
                    tape_id,
                    block_id,
                    copied_files,
                    copied_bytes,
                    stored_status,
                    now,
                    stored_status,
                    now,
                    error[:4000] if error else None,
                    job_id,
                    sequence,
                ),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"Cassetta {sequence} non trovata nel job {job_id}")
            if status == "completed":
                if schema_version >= 27:
                    db.execute(
                        "INSERT OR IGNORE INTO job_manifest_history("
                        "job_id,revision,cassette_sequence,item_sequence,library_id,"
                        "relative_path,size,mtime_ns) "
                        "SELECT item.job_id,state.revision,item.sequence,item.item_sequence,"
                        "item.library_id,item.relative_path,item.size,item.mtime_ns "
                        "FROM automatic_cassette_items item "
                        "JOIN job_management_state state ON state.job_id=item.job_id "
                        "WHERE item.job_id=? AND item.sequence=? "
                        "AND NOT EXISTS (SELECT 1 FROM imported_job_policies "
                        "WHERE job_id=?)",
                        (job_id, sequence, job_id),
                    )
                if schema_version >= 14:
                    db.execute(
                        "DELETE FROM automatic_cassette_items "
                        "WHERE job_id=? AND sequence=? "
                        "AND NOT EXISTS (SELECT 1 FROM imported_job_policies "
                        "WHERE job_id=?)",
                        (job_id, sequence, job_id),
                    )
                else:
                    db.execute(
                        "DELETE FROM automatic_cassette_items "
                        "WHERE job_id=? AND sequence=?",
                        (job_id, sequence),
                    )
            self._event(
                db,
                "automatic_cassette.state",
                {
                    "job_id": job_id,
                    "sequence": sequence,
                    "status": stored_status,
                    "error": error,
                },
            )

    def reset_automatic_cassette(
        self,
        job_id: str,
        sequence: int,
        reason: str,
    ) -> dict[str, int]:
        """Discard one interrupted tape attempt so it can be reformatted from scratch."""

        with self.transaction() as db:
            cassette = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (job_id, sequence),
            ).fetchone()
            if cassette is None:
                raise CatalogError(f"Cassetta {sequence} non trovata nel job {job_id}")
            if cassette["status"] == "completed":
                raise ValidationError("Una cassetta completata non puo essere azzerata")

            if cassette["operation"] == "append":
                failed_at = utc_now()
                block_ids = [
                    value.strip()
                    for value in str(cassette["block_id"] or "").split(",")
                    if value.strip()
                ]
                for block_id in block_ids:
                    db.execute(
                        "UPDATE blocks SET status='failed', visible=0, completed_at=?, error=? "
                        "WHERE id=? AND status='copying'",
                        (failed_at, reason[:4000], block_id),
                    )
                    db.execute(
                        "UPDATE file_versions SET visible=0 WHERE block_id=?",
                        (block_id,),
                    )
                db.execute(
                    """
                    UPDATE automatic_cassettes
                    SET status='pending', block_id=NULL, copied_files=0, copied_bytes=0,
                        started_at=NULL, completed_at=NULL, error=NULL
                    WHERE job_id=? AND sequence=?
                    """,
                    (job_id, sequence),
                )
                db.execute(
                    """
                    UPDATE automatic_jobs
                    SET status='paused', current_sequence=?, completed_at=NULL, last_error=NULL
                    WHERE id=?
                    """,
                    (sequence, job_id),
                )
                result = {"blocks": 0, "files": 0, "tapes": 0}
                self._event(
                    db,
                    "automatic_cassette.append.reset",
                    {
                        "job_id": job_id,
                        "sequence": sequence,
                        "physical_label": cassette["physical_label"],
                        "reason": reason[:1000],
                        "preserved_tape": cassette["tape_id"],
                    },
                )
                return result

            tape_id = cassette["tape_id"] or cassette["physical_label"]
            tape = db.execute("SELECT * FROM tapes WHERE id=?", (tape_id,)).fetchone()
            if tape is not None and (
                str(tape["cassette_number"]).casefold()
                != str(cassette["physical_label"]).casefold()
            ):
                raise CatalogError(
                    f"Il nastro {tape_id} non corrisponde alla cassetta "
                    f"{cassette['physical_label']}"
                )

            invalidated = self._invalidate_tape_catalog_for_lifecycle(
                db,
                tape_id,
                disposition="registered_tape_reset",
            )
            db.execute(
                """
                UPDATE automatic_cassettes
                SET status='pending', tape_id=NULL, block_id=NULL,
                    copied_files=0, copied_bytes=0, started_at=NULL,
                    completed_at=NULL, error=NULL
                WHERE job_id=? AND sequence=?
                """,
                (job_id, sequence),
            )
            cursor = db.execute(
                """
                UPDATE automatic_jobs
                SET status='paused', current_sequence=?, completed_at=NULL, last_error=NULL
                WHERE id=?
                """,
                (sequence, job_id),
            )
            if cursor.rowcount != 1:
                raise CatalogError(f"Job automatico non trovato: {job_id}")
            result = invalidated
            self._event(
                db,
                "automatic_cassette.reset",
                {
                    "job_id": job_id,
                    "sequence": sequence,
                    "physical_label": cassette["physical_label"],
                    "reason": reason[:1000],
                    **result,
                },
            )
            return result

    def reset_automatic_cassette_for_recovery(
        self,
        fence: RecoveryCommandFence,
        reason: str,
        *,
        replacement_candidate: OperationRecord | None = None,
    ) -> dict[str, object]:
        """Atomically invalidate one exact, freshly observed native checkpoint."""

        if type(fence) is not RecoveryCommandFence:
            raise TypeError("an exact recovery command fence is required")
        if replacement_candidate is not None:
            self._validate_candidate(replacement_candidate)
        with self.transaction() as db:
            operation = self._assert_command_fence_tx(db, fence)
            job_id = operation["job_id"]
            sequence = operation["cassette_sequence"]
            if (
                operation["kind"] != "archive.native"
                or type(job_id) is not str
                or type(sequence) is not int
            ):
                raise ValidationError("native recovery checkpoint is not exact")
            lineage = db.execute(
                "SELECT * FROM operation_recovery_lineages WHERE operation_id=? "
                "ORDER BY recovery_generation DESC LIMIT 1",
                (fence.operation_id,),
            ).fetchone()
            cassette = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (job_id, sequence),
            ).fetchone()
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            binding = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            probe = db.execute(
                "SELECT * FROM hardware_command_executions WHERE operation_id=? "
                "ORDER BY created_at DESC,id DESC LIMIT 1",
                (fence.operation_id,),
            ).fetchone()
            if (
                lineage is None
                or lineage["recovery_generation"] != fence.owner_generation
                or lineage["original_generation"] != operation["owner_generation"]
                or cassette is None
                or cassette["status"] == "completed"
                or cassette["operation"] not in {"format", "append"}
                or target is None
                or binding is None
                or probe is None
                or probe["issued_generation"] != fence.owner_generation
                or probe["command_kind"] != "probe_media"
                or probe["state"] != "quiesced"
                or probe["exit_outcome"] != "completed"
                or probe["created_at"] < lineage["recorded_at"]
                or probe["observed_media_identity_sha256"]
                != binding["observed_media_identity_sha256"]
                or any(
                    probe[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
            ):
                raise ValidationError("native recovery media proof is unavailable")
            format_allowed = cassette["operation"] == "format"
            confirmation = None
            sequence_authorization = db.execute(
                "SELECT * FROM operation_format_authorizations WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if format_allowed:
                confirmation = db.execute(
                    "SELECT * FROM format_confirmations WHERE operation_id=?",
                    (fence.operation_id,),
                ).fetchone()
                if (
                    confirmation is None
                    or confirmation["job_id"] != job_id
                    or confirmation["cassette_sequence"] != sequence
                    or confirmation["expected_label"] != cassette["physical_label"]
                ):
                    raise ValidationError(
                        "native recovery format authorization is unavailable"
                    )
            elif sequence_authorization is not None:
                raise ValidationError(
                    "native recovery sequence authorization is unavailable"
                )

            block_count = file_count = tape_count = 0
            if cassette["operation"] == "append":
                failed_at = self._precise_utc_now(after=probe["quiesced_at"])
                expected_tape_id = cassette["tape_id"] or cassette["physical_label"]
                mapped = tuple(
                    db.execute(
                        "SELECT binding.block_id,block.tape_id,block.status "
                        "FROM automatic_operation_blocks binding "
                        "JOIN blocks block ON block.id=binding.block_id "
                        "WHERE binding.operation_id=? AND binding.job_id=? "
                        "AND binding.cassette_sequence=? ORDER BY binding.block_id",
                        (fence.operation_id, job_id, sequence),
                    )
                )
                if any(row["tape_id"] != expected_tape_id for row in mapped):
                    raise ValidationError(
                        "native recovery provisional block tape is inexact"
                    )
                provisional_ids = tuple(
                    str(row["block_id"])
                    for row in mapped
                    if row["status"] == "copying"
                )
                all_copying_ids = tuple(
                    str(row["id"])
                    for row in db.execute(
                        "SELECT id FROM blocks WHERE tape_id=? AND status='copying' "
                        "ORDER BY id",
                        (expected_tape_id,),
                    )
                )
                if provisional_ids != all_copying_ids:
                    raise ValidationError(
                        "native recovery provisional block mapping is incomplete"
                    )
                for block_id in provisional_ids:
                    cursor = db.execute(
                        "UPDATE blocks SET status='failed',visible=0,completed_at=?,"
                        "error=? WHERE id=? AND status='copying'",
                        (failed_at, reason[:4000], block_id),
                    )
                    if cursor.rowcount != 1:
                        raise ValidationError(
                            "native recovery provisional block changed"
                        )
                    db.execute(
                        "UPDATE file_versions SET visible=0 WHERE block_id=?",
                        (block_id,),
                    )
                    block_count += 1
            else:
                tape_id = cassette["tape_id"] or cassette["physical_label"]
                tape = db.execute(
                    "SELECT * FROM tapes WHERE id=?", (tape_id,)
                ).fetchone()
                if tape is not None and (
                    str(tape["cassette_number"]).casefold()
                    != str(cassette["physical_label"]).casefold()
                ):
                    raise ValidationError("native recovery tape identity conflicts")
                invalidated = self._invalidate_tape_catalog_for_lifecycle(
                    db,
                    tape_id,
                    disposition="registered_tape_recovery_reset",
                )
                block_count = invalidated["blocks"]
                file_count = invalidated["files"]
                tape_count = invalidated["tapes"]
            db.execute(
                "UPDATE automatic_cassettes SET status='pending',"
                "tape_id=CASE WHEN operation='format' THEN NULL ELSE tape_id END,"
                "block_id=NULL,copied_files=0,copied_bytes=0,started_at=NULL,"
                "completed_at=NULL,error=NULL WHERE job_id=? AND sequence=?",
                (job_id, sequence),
            )
            db.execute(
                "UPDATE automatic_jobs SET status='paused',current_sequence=?,"
                "completed_at=NULL,last_error=NULL WHERE id=?",
                (sequence, job_id),
            )
            finished_at = self._precise_utc_now(after=probe["quiesced_at"])
            db.execute(
                "UPDATE daemon_operations SET state='cancelled',finished_at=?,"
                "error_class=NULL,error_code=NULL,error_message=NULL WHERE id=?",
                (finished_at, fence.operation_id),
            )
            replacement = None
            if replacement_candidate is not None:
                replacement = self._insert_native_recovery_replacement_tx(
                    db,
                    operation,
                    cassette,
                    target,
                    confirmation,
                    sequence_authorization,
                    fence,
                    replacement_candidate,
                    finished_at,
                )
            self._event(
                db,
                "automatic_cassette.recovery_reset",
                {
                    "job_id": job_id,
                    "sequence": sequence,
                    "physical_label": cassette["physical_label"],
                    "operation": cassette["operation"],
                    "reason": reason[:1000],
                    "replaces_operation_id": fence.operation_id,
                    "replacement_operation_id": (
                        None if replacement is None else replacement.id
                    ),
                },
            )
            return {
                "operation": str(cassette["operation"]),
                "format_allowed": format_allowed,
                "blocks": block_count,
                "files": file_count,
                "tapes": tape_count,
                "replacement": replacement,
            }

    def _insert_native_recovery_replacement_tx(
        self,
        db: sqlite3.Connection,
        original: sqlite3.Row,
        cassette: sqlite3.Row,
        target: sqlite3.Row,
        confirmation: sqlite3.Row | None,
        sequence_authorization: sqlite3.Row | None,
        fence: RecoveryCommandFence,
        candidate: OperationRecord,
        admitted_at: str,
    ) -> OperationRecord:
        if (
            candidate.id == fence.operation_id
            or candidate.kind != "archive.native"
            or candidate.state != "running"
            or candidate.phase is not None
            or candidate.finished_at is not None
            or candidate.principal != original["principal"]
            or candidate.job_id != original["job_id"]
            or candidate.cassette_sequence != original["cassette_sequence"]
            or candidate.error_class is not None
            or candidate.error_code is not None
            or candidate.error_message is not None
        ):
            raise ValidationError("native recovery replacement is not exact")
        if original["copy_buffer_bytes"] is None:
            raise ValidationError("native recovery admission snapshot is unavailable")
        active = db.execute(
            "SELECT id FROM daemon_operations WHERE state IN "
            "('running','recovery_required') LIMIT 1"
        ).fetchone()
        if active is not None:
            raise OperationConflict(self._operation_from_row(db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (active["id"],)
            ).fetchone()))
        db.execute(
            "INSERT INTO daemon_operations("
            "id,kind,state,phase,idempotency_key,principal,owner_generation,"
            "job_id,cassette_sequence,started_at,finished_at,error_class,"
            "error_code,error_message,copy_buffer_bytes) "
            "VALUES(?,?,'running',NULL,?,?,?,?,?,?,NULL,NULL,NULL,NULL,?)",
            (
                candidate.id,
                candidate.kind,
                candidate.idempotency_key,
                candidate.principal,
                fence.owner_generation,
                candidate.job_id,
                candidate.cassette_sequence,
                admitted_at,
                int(original["copy_buffer_bytes"]),
            ),
        )
        db.execute(
            "INSERT INTO native_recovery_dispatches("
            "operation_id,owner_generation,state,admitted_at) "
            "VALUES(?,?,'admitted',?)",
            (candidate.id, fence.owner_generation, admitted_at),
        )
        binding = HardwareTargetBinding(
            mount_path_sha256=str(target["mount_path_sha256"]),
            tape_device_identity_sha256=str(
                target["tape_device_identity_sha256"]
            ),
            scsi_device_identity_sha256=str(
                target["scsi_device_identity_sha256"]
            ),
            expected_media_scope_sha256=str(
                target["expected_media_scope_sha256"]
            ),
        )
        self._insert_hardware_target(db, candidate.id, binding, admitted_at)
        if cassette["operation"] == "format":
            if confirmation is None:
                raise ValidationError(
                    "native recovery format authorization is unavailable"
                )
            if sequence_authorization is None:
                db.execute(
                    "INSERT INTO format_confirmations("
                    "operation_id,job_id,cassette_sequence,expected_label,"
                    "confirmed_by,confirmed_at) VALUES(?,?,?,?,?,?)",
                    (
                        candidate.id,
                        candidate.job_id,
                        candidate.cassette_sequence,
                        confirmation["expected_label"],
                        confirmation["confirmed_by"],
                        admitted_at,
                    ),
                )
            else:
                self._consume_sequence_format_authorization_tx(
                    db,
                    candidate,
                    str(sequence_authorization["authorization_id"]),
                    admitted_at,
                )
        db.execute(
            "UPDATE job_execution_state SET current_job_id=?,updated_at=? "
            "WHERE singleton=1",
            (candidate.job_id, admitted_at),
        )
        # Retrying this cassette is not consent to cancel a deliberate job
        # pause. This path also serves autonomous recovery. Preserve both
        # markers so the replacement can acknowledge the pause safely and
        # the GUI can offer the ordinary explicit Resume action.
        pause_retained = self._job_management_state_tx(
            db, candidate.job_id
        )["pause_requested_at"] is not None
        db.execute(
            "UPDATE job_management_state SET current_checkpoint="
            "CASE WHEN pause_requested_at IS NULL THEN 'resuming' ELSE current_checkpoint END,"
            "revision=revision+1,updated_at=? WHERE job_id=?",
            (admitted_at, candidate.job_id),
        )
        self._job_history_tx(
            db,
            str(candidate.job_id),
            candidate.principal,
            "job.recovery_replacement_admitted" if pause_retained else "job.resumed",
            "resuming",
            {
                "operation_id": candidate.id,
                "replaces_operation_id": fence.operation_id,
            },
            occurred_at=admitted_at,
        )
        self._record_audit_tx(
            db,
            candidate.principal,
            "operation.start",
            "accepted",
            f"request-{uuid.uuid4().hex}",
            None,
            json.dumps(
                {
                    "kind": candidate.kind,
                    "operation_id": candidate.id,
                    "replaces_operation_id": fence.operation_id,
                },
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ),
        )
        row = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (candidate.id,)
        ).fetchone()
        return self._operation_from_row(row)

    def claim_daemon_owner(self, owner_id: str) -> DaemonFence:
        if not isinstance(owner_id, str) or not _SAFE_IDENTIFIER.fullmatch(owner_id):
            raise ValidationError("invalid daemon owner identifier")
        with self.transaction() as db:
            row = db.execute(
                "SELECT generation FROM daemon_ownership WHERE singleton=1"
            ).fetchone()
            generation = 1 if row is None else int(row["generation"]) + 1
            if row is not None and db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='job_incremental_scan_leases'"
            ).fetchone() is not None:
                leases = db.execute(
                    "SELECT * FROM job_incremental_scan_leases ORDER BY job_id"
                ).fetchall()
                for lease in leases:
                    previous = db.execute(
                        "SELECT * FROM job_incremental_scan_events WHERE run_id=? "
                        "ORDER BY event_sequence DESC LIMIT 1",
                        (lease["run_id"],),
                    ).fetchone()
                    if previous is not None and str(previous["state"]) not in {
                        "no_changes",
                        "extension_queued",
                        "waiting_labels",
                        "deferred_busy",
                        "plan_stale",
                        "source_unavailable",
                        "failed_safe",
                    }:
                        recorded_at = self._precise_utc_now(
                            after=str(previous["recorded_at"])
                        )
                        db.execute(
                            "INSERT INTO job_incremental_scan_events("
                            "run_id,event_sequence,job_id,trigger,base_layout_epoch,"
                            "base_layout_fingerprint,idempotency_key_sha256,state,"
                            "daemon_generation,recorded_at,error_code) "
                            "VALUES(?,?,?,?,?,?,?,'failed_safe',?,?,?)",
                            (
                                previous["run_id"],
                                int(previous["event_sequence"]) + 1,
                                previous["job_id"],
                                previous["trigger"],
                                previous["base_layout_epoch"],
                                previous["base_layout_fingerprint"],
                                previous["idempotency_key_sha256"],
                                previous["daemon_generation"],
                                recorded_at,
                                "daemon_restarted",
                            ),
                        )
                        db.execute(
                            "UPDATE job_incremental_policies SET last_attempt_at=?,"
                            "last_outcome='failed_safe',updated_at=? WHERE job_id=?",
                            (recorded_at, recorded_at, lease["job_id"]),
                        )
                db.execute("DELETE FROM job_incremental_scan_leases")
            db.execute(
                """
                INSERT INTO daemon_ownership(singleton, owner_id, generation, claimed_at)
                VALUES(1, ?, ?, ?)
                ON CONFLICT(singleton) DO UPDATE SET
                    owner_id=excluded.owner_id,
                    generation=excluded.generation,
                    claimed_at=excluded.claimed_at
                """,
                (owner_id, generation, self._precise_utc_now()),
            )
        return DaemonFence(owner_id, generation)

    def _reconcile_terminal_waiting_pause_tx(
        self, db: sqlite3.Connection, candidate: OperationRecord,
    ) -> None:
        """Reconcile only a stopped, pre-media attempt, never infer tape unload."""
        state = db.execute(
            "SELECT * FROM automatic_sequence_state WHERE job_id=?", (candidate.job_id,),
        ).fetchone()
        if state is None or state["state"] != "pause_pending":
            return
        management = self._job_management_state_tx(db, candidate.job_id)
        job = db.execute("SELECT * FROM automatic_jobs WHERE id=?", (candidate.job_id,)).fetchone()
        cassette = db.execute(
            "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
            (candidate.job_id, candidate.cassette_sequence),
        ).fetchone()
        prior = db.execute(
            "SELECT * FROM daemon_operations WHERE job_id=? ORDER BY started_at DESC,rowid DESC LIMIT 1",
            (candidate.job_id,),
        ).fetchone()
        epoch = db.execute(
            "SELECT * FROM job_layout_epochs WHERE job_id=? ORDER BY epoch_number DESC LIMIT 1",
            (candidate.job_id,),
        ).fetchone()
        pause_at = self._parse_utc_timestamp(management["pause_requested_at"])
        started_at = None if prior is None else self._parse_utc_timestamp(prior["started_at"])
        finished_at = None if prior is None else self._parse_utc_timestamp(prior["finished_at"])
        if (
            job is None or job["status"] != "paused" or management["retired_at"] is not None
            or management["pause_acknowledged_at"] is not None
            or cassette is None or cassette["status"] != "waiting_media"
            or job["current_sequence"] != candidate.cassette_sequence
            or prior is None or prior["kind"] != "archive.native"
            or prior["cassette_sequence"] != candidate.cassette_sequence
            or prior["state"] not in {"succeeded", "failed", "cancelled"}
            or prior["phase"] is not None
            or pause_at is None or started_at is None or finished_at is None
            or not started_at <= pause_at <= finished_at
            or epoch is None or state["layout_epoch"] != epoch["epoch_number"]
            or state["layout_fingerprint_sha256"] != epoch["layout_fingerprint_sha256"]
        ):
            raise CatalogError("automatic_sequence_pause_pending")
        if db.execute(
            "SELECT 1 FROM hardware_command_executions WHERE operation_id=? "
            "AND command_kind NOT IN ('identify','probe_media') LIMIT 1", (prior["id"],),
        ).fetchone() is not None:
            raise CatalogError("automatic_sequence_pause_pending")
        # Called only after the current owner, global active-operation and
        # command-quiescence gates, in the same transaction as new admission.
        now = self._precise_utc_now()
        db.execute(
            "UPDATE automatic_sequence_state SET state='disabled',updated_at=? WHERE job_id=?",
            (now, candidate.job_id),
        )
        db.execute(
            "UPDATE job_management_state SET pause_acknowledged_at=?,updated_at=? WHERE job_id=?",
            (now, now, candidate.job_id),
        )
        self._job_history_tx(
            db, candidate.job_id, candidate.principal, "job.pause_reconciled", "waiting_media",
            {"operation_id": prior["id"], "finished_at": prior["finished_at"],
             "reason": "terminal_pre_media_attempt"}, occurred_at=now,
        )

    def admit_operation(
        self,
        candidate: OperationRecord,
        daemon_fence: DaemonFence,
        *,
        admission_open: bool,
        hardware_target: HardwareTargetBinding | None = None,
        cutover_credential: str | None = None,
        format_confirmation_label: str | None = None,
        sequence_authorization_id: str | None = None,
        sequence_layout_fingerprint_sha256: str | None = None,
        caller_peer_kind: str | None = None,
        current_host_id: str | None = None,
        enable_native_sequence: bool = False,
    ) -> OperationAdmission:
        self._validate_candidate(candidate)
        continuation_request = (
            sequence_layout_fingerprint_sha256 is not None
            or (
                candidate.kind == "archive.native"
                and candidate.principal == "sequence-coordinator"
            )
        )
        try:
            with self.transaction() as db:
                self._assert_daemon_fence_tx(db, daemon_fence)
                reservation = self._find_sequence_continuation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if (
                    reservation is not None
                    and reservation["idempotency_key"] != candidate.idempotency_key
                ):
                    raise self._sequence_continuation_conflict()
                replay = self._find_operation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if replay is not None:
                    persisted_continuation = db.execute(
                        "SELECT 1 FROM operation_sequence_continuations "
                        "WHERE operation_id=?",
                        (replay["id"],),
                    ).fetchone()
                    if continuation_request or persisted_continuation is not None:
                        provenance = self._load_exact_sequence_continuation_tx(
                            db,
                            replay,
                            candidate,
                            sequence_layout_fingerprint_sha256,
                            sequence_authorization_id,
                            hardware_target,
                        )
                        self._record_sequence_continuation_audit_tx(
                            db, provenance, "replayed"
                        )
                    return OperationAdmission(self._operation_from_row(replay), True)
                if not admission_open:
                    raise MutationAdmissionClosed(
                        "catalog mutation admission is closed"
                    )
                sequence_layout: _SequenceContinuationLayout | None = None
                if continuation_request:
                    if (
                        sequence_layout_fingerprint_sha256 is None
                        or format_confirmation_label is not None
                    ):
                        raise self._sequence_continuation_conflict()
                    sequence_layout = self._assert_sequence_continuation_layout_tx(
                        db, candidate, sequence_layout_fingerprint_sha256
                    )
                    if (
                        candidate.idempotency_key
                        != sequence_continuation_idempotency_key(
                            sequence_layout.job_id,
                            sequence_layout.layout_fingerprint_sha256,
                            sequence_layout.cassette_sequence,
                            daemon_fence.generation,
                        )
                        or (
                            sequence_layout.cassette_operation == "format"
                            and sequence_authorization_id is None
                        )
                        or (
                            sequence_layout.cassette_operation == "append"
                            and sequence_authorization_id is not None
                        )
                    ):
                        raise self._sequence_continuation_conflict()
                active = db.execute(
                    """
                    SELECT * FROM daemon_operations
                    WHERE state IN ('running','recovery_required') LIMIT 1
                    """
                ).fetchone()
                if active is not None:
                    raise OperationConflict(self._operation_from_row(active))
                if candidate.kind in {"archive.resume", "archive.native"}:
                    if self.pending_boundary_replan_record(candidate.job_id) is not None:
                        raise MutationAdmissionClosed("boundary source plan is waiting for cassette labels")
                    if candidate.kind == "archive.native" and self.boundary_replan_required(
                        candidate.job_id, candidate.cassette_sequence,
                    ):
                        raise MutationAdmissionClosed("boundary source refresh is required before the next cassette")
                    scan_lease = db.execute(
                        "SELECT run_id FROM job_incremental_scan_leases "
                        "WHERE job_id=? COLLATE NOCASE",
                        (candidate.job_id,),
                    ).fetchone()
                    if scan_lease is not None:
                        raise MutationAdmissionClosed(
                            "incremental source discovery owns this job"
                        )
                nonquiescent = db.execute(
                    """
                    SELECT 1 FROM hardware_command_executions
                    WHERE state != 'quiesced' LIMIT 1
                    """
                ).fetchone()
                if nonquiescent is not None:
                    raise CommandQuiescenceRequired(
                        "a hardware command has not been proven quiescent"
                    )
                if (
                    self._requires_hardware_target(candidate)
                    and hardware_target is None
                ):
                    raise ValidationError(
                        "hardware operation requires a verified target binding"
                    )
                if enable_native_sequence:
                    if candidate.kind != "archive.native" or continuation_request:
                        raise ValidationError("explicit native start required")
                    self._reconcile_terminal_waiting_pause_tx(db, candidate)
                    self.enable_automatic_sequence_for_start(
                        candidate.job_id, actor=candidate.principal, enabled_at=utc_now(),
                    )
                now = self._precise_utc_now()
                application_settings = db.execute(
                    "SELECT copy_buffer_bytes FROM application_settings "
                    "WHERE singleton=1"
                ).fetchone()
                admitted_copy_buffer = (
                    None
                    if application_settings is None
                    else int(application_settings["copy_buffer_bytes"])
                )
                self._insert_daemon_operation_tx(
                    db,
                    candidate,
                    daemon_fence.generation,
                    admitted_copy_buffer,
                    now,
                )
                if hardware_target is not None:
                    self._insert_hardware_target(db, candidate.id, hardware_target, now)
                if sequence_layout is not None:
                    db.execute(
                        "INSERT INTO operation_sequence_continuations("
                        "operation_id,job_id,cassette_sequence,layout_epoch,"
                        "layout_fingerprint_sha256,continuation_idempotency_key,"
                        "linked_at) VALUES(?,?,?,?,?,?,?)",
                        (
                            candidate.id,
                            sequence_layout.job_id,
                            sequence_layout.cassette_sequence,
                            sequence_layout.layout_epoch,
                            sequence_layout.layout_fingerprint_sha256,
                            candidate.idempotency_key,
                            now,
                        ),
                    )
                expected_label = self._consume_cutover_authorization_tx(
                    db,
                    candidate,
                    cutover_credential,
                    now,
                    caller_peer_kind=caller_peer_kind,
                    current_host_id=current_host_id,
                )
                if sequence_authorization_id is not None:
                    self._consume_sequence_format_authorization_tx(
                        db,
                        candidate,
                        sequence_authorization_id,
                        now,
                    )
                elif format_confirmation_label is not None:
                    self._record_format_confirmation_tx(
                        db,
                        candidate,
                        format_confirmation_label,
                        expected_label,
                        now,
                    )
                if (
                    candidate.kind in {"archive.resume", "archive.native"}
                    and candidate.job_id is not None
                ):
                    job = db.execute(
                        "SELECT job.status,state.retired_at,state.current_checkpoint "
                        "FROM automatic_jobs job JOIN job_management_state state "
                        "ON state.job_id=job.id WHERE job.id=?",
                        (candidate.job_id,),
                    ).fetchone()
                    if job is None or job["retired_at"] is not None:
                        raise CatalogError("job_not_resumable")
                    db.execute(
                        "UPDATE job_execution_state SET current_job_id=?,updated_at=? "
                        "WHERE singleton=1",
                        (candidate.job_id, now),
                    )
                    checkpoint = (
                        "starting"
                        if candidate.kind == "archive.native"
                        and job["status"] == "planned"
                        else "resuming"
                    )
                    if job["status"] == "failed":
                        db.execute(
                            "UPDATE automatic_jobs SET status='waiting_media',"
                            "current_sequence=?,completed_at=NULL,last_error=NULL "
                            "WHERE id=?",
                            (candidate.cassette_sequence, candidate.job_id),
                        )
                    db.execute(
                        "UPDATE job_management_state SET pause_requested_at=NULL,"
                        "pause_acknowledged_at=NULL,current_checkpoint=?,"
                        "revision=revision+1,updated_at=? WHERE job_id=?",
                        (checkpoint, now, candidate.job_id),
                    )
                    self._job_history_tx(
                        db,
                        candidate.job_id,
                        candidate.principal,
                        "job.started" if checkpoint == "starting" else "job.resumed",
                        checkpoint,
                        {"operation_id": candidate.id},
                        occurred_at=now,
                    )
                self._record_audit_tx(
                    db,
                    candidate.principal,
                    "operation.start",
                    "accepted",
                    f"request-{uuid.uuid4().hex}",
                    None,
                    json.dumps(
                        {
                            "kind": candidate.kind,
                            "operation_id": candidate.id,
                        },
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
                if sequence_layout is not None:
                    persisted = db.execute(
                        "SELECT * FROM daemon_operations WHERE id=?", (candidate.id,)
                    ).fetchone()
                    provenance = self._load_exact_sequence_continuation_tx(
                        db,
                        persisted,
                        candidate,
                        sequence_layout_fingerprint_sha256,
                        sequence_authorization_id,
                        hardware_target,
                    )
                    self._record_sequence_continuation_audit_tx(
                        db, provenance, "admitted"
                    )
                row = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?", (candidate.id,)
                ).fetchone()
                return OperationAdmission(self._operation_from_row(row), False)
        except _OperationIdempotencyInsertRace as race:
            with self.transaction() as db:
                self._assert_daemon_fence_tx(db, daemon_fence)
                reservation = self._find_sequence_continuation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if (
                    reservation is not None
                    and reservation["idempotency_key"] != candidate.idempotency_key
                ):
                    raise self._sequence_continuation_conflict()
                replay = self._find_operation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if replay is None:
                    active = db.execute(
                        "SELECT * FROM daemon_operations WHERE state IN "
                        "('running','recovery_required') LIMIT 1"
                    ).fetchone()
                    if active is not None:
                        raise OperationConflict(self._operation_from_row(active))
                    cause = race.__cause__
                    if cause is not None:
                        raise cause
                    raise
                persisted_continuation = db.execute(
                    "SELECT 1 FROM operation_sequence_continuations "
                    "WHERE operation_id=?",
                    (replay["id"],),
                ).fetchone()
                if continuation_request or persisted_continuation is not None:
                    provenance = self._load_exact_sequence_continuation_tx(
                        db,
                        replay,
                        candidate,
                        sequence_layout_fingerprint_sha256,
                        sequence_authorization_id,
                        hardware_target,
                    )
                    self._record_sequence_continuation_audit_tx(
                        db, provenance, "replayed"
                    )
                return OperationAdmission(self._operation_from_row(replay), True)

    def register_cutover_authorization(
        self,
        candidate: OperationRecord,
        daemon_fence: DaemonFence,
        *,
        admission_open: bool,
        credential_sha256: str,
        bundle_sha256: str,
        catalog_binding_sha256: str,
        assignment_sha256: str,
        expected_label: str,
        host_id: str,
        drive_serial_sha256: str,
        expires_at: str,
    ) -> OperationAdmission:
        """Atomically persist a hash-only cassette-four authorization."""

        self._validate_candidate(candidate)
        try:
            with self.transaction() as db:
                self._assert_daemon_fence_tx(db, daemon_fence)
                replay = self._find_sequence_continuation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if replay is None:
                    replay = self._find_operation_by_key_tx(
                        db, candidate.idempotency_key
                    )
                if replay is not None:
                    persisted_continuation = db.execute(
                        "SELECT 1 FROM operation_sequence_continuations "
                        "WHERE operation_id=?",
                        (replay["id"],),
                    ).fetchone()
                    if persisted_continuation is not None:
                        raise self._sequence_continuation_conflict()
                    if replay["kind"] != "cutover.authorize":
                        raise CutoverAuthorizationInvalid()
                    return OperationAdmission(self._operation_from_row(replay), True)
                if not admission_open:
                    raise MutationAdmissionClosed(
                        "catalog mutation admission is closed"
                    )
                active = db.execute(
                    "SELECT * FROM daemon_operations "
                    "WHERE state IN ('running','recovery_required') LIMIT 1"
                ).fetchone()
                if active is not None:
                    raise OperationConflict(self._operation_from_row(active))
                now = self._precise_utc_now()
                now_timestamp = self._parse_utc_timestamp(now)
                expiry = self._parse_utc_timestamp(expires_at)
                policy = db.execute(
                    "SELECT * FROM imported_job_policies WHERE job_id=?",
                    (candidate.job_id,),
                ).fetchone()
                job = db.execute(
                    "SELECT * FROM automatic_jobs WHERE id=?", (candidate.job_id,)
                ).fetchone()
                cassette = db.execute(
                    "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=4",
                    (candidate.job_id,),
                ).fetchone()
                for value, name in (
                    (credential_sha256, "credential digest"),
                    (bundle_sha256, "bundle digest"),
                    (catalog_binding_sha256, "catalog binding digest"),
                    (assignment_sha256, "assignment digest"),
                    (drive_serial_sha256, "drive serial digest"),
                ):
                    try:
                        self._validate_sha256(value, name)
                    except ValidationError as exc:
                        raise CutoverAuthorizationInvalid() from exc
                try:
                    self._validate_safe_identifier(host_id, "host identifier")
                except ValidationError as exc:
                    raise CutoverAuthorizationInvalid() from exc
                current_binding = (
                    None
                    if policy is None or cassette is None
                    else cutover_catalog_binding_sha256(
                        candidate.job_id,
                        policy["bundle_sha256"],
                        policy["assignment_sha256"],
                        policy["cassette_plan_sha256"],
                        policy["completed_evidence_sha256"],
                        cassette["physical_label"],
                    )
                )
                if (
                    candidate.kind != "cutover.authorize"
                    or candidate.job_id is None
                    or candidate.cassette_sequence != 4
                    or policy is None
                    or job is None
                    or cassette is None
                    or policy["authority_state"] != "pre_cutover"
                    or policy["windows_authority"] != "resumable"
                    or policy["rollback_allowed"] != 1
                    or job["current_sequence"] != 4
                    or cassette["status"] not in {"pending", "waiting_media"}
                    or cassette["operation"] != "format"
                    or bundle_sha256 != policy["bundle_sha256"]
                    or assignment_sha256 != policy["assignment_sha256"]
                    or expected_label != cassette["physical_label"]
                    or catalog_binding_sha256 != current_binding
                    or now_timestamp is None
                    or expiry is None
                    or not now_timestamp < expiry <= now_timestamp + timedelta(hours=1)
                ):
                    raise CutoverAuthorizationInvalid()
                db.execute(
                    """
                    INSERT INTO daemon_operations(
                        id, kind, state, phase, idempotency_key, principal,
                        owner_generation, job_id, cassette_sequence, started_at,
                        finished_at, error_class, error_code, error_message
                    ) VALUES(?, ?, 'succeeded', NULL, ?, ?, ?, ?, 4, ?, ?, NULL, NULL, NULL)
                    """,
                    (
                        candidate.id,
                        candidate.kind,
                        candidate.idempotency_key,
                        candidate.principal,
                        daemon_fence.generation,
                        candidate.job_id,
                        now,
                        now,
                    ),
                )
                db.execute(
                    """
                    INSERT INTO cutover_authorizations(
                        id, credential_sha256, job_id, cassette_sequence,
                        bundle_sha256, catalog_binding_sha256, assignment_sha256,
                        expected_label, host_id, drive_serial_sha256, peer_kind,
                        created_at, expires_at, consumed_at, consumed_by_operation_id
                    ) VALUES(?, ?, ?, 4, ?, ?, ?, ?, ?, ?, 'local_admin', ?, ?, NULL, NULL)
                    """,
                    (
                        candidate.id,
                        credential_sha256,
                        candidate.job_id,
                        bundle_sha256,
                        catalog_binding_sha256,
                        assignment_sha256,
                        expected_label,
                        host_id,
                        drive_serial_sha256,
                        now,
                        expires_at,
                    ),
                )
                row = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?", (candidate.id,)
                ).fetchone()
                return OperationAdmission(self._operation_from_row(row), False)
        except sqlite3.IntegrityError as exc:
            with self.transaction() as db:
                replay = self._find_sequence_continuation_by_key_tx(
                    db, candidate.idempotency_key
                )
                if replay is None:
                    replay = self._find_operation_by_key_tx(
                        db, candidate.idempotency_key
                    )
                if replay is not None:
                    persisted_continuation = db.execute(
                        "SELECT 1 FROM operation_sequence_continuations "
                        "WHERE operation_id=?",
                        (replay["id"],),
                    ).fetchone()
                    if persisted_continuation is not None:
                        raise self._sequence_continuation_conflict() from exc
                    if replay["kind"] != "cutover.authorize":
                        raise CutoverAuthorizationInvalid() from exc
                    return OperationAdmission(self._operation_from_row(replay), True)
            raise CutoverAuthorizationInvalid() from exc

    def assert_operation_fence(self, fence: OperationFence) -> None:
        with self.transaction() as db:
            self._assert_operation_fence_tx(db, fence)

    def assert_command_fence(
        self, fence: OperationFence | RecoveryCommandFence
    ) -> None:
        """Assert the exact current fence without reserving a daemon command."""

        with self.transaction() as db:
            self._assert_command_fence_tx(db, fence)

    def ltfs_recovery_session_generation(self, fence: RecoveryCommandFence) -> int:
        """Return the original broker-session generation from authenticated lineage."""

        if type(fence) is not RecoveryCommandFence:
            raise TypeError("an exact recovery command fence is required")
        with self.transaction() as db:
            return self._ltfs_recovery_session_generation_tx(db, fence)

    def _ltfs_recovery_session_generation_tx(
        self,
        db: sqlite3.Connection,
        fence: RecoveryCommandFence,
    ) -> int:
        operation = self._assert_command_fence_tx(db, fence)
        lineage = db.execute(
            "SELECT * FROM operation_recovery_lineages "
            "WHERE operation_id=? AND recovery_generation=?",
            (fence.operation_id, fence.owner_generation),
        ).fetchone()
        latest = db.execute(
            "SELECT * FROM operation_recovery_lineages "
            "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
            (fence.operation_id,),
        ).fetchone()
        if lineage is None or latest is None or latest["id"] != lineage["id"]:
            raise StaleOperationFence(
                "recovery session has no exact current restart lineage"
            )
        try:
            command_ids = tuple(json.loads(lineage["command_ids_json"]))
        except (TypeError, ValueError):
            raise CatalogError("recovery session lineage is malformed") from None
        if len(command_ids) != len(set(command_ids)) or any(
            type(command_id) is not str or not command_id for command_id in command_ids
        ):
            raise CatalogError("recovery session lineage is malformed")
        from .daemon.recovery import recovery_lineage_sha256

        expected_sha256 = recovery_lineage_sha256(
            lineage_id=lineage["id"],
            operation_id=lineage["operation_id"],
            original_generation=lineage["original_generation"],
            recovery_generation=lineage["recovery_generation"],
            daemon_owner_id=lineage["daemon_owner_id"],
            prior_lineage_id=lineage["prior_lineage_id"],
            command_ids=command_ids,
            recorded_at=lineage["recorded_at"],
        )
        prior = (
            None
            if lineage["prior_lineage_id"] is None
            else db.execute(
                "SELECT * FROM operation_recovery_lineages WHERE id=?",
                (lineage["prior_lineage_id"],),
            ).fetchone()
        )
        prior_valid = bool(
            lineage["prior_lineage_id"] is None
            or (
                prior is not None
                and prior["operation_id"] == lineage["operation_id"]
                and prior["original_generation"] == lineage["original_generation"]
                and prior["recovery_generation"] < lineage["recovery_generation"]
            )
        )
        if (
            lineage["operation_id"] != fence.operation_id
            or lineage["recovery_generation"] != fence.owner_generation
            or lineage["original_generation"] != operation["owner_generation"]
            or lineage["original_generation"] >= lineage["recovery_generation"]
            or lineage["lineage_sha256"] != expected_sha256
            or not prior_valid
        ):
            raise CatalogError("recovery session lineage is not authentic")
        return int(lineage["original_generation"])

    def _assert_imported_archive_fence_tx(
        self,
        db: sqlite3.Connection,
        fence: OperationFence | RecoveryCommandFence,
    ) -> tuple[sqlite3.Row, int]:
        """Return the archive operation and its immutable original generation."""

        if isinstance(fence, OperationFence):
            operation = self._assert_operation_fence_tx(db, fence)
            return operation, fence.owner_generation
        if type(fence) is RecoveryCommandFence:
            operation = self._assert_command_fence_tx(db, fence)
            original_generation = self._ltfs_recovery_session_generation_tx(db, fence)
            if operation["owner_generation"] != original_generation:
                raise StaleOperationFence(
                    "recovery archive generation does not match original authority"
                )
            return operation, original_generation
        raise TypeError("an exact archive operation fence is required")

    def set_operation_phase(self, fence: OperationFence, phase: str) -> None:
        if phase not in _OPERATION_PHASES:
            raise ValidationError("invalid persistent operation phase")
        with self.transaction() as db:
            self._assert_operation_fence_tx(db, fence)
            db.execute(
                "UPDATE daemon_operations SET phase=? WHERE id=?",
                (phase, fence.operation_id),
            )

    def finish_operation(
        self,
        fence: OperationFence,
        state: str,
        error_class: str | None = None,
        error_code: str | None = None,
        error_message: str | None = None,
    ) -> None:
        if state not in {"succeeded", "failed", "cancelled", "recovery_required"}:
            raise ValidationError("invalid terminal operation state")
        if error_class is not None and error_class not in _ERROR_CLASSES:
            raise ValidationError("invalid operation error class")
        safe_message = self._safe_error_message(error_code, error_message)
        with self.transaction() as db:
            self._assert_operation_fence_tx(db, fence)
            finished_at = (
                None if state == "recovery_required" else self._precise_utc_now()
            )
            db.execute(
                """
                UPDATE daemon_operations
                SET state=?, finished_at=?, error_class=?, error_code=?, error_message=?
                WHERE id=?
                """,
                (
                    state,
                    finished_at,
                    error_class,
                    error_code,
                    safe_message,
                    fence.operation_id,
                ),
            )

    def get_operation(self, operation_id: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
        ).fetchone()

    def find_operation_by_key(self, key: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT * FROM daemon_operations WHERE idempotency_key=?", (key,)
        ).fetchone()

    def replay_operation_by_key(self, key: str) -> sqlite3.Row | None:
        """Return an ordinary replay record or fail closed on a continuation key."""

        with self.transaction() as db:
            if self._find_sequence_continuation_by_key_tx(db, key) is not None:
                raise self._sequence_continuation_conflict()
            return self._find_operation_by_key_tx(db, key)

    def native_recovery_dispatch(self, operation_id: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT * FROM native_recovery_dispatches WHERE operation_id=?",
            (operation_id,),
        ).fetchone()

    def claim_native_recovery_dispatch_start(
        self, fence: OperationFence
    ) -> bool:
        with self.transaction() as db:
            daemon = db.execute(
                "SELECT generation FROM daemon_ownership WHERE singleton=1"
            ).fetchone()
            dispatch = db.execute(
                "SELECT state,owner_generation FROM native_recovery_dispatches "
                "WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if (
                daemon is None
                or daemon["generation"] != fence.owner_generation
                or dispatch is None
                or dispatch["owner_generation"] != fence.owner_generation
            ):
                raise StaleOperationFence(fence.operation_id)
            if dispatch["state"] in {"started", "finished"}:
                return False
            operation = self._assert_operation_fence_tx(db, fence)
            if operation["kind"] != "archive.native":
                raise ValidationError("native recovery dispatch operation is invalid")
            now = self._precise_utc_now()
            cursor = db.execute(
                "UPDATE native_recovery_dispatches SET state='started',started_at=? "
                "WHERE operation_id=? AND owner_generation=? AND state='admitted'",
                (now, fence.operation_id, fence.owner_generation),
            )
            if cursor.rowcount == 1:
                return True
            row = db.execute(
                "SELECT state,owner_generation FROM native_recovery_dispatches "
                "WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if (
                row is None
                or row["owner_generation"] != fence.owner_generation
                or row["state"] not in {"started", "finished"}
            ):
                raise ValidationError("native recovery dispatch claim is invalid")
            return False

    def finish_native_recovery_dispatch(self, fence: OperationFence) -> None:
        with self.transaction() as db:
            daemon = db.execute(
                "SELECT generation FROM daemon_ownership WHERE singleton=1"
            ).fetchone()
            if daemon is None or daemon["generation"] != fence.owner_generation:
                raise StaleOperationFence(fence.operation_id)
            now = self._precise_utc_now()
            cursor = db.execute(
                "UPDATE native_recovery_dispatches SET state='finished',finished_at=? "
                "WHERE operation_id=? AND owner_generation=? AND state='started'",
                (now, fence.operation_id, fence.owner_generation),
            )
            if cursor.rowcount != 1:
                row = db.execute(
                    "SELECT state FROM native_recovery_dispatches WHERE operation_id=?",
                    (fence.operation_id,),
                ).fetchone()
                if row is None or row["state"] != "finished":
                    raise ValidationError("native recovery dispatch finish is invalid")

    def active_operation(self) -> sqlite3.Row | None:
        return self.connection.execute(
            """
            SELECT * FROM daemon_operations
            WHERE state IN ('running','recovery_required') LIMIT 1
            """
        ).fetchone()

    def recover_interrupted_operations(
        self,
        daemon_fence: DaemonFence,
    ) -> tuple[OperationRecord, ...]:
        """Turn pre-restart workers into durable admission blockers."""

        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            interrupted = db.execute(
                "SELECT * FROM daemon_operations WHERE state IN "
                "('running','recovery_required') AND owner_generation < ? "
                "ORDER BY started_at, id",
                (daemon_fence.generation,),
            ).fetchall()
            for operation in interrupted:
                self._record_operation_recovery_lineage_tx(db, operation, daemon_fence)
                self._record_imported_recovery_lineage_tx(db, operation, daemon_fence)
            db.execute(
                """
                UPDATE daemon_operations
                SET state='recovery_required', finished_at=NULL,
                    error_class='operator_required',
                    error_code='recovery_required', error_message=?
                WHERE state='running' AND owner_generation < ?
                """,
                (
                    _SAFE_ERROR_MESSAGES["recovery_required"],
                    daemon_fence.generation,
                ),
            )
            rows = db.execute(
                """
                SELECT * FROM daemon_operations
                WHERE state='recovery_required' ORDER BY started_at, id
                """
            ).fetchall()
            return tuple(self._operation_from_row(row) for row in rows)

    def _record_operation_recovery_lineage_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        daemon_fence: DaemonFence,
    ) -> None:
        if daemon_fence.generation <= operation["owner_generation"]:
            raise StaleDaemonFence("recovery lineage owner is stale")
        existing = db.execute(
            "SELECT * FROM operation_recovery_lineages "
            "WHERE operation_id=? AND recovery_generation=?",
            (operation["id"], daemon_fence.generation),
        ).fetchone()
        if existing is not None:
            if (
                existing["daemon_owner_id"] != daemon_fence.owner_id
                or existing["original_generation"] != operation["owner_generation"]
            ):
                raise StaleDaemonFence("recovery lineage replay is not exact")
            return
        prior = db.execute(
            "SELECT * FROM operation_recovery_lineages "
            "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
            (operation["id"],),
        ).fetchone()
        if prior is not None and (
            prior["original_generation"] != operation["owner_generation"]
            or daemon_fence.generation <= prior["recovery_generation"]
        ):
            raise StaleDaemonFence("recovery lineage generation is not monotonic")
        commands = self._commands_with_release_for_operation_tx(db, operation["id"])
        command_ids = tuple(row["id"] for row in commands)
        causal_values = [operation["started_at"]]
        if prior is not None:
            causal_values.append(prior["recorded_at"])
        causal_values.extend(
            row[field]
            for row in commands
            for field in (
                "created_at",
                "released_at",
                "exit_observed_at",
                "quiesced_at",
                "release_authorized_at",
                "release_confirmed_at",
            )
            if row[field] is not None
        )
        recorded_at = self._precise_utc_now(after=max(causal_values))
        lineage_id = self._new_id("operation-recovery-lineage")
        prior_lineage_id = None if prior is None else prior["id"]
        from .daemon.recovery import recovery_lineage_sha256

        lineage_sha256 = recovery_lineage_sha256(
            lineage_id=lineage_id,
            operation_id=operation["id"],
            original_generation=operation["owner_generation"],
            recovery_generation=daemon_fence.generation,
            daemon_owner_id=daemon_fence.owner_id,
            prior_lineage_id=prior_lineage_id,
            command_ids=command_ids,
            recorded_at=recorded_at,
        )
        db.execute(
            "INSERT INTO operation_recovery_lineages("
            "id, operation_id, original_generation, recovery_generation, "
            "daemon_owner_id, prior_lineage_id, command_ids_json, recorded_at, "
            "lineage_sha256) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                lineage_id,
                operation["id"],
                operation["owner_generation"],
                daemon_fence.generation,
                daemon_fence.owner_id,
                prior_lineage_id,
                json.dumps(command_ids, separators=(",", ":")),
                recorded_at,
                lineage_sha256,
            ),
        )

    def _record_imported_recovery_lineage_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        daemon_fence: DaemonFence,
    ) -> None:
        commit = db.execute(
            "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        if commit is None:
            runtime_commit = db.execute(
                "SELECT * FROM imported_runtime_cassette_commit_receipts "
                "WHERE operation_id=?",
                (operation["id"],),
            ).fetchone()
            if runtime_commit is not None:
                self._record_imported_runtime_recovery_lineage_tx(
                    db, operation, daemon_fence, runtime_commit
                )
            return
        owner = db.execute(
            "SELECT owner_id, generation FROM daemon_ownership WHERE singleton=1"
        ).fetchone()
        if (
            owner is None
            or owner["owner_id"] != daemon_fence.owner_id
            or owner["generation"] != daemon_fence.generation
            or daemon_fence.generation <= commit["owner_generation"]
        ):
            raise StaleDaemonFence("recovery lineage owner is stale")
        existing = db.execute(
            "SELECT * FROM imported_recovery_lineage_receipts "
            "WHERE operation_id=? AND recovery_generation=?",
            (operation["id"], daemon_fence.generation),
        ).fetchone()
        if existing is not None:
            if (
                existing["daemon_owner_id"] != daemon_fence.owner_id
                or existing["original_owner_generation"] != commit["owner_generation"]
                or existing["commit_binding_sha256"] != commit["commit_binding_sha256"]
            ):
                raise StaleDaemonFence("recovery lineage replay is not exact")
            return
        prior = db.execute(
            "SELECT * FROM imported_recovery_lineage_receipts "
            "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
            (operation["id"],),
        ).fetchone()
        if (
            prior is not None
            and daemon_fence.generation <= prior["recovery_generation"]
        ):
            raise StaleDaemonFence("recovery lineage generation is not monotonic")
        frozen_ids = set(json.loads(commit["command_ids_json"]))
        commands = self._commands_with_release_for_operation_tx(db, operation["id"])
        postcommit = tuple(row for row in commands if row["id"] not in frozen_ids)
        if len({row["id"] for row in commands}) != len(commands) or any(
            not hardware_command_release_evidence_valid(
                self._postcommit_command_tuple(row)
            )
            for row in commands
        ):
            raise CatalogError("recovery lineage release evidence is invalid")
        command_ids = tuple(row["id"] for row in postcommit)
        command_observations = tuple(
            self._postcommit_command_tuple(row) for row in postcommit
        )
        command_evidence = imported_postcommit_command_sha256(command_observations)
        causal_values = [commit["committed_at"]]
        causal_values.extend(
            row[field]
            for row in postcommit
            for field in (
                "created_at",
                "released_at",
                "exit_observed_at",
                "quiesced_at",
                "release_authorized_at",
                "release_confirmed_at",
            )
            if row[field] is not None
        )
        recorded_at = self._precise_utc_now(after=max(causal_values))
        lineage_id = self._new_id("recovery-lineage")
        lineage_sha256 = imported_recovery_lineage_sha256(
            (
                lineage_id,
                commit["job_id"],
                4,
                operation["id"],
                commit["owner_generation"],
                daemon_fence.generation,
                daemon_fence.owner_id,
                None if prior is None else prior["id"],
                commit["commit_binding_sha256"],
                operation["state"],
                command_ids,
                command_evidence,
                recorded_at,
            )
        )
        db.execute(
            "INSERT INTO imported_recovery_lineage_receipts("
            "id, job_id, sequence, operation_id, original_owner_generation, "
            "recovery_generation, daemon_owner_id, prior_lineage_id, "
            "commit_binding_sha256, restart_state, command_ids_json, "
            "command_observations_json, command_evidence_sha256, recorded_at, "
            "lineage_sha256) VALUES(?, ?, 4, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                lineage_id,
                commit["job_id"],
                operation["id"],
                commit["owner_generation"],
                daemon_fence.generation,
                daemon_fence.owner_id,
                None if prior is None else prior["id"],
                commit["commit_binding_sha256"],
                operation["state"],
                json.dumps(command_ids, separators=(",", ":")),
                json.dumps(command_observations, separators=(",", ":")),
                command_evidence,
                recorded_at,
                lineage_sha256,
            ),
        )

    def _record_imported_runtime_recovery_lineage_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        daemon_fence: DaemonFence,
        commit: sqlite3.Row,
    ) -> None:
        if daemon_fence.generation <= commit["owner_generation"]:
            raise StaleDaemonFence("runtime recovery lineage owner is stale")
        existing = db.execute(
            "SELECT * FROM imported_runtime_recovery_lineage_receipts "
            "WHERE operation_id=? AND recovery_generation=?",
            (operation["id"], daemon_fence.generation),
        ).fetchone()
        if existing is not None:
            if (
                existing["job_id"] != commit["job_id"]
                or existing["sequence"] != commit["sequence"]
                or existing["operation_id"] != operation["id"]
                or existing["original_owner_generation"] != commit["owner_generation"]
                or existing["commit_binding_sha256"] != commit["commit_binding_sha256"]
                or existing["daemon_owner_id"] != daemon_fence.owner_id
            ):
                raise StaleDaemonFence("runtime recovery lineage replay is not exact")
            return
        prior = db.execute(
            "SELECT * FROM imported_runtime_recovery_lineage_receipts "
            "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
            (operation["id"],),
        ).fetchone()
        if (
            prior is not None
            and daemon_fence.generation <= prior["recovery_generation"]
        ):
            raise StaleDaemonFence("runtime recovery lineage is not monotonic")
        frozen_ids = set(json.loads(commit["command_ids_json"]))
        commands = self._commands_with_release_for_operation_tx(db, operation["id"])
        postcommit = tuple(row for row in commands if row["id"] not in frozen_ids)
        observations = tuple(self._postcommit_command_tuple(row) for row in postcommit)
        if any(
            not hardware_command_release_evidence_valid(row) for row in observations
        ):
            raise CatalogError("runtime recovery release evidence is invalid")
        command_ids = tuple(row["id"] for row in postcommit)
        evidence = imported_postcommit_command_sha256(observations)
        causal = [commit["committed_at"]]
        causal.extend(
            value
            for row in postcommit
            for value in (row["created_at"], row["quiesced_at"])
            if value is not None
        )
        recorded_at = self._precise_utc_now(after=max(causal))
        lineage_id = self._new_id("runtime-recovery-lineage")
        lineage = imported_recovery_lineage_sha256(
            (
                lineage_id,
                commit["job_id"],
                commit["sequence"],
                operation["id"],
                commit["owner_generation"],
                daemon_fence.generation,
                daemon_fence.owner_id,
                None if prior is None else prior["id"],
                commit["commit_binding_sha256"],
                operation["state"],
                command_ids,
                evidence,
                recorded_at,
            )
        )
        db.execute(
            "INSERT INTO imported_runtime_recovery_lineage_receipts("
            "id,job_id,sequence,operation_id,original_owner_generation,"
            "recovery_generation,daemon_owner_id,prior_lineage_id,"
            "commit_binding_sha256,restart_state,command_ids_json,"
            "command_observations_json,"
            "command_evidence_sha256,recorded_at,lineage_sha256) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (
                lineage_id,
                commit["job_id"],
                commit["sequence"],
                operation["id"],
                commit["owner_generation"],
                daemon_fence.generation,
                daemon_fence.owner_id,
                None if prior is None else prior["id"],
                commit["commit_binding_sha256"],
                operation["state"],
                json.dumps(command_ids, separators=(",", ":")),
                json.dumps(observations, separators=(",", ":")),
                evidence,
                recorded_at,
                lineage,
            ),
        )

    def reconcile_admission_blockers(
        self,
        daemon_fence: DaemonFence,
    ) -> tuple[OperationRecord, ...]:
        """Durably promote operations with non-quiescent commands to blockers."""

        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            db.execute(
                """
                UPDATE daemon_operations
                SET state='recovery_required', finished_at=NULL,
                    error_class='operator_required',
                    error_code='recovery_required', error_message=?
                WHERE state NOT IN ('running', 'recovery_required')
                  AND EXISTS (
                      SELECT 1 FROM hardware_command_executions command
                      WHERE command.operation_id=daemon_operations.id
                        AND command.state != 'quiesced'
                  )
                """,
                (_SAFE_ERROR_MESSAGES["recovery_required"],),
            )
            rows = db.execute(
                """
                SELECT * FROM daemon_operations operation
                WHERE operation.state IN ('running', 'recovery_required')
                   OR EXISTS (
                       SELECT 1 FROM hardware_command_executions command
                       WHERE command.operation_id=operation.id
                         AND command.state != 'quiesced'
                   )
                ORDER BY operation.started_at, operation.id
                """
            ).fetchall()
            return tuple(self._operation_from_row(row) for row in rows)

    def record_phase_sample(
        self,
        fence: OperationFence,
        phase: str,
        started_at: str,
        duration_seconds: float,
    ) -> None:
        if phase not in _OPERATION_PHASES:
            raise ValidationError("invalid persistent operation phase")
        if isinstance(duration_seconds, bool) or duration_seconds < 0:
            raise ValidationError("phase duration must be non-negative")
        with self.transaction() as db:
            self._assert_operation_fence_tx(db, fence)
            db.execute(
                "UPDATE daemon_operations SET phase=? WHERE id=?",
                (phase, fence.operation_id),
            )
            db.execute(
                """
                INSERT INTO phase_samples(
                    operation_id, owner_generation, phase, started_at,
                    duration_seconds, recorded_at
                ) VALUES(?, ?, ?, ?, ?, ?)
                """,
                (
                    fence.operation_id,
                    fence.owner_generation,
                    phase,
                    started_at,
                    float(duration_seconds),
                    self._precise_utc_now(),
                ),
            )

    def record_audit(
        self,
        principal: str,
        action: str,
        result: str,
        request_id: str,
        remote_address: str | None,
        payload: dict,
    ) -> None:
        redacted = self._redact_audit_value(payload)
        encoded = json.dumps(
            redacted, ensure_ascii=False, separators=(",", ":"), sort_keys=True
        )
        with self.transaction() as db:
            self._record_audit_tx(
                db,
                principal,
                action,
                result,
                request_id,
                remote_address,
                encoded,
            )

    @staticmethod
    def _critical_observation_payload(
        observation: CriticalRecoveryObservation,
    ) -> dict[str, object]:
        return {
            "operation_id": observation.operation_id,
            "daemon_generation": observation.daemon_generation,
            "target": {
                "mount_path_sha256": observation.target.mount_path_sha256,
                "tape_device_identity_sha256": (
                    observation.target.tape_device_identity_sha256
                ),
                "scsi_device_identity_sha256": (
                    observation.target.scsi_device_identity_sha256
                ),
                "expected_media_scope_sha256": (
                    observation.target.expected_media_scope_sha256
                ),
            },
            "bound_media_identity_sha256": (
                observation.bound_media_identity_sha256
            ),
            "observed_media_identity_sha256": (
                observation.observed_media_identity_sha256
            ),
            "command_ledger_sha256": observation.command_ledger_sha256,
            "commands_quiescent": observation.commands_quiescent,
            "mounted": observation.mounted,
            "media_loaded": observation.media_loaded,
            "drive_busy": observation.drive_busy,
            "related_process_count": observation.related_process_count,
            "evidence_category": observation.evidence_category,
            "evidence_sha256": observation.evidence_sha256,
            "observed_at": observation.observed_at,
        }

    @staticmethod
    def _critical_observation_from_payload(
        payload: object,
    ) -> CriticalRecoveryObservation | None:
        if not isinstance(payload, dict) or set(payload) != {
            "operation_id",
            "daemon_generation",
            "target",
            "bound_media_identity_sha256",
            "observed_media_identity_sha256",
            "command_ledger_sha256",
            "commands_quiescent",
            "mounted",
            "media_loaded",
            "drive_busy",
            "related_process_count",
            "evidence_category",
            "evidence_sha256",
            "observed_at",
        }:
            return None
        target = payload.get("target")
        if not isinstance(target, dict) or set(target) != {
            "mount_path_sha256",
            "tape_device_identity_sha256",
            "scsi_device_identity_sha256",
            "expected_media_scope_sha256",
        }:
            return None
        try:
            return CriticalRecoveryObservation(
                operation_id=payload["operation_id"],
                daemon_generation=payload["daemon_generation"],
                target=HardwareTargetBinding(
                    target["mount_path_sha256"],
                    target["tape_device_identity_sha256"],
                    target["scsi_device_identity_sha256"],
                    target["expected_media_scope_sha256"],
                ),
                bound_media_identity_sha256=(
                    payload["bound_media_identity_sha256"]
                ),
                observed_media_identity_sha256=(
                    payload["observed_media_identity_sha256"]
                ),
                command_ledger_sha256=payload["command_ledger_sha256"],
                commands_quiescent=payload["commands_quiescent"],
                mounted=payload["mounted"],
                media_loaded=payload["media_loaded"],
                drive_busy=payload["drive_busy"],
                related_process_count=payload["related_process_count"],
                evidence_category=payload["evidence_category"],
                evidence_sha256=payload["evidence_sha256"],
                observed_at=payload["observed_at"],
            )
        except (TypeError, ValueError):
            return None

    def _latest_critical_reassessment_tx(
        self,
        db: sqlite3.Connection,
        operation_id: str,
        attempt_number: int | None = None,
        daemon_generation: int | None = None,
    ) -> CriticalRecoveryObservation | None:
        rows = db.execute(
            "SELECT payload_json FROM audit_entries "
            "WHERE action='critical_recovery.reconcile' AND result='accepted' "
            "ORDER BY id DESC"
        ).fetchall()
        for row in rows:
            try:
                payload = json.loads(row["payload_json"])
            except (TypeError, ValueError):
                continue
            if (
                not isinstance(payload, dict)
                or payload.get("operation_id") != operation_id
                or (
                    attempt_number is not None
                    and payload.get("attempt_number") != attempt_number
                )
            ):
                continue
            observation = self._critical_observation_from_payload(
                payload.get("proof")
            )
            if observation is None or (
                daemon_generation is not None
                and observation.daemon_generation != daemon_generation
            ):
                continue
            return observation
        return None

    def latest_critical_reassessment(
        self,
        operation_id: str,
        *,
        attempt_number: int | None = None,
        daemon_generation: int | None = None,
    ) -> CriticalRecoveryObservation | None:
        self._validate_safe_identifier(operation_id, "critical recovery operation id")
        return self._latest_critical_reassessment_tx(
            self.connection,
            operation_id,
            attempt_number,
            daemon_generation,
        )

    def assert_critical_one_shot_available(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        *,
        principal: str,
        idempotency_key: str,
        action: str,
    ) -> None:
        """Reject an already consumed critical key before any physical observation."""

        if action not in {"reconcile", "abandon", "authorize_replacement"}:
            raise ValidationError("invalid critical recovery action")
        for value, name in (
            (operation_id, "critical recovery operation id"),
            (principal, "critical recovery principal"),
            (idempotency_key, "critical recovery one-shot key"),
        ):
            self._validate_safe_identifier(value, name)
        reused = False
        with self.transaction() as db:
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                self._record_audit_tx(
                    db,
                    principal,
                    f"critical_recovery.{action}",
                    "rejected",
                    self._new_id("critical-replay"),
                    None,
                    json.dumps(
                        {"operation_id": operation_id, "reason": "one_shot_reused"},
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
                reused = True
            else:
                self._assert_daemon_fence_tx(db, daemon_fence)
        if reused:
            raise CatalogError("critical recovery one-shot key was already used")

    def reject_critical_action_once(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        *,
        principal: str,
        idempotency_key: str,
        action: str,
        reason: str,
    ) -> None:
        """Consume one rejected protected action without invoking an observer."""

        if action not in {"reconcile", "abandon", "authorize_replacement"}:
            raise ValidationError("invalid critical recovery action")
        if reason not in {
            "proof_mismatch",
            "observation_incomplete",
            "media_identity_required",
        }:
            raise ValidationError("invalid critical recovery rejection reason")
        for value, name in (
            (operation_id, "critical recovery operation id"),
            (principal, "critical recovery principal"),
            (idempotency_key, "critical recovery one-shot key"),
        ):
            self._validate_safe_identifier(value, name)
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                raise CatalogError("critical recovery one-shot key was already used")
            self._record_audit_tx(
                db,
                principal,
                f"critical_recovery.{action}",
                "rejected",
                idempotency_key,
                None,
                json.dumps(
                    {"operation_id": operation_id, "reason": reason},
                    separators=(",", ":"),
                    sort_keys=True,
                ),
            )

    def reject_critical_action_for_daemon_turnover(
        self,
        operation_id: str,
        stale_daemon_fence: DaemonFence,
        *,
        principal: str,
        idempotency_key: str,
        action: str,
    ) -> None:
        """Consume a stale-owner action without mutating protected recovery state."""

        if action not in {"reconcile", "abandon", "authorize_replacement"}:
            raise ValidationError("invalid critical recovery action")
        for value, name in (
            (operation_id, "critical recovery operation id"),
            (principal, "critical recovery principal"),
            (idempotency_key, "critical recovery one-shot key"),
        ):
            self._validate_safe_identifier(value, name)
        reused = False
        with self.transaction() as db:
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                reused = True
            else:
                current = db.execute(
                    "SELECT owner_id,generation FROM daemon_ownership WHERE singleton=1"
                ).fetchone()
                operation = db.execute(
                    "SELECT state FROM daemon_operations WHERE id=?", (operation_id,)
                ).fetchone()
                attempt = db.execute(
                    "SELECT daemon_generation,state FROM recovery_attempt_events "
                    "WHERE operation_id=? ORDER BY attempt_number DESC,event_sequence "
                    "DESC LIMIT 1",
                    (operation_id,),
                ).fetchone()
                if (
                    current is None
                    or (
                        current["owner_id"] == stale_daemon_fence.owner_id
                        and current["generation"] == stale_daemon_fence.generation
                    )
                    or operation is None
                    or operation["state"] != "recovery_required"
                    or attempt is None
                    or attempt["state"] != "critical_quarantine"
                    or attempt["daemon_generation"] != stale_daemon_fence.generation
                ):
                    raise CatalogError(
                        "critical recovery daemon turnover proof is unavailable"
                    )
                self._record_audit_tx(
                    db,
                    principal,
                    f"critical_recovery.{action}",
                    "rejected",
                    idempotency_key,
                    None,
                    json.dumps(
                        {
                            "operation_id": operation_id,
                            "reason": "daemon_generation_changed",
                            "expected_generation": stale_daemon_fence.generation,
                            "current_generation": current["generation"],
                        },
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
        if reused:
            raise CatalogError("critical recovery one-shot key was already used")

    def _critical_observation_matches_current_tx(
        self,
        db: sqlite3.Connection,
        observation: CriticalRecoveryObservation,
        consumed_at: str,
        *,
        physical_policy: Literal["observe", "empty", "exact_loaded"],
    ) -> bool:
        observed = self._parse_utc_timestamp(observation.observed_at)
        consumed = self._parse_utc_timestamp(consumed_at)
        if (
            observed is None
            or consumed is None
            or observed > consumed
            or consumed - observed > _CRITICAL_ACTION_PROOF_MAX_AGE
        ):
            return False
        target = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (observation.operation_id,),
        ).fetchone()
        binding = db.execute(
            "SELECT observed_media_identity_sha256 FROM "
            "operation_media_identity_bindings WHERE operation_id=?",
            (observation.operation_id,),
        ).fetchone()
        commands = self.hardware_commands_for_operation(observation.operation_id)
        commands_quiescent = bool(commands) and all(
            command.state == "quiesced" for command in commands
        )
        bound_media_matches = bool(
            (
                binding is not None
                and binding["observed_media_identity_sha256"]
                == observation.bound_media_identity_sha256
            )
            or (
                physical_policy == "empty"
                and binding is None
                and observation.bound_media_identity_sha256 is None
            )
        )
        if (
            target is None
            or self._target_values(observation.target)
            != tuple(
                target[name]
                for name in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
            or not bound_media_matches
            or critical_command_ledger_sha256(commands)
            != observation.command_ledger_sha256
            or commands_quiescent != observation.commands_quiescent
        ):
            return False
        if observation.media_loaded != (
            observation.observed_media_identity_sha256 is not None
        ):
            return False
        if physical_policy == "observe":
            return True
        physically_safe = bool(
            observation.commands_quiescent
            and not observation.mounted
            and not observation.drive_busy
            and observation.related_process_count == 0
        )
        if physical_policy == "empty":
            return bool(
                physically_safe
                and not observation.media_loaded
                and observation.observed_media_identity_sha256 is None
            )
        return bool(
            physically_safe
            and observation.media_loaded
            and observation.observed_media_identity_sha256
            == observation.bound_media_identity_sha256
        )

    def record_critical_reassessment(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        *,
        principal: str,
        idempotency_key: str,
        job_id: str,
        cassette_sequence: int,
        expected_label: str,
        expected_daemon_generation: int,
        attempt_number: int,
        evidence_sha256: str,
        target: HardwareTargetBinding,
        observed_media_identity_sha256: str | None,
        observation: CriticalRecoveryObservation,
        consumed_at: str,
        observation_started_at: str | None = None,
    ) -> None:
        """Consume one protected observation action without changing recovery state."""

        self._validate_safe_identifier(operation_id, "critical recovery operation id")
        self._validate_safe_identifier(principal, "critical recovery principal")
        self._validate_safe_identifier(idempotency_key, "critical recovery one-shot key")
        self._validate_safe_identifier(job_id, "critical recovery job id")
        self._validate_safe_identifier(expected_label, "critical expected label")
        self._validate_sha256(evidence_sha256, "critical recovery evidence")
        if observed_media_identity_sha256 is not None:
            self._validate_sha256(
                observed_media_identity_sha256, "critical observed media identity"
            )
        if (
            type(attempt_number) is not int
            or attempt_number <= 0
            or type(cassette_sequence) is not int
            or cassette_sequence <= 0
            or type(expected_daemon_generation) is not int
            or expected_daemon_generation <= 0
            or not isinstance(target, HardwareTargetBinding)
            or not isinstance(observation, CriticalRecoveryObservation)
            or self._parse_utc_timestamp(consumed_at) is None
        ):
            raise ValidationError("invalid critical recovery attempt")
        rejection: str | None = None
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.reconcile",
                    "rejected",
                    self._new_id("critical-replay"),
                    None,
                    json.dumps(
                        {"operation_id": operation_id, "reason": "one_shot_reused"},
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
                rejection = "critical recovery one-shot key was already used"
            else:
                operation = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
                ).fetchone()
                attempt = db.execute(
                    "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                    "AND attempt_number=? AND event_sequence=2",
                    (operation_id, attempt_number),
                ).fetchone()
                cassette_label = None
                if operation is not None:
                    try:
                        cassette_label = self._operation_cassette_label_tx(
                            db, operation
                        )
                    except CatalogError:
                        pass
                durable_target = db.execute(
                    "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                binding = db.execute(
                    "SELECT observed_media_identity_sha256 FROM "
                    "operation_media_identity_bindings WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                latest = self._latest_critical_reassessment_tx(
                    db,
                    operation_id,
                    attempt_number,
                    daemon_fence.generation,
                )
                current_evidence_sha256 = (
                    attempt["evidence_sha256"]
                    if latest is None and attempt is not None
                    else None if latest is None else latest.evidence_sha256
                )
                current_media_identity_sha256 = (
                    None
                    if binding is None
                    else binding["observed_media_identity_sha256"]
                )
                if latest is not None:
                    current_media_identity_sha256 = (
                        latest.observed_media_identity_sha256
                        or latest.bound_media_identity_sha256
                    )
                # Re-evaluation may identify the first medium. Accept that
                # observation, not a replacement/resume authority, only when a
                # successful identify and seal were created during this action.
                fresh_binding = db.execute(
                    "SELECT b.bound_at,c.* FROM operation_media_identity_bindings b "
                    "JOIN hardware_command_executions c ON c.id=b.bound_by_command_id "
                    "WHERE b.operation_id=?", (operation_id,),
                ).fetchone()
                started = self._parse_utc_timestamp(observation_started_at)
                observed_at = self._parse_utc_timestamp(observation.observed_at)
                first_identification = bool(
                    observed_media_identity_sha256 is None
                    and latest is None and binding is not None
                    and operation is not None
                    and operation["kind"] == "archive.native"
                    and operation["phase"] is None
                    and started is not None and observed_at is not None
                    and fresh_binding is not None
                    and fresh_binding["operation_id"] == operation_id
                    and fresh_binding["issued_generation"] == daemon_fence.generation
                    and fresh_binding["command_kind"] == "identify"
                    and fresh_binding["state"] == "quiesced"
                    and fresh_binding["exit_outcome"] == "completed"
                    and fresh_binding["terminal_exit_code"] == 0
                    and fresh_binding["observed_media_identity_sha256"] is None
                    and (created := self._parse_utc_timestamp(fresh_binding["created_at"])) is not None
                    and (bound_at := self._parse_utc_timestamp(fresh_binding["bound_at"])) is not None
                    and started <= created <= bound_at <= observed_at
                    and observation.observed_media_identity_sha256 == current_media_identity_sha256
                    and observation.bound_media_identity_sha256 == current_media_identity_sha256
                )
                if (
                    operation is None
                    or operation["state"] != "recovery_required"
                    or operation["job_id"] != job_id
                    or operation["cassette_sequence"] != cassette_sequence
                    or cassette_label is None
                    or cassette_label.casefold() != expected_label.casefold()
                    or attempt is None
                    or attempt["state"] != "critical_quarantine"
                    or current_evidence_sha256 != evidence_sha256
                    or attempt["daemon_generation"] != daemon_fence.generation
                    or attempt["daemon_generation"] != expected_daemon_generation
                    or durable_target is None
                    or tuple(
                        durable_target[name]
                        for name in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                    != self._target_values(target)
                    or (not first_identification and (
                        (binding is None) != (observed_media_identity_sha256 is None)
                        or current_media_identity_sha256 != observed_media_identity_sha256
                    ))
                ):
                    result = "rejected"
                    rejection = "critical recovery proof is stale or mismatched"
                elif (
                    observation.operation_id != operation_id
                    or observation.daemon_generation != daemon_fence.generation
                    or observation.target != target
                    or observation.bound_media_identity_sha256
                    != current_media_identity_sha256
                    or not self._critical_observation_matches_current_tx(
                        db,
                        observation,
                        consumed_at,
                        physical_policy=(
                            "empty"
                            if observed_media_identity_sha256 is None and not first_identification
                            else "observe"
                        ),
                    )
                ):
                    result = "rejected"
                    rejection = "critical reassessment proof is stale or incomplete"
                else:
                    result = "accepted"
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.reconcile",
                    result,
                    idempotency_key,
                    None,
                    json.dumps(
                        {
                            "operation_id": operation_id,
                            "attempt_number": attempt_number,
                            "job_id": job_id,
                            "cassette_sequence": cassette_sequence,
                            "expected_label": expected_label,
                            "base_evidence_sha256": evidence_sha256,
                            "proof": self._critical_observation_payload(observation),
                        },
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
        if rejection is not None:
            raise CatalogError(rejection)

    def abandon_critical_attempt(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        *,
        principal: str,
        idempotency_key: str,
        job_id: str,
        cassette_sequence: int,
        expected_label: str,
        expected_daemon_generation: int,
        attempt_number: int,
        evidence_sha256: str,
        target: HardwareTargetBinding,
        observed_media_identity_sha256: str | None,
        observation: CriticalRecoveryObservation,
        consumed_at: str,
    ) -> OperationRecord:
        """Fail one quarantined attempt only after exact terminal quiescence proof."""

        for value, name in (
            (operation_id, "critical recovery operation id"),
            (principal, "critical recovery principal"),
            (idempotency_key, "critical recovery one-shot key"),
            (job_id, "critical recovery job id"),
        ):
            self._validate_safe_identifier(value, name)
        self._validate_sha256(evidence_sha256, "critical recovery evidence")
        if observed_media_identity_sha256 is not None:
            self._validate_sha256(
                observed_media_identity_sha256, "critical observed media identity"
            )
        if (
            type(cassette_sequence) is not int
            or cassette_sequence <= 0
            or type(attempt_number) is not int
            or attempt_number <= 0
            or type(expected_daemon_generation) is not int
            or expected_daemon_generation <= 0
            or not isinstance(target, HardwareTargetBinding)
            or not isinstance(observation, CriticalRecoveryObservation)
            or self._parse_utc_timestamp(consumed_at) is None
        ):
            raise ValidationError("invalid critical recovery identity")
        rejection: str | None = None
        result: OperationRecord | None = None
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.abandon",
                    "rejected",
                    self._new_id("critical-replay"),
                    None,
                    json.dumps(
                        {"operation_id": operation_id, "reason": "one_shot_reused"},
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
                rejection = "critical recovery one-shot key was already used"
            else:
                operation = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
                ).fetchone()
                cassette_label = None
                if operation is not None:
                    try:
                        cassette_label = self._operation_cassette_label_tx(
                            db, operation
                        )
                    except CatalogError:
                        pass
                durable_target = db.execute(
                    "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                binding = db.execute(
                    "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                attempt = db.execute(
                    "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                    "AND attempt_number=? AND event_sequence=2",
                    (operation_id, attempt_number),
                ).fetchone()
                command_receipt = None
                physical = None
                target_values = self._target_values(target)
                durable_target_values = (
                    (None, None, None, None)
                    if durable_target is None
                    else tuple(
                        durable_target[name]
                        for name in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                )
                latest = self._latest_critical_reassessment_tx(
                    db,
                    operation_id,
                    attempt_number,
                    daemon_fence.generation,
                )
                current_evidence_sha256 = (
                    attempt["evidence_sha256"]
                    if latest is None and attempt is not None
                    else None if latest is None else latest.evidence_sha256
                )
                current_media_identity_sha256 = (
                    None
                    if binding is None
                    else binding["observed_media_identity_sha256"]
                )
                if latest is not None:
                    current_media_identity_sha256 = (
                        latest.observed_media_identity_sha256
                        or latest.bound_media_identity_sha256
                    )
                identity_valid = bool(
                    operation is not None
                    and operation["state"] == "recovery_required"
                    and operation["job_id"] == job_id
                    and operation["cassette_sequence"] == cassette_sequence
                    and cassette_label is not None
                    and cassette_label.casefold() == expected_label.casefold()
                    and attempt is not None
                    and attempt["state"] == "critical_quarantine"
                    and current_evidence_sha256 == evidence_sha256
                    and attempt["daemon_generation"] == daemon_fence.generation
                    and attempt["daemon_generation"] == expected_daemon_generation
                    and durable_target is not None
                    and durable_target_values == target_values
                    and (binding is None) == (observed_media_identity_sha256 is None)
                    and current_media_identity_sha256
                    == observed_media_identity_sha256
                )
                quiescence_valid = bool(
                    identity_valid
                    and observation.operation_id == operation_id
                    and observation.daemon_generation == daemon_fence.generation
                    and observation.target == target
                    and observation.bound_media_identity_sha256
                    == current_media_identity_sha256
                    and self._critical_observation_matches_current_tx(
                        db,
                        observation,
                        consumed_at,
                        physical_policy="empty",
                    )
                )
                if not identity_valid:
                    rejection = "critical recovery proof is stale or mismatched"
                elif not quiescence_valid:
                    rejection = "critical recovery ownership is not quiescent"
                if rejection is not None:
                    audit_result = "rejected"
                else:
                    fresh_command = self.create_command_quiescence_receipt(
                        operation_id, daemon_fence
                    )
                    fresh_physical = self.create_physical_reconciliation_receipt(
                        operation_id,
                        daemon_fence,
                        fresh_command.id,
                        VerifiedPhysicalQuiescence(
                            target=target,
                            observed_media_identity_sha256=(
                                observation.bound_media_identity_sha256
                            ),
                            mounted=False,
                            media_loaded=False,
                            drive_busy=False,
                            related_processes=(),
                        ),
                    )
                    command_receipt = db.execute(
                        "SELECT * FROM command_quiescence_receipts WHERE id=?",
                        (fresh_command.id,),
                    ).fetchone()
                    physical = db.execute(
                        "SELECT * FROM physical_reconciliation_receipts WHERE id=?",
                        (fresh_physical.id,),
                    ).fetchone()
                    assert command_receipt is not None and physical is not None
                    finished_at = self._precise_utc_now(
                        after=physical["recorded_at"]
                    )
                    db.execute(
                        "INSERT INTO recovery_resolutions("
                        "operation_id,resolved_by_generation,reason_code,"
                        "command_receipt_id,physical_receipt_id,resolved_at) "
                        "VALUES(?,?,?,?,?,?)",
                        (
                            operation_id,
                            daemon_fence.generation,
                            "critical_attempt_abandoned",
                            command_receipt["id"],
                            physical["id"],
                            finished_at,
                        ),
                    )
                    db.execute(
                        "UPDATE daemon_operations SET state='failed',finished_at=?,"
                        "error_class='terminal_safety_failure',"
                        "error_code='operation_failed',error_message=? WHERE id=?",
                        (finished_at, _SAFE_ERROR_MESSAGES["operation_failed"], operation_id),
                    )
                    result = self._operation_from_row(
                        db.execute(
                            "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
                        ).fetchone()
                    )
                    audit_result = "accepted"
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.abandon",
                    audit_result,
                    idempotency_key,
                    None,
                    json.dumps(
                        {
                            "operation_id": operation_id,
                            "job_id": job_id,
                            "cassette_sequence": cassette_sequence,
                            "expected_label": expected_label,
                            "attempt_number": attempt_number,
                            "evidence_sha256": evidence_sha256,
                            "action_proof": self._critical_observation_payload(
                                observation
                            ),
                        },
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
        if rejection is not None:
            raise CatalogError(rejection)
        assert result is not None
        return result

    def authorize_critical_replacement(
        self,
        operation_id: str,
        daemon_fence: RecoveryCommandFence,
        replacement_candidate: OperationRecord,
        *,
        principal: str,
        idempotency_key: str,
        job_id: str,
        cassette_sequence: int,
        expected_label: str,
        attempt_number: int,
        evidence_sha256: str,
        target: HardwareTargetBinding,
        observed_media_identity_sha256: str,
        observation: CriticalRecoveryObservation,
        consumed_at: str,
    ) -> OperationRecord:
        """Terminalize and replace one exact critical attempt in one transaction."""

        for value, name in (
            (operation_id, "critical recovery operation id"),
            (principal, "critical recovery principal"),
            (idempotency_key, "critical recovery one-shot key"),
            (job_id, "critical recovery job id"),
            (expected_label, "critical recovery expected label"),
        ):
            self._validate_safe_identifier(value, name)
        self._validate_sha256(evidence_sha256, "critical recovery evidence")
        self._validate_sha256(
            observed_media_identity_sha256, "critical observed media identity"
        )
        if (
            type(daemon_fence) is not RecoveryCommandFence
            or daemon_fence.operation_id != operation_id
            or type(cassette_sequence) is not int
            or cassette_sequence <= 0
            or type(attempt_number) is not int
            or attempt_number <= 0
            or not isinstance(target, HardwareTargetBinding)
            or not isinstance(observation, CriticalRecoveryObservation)
            or self._parse_utc_timestamp(consumed_at) is None
        ):
            raise ValidationError("invalid critical recovery identity")
        self._validate_candidate(replacement_candidate)
        rejection: str | None = None
        rejection_reason: str | None = None
        replacement: OperationRecord | None = None
        with self.transaction() as db:
            current_daemon = self.current_daemon_fence()
            generation_changed = bool(
                current_daemon is None
                or current_daemon.generation != daemon_fence.owner_generation
            )
            if db.execute(
                "SELECT 1 FROM audit_entries WHERE request_id=? LIMIT 1",
                (idempotency_key,),
            ).fetchone() is not None:
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.authorize_replacement",
                    "rejected",
                    self._new_id("critical-replay"),
                    None,
                    json.dumps(
                        {"operation_id": operation_id, "reason": "one_shot_reused"},
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
                rejection = "critical recovery one-shot key was already used"
            else:
                operation = db.execute(
                    "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
                ).fetchone()
                cassette = db.execute(
                    "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                    (job_id, cassette_sequence),
                ).fetchone()
                durable_target = db.execute(
                    "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                binding = db.execute(
                    "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                attempt = db.execute(
                    "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                    "AND attempt_number=? AND event_sequence=2",
                    (operation_id, attempt_number),
                ).fetchone()
                command_receipt = None
                target_values = self._target_values(target)
                durable_target_values = (
                    (None, None, None, None)
                    if durable_target is None
                    else tuple(
                        durable_target[name]
                        for name in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                )
                latest = self._latest_critical_reassessment_tx(
                    db,
                    operation_id,
                    attempt_number,
                    daemon_fence.owner_generation,
                )
                current_evidence_sha256 = (
                    attempt["evidence_sha256"]
                    if latest is None and attempt is not None
                    else None if latest is None else latest.evidence_sha256
                )
                current_media_identity_sha256 = (
                    None
                    if binding is None
                    else binding["observed_media_identity_sha256"]
                )
                if latest is not None:
                    current_media_identity_sha256 = (
                        latest.observed_media_identity_sha256
                        or latest.bound_media_identity_sha256
                    )
                identity_valid = bool(
                    operation is not None
                    and operation["kind"] == "archive.native"
                    and operation["state"] == "recovery_required"
                    and operation["job_id"] == job_id
                    and operation["cassette_sequence"] == cassette_sequence
                    and cassette is not None
                    and str(cassette["physical_label"]).casefold()
                    == expected_label.casefold()
                    and attempt is not None
                    and attempt["state"] == "critical_quarantine"
                    and current_evidence_sha256 == evidence_sha256
                    and attempt["daemon_generation"]
                    == daemon_fence.owner_generation
                    and current_daemon is not None
                    and attempt["daemon_generation"] == current_daemon.generation
                    and durable_target_values == target_values
                    and binding is not None
                    and current_media_identity_sha256
                    == observed_media_identity_sha256
                )
                quiescence_valid = bool(
                    identity_valid
                    and observation.operation_id == operation_id
                    and observation.daemon_generation
                    == daemon_fence.owner_generation
                    and observation.target == target
                    and observation.bound_media_identity_sha256
                    == binding["observed_media_identity_sha256"]
                    and self._critical_observation_matches_current_tx(
                        db,
                        observation,
                        consumed_at,
                        physical_policy="exact_loaded",
                    )
                )
                if not identity_valid:
                    rejection = "critical recovery proof is stale or mismatched"
                    rejection_reason = (
                        "daemon_generation_changed"
                        if generation_changed
                        else "proof_mismatch"
                    )
                elif not quiescence_valid:
                    rejection = "critical recovery ownership is not quiescent"
                    rejection_reason = "action_proof_mismatch"
                if rejection is None:
                    try:
                        with self.transaction():
                            assert current_daemon is not None
                            fresh_command = self.create_command_quiescence_receipt(
                                operation_id, current_daemon
                            )
                            command_receipt = db.execute(
                                "SELECT * FROM command_quiescence_receipts WHERE id=?",
                                (fresh_command.id,),
                            ).fetchone()
                            assert command_receipt is not None
                            reset = self.reset_automatic_cassette_for_recovery(
                                daemon_fence,
                                "critical_replacement_authorized",
                                replacement_candidate=replacement_candidate,
                            )
                            replacement = reset.get("replacement")
                            if not isinstance(replacement, OperationRecord):
                                raise CatalogError(
                                    "critical recovery replacement was not admitted"
                                )
                    except (
                        CatalogError,
                        OperationConflict,
                        StaleDaemonFence,
                        StaleOperationFence,
                        ValidationError,
                    ):
                        rejection = (
                            "critical recovery replacement proof is incomplete"
                        )
                        rejection_reason = "replacement_admission_failed"
                if rejection is not None:
                    audit_result = "rejected"
                else:
                    finished_at = self._precise_utc_now(
                        after=command_receipt["recorded_at"]
                    )
                    db.execute(
                        "UPDATE daemon_operations SET state='failed',finished_at=?,"
                        "error_class='terminal_safety_failure',"
                        "error_code='operation_failed',error_message=? WHERE id=?",
                        (
                            finished_at,
                            _SAFE_ERROR_MESSAGES["operation_failed"],
                            operation_id,
                        ),
                    )
                    audit_result = "accepted"
                audit_payload: dict[str, object] = {
                    "operation_id": operation_id,
                    "job_id": job_id,
                    "cassette_sequence": cassette_sequence,
                    "expected_label": expected_label,
                    "attempt_number": attempt_number,
                    "evidence_sha256": evidence_sha256,
                    "command_receipt_id": (
                        None
                        if command_receipt is None
                        else command_receipt["id"]
                    ),
                    "replacement_operation_id": (
                        None if replacement is None else replacement.id
                    ),
                    "action_proof": self._critical_observation_payload(observation),
                }
                if rejection_reason is not None:
                    audit_payload["reason"] = rejection_reason
                if rejection_reason == "daemon_generation_changed":
                    audit_payload["expected_generation"] = (
                        daemon_fence.owner_generation
                    )
                    audit_payload["current_generation"] = (
                        None if current_daemon is None else current_daemon.generation
                    )
                self._record_audit_tx(
                    db,
                    principal,
                    "critical_recovery.authorize_replacement",
                    audit_result,
                    idempotency_key,
                    None,
                    json.dumps(
                        audit_payload,
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                )
        if rejection is not None:
            raise CatalogError(rejection)
        assert replacement is not None
        return replacement

    def reserve_event_id(self) -> int:
        with self.transaction() as db:
            cursor = db.execute(
                "INSERT INTO daemon_event_sequence(reserved_at) VALUES(?)",
                (self._precise_utc_now(),),
            )
            return int(cursor.lastrowid)

    def latest_reserved_event_id(self) -> int:
        row = self.connection.execute(
            "SELECT COALESCE(MAX(id), 0) FROM daemon_event_sequence"
        ).fetchone()
        return int(row[0])

    def reserve_hardware_command(
        self,
        fence: OperationFence | RecoveryCommandFence,
        command_id: str,
        kind: str,
        argv_sha256: str,
    ) -> None:
        self._validate_safe_identifier(command_id, "command id")
        if kind not in _HARDWARE_COMMAND_KINDS:
            raise ValidationError("hardware command kind is not allowlisted")
        self._validate_sha256(argv_sha256, "command argument digest")
        with self.transaction() as db:
            self._assert_command_fence_tx(db, fence)
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if target is None:
                raise ValidationError("hardware command requires an admitted target")
            media = db.execute(
                """
                SELECT observed_media_identity_sha256
                FROM operation_media_identity_bindings WHERE operation_id=?
                """,
                (fence.operation_id,),
            ).fetchone()
            db.execute(
                """
                INSERT INTO hardware_command_executions(
                    id, operation_id, issued_generation, command_kind, argv_sha256,
                    mount_path_sha256, tape_device_identity_sha256,
                    scsi_device_identity_sha256, expected_media_scope_sha256,
                    observed_media_identity_sha256, state, created_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'launch_reserved', ?)
                """,
                (
                    command_id,
                    fence.operation_id,
                    fence.owner_generation,
                    kind,
                    argv_sha256,
                    target["mount_path_sha256"],
                    target["tape_device_identity_sha256"],
                    target["scsi_device_identity_sha256"],
                    target["expected_media_scope_sha256"],
                    None if media is None else media["observed_media_identity_sha256"],
                    self._precise_utc_now(),
                ),
            )

    def bind_observed_media_identity(
        self, fence: OperationFence, media_identity_sha256: str
    ) -> None:
        self._validate_sha256(media_identity_sha256, "observed media digest")
        mismatch = False
        with self.transaction() as db:
            self._assert_operation_fence_tx(db, fence)
            command = db.execute(
                """
                SELECT id, command_kind, state, exit_outcome
                FROM hardware_command_executions
                WHERE operation_id=? ORDER BY created_at DESC, id DESC LIMIT 1
                """,
                (fence.operation_id,),
            ).fetchone()
            if (
                command is None
                or command["command_kind"] != "probe_media"
                or command["state"] != "quiesced"
                or command["exit_outcome"] != "completed"
            ):
                raise CommandQuiescenceRequired(
                    "observed media requires a completed, quiescent media probe"
                )
            existing = db.execute(
                """
                SELECT observed_media_identity_sha256
                FROM operation_media_identity_bindings WHERE operation_id=?
                """,
                (fence.operation_id,),
            ).fetchone()
            if existing is not None:
                if existing["observed_media_identity_sha256"] != media_identity_sha256:
                    db.execute(
                        """
                        UPDATE daemon_operations
                        SET state='recovery_required', finished_at=NULL,
                            error_class='operator_required',
                            error_code='media_target_mismatch',
                            error_message=?
                        WHERE id=?
                        """,
                        (
                            _SAFE_ERROR_MESSAGES["media_target_mismatch"],
                            fence.operation_id,
                        ),
                    )
                    mismatch = True
            else:
                db.execute(
                    """
                    INSERT INTO operation_media_identity_bindings(
                        operation_id, observed_media_identity_sha256,
                        bound_by_command_id, bound_at
                    ) VALUES(?, ?, ?, ?)
                    """,
                    (
                        fence.operation_id,
                        media_identity_sha256,
                        command["id"],
                        self._precise_utc_now(),
                    ),
                )
        if mismatch:
            raise MediaTargetMismatch()

    def bind_recovery_observed_media_identity(
        self,
        fence: RecoveryCommandFence,
        media_identity_sha256: str,
    ) -> None:
        """Bind a first exact media identity from a fenced recovery identify."""

        self._validate_sha256(media_identity_sha256, "observed media digest")
        with self.transaction() as db:
            operation = self._assert_command_fence_tx(db, fence)
            existing = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if existing is not None:
                if existing["observed_media_identity_sha256"] != media_identity_sha256:
                    raise MediaTargetMismatch()
                return
            lineage = db.execute(
                "SELECT * FROM operation_recovery_lineages WHERE operation_id=? "
                "ORDER BY recovery_generation DESC LIMIT 1",
                (fence.operation_id,),
            ).fetchone()
            command = db.execute(
                "SELECT * FROM hardware_command_executions WHERE operation_id=? "
                "ORDER BY created_at DESC,id DESC LIMIT 1",
                (fence.operation_id,),
            ).fetchone()
            if (
                lineage is None
                or lineage["recovery_generation"] != fence.owner_generation
                or lineage["original_generation"] != operation["owner_generation"]
                or command is None
                or command["issued_generation"] != fence.owner_generation
                or command["command_kind"] != "identify"
                or command["state"] != "quiesced"
                or command["exit_outcome"] != "completed"
                or command["observed_media_identity_sha256"] is not None
                or command["created_at"] < lineage["recorded_at"]
            ):
                raise ValidationError("recovery media identification is not exact")
            db.execute(
                "INSERT INTO operation_media_identity_bindings("
                "operation_id,observed_media_identity_sha256,bound_by_command_id,"
                "bound_at) VALUES(?,?,?,?)",
                (
                    fence.operation_id,
                    media_identity_sha256,
                    command["id"],
                    self._precise_utc_now(after=command["quiesced_at"]),
                ),
            )

    def rebind_observed_media_after_confirmed_format(
        self,
        fence: OperationFence,
        *,
        pre_media_identity_sha256: str,
        post_media_identity_sha256: str,
        pre_observed_serial: str,
        observed_label: str,
        observed_serial: str,
        post_volume_uuid: str,
        post_index_generation: int,
    ) -> None:
        """Replace only the one pre-format media seal under consumed authority."""

        self._validate_sha256(pre_media_identity_sha256, "pre-format media digest")
        self._validate_sha256(post_media_identity_sha256, "post-format media digest")
        if pre_media_identity_sha256 == post_media_identity_sha256:
            raise ValidationError("post-format media identity did not change")
        for value, maximum in (
            (observed_label, 255),
            (pre_observed_serial, 32),
            (observed_serial, 32),
        ):
            if (
                type(value) is not str
                or not 0 < len(value) <= maximum
                or value != value.strip(" ")
                or not value.isascii()
                or not value.isprintable()
            ):
                raise ValidationError("post-format media identity is invalid")
        try:
            if str(uuid.UUID(post_volume_uuid)) != post_volume_uuid:
                raise ValueError
        except (AttributeError, TypeError, ValueError):
            raise ValidationError("post-format media identity is invalid") from None
        if (
            type(post_index_generation) is not int
            or not 0 < post_index_generation < 1 << 64
        ):
            raise ValidationError("post-format media identity is invalid")
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            policy = db.execute(
                "SELECT 1 FROM imported_job_policies WHERE job_id=?",
                (operation["job_id"],),
            ).fetchone()
            if policy is not None:
                job_id, sequence, _policy, cassette = (
                    self._imported_archive_operation_tx(db, operation)
                )
            else:
                job_id = operation["job_id"]
                sequence = operation["cassette_sequence"]
                cassette = db.execute(
                    "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                    (job_id, sequence),
                ).fetchone()
                if operation["kind"] != "archive.native" or cassette is None:
                    raise ValidationError("post-format media identity is invalid")
            confirmation = db.execute(
                "SELECT * FROM format_confirmations WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            binding = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            existing = db.execute(
                "SELECT * FROM format_media_rebindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if existing is not None:
                expected = (
                    fence.owner_generation,
                    pre_media_identity_sha256,
                    post_media_identity_sha256,
                    observed_label,
                    pre_observed_serial,
                    observed_serial,
                    post_volume_uuid,
                    post_index_generation,
                )
                actual = (
                    existing["owner_generation"],
                    existing["pre_media_identity_sha256"],
                    existing["post_media_identity_sha256"],
                    existing["observed_label"],
                    existing["expected_serial"],
                    existing["observed_serial"],
                    existing["post_volume_uuid"],
                    existing["post_index_generation"],
                )
                if (
                    expected != actual
                    or binding is None
                    or binding["observed_media_identity_sha256"]
                    != existing["post_media_identity_sha256"]
                    or binding["bound_by_command_id"]
                    != existing["post_probe_media_command_id"]
                ):
                    raise ValidationError("post-format media rebinding conflicts")
                return
            commands = self._commands_with_release_for_operation_tx(
                db, fence.operation_id
            )
            pre_index = next(
                (
                    index
                    for index, row in enumerate(commands)
                    if binding is not None
                    and row["id"] == binding["bound_by_command_id"]
                ),
                None,
            )
            tail = () if pre_index is None else commands[pre_index + 1 :]
            tail_kinds = tuple(row["command_kind"] for row in tail)
            proof_indexes = {
                ("inquiry", "format", "identify", "probe_media"): (1, 3),
                (
                    "inquiry",
                    "probe_media",
                    "format",
                    "identify",
                    "probe_media",
                ): (2, 4),
            }.get(tail_kinds)
            if (
                operation["phase"] != "formatting_media"
                or cassette["operation"] != "format"
                or confirmation is None
                or confirmation["job_id"] != job_id
                or confirmation["cassette_sequence"] != sequence
                or confirmation["expected_label"] != cassette["physical_label"]
                or observed_label != cassette["physical_label"]
                or observed_serial != pre_observed_serial
                or binding is None
                or binding["observed_media_identity_sha256"]
                != pre_media_identity_sha256
                or pre_index is None
                or proof_indexes is None
                or any(
                    row["issued_generation"] != fence.owner_generation
                    or row["state"] != "quiesced"
                    or row["exit_outcome"] != "completed"
                    or row["observed_media_identity_sha256"]
                    != pre_media_identity_sha256
                    for row in tail
                )
            ):
                raise ValidationError("post-format media rebinding is unauthorized")
            assert proof_indexes is not None
            format_index, post_probe_index = proof_indexes
            now = self._precise_utc_now(after=tail[-1]["quiesced_at"])
            db.execute(
                "INSERT INTO format_media_rebindings("
                "operation_id,owner_generation,confirmation_confirmed_at,"
                "pre_probe_media_command_id,format_command_id,post_probe_media_command_id,"
                "expected_label,observed_label,expected_serial,observed_serial,"
                "post_volume_uuid,post_index_generation,pre_media_identity_sha256,"
                "post_media_identity_sha256,recorded_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    fence.operation_id,
                    fence.owner_generation,
                    confirmation["confirmed_at"],
                    binding["bound_by_command_id"],
                    tail[format_index]["id"],
                    tail[post_probe_index]["id"],
                    cassette["physical_label"],
                    observed_label,
                    pre_observed_serial,
                    observed_serial,
                    post_volume_uuid,
                    post_index_generation,
                    pre_media_identity_sha256,
                    post_media_identity_sha256,
                    now,
                ),
            )
            updated = db.execute(
                "UPDATE operation_media_identity_bindings SET "
                "observed_media_identity_sha256=?,bound_by_command_id=?,bound_at=? "
                "WHERE operation_id=? AND observed_media_identity_sha256=?",
                (
                    post_media_identity_sha256,
                    tail[post_probe_index]["id"],
                    now,
                    fence.operation_id,
                    pre_media_identity_sha256,
                ),
            )
            if updated.rowcount != 1:
                raise ValidationError("post-format media rebinding is unauthorized")

    def record_blocked_process(
        self,
        command_id: str,
        fence: OperationFence | RecoveryCommandFence,
        identity: ProcessIdentity,
    ) -> None:
        self._validate_process_identity(identity)
        with self.transaction() as db:
            self._assert_command_fence_tx(db, fence)
            command = self._command_for_fence_tx(db, command_id, fence)
            if command["state"] != "launch_reserved":
                raise CatalogError("command launch identity is already recorded")
            db.execute(
                """
                UPDATE hardware_command_executions
                SET state='launch_blocked', boot_id=?, pid=?, process_start_ticks=?,
                    process_group_id=? WHERE id=?
                """,
                (
                    identity.boot_id,
                    identity.pid,
                    identity.start_ticks,
                    identity.process_group_id,
                    command_id,
                ),
            )

    def authorize_hardware_command_release(
        self,
        command_id: str,
        fence: OperationFence | RecoveryCommandFence,
        permit_sha256: str,
    ) -> None:
        self._validate_sha256(permit_sha256, "command release permit")
        with self.transaction() as db:
            self._assert_command_fence_tx(db, fence)
            command = self._command_for_fence_tx(db, command_id, fence)
            if command["release_status"] is not None:
                if (
                    command["state"] == "launch_blocked"
                    and command["release_status"] == "authorized"
                    and command["release_permit_sha256"] == permit_sha256
                ):
                    return
                raise CatalogError("command release authorization already differs")
            if command["state"] != "launch_blocked":
                raise CatalogError("command is not waiting at its launch gate")
            reused = db.execute(
                """
                SELECT command_id FROM hardware_command_release_authorizations
                WHERE permit_sha256=?
                """,
                (permit_sha256,),
            ).fetchone()
            if reused is not None and reused["command_id"] != command_id:
                raise CatalogError("command release permit was reused")
            db.execute(
                """
                INSERT INTO hardware_command_release_authorizations(
                    command_id, permit_sha256, release_status, authorized_at
                ) VALUES(?, ?, 'authorized', ?)
                """,
                (command_id, permit_sha256, self._precise_utc_now()),
            )

    def confirm_hardware_command_released(
        self,
        command_id: str,
        fence: OperationFence | RecoveryCommandFence,
        permit_sha256: str,
    ) -> None:
        self._validate_sha256(permit_sha256, "command release permit")
        with self.transaction() as db:
            self._assert_command_fence_tx(db, fence)
            command = self._command_for_fence_tx(db, command_id, fence)
            if (
                command["state"] == "released"
                and command["release_status"] == "released"
                and command["release_permit_sha256"] == permit_sha256
            ):
                return
            if (
                command["state"] != "launch_blocked"
                or command["release_status"] != "authorized"
                or command["release_permit_sha256"] != permit_sha256
            ):
                raise CatalogError("command release authorization does not match")
            now = self._precise_utc_now()
            db.execute(
                """
                UPDATE hardware_command_release_authorizations
                SET release_status='released', confirmed_at=? WHERE command_id=?
                """,
                (now, command_id),
            )
            db.execute(
                """
                UPDATE hardware_command_executions
                SET state='released', released_at=? WHERE id=?
                """,
                (now, command_id),
            )

    def mark_hardware_command_release_aborted(
        self,
        command_id: str,
        daemon_fence: DaemonFence,
        permit_sha256: str,
    ) -> None:
        self._set_hardware_command_release_failure(
            command_id, daemon_fence, permit_sha256, "aborted"
        )

    def mark_hardware_command_release_ambiguous(
        self,
        command_id: str,
        daemon_fence: DaemonFence,
        permit_sha256: str,
    ) -> None:
        self._set_hardware_command_release_failure(
            command_id, daemon_fence, permit_sha256, "ambiguous"
        )

    def reconcile_ambiguous_hardware_command_unreleased(
        self,
        command_id: str,
        daemon_fence: DaemonFence,
        *,
        scope_command_id: str,
        scope_owner_generation: int,
        observed_pid: int,
        permit_sha256: str,
    ) -> None:
        self._validate_sha256(permit_sha256, "command release permit")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            command = self._command_with_release_tx(db, command_id)
            if command is None:
                raise CatalogError("hardware command not found")
            if (
                command["id"] != scope_command_id
                or command["issued_generation"] != scope_owner_generation
                or command["pid"] != observed_pid
                or command["release_permit_sha256"] != permit_sha256
                or command["state"] != "launch_blocked"
                or command["release_status"] != "ambiguous"
            ):
                raise CatalogError(
                    "negative command release evidence does not match authorization"
                )
            db.execute(
                """
                UPDATE hardware_command_release_authorizations
                SET release_status='aborted' WHERE command_id=?
                """,
                (command_id,),
            )

    def _set_hardware_command_release_failure(
        self,
        command_id: str,
        daemon_fence: DaemonFence,
        permit_sha256: str,
        status: Literal["aborted", "ambiguous"],
    ) -> None:
        self._validate_sha256(permit_sha256, "command release permit")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            command = self._command_with_release_tx(db, command_id)
            if command is None:
                raise CatalogError("hardware command not found")
            if (
                command["release_permit_sha256"] != permit_sha256
                or command["state"] != "launch_blocked"
                or command["release_status"] not in {"authorized", status}
            ):
                raise CatalogError(
                    "command release failure does not match authorization"
                )
            db.execute(
                """
                UPDATE hardware_command_release_authorizations
                SET release_status=? WHERE command_id=?
                """,
                (status, command_id),
            )
            if status == "ambiguous":
                db.execute(
                    """
                    UPDATE daemon_operations
                    SET state='recovery_required', finished_at=NULL,
                        error_class='operator_required',
                        error_code='recovery_required', error_message=?
                    WHERE id=? AND state='running'
                    """,
                    (
                        _SAFE_ERROR_MESSAGES["recovery_required"],
                        command["operation_id"],
                    ),
                )

    def acknowledge_command_quiescence(
        self,
        command_id: str,
        daemon_fence: DaemonFence,
        evidence: CommandExitEvidence,
    ) -> None:
        if evidence.command_id != command_id:
            raise ValidationError("command exit evidence id does not match")
        if evidence.outcome not in {"completed", "terminated", "launch_aborted"}:
            raise ValidationError("invalid command exit outcome")
        if (
            evidence.terminal_exit_code is not None
            and type(evidence.terminal_exit_code) is not int
        ):
            raise ValidationError("invalid command terminal exit code")
        if evidence.outcome != "completed" and evidence.terminal_exit_code is not None:
            raise ValidationError("only completed commands may carry an exit code")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            command = self._command_with_release_tx(db, command_id)
            if command is None:
                raise CatalogError("hardware command not found")
            if command["state"] == "quiesced":
                if (
                    command["exit_outcome"] != evidence.outcome
                    or command["terminal_exit_code"] != evidence.terminal_exit_code
                ):
                    raise CatalogError("command already has different exit evidence")
                return
            recorded_process = self._process_from_command_row(command)
            if (
                evidence.outcome == "launch_aborted"
                and command["state"] == "launch_reserved"
            ):
                if evidence.process is not None:
                    raise ValidationError(
                        "unlaunched command cannot carry a process identity"
                    )
            else:
                allowed = (
                    command["state"] in {"released", "exit_observed"}
                    and evidence.outcome in {"completed", "terminated"}
                ) or (
                    command["state"] == "launch_blocked"
                    and (
                        (
                            evidence.outcome == "launch_aborted"
                            and command["release_status"]
                            in {None, "authorized", "aborted"}
                        )
                        or (
                            evidence.outcome == "terminated"
                            and command["release_status"] == "ambiguous"
                        )
                    )
                )
                if not allowed:
                    raise CommandQuiescenceRequired(
                        "command has not reached a compatible supervised state"
                    )
                if recorded_process != evidence.process:
                    raise CommandQuiescenceRequired(
                        "command process identity does not match"
                    )
            if (
                evidence.outcome == "launch_aborted"
                and command["release_status"] == "authorized"
            ):
                db.execute(
                    """
                    UPDATE hardware_command_release_authorizations
                    SET release_status='aborted' WHERE command_id=?
                    """,
                    (command_id,),
                )
            recorded_process_values = (
                (None, None, None, None)
                if recorded_process is None
                else (
                    recorded_process.boot_id,
                    recorded_process.pid,
                    recorded_process.start_ticks,
                    recorded_process.process_group_id,
                )
            )
            evidence_process_values = (
                (None, None, None, None)
                if evidence.process is None
                else (
                    evidence.process.boot_id,
                    evidence.process.pid,
                    evidence.process.start_ticks,
                    evidence.process.process_group_id,
                )
            )
            lifecycle_state = command["state"]
            if lifecycle_state == "exit_observed":
                lifecycle_state = "released"
            if not hardware_command_exit_transition_valid(
                prior_state=lifecycle_state,
                outcome=evidence.outcome,
                created_at=command["created_at"],
                released_at=command["released_at"],
                exit_at=evidence.quiesced_at,
                recorded_process=recorded_process_values,
                evidence_process=evidence_process_values,
            ):
                raise ValidationError("command exit evidence violates lifecycle")
            db.execute(
                """
                UPDATE hardware_command_executions
                SET state='quiesced', exit_outcome=?, exit_observed_at=?, quiesced_at=?,
                    terminal_exit_code=?
                WHERE id=?
                """,
                (
                    evidence.outcome,
                    evidence.quiesced_at,
                    evidence.quiesced_at,
                    evidence.terminal_exit_code,
                    command_id,
                ),
            )

    def create_command_quiescence_receipt(
        self, operation_id: str, daemon_fence: DaemonFence
    ) -> CommandQuiescenceReceipt:
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            if operation is None or operation["state"] != "recovery_required":
                raise CommandQuiescenceRequired(
                    "operation is not awaiting safe command reconciliation"
                )
            commands = db.execute(
                """
                SELECT * FROM hardware_command_executions
                WHERE operation_id=? ORDER BY created_at, id
                """,
                (operation_id,),
            ).fetchall()
            if any(row["state"] != "quiesced" for row in commands):
                raise CommandQuiescenceRequired(
                    "not every command has verified exit evidence"
                )
            receipt_id = self._new_id("command-receipt")
            lineage = db.execute(
                "SELECT recorded_at FROM operation_recovery_lineages "
                "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
                (operation_id,),
            ).fetchone()
            causal_values = [operation["started_at"]]
            if lineage is not None:
                causal_values.append(lineage["recorded_at"])
            causal_values.extend(
                row[field]
                for row in commands
                for field in ("created_at", "exit_observed_at", "quiesced_at")
                if row[field] is not None
            )
            recorded_at = self._precise_utc_now(after=max(causal_values))
            db.execute(
                """
                INSERT INTO command_quiescence_receipts(
                    id, operation_id, reconciled_by_generation, recorded_at
                ) VALUES(?, ?, ?, ?)
                """,
                (receipt_id, operation_id, daemon_fence.generation, recorded_at),
            )
            db.executemany(
                """
                INSERT INTO command_quiescence_receipt_items(
                    receipt_id, command_id, exit_outcome
                ) VALUES(?, ?, ?)
                """,
                ((receipt_id, row["id"], row["exit_outcome"]) for row in commands),
            )
            return self._command_receipt_from_rows(
                receipt_id,
                operation_id,
                daemon_fence.generation,
                recorded_at,
                commands,
            )

    def create_physical_reconciliation_receipt(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        command_receipt_id: str,
        evidence: VerifiedPhysicalQuiescence,
    ) -> PhysicalReconciliationReceipt:
        mismatch: str | None = None
        result: PhysicalReconciliationReceipt | None = None
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            if operation is None or operation["state"] != "recovery_required":
                raise CatalogError("operation is not awaiting physical reconciliation")
            command_receipt = db.execute(
                "SELECT * FROM command_quiescence_receipts WHERE id=?",
                (command_receipt_id,),
            ).fetchone()
            if (
                command_receipt is None
                or command_receipt["operation_id"] != operation_id
                or command_receipt["reconciled_by_generation"]
                != daemon_fence.generation
            ):
                raise CommandQuiescenceRequired(
                    "command receipt is not current and exact"
                )
            if evidence.mounted or evidence.media_loaded or evidence.drive_busy:
                raise CommandQuiescenceRequired("physical target is not quiescent")
            if evidence.related_processes:
                raise CommandQuiescenceRequired("related hardware processes remain")
            target_row = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            binding_row = db.execute(
                """
                SELECT observed_media_identity_sha256
                FROM operation_media_identity_bindings WHERE operation_id=?
                """,
                (operation_id,),
            ).fetchone()
            mismatch = self._physical_mismatch_dimension(
                target_row, binding_row, evidence
            )
            if mismatch is not None:
                self._record_audit_tx(
                    db,
                    "system",
                    "recovery.physical_target_mismatch",
                    "denied",
                    self._new_id("request"),
                    None,
                    json.dumps({"dimension": mismatch}, separators=(",", ":")),
                )
            else:
                receipt_id = self._new_id("physical-receipt")
                recorded_at = self._precise_utc_now(
                    after=command_receipt["recorded_at"]
                )
                target_values = self._target_values(evidence.target)
                db.execute(
                    """
                    INSERT INTO physical_reconciliation_receipts(
                        id, operation_id, reconciled_by_generation,
                        command_receipt_id, mount_path_sha256,
                        tape_device_identity_sha256, scsi_device_identity_sha256,
                        expected_media_scope_sha256, observed_media_identity_sha256,
                        mounted, media_loaded, drive_busy, related_process_count,
                        recorded_at
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, 0, ?)
                    """,
                    (
                        receipt_id,
                        operation_id,
                        daemon_fence.generation,
                        command_receipt_id,
                        *target_values,
                        evidence.observed_media_identity_sha256,
                        recorded_at,
                    ),
                )
                result = PhysicalReconciliationReceipt(
                    id=receipt_id,
                    operation_id=operation_id,
                    reconciled_by_generation=daemon_fence.generation,
                    command_receipt_id=command_receipt_id,
                    target=evidence.target,
                    observed_media_identity_sha256=evidence.observed_media_identity_sha256,
                    mounted=False,
                    media_loaded=False,
                    drive_busy=False,
                    related_processes=(),
                    recorded_at=recorded_at,
                )
        if mismatch is not None:
            raise PhysicalTargetMismatch(mismatch)
        assert result is not None
        return result

    def pre_media_reset_proof(
        self, operation_id: str, daemon_fence: DaemonFence,
    ) -> dict[str, Any]:
        """Read the exact reset candidate without probing or changing hardware."""
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = self.get_operation(operation_id)
            if operation is None:
                raise CatalogError("pre-media operation not found")
            job = db.execute("SELECT * FROM automatic_jobs WHERE id=?", (operation["job_id"],)).fetchone()
            cassette = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (operation["job_id"], operation["cassette_sequence"]),
            ).fetchone()
            target = self.hardware_target_binding(operation_id)
            if (
                operation["kind"] != "archive.native" or operation["state"] != "recovery_required"
                or operation["phase"] is not None or operation["owner_generation"] > daemon_fence.generation
                or job is None or job["status"] != "waiting_media"
                or job["current_sequence"] != operation["cassette_sequence"]
                or cassette is None or cassette["status"] != "waiting_media" or target is None
                or self._job_management_state_tx(db, operation["job_id"])["retired_at"] is not None
            ):
                raise CatalogError("operation is not a stopped current pre-media attempt")
            for table in (
                "operation_media_identity_bindings", "imported_cassette_commit_receipts",
                "imported_runtime_cassette_commit_receipts", "ltfs_terminal_receipts",
                "ltfs_unmount_boundaries", "recovery_resolutions", "recovery_attempt_events",
            ):
                if db.execute(f"SELECT 1 FROM {table} WHERE operation_id=? LIMIT 1", (operation_id,)).fetchone():
                    raise CatalogError("pre-media attempt has later recovery or media evidence")
            if db.execute(
                "SELECT 1 FROM daemon_operations WHERE id<>? AND state IN ('running','recovery_required') LIMIT 1",
                (operation_id,),
            ).fetchone():
                raise CatalogError("another hardware operation is active")
            commands = self.hardware_commands_for_operation(operation_id)
            if not commands:
                raise CatalogError("pre-media command evidence is unavailable")
            lineage = db.execute(
                "SELECT * FROM operation_recovery_lineages WHERE operation_id=? "
                "ORDER BY recovery_generation DESC LIMIT 1", (operation_id,),
            ).fetchone()
            if operation["owner_generation"] < daemon_fence.generation:
                if (lineage is None or lineage["recovery_generation"] != daemon_fence.generation
                    or lineage["daemon_owner_id"] != daemon_fence.owner_id):
                    raise CatalogError("pre-media restart lineage is not current")
                original_generation = self._ltfs_recovery_session_generation_tx(
                    db, RecoveryCommandFence(operation_id, daemon_fence.generation),
                )
                if (original_generation != operation["owner_generation"]
                    or tuple(json.loads(lineage["command_ids_json"])) != tuple(command.id for command in commands)):
                    raise CatalogError("pre-media restart lineage is not exact")
            elif lineage is not None:
                raise CatalogError("pre-media attempt has unexpected restart lineage")
            for command in commands:
                if (command.issued_generation != operation["owner_generation"] or command.target != target
                    or command.kind not in {"identify", "probe_media"}
                    or command.observed_media_identity_sha256 is not None):
                    raise CatalogError("pre-media command scope is not exact")
                if command.state == "quiesced" and command.exit_outcome == "completed":
                    if command.quiesced_at is None or command.exit_observed_at is None:
                        raise CatalogError("historical identification is not proven quiescent")
                    continue
                if command.release_status == "ambiguous":
                    if (command.process is None or command.release_permit_sha256 is None
                        or command.release_authorized_at is None or command.released_at is not None
                        or command.release_confirmed_at is not None or command.terminal_exit_code is not None
                        or command.state not in {"release_authorized", "quiesced"}
                        or (command.state == "release_authorized" and any(value is not None for value in (
                            command.exit_outcome, command.exit_observed_at, command.quiesced_at)))
                        or (command.state == "quiesced" and (command.exit_outcome != "terminated"
                            or command.quiesced_at is None or command.exit_observed_at is None))):
                        raise CatalogError("ambiguous identification release evidence is incomplete")
                    continue
                if (command.state not in {"launch_reserved", "quiesced"}
                    # An already-aborted blocked launch retains its historical
                    # process identity. Runtime still proves that PID/group
                    # absent; only an unlaunched reservation must have none.
                    or (command.state == "launch_reserved" and command.process is not None)
                    or command.released_at is not None
                    or command.release_permit_sha256 is not None or command.release_status is not None
                    or command.release_authorized_at is not None or command.release_confirmed_at is not None
                    or (command.state == "launch_reserved" and any(value is not None for value in (
                        command.exit_outcome, command.exit_observed_at, command.quiesced_at, command.terminal_exit_code)))
                    or (command.state == "quiesced" and (command.exit_outcome != "launch_aborted"
                        or command.quiesced_at is None or command.exit_observed_at is None))):
                    raise CatalogError("pending identification may have been released")
            ledger = json.dumps([asdict(command) for command in commands], sort_keys=True, separators=(",", ":"))
            return {
                "operation_id": operation_id, "job_id": operation["job_id"],
                "cassette_sequence": operation["cassette_sequence"], "daemon_generation": daemon_fence.generation,
                "command_ledger_sha256": hashlib.sha256(ledger.encode("utf-8")).hexdigest(),
                "target": asdict(target),
            }

    def pre_media_reset_replay(
        self, request: dict[str, Any], daemon_fence: DaemonFence, *, principal: str,
        session_binding_sha256: str, idempotency_key: str,
    ) -> OperationRecord | None:
        self._assert_daemon_fence_tx(self.connection, daemon_fence)
        rows = self.connection.execute(
            "SELECT * FROM audit_entries WHERE action='operation.pre_media_reset' AND request_id=?",
            (idempotency_key,),
        ).fetchall()
        if not rows:
            return None
        if len(rows) != 1:
            raise CatalogError("pre-media reset receipt is ambiguous")
        receipt = json.loads(rows[0]["payload_json"])
        if (rows[0]["principal"] != principal or receipt.get("request") != request
            or receipt.get("session_binding_sha256") != session_binding_sha256):
            raise CatalogError("pre-media reset key is bound to another request")
        return OperationRecord(**receipt["operation"])

    def finalize_pre_media_reset(
        self, request: dict[str, Any], daemon_fence: DaemonFence,
        original_commands: tuple[HardwareCommandExecution, ...], command_receipt_id: str,
        *, principal: str, session_binding_sha256: str, idempotency_key: str,
    ) -> OperationRecord:
        """Atomically pause this job and fail its never-started media attempt."""
        with self.transaction() as db:
            replay = self.pre_media_reset_replay(
                request, daemon_fence, principal=principal,
                session_binding_sha256=session_binding_sha256, idempotency_key=idempotency_key,
            )
            if replay is not None:
                return replay
            current = self.pre_media_reset_proof(request["operation_id"], daemon_fence)
            if any(current[name] != request[name] for name in current if name != "command_ledger_sha256"):
                raise CatalogError("pre-media reset coordinates changed")
            original_ledger = json.dumps([asdict(command) for command in original_commands], sort_keys=True, separators=(",", ":"))
            if hashlib.sha256(original_ledger.encode("utf-8")).hexdigest() != request["command_ledger_sha256"]:
                raise CatalogError("pre-media reset ledger is not the approved ledger")
            commands = self.hardware_commands_for_operation(request["operation_id"])
            if len(commands) != len(original_commands):
                raise CatalogError("pre-media command ledger changed")
            for before, after in zip(original_commands, commands, strict=True):
                expected = before if before.state == "quiesced" else replace(
                    before, state="quiesced",
                    exit_outcome="terminated" if before.release_status == "ambiguous" else "launch_aborted",
                    exit_observed_at=after.exit_observed_at, quiesced_at=after.quiesced_at,
                )
                if after != expected or after.state != "quiesced":
                    raise CatalogError("pre-media reconciliation changed command authority")
            receipt = db.execute("SELECT * FROM command_quiescence_receipts WHERE id=?", (command_receipt_id,)).fetchone()
            items = db.execute(
                "SELECT command_id,exit_outcome FROM command_quiescence_receipt_items WHERE receipt_id=? ORDER BY command_id",
                (command_receipt_id,),
            ).fetchall()
            if (receipt is None or receipt["operation_id"] != request["operation_id"]
                or receipt["reconciled_by_generation"] != daemon_fence.generation
                or [(item["command_id"], item["exit_outcome"]) for item in items]
                != sorted((command.id, command.exit_outcome) for command in commands)
                or any(command.quiesced_at is None or command.quiesced_at >= receipt["recorded_at"] for command in commands)):
                raise CatalogError("pre-media command receipt is not current and exact")
            now = self._precise_utc_now(after=receipt["recorded_at"])
            db.execute(
                "UPDATE daemon_operations SET state='failed',finished_at=?,error_class='terminal_safety_failure',"
                "error_code='operation_failed',error_message=? WHERE id=?",
                (now, "Pre-media attempt reset by administrator; job paused.", request["operation_id"]),
            )
            db.execute("UPDATE automatic_jobs SET status='paused' WHERE id=?", (request["job_id"],))
            db.execute(
                "UPDATE job_management_state SET pause_requested_at=?,pause_acknowledged_at=?,updated_at=? WHERE job_id=?",
                (now, now, now, request["job_id"]),
            )
            db.execute(
                "UPDATE automatic_sequence_state SET state='disabled',revision=revision+1,updated_at=? WHERE job_id=?",
                (now, request["job_id"]),
            )
            operation = self._operation_from_row(self.get_operation(request["operation_id"]))
            self._record_audit_tx(
                db, principal, "operation.pre_media_reset", "accepted", idempotency_key, None,
                json.dumps({"request": request, "operation": asdict(operation),
                    "session_binding_sha256": session_binding_sha256, "command_receipt_id": command_receipt_id},
                    sort_keys=True, separators=(",", ":")),
            )
            self._job_history_tx(db, request["job_id"], principal, "job.pre_media_reset", "paused",
                {"operation_id": request["operation_id"], "command_receipt_id": command_receipt_id}, occurred_at=now)
            return operation

    def resolve_recovery(
        self,
        operation_id: str,
        daemon_fence: DaemonFence,
        resolution: SafeRecoveryResolution,
        *,
        _db: sqlite3.Connection | None = None,
    ) -> OperationRecord:
        self._validate_safe_identifier(resolution.reason_code, "recovery reason")
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            if operation is None or operation["state"] != "recovery_required":
                raise CatalogError("operation does not require recovery")
            command_receipt = db.execute(
                "SELECT * FROM command_quiescence_receipts WHERE id=?",
                (resolution.command_receipt_id,),
            ).fetchone()
            if (
                command_receipt is None
                or command_receipt["operation_id"] != operation_id
                or command_receipt["reconciled_by_generation"]
                != daemon_fence.generation
            ):
                raise CommandQuiescenceRequired("command receipt is missing or stale")
            commands = db.execute(
                """
                SELECT * FROM hardware_command_executions
                WHERE operation_id=? ORDER BY id
                """,
                (operation_id,),
            ).fetchall()
            items = db.execute(
                """
                SELECT command_id, exit_outcome
                FROM command_quiescence_receipt_items
                WHERE receipt_id=? ORDER BY command_id
                """,
                (resolution.command_receipt_id,),
            ).fetchall()
            command_ids = [(row["id"], row["exit_outcome"]) for row in commands]
            item_ids = [(row["command_id"], row["exit_outcome"]) for row in items]
            if command_ids != item_ids or any(
                row["state"] != "quiesced" for row in commands
            ):
                raise CommandQuiescenceRequired(
                    "command receipt does not cover the exact command ledger"
                )
            physical = db.execute(
                "SELECT * FROM physical_reconciliation_receipts WHERE id=?",
                (resolution.physical_receipt_id,),
            ).fetchone()
            if (
                physical is None
                or physical["operation_id"] != operation_id
                or physical["command_receipt_id"] != resolution.command_receipt_id
                or physical["reconciled_by_generation"] != daemon_fence.generation
                or physical["recorded_at"] <= command_receipt["recorded_at"]
            ):
                raise CommandQuiescenceRequired(
                    "physical receipt is missing, stale, or unordered"
                )
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            binding = db.execute(
                """
                SELECT * FROM operation_media_identity_bindings WHERE operation_id=?
                """,
                (operation_id,),
            ).fetchone()
            self._validate_recovery_targets(target, binding, commands, physical)
            resolved_at = self._precise_utc_now(after=physical["recorded_at"])
            db.execute(
                """
                INSERT INTO recovery_resolutions(
                    operation_id, resolved_by_generation, reason_code,
                    command_receipt_id, physical_receipt_id, resolved_at
                ) VALUES(?, ?, ?, ?, ?, ?)
                """,
                (
                    operation_id,
                    daemon_fence.generation,
                    resolution.reason_code,
                    resolution.command_receipt_id,
                    resolution.physical_receipt_id,
                    resolved_at,
                ),
            )
            commit = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if commit is not None:
                lineage = db.execute(
                    "SELECT * FROM imported_recovery_lineage_receipts "
                    "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
                    (operation_id,),
                ).fetchone()
                lineage_id = None
                if daemon_fence.generation != commit["owner_generation"]:
                    if (
                        lineage is None
                        or lineage["recovery_generation"] != daemon_fence.generation
                    ):
                        raise CommandQuiescenceRequired(
                            "recovery resolution has no exact restart lineage"
                        )
                    lineage_id = lineage["id"]
                resolution_evidence = imported_recovery_resolution_sha256(
                    (
                        operation_id,
                        lineage_id,
                        commit["commit_binding_sha256"],
                        daemon_fence.generation,
                        resolution.reason_code,
                        tuple(command_receipt),
                        tuple(
                            (row["command_id"], row["exit_outcome"]) for row in items
                        ),
                        tuple(physical),
                        resolved_at,
                    )
                )
                db.execute(
                    "INSERT INTO imported_recovery_resolution_receipts("
                    "operation_id, recovery_lineage_id, commit_binding_sha256, "
                    "resolved_generation, command_receipt_id, physical_receipt_id, "
                    "resolved_at, resolution_evidence_sha256) "
                    "VALUES(?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        operation_id,
                        lineage_id,
                        commit["commit_binding_sha256"],
                        daemon_fence.generation,
                        resolution.command_receipt_id,
                        resolution.physical_receipt_id,
                        resolved_at,
                        resolution_evidence,
                    ),
                )
            db.execute(
                """
                UPDATE daemon_operations
                SET state='cancelled', finished_at=?, error_class=NULL,
                    error_code=NULL, error_message=NULL WHERE id=?
                """,
                (resolved_at, operation_id),
            )
            row = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            return self._operation_from_row(row)

    def ensure_recovery_blocker(
        self,
        daemon_fence: DaemonFence,
        evidence_code: str,
        hardware_target: HardwareTargetBinding,
        observed_media_identity_sha256: str | None,
    ) -> OperationRecord:
        self._validate_safe_identifier(evidence_code, "recovery evidence code")
        if observed_media_identity_sha256 is not None:
            self._validate_sha256(
                observed_media_identity_sha256, "observed media digest"
            )
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            active = db.execute(
                """
                SELECT * FROM daemon_operations
                WHERE state IN ('running','recovery_required') LIMIT 1
                """
            ).fetchone()
            if active is not None:
                return self._operation_from_row(active)
            operation_id = self._new_id("startup-recovery")
            now = self._precise_utc_now()
            db.execute(
                """
                INSERT INTO daemon_operations(
                    id, kind, state, phase, idempotency_key, principal,
                    owner_generation, started_at, error_class, error_code,
                    error_message
                ) VALUES(?, 'system.recovery', 'recovery_required', NULL, ?,
                    'system', ?, ?, 'operator_required', 'recovery_required', ?)
                """,
                (
                    operation_id,
                    f"startup-{evidence_code}-{operation_id}",
                    daemon_fence.generation,
                    now,
                    _SAFE_ERROR_MESSAGES["recovery_required"],
                ),
            )
            self._insert_hardware_target(db, operation_id, hardware_target, now)
            if observed_media_identity_sha256 is not None:
                command_id = self._new_id("startup-evidence")
                db.execute(
                    """
                    INSERT INTO hardware_command_executions(
                        id, operation_id, issued_generation, command_kind,
                        argv_sha256, mount_path_sha256,
                        tape_device_identity_sha256, scsi_device_identity_sha256,
                        expected_media_scope_sha256,
                        observed_media_identity_sha256, state, exit_outcome,
                        created_at, exit_observed_at, quiesced_at
                    ) VALUES(?, ?, ?, 'startup-evidence', ?, ?, ?, ?, ?, ?,
                        'quiesced', 'launch_aborted', ?, ?, ?)
                    """,
                    (
                        command_id,
                        operation_id,
                        daemon_fence.generation,
                        hashlib.sha256(b"startup-evidence").hexdigest(),
                        *self._target_values(hardware_target),
                        observed_media_identity_sha256,
                        now,
                        now,
                        now,
                    ),
                )
                db.execute(
                    """
                    INSERT INTO operation_media_identity_bindings(
                        operation_id, observed_media_identity_sha256,
                        bound_by_command_id, bound_at
                    ) VALUES(?, ?, ?, ?)
                    """,
                    (operation_id, observed_media_identity_sha256, command_id, now),
                )
            row = db.execute(
                "SELECT * FROM daemon_operations WHERE id=?", (operation_id,)
            ).fetchone()
            return self._operation_from_row(row)

    def command(self, command_id: str) -> HardwareCommandExecution | None:
        row = self._command_with_release_tx(self.connection, command_id)
        return None if row is None else self._hardware_command_from_row(row)

    def hardware_commands_for_operation(
        self, operation_id: str
    ) -> tuple[HardwareCommandExecution, ...]:
        rows = self.connection.execute(
            """
            SELECT command.*,
                   authorization.permit_sha256 AS release_permit_sha256,
                   authorization.release_status AS release_status,
                   authorization.authorized_at AS release_authorized_at,
                   authorization.confirmed_at AS release_confirmed_at
            FROM hardware_command_executions command
            LEFT JOIN hardware_command_release_authorizations authorization
              ON authorization.command_id=command.id
            WHERE command.operation_id=? ORDER BY command.created_at, command.id
            """,
            (operation_id,),
        ).fetchall()
        return tuple(self._hardware_command_from_row(row) for row in rows)

    def observed_media_binding(self, operation_id: str) -> str | None:
        row = self.connection.execute(
            """
            SELECT observed_media_identity_sha256
            FROM operation_media_identity_bindings WHERE operation_id=?
            """,
            (operation_id,),
        ).fetchone()
        return None if row is None else str(row[0])

    def hardware_target_binding(
        self, operation_id: str
    ) -> HardwareTargetBinding | None:
        row = self.connection.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        return None if row is None else self._target_from_row(row)

    def recovery_commit_evidence(self, operation_id: str):
        """Return exact immutable post-commit evidence, or no evidence."""

        self._validate_safe_identifier(operation_id, "recovery operation id")
        legacy = self.connection.execute(
            "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        runtime = self.connection.execute(
            "SELECT * FROM imported_runtime_cassette_commit_receipts "
            "WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        if legacy is not None and runtime is not None:
            raise CatalogError("recovery commit evidence families conflict")
        commit = legacy if legacy is not None else runtime
        if commit is None:
            return None
        target = self.connection.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        media = self.connection.execute(
            "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        try:
            command_ids = tuple(json.loads(commit["command_ids_json"]))
        except (TypeError, ValueError):
            raise CatalogError("recovery commit command evidence is malformed") from None
        commands = self._commands_with_release_by_ids_tx(
            self.connection, command_ids
        )
        unmounts = tuple(row for row in commands if row["command_kind"] == "unmount")
        if (
            target is None
            or media is None
            or len(unmounts) != 1
            or tuple(row["id"] for row in commands) != command_ids
            or commit["observed_media_identity_sha256"]
            != media["observed_media_identity_sha256"]
            or any(
                commit[field] != target[field]
                for field in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
        ):
            raise CatalogError("recovery commit evidence is not exact")
        from .daemon.recovery import CommitEvidence

        manifest = str(commit["manifest_sha256"])
        return CommitEvidence(
            operation_id=operation_id,
            attempt_generation=int(commit["owner_generation"]),
            target=self._target_from_row(target),
            observed_media_identity_sha256=str(
                commit["observed_media_identity_sha256"]
            ),
            unmount_command_id=str(unmounts[0]["id"]),
            manifest_sha256=manifest,
            provisional_manifest_sha256=manifest,
            recorded_at=str(commit["committed_at"]),
        )

    def begin_recovery_attempt(
        self,
        operation_id: str,
        attempt_number: int,
        daemon_fence: DaemonFence,
        *,
        trigger: str,
        evidence_sha256: str,
        decision: str,
        recorded_at: str,
    ) -> RecoveryAttemptSummary:
        """Append or exactly replay the sequence-one event for an attempt."""

        claim = self.claim_recovery_attempt(
            operation_id,
            attempt_number,
            daemon_fence,
            trigger=trigger,
            evidence_sha256=evidence_sha256,
            decision=decision,
            recorded_at=recorded_at,
        )
        if claim.attempt.started_at != recorded_at:
            raise CatalogError("conflicting recovery attempt begin replay")
        return claim.attempt

    @staticmethod
    def _operation_cassette_label_tx(
        db: sqlite3.Connection, operation: sqlite3.Row
    ) -> str | None:
        cassette_sequence = operation["cassette_sequence"]
        if cassette_sequence is None:
            return None
        job_id = operation["job_id"]
        if job_id is None:
            raise CatalogError("recovery attempt cassette has no job identity")
        if operation["kind"] == "restore.cassette":
            cassette = db.execute(
                "SELECT physical_label FROM restore_run_cassettes "
                "WHERE run_id=? AND sequence=?",
                (job_id, cassette_sequence),
            ).fetchone()
        else:
            cassette = db.execute(
                "SELECT physical_label FROM automatic_cassettes "
                "WHERE job_id=? AND sequence=?",
                (job_id, cassette_sequence),
            ).fetchone()
        if cassette is None:
            raise CatalogError("recovery attempt cassette identity is missing")
        return str(cassette["physical_label"])

    def operation_cassette_label(self, operation_id: str) -> str | None:
        operation = self.connection.execute(
            "SELECT kind,job_id,cassette_sequence FROM daemon_operations WHERE id=?",
            (operation_id,),
        ).fetchone()
        if operation is None:
            raise CatalogError("recovery attempt operation does not exist")
        return self._operation_cassette_label_tx(self.connection, operation)

    def claim_recovery_attempt(
        self,
        operation_id: str,
        attempt_number: int,
        daemon_fence: DaemonFence,
        *,
        trigger: str,
        evidence_sha256: str,
        decision: str,
        recorded_at: str,
    ) -> RecoveryAttemptClaim:
        """Atomically append a start event and identify its sole effect owner."""

        self._validate_recovery_attempt_identity(
            operation_id,
            attempt_number,
            trigger=trigger,
            evidence_sha256=evidence_sha256,
            decision=decision,
            recorded_at=recorded_at,
        )
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            operation = db.execute(
                "SELECT kind,job_id,cassette_sequence FROM daemon_operations WHERE id=?",
                (operation_id,),
            ).fetchone()
            if operation is None:
                raise CatalogError("recovery attempt operation does not exist")
            job_id = operation["job_id"]
            cassette_sequence = operation["cassette_sequence"]
            cassette_label = self._operation_cassette_label_tx(db, operation)
            payload = (
                operation_id,
                attempt_number,
                1,
                job_id,
                cassette_sequence,
                cassette_label,
                trigger,
                evidence_sha256,
                decision,
                "started",
                daemon_fence.generation,
                recorded_at,
                None,
            )
            existing = db.execute(
                "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                "AND attempt_number=? AND event_sequence=1",
                (operation_id, attempt_number),
            ).fetchone()
            owned = existing is None
            if existing is not None:
                existing_values = self._recovery_attempt_event_values(existing)
                if (
                    existing_values[:11] != payload[:11]
                    or existing_values[12:] != payload[12:]
                ):
                    raise CatalogError("conflicting recovery attempt begin replay")
            else:
                db.execute(
                    "INSERT INTO recovery_attempt_events("
                    "operation_id,attempt_number,event_sequence,job_id,"
                    "cassette_sequence,cassette_label,trigger,evidence_sha256,"
                    "decision,state,daemon_generation,recorded_at,next_eligible_at"
                    ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    payload,
                )
            return RecoveryAttemptClaim(
                self._recovery_attempt_summary_tx(
                    db, operation_id, attempt_number
                ),
                owned,
            )

    def finish_recovery_attempt(
        self,
        operation_id: str,
        attempt_number: int,
        daemon_fence: DaemonFence,
        *,
        state: str,
        evidence_sha256: str,
        decision: str,
        recorded_at: str,
        next_eligible_at: str | None = None,
    ) -> RecoveryAttemptSummary:
        """Append or exactly replay the one sequence-two attempt outcome."""

        self._validate_recovery_attempt_identity(
            operation_id,
            attempt_number,
            trigger=None,
            evidence_sha256=evidence_sha256,
            decision=decision,
            recorded_at=recorded_at,
        )
        if state not in _RECOVERY_ATTEMPT_OUTCOMES:
            raise ValidationError("invalid recovery attempt outcome")
        outcome_time = self._parse_utc_timestamp(recorded_at)
        next_time = (
            None
            if next_eligible_at is None
            else self._parse_utc_timestamp(next_eligible_at)
        )
        if next_eligible_at is not None and (
            not isinstance(next_eligible_at, str) or len(next_eligible_at) > 64
        ):
            raise ValidationError("invalid recovery retry eligibility timestamp")
        if state == "retry_scheduled":
            if next_time is None or outcome_time is None or next_time < outcome_time:
                raise ValidationError("invalid recovery retry eligibility timestamp")
        elif next_eligible_at is not None:
            raise ValidationError("only a scheduled retry has a next eligible time")
        with self.transaction() as db:
            self._assert_daemon_fence_tx(db, daemon_fence)
            started = db.execute(
                "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                "AND attempt_number=? AND event_sequence=1",
                (operation_id, attempt_number),
            ).fetchone()
            if started is None:
                raise CatalogError("recovery attempt has not begun")
            started_time = self._parse_utc_timestamp(started["recorded_at"])
            if (
                started_time is None
                or outcome_time is None
                or outcome_time <= started_time
            ):
                raise ValidationError("recovery attempt timestamps are not monotonic")
            payload = (
                operation_id,
                attempt_number,
                2,
                started["job_id"],
                started["cassette_sequence"],
                started["cassette_label"],
                started["trigger"],
                evidence_sha256,
                decision,
                state,
                daemon_fence.generation,
                recorded_at,
                next_eligible_at,
            )
            existing = db.execute(
                "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
                "AND attempt_number=? AND event_sequence=2",
                (operation_id, attempt_number),
            ).fetchone()
            if existing is not None:
                if self._recovery_attempt_event_values(existing) != payload:
                    raise CatalogError("conflicting recovery attempt outcome replay")
            else:
                db.execute(
                    "INSERT INTO recovery_attempt_events("
                    "operation_id,attempt_number,event_sequence,job_id,"
                    "cassette_sequence,cassette_label,trigger,evidence_sha256,"
                    "decision,state,daemon_generation,recorded_at,next_eligible_at"
                    ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    payload,
                )
            return self._recovery_attempt_summary_tx(
                db, operation_id, attempt_number
            )

    def list_recovery_attempts(
        self, operation_id: str | None = None
    ) -> tuple[RecoveryAttemptSummary, ...]:
        """Fold immutable attempt events into ordered typed summaries."""

        if operation_id is not None:
            self._validate_safe_identifier(operation_id, "recovery operation id")
            keys = self.connection.execute(
                "SELECT DISTINCT operation_id,attempt_number "
                "FROM recovery_attempt_events WHERE operation_id=? "
                "ORDER BY attempt_number",
                (operation_id,),
            ).fetchall()
        else:
            keys = self.connection.execute(
                "SELECT DISTINCT operation_id,attempt_number "
                "FROM recovery_attempt_events "
                "ORDER BY operation_id,attempt_number"
            ).fetchall()
        return tuple(
            self._recovery_attempt_summary_tx(
                self.connection, row["operation_id"], row["attempt_number"]
            )
            for row in keys
        )

    @staticmethod
    def _recovery_attempt_event_values(row: sqlite3.Row) -> tuple[Any, ...]:
        return tuple(
            row[name]
            for name in (
                "operation_id",
                "attempt_number",
                "event_sequence",
                "job_id",
                "cassette_sequence",
                "cassette_label",
                "trigger",
                "evidence_sha256",
                "decision",
                "state",
                "daemon_generation",
                "recorded_at",
                "next_eligible_at",
            )
        )

    @staticmethod
    def _recovery_attempt_summary_tx(
        db: sqlite3.Connection,
        operation_id: str,
        attempt_number: int,
    ) -> RecoveryAttemptSummary:
        rows = db.execute(
            "SELECT * FROM recovery_attempt_events WHERE operation_id=? "
            "AND attempt_number=? ORDER BY event_sequence",
            (operation_id, attempt_number),
        ).fetchall()
        if (
            not rows
            or rows[0]["event_sequence"] != 1
            or rows[0]["state"] != "started"
            or len(rows) > 2
            or (len(rows) == 2 and rows[1]["event_sequence"] != 2)
        ):
            raise CatalogError("recovery attempt event sequence is malformed")
        started = rows[0]
        outcome = rows[-1]
        if any(
            outcome[name] != started[name]
            for name in (
                "operation_id",
                "attempt_number",
                "job_id",
                "cassette_sequence",
                "cassette_label",
                "trigger",
            )
        ):
            raise CatalogError("recovery attempt event identity is inconsistent")
        return RecoveryAttemptSummary(
            operation_id=started["operation_id"],
            job_id=started["job_id"],
            cassette_sequence=started["cassette_sequence"],
            cassette_label=started["cassette_label"],
            attempt_number=started["attempt_number"],
            trigger=started["trigger"],
            started_evidence_sha256=started["evidence_sha256"],
            started_decision=started["decision"],
            started_generation=started["daemon_generation"],
            started_at=started["recorded_at"],
            state=outcome["state"],
            evidence_sha256=outcome["evidence_sha256"],
            decision=outcome["decision"],
            daemon_generation=outcome["daemon_generation"],
            outcome_at=None if len(rows) == 1 else outcome["recorded_at"],
            next_eligible_at=outcome["next_eligible_at"],
        )

    def current_daemon_fence(self) -> DaemonFence | None:
        row = self.connection.execute(
            "SELECT owner_id, generation FROM daemon_ownership WHERE singleton=1"
        ).fetchone()
        if row is None:
            return None
        return DaemonFence(str(row["owner_id"]), int(row["generation"]))

    def media_identity_binding_evidence(self, operation_id: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT operation_id, observed_media_identity_sha256, "
            "bound_by_command_id, bound_at "
            "FROM operation_media_identity_bindings WHERE operation_id=?",
            (operation_id,),
        ).fetchone()

    def recovery_lineage_evidence(self, operation_id: str) -> tuple[sqlite3.Row, ...]:
        rows = self.connection.execute(
            "SELECT * FROM operation_recovery_lineages WHERE operation_id=? "
            "ORDER BY recovery_generation, id",
            (operation_id,),
        ).fetchall()
        return tuple(rows)

    def latest_command_quiescence_receipt(
        self, operation_id: str
    ) -> CommandQuiescenceReceipt | None:
        receipt = self.connection.execute(
            "SELECT * FROM command_quiescence_receipts WHERE operation_id=? "
            "ORDER BY recorded_at DESC, id DESC LIMIT 1",
            (operation_id,),
        ).fetchone()
        if receipt is None:
            return None
        rows = self.connection.execute(
            "SELECT command.*, item.exit_outcome AS receipt_exit_outcome "
            "FROM command_quiescence_receipt_items item "
            "JOIN hardware_command_executions command ON command.id=item.command_id "
            "WHERE item.receipt_id=? ORDER BY command.created_at, command.id",
            (receipt["id"],),
        ).fetchall()
        evidence = tuple(
            CommandExitEvidence(
                row["id"],
                self._process_from_command_row(row),
                row["receipt_exit_outcome"],
                row["quiesced_at"],
                row["terminal_exit_code"],
            )
            for row in rows
        )
        return CommandQuiescenceReceipt(
            id=receipt["id"],
            operation_id=receipt["operation_id"],
            reconciled_by_generation=receipt["reconciled_by_generation"],
            command_ids=tuple(row["id"] for row in rows),
            evidence=evidence,
            recorded_at=receipt["recorded_at"],
        )

    def latest_physical_reconciliation_receipt(
        self, operation_id: str
    ) -> PhysicalReconciliationReceipt | None:
        row = self.connection.execute(
            "SELECT * FROM physical_reconciliation_receipts WHERE operation_id=? "
            "ORDER BY recorded_at DESC, id DESC LIMIT 1",
            (operation_id,),
        ).fetchone()
        if row is None:
            return None
        target = None
        if row["mount_path_sha256"] is not None:
            target = self._target_from_row(row)
        return PhysicalReconciliationReceipt(
            id=row["id"],
            operation_id=row["operation_id"],
            reconciled_by_generation=row["reconciled_by_generation"],
            command_receipt_id=row["command_receipt_id"],
            target=target,
            observed_media_identity_sha256=row["observed_media_identity_sha256"],
            mounted=bool(row["mounted"]),
            media_loaded=bool(row["media_loaded"]),
            drive_busy=bool(row["drive_busy"]),
            related_processes=(),
            recorded_at=row["recorded_at"],
        )

    def recovery_resolution_evidence(self, operation_id: str) -> sqlite3.Row | None:
        return self.connection.execute(
            "SELECT * FROM recovery_resolutions WHERE operation_id=?",
            (operation_id,),
        ).fetchone()

    def physical_receipt_count(self, operation_id: str) -> int:
        return int(
            self.connection.execute(
                """
                SELECT COUNT(*) FROM physical_reconciliation_receipts
                WHERE operation_id=?
                """,
                (operation_id,),
            ).fetchone()[0]
        )

    def latest_audit_payload(self) -> dict:
        row = self.connection.execute(
            "SELECT payload_json FROM audit_entries ORDER BY id DESC LIMIT 1"
        ).fetchone()
        return {} if row is None else json.loads(row["payload_json"])

    def freeze_imported_job(
        self,
        job_id: str,
        assignment_sha256: str,
        cassette_plan_sha256: str,
        bundle_sha256: str,
        *,
        authority_state: str = "pre_cutover",
        windows_authority: str = "resumable",
        rollback_allowed: bool = True,
    ) -> None:
        self._validate_sha256(assignment_sha256, "assignment digest")
        self._validate_sha256(cassette_plan_sha256, "cassette plan digest")
        self._validate_sha256(bundle_sha256, "bundle digest")
        with self.transaction() as db:
            from .migration.validator import canonical_completed_evidence_sha256

            try:
                completed_evidence_sha256 = canonical_completed_evidence_sha256(
                    db,
                    job_id,
                    (1, 2, 3),
                    allow_missing_assignments=True,
                )
            except (LookupError, sqlite3.DatabaseError, TypeError, ValueError) as exc:
                raise ValidationError("imported completed evidence is invalid") from exc
            db.execute(
                """
                INSERT INTO imported_job_policies(
                    job_id, policy_kind, assignment_sha256,
                    cassette_plan_sha256, completed_evidence_sha256, bundle_sha256,
                    authority_state, windows_authority, rollback_allowed,
                    frozen_at, activated_by_operation, activated_at
                ) VALUES(?, 'frozen-allocation', ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL)
                """,
                (
                    job_id,
                    assignment_sha256,
                    cassette_plan_sha256,
                    completed_evidence_sha256,
                    bundle_sha256,
                    authority_state,
                    windows_authority,
                    int(rollback_allowed),
                    self._precise_utc_now(),
                ),
            )

            db.execute(
                """
                INSERT INTO migration_receipts(
                    id, job_id, bundle_sha256, assignment_sha256,
                    cassette_plan_sha256, completed_evidence_sha256, recorded_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    self._new_id("migration-receipt"),
                    job_id,
                    bundle_sha256,
                    assignment_sha256,
                    cassette_plan_sha256,
                    completed_evidence_sha256,
                    self._precise_utc_now(),
                ),
            )

    @staticmethod
    def _postcommit_command_tuple(command: sqlite3.Row) -> tuple[object, ...]:
        return _postcommit_command_evidence_tuple(command)

    @staticmethod
    def _commands_with_release_for_operation_tx(
        db: sqlite3.Connection,
        operation_id: str,
    ) -> tuple[sqlite3.Row, ...]:
        return tuple(
            db.execute(
                """
                SELECT command.*,
                       authorization.permit_sha256 AS release_permit_sha256,
                       authorization.release_status AS release_status,
                       authorization.authorized_at AS release_authorized_at,
                       authorization.confirmed_at AS release_confirmed_at
                FROM hardware_command_executions command
                LEFT JOIN hardware_command_release_authorizations authorization
                  ON authorization.command_id=command.id
                WHERE command.operation_id=?
                ORDER BY command.created_at, command.id
                """,
                (operation_id,),
            ).fetchall()
        )

    @classmethod
    def _commands_with_release_by_ids_tx(
        cls,
        db: sqlite3.Connection,
        command_ids: tuple[str, ...],
    ) -> tuple[sqlite3.Row, ...]:
        if not command_ids:
            return ()
        selected = set(command_ids)
        return tuple(
            command
            for command in cls._commands_with_release_for_operation_tx(
                db,
                db.execute(
                    "SELECT operation_id FROM hardware_command_executions WHERE id=?",
                    (command_ids[0],),
                ).fetchone()[0],
            )
            if command["id"] in selected
        )

    @classmethod
    def _postcommit_ledger_sha256(cls, commands) -> str:
        return imported_postcommit_command_sha256(
            tuple(cls._postcommit_command_tuple(command) for command in commands)
        )

    @classmethod
    def _authenticated_recovery_lineage_chain_tx(
        cls,
        db: sqlite3.Connection,
        *,
        runtime: bool,
        latest: sqlite3.Row,
        commit: sqlite3.Row,
        operation: sqlite3.Row,
    ) -> tuple[sqlite3.Row, ...]:
        chain: list[sqlite3.Row] = []
        seen: set[str] = set()
        current: sqlite3.Row | None = latest
        newer_generation: int | None = None
        newer_recorded: datetime | None = None
        committed = cls._parse_utc_timestamp(commit["committed_at"])
        try:
            while current is not None:
                lineage_id = current["id"]
                lineage_ids = tuple(json.loads(current["command_ids_json"]))
                observations = tuple(
                    tuple(value)
                    for value in json.loads(current["command_observations_json"])
                )
                evidence = imported_postcommit_command_sha256(observations)
                recorded = cls._parse_utc_timestamp(current["recorded_at"])
                observation_times = tuple(
                    value[index]
                    for value in observations
                    for index in (16, 17, 18, 19, 22, 23)
                    if value[index] is not None
                )
                parsed_observation_times = tuple(
                    cls._parse_utc_timestamp(value) for value in observation_times
                )
                binding = imported_recovery_lineage_sha256(
                    (
                        lineage_id,
                        current["job_id"],
                        current["sequence"],
                        current["operation_id"],
                        current["original_owner_generation"],
                        current["recovery_generation"],
                        current["daemon_owner_id"],
                        current["prior_lineage_id"],
                        current["commit_binding_sha256"],
                        current["restart_state"],
                        lineage_ids,
                        evidence,
                        current["recorded_at"],
                    )
                )
                if (
                    lineage_id in seen
                    or current["job_id"] != commit["job_id"]
                    or current["sequence"] != commit["sequence"]
                    or current["operation_id"] != operation["id"]
                    or current["original_owner_generation"]
                    != commit["owner_generation"]
                    or current["recovery_generation"] <= commit["owner_generation"]
                    or (
                        newer_generation is not None
                        and current["recovery_generation"] >= newer_generation
                    )
                    or current["commit_binding_sha256"]
                    != commit["commit_binding_sha256"]
                    or current["restart_state"] not in {"running", "recovery_required"}
                    or not isinstance(current["daemon_owner_id"], str)
                    or not current["daemon_owner_id"]
                    or tuple(value[0] for value in observations) != lineage_ids
                    or any(
                        not hardware_command_release_evidence_valid(value)
                        for value in observations
                    )
                    or current["command_evidence_sha256"] != evidence
                    or current["lineage_sha256"] != binding
                    or committed is None
                    or recorded is None
                    or recorded <= committed
                    or (newer_recorded is not None and recorded >= newer_recorded)
                    or any(
                        value is None or value > recorded
                        for value in parsed_observation_times
                    )
                ):
                    return ()
                chain.append(current)
                seen.add(lineage_id)
                newer_generation = current["recovery_generation"]
                newer_recorded = recorded
                prior_id = current["prior_lineage_id"]
                current = (
                    None
                    if prior_id is None
                    else (
                        db.execute(
                            "SELECT * FROM "
                            "imported_runtime_recovery_lineage_receipts WHERE id=?",
                            (prior_id,),
                        ).fetchone()
                        if runtime
                        else db.execute(
                            "SELECT * FROM imported_recovery_lineage_receipts "
                            "WHERE id=?",
                            (prior_id,),
                        ).fetchone()
                    )
                )
                if prior_id is not None and current is None:
                    return ()
        except (IndexError, KeyError, TypeError, ValueError, json.JSONDecodeError):
            return ()
        return tuple(chain)

    @classmethod
    def _postcommit_receipt_lineage_replay_valid(
        cls,
        receipt: sqlite3.Row,
        lineage_chain: tuple[sqlite3.Row, ...],
        commit: sqlite3.Row,
        command: sqlite3.Row,
    ) -> bool:
        receipt_lineage_id = receipt["recovery_lineage_id"]
        if not lineage_chain:
            return receipt_lineage_id is None
        receipt_recorded = cls._parse_utc_timestamp(receipt["recorded_at"])
        if receipt_recorded is None:
            return False
        if receipt_lineage_id is None:
            oldest = lineage_chain[-1]
            oldest_recorded = cls._parse_utc_timestamp(oldest["recorded_at"])
            current_observation = cls._postcommit_command_tuple(command)
            try:
                oldest_observations = {
                    value[0]: tuple(value)
                    for value in json.loads(oldest["command_observations_json"])
                }
            except (IndexError, TypeError, ValueError, json.JSONDecodeError):
                return False
            return bool(
                receipt["command_id"] == command["id"]
                and receipt["operation_id"] == command["operation_id"]
                and receipt["job_id"] == commit["job_id"]
                and receipt["sequence"] == commit["sequence"]
                and receipt["issued_generation"] == command["issued_generation"]
                and commit["owner_generation"]
                <= receipt["issued_generation"]
                < oldest["recovery_generation"]
                and receipt["command_evidence_sha256"]
                in {
                    imported_postcommit_command_sha256(current_observation),
                    imported_postcommit_command_sha256(
                        ("exact-no-media-v1", *current_observation)
                    ),
                    _exact_no_media_command_sha256(command),
                }
                and oldest_recorded is not None
                and receipt_recorded < oldest_recorded
                and oldest_observations.get(command["id"]) == current_observation
            )
        bound = next(
            (row for row in lineage_chain if row["id"] == receipt_lineage_id),
            None,
        )
        bound_recorded = (
            None if bound is None else cls._parse_utc_timestamp(bound["recorded_at"])
        )
        return bool(
            bound is not None
            and bound_recorded is not None
            and receipt_recorded > bound_recorded
        )

    @staticmethod
    def _cutover_authorization_evidence(
        authorization: sqlite3.Row,
        operation: sqlite3.Row,
        target: sqlite3.Row,
    ) -> str:
        return cutover_authorization_evidence_sha256(
            (
                authorization["id"],
                authorization["credential_sha256"],
                authorization["job_id"],
                authorization["cassette_sequence"],
                authorization["bundle_sha256"],
                authorization["catalog_binding_sha256"],
                authorization["assignment_sha256"],
                authorization["expected_label"],
                authorization["host_id"],
                authorization["drive_serial_sha256"],
                authorization["peer_kind"],
                authorization["created_at"],
                authorization["expires_at"],
                authorization["consumed_at"],
                authorization["consumed_by_operation_id"],
                operation["id"],
                operation["kind"],
                operation["job_id"],
                operation["cassette_sequence"],
                tuple(
                    target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                ),
            )
        )

    def attest_imported_postcommit_command(
        self,
        fence: OperationFence | RecoveryCommandFence,
        command_id: str,
    ) -> str:
        """Persist exact immutable evidence for one post-commit command."""

        return self._attest_imported_postcommit_command(fence, command_id)

    def _attest_imported_postcommit_command(
        self,
        fence: OperationFence | RecoveryCommandFence,
        command_id: str,
        _db: sqlite3.Connection | None = None,
        *,
        no_media_proven: bool = False,
    ) -> str:
        failure = "imported post-commit command evidence is invalid"
        if type(no_media_proven) is not bool:
            raise ValidationError(failure)
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            operation = self._assert_command_fence_tx(db, fence)
            commit = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
                (operation["id"],),
            ).fetchone()
            command = self._command_with_release_tx(db, command_id)
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (operation["id"],),
            ).fetchone()
            media = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (operation["id"],),
            ).fetchone()
            if commit is None or command is None or target is None or media is None:
                raise ValidationError(failure)
            try:
                frozen_ids = set(json.loads(commit["command_ids_json"]))
            except (TypeError, ValueError):
                raise ValidationError(failure) from None
            if (
                command["id"] in frozen_ids
                or command["operation_id"] != operation["id"]
                or command["command_kind"]
                not in {
                    "unload",
                    "probe_mount",
                    "probe_media",
                    "probe_drive",
                    "status",
                    "inquiry",
                    "terminate_process_group",
                }
                or command["state"] != "quiesced"
                or command["exit_outcome"]
                not in {"completed", "terminated", "launch_aborted"}
                or no_media_proven
                and (
                    command["command_kind"] != "probe_media"
                    or command["exit_outcome"] != "completed"
                )
                or not hardware_command_release_evidence_valid(
                    self._postcommit_command_tuple(command)
                )
                or not imported_postcommit_terminal_timeline_valid(
                    outcome=command["exit_outcome"],
                    created_at=command["created_at"],
                    released_at=command["released_at"],
                    exit_observed_at=command["exit_observed_at"],
                    quiesced_at=command["quiesced_at"],
                    process_identity=tuple(
                        command[field]
                        for field in (
                            "boot_id",
                            "pid",
                            "process_start_ticks",
                            "process_group_id",
                        )
                    ),
                    committed_at=commit["committed_at"],
                )
                or command["observed_media_identity_sha256"]
                != media["observed_media_identity_sha256"]
                or any(
                    command[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
            ):
                raise ValidationError(failure)
            lineage = None
            lineage_chain: tuple[sqlite3.Row, ...] = ()
            current_owner = db.execute(
                "SELECT owner_id, generation FROM daemon_ownership WHERE singleton=1"
            ).fetchone()
            if fence.owner_generation < command["issued_generation"]:
                raise ValidationError(failure)
            if fence.owner_generation == commit["owner_generation"]:
                if command["issued_generation"] != commit["owner_generation"]:
                    raise ValidationError(failure)
            else:
                lineage = db.execute(
                    "SELECT * FROM imported_recovery_lineage_receipts "
                    "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
                    (operation["id"],),
                ).fetchone()
                if (
                    not isinstance(fence, RecoveryCommandFence)
                    or lineage is None
                    or lineage["recovery_generation"] != fence.owner_generation
                    or current_owner is None
                    or current_owner["generation"] != fence.owner_generation
                    or current_owner["owner_id"] != lineage["daemon_owner_id"]
                ):
                    raise ValidationError(failure)
                if command["issued_generation"] == fence.owner_generation:
                    lineage_recorded_at = self._parse_utc_timestamp(
                        lineage["recorded_at"]
                    )
                    command_created_at = self._parse_utc_timestamp(
                        command["created_at"]
                    )
                    if (
                        lineage_recorded_at is None
                        or command_created_at is None
                        or command_created_at <= lineage_recorded_at
                    ):
                        raise ValidationError(failure)
                else:
                    try:
                        lineage_ids = tuple(json.loads(lineage["command_ids_json"]))
                        lineage_observations = tuple(
                            tuple(value)
                            for value in json.loads(
                                lineage["command_observations_json"]
                            )
                        )
                    except (KeyError, TypeError, ValueError):
                        raise ValidationError(failure) from None
                    observation_by_id = {
                        value[0]: value for value in lineage_observations
                    }
                    observed_command = observation_by_id.get(command_id)
                    current_command = self._postcommit_command_tuple(command)
                    transitioned_after_restart = bool(
                        observed_command is not None
                        and observed_command != current_command
                    )
                    observed_at = self._parse_utc_timestamp(lineage["recorded_at"])
                    terminal_at = self._parse_utc_timestamp(command["quiesced_at"])
                    lineage_evidence = imported_postcommit_command_sha256(
                        lineage_observations
                    )
                    lineage_binding = imported_recovery_lineage_sha256(
                        (
                            lineage["id"],
                            lineage["job_id"],
                            lineage["sequence"],
                            lineage["operation_id"],
                            lineage["original_owner_generation"],
                            lineage["recovery_generation"],
                            lineage["daemon_owner_id"],
                            lineage["prior_lineage_id"],
                            lineage["commit_binding_sha256"],
                            lineage["restart_state"],
                            lineage_ids,
                            lineage_evidence,
                            lineage["recorded_at"],
                        )
                    )
                    if (
                        lineage["job_id"] != commit["job_id"]
                        or lineage["sequence"] != 4
                        or lineage["operation_id"] != operation["id"]
                        or lineage["original_owner_generation"]
                        != commit["owner_generation"]
                        or lineage["commit_binding_sha256"]
                        != commit["commit_binding_sha256"]
                        or tuple(value[0] for value in lineage_observations)
                        != lineage_ids
                        or command_id not in lineage_ids
                        or observed_command is None
                        or not imported_postcommit_observation_transition_valid(
                            observed_command,
                            current_command,
                        )
                        or (
                            transitioned_after_restart
                            and (
                                observed_at is None
                                or terminal_at is None
                                or terminal_at <= observed_at
                            )
                        )
                        or lineage["command_evidence_sha256"] != lineage_evidence
                        or lineage["lineage_sha256"] != lineage_binding
                    ):
                        raise ValidationError(failure)
                lineage_chain = self._authenticated_recovery_lineage_chain_tx(
                    db,
                    runtime=False,
                    latest=lineage,
                    commit=commit,
                    operation=operation,
                )
                if not lineage_chain:
                    raise ValidationError(failure)
            postcommands = tuple(
                row
                for row in self._commands_with_release_for_operation_tx(
                    db, operation["id"]
                )
                if row["id"] not in frozen_ids
            )
            command_order = next(
                (
                    index
                    for index, row in enumerate(postcommands, 1)
                    if row["id"] == command_id
                ),
                None,
            )
            if command_order is None:
                raise ValidationError(failure)
            command_evidence = self._postcommit_command_tuple(command)
            evidence = imported_postcommit_command_sha256(
                command_evidence
            )
            if no_media_proven:
                evidence = _exact_no_media_command_sha256(command)
            existing = db.execute(
                "SELECT * FROM imported_postcommit_command_receipts WHERE command_id=?",
                (command_id,),
            ).fetchone()
            if existing is not None:
                if (
                    existing["command_evidence_sha256"] != evidence
                    or existing["command_order"] != command_order
                    or existing["issued_generation"] != command["issued_generation"]
                    or not self._postcommit_receipt_lineage_replay_valid(
                        existing, lineage_chain, commit, command
                    )
                ):
                    raise ValidationError(failure)
                return existing["command_evidence_sha256"]
            db.execute(
                "INSERT INTO imported_postcommit_command_receipts("
                "command_id, operation_id, job_id, sequence, issued_generation, "
                "recovery_lineage_id, command_order, command_evidence_sha256, "
                "recorded_at) VALUES(?, ?, ?, 4, ?, ?, ?, ?, ?)",
                (
                    command_id,
                    operation["id"],
                    commit["job_id"],
                    command["issued_generation"],
                    None if lineage is None else lineage["id"],
                    command_order,
                    evidence,
                    self._precise_utc_now(
                        after=max(
                            command["quiesced_at"],
                            "" if lineage is None else lineage["recorded_at"],
                        )
                    ),
                ),
            )
            return evidence

    @staticmethod
    def _imported_archive_operation_tx(
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        *,
        minimum_sequence: int = 4,
    ) -> tuple[str, int, sqlite3.Row, sqlite3.Row]:
        job_id = operation["job_id"]
        sequence = operation["cassette_sequence"]
        if (
            operation["kind"] != "archive.resume"
            or not isinstance(job_id, str)
            or isinstance(sequence, bool)
            or not isinstance(sequence, int)
            or not minimum_sequence <= sequence <= 20
        ):
            raise ValidationError("imported cassette operation is invalid")
        policy = db.execute(
            "SELECT * FROM imported_job_policies WHERE job_id=?", (job_id,)
        ).fetchone()
        cassette = db.execute(
            "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
            (job_id, sequence),
        ).fetchone()
        if policy is None or cassette is None:
            raise ValidationError("imported cassette operation is invalid")
        expected_authority = "pre_cutover" if sequence == 4 else "active_linux"
        if policy["authority_state"] != expected_authority:
            raise ValidationError("imported cassette authority is invalid")
        return job_id, sequence, policy, cassette

    def require_consumed_format_confirmation(
        self,
        fence: OperationFence,
        job_id: str,
        sequence: int,
        expected_label: str,
    ) -> None:
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            policy = db.execute(
                "SELECT 1 FROM imported_job_policies WHERE job_id=?",
                (operation["job_id"],),
            ).fetchone()
            if policy is not None:
                actual_job, actual_sequence, _policy, cassette = (
                    self._imported_archive_operation_tx(db, operation)
                )
            else:
                actual_job = operation["job_id"]
                actual_sequence = operation["cassette_sequence"]
                cassette = db.execute(
                    "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                    (actual_job, actual_sequence),
                ).fetchone()
                if operation["kind"] != "archive.native" or cassette is None:
                    raise ValidationError("format confirmation is not operation-bound")
            confirmation = db.execute(
                "SELECT * FROM format_confirmations WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if (
                actual_job != job_id
                or actual_sequence != sequence
                or cassette["operation"] != "format"
                or cassette["physical_label"] != expected_label
                or confirmation is None
                or confirmation["job_id"] != job_id
                or confirmation["cassette_sequence"] != sequence
                or confirmation["expected_label"] != expected_label
            ):
                raise ValidationError("format confirmation is not operation-bound")

    def transition_imported_cassette_phase(
        self, fence: OperationFence, phase: str
    ) -> None:
        if phase not in _OPERATION_PHASES:
            raise ValidationError("invalid persistent operation phase")
        predecessors = {
            "identifying_media": {None},
            "formatting_media": {"identifying_media"},
            "mounting": {"identifying_media", "formatting_media"},
            "writing": {"mounting"},
            "writing_manifest": {"writing"},
            "finalizing_index": {"writing_manifest"},
            "unmounting": {"finalizing_index"},
            "committing": {"unmounting"},
            "unloading": {"committing", "unloading"},
        }
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            if operation["phase"] == phase:
                return
            job_id, sequence, _policy, cassette = self._imported_archive_operation_tx(
                db, operation
            )
            if operation["phase"] not in predecessors[phase]:
                raise ValidationError("imported cassette phase transition is invalid")
            if phase == "formatting_media" and cassette["operation"] != "format":
                raise ValidationError("append cassette cannot enter formatting")
            db.execute(
                "UPDATE daemon_operations SET phase=? WHERE id=?",
                (phase, fence.operation_id),
            )
            db.execute(
                "UPDATE automatic_jobs SET status=?, current_sequence=?, "
                "started_at=COALESCE(started_at, ?), last_error=NULL WHERE id=?",
                (phase, sequence, self._precise_utc_now(), job_id),
            )
            db.execute(
                "UPDATE automatic_cassettes SET status=?, "
                "started_at=CASE WHEN ? IN ('writing','writing_manifest',"
                "'finalizing_index','unmounting','committing','unloading') "
                "THEN COALESCE(started_at, ?) ELSE started_at END, error=NULL "
                "WHERE job_id=? AND sequence=?",
                (phase, phase, self._precise_utc_now(), job_id, sequence),
            )

    def record_imported_unmount_timings(
        self,
        fence: OperationFence,
        *,
        finalization_started_at: str,
        finalization_seconds: float,
        unmounting_started_at: str,
        mount_release_seconds: float,
    ) -> None:
        samples = (
            ("finalizing_index", finalization_started_at, finalization_seconds),
            ("unmounting", unmounting_started_at, mount_release_seconds),
        )
        if any(
            not isinstance(started_at, str)
            or self._parse_utc_timestamp(started_at) is None
            or isinstance(duration, bool)
            or not isinstance(duration, (int, float))
            or not math.isfinite(duration)
            or duration < 0
            for _phase, started_at, duration in samples
        ):
            raise ValidationError("imported unmount timings are invalid")
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            self._imported_archive_operation_tx(db, operation)
            existing = db.execute(
                "SELECT COUNT(*) FROM phase_samples WHERE operation_id=? "
                "AND phase IN ('finalizing_index','unmounting')",
                (fence.operation_id,),
            ).fetchone()[0]
            if operation["phase"] != "unmounting" or existing:
                raise ValidationError("imported unmount timings are out of phase")
            db.executemany(
                "INSERT INTO phase_samples(operation_id,owner_generation,phase,"
                "started_at,duration_seconds,recorded_at) VALUES(?,?,?,?,?,?)",
                [
                    (
                        fence.operation_id,
                        fence.owner_generation,
                        phase,
                        started_at,
                        float(duration),
                        self._precise_utc_now(),
                    )
                    for phase, started_at, duration in samples
                ],
            )

    def record_imported_unmount_boundary(
        self,
        fence: OperationFence,
        *,
        phase: str,
        started_at: str,
    ) -> None:
        """Seal one callback boundary before the long-running broker finalize RPC."""

        if (
            phase not in {"finalizing_index", "unmounting"}
            or not isinstance(started_at, str)
            or self._parse_utc_timestamp(started_at) is None
        ):
            raise ValidationError("LTFS unmount boundary is invalid")
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            self._imported_archive_operation_tx(db, operation)
            allowed_operation_phases = {
                "finalizing_index": {
                    "writing_manifest",
                    "finalizing_index",
                    "unmounting",
                },
                "unmounting": {"finalizing_index", "unmounting"},
            }
            if operation["phase"] not in allowed_operation_phases[phase]:
                raise ValidationError("LTFS unmount boundary is out of phase")
            existing = db.execute(
                "SELECT started_at FROM ltfs_unmount_boundaries "
                "WHERE operation_id=? AND owner_generation=? AND phase=?",
                (fence.operation_id, fence.owner_generation, phase),
            ).fetchone()
            if existing is not None:
                if existing["started_at"] != started_at:
                    raise ValidationError("LTFS unmount boundary conflicts")
                return
            if phase == "unmounting":
                prior = db.execute(
                    "SELECT started_at FROM ltfs_unmount_boundaries "
                    "WHERE operation_id=? AND owner_generation=? "
                    "AND phase='finalizing_index'",
                    (fence.operation_id, fence.owner_generation),
                ).fetchone()
                if prior is None or self._parse_utc_timestamp(
                    started_at
                ) < self._parse_utc_timestamp(prior["started_at"]):
                    raise ValidationError("LTFS unmount boundary is not causal")
            db.execute(
                "INSERT INTO ltfs_unmount_boundaries(operation_id,owner_generation,"
                "phase,started_at,recorded_at) VALUES(?,?,?,?,?)",
                (
                    fence.operation_id,
                    fence.owner_generation,
                    phase,
                    started_at,
                    self._precise_utc_now(),
                ),
            )

    def record_imported_ltfs_terminal(
        self,
        fence: OperationFence | RecoveryCommandFence,
        *,
        finalization_started_at: str,
        unmounting_started_at: str,
        unmount_result: object,
        _db: sqlite3.Connection | None = None,
    ) -> None:
        """Atomically import exact LTFS terminal evidence and unmount timings."""

        from .broker.protocol import _encode_ltfs_standalone_receipt
        from .tape.command_supervisor import LtfsFinalizationReceipt
        from .tape.models import UnmountResult

        if type(unmount_result) is not UnmountResult:
            raise ValidationError("LTFS terminal receipt is invalid")
        finalization = unmount_result.finalization_receipt
        if type(finalization) is not LtfsFinalizationReceipt:
            raise ValidationError("LTFS terminal receipt is invalid")
        session = finalization.session_receipt
        standalone = finalization.standalone_receipt
        samples = (
            (
                "finalizing_index",
                finalization_started_at,
                unmount_result.finalization_seconds,
            ),
            (
                "unmounting",
                unmounting_started_at,
                unmount_result.mount_release_seconds,
            ),
        )
        if any(
            not isinstance(started_at, str)
            or self._parse_utc_timestamp(started_at) is None
            or isinstance(duration, bool)
            or not isinstance(duration, (int, float))
            or not math.isfinite(duration)
            or duration < 0
            for _phase, started_at, duration in samples
        ):
            raise ValidationError("LTFS terminal receipt is invalid")
        if (
            session.operation_id != fence.operation_id
            or session.read_only
            or standalone.operation_id != session.receipt_operation_uuid
            or standalone.volume_uuid != session.observed_volume_uuid
            or standalone.prior_generation != session.observed_prior_generation
            or standalone.new_generation <= standalone.prior_generation
            or standalone.bytes_valid is not True
            or standalone.bytes <= 0
            or standalone.files_valid is not True
            or standalone.files <= 0
            or standalone.media_committed is not True
            or standalone.catalog_acknowledged is not True
            or standalone.device_close_result_valid is not True
            or standalone.device_close_result != 0
            or standalone.cleanup_failed is not False
            or standalone.result != 0
            or finalization.unmounted is not True
            or finalization.child_quiesced is not True
            or unmount_result.observed_volume_label != session.observed_volume_label
            or unmount_result.observed_media_identity_sha256
            != session.observed_media_identity_sha256
            or type(finalization.request_nonce) is not bytes
            or len(finalization.request_nonce) != 32
            or type(finalization.finalization_nonce) is not bytes
            or len(finalization.finalization_nonce) != 32
            or type(finalization.broker_proof) is not bytes
            or len(finalization.broker_proof) != 32
            or len(
                {
                    finalization.request_nonce,
                    finalization.finalization_nonce,
                    finalization.broker_proof,
                }
            )
            != 3
            or type(unmount_result.observed_volume_label) is not str
            or not unmount_result.observed_volume_label
            or unmount_result.observed_volume_label
            != unmount_result.observed_volume_label.strip(" ")
            or not unmount_result.observed_volume_label.isascii()
            or not unmount_result.observed_volume_label.isprintable()
            or len(unmount_result.observed_volume_label) > 255
            or not isinstance(unmount_result.observed_media_identity_sha256, str)
            or not _SHA256.fullmatch(unmount_result.observed_media_identity_sha256)
        ):
            raise ValidationError("LTFS terminal receipt is invalid")
        standalone_json = json.dumps(
            _encode_ltfs_standalone_receipt(standalone),
            separators=(",", ":"),
            sort_keys=True,
        )
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            operation, original_generation = self._assert_imported_archive_fence_tx(
                db, fence
            )
            if session.owner_generation != original_generation:
                raise ValidationError("LTFS terminal receipt is invalid")
            values = (
                fence.operation_id,
                original_generation,
                session.receipt_operation_uuid,
                session.session_id,
                session.request_sha256,
                standalone.volume_uuid,
                standalone.prior_generation,
                standalone.new_generation,
                int(standalone.bytes_valid),
                standalone.bytes,
                int(standalone.files_valid),
                standalone.files,
                int(standalone.media_committed),
                int(standalone.catalog_acknowledged),
                int(standalone.device_close_result_valid),
                standalone.device_close_result,
                int(standalone.cleanup_failed),
                standalone.result,
                standalone.terminal_sha256,
                finalization.request_nonce,
                finalization.finalization_nonce,
                finalization.broker_proof,
                session.observed_volume_label,
                session.observed_media_identity_sha256,
                standalone_json,
            )
            job_id, sequence, _policy, cassette = self._imported_archive_operation_tx(
                db, operation
            )
            boundaries = {
                row["phase"]: row["started_at"]
                for row in db.execute(
                    "SELECT phase,started_at FROM ltfs_unmount_boundaries "
                    "WHERE operation_id=? AND owner_generation=?",
                    (fence.operation_id, original_generation),
                )
            }
            if (
                operation["phase"] not in {"unmounting", "committing"}
                or cassette["physical_label"] != session.observed_volume_label
                or boundaries
                != {
                    "finalizing_index": finalization_started_at,
                    "unmounting": unmounting_started_at,
                }
            ):
                raise ValidationError("LTFS terminal receipt is invalid")
            existing = db.execute(
                "SELECT * FROM ltfs_terminal_receipts "
                "WHERE operation_id=? AND owner_generation=?",
                (fence.operation_id, original_generation),
            ).fetchone()
            if existing is not None:
                existing_values = tuple(
                    existing[key]
                    for key in (
                        "operation_id",
                        "owner_generation",
                        "receipt_operation_uuid",
                        "session_id",
                        "request_sha256",
                        "volume_uuid",
                        "prior_generation",
                        "new_generation",
                        "bytes_valid",
                        "byte_count",
                        "files_valid",
                        "file_count",
                        "media_committed",
                        "catalog_acknowledged",
                        "device_close_result_valid",
                        "device_close_result",
                        "cleanup_failed",
                        "result",
                        "terminal_sha256",
                        "request_nonce",
                        "finalization_nonce",
                        "broker_proof",
                        "observed_volume_label",
                        "observed_media_identity_sha256",
                        "standalone_receipt_json",
                    )
                )
                existing_samples = tuple(
                    (
                        row["phase"],
                        row["started_at"],
                        row["duration_seconds"],
                    )
                    for row in db.execute(
                        "SELECT phase,started_at,duration_seconds FROM phase_samples "
                        "WHERE operation_id=? AND phase IN "
                        "('finalizing_index','unmounting') ORDER BY id",
                        (fence.operation_id,),
                    )
                )
                requested_samples = tuple(
                    (phase, started_at, float(duration))
                    for phase, started_at, duration in samples
                )
                if existing_values != values or existing_samples != requested_samples:
                    raise ValidationError("LTFS terminal receipt conflicts")
                return
            if operation["phase"] != "unmounting":
                raise ValidationError("LTFS terminal receipt is out of phase")
            if (
                db.execute(
                    "SELECT 1 FROM phase_samples WHERE operation_id=? AND phase IN "
                    "('finalizing_index','unmounting')",
                    (fence.operation_id,),
                ).fetchone()
                is not None
            ):
                raise ValidationError("LTFS terminal receipt is out of phase")
            db.execute(
                "INSERT INTO ltfs_terminal_receipts("
                "operation_id,owner_generation,job_id,sequence,receipt_operation_uuid,"
                "session_id,request_sha256,volume_uuid,prior_generation,new_generation,"
                "bytes_valid,byte_count,files_valid,file_count,media_committed,"
                "catalog_acknowledged,device_close_result_valid,device_close_result,"
                "cleanup_failed,result,terminal_sha256,request_nonce,"
                "finalization_nonce,broker_proof,"
                "observed_volume_label,observed_media_identity_sha256,"
                "standalone_receipt_json,recorded_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,"
                "?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    fence.operation_id,
                    original_generation,
                    job_id,
                    sequence,
                    *values[2:],
                    self._precise_utc_now(),
                ),
            )
            db.executemany(
                "INSERT INTO phase_samples(operation_id,owner_generation,phase,"
                "started_at,duration_seconds,recorded_at) VALUES(?,?,?,?,?,?)",
                [
                    (
                        fence.operation_id,
                        original_generation,
                        phase,
                        started_at,
                        float(duration),
                        self._precise_utc_now(),
                    )
                    for phase, started_at, duration in samples
                ],
            )

    @staticmethod
    def _require_ltfs_terminal_receipt_tx(
        db: sqlite3.Connection,
        operation_id: str,
        owner_generation: int,
        job_id: str,
        sequence: int,
        physical_label: str,
        observed_media_identity_sha256: str | None,
    ) -> sqlite3.Row:
        row = db.execute(
            "SELECT * FROM ltfs_terminal_receipts WHERE operation_id=? "
            "AND owner_generation=? AND job_id=? AND sequence=?",
            (operation_id, owner_generation, job_id, sequence),
        ).fetchone()
        if (
            row is None
            or row["observed_volume_label"] != physical_label
            or row["observed_media_identity_sha256"] != observed_media_identity_sha256
            or row["new_generation"] <= row["prior_generation"]
            or row["bytes_valid"] != 1
            or row["byte_count"] <= 0
            or row["files_valid"] != 1
            or row["file_count"] <= 0
            or row["media_committed"] != 1
            or row["catalog_acknowledged"] != 1
            or row["device_close_result_valid"] != 1
            or row["device_close_result"] != 0
            or row["cleanup_failed"] != 0
            or row["result"] != 0
        ):
            raise ValidationError("LTFS terminal receipt is unavailable")
        return row

    def recover_imported_ltfs_terminal_and_commit(
        self,
        fence: OperationFence | RecoveryCommandFence,
        finalization_receipt: object,
    ) -> str:
        """Import one recovered broker terminal and commit without unloading media."""

        from .tape.command_supervisor import LtfsFinalizationReceipt
        from .tape.models import UnmountResult

        if (
            type(fence) not in {OperationFence, RecoveryCommandFence}
            or type(finalization_receipt) is not LtfsFinalizationReceipt
        ):
            raise ValidationError("recovered LTFS terminal receipt is invalid")
        standalone = finalization_receipt.standalone_receipt
        with self.transaction() as db:
            operation, original_generation = self._assert_imported_archive_fence_tx(
                db, fence
            )
            job_id, sequence, _policy, cassette = self._imported_archive_operation_tx(
                db, operation
            )
            if (
                finalization_receipt.session_receipt.owner_generation
                != original_generation
            ):
                raise ValidationError("recovered LTFS terminal receipt is invalid")
            if operation["phase"] == "unloading":
                self._require_recovered_ltfs_terminal_replay_tx(
                    db,
                    fence.operation_id,
                    original_generation,
                    finalization_receipt,
                )
                tape_id = cassette["tape_id"]
                block_ids = tuple(
                    value
                    for value in str(cassette["block_id"] or "").split(",")
                    if value
                )
                if type(tape_id) is not str or not tape_id or not block_ids:
                    raise ValidationError(
                        "recovered LTFS staging evidence is unavailable"
                    )
                if sequence == 4:
                    self.commit_imported_cassette_authority(
                        fence, tape_id, block_ids, _db=db
                    )
                    return "waiting_media"
                return self._replay_imported_runtime_commit_tx(
                    db,
                    operation,
                    original_generation,
                    tape_id,
                    block_ids,
                )
            boundaries = {
                row["phase"]: row["started_at"]
                for row in db.execute(
                    "SELECT phase,started_at FROM ltfs_unmount_boundaries "
                    "WHERE operation_id=? AND owner_generation=?",
                    (fence.operation_id, original_generation),
                )
            }
            if frozenset(boundaries) != {"finalizing_index", "unmounting"}:
                raise ValidationError("recovered LTFS boundaries are unavailable")
            existing_samples = tuple(
                db.execute(
                    "SELECT phase,duration_seconds FROM phase_samples "
                    "WHERE operation_id=? AND owner_generation=? AND phase IN "
                    "('finalizing_index','unmounting') ORDER BY id",
                    (fence.operation_id, original_generation),
                )
            )
            if existing_samples:
                if tuple(row["phase"] for row in existing_samples) != (
                    "finalizing_index",
                    "unmounting",
                ):
                    raise ValidationError("recovered LTFS timings are invalid")
                finalization_seconds = float(existing_samples[0]["duration_seconds"])
                mount_release_seconds = float(existing_samples[1]["duration_seconds"])
            else:
                finalization_seconds = standalone.capture_duration_ns / 1_000_000_000
                mount_release_seconds = (
                    standalone.device_close_duration_ns / 1_000_000_000
                )
            unmount_result = UnmountResult(
                finalization_seconds,
                mount_release_seconds,
                finalization_receipt,
            )
            self.record_imported_ltfs_terminal(
                fence,
                finalization_started_at=boundaries["finalizing_index"],
                unmounting_started_at=boundaries["unmounting"],
                unmount_result=unmount_result,
                _db=db,
            )
            if operation["phase"] == "unmounting":
                db.execute(
                    "UPDATE daemon_operations SET phase='committing' WHERE id=?",
                    (fence.operation_id,),
                )
                db.execute(
                    "UPDATE automatic_jobs SET status='committing' WHERE id=?",
                    (job_id,),
                )
                db.execute(
                    "UPDATE automatic_cassettes SET status='committing' "
                    "WHERE job_id=? AND sequence=?",
                    (job_id, sequence),
                )
            elif operation["phase"] != "committing":
                raise ValidationError("recovered LTFS commit is out of phase")
            tape_id = cassette["tape_id"]
            block_ids = tuple(
                value for value in str(cassette["block_id"] or "").split(",") if value
            )
            if type(tape_id) is not str or not tape_id or not block_ids:
                raise ValidationError("recovered LTFS staging evidence is unavailable")
            if sequence == 4:
                self.commit_imported_cassette_authority(
                    fence, tape_id, block_ids, _db=db
                )
                return "waiting_media"
            return self.commit_imported_cassette(fence, tape_id, block_ids, _db=db)

    @staticmethod
    def _require_recovered_ltfs_terminal_replay_tx(
        db: sqlite3.Connection,
        operation_id: str,
        original_generation: int,
        finalization: object,
    ) -> sqlite3.Row:
        from .broker.protocol import _encode_ltfs_standalone_receipt
        from .tape.command_supervisor import LtfsFinalizationReceipt

        if type(finalization) is not LtfsFinalizationReceipt:
            raise ValidationError("recovered LTFS terminal receipt is invalid")
        session = finalization.session_receipt
        standalone = finalization.standalone_receipt
        row = db.execute(
            "SELECT * FROM ltfs_terminal_receipts WHERE operation_id=? "
            "AND owner_generation=?",
            (operation_id, original_generation),
        ).fetchone()
        encoded = json.dumps(
            _encode_ltfs_standalone_receipt(standalone),
            separators=(",", ":"),
            sort_keys=True,
        )
        if (
            row is None
            or session.operation_id != operation_id
            or session.owner_generation != original_generation
            or row["receipt_operation_uuid"] != session.receipt_operation_uuid
            or row["session_id"] != session.session_id
            or row["request_sha256"] != session.request_sha256
            or row["volume_uuid"] != standalone.volume_uuid
            or row["prior_generation"] != standalone.prior_generation
            or row["new_generation"] != standalone.new_generation
            or row["byte_count"] != standalone.bytes
            or row["file_count"] != standalone.files
            or row["terminal_sha256"] != standalone.terminal_sha256
            or row["request_nonce"] != finalization.request_nonce
            or row["finalization_nonce"] != finalization.finalization_nonce
            or row["broker_proof"] != finalization.broker_proof
            or row["observed_volume_label"] != session.observed_volume_label
            or row["observed_media_identity_sha256"]
            != session.observed_media_identity_sha256
            or row["standalone_receipt_json"] != encoded
        ):
            raise ValidationError("recovered LTFS terminal receipt conflicts")
        return row

    def _replay_imported_runtime_commit_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        original_generation: int,
        tape_id: str,
        block_ids: tuple[str, ...],
    ) -> str:
        failure = "imported cassette commit replay is invalid"
        job_id = str(operation["job_id"])
        sequence = int(operation["cassette_sequence"])
        rows = db.execute(
            "SELECT * FROM imported_runtime_cassette_commit_receipts "
            "WHERE operation_id=?",
            (operation["id"],),
        ).fetchall()
        cassette = db.execute(
            "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
            (job_id, sequence),
        ).fetchone()
        job = db.execute(
            "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
        ).fetchone()
        target = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        media = db.execute(
            "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        commit = rows[0] if len(rows) == 1 else None
        if (
            commit is None
            or cassette is None
            or job is None
            or target is None
            or media is None
        ):
            raise ValidationError(failure)
        try:
            committed_blocks = tuple(json.loads(commit["block_ids_json"]))
            command_ids = tuple(json.loads(commit["command_ids_json"]))
            commands = self._commands_with_release_by_ids_tx(db, command_ids)
            from .migration.validator import (
                canonical_completed_evidence_sha256,
                canonical_sequence_manifest_sha256,
            )

            evidence = canonical_completed_evidence_sha256(
                db, job_id, (sequence,), allow_missing_assignments=False
            )
            manifest = canonical_sequence_manifest_sha256(db, job_id, sequence)
        except (LookupError, sqlite3.DatabaseError, TypeError, ValueError) as exc:
            raise ValidationError(failure) from exc
        command_evidence = imported_postcommit_command_sha256(
            tuple(self._postcommit_command_tuple(row) for row in commands)
        )
        target_values = tuple(
            target[field]
            for field in (
                "mount_path_sha256",
                "tape_device_identity_sha256",
                "scsi_device_identity_sha256",
                "expected_media_scope_sha256",
            )
        )
        binding = imported_cassette_commit_binding_sha256(
            (
                operation["id"],
                original_generation,
                job_id,
                sequence,
                tape_id,
                block_ids,
                manifest,
                evidence,
                media["observed_media_identity_sha256"],
                commit["terminal_sha256"],
                target_values,
                command_ids,
                command_evidence,
                commit["authority_sha256"],
                commit["committed_at"],
            )
        )
        expected_job_state = (
            "completed"
            if sequence
            == db.execute(
                "SELECT total_cassettes FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()[0]
            else "waiting_media"
        )
        if (
            operation["phase"] != "unloading"
            or commit["owner_generation"] != original_generation
            or commit["job_id"] != job_id
            or commit["sequence"] != sequence
            or commit["tape_id"] != tape_id
            or committed_blocks != block_ids
            or tuple(row["id"] for row in commands) != command_ids
            or commit["evidence_sha256"] != evidence
            or commit["manifest_sha256"] != manifest
            or commit["command_evidence_sha256"] != command_evidence
            or commit["commit_binding_sha256"] != binding
            or commit["observed_media_identity_sha256"]
            != media["observed_media_identity_sha256"]
            or any(
                commit[field] != target[field]
                for field in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
            or cassette["status"] != "completed"
            or cassette["tape_id"] != tape_id
            or job["status"] != expected_job_state
        ):
            raise ValidationError(failure)
        return expected_job_state

    def stage_imported_cassette(
        self,
        fence: OperationFence,
        *,
        tape_id: str | None = None,
        mount_hint: str,
        blocks: tuple[tuple[str, str, str, int, int], ...],
    ) -> str:
        if tape_id is not None:
            self._validate_safe_identifier(tape_id, "tape ID")
        if (
            not isinstance(mount_hint, str)
            or not mount_hint
            or not isinstance(blocks, tuple)
            or not blocks
        ):
            raise ValidationError("imported cassette staging inputs are invalid")
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            job_id, sequence, _policy, cassette = self._imported_archive_operation_tx(
                db, operation
            )
            if operation["phase"] != "mounting" or cassette["status"] != "mounting":
                raise ValidationError("imported cassette is not ready for staging")
            volume_serial = cassette["tape_serial"]
            if not isinstance(volume_serial, str) or not volume_serial:
                raise ValidationError("frozen cassette serial is invalid")
            if cassette["tape_id"] is not None or cassette["block_id"] is not None:
                raise ValidationError("imported cassette was already staged")
            normalized: list[tuple[str, str, str, int, int]] = []
            for value in blocks:
                if not isinstance(value, tuple) or len(value) != 5:
                    raise ValidationError("imported block plan is invalid")
                block_id, library_id, root, files, size = value
                self._validate_safe_identifier(block_id, "block ID")
                self._validate_safe_identifier(library_id, "library ID")
                self._validate_portable_relative_path(root, "tape_relative_root")
                if (
                    isinstance(files, bool)
                    or not isinstance(files, int)
                    or files <= 0
                    or isinstance(size, bool)
                    or not isinstance(size, int)
                    or size < 0
                    or root != f"libraries/{library_id}/blocks/{block_id}"
                ):
                    raise ValidationError("imported block plan is invalid")
                normalized.append(value)
            block_ids = tuple(value[0] for value in normalized)
            if len(set(block_ids)) != len(block_ids):
                raise ValidationError("imported block IDs are duplicated")
            assigned = {
                row["library_id"]: (row["files"], row["bytes"])
                for row in db.execute(
                    "SELECT library_id, COUNT(*) AS files, SUM(size) AS bytes "
                    "FROM automatic_cassette_items WHERE job_id=? AND sequence=? "
                    "GROUP BY library_id",
                    (job_id, sequence),
                )
            }
            planned = {value[1]: (value[3], value[4]) for value in normalized}
            if (
                assigned != planned
                or sum(value[3] for value in normalized) != cassette["planned_files"]
                or sum(value[4] for value in normalized) != cassette["planned_bytes"]
            ):
                raise ValidationError("imported block plan changed frozen assignments")
            existing = db.execute(
                "SELECT * FROM tapes WHERE cassette_number=? COLLATE NOCASE",
                (cassette["physical_label"],),
            ).fetchall()
            if existing:
                if (
                    len(existing) != 1
                    or tape_id is not None
                    and existing[0]["id"] != tape_id
                    or existing[0]["cassette_number"] != cassette["physical_label"]
                    or existing[0]["volume_label"] != cassette["physical_label"]
                    or existing[0]["volume_serial"] != volume_serial
                    or existing[0]["status"] != "active"
                ):
                    raise ValidationError(
                        "imported tape identity conflicts with catalog"
                    )
                tape_id = existing[0]["id"]
                db.execute(
                    "UPDATE tapes SET volume_serial=?, volume_label=?, filesystem='LTFS', "
                    "mount_hint=?, last_seen_at=? WHERE id=?",
                    (
                        volume_serial,
                        cassette["physical_label"],
                        mount_hint,
                        self._precise_utc_now(),
                        tape_id,
                    ),
                )
            else:
                if tape_id is None:
                    tape_id = (
                        "imported-"
                        + hashlib.sha256(
                            json.dumps(
                                (
                                    "lto-imported-tape-v1",
                                    cassette["physical_label"],
                                    volume_serial,
                                ),
                                ensure_ascii=True,
                                separators=(",", ":"),
                            ).encode("ascii")
                        ).hexdigest()
                    )
                now = self._precise_utc_now()
                db.execute(
                    "INSERT INTO tapes(id,cassette_number,volume_serial,volume_label,"
                    "filesystem,mount_hint,status,created_at,last_seen_at) "
                    "VALUES(?,?,?,?,? ,?,'active',?,?)",
                    (
                        tape_id,
                        cassette["physical_label"],
                        volume_serial,
                        cassette["physical_label"],
                        "LTFS",
                        mount_hint,
                        now,
                        now,
                    ),
                )
            now = self._precise_utc_now()
            db.executemany(
                "INSERT INTO blocks(id,library_id,tape_id,tape_relative_root,status,"
                "visible,planned_files,planned_bytes,started_at) "
                "VALUES(?,?,?,?,'copying',0,?,?,?)",
                [
                    (block_id, library_id, tape_id, root, files, size, now)
                    for block_id, library_id, root, files, size in normalized
                ],
            )
            db.execute(
                "UPDATE automatic_cassettes SET tape_id=?, block_id=?, "
                "started_at=COALESCE(started_at, ?) WHERE job_id=? AND sequence=?",
                (tape_id, ",".join(block_ids), now, job_id, sequence),
            )
            return tape_id

    def stage_imported_file(
        self,
        fence: OperationFence,
        *,
        item_sequence: int,
        block_id: str,
        tape_relative_path: str,
        sha256: str,
    ) -> int:
        self._validate_safe_identifier(block_id, "block ID")
        self._validate_portable_relative_path(tape_relative_path, "tape_relative_path")
        self._validate_sha256(sha256, "sha256")
        if isinstance(item_sequence, bool) or not isinstance(item_sequence, int):
            raise ValidationError("imported item sequence is invalid")
        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            job_id, sequence, _policy, cassette = self._imported_archive_operation_tx(
                db, operation
            )
            item = db.execute(
                "SELECT * FROM automatic_cassette_items WHERE job_id=? "
                "AND sequence=? AND item_sequence=?",
                (job_id, sequence, item_sequence),
            ).fetchone()
            block = db.execute(
                "SELECT * FROM blocks WHERE id=?", (block_id,)
            ).fetchone()
            expected_path = (
                None
                if block is None or item is None
                else (
                    PurePosixPath(block["tape_relative_root"])
                    / "files"
                    / PurePosixPath(ltfs_tape_relative_path(item["relative_path"]))
                ).as_posix()
            )
            if (
                operation["phase"] != "writing"
                or cassette["status"] != "writing"
                or item is None
                or block is None
                or block["status"] != "copying"
                or block["library_id"].casefold() != item["library_id"].casefold()
                or block["tape_id"].casefold() != cassette["tape_id"].casefold()
                or tape_relative_path != expected_path
                or db.execute(
                    "SELECT 1 FROM file_versions WHERE block_id=? AND "
                    "relative_path=? COLLATE NOCASE",
                    (block_id, item["relative_path"]),
                ).fetchone()
                is not None
            ):
                raise ValidationError(
                    "imported staged file is not frozen-assignment exact"
                )
            parent_path, file_name = self._split_relative_path(item["relative_path"])
            version_id = self._insert_file_version(
                db,
                item["library_id"],
                block_id,
                cassette["tape_id"],
                item["relative_path"],
                tape_relative_path,
                item["size"],
                item["mtime_ns"],
                sha256,
                {},
                visible=0,
                parent_path=parent_path,
                file_name=file_name,
                alternate_streams=[],
            )
            db.execute(
                "UPDATE file_versions SET copied_at=? WHERE id=?",
                (self._precise_utc_now(), version_id),
            )
            block_update = db.execute(
                "SELECT 1 FROM blocks WHERE id=? AND status='copying' "
                "AND copied_files<=planned_files AND copied_bytes<=planned_bytes",
                (block_id,),
            ).fetchone()
            cassette_update = db.execute(
                "UPDATE automatic_cassettes SET copied_files=copied_files+1, "
                "copied_bytes=copied_bytes+? WHERE job_id=? AND sequence=? "
                "AND copied_files+1<=planned_files AND copied_bytes+?<=planned_bytes",
                (item["size"], job_id, sequence, item["size"]),
            )
            if block_update is None or cassette_update.rowcount != 1:
                raise ValidationError("imported copy progress exceeds frozen plan")
            return version_id

    def commit_imported_cassette(
        self,
        fence: OperationFence | RecoveryCommandFence,
        tape_id: str,
        block_ids: tuple[str, ...],
        *,
        _db: sqlite3.Connection | None = None,
    ) -> str:
        self._validate_safe_identifier(tape_id, "tape ID")
        if (
            not isinstance(block_ids, tuple)
            or not block_ids
            or len(set(block_ids)) != len(block_ids)
            or any(
                not isinstance(value, str) or not _SAFE_IDENTIFIER.fullmatch(value)
                for value in block_ids
            )
        ):
            raise ValidationError("imported cassette block IDs are invalid")
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            operation, original_generation = self._assert_imported_archive_fence_tx(
                db, fence
            )
            job_id, sequence, policy, cassette = self._imported_archive_operation_tx(
                db, operation, minimum_sequence=5
            )
            expected_blocks = tuple(
                value for value in str(cassette["block_id"] or "").split(",") if value
            )
            blocks = db.execute(
                "SELECT * FROM blocks WHERE id IN ("
                + ",".join("?" for _ in block_ids)
                + ") ORDER BY started_at,id",
                block_ids,
            ).fetchall()
            commands = self._commands_with_release_for_operation_tx(
                db, fence.operation_id
            )
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            media = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            terminal_receipt = self._require_ltfs_terminal_receipt_tx(
                db,
                fence.operation_id,
                original_generation,
                job_id,
                sequence,
                cassette["physical_label"],
                None if media is None else media["observed_media_identity_sha256"],
            )
            copied_times = tuple(
                self._parse_utc_timestamp(row["copied_at"])
                for row in db.execute(
                    "SELECT copied_at FROM file_versions WHERE block_id IN ("
                    + ",".join("?" for _ in block_ids)
                    + ")",
                    block_ids,
                )
            )
            latest_copy = max(
                (value for value in copied_times if value is not None), default=None
            )
            media_probe = next(
                (
                    row
                    for row in commands
                    if media is not None and row["id"] == media["bound_by_command_id"]
                ),
                None,
            )
            command_kinds = tuple(row["command_kind"] for row in commands)
            bound_index = next(
                (
                    index
                    for index, row in enumerate(commands)
                    if media is not None and row["id"] == media["bound_by_command_id"]
                ),
                None,
            )
            format_rebind = db.execute(
                "SELECT * FROM format_media_rebindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            pre_bound_index = (
                bound_index
                if format_rebind is None
                else next(
                    (
                        index
                        for index, row in enumerate(commands)
                        if row["id"] == format_rebind["pre_probe_media_command_id"]
                    ),
                    None,
                )
            )
            ledger_shape_valid = bool(
                pre_bound_index is not None
                and imported_media_ledger_shape_valid(
                    command_kinds,
                    operation=cassette["operation"],
                    pre_bound_probe_index=pre_bound_index,
                    bound_probe_index=bound_index,
                )
                and (
                    cassette["operation"] == "append"
                    and format_rebind is None
                    or cassette["operation"] == "format"
                    and format_rebind is not None
                    and (
                        commands[pre_bound_index + 2]["id"]
                        == format_rebind["format_command_id"]
                        or commands[pre_bound_index + 3]["id"]
                        == format_rebind["format_command_id"]
                    )
                    and commands[bound_index]["id"]
                    == format_rebind["post_probe_media_command_id"]
                )
            )
            phase_samples = tuple(
                db.execute(
                    "SELECT phase,duration_seconds FROM phase_samples "
                    "WHERE operation_id=? AND phase IN "
                    "('finalizing_index','unmounting') ORDER BY id",
                    (fence.operation_id,),
                )
            )
            operation_started = self._parse_utc_timestamp(operation["started_at"])
            media_bound = (
                None if media is None else self._parse_utc_timestamp(media["bound_at"])
            )
            command_created = tuple(
                self._parse_utc_timestamp(row["created_at"]) for row in commands
            )
            earliest_copy = min(
                (value for value in copied_times if value is not None), default=None
            )
            terminal_recorded = self._parse_utc_timestamp(
                terminal_receipt["recorded_at"]
            )
            format_confirmation = db.execute(
                "SELECT * FROM format_confirmations WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            format_authorized = bool(
                cassette["operation"] == "append"
                and format_confirmation is None
                or cassette["operation"] == "format"
                and format_confirmation is not None
                and format_confirmation["job_id"] == job_id
                and format_confirmation["cassette_sequence"] == sequence
                and format_confirmation["expected_label"] == cassette["physical_label"]
            )
            if (
                operation["phase"] != "committing"
                or cassette["status"] != "committing"
                or cassette["tape_id"].casefold() != tape_id.casefold()
                or expected_blocks != block_ids
                or cassette["copied_files"] != cassette["planned_files"]
                or cassette["copied_bytes"] != cassette["planned_bytes"]
                or len(blocks) != len(block_ids)
                or target is None
                or media is None
                or media_probe is None
                or media_probe["command_kind"] != "probe_media"
                or bound_index is None
                or bound_index < 0
                or not ledger_shape_valid
                or not format_authorized
                or any(
                    row["observed_media_identity_sha256"] is not None
                    for row in commands[: pre_bound_index + 1]
                )
                or not copied_times
                or any(value is None for value in copied_times)
                or latest_copy is None
                or terminal_recorded is None
                or terminal_recorded < latest_copy
                or earliest_copy is None
                or operation_started is None
                or media_bound is None
                or any(value is None for value in command_created)
                or command_created[bound_index] > media_bound
                or any(
                    value < media_bound for value in command_created[bound_index + 1 :]
                )
                or command_created[-1] > earliest_copy
                or tuple(row["phase"] for row in phase_samples)
                != ("finalizing_index", "unmounting")
                or any(row["command_kind"] == "unload" for row in commands)
                or any(
                    row["status"] != "copying"
                    or row["visible"] != 0
                    or row["tape_id"].casefold() != tape_id.casefold()
                    or row["copied_files"] != row["planned_files"]
                    or row["copied_bytes"] != row["planned_bytes"]
                    for row in blocks
                )
                or any(
                    row["issued_generation"] != original_generation
                    or row["exit_outcome"] != "completed"
                    or not hardware_command_release_evidence_valid(
                        self._postcommit_command_tuple(row)
                    )
                    or any(
                        row[field] != target[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                    or row["observed_media_identity_sha256"]
                    != (
                        None
                        if index <= pre_bound_index
                        else format_rebind["pre_media_identity_sha256"]
                        if format_rebind is not None and index <= bound_index
                        else media["observed_media_identity_sha256"]
                    )
                    for index, row in enumerate(commands)
                )
            ):
                raise ValidationError("imported cassette commit proof is invalid")
            for block in blocks:
                versions = db.execute(
                    "SELECT COUNT(*) AS files, COALESCE(SUM(size),0) AS bytes, "
                    "MIN(visible) AS minimum_visible, MAX(visible) AS maximum_visible "
                    "FROM file_versions WHERE block_id=?",
                    (block["id"],),
                ).fetchone()
                if (
                    versions["files"] != block["planned_files"]
                    or versions["bytes"] != block["planned_bytes"]
                    or versions["minimum_visible"] != 0
                    or versions["maximum_visible"] != 0
                ):
                    raise ValidationError("imported cassette commit proof is invalid")
            committed_at = self._precise_utc_now(after=terminal_receipt["recorded_at"])
            placeholders = ",".join("?" for _ in block_ids)
            db.execute(
                "UPDATE blocks SET status='completed',visible=1,completed_at=?,error=NULL "
                f"WHERE id IN ({placeholders})",
                (committed_at, *block_ids),
            )
            db.execute(
                f"UPDATE file_versions SET visible=1 WHERE block_id IN ({placeholders})",
                block_ids,
            )
            db.execute(
                "UPDATE automatic_cassettes SET status='completed',completed_at=?,"
                "error=NULL WHERE job_id=? AND sequence=?",
                (committed_at, job_id, sequence),
            )
            from .migration.validator import (
                canonical_completed_evidence_sha256,
                canonical_sequence_manifest_sha256,
            )

            evidence = canonical_completed_evidence_sha256(
                db, job_id, (sequence,), allow_missing_assignments=False
            )
            manifest = canonical_sequence_manifest_sha256(db, job_id, sequence)
            command_ids = tuple(row["id"] for row in commands)
            command_evidence = imported_postcommit_command_sha256(
                tuple(self._postcommit_command_tuple(row) for row in commands)
            )
            target_values = tuple(
                target[field]
                for field in (
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
            binding = imported_cassette_commit_binding_sha256(
                (
                    fence.operation_id,
                    original_generation,
                    job_id,
                    sequence,
                    tape_id,
                    block_ids,
                    manifest,
                    evidence,
                    media["observed_media_identity_sha256"],
                    terminal_receipt["terminal_sha256"],
                    target_values,
                    command_ids,
                    command_evidence,
                    policy["assignment_sha256"],
                    committed_at,
                )
            )
            db.execute(
                "INSERT INTO imported_runtime_cassette_commit_receipts("
                "job_id,sequence,operation_id,owner_generation,authority_sha256,"
                "evidence_sha256,manifest_sha256,tape_id,block_ids_json,"
                "command_ids_json,command_evidence_sha256,commit_binding_sha256,"
                "observed_media_identity_sha256,mount_path_sha256,"
                "tape_device_identity_sha256,scsi_device_identity_sha256,"
                "expected_media_scope_sha256,terminal_sha256,committed_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    job_id,
                    sequence,
                    fence.operation_id,
                    original_generation,
                    policy["assignment_sha256"],
                    evidence,
                    manifest,
                    tape_id,
                    json.dumps(block_ids, separators=(",", ":")),
                    json.dumps(command_ids, separators=(",", ":")),
                    command_evidence,
                    binding,
                    media["observed_media_identity_sha256"],
                    *target_values,
                    terminal_receipt["terminal_sha256"],
                    committed_at,
                ),
            )
            total = db.execute(
                "SELECT total_cassettes FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()[0]
            next_state = "completed" if sequence == total else "waiting_media"
            next_sequence = sequence if next_state == "completed" else sequence + 1
            db.execute(
                "UPDATE automatic_jobs SET status=?,current_sequence=?,"
                "completed_at=CASE WHEN ?='completed' THEN ? ELSE NULL END,last_error=NULL "
                "WHERE id=?",
                (next_state, next_sequence, next_state, committed_at, job_id),
            )
            db.execute(
                "UPDATE daemon_operations SET phase='unloading' WHERE id=?",
                (fence.operation_id,),
            )
            return next_state

    def attest_imported_postcommit_unload(
        self,
        fence: OperationFence | RecoveryCommandFence,
        *,
        no_media_proven: bool | None = None,
        require_durable_no_media: bool = False,
    ) -> str:
        if (
            type(require_durable_no_media) is not bool
            or no_media_proven is not None
            and no_media_proven is not True
            or require_durable_no_media
            and no_media_proven is not None
        ):
            raise ValidationError("imported post-commit unload tail is invalid")
        with self.transaction() as db:
            legacy = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            runtime = db.execute(
                "SELECT * FROM imported_runtime_cassette_commit_receipts "
                "WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            commit = legacy if legacy is not None else runtime
            if commit is None or (legacy is not None and runtime is not None):
                raise ValidationError("imported post-commit family is invalid")
            self._assert_command_fence_tx(db, fence)
            frozen_ids = set(json.loads(commit["command_ids_json"]))
            rows = tuple(
                row
                for row in self._commands_with_release_for_operation_tx(
                    db, fence.operation_id
                )
                if row["id"] not in frozen_ids
            )
            quiesced_times = tuple(
                self._parse_utc_timestamp(row["quiesced_at"]) for row in rows
            )
            created_times = tuple(
                self._parse_utc_timestamp(row["created_at"]) for row in rows
            )
            receipt_table = (
                "imported_postcommit_command_receipts"
                if legacy is not None
                else "imported_runtime_postcommit_command_receipts"
            )
            durable_probe_indexes: list[int] = []
            recoverable_probe_indexes: list[int] = []
            for index, row in enumerate(rows):
                if row["command_kind"] != "probe_media":
                    continue
                exact_evidence = imported_postcommit_command_sha256(
                    ("exact-no-media-v1", *self._postcommit_command_tuple(row))
                )
                exact_evidence_v2 = _exact_no_media_command_sha256(row)
                receipt = db.execute(
                    f"SELECT command_evidence_sha256 FROM {receipt_table} "
                    "WHERE command_id=?",
                    (row["id"],),
                ).fetchone()
                if (
                    receipt is not None
                    and receipt["command_evidence_sha256"]
                    in {exact_evidence, exact_evidence_v2}
                ):
                    durable_probe_indexes.append(index)
                elif (
                    row["terminal_exit_code"] == 3
                    and index > 0
                    and self._imported_postcommit_exact_eject_pair_valid(
                        rows[index - 1], row
                    )
                ):
                    recoverable_probe_indexes.append(index)
            exact_tail_pair = bool(
                len(rows) >= 2
                and self._imported_postcommit_exact_eject_pair_valid(
                    rows[-2], rows[-1]
                )
                and rows[-1]["terminal_exit_code"] == 3
            )
            proof_index: int | None = None
            if no_media_proven is True:
                if exact_tail_pair:
                    proof_index = len(rows) - 1
                elif recoverable_probe_indexes:
                    proof_index = recoverable_probe_indexes[-1]
            elif durable_probe_indexes:
                proof_index = durable_probe_indexes[-1]
            elif require_durable_no_media and recoverable_probe_indexes:
                # The command supervisor durably recorded the exact no-medium
                # return code before the process could publish its receipt.  It
                # is therefore safe to recreate the missing receipt on replay.
                proof_index = recoverable_probe_indexes[-1]
            if proof_index is not None:
                tail_valid = self._imported_postcommit_eject_tail_valid(
                    rows,
                    exact_probe_indexes=frozenset(
                        (*durable_probe_indexes, *recoverable_probe_indexes, proof_index)
                    ),
                )
                durable_probe = proof_index in durable_probe_indexes
                recoverable_probe = proof_index in recoverable_probe_indexes
                only_observations_follow = all(
                    row["command_kind"] == "probe_media"
                    for row in rows[proof_index + 1 :]
                )
                proof_valid = (
                    only_observations_follow
                    and (
                        durable_probe
                        if require_durable_no_media
                        else no_media_proven is True or durable_probe
                    )
                )
                if require_durable_no_media and recoverable_probe:
                    proof_valid = only_observations_follow
            else:
                completed = tuple(
                    row for row in rows if row["exit_outcome"] == "completed"
                )
                tail_valid = bool(
                    rows
                    and no_media_proven is None
                    and not require_durable_no_media
                    and len(completed) == 1
                    and completed[0]["id"] == rows[-1]["id"]
                    and all(row["command_kind"] == "unload" for row in rows)
                    and all(
                        row["exit_outcome"]
                        in {"terminated", "launch_aborted"}
                        for row in rows[:-1]
                    )
                )
                proof_valid = tail_valid
            if proof_index is not None and no_media_proven is True and isinstance(
                fence, OperationFence
            ):
                tail_fence_valid = all(
                    row["issued_generation"] == fence.owner_generation for row in rows
                )
            elif proof_index is not None and no_media_proven is True:
                tail_fence_valid = bool(
                    rows[-1]["issued_generation"] == fence.owner_generation
                )
            elif proof_index is not None:
                tail_fence_valid = True
            else:
                tail_fence_valid = bool(
                    len(rows) == 1
                    or isinstance(fence, RecoveryCommandFence)
                    and rows[-1]["issued_generation"] == fence.owner_generation
                )
            if (
                not tail_valid
                or not proof_valid
                or not tail_fence_valid
                or any(value is None for value in (*quiesced_times, *created_times))
                or any(
                    quiesced_times[index] > created_times[index + 1]
                    for index in range(len(rows) - 1)
                )
            ):
                raise ValidationError("imported post-commit unload tail is invalid")
            evidence = ""
            proof_evidence: str | None = None
            for index, row in enumerate(rows):
                exact_no_media = proof_index == index
                if legacy is not None:
                    evidence = self._attest_imported_postcommit_command(
                        fence,
                        row["id"],
                        db,
                        no_media_proven=exact_no_media,
                    )
                else:
                    evidence = self._attest_imported_runtime_postcommit_unload(
                        fence,
                        row["id"],
                        db,
                        no_media_proven=exact_no_media,
                    )
                if exact_no_media:
                    proof_evidence = evidence
            return proof_evidence if proof_evidence is not None else evidence

    def attest_qualification_readback_eject(self, fence: OperationFence) -> str:
        """Persist the exact supervised unload/no-medium boundary for readback."""

        with self.transaction() as db:
            operation = self._assert_operation_fence_tx(db, fence)
            if (
                operation["kind"] != "tape.qualification-readback"
                or operation["state"] != "running"
            ):
                raise ValidationError("qualification readback eject proof is invalid")
            rows = self._commands_with_release_for_operation_tx(
                db, fence.operation_id
            )
            media = db.execute(
                "SELECT observed_media_identity_sha256 FROM "
                "operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if len(rows) < 2 or media is None:
                raise ValidationError("qualification readback eject proof is invalid")
            unload, probe = rows[-2:]
            unload_quiesced = self._parse_utc_timestamp(unload["quiesced_at"])
            probe_created = self._parse_utc_timestamp(probe["created_at"])
            probe_quiesced = self._parse_utc_timestamp(probe["quiesced_at"])
            if (
                not self._imported_postcommit_exact_eject_pair_valid(unload, probe)
                or probe["terminal_exit_code"] != 3
                or unload["issued_generation"] != fence.owner_generation
                or unload_quiesced is None
                or probe_created is None
                or probe_quiesced is None
                or not unload_quiesced <= probe_created <= probe_quiesced
            ):
                raise ValidationError("qualification readback eject proof is invalid")
            payload = (
                "qualification-readback-exact-eject-v1",
                fence.operation_id,
                fence.owner_generation,
                media["observed_media_identity_sha256"],
                *self._postcommit_command_tuple(unload),
                unload["terminal_exit_code"],
                *self._postcommit_command_tuple(probe),
                probe["terminal_exit_code"],
            )
            digest = imported_postcommit_command_sha256(payload)
            existing = db.execute(
                "SELECT * FROM qualification_readback_release_receipts "
                "WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if existing is not None:
                if (
                    existing["owner_generation"] != fence.owner_generation
                    or existing["unload_command_id"] != unload["id"]
                    or existing["probe_command_id"] != probe["id"]
                    or existing["release_receipt_sha256"] != digest
                ):
                    raise ValidationError(
                        "qualification readback eject proof is invalid"
                    )
                return digest
            recorded_at = self._precise_utc_now(after=probe["quiesced_at"])
            db.execute(
                "INSERT INTO qualification_readback_release_receipts("
                "operation_id,owner_generation,unload_command_id,probe_command_id,"
                "release_receipt_sha256,recorded_at) VALUES(?,?,?,?,?,?)",
                (
                    fence.operation_id,
                    fence.owner_generation,
                    unload["id"],
                    probe["id"],
                    digest,
                    recorded_at,
                ),
            )
            return digest

    @staticmethod
    def _imported_postcommit_eject_tail_valid(
        rows: tuple[sqlite3.Row, ...],
        *,
        exact_probe_indexes: frozenset[int],
    ) -> bool:
        index = 0
        while index < len(rows):
            command = rows[index]
            if command["state"] != "quiesced" or command["exit_outcome"] not in {
                "completed",
                "terminated",
                "launch_aborted",
            }:
                return False
            if command["command_kind"] == "probe_media":
                index += 1
                continue
            if command["command_kind"] != "unload":
                return False
            if command["exit_outcome"] in {"terminated", "launch_aborted"}:
                index += 1
                continue
            if (
                index + 1 >= len(rows)
                or index + 1 not in exact_probe_indexes
                or not Catalog._imported_postcommit_exact_eject_pair_valid(
                    command, rows[index + 1]
                )
            ):
                return False
            index += 2
        return bool(rows)

    @staticmethod
    def _imported_postcommit_exact_eject_pair_valid(
        unload: sqlite3.Row,
        probe: sqlite3.Row,
    ) -> bool:
        return bool(
            unload["command_kind"] == "unload"
            and unload["state"] == "quiesced"
            and unload["exit_outcome"] == "completed"
            and unload["terminal_exit_code"] == 0
            and probe["command_kind"] == "probe_media"
            and probe["state"] == "quiesced"
            and probe["exit_outcome"] == "completed"
            and unload["issued_generation"] == probe["issued_generation"]
            and all(
                unload[field] == probe[field]
                for field in (
                    "operation_id",
                    "mount_path_sha256",
                    "tape_device_identity_sha256",
                    "scsi_device_identity_sha256",
                    "expected_media_scope_sha256",
                )
            )
        )

    def _attest_imported_runtime_postcommit_unload(
        self,
        fence: OperationFence | RecoveryCommandFence,
        command_id: str,
        _db: sqlite3.Connection | None = None,
        *,
        no_media_proven: bool = False,
    ) -> str:
        failure = "imported runtime unload proof is invalid"
        if type(no_media_proven) is not bool:
            raise ValidationError(failure)
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            operation = self._assert_command_fence_tx(db, fence)
            commit = db.execute(
                "SELECT * FROM imported_runtime_cassette_commit_receipts "
                "WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            command = self._command_with_release_tx(db, command_id)
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            media = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            if commit is None or command is None or target is None or media is None:
                raise ValidationError(failure)
            current_owner = db.execute(
                "SELECT owner_id,generation FROM daemon_ownership WHERE singleton=1"
            ).fetchone()
            recovery_fence_valid = bool(
                isinstance(fence, RecoveryCommandFence)
                and operation["state"] == "recovery_required"
                and current_owner is not None
                and current_owner["generation"] == fence.owner_generation
                and fence.operation_id == operation["id"]
                and commit["owner_generation"]
                <= command["issued_generation"]
                <= fence.owner_generation
            )
            operation_fence_valid = bool(
                isinstance(fence, OperationFence)
                and fence.owner_generation == commit["owner_generation"]
                and command["issued_generation"] == commit["owner_generation"]
            )
            frozen_ids = tuple(json.loads(commit["command_ids_json"]))
            commands = self._commands_with_release_for_operation_tx(
                db, fence.operation_id
            )
            postcommit = tuple(row for row in commands if row["id"] not in frozen_ids)
            command_order = next(
                (
                    index
                    for index, row in enumerate(postcommit, 1)
                    if row["id"] == command_id
                ),
                None,
            )
            lineage = None
            lineage_chain: tuple[sqlite3.Row, ...] = ()
            lineage_valid = True
            if isinstance(fence, RecoveryCommandFence):
                lineage = db.execute(
                    "SELECT * FROM imported_runtime_recovery_lineage_receipts "
                    "WHERE operation_id=? ORDER BY recovery_generation DESC LIMIT 1",
                    (operation["id"],),
                ).fetchone()
                lineage_ids: tuple[str, ...] = ()
                lineage_observations: tuple[tuple[object, ...], ...] = ()
                lineage_evidence = ""
                lineage_binding = ""
                lineage_prior_valid = False
                lineage_timeline_valid = False
                if lineage is not None:
                    try:
                        lineage_ids = tuple(json.loads(lineage["command_ids_json"]))
                        lineage_observations = tuple(
                            tuple(value)
                            for value in json.loads(
                                lineage["command_observations_json"]
                            )
                        )
                        lineage_evidence = imported_postcommit_command_sha256(
                            lineage_observations
                        )
                        lineage_binding = imported_recovery_lineage_sha256(
                            (
                                lineage["id"],
                                lineage["job_id"],
                                lineage["sequence"],
                                lineage["operation_id"],
                                lineage["original_owner_generation"],
                                lineage["recovery_generation"],
                                lineage["daemon_owner_id"],
                                lineage["prior_lineage_id"],
                                lineage["commit_binding_sha256"],
                                lineage["restart_state"],
                                lineage_ids,
                                lineage_evidence,
                                lineage["recorded_at"],
                            )
                        )
                        prior_lineage = (
                            None
                            if lineage["prior_lineage_id"] is None
                            else db.execute(
                                "SELECT * FROM "
                                "imported_runtime_recovery_lineage_receipts "
                                "WHERE id=?",
                                (lineage["prior_lineage_id"],),
                            ).fetchone()
                        )
                        lineage_prior_valid = bool(
                            lineage["prior_lineage_id"] is None
                            or (
                                prior_lineage is not None
                                and prior_lineage["operation_id"]
                                == lineage["operation_id"]
                                and prior_lineage["original_owner_generation"]
                                == lineage["original_owner_generation"]
                                and prior_lineage["recovery_generation"]
                                < lineage["recovery_generation"]
                                and prior_lineage["commit_binding_sha256"]
                                == lineage["commit_binding_sha256"]
                            )
                        )
                        lineage_recorded = self._parse_utc_timestamp(
                            lineage["recorded_at"]
                        )
                        committed = self._parse_utc_timestamp(commit["committed_at"])
                        observation_times = tuple(
                            value[index]
                            for value in lineage_observations
                            for index in (16, 17, 18, 19, 22, 23)
                            if value[index] is not None
                        )
                        parsed_observation_times = tuple(
                            self._parse_utc_timestamp(value)
                            for value in observation_times
                        )
                        lineage_timeline_valid = bool(
                            lineage_recorded is not None
                            and committed is not None
                            and lineage_recorded > committed
                            and all(
                                value is not None and value <= lineage_recorded
                                for value in parsed_observation_times
                            )
                        )
                    except (
                        IndexError,
                        KeyError,
                        TypeError,
                        ValueError,
                        json.JSONDecodeError,
                    ):
                        lineage = None
                lineage_valid = bool(
                    lineage is not None
                    and lineage["job_id"] == commit["job_id"]
                    and lineage["sequence"] == commit["sequence"]
                    and lineage["operation_id"] == operation["id"]
                    and lineage["recovery_generation"] == fence.owner_generation
                    and current_owner is not None
                    and lineage["daemon_owner_id"] == current_owner["owner_id"]
                    and lineage["original_owner_generation"]
                    == commit["owner_generation"]
                    and lineage["commit_binding_sha256"]
                    == commit["commit_binding_sha256"]
                    and lineage["restart_state"] in {"running", "recovery_required"}
                    and lineage_prior_valid
                    and lineage_timeline_valid
                    and tuple(value[0] for value in lineage_observations) == lineage_ids
                    and lineage["command_evidence_sha256"] == lineage_evidence
                    and lineage["lineage_sha256"] == lineage_binding
                )
                if (
                    lineage_valid
                    and command["issued_generation"] == fence.owner_generation
                ):
                    created = self._parse_utc_timestamp(command["created_at"])
                    recorded = self._parse_utc_timestamp(lineage["recorded_at"])
                    lineage_valid = bool(
                        created is not None
                        and recorded is not None
                        and created > recorded
                    )
                elif lineage_valid:
                    observations = {
                        value[0]: tuple(value) for value in lineage_observations
                    }
                    observed = observations.get(command_id)
                    current_observation = self._postcommit_command_tuple(command)
                    transitioned_after_restart = bool(
                        observed is not None and observed != current_observation
                    )
                    observed_at = self._parse_utc_timestamp(lineage["recorded_at"])
                    terminal_at = self._parse_utc_timestamp(command["quiesced_at"])
                    lineage_valid = bool(
                        observed is not None
                        and imported_postcommit_observation_transition_valid(
                            observed, current_observation
                        )
                        and (
                            not transitioned_after_restart
                            or (
                                observed_at is not None
                                and terminal_at is not None
                                and terminal_at > observed_at
                            )
                        )
                    )
                if lineage_valid and lineage is not None:
                    lineage_chain = self._authenticated_recovery_lineage_chain_tx(
                        db,
                        runtime=True,
                        latest=lineage,
                        commit=commit,
                        operation=operation,
                    )
                    lineage_valid = bool(lineage_chain)
            command_evidence = self._postcommit_command_tuple(command)
            evidence = imported_postcommit_command_sha256(
                command_evidence
            )
            if no_media_proven:
                evidence = _exact_no_media_command_sha256(command)
            existing = db.execute(
                "SELECT * FROM imported_runtime_postcommit_command_receipts "
                "WHERE command_id=?",
                (command_id,),
            ).fetchone()
            if (
                operation["phase"] != "unloading"
                or not (operation_fence_valid or recovery_fence_valid)
                or not lineage_valid
                or operation["job_id"] != commit["job_id"]
                or operation["cassette_sequence"] != commit["sequence"]
                or command["operation_id"] != fence.operation_id
                or command_order is None
                or command["command_kind"]
                not in (
                    {"probe_media"}
                    if no_media_proven
                    else {"unload", "probe_media"}
                )
                or command["state"] != "quiesced"
                or command["exit_outcome"]
                not in {"completed", "terminated", "launch_aborted"}
                or no_media_proven and command["exit_outcome"] != "completed"
                or command["observed_media_identity_sha256"]
                != media["observed_media_identity_sha256"]
                or any(
                    command[field] != target[field] or commit[field] != target[field]
                    for field in (
                        "mount_path_sha256",
                        "tape_device_identity_sha256",
                        "scsi_device_identity_sha256",
                        "expected_media_scope_sha256",
                    )
                )
                or not hardware_command_release_evidence_valid(
                    self._postcommit_command_tuple(command)
                )
                or not imported_postcommit_terminal_timeline_valid(
                    outcome=command["exit_outcome"],
                    created_at=command["created_at"],
                    released_at=command["released_at"],
                    exit_observed_at=command["exit_observed_at"],
                    quiesced_at=command["quiesced_at"],
                    process_identity=tuple(
                        command[field]
                        for field in (
                            "boot_id",
                            "pid",
                            "process_start_ticks",
                            "process_group_id",
                        )
                    ),
                    committed_at=commit["committed_at"],
                )
            ):
                raise ValidationError(failure)
            if existing is not None:
                if (
                    existing["operation_id"] != fence.operation_id
                    or existing["job_id"] != commit["job_id"]
                    or existing["sequence"] != commit["sequence"]
                    or existing["issued_generation"] != command["issued_generation"]
                    or not self._postcommit_receipt_lineage_replay_valid(
                        existing, lineage_chain, commit, command
                    )
                    or existing["command_order"] != command_order
                    or existing["command_evidence_sha256"] != evidence
                ):
                    raise ValidationError(failure)
                return evidence
            db.execute(
                "INSERT INTO imported_runtime_postcommit_command_receipts("
                "command_id,operation_id,job_id,sequence,issued_generation,"
                "recovery_lineage_id,command_order,command_evidence_sha256,recorded_at) "
                "VALUES(?,?,?,?,?,?,?,?,?)",
                (
                    command_id,
                    fence.operation_id,
                    commit["job_id"],
                    commit["sequence"],
                    command["issued_generation"],
                    None if lineage is None else lineage["id"],
                    command_order,
                    evidence,
                    self._precise_utc_now(after=command["quiesced_at"]),
                ),
            )
            return evidence

    def commit_imported_cassette_authority(
        self,
        fence: OperationFence | RecoveryCommandFence,
        tape_id: str,
        block_ids: tuple[str, ...],
        *,
        _db: sqlite3.Connection | None = None,
    ) -> ImportedJobPolicy:
        """Atomically commit imported cassette four and Linux authority."""

        self._validate_safe_identifier(tape_id, "tape ID")
        if (
            not isinstance(block_ids, tuple)
            or not block_ids
            or len(set(block_ids)) != len(block_ids)
            or any(
                not isinstance(value, str) or not _SAFE_IDENTIFIER.fullmatch(value)
                for value in block_ids
            )
        ):
            raise ValidationError("imported cassette block IDs are invalid")
        failure = "imported cassette commit proof is invalid"
        transaction = self.transaction() if _db is None else nullcontext(_db)
        with transaction as db:
            operation, original_generation = self._assert_imported_archive_fence_tx(
                db, fence
            )
            if (
                operation["kind"] != "archive.resume"
                or operation["state"]
                != (
                    "recovery_required"
                    if isinstance(fence, RecoveryCommandFence)
                    else "running"
                )
                or operation["phase"] not in {"committing", "unloading"}
                or operation["job_id"] is None
                or operation["cassette_sequence"] != 4
                or operation["owner_generation"] != original_generation
                or operation["finished_at"] is not None
                or operation["error_class"] is not None
                or operation["error_code"] is not None
                or operation["error_message"] is not None
            ):
                raise ValidationError(failure)
            job_id = str(operation["job_id"])
            policy = db.execute(
                "SELECT * FROM imported_job_policies WHERE job_id=?", (job_id,)
            ).fetchone()
            receipt_rows = db.execute(
                "SELECT * FROM migration_receipts WHERE job_id=? ORDER BY id", (job_id,)
            ).fetchall()
            commit_rows = db.execute(
                "SELECT * FROM imported_cassette_commit_receipts WHERE job_id=? AND sequence=4",
                (job_id,),
            ).fetchall()
            if commit_rows:
                commit = commit_rows[0] if len(commit_rows) == 1 else None
                if (
                    commit is None
                    or policy is None
                    or policy["authority_state"] != "active_linux"
                    or policy["activated_by_operation"] != fence.operation_id
                    or commit["operation_id"] != fence.operation_id
                    or commit["owner_generation"] != original_generation
                    or commit["tape_id"].casefold() != tape_id.casefold()
                    or tuple(json.loads(commit["block_ids_json"])) != block_ids
                ):
                    raise ValidationError(failure)
                try:
                    from .migration.validator import (
                        canonical_completed_evidence_sha256,
                        canonical_sequence_manifest_sha256,
                    )

                    evidence = canonical_completed_evidence_sha256(
                        db, job_id, (4,), allow_missing_assignments=False
                    )
                    manifest = canonical_sequence_manifest_sha256(db, job_id, 4)
                    command_ids = tuple(json.loads(commit["command_ids_json"]))
                    replay_commands = self._commands_with_release_by_ids_tx(
                        db, command_ids
                    )
                    all_commands = self._commands_with_release_for_operation_tx(
                        db, fence.operation_id
                    )
                    target = db.execute(
                        "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                        (fence.operation_id,),
                    ).fetchone()
                    media = db.execute(
                        "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                        (fence.operation_id,),
                    ).fetchone()
                    migration_receipts = db.execute(
                        "SELECT * FROM migration_receipts WHERE job_id=? ORDER BY id",
                        (job_id,),
                    ).fetchall()
                    authorizations = db.execute(
                        "SELECT * FROM cutover_authorizations "
                        "WHERE consumed_by_operation_id=? ORDER BY id",
                        (fence.operation_id,),
                    ).fetchall()
                    authorization = (
                        authorizations[0] if len(authorizations) == 1 else None
                    )
                    cassette = db.execute(
                        "SELECT * FROM automatic_cassettes "
                        "WHERE job_id=? AND sequence=4",
                        (job_id,),
                    ).fetchone()
                    command_evidence = self._postcommit_ledger_sha256(replay_commands)
                    authorization_evidence = self._cutover_authorization_evidence(
                        authorization, operation, target
                    )
                    terminal_sha256 = commit["terminal_sha256"]
                    terminal_receipt = (
                        None
                        if terminal_sha256 is None
                        else db.execute(
                            "SELECT terminal_sha256,observed_volume_label FROM "
                            "ltfs_terminal_receipts WHERE operation_id=? "
                            "AND owner_generation=?",
                            (fence.operation_id, original_generation),
                        ).fetchone()
                    )
                    if terminal_sha256 is not None and (
                        terminal_receipt is None
                        or terminal_receipt["terminal_sha256"] != terminal_sha256
                        or terminal_receipt["observed_volume_label"]
                        != cassette["physical_label"]
                    ):
                        raise ValidationError(failure)
                    binding = imported_cassette_commit_binding_sha256(
                        (
                            fence.operation_id,
                            original_generation,
                            job_id,
                            4,
                            tape_id,
                            block_ids,
                            manifest,
                            evidence,
                            media["observed_media_identity_sha256"],
                            *(() if terminal_sha256 is None else (terminal_sha256,)),
                            tuple(
                                target[field]
                                for field in (
                                    "mount_path_sha256",
                                    "tape_device_identity_sha256",
                                    "scsi_device_identity_sha256",
                                    "expected_media_scope_sha256",
                                )
                            ),
                            command_ids,
                            command_evidence,
                            authorization_evidence,
                            commit["committed_at"],
                        )
                    )
                except (
                    LookupError,
                    sqlite3.DatabaseError,
                    TypeError,
                    ValueError,
                ) as exc:
                    raise ValidationError(failure) from exc
                committed_time = self._parse_utc_timestamp(commit["committed_at"])
                frozen_id_set = set(command_ids)
                postcommit_commands = [
                    row for row in all_commands if row["id"] not in frozen_id_set
                ]
                command_ledger_invalid = (
                    committed_time is None
                    or len(frozen_id_set) != len(command_ids)
                    or len({row["id"] for row in all_commands}) != len(all_commands)
                    or tuple(row["id"] for row in replay_commands) != command_ids
                    or any(row["command_kind"] == "unload" for row in replay_commands)
                    or any(
                        not hardware_command_release_evidence_valid(
                            self._postcommit_command_tuple(row)
                        )
                        for row in all_commands
                    )
                )
                for command in postcommit_commands:
                    created = self._parse_utc_timestamp(command["created_at"])
                    if (
                        created is None
                        or not imported_postcommit_terminal_timeline_valid(
                            outcome=command["exit_outcome"],
                            created_at=command["created_at"],
                            released_at=command["released_at"],
                            exit_observed_at=command["exit_observed_at"],
                            quiesced_at=command["quiesced_at"],
                            process_identity=tuple(
                                command[field]
                                for field in (
                                    "boot_id",
                                    "pid",
                                    "process_start_ticks",
                                    "process_group_id",
                                )
                            ),
                            committed_at=commit["committed_at"],
                        )
                        or command["command_kind"] != "unload"
                        or command["state"] != "quiesced"
                        or command["exit_outcome"]
                        not in {"completed", "terminated", "launch_aborted"}
                        or command["issued_generation"] != fence.owner_generation
                        or command["observed_media_identity_sha256"]
                        != media["observed_media_identity_sha256"]
                        or any(
                            command[field] != target[field]
                            for field in (
                                "mount_path_sha256",
                                "tape_device_identity_sha256",
                                "scsi_device_identity_sha256",
                                "expected_media_scope_sha256",
                            )
                        )
                    ):
                        command_ledger_invalid = True
                        break
                migration = (
                    migration_receipts[0] if len(migration_receipts) == 1 else None
                )
                if (
                    len(replay_commands) != len(command_ids)
                    or command_ledger_invalid
                    or evidence != commit["evidence_sha256"]
                    or manifest != commit["manifest_sha256"]
                    or command_evidence != commit["command_evidence_sha256"]
                    or binding != commit["commit_binding_sha256"]
                    or authorization_evidence != commit["cutover_authorization_sha256"]
                    or migration is None
                    or migration["id"] != commit["migration_receipt_id"]
                    or migration["bundle_sha256"] != policy["bundle_sha256"]
                    or migration["assignment_sha256"] != policy["assignment_sha256"]
                    or migration["cassette_plan_sha256"]
                    != policy["cassette_plan_sha256"]
                    or migration["completed_evidence_sha256"]
                    != policy["completed_evidence_sha256"]
                    or authorization is None
                    or cassette is None
                    or authorization["id"] != commit["cutover_authorization_id"]
                    or authorization["job_id"] != job_id
                    or authorization["cassette_sequence"] != 4
                    or authorization["bundle_sha256"] != policy["bundle_sha256"]
                    or authorization["assignment_sha256"] != policy["assignment_sha256"]
                    or authorization["expected_label"] != cassette["physical_label"]
                    or authorization["peer_kind"] != "local_admin"
                    or authorization["drive_serial_sha256"]
                    != target["tape_device_identity_sha256"]
                    or authorization["catalog_binding_sha256"]
                    != cutover_catalog_binding_sha256(
                        job_id,
                        policy["bundle_sha256"],
                        policy["assignment_sha256"],
                        policy["cassette_plan_sha256"],
                        policy["completed_evidence_sha256"],
                        cassette["physical_label"],
                    )
                    or commit["observed_media_identity_sha256"]
                    != media["observed_media_identity_sha256"]
                    or any(
                        commit[field] != target[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                    or policy["activated_at"] != commit["committed_at"]
                ):
                    raise ValidationError(failure)
                try:
                    from .daemon.frozen_job import FrozenJobPlan

                    FrozenJobPlan._load(db, job_id)
                except (
                    LookupError,
                    RuntimeError,
                    sqlite3.DatabaseError,
                    TypeError,
                    ValueError,
                ) as exc:
                    raise ValidationError(failure) from exc
                policy_record = self._import_policy_from_row(policy)
                return policy_record
            if (
                policy is None
                or len(receipt_rows) != 1
                or policy["authority_state"] != "pre_cutover"
                or policy["windows_authority"] != "resumable"
                or policy["rollback_allowed"] != 1
                or policy["activated_by_operation"] is not None
                or policy["activated_at"] is not None
                or operation["phase"] != "committing"
            ):
                raise ValidationError(failure)

            job = db.execute(
                "SELECT * FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            cassettes = db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? ORDER BY sequence",
                (job_id,),
            ).fetchall()
            fourth = cassettes[3] if len(cassettes) >= 5 else None
            target = db.execute(
                "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            authorizations = db.execute(
                "SELECT * FROM cutover_authorizations WHERE consumed_by_operation_id=?",
                (fence.operation_id,),
            ).fetchall()
            media = db.execute(
                "SELECT * FROM operation_media_identity_bindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            commands = self._commands_with_release_for_operation_tx(
                db, fence.operation_id
            )
            blocks = db.execute(
                "SELECT * FROM blocks WHERE id IN ("
                + ",".join("?" for _ in block_ids)
                + ")",
                block_ids,
            ).fetchall()
            versions = db.execute(
                "SELECT * FROM file_versions WHERE block_id IN ("
                + ",".join("?" for _ in block_ids)
                + ") ORDER BY block_id, library_id, relative_path, id",
                block_ids,
            ).fetchall()
            tape = db.execute("SELECT * FROM tapes WHERE id=?", (tape_id,)).fetchone()
            authorization = authorizations[0] if len(authorizations) == 1 else None
            if (
                job is None
                or fourth is None
                or target is None
                or authorization is None
                or media is None
                or tape is None
                or len(blocks) != len(block_ids)
                or not commands
                or len({row["id"] for row in commands}) != len(commands)
                or fourth["status"] != "committing"
                or fourth["physical_label"] != tape["cassette_number"]
                or fourth["physical_label"] != tape["volume_label"]
                or fourth["tape_serial"] != tape["volume_serial"]
                or fourth["tape_id"].casefold() != tape_id.casefold()
                or tuple(value for value in str(fourth["block_id"]).split(",") if value)
                != block_ids
                or fourth["copied_files"] != fourth["planned_files"]
                or fourth["copied_bytes"] != fourth["planned_bytes"]
                or fourth["completed_at"] is not None
                or fourth["error"] is not None
                or job["current_sequence"] != 4
            ):
                raise ValidationError(failure)
            terminal_receipt = self._require_ltfs_terminal_receipt_tx(
                db,
                fence.operation_id,
                original_generation,
                job_id,
                4,
                fourth["physical_label"],
                media["observed_media_identity_sha256"],
            )
            receipt = receipt_rows[0]
            try:
                from .migration.validator import (
                    canonical_assignment_sha256,
                    canonical_cassette_plan_sha256,
                    canonical_completed_evidence_sha256,
                    canonical_sequence_manifest_sha256,
                )

                completed_prior = canonical_completed_evidence_sha256(
                    db, job_id, (1, 2, 3), allow_missing_assignments=True
                )
                assignment = canonical_assignment_sha256(db, job_id)
                cassette_plan = canonical_cassette_plan_sha256(
                    db, job_id, assignment_sha256=assignment
                )
                manifest = canonical_sequence_manifest_sha256(db, job_id, 4)
            except (LookupError, sqlite3.DatabaseError, TypeError, ValueError) as exc:
                raise ValidationError(failure) from exc
            if (
                completed_prior != policy["completed_evidence_sha256"]
                or assignment != policy["assignment_sha256"]
                or cassette_plan != policy["cassette_plan_sha256"]
                or receipt["completed_evidence_sha256"] != completed_prior
                or receipt["assignment_sha256"] != assignment
                or receipt["cassette_plan_sha256"] != cassette_plan
                or receipt["bundle_sha256"] != policy["bundle_sha256"]
            ):
                raise ValidationError(failure)

            operation_started = self._parse_utc_timestamp(operation["started_at"])
            target_bound = self._parse_utc_timestamp(target["bound_at"])
            authorization_created = self._parse_utc_timestamp(
                authorization["created_at"]
            )
            authorization_expires = self._parse_utc_timestamp(
                authorization["expires_at"]
            )
            authorization_consumed = self._parse_utc_timestamp(
                authorization["consumed_at"]
            )
            media_bound = self._parse_utc_timestamp(media["bound_at"])
            cassette_started = self._parse_utc_timestamp(fourth["started_at"])
            block_started_by_id = {
                row["id"]: self._parse_utc_timestamp(row["started_at"])
                for row in blocks
            }
            block_started = list(block_started_by_id.values())
            copied_by_block = [
                (row["block_id"], self._parse_utc_timestamp(row["copied_at"]))
                for row in versions
            ]
            copied_times = [value for _, value in copied_by_block]
            latest_copy = max(
                (value for value in copied_times if value is not None), default=None
            )
            terminal_recorded = self._parse_utc_timestamp(
                terminal_receipt["recorded_at"]
            )
            if (
                operation_started is None
                or target_bound is None
                or authorization_created is None
                or authorization_expires is None
                or authorization_consumed is None
                or media_bound is None
                or cassette_started is None
                or not versions
                or any(value is None for value in (*block_started, *copied_times))
                or latest_copy is None
                or terminal_recorded is None
                or terminal_recorded < latest_copy
                or not (
                    authorization_created
                    <= operation_started
                    <= target_bound
                    <= authorization_consumed
                    <= authorization_expires
                    and authorization_consumed <= media_bound <= cassette_started
                    and all(
                        cassette_started <= value <= terminal_recorded
                        for value in block_started
                    )
                    and all(
                        block_started_by_id[version_block] <= value <= terminal_recorded
                        for version_block, value in copied_by_block
                    )
                )
            ):
                raise ValidationError(failure)
            if (
                authorization["job_id"] != job_id
                or authorization["cassette_sequence"] != 4
                or authorization["expected_label"] != fourth["physical_label"]
                or authorization["bundle_sha256"] != policy["bundle_sha256"]
                or authorization["assignment_sha256"] != assignment
                or authorization["drive_serial_sha256"]
                != target["tape_device_identity_sha256"]
                or target["expected_media_scope_sha256"]
                != expected_media_scope_sha256(
                    (
                        "archive.resume",
                        job_id,
                        "4",
                        fourth["physical_label"],
                        "",
                        "",
                    )
                )
                or authorization["catalog_binding_sha256"]
                != cutover_catalog_binding_sha256(
                    job_id,
                    policy["bundle_sha256"],
                    assignment,
                    policy["cassette_plan_sha256"],
                    completed_prior,
                    fourth["physical_label"],
                )
            ):
                raise ValidationError(failure)

            command_payload = []
            bound_index = next(
                (
                    index
                    for index, row in enumerate(commands)
                    if row["id"] == media["bound_by_command_id"]
                ),
                None,
            )
            format_rebind = db.execute(
                "SELECT * FROM format_media_rebindings WHERE operation_id=?",
                (fence.operation_id,),
            ).fetchone()
            pre_bound_index = (
                None
                if format_rebind is None
                else next(
                    (
                        index
                        for index, row in enumerate(commands)
                        if row["id"] == format_rebind["pre_probe_media_command_id"]
                    ),
                    None,
                )
            )
            command_kinds = tuple(row["command_kind"] for row in commands)
            ledger_shape_valid = bool(
                pre_bound_index is not None
                and imported_media_ledger_shape_valid(
                    command_kinds,
                    operation="format",
                    pre_bound_probe_index=pre_bound_index,
                    bound_probe_index=bound_index,
                )
                and (
                    commands[pre_bound_index + 2]["id"]
                    == format_rebind["format_command_id"]
                    or commands[pre_bound_index + 3]["id"]
                    == format_rebind["format_command_id"]
                )
                and commands[bound_index]["id"]
                == format_rebind["post_probe_media_command_id"]
                and format_rebind["owner_generation"] == original_generation
                and format_rebind["expected_label"] == fourth["physical_label"]
                and format_rebind["observed_label"] == fourth["physical_label"]
                and format_rebind["expected_serial"] == format_rebind["observed_serial"]
                and format_rebind["post_media_identity_sha256"]
                == media["observed_media_identity_sha256"]
            )
            if not ledger_shape_valid:
                raise ValidationError(failure)
            for index, command in enumerate(commands):
                created = self._parse_utc_timestamp(command["created_at"])
                released = self._parse_utc_timestamp(command["released_at"])
                exited = self._parse_utc_timestamp(command["exit_observed_at"])
                quiesced = self._parse_utc_timestamp(command["quiesced_at"])
                if (
                    command["issued_generation"] != original_generation
                    or command["command_kind"] == "unload"
                    or command["state"] != "quiesced"
                    or command["exit_outcome"] != "completed"
                    or not hardware_command_release_evidence_valid(
                        self._postcommit_command_tuple(command)
                    )
                    or any(
                        command[field] != target[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    )
                    or created is None
                    or released is None
                    or exited is None
                    or quiesced is None
                    or not (
                        operation_started
                        <= created
                        <= released
                        <= exited
                        <= quiesced
                        <= terminal_recorded
                    )
                ):
                    raise ValidationError(failure)
                expected_observed = (
                    None
                    if index <= pre_bound_index
                    else format_rebind["pre_media_identity_sha256"]
                    if index <= bound_index
                    else media["observed_media_identity_sha256"]
                )
                if command["observed_media_identity_sha256"] != expected_observed:
                    raise ValidationError(failure)
                command_payload.append(self._postcommit_command_tuple(command))
            if (
                self._parse_utc_timestamp(commands[bound_index]["quiesced_at"])
                > media_bound
                or any(
                    self._parse_utc_timestamp(row["created_at"]) < media_bound
                    for row in commands[bound_index + 1 :]
                )
                or self._parse_utc_timestamp(commands[-1]["created_at"])
                > min(copied_times)
            ):
                raise ValidationError(failure)
            if any(
                row["status"] != "copying"
                or row["visible"] != 0
                or row["tape_id"].casefold() != tape_id.casefold()
                or row["completed_at"] is not None
                or row["error"] is not None
                for row in blocks
            ) or any(
                row["visible"] != 0 or row["tape_id"].casefold() != tape_id.casefold()
                for row in versions
            ):
                raise ValidationError(failure)

            committed_at = self._precise_utc_now(after=terminal_receipt["recorded_at"])
            db.execute(
                "UPDATE blocks SET status='completed', visible=1, completed_at=?, error=NULL "
                "WHERE id IN (" + ",".join("?" for _ in block_ids) + ")",
                (committed_at, *block_ids),
            )
            db.execute(
                "UPDATE file_versions SET visible=1 WHERE block_id IN ("
                + ",".join("?" for _ in block_ids)
                + ")",
                block_ids,
            )
            db.execute(
                "UPDATE automatic_cassettes SET status='completed', completed_at=?, error=NULL "
                "WHERE job_id=? AND sequence=4",
                (committed_at, job_id),
            )
            db.execute(
                "UPDATE automatic_jobs SET status='waiting_media', current_sequence=5, "
                "last_error=NULL WHERE id=?",
                (job_id,),
            )
            try:
                evidence = canonical_completed_evidence_sha256(
                    db, job_id, (4,), allow_missing_assignments=False
                )
            except (LookupError, sqlite3.DatabaseError, TypeError, ValueError) as exc:
                raise ValidationError(failure) from exc
            command_ids = tuple(row["id"] for row in commands)
            command_evidence = imported_postcommit_command_sha256(
                tuple(command_payload)
            )
            authorization_evidence = self._cutover_authorization_evidence(
                authorization, operation, target
            )
            binding = imported_cassette_commit_binding_sha256(
                (
                    fence.operation_id,
                    original_generation,
                    job_id,
                    4,
                    tape_id,
                    block_ids,
                    manifest,
                    evidence,
                    media["observed_media_identity_sha256"],
                    terminal_receipt["terminal_sha256"],
                    tuple(
                        target[field]
                        for field in (
                            "mount_path_sha256",
                            "tape_device_identity_sha256",
                            "scsi_device_identity_sha256",
                            "expected_media_scope_sha256",
                        )
                    ),
                    command_ids,
                    command_evidence,
                    authorization_evidence,
                    committed_at,
                )
            )
            db.execute(
                "INSERT INTO imported_cassette_commit_receipts("
                "job_id, sequence, operation_id, owner_generation, migration_receipt_id, "
                "cutover_authorization_id, cutover_authorization_sha256, evidence_sha256, "
                "manifest_sha256, tape_id, "
                "block_ids_json, command_ids_json, command_evidence_sha256, "
                "commit_binding_sha256, observed_media_identity_sha256, "
                "mount_path_sha256, tape_device_identity_sha256, "
                "scsi_device_identity_sha256, expected_media_scope_sha256, "
                "terminal_sha256, committed_at) "
                "VALUES(?, 4, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    job_id,
                    fence.operation_id,
                    original_generation,
                    receipt["id"],
                    authorization["id"],
                    authorization_evidence,
                    evidence,
                    manifest,
                    tape_id,
                    json.dumps(block_ids, separators=(",", ":")),
                    json.dumps(command_ids, separators=(",", ":")),
                    command_evidence,
                    binding,
                    media["observed_media_identity_sha256"],
                    target["mount_path_sha256"],
                    target["tape_device_identity_sha256"],
                    target["scsi_device_identity_sha256"],
                    target["expected_media_scope_sha256"],
                    terminal_receipt["terminal_sha256"],
                    committed_at,
                ),
            )
            updated = db.execute(
                "UPDATE imported_job_policies SET authority_state='active_linux', "
                "windows_authority='historical_read_only', rollback_allowed=0, "
                "activated_by_operation=?, activated_at=? WHERE job_id=? "
                "AND authority_state='pre_cutover' AND activated_at IS NULL",
                (fence.operation_id, committed_at, job_id),
            )
            if updated.rowcount != 1:
                raise ValidationError(failure)
            db.execute(
                "UPDATE daemon_operations SET phase='unloading' WHERE id=?",
                (fence.operation_id,),
            )

        policy_record = self.get_import_policy(job_id)
        if policy_record is None:
            raise ValidationError(failure)
        return policy_record

    def activate_imported_job_authority(
        self, job_id: str, operation_id: str
    ) -> ImportedJobPolicy:
        """Reject the retired post-hoc activation path."""

        validate_id(job_id, "job ID")
        self._validate_safe_identifier(operation_id, "operation ID")
        raise ValidationError(
            "imported authority must be activated by the fenced cassette commit"
        )

    def remap_imported_job_paths(
        self,
        job_id: str,
        library_roots: Mapping[str, str],
        device_name: str,
        mount_path: str,
    ) -> None:
        """Apply the importer's already-validated platform-only path changes."""

        validate_id(job_id, "job ID")
        if not library_roots or any(
            not isinstance(library_id, str)
            or not isinstance(source_root, str)
            or not Path(source_root).is_absolute()
            for library_id, source_root in library_roots.items()
        ):
            raise ValidationError("invalid imported library roots")
        if (
            not isinstance(device_name, str)
            or not Path(device_name).is_absolute()
            or not isinstance(mount_path, str)
            or not Path(mount_path).is_absolute()
        ):
            raise ValidationError("invalid imported job paths")
        with self.transaction() as db:
            job = db.execute(
                "SELECT id FROM automatic_jobs WHERE id=?", (job_id,)
            ).fetchone()
            assigned = {
                row[0]
                for row in db.execute(
                    "SELECT library_id FROM automatic_job_libraries WHERE job_id=?",
                    (job_id,),
                )
            }
            if job is None or set(library_roots) != assigned:
                raise CatalogError("imported path mapping does not match the job")
            db.executemany(
                "UPDATE libraries SET source_root=? WHERE id=?",
                [
                    (source_root, library_id)
                    for library_id, source_root in library_roots.items()
                ],
            )
            db.execute(
                "UPDATE automatic_jobs SET device_name=?, mount_path=? WHERE id=?",
                (device_name, mount_path, job_id),
            )

    def get_import_policy(self, job_id: str) -> ImportedJobPolicy | None:
        row = self.connection.execute(
            "SELECT * FROM imported_job_policies WHERE job_id=?", (job_id,)
        ).fetchone()
        if row is None:
            return None
        return self._import_policy_from_row(row)

    @staticmethod
    def _import_policy_from_row(row: sqlite3.Row) -> ImportedJobPolicy:
        return ImportedJobPolicy(
            job_id=row["job_id"],
            policy_kind=row["policy_kind"],
            assignment_sha256=row["assignment_sha256"],
            cassette_plan_sha256=row["cassette_plan_sha256"],
            completed_evidence_sha256=row["completed_evidence_sha256"],
            bundle_sha256=row["bundle_sha256"],
            authority_state=row["authority_state"],
            windows_authority=row["windows_authority"],
            rollback_allowed=bool(row["rollback_allowed"]),
            frozen_at=row["frozen_at"],
            activated_by_operation=row["activated_by_operation"],
            activated_at=row["activated_at"],
        )

    @staticmethod
    def _operation_from_row(row: sqlite3.Row) -> OperationRecord:
        return OperationRecord(
            id=row["id"],
            kind=row["kind"],
            state=row["state"],
            phase=row["phase"],
            idempotency_key=row["idempotency_key"],
            principal=row["principal"],
            job_id=row["job_id"],
            cassette_sequence=row["cassette_sequence"],
            started_at=row["started_at"],
            finished_at=row["finished_at"],
            error_class=row["error_class"],
            error_code=row["error_code"],
            error_message=row["error_message"],
        )

    @staticmethod
    def _target_from_row(row: sqlite3.Row | None) -> HardwareTargetBinding | None:
        if row is None:
            return None
        return HardwareTargetBinding(
            mount_path_sha256=row["mount_path_sha256"],
            tape_device_identity_sha256=row["tape_device_identity_sha256"],
            scsi_device_identity_sha256=row["scsi_device_identity_sha256"],
            expected_media_scope_sha256=row["expected_media_scope_sha256"],
        )

    @classmethod
    def _hardware_command_from_row(cls, row: sqlite3.Row) -> HardwareCommandExecution:
        state = row["state"]
        if state == "launch_blocked" and row["release_status"] in {
            "authorized",
            "ambiguous",
        }:
            state = "release_authorized"
        return HardwareCommandExecution(
            id=row["id"],
            operation_id=row["operation_id"],
            issued_generation=row["issued_generation"],
            kind=row["command_kind"],
            argv_sha256=row["argv_sha256"],
            target=cls._target_from_row(row),
            observed_media_identity_sha256=row["observed_media_identity_sha256"],
            state=state,
            process=cls._process_from_command_row(row),
            exit_outcome=row["exit_outcome"],
            created_at=row["created_at"],
            release_permit_sha256=row["release_permit_sha256"],
            release_status=row["release_status"],
            release_authorized_at=row["release_authorized_at"],
            release_confirmed_at=row["release_confirmed_at"],
            released_at=row["released_at"],
            exit_observed_at=row["exit_observed_at"],
            quiesced_at=row["quiesced_at"],
            terminal_exit_code=row["terminal_exit_code"],
        )

    @staticmethod
    def _process_from_command_row(row: sqlite3.Row) -> ProcessIdentity | None:
        if row["boot_id"] is None:
            return None
        return ProcessIdentity(
            row["boot_id"],
            row["pid"],
            row["process_start_ticks"],
            row["process_group_id"],
        )

    def _assert_daemon_fence_tx(
        self, db: sqlite3.Connection, fence: DaemonFence
    ) -> None:
        row = db.execute(
            "SELECT owner_id, generation FROM daemon_ownership WHERE singleton=1"
        ).fetchone()
        if (
            row is None
            or row["owner_id"] != fence.owner_id
            or row["generation"] != fence.generation
        ):
            raise StaleDaemonFence("daemon catalog ownership has changed")

    def _assert_operation_fence_tx(
        self, db: sqlite3.Connection, fence: OperationFence
    ) -> sqlite3.Row:
        owner = db.execute(
            "SELECT generation FROM daemon_ownership WHERE singleton=1"
        ).fetchone()
        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (fence.operation_id,)
        ).fetchone()
        if (
            owner is None
            or owner["generation"] != fence.owner_generation
            or operation is None
            or operation["owner_generation"] != fence.owner_generation
            or operation["state"] != "running"
        ):
            raise StaleOperationFence("operation fence is no longer current")
        return operation

    def _assert_command_fence_tx(
        self,
        db: sqlite3.Connection,
        fence: OperationFence | RecoveryCommandFence,
    ) -> sqlite3.Row:
        if isinstance(fence, OperationFence):
            return self._assert_operation_fence_tx(db, fence)
        owner = db.execute(
            "SELECT generation FROM daemon_ownership WHERE singleton=1"
        ).fetchone()
        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?", (fence.operation_id,)
        ).fetchone()
        if (
            owner is None
            or owner["generation"] != fence.owner_generation
            or operation is None
            or operation["state"] != "recovery_required"
        ):
            raise StaleOperationFence("recovery command fence is no longer current")
        return operation

    @staticmethod
    def _command_for_fence_tx(
        db: sqlite3.Connection,
        command_id: str,
        fence: OperationFence | RecoveryCommandFence,
    ) -> sqlite3.Row:
        row = Catalog._command_with_release_tx(db, command_id)
        if row is None or row["operation_id"] != fence.operation_id:
            raise CatalogError("hardware command does not belong to operation")
        return row

    @staticmethod
    def _command_with_release_tx(
        db: sqlite3.Connection, command_id: str
    ) -> sqlite3.Row | None:
        rows = db.execute(
            """
            SELECT command.*,
                   authorization.permit_sha256 AS release_permit_sha256,
                   authorization.release_status AS release_status,
                   authorization.authorized_at AS release_authorized_at,
                   authorization.confirmed_at AS release_confirmed_at
            FROM hardware_command_executions command
            LEFT JOIN hardware_command_release_authorizations authorization
              ON authorization.command_id=command.id
            WHERE command.id=?
            """,
            (command_id,),
        ).fetchall()
        if len(rows) > 1:
            raise CatalogError("hardware command has duplicate release evidence")
        return None if not rows else rows[0]

    @staticmethod
    def _insert_hardware_target(
        db: sqlite3.Connection,
        operation_id: str,
        target: HardwareTargetBinding,
        bound_at: str,
    ) -> None:
        db.execute(
            """
            INSERT INTO operation_hardware_targets(
                operation_id, mount_path_sha256, tape_device_identity_sha256,
                scsi_device_identity_sha256, expected_media_scope_sha256,
                bound_at
            ) VALUES(?, ?, ?, ?, ?, ?)
            """,
            (operation_id, *Catalog._target_values(target), bound_at),
        )

    def _find_operation_by_key_tx(
        self, db: sqlite3.Connection, idempotency_key: str
    ) -> sqlite3.Row | None:
        return db.execute(
            "SELECT * FROM daemon_operations WHERE idempotency_key=?",
            (idempotency_key,),
        ).fetchone()

    def _find_sequence_continuation_by_key_tx(
        self,
        db: sqlite3.Connection, idempotency_key: str
    ) -> sqlite3.Row | None:
        binding = db.execute(
            "SELECT operation_id FROM operation_sequence_continuations "
            "WHERE continuation_idempotency_key=?",
            (idempotency_key,),
        ).fetchone()
        if binding is None:
            return None
        operation = db.execute(
            "SELECT * FROM daemon_operations WHERE id=?",
            (binding["operation_id"],),
        ).fetchone()
        if operation is None:
            raise self._sequence_continuation_conflict()
        return operation

    @staticmethod
    def _insert_daemon_operation_tx(
        db: sqlite3.Connection,
        candidate: OperationRecord,
        owner_generation: int,
        admitted_copy_buffer: int | None,
        admitted_at: str,
    ) -> None:
        try:
            db.execute(
                """
                INSERT INTO daemon_operations(
                    id, kind, state, phase, idempotency_key, principal,
                    owner_generation, job_id, cassette_sequence, started_at,
                    finished_at, error_class, error_code, error_message,
                    copy_buffer_bytes
                ) VALUES(?, ?, 'running', ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NULL, NULL, ?)
                """,
                (
                    candidate.id,
                    candidate.kind,
                    candidate.phase,
                    candidate.idempotency_key,
                    candidate.principal,
                    owner_generation,
                    candidate.job_id,
                    candidate.cassette_sequence,
                    candidate.started_at or admitted_at,
                    admitted_copy_buffer,
                ),
            )
        except sqlite3.IntegrityError as exc:
            if (
                getattr(exc, "sqlite_errorcode", None)
                == sqlite3.SQLITE_CONSTRAINT_UNIQUE
                and "daemon_operations.idempotency_key" in str(exc)
            ):
                raise _OperationIdempotencyInsertRace() from exc
            raise

    @staticmethod
    def _target_values(target: HardwareTargetBinding | None) -> tuple:
        if target is None:
            return (None, None, None, None)
        return (
            target.mount_path_sha256,
            target.tape_device_identity_sha256,
            target.scsi_device_identity_sha256,
            target.expected_media_scope_sha256,
        )

    @staticmethod
    def _validate_candidate(candidate: OperationRecord) -> None:
        if candidate.state != "running" or candidate.finished_at is not None:
            raise ValidationError(
                "new operation candidate must be running and unfinished"
            )
        for value, name in (
            (candidate.id, "operation id"),
            (candidate.kind, "operation kind"),
            (candidate.idempotency_key, "idempotency key"),
            (candidate.principal, "principal"),
        ):
            Catalog._validate_safe_identifier(value, name)
        if candidate.phase is not None and candidate.phase not in _OPERATION_PHASES:
            raise ValidationError("invalid initial operation phase")
        if candidate.error_class or candidate.error_code or candidate.error_message:
            raise ValidationError("new operation candidate cannot contain an error")

    @staticmethod
    def _validate_recovery_attempt_identity(
        operation_id: object,
        attempt_number: object,
        *,
        trigger: object | None,
        evidence_sha256: object,
        decision: object,
        recorded_at: object,
    ) -> None:
        Catalog._validate_safe_identifier(operation_id, "recovery operation id")
        if (
            type(attempt_number) is not int
            or attempt_number <= 0
            or attempt_number >= 1 << 31
        ):
            raise ValidationError("invalid recovery attempt number")
        if trigger is not None:
            Catalog._validate_safe_identifier(trigger, "recovery trigger")
        Catalog._validate_sha256(evidence_sha256, "recovery evidence digest")
        if decision not in _RECOVERY_ATTEMPT_DECISIONS:
            raise ValidationError("invalid recovery decision")
        if (
            not isinstance(recorded_at, str)
            or len(recorded_at) > 64
            or Catalog._parse_utc_timestamp(recorded_at) is None
        ):
            raise ValidationError("invalid recovery attempt timestamp")

    @staticmethod
    def _requires_hardware_target(candidate: OperationRecord) -> bool:
        return candidate.cassette_sequence is not None and candidate.kind.startswith(
            ("archive.", "restore.", "tape.")
        )

    @staticmethod
    def _validate_safe_identifier(value: object, name: str) -> None:
        if not isinstance(value, str) or not _SAFE_IDENTIFIER.fullmatch(value):
            raise ValidationError(f"invalid {name}")

    @staticmethod
    def _validate_sha256(value: object, name: str) -> None:
        if not isinstance(value, str) or not _SHA256.fullmatch(value):
            raise ValidationError(f"invalid {name}")

    @staticmethod
    def _parse_utc_timestamp(value: object) -> datetime | None:
        if not isinstance(value, str) or not value:
            return None
        try:
            parsed = datetime.fromisoformat(value)
        except ValueError:
            return None
        if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
            return None
        return parsed

    @classmethod
    def _catalog_activation_state_invalid(cls, job, cassettes) -> bool:
        """Validate only catalog evidence; never inspect prior physical media."""

        if (
            type(job["total_cassettes"]) is not int
            or job["total_cassettes"] < 5
            or len(cassettes) != job["total_cassettes"]
            or job["status"] not in {"paused", "waiting_media"}
            or job["current_sequence"] != 5
            or tuple(row["sequence"] for row in cassettes)
            != tuple(range(1, len(cassettes) + 1))
        ):
            return True

        def completed(row) -> bool:
            started_at = cls._parse_utc_timestamp(row["started_at"])
            completed_at = cls._parse_utc_timestamp(row["completed_at"])
            return bool(
                row["status"] == "completed"
                and isinstance(row["tape_id"], str)
                and row["tape_id"]
                and isinstance(row["block_id"], str)
                and row["block_id"]
                and type(row["planned_files"]) is int
                and type(row["planned_bytes"]) is int
                and row["copied_files"] == row["planned_files"]
                and row["copied_bytes"] == row["planned_bytes"]
                and started_at is not None
                and completed_at is not None
                and started_at <= completed_at
                and row["error"] is None
            )

        def untouched(row, *, current: bool) -> bool:
            allowed_status = {"pending", "waiting_media"} if current else {"pending"}
            return bool(
                row["status"] in allowed_status
                and row["tape_id"] is None
                and row["block_id"] is None
                and row["copied_files"] == 0
                and row["copied_bytes"] == 0
                and row["started_at"] is None
                and row["completed_at"] is None
                and row["error"] is None
                and row["reuse_registered"] == 0
            )

        return bool(
            any(not completed(row) for row in cassettes[:4])
            or not untouched(cassettes[4], current=True)
            or any(not untouched(row, current=False) for row in cassettes[5:])
        )

    @staticmethod
    def _validate_portable_relative_path(value: object, name: str) -> None:
        if not isinstance(value, str) or not value or "\\" in value or "\x00" in value:
            raise ValidationError(f"invalid {name}")
        path = PurePosixPath(value)
        windows_path = PureWindowsPath(value)
        if (
            path.is_absolute()
            or windows_path.is_absolute()
            or windows_path.drive
            or windows_path.root
            or not path.parts
            or path.as_posix() != value
            or any(
                part in ("", ".", "..")
                or ":" in part
                or part.rstrip(". ") != part
                or part.split(".", 1)[0].upper()
                in {
                    "CON",
                    "PRN",
                    "AUX",
                    "NUL",
                    *{f"COM{number}" for number in range(1, 10)},
                    *{f"LPT{number}" for number in range(1, 10)},
                }
                for part in path.parts
            )
        ):
            raise ValidationError(f"invalid {name}")

    @staticmethod
    def _validate_process_identity(identity: ProcessIdentity) -> None:
        if not isinstance(identity.boot_id, str) or not identity.boot_id:
            raise ValidationError("invalid process boot identity")
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value <= 0
            for value in (identity.pid, identity.start_ticks, identity.process_group_id)
        ):
            raise ValidationError("invalid process identity")

    @staticmethod
    def _safe_error_message(
        error_code: str | None, supplied_message: str | None
    ) -> str | None:
        if error_code is None:
            return None
        if error_code not in _SAFE_ERROR_MESSAGES:
            raise ValidationError("operation error code is not allowlisted")
        return _SAFE_ERROR_MESSAGES[error_code]

    @staticmethod
    def _redact_audit_value(value: object, key: str | None = None) -> object:
        if key is not None:
            normalized = re.sub(r"[^a-z0-9]+", "_", key.casefold()).strip("_")
            suffixes = ("password", "cookie", "token", "secret", "credential")
            if (
                normalized in {"authorization", "smb_username"}
                or normalized.replace("_", "") == "smbusername"
                or normalized.endswith(suffixes)
            ):
                return "[REDACTED]"
        if isinstance(value, dict):
            return {
                str(item_key): Catalog._redact_audit_value(item_value, str(item_key))
                for item_key, item_value in value.items()
            }
        if isinstance(value, (list, tuple)):
            return [Catalog._redact_audit_value(item) for item in value]
        return value

    @staticmethod
    def _record_audit_tx(
        db: sqlite3.Connection,
        principal: str,
        action: str,
        result: str,
        request_id: str,
        remote_address: str | None,
        encoded_payload: str,
    ) -> None:
        db.execute(
            """
            INSERT INTO audit_entries(
                recorded_at, principal, action, result, request_id,
                remote_address, payload_json
            ) VALUES(?, ?, ?, ?, ?, ?, ?)
            """,
            (
                Catalog._precise_utc_now(),
                principal,
                action,
                result,
                request_id,
                remote_address,
                encoded_payload,
            ),
        )

    def _consume_cutover_authorization_tx(
        self,
        db: sqlite3.Connection,
        candidate: OperationRecord,
        authorization_value: str | None,
        now: str,
        *,
        caller_peer_kind: str | None,
        current_host_id: str | None,
    ) -> str | None:
        authority = db.execute(
            "SELECT authority_state FROM imported_job_policies WHERE job_id=?",
            (candidate.job_id,),
        ).fetchone()
        requires_cutover_authorization = (
            candidate.kind == "archive.resume"
            and candidate.cassette_sequence == 4
            and authority is not None
            and authority["authority_state"] == "pre_cutover"
        )
        if requires_cutover_authorization and (
            caller_peer_kind != "local_admin" or current_host_id is None
        ):
            raise CutoverAuthorizationInvalid()
        if authorization_value is None:
            if requires_cutover_authorization:
                raise CutoverAuthorizationInvalid()
            return None
        credential_sha256 = hashlib.sha256(
            authorization_value.encode("utf-8")
        ).hexdigest()
        authorization = db.execute(
            """
            SELECT * FROM cutover_authorizations WHERE credential_sha256=?
            """,
            (credential_sha256,),
        ).fetchone()
        authorization_expiry = (
            None
            if authorization is None
            else self._parse_utc_timestamp(authorization["expires_at"])
        )
        current_time = self._parse_utc_timestamp(now)
        if (
            authorization is None
            or authorization["consumed_at"] is not None
            or authorization_expiry is None
            or current_time is None
            or authorization_expiry <= current_time
            or authorization["peer_kind"] != "local_admin"
            or caller_peer_kind != authorization["peer_kind"]
            or current_host_id != authorization["host_id"]
            or authorization["job_id"] != candidate.job_id
            or authorization["cassette_sequence"] != candidate.cassette_sequence
        ):
            raise CutoverAuthorizationInvalid()
        policy = db.execute(
            "SELECT * FROM imported_job_policies WHERE job_id=?",
            (candidate.job_id,),
        ).fetchone()
        cassette = db.execute(
            "SELECT physical_label FROM automatic_cassettes "
            "WHERE job_id=? AND sequence=?",
            (candidate.job_id, candidate.cassette_sequence),
        ).fetchone()
        target = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (candidate.id,),
        ).fetchone()
        if (
            policy is None
            or cassette is None
            or target is None
            or policy["authority_state"] != "pre_cutover"
            or policy["assignment_sha256"] != authorization["assignment_sha256"]
            or policy["bundle_sha256"] != authorization["bundle_sha256"]
            or authorization["expected_label"] != cassette["physical_label"]
            or authorization["drive_serial_sha256"]
            != target["tape_device_identity_sha256"]
            or target["expected_media_scope_sha256"]
            != expected_media_scope_sha256(
                (
                    candidate.kind,
                    candidate.job_id,
                    str(candidate.cassette_sequence),
                    cassette["physical_label"],
                    "",
                    "",
                )
            )
            or authorization["catalog_binding_sha256"]
            != cutover_catalog_binding_sha256(
                candidate.job_id,
                policy["bundle_sha256"],
                policy["assignment_sha256"],
                policy["cassette_plan_sha256"],
                policy["completed_evidence_sha256"],
                cassette["physical_label"],
            )
        ):
            raise CutoverAuthorizationInvalid()
        db.execute(
            """
            UPDATE cutover_authorizations
            SET consumed_at=?, consumed_by_operation_id=? WHERE id=?
            """,
            (now, candidate.id, authorization["id"]),
        )
        return authorization["expected_label"]

    def _record_format_confirmation_tx(
        self,
        db: sqlite3.Connection,
        candidate: OperationRecord,
        label: str,
        authorized_label: str | None,
        now: str,
    ) -> None:
        if candidate.job_id is None or candidate.cassette_sequence is None:
            raise ValidationError(
                "format confirmation requires job and cassette coordinates"
            )
        expected_label = authorized_label
        if expected_label is None:
            row = db.execute(
                """
                SELECT physical_label FROM automatic_cassettes
                WHERE job_id=? AND sequence=?
                """,
                (candidate.job_id, candidate.cassette_sequence),
            ).fetchone()
            expected_label = None if row is None else row["physical_label"]
        if expected_label is None or label != expected_label:
            raise ValidationError(
                "format confirmation does not match the expected label"
            )
        db.execute(
            """
            INSERT INTO format_confirmations(
                operation_id, job_id, cassette_sequence, expected_label,
                confirmed_by, confirmed_at
            ) VALUES(?, ?, ?, ?, ?, ?)
            """,
            (
                candidate.id,
                candidate.job_id,
                candidate.cassette_sequence,
                expected_label,
                candidate.principal,
                now,
            ),
        )

    def _assert_sequence_continuation_layout_tx(
        self,
        db: sqlite3.Connection,
        candidate: OperationRecord,
        layout_fingerprint_sha256: str,
    ) -> _SequenceContinuationLayout:
        """Fence automatic continuation to its exact current durable layout."""

        self._validate_sha256(
            layout_fingerprint_sha256, "sequence continuation layout fingerprint"
        )
        if (
            candidate.kind != "archive.native"
            or candidate.job_id is None
            or candidate.cassette_sequence is None
        ):
            raise ValidationError("sequence continuation is not cassette-bound")
        state = db.execute(
            "SELECT state,layout_epoch,layout_fingerprint_sha256 FROM automatic_sequence_state "
            "WHERE job_id=?",
            (candidate.job_id,),
        ).fetchone()
        latest = db.execute(
            "SELECT epoch_number,layout_fingerprint_sha256 FROM job_layout_epochs "
            "WHERE job_id=? ORDER BY epoch_number DESC LIMIT 1",
            (candidate.job_id,),
        ).fetchone()
        job = db.execute(
            "SELECT status,current_sequence FROM automatic_jobs WHERE id=?",
            (candidate.job_id,),
        ).fetchone()
        cassette = db.execute(
            "SELECT status,planned_files,planned_bytes,operation "
            "FROM automatic_cassettes "
            "WHERE job_id=? AND sequence=?",
            (candidate.job_id, candidate.cassette_sequence),
        ).fetchone()
        imported = db.execute(
            "SELECT 1 FROM imported_job_policies WHERE job_id=?", (candidate.job_id,)
        ).fetchone()
        if (
            state is None
            or latest is None
            or job is None
            or cassette is None
            or imported is not None
            or state["state"] != "enabled"
            or job["status"] != "waiting_media"
            or int(job["current_sequence"]) != candidate.cassette_sequence
            or cassette["status"] not in {"pending", "waiting_media"}
            or (int(cassette["planned_files"]) <= 0 and int(cassette["planned_bytes"]) <= 0)
            or state["layout_epoch"] != latest["epoch_number"]
            or state["layout_fingerprint_sha256"] != layout_fingerprint_sha256
            or latest["layout_fingerprint_sha256"] != layout_fingerprint_sha256
        ):
            raise ValidationError("sequence continuation layout is not current")
        operation = str(cassette["operation"])
        if operation not in {"append", "format"}:
            raise ValidationError("sequence continuation operation is unsupported")
        return _SequenceContinuationLayout(
            job_id=str(candidate.job_id),
            cassette_sequence=int(candidate.cassette_sequence),
            layout_epoch=int(state["layout_epoch"]),
            layout_fingerprint_sha256=str(layout_fingerprint_sha256),
            cassette_operation=operation,
        )

    @staticmethod
    def _sequence_continuation_conflict() -> CatalogError:
        return CatalogError("idempotency_conflict")

    def _load_exact_sequence_continuation_tx(
        self,
        db: sqlite3.Connection,
        operation: sqlite3.Row,
        candidate: OperationRecord,
        supplied_fingerprint: str | None,
        supplied_authority_id: str | None,
        supplied_target: HardwareTargetBinding | None,
    ) -> _SequenceContinuationProvenance:
        """Load and compare only immutable relational continuation authority."""

        binding = db.execute(
            "SELECT * FROM operation_sequence_continuations WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        target_row = db.execute(
            "SELECT * FROM operation_hardware_targets WHERE operation_id=?",
            (operation["id"],),
        ).fetchone()
        if binding is None or target_row is None or supplied_target is None:
            raise self._sequence_continuation_conflict()
        try:
            operation_id = str(operation["id"])
            job_id = str(binding["job_id"])
            cassette_sequence = int(binding["cassette_sequence"])
            layout_epoch = int(binding["layout_epoch"])
            fingerprint = str(binding["layout_fingerprint_sha256"])
            continuation_key = str(binding["continuation_idempotency_key"])
            owner_generation = int(operation["owner_generation"])
            persisted_target = HardwareTargetBinding(
                mount_path_sha256=str(target_row["mount_path_sha256"]),
                tape_device_identity_sha256=str(
                    target_row["tape_device_identity_sha256"]
                ),
                scsi_device_identity_sha256=str(
                    target_row["scsi_device_identity_sha256"]
                ),
                expected_media_scope_sha256=str(
                    target_row["expected_media_scope_sha256"]
                ),
            )
        except (TypeError, ValueError):
            raise self._sequence_continuation_conflict() from None
        if (
            operation_id != str(binding["operation_id"])
            or operation["kind"] != "archive.native"
            or operation["principal"] != "sequence-coordinator"
            or operation["job_id"] != job_id
            or operation["cassette_sequence"] != cassette_sequence
            or operation["idempotency_key"] != continuation_key
            or owner_generation <= 0
            or layout_epoch <= 0
            or _SHA256.fullmatch(fingerprint) is None
            or self._parse_utc_timestamp(binding["linked_at"]) is None
            or self._parse_utc_timestamp(target_row["bound_at"]) is None
            or candidate.kind != "archive.native"
            or candidate.principal != "sequence-coordinator"
            or candidate.job_id != job_id
            or candidate.cassette_sequence != cassette_sequence
            or candidate.idempotency_key != continuation_key
            or supplied_fingerprint != fingerprint
            or persisted_target != supplied_target
            or sequence_continuation_idempotency_key(
                job_id,
                fingerprint,
                cassette_sequence,
                owner_generation,
            )
            != continuation_key
        ):
            raise self._sequence_continuation_conflict()

        epoch = db.execute(
            "SELECT layout_fingerprint_sha256 FROM job_layout_epochs "
            "WHERE job_id=? AND epoch_number=?",
            (job_id, layout_epoch),
        ).fetchone()
        cassette = db.execute(
            "SELECT operation,physical_label,reuse_registered "
            "FROM automatic_cassettes WHERE job_id=? AND sequence=?",
            (job_id, cassette_sequence),
        ).fetchone()
        layout_targets = db.execute(
            "SELECT operation,physical_label FROM job_layout_targets "
            "WHERE job_id=? AND epoch_number=? AND target_sequence=?",
            (job_id, layout_epoch, cassette_sequence),
        ).fetchall()
        if (
            epoch is None
            or cassette is None
            or len(layout_targets) != 1
            or epoch["layout_fingerprint_sha256"] != fingerprint
            or layout_targets[0]["operation"] != cassette["operation"]
            or layout_targets[0]["physical_label"] != cassette["physical_label"]
            or cassette["operation"] not in {"append", "format"}
        ):
            raise self._sequence_continuation_conflict()

        links = db.execute(
            "SELECT * FROM operation_format_authorizations WHERE operation_id=?",
            (operation_id,),
        ).fetchall()
        confirmations = db.execute(
            "SELECT * FROM format_confirmations WHERE operation_id=?",
            (operation_id,),
        ).fetchall()
        authority_id: str | None = None
        if cassette["operation"] == "format":
            if len(links) != 1 or len(confirmations) != 1:
                raise self._sequence_continuation_conflict()
            authority = db.execute(
                "SELECT * FROM automatic_format_authorizations "
                "WHERE authorization_id=?",
                (links[0]["authorization_id"],),
            ).fetchone()
            confirmation = confirmations[0]
            if authority is None:
                raise self._sequence_continuation_conflict()
            authority_id = str(authority["authorization_id"])
            if (
                _SHA256.fullmatch(authority_id) is None
                or supplied_authority_id != authority_id
                or links[0]["authorization_id"] != authority_id
                or self._parse_utc_timestamp(links[0]["linked_at"]) is None
                or authority["job_id"] != job_id
                or authority["cassette_sequence"] != cassette_sequence
                or authority["layout_epoch"] != layout_epoch
                or authority["layout_fingerprint_sha256"] != fingerprint
                or authority["expected_operation"] != "format"
                or authority["expected_label"] != cassette["physical_label"]
                or authority["reuse_registered"] != cassette["reuse_registered"]
                or confirmation["job_id"] != job_id
                or confirmation["cassette_sequence"] != cassette_sequence
                or confirmation["expected_label"] != authority["expected_label"]
                or confirmation["confirmed_by"] != authority["authorized_by"]
                or self._parse_utc_timestamp(confirmation["confirmed_at"]) is None
            ):
                raise self._sequence_continuation_conflict()
        elif (
            supplied_authority_id is not None
            or links
            or confirmations
        ):
            raise self._sequence_continuation_conflict()

        return _SequenceContinuationProvenance(
            operation_id=operation_id,
            job_id=job_id,
            cassette_sequence=cassette_sequence,
            layout_epoch=layout_epoch,
            layout_fingerprint_sha256=fingerprint,
            authority_id=authority_id,
            continuation_idempotency_key=continuation_key,
        )

    @staticmethod
    def _encode_sequence_continuation_audit(
        provenance: _SequenceContinuationProvenance,
        outcome: Literal["admitted", "replayed"],
    ) -> str:
        return json.dumps(
            {
                "authority_id": provenance.authority_id,
                "continuation_idempotency_key": (
                    provenance.continuation_idempotency_key
                ),
                "job_id": provenance.job_id,
                "layout_epoch": provenance.layout_epoch,
                "layout_fingerprint_sha256": (
                    provenance.layout_fingerprint_sha256
                ),
                "operation_id": provenance.operation_id,
                "outcome": outcome,
                "sequence": provenance.cassette_sequence,
            },
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )

    def _record_sequence_continuation_audit_tx(
        self,
        db: sqlite3.Connection,
        provenance: _SequenceContinuationProvenance,
        outcome: Literal["admitted", "replayed"],
    ) -> None:
        self._record_audit_tx(
            db,
            "sequence-coordinator",
            f"automatic.sequence.continuation.{outcome}",
            "accepted",
            f"sequence-{outcome}-{uuid.uuid4().hex}",
            None,
            self._encode_sequence_continuation_audit(provenance, outcome),
        )

    def _consume_sequence_format_authorization_tx(
        self,
        db: sqlite3.Connection,
        candidate: OperationRecord,
        authorization_id: str,
        now: str,
    ) -> None:
        """Derive one operation confirmation from an exact current authority."""
        self._validate_sha256(authorization_id, "sequence format authorization")
        authority = db.execute(
            "SELECT authority.*,state.layout_epoch AS current_layout_epoch,"
            "state.layout_fingerprint_sha256 AS current_layout_fingerprint,"
            "epoch.layout_fingerprint_sha256 AS epoch_layout_fingerprint,"
            "latest_epoch.epoch_number AS latest_layout_epoch,"
            "latest_epoch.layout_fingerprint_sha256 AS latest_layout_fingerprint "
            "FROM automatic_format_authorizations AS authority "
            "JOIN automatic_sequence_state AS state "
            "ON state.job_id=authority.job_id "
            "JOIN job_layout_epochs AS epoch "
            "ON epoch.job_id=state.job_id AND epoch.epoch_number=state.layout_epoch "
            "JOIN job_layout_epochs AS latest_epoch "
            "ON latest_epoch.job_id=state.job_id "
            "AND latest_epoch.epoch_number=(SELECT MAX(epoch_number) "
            "FROM job_layout_epochs WHERE job_id=state.job_id) "
            "WHERE authority.authorization_id=?",
            (authorization_id,),
        ).fetchone()
        cassette = (
            None
            if candidate.job_id is None or candidate.cassette_sequence is None
            else db.execute(
                "SELECT * FROM automatic_cassettes WHERE job_id=? AND sequence=?",
                (candidate.job_id, candidate.cassette_sequence),
            ).fetchone()
        )
        if (
            candidate.kind != "archive.native"
            or authority is None
            or cassette is None
            or authority["job_id"] != candidate.job_id
            or authority["cassette_sequence"] != candidate.cassette_sequence
            or authority["layout_epoch"] != authority["current_layout_epoch"]
            or authority["layout_fingerprint_sha256"]
            != authority["current_layout_fingerprint"]
            or authority["layout_fingerprint_sha256"]
            != authority["epoch_layout_fingerprint"]
            or authority["layout_epoch"] != authority["latest_layout_epoch"]
            or authority["layout_fingerprint_sha256"]
            != authority["latest_layout_fingerprint"]
            or cassette["operation"] != "format"
            or authority["expected_operation"] != "format"
            or cassette["physical_label"] != authority["expected_label"]
            or re.fullmatch(r"[A-Z0-9]{6}", str(cassette["physical_label"])) is None
            or cassette["reuse_registered"] != authority["reuse_registered"]
        ):
            raise ValidationError("sequence format authorization is not operation-bound")
        db.execute(
            "INSERT INTO format_confirmations("
            "operation_id,job_id,cassette_sequence,expected_label,"
            "confirmed_by,confirmed_at) VALUES(?,?,?,?,?,?)",
            (
                candidate.id,
                candidate.job_id,
                candidate.cassette_sequence,
                authority["expected_label"],
                authority["authorized_by"],
                now,
            ),
        )
        db.execute(
            "INSERT INTO operation_format_authorizations("
            "operation_id,authorization_id,linked_at) VALUES(?,?,?)",
            (candidate.id, authorization_id, now),
        )

    @staticmethod
    def _physical_mismatch_dimension(
        target_row: sqlite3.Row | None,
        binding_row: sqlite3.Row | None,
        evidence: VerifiedPhysicalQuiescence,
    ) -> str | None:
        if target_row is None:
            if evidence.target is not None:
                return "mount_path_sha256"
            if evidence.observed_media_identity_sha256 is not None:
                return "observed_media_identity_sha256"
            return None
        if evidence.target is None:
            return "mount_path_sha256"
        for dimension in (
            "mount_path_sha256",
            "tape_device_identity_sha256",
            "scsi_device_identity_sha256",
            "expected_media_scope_sha256",
        ):
            if target_row[dimension] != getattr(evidence.target, dimension):
                return dimension
        expected_media = (
            None
            if binding_row is None
            else binding_row["observed_media_identity_sha256"]
        )
        if expected_media != evidence.observed_media_identity_sha256:
            return "observed_media_identity_sha256"
        return None

    def _validate_recovery_targets(
        self,
        target: sqlite3.Row | None,
        binding: sqlite3.Row | None,
        commands: list[sqlite3.Row],
        physical: sqlite3.Row,
    ) -> None:
        dimensions = (
            "mount_path_sha256",
            "tape_device_identity_sha256",
            "scsi_device_identity_sha256",
            "expected_media_scope_sha256",
        )
        if target is None:
            if commands:
                raise PhysicalTargetMismatch("mount_path_sha256")
            for dimension in dimensions:
                if physical[dimension] is not None:
                    raise PhysicalTargetMismatch(dimension)
        else:
            for dimension in dimensions:
                expected = target[dimension]
                if physical[dimension] != expected:
                    raise PhysicalTargetMismatch(dimension)
                if any(command[dimension] != expected for command in commands):
                    raise PhysicalTargetMismatch(dimension)
        expected_media = (
            None if binding is None else binding["observed_media_identity_sha256"]
        )
        if physical["observed_media_identity_sha256"] != expected_media:
            raise PhysicalTargetMismatch("observed_media_identity_sha256")
        ordered_commands = sorted(
            commands, key=lambda row: (row["created_at"], row["id"])
        )
        format_rebind = (
            None
            if binding is None
            else self.connection.execute(
                "SELECT * FROM format_media_rebindings WHERE operation_id=?",
                (binding["operation_id"],),
            ).fetchone()
        )
        pre_index = (
            None
            if format_rebind is None
            else next(
                (
                    index
                    for index, command in enumerate(ordered_commands)
                    if command["id"] == format_rebind["pre_probe_media_command_id"]
                ),
                None,
            )
        )
        post_index = (
            None
            if format_rebind is None
            else next(
                (
                    index
                    for index, command in enumerate(ordered_commands)
                    if command["id"] == format_rebind["post_probe_media_command_id"]
                ),
                None,
            )
        )
        if format_rebind is not None and (pre_index is None or post_index is None):
            raise PhysicalTargetMismatch("observed_media_identity_sha256")
        for index, command in enumerate(ordered_commands):
            observed = command["observed_media_identity_sha256"]
            if format_rebind is not None:
                expected_observed = (
                    None
                    if index <= pre_index
                    else format_rebind["pre_media_identity_sha256"]
                    if index <= post_index
                    else expected_media
                )
                if observed != expected_observed:
                    raise PhysicalTargetMismatch("observed_media_identity_sha256")
                continue
            if expected_media is None:
                if observed is not None:
                    raise PhysicalTargetMismatch("observed_media_identity_sha256")
            elif observed is None:
                if command["created_at"] >= binding["bound_at"]:
                    raise PhysicalTargetMismatch("observed_media_identity_sha256")
            elif observed != expected_media:
                raise PhysicalTargetMismatch("observed_media_identity_sha256")

    @staticmethod
    def _command_receipt_from_rows(
        receipt_id: str,
        operation_id: str,
        generation: int,
        recorded_at: str,
        commands: list[sqlite3.Row],
    ) -> CommandQuiescenceReceipt:
        evidence = tuple(
            CommandExitEvidence(
                row["id"],
                Catalog._process_from_command_row(row),
                row["exit_outcome"],
                row["quiesced_at"],
                row["terminal_exit_code"],
            )
            for row in commands
        )
        return CommandQuiescenceReceipt(
            id=receipt_id,
            operation_id=operation_id,
            reconciled_by_generation=generation,
            command_ids=tuple(row["id"] for row in commands),
            evidence=evidence,
            recorded_at=recorded_at,
        )

    @staticmethod
    def _new_id(prefix: str) -> str:
        return f"{prefix}-{uuid.uuid4().hex}"

    @staticmethod
    def _precise_utc_now(*, after: str | None = None) -> str:
        value = datetime.now(UTC)
        if after is not None:
            try:
                earlier = datetime.fromisoformat(after)
            except ValueError:
                earlier = value
            if value <= earlier:
                value = earlier + timedelta(microseconds=1)
        return value.isoformat(timespec="microseconds")

    def event(self, action: str, payload: dict[str, Any]) -> None:
        with self.transaction() as db:
            self._event(db, action, payload)

    def export(self, *, include_events: bool = True) -> dict[str, Any]:
        tables = [
            "libraries",
            "tapes",
            "blocks",
            "file_versions",
            "automatic_jobs",
            "automatic_job_libraries",
            "automatic_cassettes",
        ]
        if include_events:
            tables.append("events")
        result: dict[str, Any] = {
            "schema_version": SCHEMA_VERSION,
            "exported_at": utc_now(),
        }
        for table in tables:
            result[table] = [
                dict(row) for row in self.connection.execute(f"SELECT * FROM {table}")
            ]
        return result

    @staticmethod
    def _event(db: sqlite3.Connection, action: str, payload: dict[str, Any]) -> None:
        db.execute(
            "INSERT INTO events(occurred_at, action, payload_json) VALUES(?, ?, ?)",
            (
                utc_now(),
                action,
                json.dumps(payload, ensure_ascii=False, sort_keys=True),
            ),
        )
